// ============================================================================
// NAZA ALL-ZIG MONOLITH
// Target: Zig 0.15.x. Core logic stays pure Zig; the optional Debian GUI uses X11 only as the OS surface boundary.
// ============================================================================

const ModelSpec = @import("model_spec.zig");

pub const VERSION = "0.9.0-native-gui";

// ----------------------------------------------------------------------------
// Pinned model
// ----------------------------------------------------------------------------

pub const PinnedModel = struct {
    pub const repo = ModelSpec.repo;
    pub const file = ModelSpec.file;
    pub const sha256_hex = ModelSpec.sha256_hex;
    pub const max_download_bytes: u64 = 512 * 1024 * 1024;
    pub const max_redirects: usize = 5;
    pub const max_destination_bytes: usize = 4096;
};

fn openRegularModel(path: []const u8) !std.fs.File {
    const fd = try std.posix.openat(std.fs.cwd().fd, path, .{
        .ACCMODE = .RDONLY,
        .NOFOLLOW = true,
        .NONBLOCK = true,
        .CLOEXEC = true,
    }, 0);
    const file = std.fs.File{ .handle = fd };
    errdefer file.close();
    const stat = try file.stat();
    if (stat.kind != .file) return error.ModelNotRegularFile;
    if (stat.size == 0 or stat.size > PinnedModel.max_download_bytes) return error.ModelTooLarge;
    return file;
}

pub fn verifyPinnedModelBytes(bytes: []const u8) !void {
    if (bytes.len == 0 or bytes.len > PinnedModel.max_download_bytes) return error.ModelTooLarge;
    var actual: [32]u8 = undefined;
    var expected: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(bytes, &actual, .{});
    _ = try std.fmt.hexToBytes(&expected, PinnedModel.sha256_hex);
    if (!ctEqual(&actual, &expected)) return error.ModelHashMismatch;
}

pub fn verifyPinnedModel(path: []const u8) !void {
    if (path.len == 0 or path.len > PinnedModel.max_destination_bytes) return error.InvalidArguments;

    const cwd = std.fs.cwd();
    const path_stat = try cwd.statFile(path);
    if (path_stat.kind != .file) return error.ModelNotRegularFile;
    if (path_stat.size > PinnedModel.max_download_bytes) return error.ModelTooLarge;

    var file = try openRegularModel(path);
    defer file.close();
    const stat = try file.stat();
    if (stat.kind != .file) return error.ModelNotRegularFile;
    if (stat.size > PinnedModel.max_download_bytes) return error.ModelTooLarge;

    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    var buf: [128 * 1024]u8 = undefined;
    var total: u64 = 0;
    while (true) {
        const n = try file.read(&buf);
        if (n == 0) break;
        if (n > PinnedModel.max_download_bytes -| total) return error.ModelTooLarge;
        hasher.update(buf[0..n]);
        total += n;
    }
    var digest: [32]u8 = undefined;
    hasher.final(&digest);
    var expected: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&expected, PinnedModel.sha256_hex);
    if (!ctEqual(digest[0..], expected[0..])) return error.ModelHashMismatch;
}

fn isAllowedModelHost(host: []const u8) bool {
    return std.ascii.eqlIgnoreCase(host, "huggingface.co") or
        std.ascii.endsWithIgnoreCase(host, ".huggingface.co") or
        std.ascii.eqlIgnoreCase(host, "hf.co") or
        std.ascii.endsWithIgnoreCase(host, ".hf.co");
}

fn isAllowedModelUri(uri: std.Uri) bool {
    if (!std.ascii.eqlIgnoreCase(uri.scheme, "https")) return false;
    if (uri.user != null or uri.password != null or uri.fragment != null) return false;
    if (uri.port) |port| if (port != 443) return false;
    var host_buf: [std.Uri.host_name_max]u8 = undefined;
    const host = uri.getHost(&host_buf) catch return false;
    return isAllowedModelHost(host);
}

fn resolveModelRedirect(allocator: std.mem.Allocator, base: std.Uri, location: []const u8) ![]u8 {
    if (location.len == 0 or location.len > 8192) return error.RedirectMissingLocation;
    var buffer: [16384]u8 = undefined;
    @memcpy(buffer[0..location.len], location);
    var available: []u8 = &buffer;
    const resolved = try std.Uri.resolveInPlace(base, location.len, &available);
    if (!isAllowedModelUri(resolved)) return error.UntrustedDownloadHost;
    return std.fmt.allocPrint(allocator, "{f}", .{resolved});
}

/// Download the pinned GGUF over HTTPS and publish it only after the complete
/// stream matches the pinned SHA-256. The destination is never overwritten.
/// Redirects are handled manually so every hop can be checked before use.
pub fn downloadPinnedModel(allocator: std.mem.Allocator, destination: []const u8) !u64 {
    return downloadPinnedModelInternal(allocator, destination, false);
}

fn downloadPinnedModelInternal(allocator: std.mem.Allocator, destination: []const u8, show_progress: bool) !u64 {
    if (destination.len == 0 or destination.len > PinnedModel.max_destination_bytes) return error.InvalidArguments;

    const cwd = std.fs.cwd();
    if (cwd.statFile(destination)) |stat| {
        if (stat.kind != .file) return error.ModelDestinationExists;
        if (verifyPinnedModel(destination)) |_| return error.ModelAlreadyVerified else |_| return error.ModelDestinationExists;
    } else |err| switch (err) {
        error.FileNotFound => {},
        else => return err,
    }

    const nonce = std.crypto.random.int(u64);
    const part_path = try std.fmt.allocPrint(allocator, "{s}.part-{x}", .{ destination, nonce });
    defer allocator.free(part_path);

    var part_created = false;
    var destination_created = false;
    errdefer {
        if (part_created) cwd.deleteFile(part_path) catch {};
        if (destination_created) cwd.deleteFile(destination) catch {};
    }

    var staged = try cwd.createFile(part_path, .{
        .read = false,
        .truncate = false,
        .exclusive = true,
        .mode = 0o600,
    });
    part_created = true;
    var staged_open = true;
    defer if (staged_open) staged.close();

    var expected: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&expected, PinnedModel.sha256_hex);
    var hasher = std.crypto.hash.sha2.Sha256.init(.{});
    var total: u64 = 0;
    var last_percent: u64 = 101;
    var next_unknown_report: u64 = 8 * 1024 * 1024;
    var progress_started = false;
    defer if (progress_started) std.debug.print("\n", .{});

    var client: std.http.Client = .{ .allocator = allocator };
    defer client.deinit();

    const initial_url = PinnedModel.repo ++ PinnedModel.file;
    var current_url = try allocator.dupe(u8, initial_url);
    defer allocator.free(current_url);
    var current_uri = try std.Uri.parse(current_url);
    var redirects: usize = 0;

    while (true) {
        if (!isAllowedModelUri(current_uri)) return error.UntrustedDownloadHost;

        var request = try client.request(.GET, current_uri, .{
            .redirect_behavior = .unhandled,
            .keep_alive = false,
            .headers = .{
                .accept_encoding = .{ .override = "identity" },
                .user_agent = .{ .override = "NAZA-pure-Zig/" ++ VERSION },
            },
        });
        defer request.deinit();

        try request.sendBodiless();
        var redirect_buffer: [8192]u8 = undefined;
        var response = try request.receiveHead(&redirect_buffer);

        if (response.head.status.class() == .redirect) {
            if (redirects >= PinnedModel.max_redirects) return error.TooManyRedirects;
            const location = response.head.location orelse return error.RedirectMissingLocation;
            const next_url = try resolveModelRedirect(allocator, current_uri, location);
            const next_uri = std.Uri.parse(next_url) catch |err| {
                allocator.free(next_url);
                return err;
            };
            allocator.free(current_url);
            current_url = next_url;
            current_uri = next_uri;
            redirects += 1;
            continue;
        }

        if (response.head.status != .ok) return error.HttpStatusNotOk;
        if (response.head.content_encoding != .identity) return error.UnsupportedContentEncoding;
        if (response.head.content_length) |length| {
            if (length > PinnedModel.max_download_bytes) return error.ModelTooLarge;
        }

        const body = response.reader(&.{});
        var transfer_buffer: [128 * 1024]u8 = undefined;
        while (true) {
            // Zig's HTTP reader transitions back to `.ready` immediately after
            // the declared body length is consumed; asking it for one more read
            // is invalid. Stop at that boundary instead of probing for EOF.
            if (response.head.content_length) |length| {
                if (total == length) break;
                if (total > length) return error.DownloadTooLong;
            }
            const n = body.readSliceShort(&transfer_buffer) catch |err| switch (err) {
                error.ReadFailed => return error.DownloadReadFailed,
            };
            if (n == 0) break;
            if (n > PinnedModel.max_download_bytes -| total) return error.ModelTooLarge;
            if (response.head.content_length) |length| {
                if (n > length - total) return error.DownloadTooLong;
            }
            try staged.writeAll(transfer_buffer[0..n]);
            hasher.update(transfer_buffer[0..n]);
            total += n;
            if (show_progress) {
                progress_started = true;
                if (response.head.content_length) |length| {
                    const percent = if (length == 0) 100 else (total * 100) / length;
                    if (percent != last_percent) {
                        std.debug.print("\rDownloading: {d}% ({d}/{d} MiB)", .{ percent, total / (1024 * 1024), length / (1024 * 1024) });
                        last_percent = percent;
                    }
                } else if (total >= next_unknown_report) {
                    std.debug.print("\rDownloading: {d} MiB", .{total / (1024 * 1024)});
                    next_unknown_report = total + 8 * 1024 * 1024;
                }
            }
        }
        if (response.head.content_length) |length| if (total != length) return error.DownloadTruncated;
        break;
    }

    var digest: [32]u8 = undefined;
    hasher.final(&digest);
    if (!ctEqual(&digest, &expected)) return error.ModelHashMismatch;

    try staged.sync();
    staged.close();
    staged_open = false;

    // A hard link gives us atomic, no-clobber publication: if another process
    // created the destination after the initial check, link() fails instead of
    // replacing it. The temporary name is removed only after publication.
    try std.posix.link(part_path, destination);
    destination_created = true;
    try cwd.deleteFile(part_path);
    part_created = false;
    try verifyPinnedModel(destination);
    destination_created = false;
    return total;
}

test "pinned model downloader rejects untrusted URI forms" {
    try std.testing.expect(isAllowedModelUri(try std.Uri.parse("https://huggingface.co/model.gguf")));
    try std.testing.expect(isAllowedModelUri(try std.Uri.parse("https://cdn-lfs.hf.co/model.gguf")));
    try std.testing.expect(!isAllowedModelUri(try std.Uri.parse("http://huggingface.co/model.gguf")));
    try std.testing.expect(!isAllowedModelUri(try std.Uri.parse("https://user@huggingface.co/model.gguf")));
    try std.testing.expect(!isAllowedModelUri(try std.Uri.parse("https://huggingface.co:444/model.gguf")));
    try std.testing.expect(!isAllowedModelUri(try std.Uri.parse("https://evil-huggingface.co/model.gguf")));
    try std.testing.expect(!isAllowedModelUri(try std.Uri.parse("https://huggingface.co.evil.example/model.gguf")));
}

test "model redirects resolve relative paths but reject hostile targets" {
    const base = try std.Uri.parse("https://huggingface.co/repo/resolve/main/model.gguf");
    const url = try resolveModelRedirect(std.testing.allocator, base, "/repo/resolve/revision/model.gguf");
    defer std.testing.allocator.free(url);
    try std.testing.expectEqualStrings("https://huggingface.co/repo/resolve/revision/model.gguf", url);
    try std.testing.expectError(error.UntrustedDownloadHost, resolveModelRedirect(std.testing.allocator, base, "//evil.example/model"));
    try std.testing.expectError(error.UntrustedDownloadHost, resolveModelRedirect(std.testing.allocator, base, "http://huggingface.co/model"));
}

test "owned inference bytes must match pinned hash" {
    try std.testing.expectError(error.ModelTooLarge, verifyPinnedModelBytes(""));
    try std.testing.expectError(error.ModelHashMismatch, verifyPinnedModelBytes("GGUF untrusted model"));
}

test "pinned model downloader validates destination before networking" {
    try std.testing.expectError(error.InvalidArguments, downloadPinnedModel(std.testing.allocator, ""));
    var too_long: [PinnedModel.max_destination_bytes + 1]u8 = undefined;
    @memset(&too_long, 'a');
    try std.testing.expectError(error.InvalidArguments, downloadPinnedModel(std.testing.allocator, &too_long));
}

// ----------------------------------------------------------------------------
// Constant-time helpers and zeroization
// ----------------------------------------------------------------------------

pub fn ctEqual(a: []const u8, b: []const u8) bool {
    if (a.len != b.len) return false;
    var x: u8 = 0;
    for (a, b) |aa, bb| x |= aa ^ bb;
    return x == 0;
}

pub fn ctSelect(mask: u8, yes: u8, no: u8) u8 {
    return (yes & mask) | (no & ~mask);
}

pub fn secureZero(bytes: []u8) void {
    const p: []volatile u8 = @ptrCast(bytes);
    @memset(p, 0);
}

// ----------------------------------------------------------------------------
// Keccak-f[1600] / SHA-3 / SHAKE -- pure Zig, no external linkage.
// ----------------------------------------------------------------------------

pub const Keccak = struct {
    const RC = [24]u64{
        0x0000000000000001, 0x0000000000008082,
        0x800000000000808a, 0x8000000080008000,
        0x000000000000808b, 0x0000000080000001,
        0x8000000080008081, 0x8000000000008009,
        0x000000000000008a, 0x0000000000000088,
        0x0000000080008009, 0x000000008000000a,
        0x000000008000808b, 0x800000000000008b,
        0x8000000000008089, 0x8000000000008003,
        0x8000000000008002, 0x8000000000000080,
        0x000000000000800a, 0x800000008000000a,
        0x8000000080008081, 0x8000000000008080,
        0x0000000080000001, 0x8000000080008008,
    };

    // Rho offsets indexed by x + 5*y.
    const ROT = [25]u6{
        0,  1,  62, 28, 27,
        36, 44, 6,  55, 20,
        3,  10, 43, 25, 39,
        41, 45, 15, 21, 8,
        18, 2,  61, 56, 14,
    };

    inline fn rol(x: u64, n: u6) u64 {
        return std.math.rotl(u64, x, n);
    }

    pub fn f1600(a: *[25]u64) void {
        var round: usize = 0;
        while (round < 24) : (round += 1) {
            var c: [5]u64 = undefined;
            var d: [5]u64 = undefined;
            var x: usize = 0;
            while (x < 5) : (x += 1) {
                c[x] = a[x] ^ a[x + 5] ^ a[x + 10] ^ a[x + 15] ^ a[x + 20];
            }
            x = 0;
            while (x < 5) : (x += 1) d[x] = c[(x + 4) % 5] ^ rol(c[(x + 1) % 5], 1);

            var y: usize = 0;
            y = 0;
            while (y < 5) : (y += 1) {
                x = 0;
                while (x < 5) : (x += 1) a[x + 5 * y] ^= d[x];
            }

            var b: [25]u64 = undefined;
            y = 0;
            while (y < 5) : (y += 1) {
                x = 0;
                while (x < 5) : (x += 1) {
                    const idx = x + 5 * y;
                    const nx = y;
                    const ny = (2 * x + 3 * y) % 5;
                    b[nx + 5 * ny] = rol(a[idx], ROT[idx]);
                }
            }

            y = 0;
            while (y < 5) : (y += 1) {
                x = 0;
                while (x < 5) : (x += 1) {
                    a[x + 5 * y] = b[x + 5 * y] ^ ((~b[((x + 1) % 5) + 5 * y]) & b[((x + 2) % 5) + 5 * y]);
                }
            }
            a[0] ^= RC[round];
        }
    }

    pub const Sponge = struct {
        state: [25]u64 = [_]u64{0} ** 25,
        rate: usize,
        suffix: u8,
        pos: usize = 0,
        finalized: bool = false,

        pub fn init(rate: usize, suffix: u8) Sponge {
            return .{ .rate = rate, .suffix = suffix };
        }

        inline fn xorByte(self: *Sponge, off: usize, v: u8) void {
            const lane = off >> 3;
            const shift: u6 = @intCast((off & 7) * 8);
            self.state[lane] ^= @as(u64, v) << shift;
        }

        inline fn getByte(self: *const Sponge, off: usize) u8 {
            const lane = off >> 3;
            const shift: u6 = @intCast((off & 7) * 8);
            return @truncate(self.state[lane] >> shift);
        }

        pub fn update(self: *Sponge, input: []const u8) !void {
            if (self.finalized) return error.AlreadyFinalized;
            for (input) |v| {
                self.xorByte(self.pos, v);
                self.pos += 1;
                if (self.pos == self.rate) {
                    f1600(&self.state);
                    self.pos = 0;
                }
            }
        }

        pub fn finalize(self: *Sponge) void {
            if (self.finalized) return;
            self.xorByte(self.pos, self.suffix);
            self.xorByte(self.rate - 1, 0x80);
            f1600(&self.state);
            self.pos = 0;
            self.finalized = true;
        }

        pub fn squeeze(self: *Sponge, out: []u8) !void {
            if (!self.finalized) self.finalize();
            for (out) |*v| {
                if (self.pos == self.rate) {
                    f1600(&self.state);
                    self.pos = 0;
                }
                v.* = self.getByte(self.pos);
                self.pos += 1;
            }
        }
    };
};

pub fn sha3_256(input: []const u8) [32]u8 {
    var s = Keccak.Sponge.init(136, 0x06);
    s.update(input) catch unreachable;
    s.finalize();
    var out: [32]u8 = undefined;
    s.squeeze(&out) catch unreachable;
    return out;
}

pub fn sha3_512(input: []const u8) [64]u8 {
    var s = Keccak.Sponge.init(72, 0x06);
    s.update(input) catch unreachable;
    s.finalize();
    var out: [64]u8 = undefined;
    s.squeeze(&out) catch unreachable;
    return out;
}

pub fn shake128(input: []const u8, out: []u8) void {
    var s = Keccak.Sponge.init(168, 0x1f);
    s.update(input) catch unreachable;
    s.finalize();
    s.squeeze(out) catch unreachable;
}

pub fn shake256(input: []const u8, out: []u8) void {
    var s = Keccak.Sponge.init(136, 0x1f);
    s.update(input) catch unreachable;
    s.finalize();
    s.squeeze(out) catch unreachable;
}

// ----------------------------------------------------------------------------
// SHA-2 / HMAC / HKDF convenience. Zig stdlib is Zig, not C linkage.
// ----------------------------------------------------------------------------

pub fn sha256(input: []const u8) [32]u8 {
    var h = std.crypto.hash.sha2.Sha256.init(.{});
    h.update(input);
    var out: [32]u8 = undefined;
    h.final(&out);
    return out;
}

pub fn sha512(input: []const u8) [64]u8 {
    var h = std.crypto.hash.sha2.Sha512.init(.{});
    h.update(input);
    var out: [64]u8 = undefined;
    h.final(&out);
    return out;
}

pub fn hmacSha256(key: []const u8, msg: []const u8) [32]u8 {
    var k0 = [_]u8{0} ** 64;
    if (key.len > 64) {
        const kh = sha256(key);
        @memcpy(k0[0..32], &kh);
    } else {
        @memcpy(k0[0..key.len], key);
    }
    var ipad = [_]u8{0x36} ** 64;
    var opad = [_]u8{0x5c} ** 64;
    for (0..64) |i| {
        ipad[i] ^= k0[i];
        opad[i] ^= k0[i];
    }
    var inner = std.crypto.hash.sha2.Sha256.init(.{});
    inner.update(&ipad);
    inner.update(msg);
    var ih: [32]u8 = undefined;
    inner.final(&ih);
    var outer = std.crypto.hash.sha2.Sha256.init(.{});
    outer.update(&opad);
    outer.update(&ih);
    var out: [32]u8 = undefined;
    outer.final(&out);
    secureZero(k0[0..]);
    secureZero(ipad[0..]);
    secureZero(opad[0..]);
    secureZero(ih[0..]);
    return out;
}

pub fn hkdfExtractSha256(salt: []const u8, ikm: []const u8) [32]u8 {
    if (salt.len == 0) {
        const zero = [_]u8{0} ** 32;
        return hmacSha256(&zero, ikm);
    }
    return hmacSha256(salt, ikm);
}

pub fn hkdfExpandSha256(prk: []const u8, info: []const u8, out: []u8) !void {
    if (out.len > 255 * 32) return error.OutputTooLong;
    var t: [32]u8 = undefined;
    var t_len: usize = 0;
    var pos: usize = 0;
    var counter: u8 = 1;
    while (pos < out.len) {
        var h = std.crypto.auth.hmac.sha2.HmacSha256.init(prk);
        if (t_len != 0) h.update(t[0..t_len]);
        h.update(info);
        const c = [_]u8{counter};
        h.update(&c);
        h.final(&t);
        t_len = 32;
        const n = @min(out.len - pos, 32);
        @memcpy(out[pos .. pos + n], t[0..n]);
        pos += n;
        counter +%= 1;
    }
    secureZero(t[0..]);
}

test "HMAC-SHA256 RFC 4231 case 1" {
    const key = [_]u8{0x0b} ** 20;
    const got = hmacSha256(&key, "Hi There");
    var expected: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&expected, "b0344c61d8db38535ca8afceaf0bf12b881dc200c9833da726e9376c2e32cff7");
    try std.testing.expectEqualSlices(u8, &expected, &got);
}

test "HKDF-SHA256 RFC 5869 case 1 and maximum output" {
    const ikm = [_]u8{0x0b} ** 22;
    const salt = [_]u8{ 0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0a, 0x0b, 0x0c };
    const info = [_]u8{ 0xf0, 0xf1, 0xf2, 0xf3, 0xf4, 0xf5, 0xf6, 0xf7, 0xf8, 0xf9 };
    const prk = hkdfExtractSha256(&salt, &ikm);
    var expected_prk: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&expected_prk, "077709362c2e32df0ddc3f0dc47bba6390b6c73bb50f9c3122ec844ad7c2b3e5");
    try std.testing.expectEqualSlices(u8, &expected_prk, &prk);

    var okm: [42]u8 = undefined;
    try hkdfExpandSha256(&prk, &info, &okm);
    var expected_okm: [42]u8 = undefined;
    _ = try std.fmt.hexToBytes(&expected_okm, "3cb25f25faacd57a90434f64d0362f2a2d2d0a90cf1a5a4c5db02d56ecc4c5bf34007208d5b887185865");
    try std.testing.expectEqualSlices(u8, &expected_okm, &okm);

    var maximum: [255 * 32]u8 = undefined;
    try hkdfExpandSha256(&prk, &info, &maximum);
    var too_long: [255 * 32 + 1]u8 = undefined;
    try std.testing.expectError(error.OutputTooLong, hkdfExpandSha256(&prk, &info, &too_long));
}

// ----------------------------------------------------------------------------
// GGUF v2/v3 reader with bounded metadata + tensor table support.
// ----------------------------------------------------------------------------

fn readExact(reader: anytype, dst: []u8) !void {
    const ReaderType = @TypeOf(reader);
    const ReaderContainer = switch (@typeInfo(ReaderType)) {
        .pointer => |info| info.child,
        else => ReaderType,
    };
    if (@hasDecl(ReaderContainer, "readSliceAll")) {
        try reader.readSliceAll(dst);
    } else {
        try reader.readNoEof(dst);
    }
}

pub const Gguf = struct {
    pub const Error = error{
        InvalidMagic,
        UnsupportedVersion,
        InvalidStringLength,
        UnsupportedMetadataType,
        MetadataTooLarge,
        TensorTableTooLarge,
        InvalidArrayType,
        InvalidTensorDimensions,
    };

    pub const ValueType = enum(u32) {
        uint8 = 0,
        int8 = 1,
        uint16 = 2,
        int16 = 3,
        uint32 = 4,
        int32 = 5,
        float32 = 6,
        bool = 7,
        string = 8,
        array = 9,
        uint64 = 10,
        int64 = 11,
        float64 = 12,
    };

    pub const Header = struct { version: u32, tensor_count: u64, metadata_count: u64 };
    pub const Limits = struct {
        max_metadata_entries: u64 = 1_000_000,
        max_tensors: u64 = 1_000_000,
        max_string_bytes: u64 = 16 * 1024 * 1024,
        max_array_items: u64 = 16 * 1024 * 1024,
        max_dims: u32 = 8,
    };

    pub const TensorInfo = struct {
        name_len: u64,
        n_dims: u32,
        dimensions: [8]u64,
        ggml_type: u32,
        offset: u64,
    };

    fn readIntLe(reader: anytype, comptime T: type) !T {
        var buf: [@sizeOf(T)]u8 = undefined;
        try readExact(reader, &buf);
        return std.mem.readInt(T, &buf, .little);
    }

    fn skipBytes(reader: anytype, count: u64) !void {
        var left = count;
        var buf: [4096]u8 = undefined;
        while (left != 0) {
            const chunk: usize = @intCast(@min(left, buf.len));
            try readExact(reader, buf[0..chunk]);
            left -= chunk;
        }
    }

    fn skipString(reader: anytype, limits: Limits) !u64 {
        const len = try readIntLe(reader, u64);
        if (len > limits.max_string_bytes) return Error.InvalidStringLength;
        try skipBytes(reader, len);
        return len;
    }

    fn scalarSize(t: ValueType) ?u64 {
        return switch (t) {
            .uint8, .int8, .bool => 1,
            .uint16, .int16 => 2,
            .uint32, .int32, .float32 => 4,
            .uint64, .int64, .float64 => 8,
            .string, .array => null,
        };
    }

    fn readValueType(reader: anytype) !ValueType {
        const raw = try readIntLe(reader, u32);
        return std.meta.intToEnum(ValueType, raw) catch Error.UnsupportedMetadataType;
    }

    fn skipValue(reader: anytype, t: ValueType, limits: Limits, depth: u8) !void {
        if (depth > 8) return Error.InvalidArrayType;
        if (scalarSize(t)) |n| {
            try skipBytes(reader, n);
            return;
        }
        switch (t) {
            .string => _ = try skipString(reader, limits),
            .array => {
                const item_type = try readValueType(reader);
                const len = try readIntLe(reader, u64);
                if (len > limits.max_array_items) return Error.MetadataTooLarge;
                if (scalarSize(item_type)) |n| {
                    if (n != 0 and len > std.math.maxInt(u64) / n) return Error.MetadataTooLarge;
                    try skipBytes(reader, len * n);
                } else {
                    var i: u64 = 0;
                    while (i < len) : (i += 1) try skipValue(reader, item_type, limits, depth + 1);
                }
            },
            else => unreachable,
        }
    }

    pub fn readHeader(reader: anytype, limits: Limits) !Header {
        var magic: [4]u8 = undefined;
        try readExact(reader, &magic);
        if (!std.mem.eql(u8, &magic, "GGUF")) return Error.InvalidMagic;
        const version = try readIntLe(reader, u32);
        if (version < 2 or version > 3) return Error.UnsupportedVersion;
        const tensors = try readIntLe(reader, u64);
        const metadata = try readIntLe(reader, u64);
        if (tensors > limits.max_tensors) return Error.TensorTableTooLarge;
        if (metadata > limits.max_metadata_entries) return Error.MetadataTooLarge;
        return .{ .version = version, .tensor_count = tensors, .metadata_count = metadata };
    }

    pub fn skipMetadata(reader: anytype, h: Header, limits: Limits) !void {
        var i: u64 = 0;
        while (i < h.metadata_count) : (i += 1) {
            _ = try skipString(reader, limits);
            try skipValue(reader, try readValueType(reader), limits, 0);
        }
    }

    pub fn readTensorInfo(reader: anytype, limits: Limits) !TensorInfo {
        const name_len = try readIntLe(reader, u64);
        if (name_len > limits.max_string_bytes) return Error.InvalidStringLength;
        try skipBytes(reader, name_len);
        const n_dims = try readIntLe(reader, u32);
        if (n_dims == 0 or n_dims > limits.max_dims) return Error.InvalidTensorDimensions;
        var dims = [_]u64{0} ** 8;
        var i: usize = 0;
        while (i < n_dims) : (i += 1) dims[i] = try readIntLe(reader, u64);
        return .{
            .name_len = name_len,
            .n_dims = n_dims,
            .dimensions = dims,
            .ggml_type = try readIntLe(reader, u32),
            .offset = try readIntLe(reader, u64),
        };
    }
};

// ----------------------------------------------------------------------------
// Small tensor/matrix runtime for pure-Zig transformer work.
// This is intentionally scalar and portable; SIMD kernels can replace it later.
// ----------------------------------------------------------------------------

pub const Tensor = struct {
    data: []f32,
    rows: usize,
    cols: usize,

    pub fn at(self: Tensor, r: usize, c: usize) f32 {
        return self.data[r * self.cols + c];
    }
    pub fn set(self: Tensor, r: usize, c: usize, v: f32) void {
        self.data[r * self.cols + c] = v;
    }
};

pub fn matmul(out: Tensor, a: Tensor, b: Tensor) !void {
    if (a.cols != b.rows or out.rows != a.rows or out.cols != b.cols) return error.ShapeMismatch;
    var i: usize = 0;
    while (i < out.rows) : (i += 1) {
        var j: usize = 0;
        while (j < out.cols) : (j += 1) {
            var acc: f32 = 0;
            var k: usize = 0;
            while (k < a.cols) : (k += 1) acc += a.at(i, k) * b.at(k, j);
            out.set(i, j, acc);
        }
    }
}

pub fn rmsNorm(out: []f32, x: []const f32, weight: []const f32, eps: f32) !void {
    if (out.len != x.len or x.len != weight.len) return error.ShapeMismatch;
    var sum: f32 = 0;
    for (x) |v| sum += v * v;
    const inv = 1.0 / @sqrt(sum / @as(f32, @floatFromInt(x.len)) + eps);
    for (out, x, weight) |*o, v, w| o.* = v * inv * w;
}

pub fn silu(x: f32) f32 {
    return x / (1.0 + @exp(-x));
}

pub fn softmaxInPlace(x: []f32) void {
    if (x.len == 0) return;
    var m = x[0];
    for (x[1..]) |v| if (v > m) {
        m = v;
    };
    var sum: f32 = 0;
    for (x) |*v| {
        v.* = @exp(v.* - m);
        sum += v.*;
    }
    if (sum == 0) return;
    for (x) |*v| v.* /= sum;
}

// Q3_K block dequantization hook. The exact GGML Q3_K packed layout is retained as
// a dedicated boundary so it can be swapped with an optimized implementation.
pub const Q3K = struct {
    pub const block_q = 256;
    pub const block_bytes = 110;

    pub fn validateLength(src_len: usize, values: usize) bool {
        if (values % block_q != 0) return false;
        return src_len == (values / block_q) * block_bytes;
    }
};

// ----------------------------------------------------------------------------
// ML-KEM arithmetic implementation core (FIPS 203 family): q=3329, n=256.
// Polynomial arithmetic, sampling, IND-CPA, and KEM operations are implemented below;
// standards-validation status remains separate until official FIPS 203 vectors execute.
// ----------------------------------------------------------------------------

pub const MlKem = struct {
    pub const q: i32 = 3329;
    pub const n: usize = 256;

    pub const Poly = [n]i16;

    pub inline fn freeze(x: i32) i16 {
        var r = @mod(x, q);
        if (r < 0) r += q;
        return @intCast(r);
    }

    pub fn add(a: Poly, b: Poly) Poly {
        var r: Poly = undefined;
        for (0..n) |i| r[i] = freeze(@as(i32, a[i]) + @as(i32, b[i]));
        return r;
    }

    pub fn sub(a: Poly, b: Poly) Poly {
        var r: Poly = undefined;
        for (0..n) |i| r[i] = freeze(@as(i32, a[i]) - @as(i32, b[i]));
        return r;
    }

    // Schoolbook multiplication in Z_q[X]/(X^256 + 1). Slow but simple,
    // deterministic, and useful as a portable correctness oracle for the NTT kernels.
    pub fn mulNegacyclic(a: Poly, b: Poly) Poly {
        var tmp = [_]i64{0} ** (2 * n);
        for (0..n) |i| {
            for (0..n) |j| tmp[i + j] += @as(i64, a[i]) * @as(i64, b[j]);
        }
        var r: Poly = [_]i16{0} ** n;
        for (0..n) |i| {
            var v = tmp[i];
            if (i + n < 2 * n) v -= tmp[i + n];
            r[i] = freeze(@intCast(@mod(v, @as(i64, q))));
        }
        return r;
    }

    fn load24(src: []const u8) u32 {
        return @as(u32, src[0]) | (@as(u32, src[1]) << 8) | (@as(u32, src[2]) << 16);
    }

    // Kyber/ML-KEM rejection sampling of 12-bit candidates < q.
    pub fn rejUniform(out: *Poly, seed: []const u8) void {
        var stream: [4096]u8 = undefined;
        shake128(seed, &stream);
        var ctr: usize = 0;
        var pos: usize = 0;
        while (ctr < n and pos + 3 <= stream.len) : (pos += 3) {
            const val = load24(stream[pos .. pos + 3]);
            const d1: u16 = @truncate(val & 0x0fff);
            const d2: u16 = @truncate((val >> 12) & 0x0fff);
            if (d1 < q) {
                out[ctr] = @intCast(d1);
                ctr += 1;
            }
            if (ctr < n and d2 < q) {
                out[ctr] = @intCast(d2);
                ctr += 1;
            }
        }
        if (ctr != n) @panic("rejection stream unexpectedly exhausted");
    }

    // CBD eta=2 portable sampler from 128 random bytes. Each byte encodes
    // two coefficients: four low bits then four high bits.
    pub fn cbdEta2(buf: *const [128]u8) Poly {
        var r: Poly = undefined;
        var idx: usize = 0;
        for (buf) |v| {
            var b = v;
            var group: usize = 0;
            while (group < 2) : (group += 1) {
                const a0: u8 = b & 0x3;
                const b0: u8 = (b >> 2) & 0x3;
                r[idx] = @as(i16, @intCast(@popCount(a0))) - @as(i16, @intCast(@popCount(b0)));
                idx += 1;
                b >>= 4;
            }
        }
        return r;
    }

    pub const Params = struct { k: u8, eta1: u8, eta2: u8, du: u8, dv: u8 };
    pub const p512 = Params{ .k = 2, .eta1 = 3, .eta2 = 2, .du = 10, .dv = 4 };
    pub const p768 = Params{ .k = 3, .eta1 = 2, .eta2 = 2, .du = 10, .dv = 4 };
    pub const p1024 = Params{ .k = 4, .eta1 = 2, .eta2 = 2, .du = 11, .dv = 5 };
};

// ============================================================================
// EXPANSION 0.3 — cryptographic arithmetic, storage, inference and runtime core
// ============================================================================

pub fn ctIsZero(bytes: []const u8) bool {
    var acc: u8 = 0;
    for (bytes) |b| acc |= b;
    return acc == 0;
}

pub fn ctCompareMask(a: []const u8, b: []const u8) u8 {
    if (a.len != b.len) return 0;
    var x: u8 = 0;
    for (a, b) |aa, bb| x |= aa ^ bb;
    const y: u16 = @as(u16, x);
    const nz: u16 = (y | (0 -% y)) >> 8;
    return @truncate(~nz);
}

pub fn ctConditionalCopy(dst: []u8, src: []const u8, mask: u8) !void {
    if (dst.len != src.len) return error.LengthMismatch;
    for (dst, src) |*d, s| d.* = ctSelect(mask, s, d.*);
}

pub fn xorInto(dst: []u8, src: []const u8) !void {
    if (dst.len != src.len) return error.LengthMismatch;
    for (dst, src) |*d, s| d.* ^= s;
}

pub fn writeU16Le(dst: []u8, v: u16) !void {
    if (dst.len < 2) return error.BufferTooSmall;
    dst[0] = @truncate(v);
    dst[1] = @truncate(v >> 8);
}

pub fn writeU32Le(dst: []u8, v: u32) !void {
    if (dst.len < 4) return error.BufferTooSmall;
    var i: usize = 0;
    while (i < 4) : (i += 1) dst[i] = @truncate(v >> @intCast(i * 8));
}

pub fn writeU64Le(dst: []u8, v: u64) !void {
    if (dst.len < 8) return error.BufferTooSmall;
    var i: usize = 0;
    while (i < 8) : (i += 1) dst[i] = @truncate(v >> @intCast(i * 8));
}

pub fn readU16Le(src: []const u8) !u16 {
    if (src.len < 2) return error.BufferTooSmall;
    return @as(u16, src[0]) | (@as(u16, src[1]) << 8);
}

pub fn readU32Le(src: []const u8) !u32 {
    if (src.len < 4) return error.BufferTooSmall;
    return @as(u32, src[0]) |
        (@as(u32, src[1]) << 8) |
        (@as(u32, src[2]) << 16) |
        (@as(u32, src[3]) << 24);
}

pub fn readU64Le(src: []const u8) !u64 {
    if (src.len < 8) return error.BufferTooSmall;
    var v: u64 = 0;
    var i: usize = 0;
    while (i < 8) : (i += 1) v |= @as(u64, src[i]) << @intCast(i * 8);
    return v;
}

pub const Hex = struct {
    pub fn nibble(c: u8) !u8 {
        return switch (c) {
            '0'...'9' => c - '0',
            'a'...'f' => c - 'a' + 10,
            'A'...'F' => c - 'A' + 10,
            else => error.InvalidHex,
        };
    }

    pub fn decode(out: []u8, text: []const u8) !usize {
        if ((text.len & 1) != 0) return error.InvalidHex;
        if (out.len < text.len / 2) return error.BufferTooSmall;
        var i: usize = 0;
        while (i < text.len) : (i += 2) out[i / 2] = (try nibble(text[i]) << 4) | try nibble(text[i + 1]);
        return text.len / 2;
    }

    pub fn encodeLower(out: []u8, bytes: []const u8) !usize {
        const alphabet = "0123456789abcdef";
        if (out.len < bytes.len * 2) return error.BufferTooSmall;
        for (bytes, 0..) |b, i| {
            out[i * 2] = alphabet[b >> 4];
            out[i * 2 + 1] = alphabet[b & 15];
        }
        return bytes.len * 2;
    }
};

pub const Base64 = struct {
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    fn index(c: u8) !u8 {
        return switch (c) {
            'A'...'Z' => c - 'A',
            'a'...'z' => c - 'a' + 26,
            '0'...'9' => c - '0' + 52,
            '+' => 62,
            '/' => 63,
            else => error.InvalidBase64,
        };
    }

    pub fn encodedLength(n: usize) usize {
        return ((n + 2) / 3) * 4;
    }

    pub fn encode(out: []u8, src: []const u8) !usize {
        const need = encodedLength(src.len);
        if (out.len < need) return error.BufferTooSmall;
        var si: usize = 0;
        var oi: usize = 0;
        while (si + 3 <= src.len) : (si += 3) {
            const v = (@as(u32, src[si]) << 16) | (@as(u32, src[si + 1]) << 8) | src[si + 2];
            out[oi] = alphabet[@intCast((v >> 18) & 63)];
            out[oi + 1] = alphabet[@intCast((v >> 12) & 63)];
            out[oi + 2] = alphabet[@intCast((v >> 6) & 63)];
            out[oi + 3] = alphabet[@intCast(v & 63)];
            oi += 4;
        }
        const rem = src.len - si;
        if (rem == 1) {
            const v = @as(u32, src[si]) << 16;
            out[oi] = alphabet[@intCast((v >> 18) & 63)];
            out[oi + 1] = alphabet[@intCast((v >> 12) & 63)];
            out[oi + 2] = '=';
            out[oi + 3] = '=';
        } else if (rem == 2) {
            const v = (@as(u32, src[si]) << 16) | (@as(u32, src[si + 1]) << 8);
            out[oi] = alphabet[@intCast((v >> 18) & 63)];
            out[oi + 1] = alphabet[@intCast((v >> 12) & 63)];
            out[oi + 2] = alphabet[@intCast((v >> 6) & 63)];
            out[oi + 3] = '=';
        }
        return need;
    }

    pub fn decode(out: []u8, src: []const u8) !usize {
        if ((src.len & 3) != 0) return error.InvalidBase64;
        var si: usize = 0;
        var oi: usize = 0;
        while (si < src.len) : (si += 4) {
            const last = si + 4 == src.len;
            const pad2 = src[si + 2] == '=';
            const pad1 = src[si + 3] == '=';
            if (!last and (pad1 or pad2)) return error.InvalidBase64;
            const a = try index(src[si]);
            const b = try index(src[si + 1]);
            const c: u8 = if (pad2) 0 else try index(src[si + 2]);
            const d: u8 = if (pad1) 0 else try index(src[si + 3]);
            const v = (@as(u32, a) << 18) | (@as(u32, b) << 12) | (@as(u32, c) << 6) | d;
            if (oi >= out.len) return error.BufferTooSmall;
            out[oi] = @truncate(v >> 16);
            oi += 1;
            if (!pad2) {
                if (oi >= out.len) return error.BufferTooSmall;
                out[oi] = @truncate(v >> 8);
                oi += 1;
            }
            if (!pad1) {
                if (oi >= out.len) return error.BufferTooSmall;
                out[oi] = @truncate(v);
                oi += 1;
            }
        }
        return oi;
    }
};

// ----------------------------------------------------------------------------
// SHA-512 HMAC + HKDF used by Naza's robust-combiner transcript machinery.
// ----------------------------------------------------------------------------

pub fn hmacSha512(key: []const u8, msg: []const u8) [64]u8 {
    var k0 = [_]u8{0} ** 128;
    if (key.len > 128) {
        const kh = sha512(key);
        @memcpy(k0[0..64], &kh);
    } else {
        @memcpy(k0[0..key.len], key);
    }
    var ipad = [_]u8{0x36} ** 128;
    var opad = [_]u8{0x5c} ** 128;
    for (0..128) |i| {
        ipad[i] ^= k0[i];
        opad[i] ^= k0[i];
    }
    var inner = std.crypto.hash.sha2.Sha512.init(.{});
    inner.update(&ipad);
    inner.update(msg);
    var ih: [64]u8 = undefined;
    inner.final(&ih);
    var outer = std.crypto.hash.sha2.Sha512.init(.{});
    outer.update(&opad);
    outer.update(&ih);
    var out: [64]u8 = undefined;
    outer.final(&out);
    secureZero(k0[0..]);
    secureZero(ipad[0..]);
    secureZero(opad[0..]);
    secureZero(ih[0..]);
    return out;
}

pub fn hkdfExtractSha512(salt: []const u8, ikm: []const u8) [64]u8 {
    if (salt.len == 0) {
        const zero = [_]u8{0} ** 64;
        return hmacSha512(&zero, ikm);
    }
    return hmacSha512(salt, ikm);
}

pub fn hkdfExpandSha512(prk: []const u8, info: []const u8, out: []u8) !void {
    if (out.len > 255 * 64) return error.OutputTooLong;
    var t: [64]u8 = undefined;
    var t_len: usize = 0;
    var pos: usize = 0;
    var counter: u8 = 1;
    while (pos < out.len) {
        var h = std.crypto.auth.hmac.sha2.HmacSha512.init(prk);
        if (t_len != 0) h.update(t[0..t_len]);
        h.update(info);
        const c = [_]u8{counter};
        h.update(&c);
        h.final(&t);
        t_len = 64;
        const ncopy = @min(out.len - pos, 64);
        @memcpy(out[pos .. pos + ncopy], t[0..ncopy]);
        pos += ncopy;
        counter +%= 1;
    }
    secureZero(t[0..]);
}

pub fn hkdfSha512(ikm: []const u8, salt: []const u8, info: []const u8, out: []u8) !void {
    var prk = hkdfExtractSha512(salt, ikm);
    defer secureZero(prk[0..]);
    try hkdfExpandSha512(&prk, info, out);
}

// ----------------------------------------------------------------------------
// ML-KEM / Kyber NTT arithmetic. Constants are the standardized public zeta schedule.
// ----------------------------------------------------------------------------

pub const MlKemNtt = struct {
    pub const q: i32 = 3329;
    pub const qinv: i32 = -3327; // q^-1 mod 2^16 in signed representation
    pub const mont: i32 = 2285;
    pub const f_inv: i16 = 1441;

    pub const zetas = [128]i16{
        -1044, -758,  -359,  -1517, 1493,  1422,  287,   202,
        -171,  622,   1577,  182,   962,   -1202, -1474, 1468,
        573,   -1325, 264,   383,   -829,  1458,  -1602, -130,
        -681,  1017,  732,   608,   -1542, 411,   -205,  -1571,
        1223,  652,   -552,  1015,  -1293, 1491,  -282,  -1544,
        516,   -8,    -320,  -666,  -1618, -1162, 126,   1469,
        -853,  -90,   -271,  830,   107,   -1421, -247,  -951,
        -398,  961,   -1508, -725,  448,   -1065, 677,   -1275,
        -1103, 430,   555,   843,   -1251, 871,   1550,  105,
        422,   587,   177,   -235,  -291,  -460,  1574,  1653,
        -246,  778,   1159,  -147,  -777,  1483,  -602,  1119,
        -1590, 644,   -872,  349,   418,   329,   -156,  -75,
        817,   1097,  603,   610,   1322,  -1285, -1465, 384,
        -1215, -136,  1218,  -1335, -874,  220,   -1187, -1659,
        -1185, -1530, -1278, 794,   -1510, -854,  -870,  478,
        -108,  -308,  996,   991,   958,   -1460, 1522,  1628,
    };

    pub inline fn montgomeryReduce(a: i32) i16 {
        const low: i16 = @truncate(a);
        const t: i16 = @truncate(@as(i32, low) * qinv);
        return @truncate((a - @as(i32, t) * q) >> 16);
    }

    pub inline fn barrettReduce(a: i16) i16 {
        const v: i32 = ((@as(i32, 1) << 26) + q / 2) / q;
        var t: i32 = (v * @as(i32, a) + (@as(i32, 1) << 25)) >> 26;
        t *= q;
        return @intCast(@as(i32, a) - t);
    }

    pub inline fn fqmul(a: i16, b: i16) i16 {
        return montgomeryReduce(@as(i32, a) * @as(i32, b));
    }

    pub fn ntt(r: *MlKem.Poly) void {
        var k: usize = 1;
        var len: usize = 128;
        while (len >= 2) : (len >>= 1) {
            var start: usize = 0;
            while (start < 256) {
                const zeta = zetas[k];
                k += 1;
                var j = start;
                while (j < start + len) : (j += 1) {
                    const t = fqmul(zeta, r[j + len]);
                    const a = r[j];
                    r[j + len] = a -% t;
                    r[j] = a +% t;
                }
                start += 2 * len;
            }
            if (len == 2) break;
        }
    }

    pub fn invNttToMont(r: *MlKem.Poly) void {
        var k: usize = 127;
        var len: usize = 2;
        while (len <= 128) : (len <<= 1) {
            var start: usize = 0;
            while (start < 256) {
                const zeta = zetas[k];
                if (k != 0) k -= 1;
                var j = start;
                while (j < start + len) : (j += 1) {
                    const t = r[j];
                    r[j] = barrettReduce(t +% r[j + len]);
                    r[j + len] = r[j + len] -% t;
                    r[j + len] = fqmul(zeta, r[j + len]);
                }
                start += 2 * len;
            }
        }
        for (r) |*x| x.* = fqmul(x.*, f_inv);
    }

    pub fn baseMul(r: *[2]i16, a: *const [2]i16, b: *const [2]i16, zeta: i16) void {
        var x0 = fqmul(a[1], b[1]);
        x0 = fqmul(x0, zeta);
        x0 +%= fqmul(a[0], b[0]);
        var x1 = fqmul(a[0], b[1]);
        x1 +%= fqmul(a[1], b[0]);
        r[0] = x0;
        r[1] = x1;
    }

    pub fn polyBaseMulMontgomery(r: *MlKem.Poly, a: *const MlKem.Poly, b: *const MlKem.Poly) void {
        var i: usize = 0;
        while (i < 64) : (i += 1) {
            var aa = [2]i16{ a[4 * i], a[4 * i + 1] };
            var bb = [2]i16{ b[4 * i], b[4 * i + 1] };
            var rr: [2]i16 = undefined;
            baseMul(&rr, &aa, &bb, zetas[64 + i]);
            r[4 * i] = rr[0];
            r[4 * i + 1] = rr[1];
            aa = [2]i16{ a[4 * i + 2], a[4 * i + 3] };
            bb = [2]i16{ b[4 * i + 2], b[4 * i + 3] };
            baseMul(&rr, &aa, &bb, -zetas[64 + i]);
            r[4 * i + 2] = rr[0];
            r[4 * i + 3] = rr[1];
        }
    }

    pub fn polyReduce(r: *MlKem.Poly) void {
        for (r) |*x| x.* = barrettReduce(x.*);
    }

    pub fn polyToMont(r: *MlKem.Poly) void {
        const f: i16 = 1353; // (1<<32) mod q
        for (r) |*x| x.* = fqmul(x.*, f);
    }
};

// ----------------------------------------------------------------------------
// ML-KEM polynomial codecs, message map, CBD and matrix-XOF generation.
// ----------------------------------------------------------------------------

pub const MlKemCodec = struct {
    pub const poly_bytes = 384;

    pub fn polyToBytes(out: *[poly_bytes]u8, a: *const MlKem.Poly) void {
        var i: usize = 0;
        while (i < 128) : (i += 1) {
            var t0: i32 = MlKemNtt.barrettReduce(a[2 * i]);
            var t1: i32 = MlKemNtt.barrettReduce(a[2 * i + 1]);
            if (t0 < 0) t0 += MlKem.q;
            if (t1 < 0) t1 += MlKem.q;
            const low0: u16 = @intCast(t0);
            const high1: u16 = @intCast(t1);
            out[3 * i] = @truncate(low0);
            out[3 * i + 1] = @truncate((low0 >> 8) | (high1 << 4));
            out[3 * i + 2] = @truncate(high1 >> 4);
        }
    }

    pub fn polyFromBytes(r: *MlKem.Poly, src: *const [poly_bytes]u8) void {
        var i: usize = 0;
        while (i < 128) : (i += 1) {
            r[2 * i] = @intCast((@as(u16, src[3 * i]) | (@as(u16, src[3 * i + 1]) << 8)) & 0xfff);
            r[2 * i + 1] = @intCast(((@as(u16, src[3 * i + 1]) >> 4) | (@as(u16, src[3 * i + 2]) << 4)) & 0xfff);
        }
    }

    pub fn fromMsg(r: *MlKem.Poly, msg: *const [32]u8) void {
        var i: usize = 0;
        while (i < 256) : (i += 1) {
            const bit: u16 = (msg[i >> 3] >> @intCast(i & 7)) & 1;
            const mask: u16 = 0 -% bit;
            r[i] = @intCast(mask & ((MlKem.q + 1) / 2));
        }
    }

    pub fn toMsg(msg: *[32]u8, a: *const MlKem.Poly) void {
        @memset(msg, 0);
        var i: usize = 0;
        while (i < 256) : (i += 1) {
            var t: i32 = MlKemNtt.barrettReduce(a[i]);
            if (t < 0) t += MlKem.q;
            const q: u32 = @intCast(MlKem.q);
            const bit: u8 = @truncate((((@as(u32, @intCast(t)) << 1) + q / 2) / q) & 1);
            msg[i >> 3] |= bit << @intCast(i & 7);
        }
    }

    pub fn cbdEta3(buf: *const [192]u8) MlKem.Poly {
        var r: MlKem.Poly = undefined;
        var i: usize = 0;
        while (i < 64) : (i += 1) {
            const t = @as(u32, buf[3 * i]) | (@as(u32, buf[3 * i + 1]) << 8) | (@as(u32, buf[3 * i + 2]) << 16);
            var d = t & 0x00249249;
            d += (t >> 1) & 0x00249249;
            d += (t >> 2) & 0x00249249;
            var j: usize = 0;
            while (j < 4) : (j += 1) {
                const aa: i16 = @intCast((d >> @intCast(6 * j)) & 0x7);
                const bb: i16 = @intCast((d >> @intCast(6 * j + 3)) & 0x7);
                r[4 * i + j] = aa - bb;
            }
        }
        return r;
    }

    pub fn noiseEta2(seed: *const [32]u8, nonce: u8) MlKem.Poly {
        var ext: [33]u8 = undefined;
        @memcpy(ext[0..32], seed);
        ext[32] = nonce;
        var buf: [128]u8 = undefined;
        shake256(&ext, &buf);
        defer secureZero(buf[0..]);
        return MlKem.cbdEta2(&buf);
    }

    pub fn noiseEta3(seed: *const [32]u8, nonce: u8) MlKem.Poly {
        var ext: [33]u8 = undefined;
        @memcpy(ext[0..32], seed);
        ext[32] = nonce;
        var buf: [192]u8 = undefined;
        shake256(&ext, &buf);
        defer secureZero(buf[0..]);
        return cbdEta3(&buf);
    }

    pub fn uniformFromRho(rho: *const [32]u8, x: u8, y: u8) MlKem.Poly {
        var seed: [34]u8 = undefined;
        @memcpy(seed[0..32], rho);
        seed[32] = x;
        seed[33] = y;
        var p: MlKem.Poly = undefined;
        MlKem.rejUniform(&p, &seed);
        return p;
    }

    pub fn compressCoeff(x_in: i16, bits: u5) u16 {
        var x: i32 = MlKemNtt.barrettReduce(x_in);
        if (x < 0) x += MlKem.q;
        const scale: u32 = @as(u32, 1) << bits;
        const q: u32 = @intCast(MlKem.q);
        return @truncate(((@as(u32, @intCast(x)) * scale + q / 2) / q) & (scale - 1));
    }

    pub fn decompressCoeff(x: u16, bits: u5) i16 {
        const round = @as(u32, 1) << (bits - 1);
        return @intCast((@as(u32, x) * MlKem.q + round) >> bits);
    }

    pub fn compressPoly4(out: *[128]u8, a: *const MlKem.Poly) void {
        var i: usize = 0;
        while (i < 128) : (i += 1) {
            const t0: u8 = @truncate(compressCoeff(a[2 * i], 4));
            const t1: u8 = @truncate(compressCoeff(a[2 * i + 1], 4));
            out[i] = t0 | (t1 << 4);
        }
    }

    pub fn decompressPoly4(r: *MlKem.Poly, src: *const [128]u8) void {
        for (src, 0..) |v, i| {
            r[2 * i] = decompressCoeff(v & 15, 4);
            r[2 * i + 1] = decompressCoeff(v >> 4, 4);
        }
    }

    pub fn compressPoly5(out: *[160]u8, a: *const MlKem.Poly) void {
        var i: usize = 0;
        while (i < 32) : (i += 1) {
            var t: [8]u16 = undefined;
            var j: usize = 0;
            while (j < 8) : (j += 1) t[j] = compressCoeff(a[8 * i + j], 5);
            out[5 * i] = @truncate(t[0] | (t[1] << 5));
            out[5 * i + 1] = @truncate((t[1] >> 3) | (t[2] << 2) | (t[3] << 7));
            out[5 * i + 2] = @truncate((t[3] >> 1) | (t[4] << 4));
            out[5 * i + 3] = @truncate((t[4] >> 4) | (t[5] << 1) | (t[6] << 6));
            out[5 * i + 4] = @truncate((t[6] >> 2) | (t[7] << 3));
        }
    }

    pub fn decompressPoly5(r: *MlKem.Poly, src: *const [160]u8) void {
        var i: usize = 0;
        while (i < 32) : (i += 1) {
            const s0 = src[5 * i];
            const s1 = src[5 * i + 1];
            const s2 = src[5 * i + 2];
            const s3 = src[5 * i + 3];
            const s4 = src[5 * i + 4];
            const t = [8]u16{
                s0 & 31,
                ((@as(u16, s0) >> 5) | (@as(u16, s1) << 3)) & 31,
                (@as(u16, s1) >> 2) & 31,
                ((@as(u16, s1) >> 7) | (@as(u16, s2) << 1)) & 31,
                ((@as(u16, s2) >> 4) | (@as(u16, s3) << 4)) & 31,
                (@as(u16, s3) >> 1) & 31,
                ((@as(u16, s3) >> 6) | (@as(u16, s4) << 2)) & 31,
                (@as(u16, s4) >> 3) & 31,
            };
            var j: usize = 0;
            while (j < 8) : (j += 1) r[8 * i + j] = decompressCoeff(t[j], 5);
        }
    }
};

pub const MlKemVec = struct {
    pub const max_k = 4;
    pub const PolyVec = [max_k]MlKem.Poly;

    pub fn clear(v: *PolyVec) void {
        for (v) |*p| @memset(p, 0);
    }

    pub fn ntt(v: *PolyVec, k: usize) void {
        var i: usize = 0;
        while (i < k) : (i += 1) MlKemNtt.ntt(&v[i]);
    }

    pub fn invNtt(v: *PolyVec, k: usize) void {
        var i: usize = 0;
        while (i < k) : (i += 1) MlKemNtt.invNttToMont(&v[i]);
    }

    pub fn reduce(v: *PolyVec, k: usize) void {
        var i: usize = 0;
        while (i < k) : (i += 1) MlKemNtt.polyReduce(&v[i]);
    }

    pub fn add(r: *PolyVec, a: *const PolyVec, b: *const PolyVec, k: usize) void {
        var i: usize = 0;
        while (i < k) : (i += 1) r[i] = MlKem.add(a[i], b[i]);
    }

    pub fn pointwiseAcc(r: *MlKem.Poly, a: *const PolyVec, b: *const PolyVec, k: usize) void {
        var tmp: MlKem.Poly = undefined;
        MlKemNtt.polyBaseMulMontgomery(r, &a[0], &b[0]);
        var i: usize = 1;
        while (i < k) : (i += 1) {
            MlKemNtt.polyBaseMulMontgomery(&tmp, &a[i], &b[i]);
            r.* = MlKem.add(r.*, tmp);
        }
        MlKemNtt.polyReduce(r);
    }
};

// ----------------------------------------------------------------------------
// Deterministic ML-KEM IND-CPA core implementation. It performs matrix/noise/NTT
// operations directly in Zig; vector verification remains a separate validation state.
// ----------------------------------------------------------------------------

pub const MlKemIndCpa = struct {
    pub const MaxK = 4;
    pub const Matrix = [MaxK][MaxK]MlKem.Poly;

    pub fn genMatrix(out: *Matrix, rho: *const [32]u8, k: usize, transposed: bool) !void {
        if (k < 2 or k > 4) return error.InvalidParameterSet;
        var i: usize = 0;
        while (i < k) : (i += 1) {
            var j: usize = 0;
            while (j < k) : (j += 1) {
                const x: u8 = @intCast(if (transposed) i else j);
                const y: u8 = @intCast(if (transposed) j else i);
                out[i][j] = MlKemCodec.uniformFromRho(rho, x, y);
            }
        }
    }

    pub fn deriveKeygenSeeds(seed: *const [32]u8, params: MlKem.Params, rho: *[32]u8, sigma: *[32]u8) void {
        // FIPS 203 K-PKE.KeyGen: (rho, sigma) = G(d || k), with G = SHA3-512.
        var input: [33]u8 = undefined;
        @memcpy(input[0..32], seed);
        input[32] = params.k;
        const expanded = sha3_512(&input);
        @memcpy(rho, expanded[0..32]);
        @memcpy(sigma, expanded[32..64]);
        secureZero(&input);
    }

    pub fn sampleSecret(out: *MlKemVec.PolyVec, sigma: *const [32]u8, params: MlKem.Params) void {
        var nonce: u8 = 0;
        var i: usize = 0;
        while (i < params.k) : (i += 1) {
            out[i] = if (params.eta1 == 3) MlKemCodec.noiseEta3(sigma, nonce) else MlKemCodec.noiseEta2(sigma, nonce);
            nonce +%= 1;
        }
    }

    pub fn sampleKeygenError(out: *MlKemVec.PolyVec, sigma: *const [32]u8, params: MlKem.Params, start_nonce: u8) void {
        var nonce = start_nonce;
        var i: usize = 0;
        while (i < params.k) : (i += 1) {
            out[i] = if (params.eta1 == 3) MlKemCodec.noiseEta3(sigma, nonce) else MlKemCodec.noiseEta2(sigma, nonce);
            nonce +%= 1;
        }
    }

    pub fn keypairCore(t: *MlKemVec.PolyVec, s: *MlKemVec.PolyVec, rho: *[32]u8, seed: *const [32]u8, params: MlKem.Params) !void {
        var sigma: [32]u8 = undefined;
        defer secureZero(sigma[0..]);
        deriveKeygenSeeds(seed, params, rho, &sigma);
        var a: Matrix = undefined;
        try genMatrix(&a, rho, params.k, false);
        sampleSecret(s, &sigma, params);
        var e: MlKemVec.PolyVec = undefined;
        defer secureZero(std.mem.asBytes(&e));
        sampleKeygenError(&e, &sigma, params, params.k);
        MlKemVec.ntt(s, params.k);
        MlKemVec.ntt(&e, params.k);
        var i: usize = 0;
        while (i < params.k) : (i += 1) {
            MlKemVec.pointwiseAcc(&t[i], &a[i], s, params.k);
            MlKemNtt.polyToMont(&t[i]);
            t[i] = MlKem.add(t[i], e[i]);
            MlKemNtt.polyReduce(&t[i]);
        }
    }
};

// ----------------------------------------------------------------------------
// Pure-Zig entropy / DRBG utilities.
// ----------------------------------------------------------------------------

pub const HashDrbg = struct {
    key: [32]u8,
    counter: u64,

    pub fn init(seed: []const u8) HashDrbg {
        return .{ .key = sha256(seed), .counter = 0 };
    }

    pub fn reseed(self: *HashDrbg, seed: []const u8) void {
        var h = std.crypto.hash.sha2.Sha256.init(.{});
        h.update(&self.key);
        h.update(seed);
        h.final(&self.key);
        self.counter = 0;
    }

    pub fn fill(self: *HashDrbg, out: []u8) void {
        var pos: usize = 0;
        while (pos < out.len) {
            var ctr: [8]u8 = undefined;
            writeU64Le(&ctr, self.counter) catch unreachable;
            const block = hmacSha256(&self.key, &ctr);
            const ncopy = @min(block.len, out.len - pos);
            @memcpy(out[pos .. pos + ncopy], block[0..ncopy]);
            self.counter +%= 1;
            pos += ncopy;
        }
        const next = hmacSha256(&self.key, "NAZA/DRBG/REKEY");
        self.key = next;
    }

    pub fn deinit(self: *HashDrbg) void {
        secureZero(self.key[0..]);
        self.counter = 0;
    }
};

pub const XorShift128Plus = struct {
    s0: u64,
    s1: u64,

    pub fn init(seed: u64) XorShift128Plus {
        var x = seed;
        const a = splitmix(&x);
        const b = splitmix(&x);
        return .{ .s0 = a, .s1 = b };
    }

    fn splitmix(x: *u64) u64 {
        x.* +%= 0x9E3779B97F4A7C15;
        var z = x.*;
        z = (z ^ (z >> 30)) *% 0xBF58476D1CE4E5B9;
        z = (z ^ (z >> 27)) *% 0x94D049BB133111EB;
        return z ^ (z >> 31);
    }

    pub fn next(self: *XorShift128Plus) u64 {
        var x = self.s0;
        const y = self.s1;
        self.s0 = y;
        x ^= x << 23;
        x ^= x >> 17;
        x ^= y ^ (y >> 26);
        self.s1 = x;
        return x +% y;
    }

    pub fn unit(self: *XorShift128Plus) f64 {
        return @as(f64, @floatFromInt(self.next() >> 11)) * (1.0 / 9007199254740992.0);
    }
};

// ----------------------------------------------------------------------------
// Tensor primitives for transformer inference.
// ----------------------------------------------------------------------------

pub fn vectorAdd(dst: []f32, a: []const f32, b: []const f32) !void {
    if (dst.len != a.len or a.len != b.len) return error.ShapeMismatch;
    for (dst, a, b) |*d, x, y| d.* = x + y;
}

pub fn vectorMul(dst: []f32, a: []const f32, b: []const f32) !void {
    if (dst.len != a.len or a.len != b.len) return error.ShapeMismatch;
    for (dst, a, b) |*d, x, y| d.* = x * y;
}

pub fn vectorScale(dst: []f32, a: []const f32, scale: f32) !void {
    if (dst.len != a.len) return error.ShapeMismatch;
    for (dst, a) |*d, x| d.* = x * scale;
}

pub fn dot(a: []const f32, b: []const f32) !f32 {
    if (a.len != b.len) return error.ShapeMismatch;
    var acc: f32 = 0;
    for (a, b) |x, y| acc += x * y;
    return acc;
}

pub fn swiglu(out: []f32, gate: []const f32, up: []const f32) !void {
    if (out.len != gate.len or gate.len != up.len) return error.ShapeMismatch;
    for (out, gate, up) |*o, g, u| o.* = silu(g) * u;
}

pub fn argmax(x: []const f32) usize {
    if (x.len == 0) return 0;
    var best: usize = 0;
    var i: usize = 1;
    while (i < x.len) : (i += 1) if (x[i] > x[best]) {
        best = i;
    };
    return best;
}

pub const LlamaConfig = struct {
    vocab_size: usize,
    hidden_size: usize,
    intermediate_size: usize,
    layer_count: usize,
    head_count: usize,
    kv_head_count: usize,
    context_length: usize,
    rope_theta: f32 = 500000.0,
    rms_epsilon: f32 = 1e-5,

    pub fn headDim(self: LlamaConfig) !usize {
        if (self.head_count == 0 or self.hidden_size % self.head_count != 0) return error.InvalidModelConfig;
        return self.hidden_size / self.head_count;
    }

    pub fn validate(self: LlamaConfig) !void {
        if (self.vocab_size == 0 or self.hidden_size == 0 or self.layer_count == 0) return error.InvalidModelConfig;
        if (self.kv_head_count == 0 or self.head_count % self.kv_head_count != 0) return error.InvalidModelConfig;
        _ = try self.headDim();
    }
};

pub const Rope = struct {
    pub fn apply(x: []f32, position: usize, theta: f32) !void {
        if ((x.len & 1) != 0) return error.InvalidHeadDimension;
        const half = x.len / 2;
        var i: usize = 0;
        while (i < half) : (i += 1) {
            const exponent = @as(f32, @floatFromInt(2 * i)) / @as(f32, @floatFromInt(x.len));
            const freq = 1.0 / std.math.pow(f32, theta, exponent);
            const angle = @as(f32, @floatFromInt(position)) * freq;
            const c = @cos(angle);
            const s = @sin(angle);
            const a = x[i];
            const b = x[i + half];
            x[i] = a * c - b * s;
            x[i + half] = a * s + b * c;
        }
    }

    pub fn applyInterleaved(x: []f32, position: usize, theta: f32) !void {
        if ((x.len & 1) != 0) return error.InvalidHeadDimension;
        var i: usize = 0;
        while (i < x.len) : (i += 2) {
            const exponent = @as(f32, @floatFromInt(i)) / @as(f32, @floatFromInt(x.len));
            const freq = 1.0 / std.math.pow(f32, theta, exponent);
            const angle = @as(f32, @floatFromInt(position)) * freq;
            const c = @cos(angle);
            const s = @sin(angle);
            const a = x[i];
            const b = x[i + 1];
            x[i] = a * c - b * s;
            x[i + 1] = a * s + b * c;
        }
    }
};

pub const KvCache = struct {
    allocator: std.mem.Allocator,
    keys: []f32,
    values: []f32,
    layer_count: usize,
    context: usize,
    kv_heads: usize,
    head_dim: usize,

    pub fn init(allocator: std.mem.Allocator, cfg: LlamaConfig) !KvCache {
        try cfg.validate();
        const hd = try cfg.headDim();
        const items = try std.math.mul(usize, cfg.layer_count, try std.math.mul(usize, cfg.context_length, try std.math.mul(usize, cfg.kv_head_count, hd)));
        const k = try allocator.alloc(f32, items);
        errdefer allocator.free(k);
        const v = try allocator.alloc(f32, items);
        @memset(k, 0);
        @memset(v, 0);
        return .{ .allocator = allocator, .keys = k, .values = v, .layer_count = cfg.layer_count, .context = cfg.context_length, .kv_heads = cfg.kv_head_count, .head_dim = hd };
    }

    pub fn deinit(self: *KvCache) void {
        @memset(self.keys, 0);
        @memset(self.values, 0);
        self.allocator.free(self.keys);
        self.allocator.free(self.values);
        self.* = undefined;
    }

    fn base(self: KvCache, layer: usize, pos: usize, head: usize) !usize {
        if (layer >= self.layer_count or pos >= self.context or head >= self.kv_heads) return error.CacheIndexOutOfRange;
        return (((layer * self.context) + pos) * self.kv_heads + head) * self.head_dim;
    }

    pub fn put(self: *KvCache, layer: usize, pos: usize, head: usize, key_values: []const f32, value_values: []const f32) !void {
        if (key_values.len != self.head_dim or value_values.len != self.head_dim) return error.ShapeMismatch;
        const off = try self.base(layer, pos, head);
        @memcpy(self.keys[off .. off + self.head_dim], key_values);
        @memcpy(self.values[off .. off + self.head_dim], value_values);
    }

    pub fn key(self: KvCache, layer: usize, pos: usize, head: usize) ![]const f32 {
        const off = try self.base(layer, pos, head);
        return self.keys[off .. off + self.head_dim];
    }

    pub fn value(self: KvCache, layer: usize, pos: usize, head: usize) ![]const f32 {
        const off = try self.base(layer, pos, head);
        return self.values[off .. off + self.head_dim];
    }
};

pub const Attention = struct {
    pub fn singleHead(
        out: []f32,
        scratch_scores: []f32,
        query: []const f32,
        cache: KvCache,
        layer: usize,
        kv_head: usize,
        position: usize,
    ) !void {
        if (out.len != query.len or query.len != cache.head_dim) return error.ShapeMismatch;
        if (scratch_scores.len < position + 1) return error.BufferTooSmall;
        const inv_sqrt = 1.0 / @sqrt(@as(f32, @floatFromInt(query.len)));
        var p: usize = 0;
        while (p <= position) : (p += 1) {
            const k = try cache.key(layer, p, kv_head);
            scratch_scores[p] = (try dot(query, k)) * inv_sqrt;
        }
        softmaxInPlace(scratch_scores[0 .. position + 1]);
        @memset(out, 0);
        p = 0;
        while (p <= position) : (p += 1) {
            const v = try cache.value(layer, p, kv_head);
            const w = scratch_scores[p];
            for (out, v) |*o, x| o.* += w * x;
        }
    }
};

pub const Sampler = struct {
    temperature: f32 = 0.8,
    top_k: usize = 40,
    top_p: f32 = 0.95,
    repeat_penalty: f32 = 1.0,
    rng: XorShift128Plus,

    pub fn init(seed: u64) Sampler {
        return .{ .rng = XorShift128Plus.init(seed) };
    }

    pub fn greedy(logits: []const f32) usize {
        return argmax(logits);
    }

    pub fn applyTemperature(self: Sampler, logits: []f32) void {
        if (self.temperature <= 0.00001) return;
        const inv = 1.0 / self.temperature;
        for (logits) |*v| v.* *= inv;
    }

    pub fn applyRepeatPenalty(self: Sampler, logits: []f32, history: []const u32) void {
        if (self.repeat_penalty == 1.0) return;
        for (history) |tok| {
            const i: usize = @intCast(tok);
            if (i >= logits.len) continue;
            if (logits[i] < 0) logits[i] *= self.repeat_penalty else logits[i] /= self.repeat_penalty;
        }
    }

    pub fn sampleFull(self: *Sampler, logits: []f32) usize {
        if (self.temperature <= 0.00001) return greedy(logits);
        self.applyTemperature(logits);
        softmaxInPlace(logits);
        const u = self.rng.unit();
        var acc: f64 = 0;
        for (logits, 0..) |p, i| {
            acc += p;
            if (u <= acc) return i;
        }
        return logits.len - 1;
    }
};

// ----------------------------------------------------------------------------
// Executable byte-trie tokenizer. GGUF BPE metadata populates it directly.
// ----------------------------------------------------------------------------

pub const ByteTokenizer = struct {
    pub fn encodeBytes(allocator: std.mem.Allocator, text: []const u8) ![]u32 {
        const out = try allocator.alloc(u32, text.len);
        for (text, 0..) |b, i| out[i] = b;
        return out;
    }

    pub fn decodeBytes(allocator: std.mem.Allocator, tokens: []const u32) ![]u8 {
        const out = try allocator.alloc(u8, tokens.len);
        for (tokens, 0..) |t, i| {
            if (t > 255) return error.InvalidByteToken;
            out[i] = @intCast(t);
        }
        return out;
    }
};

pub const BpeMerge = struct { left: u32, right: u32, merged: u32, rank: u32 };

pub const BpeTokenizer = struct {
    allocator: std.mem.Allocator,
    merges: []BpeMerge,

    pub fn init(allocator: std.mem.Allocator, merges: []const BpeMerge) !BpeTokenizer {
        const owned = try allocator.dupe(BpeMerge, merges);
        return .{ .allocator = allocator, .merges = owned };
    }

    pub fn deinit(self: *BpeTokenizer) void {
        self.allocator.free(self.merges);
        self.* = undefined;
    }

    fn findMerge(self: BpeTokenizer, left: u32, right: u32) ?BpeMerge {
        var best: ?BpeMerge = null;
        for (self.merges) |m| {
            if (m.left == left and m.right == right) {
                if (best == null or m.rank < best.?.rank) best = m;
            }
        }
        return best;
    }

    pub fn mergeInPlace(self: BpeTokenizer, tokens: []u32, len: *usize) void {
        while (len.* > 1) {
            var best_i: ?usize = null;
            var best: ?BpeMerge = null;
            var i: usize = 0;
            while (i + 1 < len.*) : (i += 1) {
                if (self.findMerge(tokens[i], tokens[i + 1])) |m| {
                    if (best == null or m.rank < best.?.rank) {
                        best = m;
                        best_i = i;
                    }
                }
            }
            if (best_i == null) break;
            const at = best_i.?;
            tokens[at] = best.?.merged;
            i = at + 1;
            while (i + 1 < len.*) : (i += 1) tokens[i] = tokens[i + 1];
            len.* -= 1;
        }
    }
};

// ----------------------------------------------------------------------------
// GGML/GGUF quantization descriptors and scalar dequantization helpers.
// ----------------------------------------------------------------------------

pub const GgmlType = enum(u32) {
    f32 = 0,
    f16 = 1,
    q4_0 = 2,
    q4_1 = 3,
    q5_0 = 6,
    q5_1 = 7,
    q8_0 = 8,
    q8_1 = 9,
    q2_k = 10,
    q3_k = 11,
    q4_k = 12,
    q5_k = 13,
    q6_k = 14,
    q8_k = 15,
    iq2_xxs = 16,
    iq2_xs = 17,
    iq3_xxs = 18,
    iq1_s = 19,
    iq4_nl = 20,
    iq3_s = 21,
    iq2_s = 22,
    iq4_xs = 23,
    i8 = 24,
    i16 = 25,
    i32 = 26,
    i64 = 27,
    f64 = 28,
    iq1_m = 29,
    bf16 = 30,
    _,
};

pub const QuantInfo = struct { block_values: usize, block_bytes: usize };

pub fn quantInfo(t: GgmlType) ?QuantInfo {
    return switch (t) {
        .f32 => .{ .block_values = 1, .block_bytes = 4 },
        .f16 => .{ .block_values = 1, .block_bytes = 2 },
        .q4_0 => .{ .block_values = 32, .block_bytes = 18 },
        .q4_1 => .{ .block_values = 32, .block_bytes = 20 },
        .q5_0 => .{ .block_values = 32, .block_bytes = 22 },
        .q5_1 => .{ .block_values = 32, .block_bytes = 24 },
        .q8_0 => .{ .block_values = 32, .block_bytes = 34 },
        .q2_k => .{ .block_values = 256, .block_bytes = 84 },
        .q3_k => .{ .block_values = 256, .block_bytes = 110 },
        .q4_k => .{ .block_values = 256, .block_bytes = 144 },
        .q5_k => .{ .block_values = 256, .block_bytes = 176 },
        .q6_k => .{ .block_values = 256, .block_bytes = 210 },
        else => null,
    };
}

fn f16ToF32(bits: u16) f32 {
    const h: f16 = @bitCast(bits);
    return @floatCast(h);
}

pub const Dequant = struct {
    pub fn q8_0(out: []f32, src: []const u8) !void {
        if (out.len % 32 != 0 or src.len != (out.len / 32) * 34) return error.InvalidQuantizedLength;
        var b: usize = 0;
        while (b < out.len / 32) : (b += 1) {
            const off = b * 34;
            const d = f16ToF32(try readU16Le(src[off .. off + 2]));
            var i: usize = 0;
            while (i < 32) : (i += 1) {
                const qv: i8 = @bitCast(src[off + 2 + i]);
                out[b * 32 + i] = d * @as(f32, @floatFromInt(qv));
            }
        }
    }

    pub fn q4_0(out: []f32, src: []const u8) !void {
        if (out.len % 32 != 0 or src.len != (out.len / 32) * 18) return error.InvalidQuantizedLength;
        var b: usize = 0;
        while (b < out.len / 32) : (b += 1) {
            const off = b * 18;
            const d = f16ToF32(try readU16Le(src[off .. off + 2]));
            var i: usize = 0;
            while (i < 16) : (i += 1) {
                const q = src[off + 2 + i];
                const lo: i8 = @intCast(@as(i16, q & 15) - 8);
                const hi: i8 = @intCast(@as(i16, q >> 4) - 8);
                out[b * 32 + i] = d * @as(f32, @floatFromInt(lo));
                out[b * 32 + i + 16] = d * @as(f32, @floatFromInt(hi));
            }
        }
    }
};

// ----------------------------------------------------------------------------
// Naza storage: private-ish atomic replacement protocol without Python/sqlite.
// ----------------------------------------------------------------------------

pub const AtomicStorage = struct {
    pub const max_file = 64 * 1024 * 1024;

    pub fn readAlloc(allocator: std.mem.Allocator, path: []const u8, maximum: usize) ![]u8 {
        if (maximum > max_file) return error.LimitTooLarge;
        var f = try std.fs.cwd().openFile(path, .{});
        defer f.close();
        const st = try f.stat();
        if (st.kind != .file) return error.NotRegularFile;
        if (st.mode & 0o077 != 0) return error.InsecureFilePermissions;
        if (st.size > maximum) return error.FileTooLarge;
        const n: usize = @intCast(st.size);
        const out = try allocator.alloc(u8, n);
        errdefer allocator.free(out);
        var io_buf: [8192]u8 = undefined;
        var reader = f.reader(&io_buf).interface;
        try reader.readSliceAll(out);
        return out;
    }

    pub fn writeAtomic(path: []const u8, data: []const u8) !void {
        if (data.len > max_file) return error.FileTooLarge;
        var name_buf: [1024]u8 = undefined;
        if (path.len + 32 > name_buf.len) return error.PathTooLong;
        @memcpy(name_buf[0..path.len], path);
        const nonce = std.crypto.random.int(u64);
        const suffix = try std.fmt.bufPrint(name_buf[path.len..], ".naza.tmp-{x}", .{nonce});
        const tmp = name_buf[0 .. path.len + suffix.len];
        {
            var f = try std.fs.cwd().createFile(tmp, .{ .truncate = false, .exclusive = true, .mode = 0o600 });
            errdefer std.fs.cwd().deleteFile(tmp) catch {};
            try f.writeAll(data);
            try f.sync();
            f.close();
        }
        std.fs.cwd().rename(tmp, path) catch |err| {
            std.fs.cwd().deleteFile(tmp) catch {};
            return err;
        };
    }

    pub fn secureDelete(path: []const u8, passes: usize) !void {
        var f = std.fs.cwd().openFile(path, .{ .mode = .read_write }) catch |err| switch (err) {
            error.FileNotFound => return,
            else => return err,
        };
        const st = try f.stat();
        var buf: [8192]u8 = undefined;
        var pass: usize = 0;
        while (pass < passes) : (pass += 1) {
            try f.seekTo(0);
            var remain = st.size;
            while (remain > 0) {
                const n: usize = @intCast(@min(remain, buf.len));
                // Deterministic overwrite avoids claiming secure erasure on flash.
                @memset(buf[0..n], @truncate(pass *% 0xA5));
                try f.writeAll(buf[0..n]);
                remain -= n;
            }
            try f.sync();
        }
        f.close();
        try std.fs.cwd().deleteFile(path);
    }
};

// ----------------------------------------------------------------------------
// Transcript-bound robust KEM-combiner KDF core ported from Naza research code.
// It deliberately excludes envelope AEAD/KEM execution until their primitives
// are implemented and verified in this pure-Zig codebase.
// ----------------------------------------------------------------------------

pub const SpookyCombiner = struct {
    pub const version: u32 = 1;
    pub const suite = "SpookyCombiner-1/ML-KEM-1024+HQC-256/HKDF-SHA512";
    pub const context = "naza/spooky-combiner-1/research-key-envelope/v1";
    pub const kem_a = "ML-KEM-1024";
    pub const kem_b = "HQC-256";

    pub const Keys = struct { wrap: [32]u8, confirm: [32]u8 };

    fn digestChunks(prefix: []const u8, chunks: []const []const u8) [64]u8 {
        var h = std.crypto.hash.sha2.Sha512.init(.{});
        h.update(prefix);
        for (chunks) |c| h.update(c);
        var out: [64]u8 = undefined;
        h.final(&out);
        return out;
    }

    pub fn transcript(envelope_id: *const [32]u8, pk_a: []const u8, ct_a: []const u8, pk_b: []const u8, ct_b: []const u8) [64]u8 {
        const chunks = [_][]const u8{ envelope_id, suite, context, kem_a, pk_a, ct_a, kem_b, pk_b, ct_b };
        return digestChunks("SPK1/TRANSCRIPT\x00", &chunks);
    }

    pub fn laneExtract(shared: []const u8, transcript_hash: *const [64]u8, index: u8, alg: []const u8, out: *[64]u8) void {
        const idx = [_]u8{index};
        const chunks = [_][]const u8{ transcript_hash, &idx, alg };
        const salt = digestChunks("SPK1/LANE-SALT\x00", &chunks);
        var info: [128]u8 = undefined;
        const prefix = "SPK1/LANE-EXTRACT\x00";
        var n: usize = 0;
        @memcpy(info[n .. n + prefix.len], prefix);
        n += prefix.len;
        info[n] = index;
        n += 1;
        info[n] = 0;
        n += 1;
        if (n + alg.len > info.len) @panic("algorithm name too long");
        @memcpy(info[n .. n + alg.len], alg);
        n += alg.len;
        hkdfSha512(shared, &salt, info[0..n], out) catch unreachable;
    }

    pub fn combine(ss_a: []const u8, ss_b: []const u8, transcript_hash: *const [64]u8) Keys {
        var lane_a: [64]u8 = undefined;
        var lane_b: [64]u8 = undefined;
        defer secureZero(lane_a[0..]);
        defer secureZero(lane_b[0..]);
        laneExtract(ss_a, transcript_hash, 0, kem_a, &lane_a);
        laneExtract(ss_b, transcript_hash, 1, kem_b, &lane_b);
        const chunks = [_][]const u8{transcript_hash};
        const root_salt = digestChunks("SPK1/ROOT-SALT\x00", &chunks);
        var ikm: [128]u8 = undefined;
        @memcpy(ikm[0..64], &lane_a);
        @memcpy(ikm[64..128], &lane_b);
        defer secureZero(ikm[0..]);
        var root: [64]u8 = undefined;
        hkdfSha512(&ikm, &root_salt, "SPK1/ROBUST-COMBINER-ROOT\x00", &root) catch unreachable;
        defer secureZero(root[0..]);
        var keys: Keys = undefined;
        hkdfSha512(&root, transcript_hash, "SPK1/DATA-WRAP-KEY\x00", &keys.wrap) catch unreachable;
        hkdfSha512(&root, transcript_hash, "SPK1/KEY-CONFIRMATION\x00", &keys.confirm) catch unreachable;
        return keys;
    }

    pub fn confirmation(confirm_key: *const [32]u8, transcript_hash: *const [64]u8, ciphertext: []const u8) [32]u8 {
        var h = std.crypto.auth.hmac.sha2.HmacSha512.init(confirm_key);
        h.update("SPK1/CONFIRM\x00");
        h.update(transcript_hash);
        h.update(ciphertext);
        var full: [64]u8 = undefined;
        h.final(&full);
        var out: [32]u8 = undefined;
        @memcpy(&out, full[0..32]);
        secureZero(full[0..]);
        return out;
    }
};

test "Spooky combiner binds transcript and lane order" {
    const envelope_id = [_]u8{0x01} ** 32;
    const pk_a = [_]u8{0x02} ** 16;
    const ct_a = [_]u8{0x03} ** 16;
    const pk_b = [_]u8{0x04} ** 16;
    const ct_b = [_]u8{0x05} ** 16;
    const transcript = SpookyCombiner.transcript(&envelope_id, &pk_a, &ct_a, &pk_b, &ct_b);
    const ss_a = [_]u8{0x11} ** 32;
    const ss_b = [_]u8{0x22} ** 32;
    const first = SpookyCombiner.combine(&ss_a, &ss_b, &transcript);
    const swapped = SpookyCombiner.combine(&ss_b, &ss_a, &transcript);
    try std.testing.expect(!ctEqual(&first.wrap, &swapped.wrap));
    try std.testing.expect(!ctEqual(&first.confirm, &swapped.confirm));

    var changed_id = envelope_id;
    changed_id[0] ^= 1;
    const changed_transcript = SpookyCombiner.transcript(&changed_id, &pk_a, &ct_a, &pk_b, &ct_b);
    const changed = SpookyCombiner.combine(&ss_a, &ss_b, &changed_transcript);
    try std.testing.expect(!ctEqual(&first.wrap, &changed.wrap));
    try std.testing.expect(!ctEqual(&first.confirm, &changed.confirm));
}

// ----------------------------------------------------------------------------
// Fail-closed model manifest and tensor-name expectations for Llama-family GGUF.
// ----------------------------------------------------------------------------

pub const ModelManifest = struct {
    pub const required_metadata = [_][]const u8{
        "general.architecture",
        "general.name",
        "llama.context_length",
        "llama.embedding_length",
        "llama.block_count",
        "llama.attention.head_count",
        "llama.attention.head_count_kv",
        "llama.rope.freq_base",
        "tokenizer.ggml.model",
        "tokenizer.ggml.tokens",
    };

    pub fn tensorNameRequired(name: []const u8) bool {
        if (std.mem.eql(u8, name, "token_embd.weight")) return true;
        if (std.mem.eql(u8, name, "output_norm.weight")) return true;
        if (std.mem.eql(u8, name, "output.weight")) return true;
        return std.mem.startsWith(u8, name, "blk.");
    }
};

// ----------------------------------------------------------------------------
// Conversation state and prompt framing, kept local and allocation-bounded.
// ----------------------------------------------------------------------------

pub const ChatMessage = struct {
    role: enum { system, user, assistant },
    text: []const u8,
};

pub const PromptBuilder = struct {
    pub fn llama3(allocator: std.mem.Allocator, messages: []const ChatMessage) ![]u8 {
        var list = std.ArrayList(u8).empty;
        defer list.deinit(allocator);
        try list.appendSlice(allocator, "<|begin_of_text|>");
        for (messages) |m| {
            try list.appendSlice(allocator, "<|start_header_id|>");
            try list.appendSlice(allocator, @tagName(m.role));
            try list.appendSlice(allocator, "<|end_header_id|>\n\n");
            try list.appendSlice(allocator, m.text);
            try list.appendSlice(allocator, "<|eot_id|>");
        }
        try list.appendSlice(allocator, "<|start_header_id|>assistant<|end_header_id|>\n\n");
        return try list.toOwnedSlice(allocator);
    }
};

// ----------------------------------------------------------------------------
// Scanner/entropy implementation port: deterministic math only, no fake quantum API.
// ----------------------------------------------------------------------------

pub const SystemMetrics = struct {
    cpu_percent: f64 = 0,
    memory_percent: f64 = 0,
    load1: f64 = 0,
    temperature_c: f64 = 0,
    process_count: u64 = 0,
};

pub const EntropyScore = struct {
    pub fn clamp01(x: f64) f64 {
        return @max(0.0, @min(1.0, x));
    }

    pub fn normalized(metrics: SystemMetrics) f64 {
        const cpu = clamp01(metrics.cpu_percent / 100.0);
        const mem = clamp01(metrics.memory_percent / 100.0);
        const load = clamp01(metrics.load1 / 16.0);
        const temp = clamp01((metrics.temperature_c - 20.0) / 80.0);
        const procs = clamp01(@as(f64, @floatFromInt(metrics.process_count)) / 1000.0);
        const mean = (cpu + mem + load + temp + procs) / 5.0;
        var variance: f64 = 0;
        const vals = [_]f64{ cpu, mem, load, temp, procs };
        for (vals) |v| {
            const d = v - mean;
            variance += d * d;
        }
        variance /= vals.len;
        return clamp01(0.65 * mean + 0.35 * @sqrt(variance));
    }

    pub fn temperatureModifier(score: f64) f32 {
        return @floatCast(0.75 + 0.5 * clamp01(score));
    }
};

// ----------------------------------------------------------------------------
// Additional deterministic tests used by both `zig test` and runtime selftest.
// ----------------------------------------------------------------------------

test "base64 roundtrip" {
    const src = "entangled-zig";
    var enc: [64]u8 = undefined;
    const n = try Base64.encode(&enc, src);
    var dec: [64]u8 = undefined;
    const m = try Base64.decode(&dec, enc[0..n]);
    try std.testing.expectEqualStrings(src, dec[0..m]);
}

test "ML-KEM message codec roundtrip" {
    var msg: [32]u8 = undefined;
    for (&msg, 0..) |*b, i| b.* = @truncate(i * 17 + 3);
    var p: MlKem.Poly = undefined;
    MlKemCodec.fromMsg(&p, &msg);
    var got: [32]u8 = undefined;
    MlKemCodec.toMsg(&got, &p);
    try std.testing.expectEqualSlices(u8, &msg, &got);
}

test "ML-KEM polynomial byte codec" {
    var p: MlKem.Poly = undefined;
    for (&p, 0..) |*x, i| x.* = @intCast(i % MlKem.q);
    var bytes: [MlKemCodec.poly_bytes]u8 = undefined;
    MlKemCodec.polyToBytes(&bytes, &p);
    var got: MlKem.Poly = undefined;
    MlKemCodec.polyFromBytes(&got, &bytes);
    try std.testing.expectEqualSlices(i16, &p, &got);
}

test "DRBG deterministic" {
    var a = HashDrbg.init("seed");
    defer a.deinit();
    var b = HashDrbg.init("seed");
    defer b.deinit();
    var x: [100]u8 = undefined;
    var y: [100]u8 = undefined;
    a.fill(&x);
    b.fill(&y);
    try std.testing.expectEqualSlices(u8, &x, &y);
}

test "RoPE preserves pair energy" {
    var x = [_]f32{ 1, 2, 3, 4 };
    const before = x[0] * x[0] + x[2] * x[2];
    try Rope.apply(&x, 42, 500000.0);
    const after = x[0] * x[0] + x[2] * x[2];
    try std.testing.expectApproxEqAbs(before, after, 0.001);
}

test "prompt builder llama3 framing" {
    const allocator = std.testing.allocator;
    const msgs = [_]ChatMessage{.{ .role = .user, .text = "hello" }};
    const p = try PromptBuilder.llama3(allocator, &msgs);
    defer allocator.free(p);
    try std.testing.expect(std.mem.indexOf(u8, p, "assistant") != null);
}

// ============================================================================
// EXPANSION 0.3b — authenticated local records, conversation log, scanner math,
// model execution and GGUF tensor planning.
// ============================================================================

pub const AeadBox = struct {
    // Original Naza uses AES-256-GCM for authenticated records. Keep the
    // record format stable while removing the unrelated ChaCha20-Poly1305
    // implementation from the application surface.
    const Aead = std.crypto.aead.aes_gcm.Aes256Gcm;
    pub const key_length = Aead.key_length;
    pub const nonce_length = Aead.nonce_length;
    pub const tag_length = Aead.tag_length;

    pub fn seal(ciphertext: []u8, tag: *[tag_length]u8, plaintext: []const u8, aad: []const u8, nonce: *const [nonce_length]u8, key: *const [key_length]u8) !void {
        if (ciphertext.len != plaintext.len) return error.LengthMismatch;
        Aead.encrypt(ciphertext, tag, plaintext, aad, nonce.*, key.*);
    }

    pub fn open(plaintext: []u8, ciphertext: []const u8, tag: *const [tag_length]u8, aad: []const u8, nonce: *const [nonce_length]u8, key: *const [key_length]u8) !void {
        if (plaintext.len != ciphertext.len) return error.LengthMismatch;
        Aead.decrypt(plaintext, ciphertext, tag.*, aad, nonce.*, key.*) catch return error.AuthenticationFailed;
    }
};

pub const SealedRecord = struct {
    pub const magic = "NZR1";
    pub const version: u8 = 1;
    pub const header_len = 4 + 1 + AeadBox.nonce_length + 8;

    pub fn sealAlloc(allocator: std.mem.Allocator, key: *const [32]u8, aad: []const u8, plaintext: []const u8) ![]u8 {
        if (plaintext.len > 16 * 1024 * 1024) return error.RecordTooLarge;
        const total = header_len + plaintext.len + AeadBox.tag_length;
        const out = try allocator.alloc(u8, total);
        errdefer allocator.free(out);
        @memcpy(out[0..4], magic);
        out[4] = version;
        var nonce: [AeadBox.nonce_length]u8 = undefined;
        std.crypto.random.bytes(&nonce);
        @memcpy(out[5 .. 5 + nonce.len], &nonce);
        try writeU64Le(out[5 + nonce.len .. 5 + nonce.len + 8], plaintext.len);
        const ct_off = header_len;
        var tag: [AeadBox.tag_length]u8 = undefined;
        try AeadBox.seal(out[ct_off .. ct_off + plaintext.len], &tag, plaintext, aad, &nonce, key);
        @memcpy(out[ct_off + plaintext.len ..], &tag);
        secureZero(tag[0..]);
        secureZero(nonce[0..]);
        return out;
    }

    pub fn openAlloc(allocator: std.mem.Allocator, key: *const [32]u8, aad: []const u8, blob: []const u8) ![]u8 {
        if (blob.len < header_len + AeadBox.tag_length) return error.InvalidRecord;
        if (!std.mem.eql(u8, blob[0..4], magic) or blob[4] != version) return error.InvalidRecord;
        var nonce: [AeadBox.nonce_length]u8 = undefined;
        @memcpy(&nonce, blob[5 .. 5 + nonce.len]);
        const n64 = try readU64Le(blob[5 + nonce.len .. 5 + nonce.len + 8]);
        if (n64 > 16 * 1024 * 1024) return error.RecordTooLarge;
        const n: usize = @intCast(n64);
        if (blob.len != header_len + n + AeadBox.tag_length) return error.InvalidRecord;
        var tag: [AeadBox.tag_length]u8 = undefined;
        @memcpy(&tag, blob[header_len + n ..]);
        const out = try allocator.alloc(u8, n);
        errdefer allocator.free(out);
        try AeadBox.open(out, blob[header_len .. header_len + n], &tag, aad, &nonce, key);
        secureZero(tag[0..]);
        secureZero(nonce[0..]);
        return out;
    }
};

pub const ConversationRecord = struct {
    timestamp_ns: i128,
    role: u8,
    payload: []const u8,

    pub fn encodeAlloc(self: ConversationRecord, allocator: std.mem.Allocator) ![]u8 {
        if (self.payload.len > 4 * 1024 * 1024) return error.RecordTooLarge;
        const out = try allocator.alloc(u8, 16 + 1 + 8 + self.payload.len);
        const x: u128 = @bitCast(self.timestamp_ns);
        var i: usize = 0;
        while (i < 16) : (i += 1) out[i] = @truncate(x >> @intCast(i * 8));
        out[16] = self.role;
        try writeU64Le(out[17..25], self.payload.len);
        @memcpy(out[25..], self.payload);
        return out;
    }
};

pub const ConversationLog = struct {
    pub const aad = "naza/conversation-log/v1";

    pub fn appendEncrypted(allocator: std.mem.Allocator, path: []const u8, key: *const [32]u8, record: ConversationRecord) !void {
        const raw = try record.encodeAlloc(allocator);
        defer allocator.free(raw);
        const sealed = try SealedRecord.sealAlloc(allocator, key, aad, raw);
        defer allocator.free(sealed);
        var file = try std.fs.cwd().openFile(path, .{ .mode = .read_write });
        defer file.close();
        try file.seekFromEnd(0);
        var lenbuf: [8]u8 = undefined;
        try writeU64Le(&lenbuf, sealed.len);
        try file.writeAll(&lenbuf);
        try file.writeAll(sealed);
        try file.sync();
    }

    pub fn createAndAppend(allocator: std.mem.Allocator, path: []const u8, key: *const [32]u8, record: ConversationRecord) !void {
        var file = try std.fs.cwd().createFile(path, .{ .truncate = false });
        file.close();
        try appendEncrypted(allocator, path, key, record);
    }
};

pub const FileMac = struct {
    pub fn deriveKey(data_key: *const [32]u8) [32]u8 {
        const prk = hkdfExtractSha256("naza/file-mac/salt/v1", data_key);
        var out: [32]u8 = undefined;
        hkdfExpandSha256(&prk, "naza/file-mac/key/v1", &out) catch unreachable;
        return out;
    }

    pub fn computeBytes(data_key: *const [32]u8, data: []const u8) [32]u8 {
        var key = deriveKey(data_key);
        defer secureZero(key[0..]);
        return hmacSha256(&key, data);
    }

    pub fn verifyBytes(data_key: *const [32]u8, data: []const u8, expected: *const [32]u8) bool {
        var got = computeBytes(data_key, data);
        defer secureZero(got[0..]);
        return ctEqual(&got, expected);
    }
};

pub const KeyEnvelope = struct {
    pub const magic = "NKEY4";
    pub const aad = "naza/key-envelope/pure-zig/v4";

    pub fn wrapAlloc(allocator: std.mem.Allocator, kek: *const [32]u8, data_key: *const [32]u8) ![]u8 {
        const sealed = try SealedRecord.sealAlloc(allocator, kek, aad, data_key);
        errdefer allocator.free(sealed);
        const out = try allocator.alloc(u8, magic.len + sealed.len);
        @memcpy(out[0..magic.len], magic);
        @memcpy(out[magic.len..], sealed);
        allocator.free(sealed);
        return out;
    }

    pub fn unwrap(allocator: std.mem.Allocator, kek: *const [32]u8, blob: []const u8) ![32]u8 {
        if (blob.len < magic.len or !std.mem.eql(u8, blob[0..magic.len], magic)) return error.InvalidKeyEnvelope;
        const raw = try SealedRecord.openAlloc(allocator, kek, aad, blob[magic.len..]);
        defer {
            secureZero(raw);
            allocator.free(raw);
        }
        if (raw.len != 32) return error.InvalidKeyEnvelope;
        var out: [32]u8 = undefined;
        @memcpy(&out, raw);
        return out;
    }
};

/// Password-wrapped data-key envelope for new records. NKEY4 remains
/// readable through KeyEnvelope.unwrap; new password-protected keys use this
/// bounded, parameter-carrying Argon2id format.
pub const PasswordKeyEnvelope = struct {
    pub const magic = "NKEY5";
    pub const version: u8 = 1;
    pub const salt_length = 16;
    pub const header_length = magic.len + 1 + 4 + 4 + 4 + salt_length;
    pub const aad_label = "naza/password-key-envelope/v5";

    pub fn wrapAlloc(allocator: std.mem.Allocator, passphrase: []const u8, data_key: *const [32]u8) ![]u8 {
        return wrapWithParams(allocator, passphrase, data_key, PassphraseKdf.default_params);
    }

    pub fn wrapWithParams(allocator: std.mem.Allocator, passphrase: []const u8, data_key: *const [32]u8, params: PassphraseKdf.Params) ![]u8 {
        var salt: [salt_length]u8 = undefined;
        std.crypto.random.bytes(&salt);
        defer secureZero(&salt);

        var header: [header_length]u8 = undefined;
        @memcpy(header[0..magic.len], magic);
        header[5] = version;
        try writeU32Le(header[6..10], params.memory_kib);
        try writeU32Le(header[10..14], params.time_cost);
        try writeU32Le(header[14..18], params.lanes);
        @memcpy(header[18..], &salt);

        var aad: [header_length + aad_label.len]u8 = undefined;
        @memcpy(aad[0..header_length], &header);
        @memcpy(aad[header_length..], aad_label);

        var kek = try PassphraseKdf.derive(allocator, passphrase, &salt, params);
        defer secureZero(&kek);

        const sealed = try SealedRecord.sealAlloc(allocator, &kek, &aad, data_key);
        defer allocator.free(sealed);
        const out = try allocator.alloc(u8, header_length + sealed.len);
        errdefer allocator.free(out);
        @memcpy(out[0..header_length], &header);
        @memcpy(out[header_length..], sealed);
        return out;
    }

    pub fn unwrap(allocator: std.mem.Allocator, passphrase: []const u8, blob: []const u8) ![32]u8 {
        if (blob.len < header_length + SealedRecord.header_len + AeadBox.tag_length) return error.InvalidKeyEnvelope;
        if (!std.mem.eql(u8, blob[0..magic.len], magic) or blob[5] != version) return error.InvalidKeyEnvelope;

        const lanes = try readU32Le(blob[14..18]);
        if (lanes > std.math.maxInt(u24)) return error.InvalidKeyEnvelope;
        const params = PassphraseKdf.Params{
            .memory_kib = try readU32Le(blob[6..10]),
            .time_cost = try readU32Le(blob[10..14]),
            .lanes = @intCast(lanes),
        };
        var kek = try PassphraseKdf.derive(allocator, passphrase, blob[18..header_length], params);
        defer secureZero(&kek);
        var aad: [header_length + aad_label.len]u8 = undefined;
        @memcpy(aad[0..header_length], blob[0..header_length]);
        @memcpy(aad[header_length..], aad_label);
        const raw = try SealedRecord.openAlloc(allocator, &kek, &aad, blob[header_length..]);
        defer {
            secureZero(raw);
            allocator.free(raw);
        }
        if (raw.len != 32) return error.InvalidKeyEnvelope;
        var out: [32]u8 = undefined;
        @memcpy(&out, raw);
        return out;
    }

    /// Rewrap one authenticated NKEY4 data key. The caller owns replacement
    /// and backup policy for its containing encrypted-data store.
    pub fn migrateNkey4Alloc(allocator: std.mem.Allocator, old_kek: *const [32]u8, old_blob: []const u8, new_passphrase: []const u8) ![]u8 {
        var data_key = try KeyEnvelope.unwrap(allocator, old_kek, old_blob);
        defer secureZero(&data_key);
        return wrapAlloc(allocator, new_passphrase, &data_key);
    }

    /// Convenience migration for legacy passphrase-derived NKEY4 keys.
    pub fn migrateNkey4PassphraseAlloc(allocator: std.mem.Allocator, old_passphrase: []const u8, old_salt: []const u8, old_rounds: u32, old_blob: []const u8, new_passphrase: []const u8) ![]u8 {
        var old_kek = try PassphraseKdf.derivePbkdf2Legacy(old_passphrase, old_salt, old_rounds);
        defer secureZero(&old_kek);
        return migrateNkey4Alloc(allocator, &old_kek, old_blob, new_passphrase);
    }
};

pub const PassphraseKdf = struct {
    pub const Params = struct {
        time_cost: u32 = 3,
        memory_kib: u32 = 64 * 1024,
        lanes: u24 = 1,
    };

    pub const default_params = Params{};
    pub const min_memory_kib: u32 = 19 * 1024;
    pub const max_memory_kib: u32 = 256 * 1024;
    pub const max_time_cost: u32 = 10;
    pub const max_lanes: u24 = 4;

    /// Argon2id v1.3 key derivation. Parameter bounds are checked before the
    /// allocator is asked for memory so a corrupt envelope cannot request an
    /// unbounded allocation or computation.
    pub fn derive(allocator: std.mem.Allocator, passphrase: []const u8, salt: []const u8, params: Params) ![32]u8 {
        if (passphrase.len < 8) return error.WeakPassphrase;
        if (salt.len < 16) return error.WeakSalt;
        if (params.time_cost < 2 or params.time_cost > max_time_cost) return error.WeakParameters;
        if (params.memory_kib < min_memory_kib or params.memory_kib > max_memory_kib) return error.WeakParameters;
        if (params.lanes < 1 or params.lanes > max_lanes) return error.WeakParameters;
        if (params.memory_kib < 8 * params.lanes) return error.WeakParameters;
        var out: [32]u8 = undefined;
        errdefer secureZero(&out);
        try std.crypto.pwhash.argon2.kdf(allocator, &out, passphrase, salt, .{
            .t = params.time_cost,
            .m = params.memory_kib,
            .p = params.lanes,
        }, .argon2id);
        return out;
    }

    /// Legacy NKEY4-compatible PBKDF2 derivation. New records must use
    /// derive()/Argon2id; retain this only to open and migrate older records.
    pub fn derivePbkdf2Legacy(passphrase: []const u8, salt: []const u8, rounds: u32) ![32]u8 {
        if (passphrase.len < 8) return error.WeakPassphrase;
        if (salt.len < 16) return error.WeakSalt;
        if (rounds < 100_000) return error.WeakParameters;
        var out: [32]u8 = undefined;
        try std.crypto.pwhash.pbkdf2(&out, passphrase, salt, rounds, std.crypto.auth.hmac.sha2.HmacSha256);
        return out;
    }
};

// ----------------------------------------------------------------------------
// GGUF tensor plan: verifies element counts and byte ranges before touching data.
// ----------------------------------------------------------------------------

pub const TensorPlan = struct {
    name_hash: [32]u8,
    dims: [8]u64,
    n_dims: u32,
    ggml_type: GgmlType,
    offset: u64,
    elements: u64,
    bytes: u64,

    pub fn fromInfo(info: Gguf.TensorInfo, name: []const u8) !TensorPlan {
        var elems: u64 = 1;
        var i: usize = 0;
        while (i < info.n_dims) : (i += 1) elems = try std.math.mul(u64, elems, info.dimensions[i]);
        const gt: GgmlType = @enumFromInt(info.ggml_type);
        const qi = quantInfo(gt) orelse return error.UnsupportedTensorType;
        if (elems % qi.block_values != 0) return error.InvalidTensorShape;
        const blocks = elems / qi.block_values;
        const bytes = try std.math.mul(u64, blocks, qi.block_bytes);
        return .{
            .name_hash = sha256(name),
            .dims = info.dimensions,
            .n_dims = info.n_dims,
            .ggml_type = gt,
            .offset = info.offset,
            .elements = elems,
            .bytes = bytes,
        };
    }

    pub fn validateRange(self: TensorPlan, data_start: u64, file_size: u64) !void {
        const absolute = try std.math.add(u64, data_start, self.offset);
        const end = try std.math.add(u64, absolute, self.bytes);
        if (end > file_size) return error.TensorOutOfRange;
    }
};

pub const TensorName = struct {
    pub fn block(buf: []u8, layer: usize, suffix: []const u8) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.{s}", .{ layer, suffix });
    }

    pub const attn_norm = "attn_norm.weight";
    pub const attn_q = "attn_q.weight";
    pub const attn_k = "attn_k.weight";
    pub const attn_v = "attn_v.weight";
    pub const attn_output = "attn_output.weight";
    pub const ffn_norm = "ffn_norm.weight";
    pub const ffn_gate = "ffn_gate.weight";
    pub const ffn_up = "ffn_up.weight";
    pub const ffn_down = "ffn_down.weight";
};

pub const LlamaWeightsView = struct {
    token_embedding: ?TensorPlan = null,
    output_norm: ?TensorPlan = null,
    output: ?TensorPlan = null,

    pub fn complete(self: LlamaWeightsView) bool {
        return self.token_embedding != null and self.output_norm != null and self.output != null;
    }
};

pub const Linear = struct {
    pub fn matmulF32(out: []f32, input: []const f32, weights: []const f32, rows: usize, cols: usize) !void {
        const elements = std.math.mul(usize, rows, cols) catch return error.TensorTooLarge;
        if (input.len != cols or out.len != rows or weights.len != elements) return error.ShapeMismatch;
        var r: usize = 0;
        while (r < rows) : (r += 1) {
            var acc: f32 = 0;
            const row = weights[r * cols .. (r + 1) * cols];
            for (row, input) |w, x| acc += w * x;
            out[r] = acc;
        }
    }
};

pub const TransformerScratch = struct {
    allocator: std.mem.Allocator,
    hidden: []f32,
    normed: []f32,
    q: []f32,
    k: []f32,
    v: []f32,
    attn: []f32,
    gate: []f32,
    up: []f32,
    ff: []f32,
    scores: []f32,

    pub fn init(allocator: std.mem.Allocator, cfg: LlamaConfig) !TransformerScratch {
        try cfg.validate();
        const hidden = try allocator.alloc(f32, cfg.hidden_size);
        errdefer allocator.free(hidden);
        const normed = try allocator.alloc(f32, cfg.hidden_size);
        errdefer allocator.free(normed);
        const q = try allocator.alloc(f32, cfg.hidden_size);
        errdefer allocator.free(q);
        const kv_dim = (cfg.hidden_size / cfg.head_count) * cfg.kv_head_count;
        const k = try allocator.alloc(f32, kv_dim);
        errdefer allocator.free(k);
        const v = try allocator.alloc(f32, kv_dim);
        errdefer allocator.free(v);
        const attn = try allocator.alloc(f32, cfg.hidden_size);
        errdefer allocator.free(attn);
        const gate = try allocator.alloc(f32, cfg.intermediate_size);
        errdefer allocator.free(gate);
        const up = try allocator.alloc(f32, cfg.intermediate_size);
        errdefer allocator.free(up);
        const ff = try allocator.alloc(f32, cfg.intermediate_size);
        errdefer allocator.free(ff);
        const scores = try allocator.alloc(f32, cfg.context_length);
        errdefer allocator.free(scores);
        return .{ .allocator = allocator, .hidden = hidden, .normed = normed, .q = q, .k = k, .v = v, .attn = attn, .gate = gate, .up = up, .ff = ff, .scores = scores };
    }

    pub fn deinit(self: *TransformerScratch) void {
        const fields = [_][]f32{ self.hidden, self.normed, self.q, self.k, self.v, self.attn, self.gate, self.up, self.ff, self.scores };
        for (fields) |f| {
            @memset(f, 0);
            self.allocator.free(f);
        }
        self.* = undefined;
    }
};

pub const LlamaLayerF32 = struct {
    attn_norm: []const f32,
    wq: []const f32,
    wk: []const f32,
    wv: []const f32,
    wo: []const f32,
    ffn_norm: []const f32,
    w_gate: []const f32,
    w_up: []const f32,
    w_down: []const f32,

    pub fn forward(self: LlamaLayerF32, cfg: LlamaConfig, layer_index: usize, position: usize, cache: *KvCache, s: *TransformerScratch) !void {
        const hd = try cfg.headDim();
        try rmsNorm(s.normed, s.hidden, self.attn_norm, cfg.rms_epsilon);
        try Linear.matmulF32(s.q, s.normed, self.wq, cfg.hidden_size, cfg.hidden_size);
        const kv_dim = hd * cfg.kv_head_count;
        try Linear.matmulF32(s.k, s.normed, self.wk, kv_dim, cfg.hidden_size);
        try Linear.matmulF32(s.v, s.normed, self.wv, kv_dim, cfg.hidden_size);

        var h: usize = 0;
        while (h < cfg.head_count) : (h += 1) {
            const qh = s.q[h * hd .. (h + 1) * hd];
            try Rope.apply(qh, position, cfg.rope_theta);
        }
        h = 0;
        while (h < cfg.kv_head_count) : (h += 1) {
            const kh = s.k[h * hd .. (h + 1) * hd];
            try Rope.apply(kh, position, cfg.rope_theta);
            const vh = s.v[h * hd .. (h + 1) * hd];
            try cache.put(layer_index, position, h, kh, vh);
        }

        const group = cfg.head_count / cfg.kv_head_count;
        h = 0;
        while (h < cfg.head_count) : (h += 1) {
            const kvh = h / group;
            const qh = s.q[h * hd .. (h + 1) * hd];
            const oh = s.attn[h * hd .. (h + 1) * hd];
            try Attention.singleHead(oh, s.scores, qh, cache.*, layer_index, kvh, position);
        }

        try Linear.matmulF32(s.q, s.attn, self.wo, cfg.hidden_size, cfg.hidden_size);
        for (s.hidden, s.q) |*x, y| x.* += y;
        try rmsNorm(s.normed, s.hidden, self.ffn_norm, cfg.rms_epsilon);
        try Linear.matmulF32(s.gate, s.normed, self.w_gate, cfg.intermediate_size, cfg.hidden_size);
        try Linear.matmulF32(s.up, s.normed, self.w_up, cfg.intermediate_size, cfg.hidden_size);
        try swiglu(s.ff, s.gate, s.up);
        // Reuse q as hidden-size output of down projection.
        try Linear.matmulF32(s.q, s.ff, self.w_down, cfg.hidden_size, cfg.intermediate_size);
        for (s.hidden, s.q) |*x, y| x.* += y;
    }
};

// ----------------------------------------------------------------------------
// Road scanner prompt data. This ports the data-contract but leaves sensors to
// explicit caller input so the inference engine does not claim mystical access.
// ----------------------------------------------------------------------------

pub const RoadScannerInput = struct {
    road_name: []const u8,
    direction: []const u8,
    surface: []const u8,
    weather: []const u8,
    visibility: []const u8,
    traffic: []const u8,
    hazards: []const u8,
    notes: []const u8,
};

pub const RoadScanner = struct {
    pub const RiskLevel = enum { low, medium, high };

    pub fn firstRiskLevel(text: []const u8) RiskLevel {
        const labels = [_]struct { text: []const u8, level: RiskLevel }{
            .{ .text = "low", .level = .low },
            .{ .text = "medium", .level = .medium },
            .{ .text = "high", .level = .high },
        };
        var i: usize = 0;
        while (i < text.len) : (i += 1) {
            for (labels) |label| {
                if (i + label.text.len <= text.len and std.ascii.eqlIgnoreCase(text[i .. i + label.text.len], label.text)) {
                    const left_ok = i == 0 or !std.ascii.isAlphanumeric(text[i - 1]);
                    const end = i + label.text.len;
                    const right_ok = end == text.len or !std.ascii.isAlphanumeric(text[end]);
                    if (left_ok and right_ok) return label.level;
                }
            }
        }
        return .medium;
    }

    pub fn buildPrompt(allocator: std.mem.Allocator, in: RoadScannerInput, metrics: ?SystemMetrics) ![]u8 {
        var list = std.ArrayList(u8).empty;
        defer list.deinit(allocator);
        try list.appendSlice(allocator, "You are a road-condition analysis engine. Report observable risk, uncertainty, and recommended caution.\n");
        const pairs = [_][2][]const u8{
            .{ "road", in.road_name },  .{ "direction", in.direction },   .{ "surface", in.surface },
            .{ "weather", in.weather }, .{ "visibility", in.visibility }, .{ "traffic", in.traffic },
            .{ "hazards", in.hazards }, .{ "notes", in.notes },
        };
        for (pairs) |p| {
            try list.appendSlice(allocator, p[0]);
            try list.appendSlice(allocator, ": ");
            try list.appendSlice(allocator, p[1]);
            try list.append(allocator, '\n');
        }
        if (metrics) |m| {
            var buf: [256]u8 = undefined;
            const line = try std.fmt.bufPrint(&buf, "system_entropy_modifier={d:.4}\n", .{EntropyScore.normalized(m)});
            try list.appendSlice(allocator, line);
        }
        return try list.toOwnedSlice(allocator);
    }
};

pub const TokenHistory = struct {
    allocator: std.mem.Allocator,
    items: []u32,
    len: usize = 0,

    pub fn init(allocator: std.mem.Allocator, capacity: usize) !TokenHistory {
        return .{ .allocator = allocator, .items = try allocator.alloc(u32, capacity) };
    }

    pub fn deinit(self: *TokenHistory) void {
        @memset(self.items, 0);
        self.allocator.free(self.items);
        self.* = undefined;
    }

    pub fn push(self: *TokenHistory, tok: u32) void {
        if (self.items.len == 0) return;
        if (self.len < self.items.len) {
            self.items[self.len] = tok;
            self.len += 1;
            return;
        }
        var i: usize = 1;
        while (i < self.items.len) : (i += 1) self.items[i - 1] = self.items[i];
        self.items[self.items.len - 1] = tok;
    }

    pub fn slice(self: TokenHistory) []const u32 {
        return self.items[0..self.len];
    }
};

pub const GenerationConfig = struct {
    max_tokens: usize = 256,
    temperature: f32 = 0.8,
    top_k: usize = 40,
    top_p: f32 = 0.95,
    repeat_penalty: f32 = 1.05,
    seed: u64 = 0x4e415a41,

    pub fn validate(self: GenerationConfig) !void {
        if (self.max_tokens == 0 or self.max_tokens > 1_000_000) return error.InvalidGenerationConfig;
        if (self.temperature < 0 or self.temperature > 10) return error.InvalidGenerationConfig;
        if (self.top_p <= 0 or self.top_p > 1) return error.InvalidGenerationConfig;
        if (self.repeat_penalty <= 0) return error.InvalidGenerationConfig;
    }
};

// ----------------------------------------------------------------------------
// Pure-Zig incremental UTF-8 validator used for generated token fragments.
// ----------------------------------------------------------------------------

pub const Utf8Validator = struct {
    needed: u3 = 0,
    min: u8 = 0x80,
    max: u8 = 0xbf,

    pub fn reset(self: *Utf8Validator) void {
        self.* = .{};
    }

    pub fn feed(self: *Utf8Validator, bytes: []const u8) bool {
        for (bytes) |b| {
            if (self.needed == 0) {
                if (b <= 0x7f) continue;
                if (b >= 0xc2 and b <= 0xdf) {
                    self.needed = 1;
                    self.min = 0x80;
                    self.max = 0xbf;
                    continue;
                }
                if (b >= 0xe0 and b <= 0xef) {
                    self.needed = 2;
                    self.min = if (b == 0xe0) 0xa0 else 0x80;
                    self.max = if (b == 0xed) 0x9f else 0xbf;
                    continue;
                }
                if (b >= 0xf0 and b <= 0xf4) {
                    self.needed = 3;
                    self.min = if (b == 0xf0) 0x90 else 0x80;
                    self.max = if (b == 0xf4) 0x8f else 0xbf;
                    continue;
                }
                return false;
            }
            if (b < self.min or b > self.max) return false;
            self.needed -= 1;
            self.min = 0x80;
            self.max = 0xbf;
        }
        return true;
    }

    pub fn complete(self: Utf8Validator) bool {
        return self.needed == 0;
    }
};

test "sealed record roundtrip" {
    const allocator = std.testing.allocator;
    const key = [_]u8{0x42} ** 32;
    const blob = try SealedRecord.sealAlloc(allocator, &key, "aad", "hello quantum-resistant-ish world");
    defer allocator.free(blob);
    const clear = try SealedRecord.openAlloc(allocator, &key, "aad", blob);
    defer allocator.free(clear);
    try std.testing.expectEqualStrings("hello quantum-resistant-ish world", clear);

    blob[blob.len - 1] ^= 1;
    try std.testing.expectError(error.AuthenticationFailed, SealedRecord.openAlloc(allocator, &key, "aad", blob));
}

test "AES-256-GCM rejects modified ciphertext and AAD" {
    const key = [_]u8{0x11} ** 32;
    const nonce = [_]u8{0x22} ** AeadBox.nonce_length;
    const plain = "naza authenticated record";
    var cipher: [plain.len]u8 = undefined;
    var tag: [AeadBox.tag_length]u8 = undefined;
    try AeadBox.seal(&cipher, &tag, plain, "naza/aad/v1", &nonce, &key);
    var recovered: [plain.len]u8 = undefined;
    try AeadBox.open(&recovered, &cipher, &tag, "naza/aad/v1", &nonce, &key);
    try std.testing.expectEqualSlices(u8, plain, &recovered);
    try std.testing.expectError(error.AuthenticationFailed, AeadBox.open(&recovered, &cipher, &tag, "naza/wrong-aad", &nonce, &key));
    var wrong_key = key;
    wrong_key[0] ^= 1;
    try std.testing.expectError(error.AuthenticationFailed, AeadBox.open(&recovered, &cipher, &tag, "naza/aad/v1", &nonce, &wrong_key));
    cipher[0] ^= 1;
    try std.testing.expectError(error.AuthenticationFailed, AeadBox.open(&recovered, &cipher, &tag, "naza/aad/v1", &nonce, &key));
}

test "file mac changes with payload" {
    const key = [_]u8{7} ** 32;
    const a = FileMac.computeBytes(&key, "a");
    const b = FileMac.computeBytes(&key, "b");
    try std.testing.expect(!ctEqual(&a, &b));
}

test "NKEY4 envelope is bound to its key and framing" {
    const allocator = std.testing.allocator;
    const kek = [_]u8{0x31} ** 32;
    const data_key = [_]u8{0x72} ** 32;
    var blob = try KeyEnvelope.wrapAlloc(allocator, &kek, &data_key);
    defer allocator.free(blob);
    const opened = try KeyEnvelope.unwrap(allocator, &kek, blob);
    try std.testing.expectEqualSlices(u8, &data_key, &opened);

    var wrong_kek = kek;
    wrong_kek[7] ^= 0x40;
    try std.testing.expectError(error.AuthenticationFailed, KeyEnvelope.unwrap(allocator, &wrong_kek, blob));

    blob[0] ^= 1;
    try std.testing.expectError(error.InvalidKeyEnvelope, KeyEnvelope.unwrap(allocator, &kek, blob));
}

test "Argon2id matches RFC 9106 section 5.3 vector" {
    const password = [_]u8{0x01} ** 32;
    const salt = [_]u8{0x02} ** 16;
    const secret = [_]u8{0x03} ** 8;
    const associated_data = [_]u8{0x04} ** 12;
    var got: [32]u8 = undefined;
    try std.crypto.pwhash.argon2.kdf(std.testing.allocator, &got, &password, &salt, .{
        .t = 3,
        .m = 32,
        .p = 4,
        .secret = &secret,
        .ad = &associated_data,
    }, .argon2id);
    var expected: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&expected, "0d640df58d78766c08c037a34a8b53c9d01ef0452d75b65eb52520e96b01e659");
    try std.testing.expectEqualSlices(u8, &expected, &got);
}

test "Keystore RSA verifier accepts OpenSSL signature and rejects tampering" {
    var modulus: [256]u8 = undefined;
    _ = try std.fmt.hexToBytes(&modulus, "");
    var signature: [256]u8 = undefined;
    _ = try std.fmt.hexToBytes(&signature, "");
    try AndroidKeystoreGate.verifySignature("", "10001", "NAZA-GATE-TEST-VECTOR", &signature);
    signature[0] ^= 1;
    try std.testing.expectError(error.KeystoreProofInvalid, AndroidKeystoreGate.verifySignature("", "10001", "NAZA-GATE-TEST-VECTOR", &signature));
}

test "NKEY4 passphrase key migrates into authenticated NKEY5 Argon2id envelope" {
    const allocator = std.testing.allocator;
    const old_passphrase = "old NKEY4 passphrase";
    const old_salt = "nkey4-test-salt!";
    const new_passphrase = "new NKEY5 passphrase";
    const data_key = [_]u8{0xa7} ** 32;

    var old_kek = try PassphraseKdf.derivePbkdf2Legacy(old_passphrase, old_salt, 100_000);
    defer secureZero(&old_kek);
    const old_blob = try KeyEnvelope.wrapAlloc(allocator, &old_kek, &data_key);
    defer allocator.free(old_blob);

    const upgraded = try PasswordKeyEnvelope.migrateNkey4PassphraseAlloc(allocator, old_passphrase, old_salt, 100_000, old_blob, new_passphrase);
    defer allocator.free(upgraded);
    const opened = try PasswordKeyEnvelope.unwrap(allocator, new_passphrase, upgraded);
    try std.testing.expectEqualSlices(u8, &data_key, &opened);
    try std.testing.expectError(error.AuthenticationFailed, PasswordKeyEnvelope.unwrap(allocator, "wrong passphrase", upgraded));

    var oversized = try allocator.dupe(u8, upgraded);
    defer allocator.free(oversized);
    try writeU32Le(oversized[6..10], PassphraseKdf.max_memory_kib + 1);
    try std.testing.expectError(error.WeakParameters, PasswordKeyEnvelope.unwrap(allocator, new_passphrase, oversized));
}

test "utf8 streaming validator" {
    var v = Utf8Validator{};
    try std.testing.expect(v.feed("hello"));
    try std.testing.expect(v.feed("\xF0\x9F"));
    try std.testing.expect(v.feed("\x98\x80"));
    try std.testing.expect(v.complete());
}

// ============================================================================
// EXPANSION 0.3c — ML-DSA arithmetic, hash-based signature implementation,
// code-based polynomial implementation and Falcon-style FFT utilities.
// ============================================================================

pub const MlDsa = struct {
    pub const q: i32 = 8_380_417;
    pub const n: usize = 256;
    pub const N: usize = n;
    pub const D: u5 = 13;
    pub const qinv: i64 = 58_728_449;
    pub const mont: i32 = -4_186_625;
    pub const Poly = [n]i32;

    pub const Params = struct {
        k: usize,
        l: usize,
        eta: i32,
        tau: usize,
        beta: i32,
        gamma1: i32,
        gamma2: i32,
        omega: usize,
    };

    pub const ml_dsa_44 = Params{ .k = 4, .l = 4, .eta = 2, .tau = 39, .beta = 78, .gamma1 = 1 << 17, .gamma2 = (q - 1) / 88, .omega = 80 };
    pub const ml_dsa_65 = Params{ .k = 6, .l = 5, .eta = 4, .tau = 49, .beta = 196, .gamma1 = 1 << 19, .gamma2 = (q - 1) / 32, .omega = 55 };
    pub const ml_dsa_87 = Params{ .k = 8, .l = 7, .eta = 2, .tau = 60, .beta = 120, .gamma1 = 1 << 19, .gamma2 = (q - 1) / 32, .omega = 75 };

    pub const zetas = [256]i32{
        0,        25847,    -2608894, -518909,  237124,   -777960,  -876248,  466468,
        1826347,  2353451,  -359251,  -2091905, 3119733,  -2884855, 3111497,  2680103,
        2725464,  1024112,  -1079900, 3585928,  -549488,  -1119584, 2619752,  -2108549,
        -2118186, -3859737, -1399561, -3277672, 1757237,  -19422,   4010497,  280005,
        2706023,  95776,    3077325,  3530437,  -1661693, -3592148, -2537516, 3915439,
        -3861115, -3043716, 3574422,  -2867647, 3539968,  -300467,  2348700,  -539299,
        -1699267, -1643818, 3505694,  -3821735, 3507263,  -2140649, -1600420, 3699596,
        811944,   531354,   954230,   3881043,  3900724,  -2556880, 2071892,  -2797779,
        -3930395, -1528703, -3677745, -3041255, -1452451, 3475950,  2176455,  -1585221,
        -1257611, 1939314,  -4083598, -1000202, -3190144, -3157330, -3632928, 126922,
        3412210,  -983419,  2147896,  2715295,  -2967645, -3693493, -411027,  -2477047,
        -671102,  -1228525, -22981,   -1308169, -381987,  1349076,  1852771,  -1430430,
        -3343383, 264944,   508951,   3097992,  44288,    -1100098, 904516,   3958618,
        -3724342, -8578,    1653064,  -3249728, 2389356,  -210977,  759969,   -1316856,
        189548,   -3553272, 3159746,  -1851402, -2409325, -177440,  1315589,  1341330,
        1285669,  -1584928, -812732,  -1439742, -3019102, -3881060, -3628969, 3839961,
        2091667,  3407706,  2316500,  3817976,  -3342478, 2244091,  -2446433, -3562462,
        266997,   2434439,  -1235728, 3513181,  -3520352, -3759364, -1197226, -3193378,
        900702,   1859098,  909542,   819034,   495491,   -1613174, -43260,   -522500,
        -655327,  -3122442, 2031748,  3207046,  -3556995, -525098,  -768622,  -3595838,
        342297,   286988,   -2437823, 4108315,  3437287,  -3342277, 1735879,  203044,
        2842341,  2691481,  -2590150, 1265009,  4055324,  1247620,  2486353,  1595974,
        -3767016, 1250494,  2635921,  -3548272, -2994039, 1869119,  1903435,  -1050970,
        -1333058, 1237275,  -3318210, -1430225, -451100,  1312455,  3306115,  -1962642,
        -1279661, 1917081,  -2546312, -1374803, 1500165,  777191,   2235880,  3406031,
        -542412,  -2831860, -1671176, -1846953, -2584293, -3724270, 594136,   -3776993,
        -2013608, 2432395,  2454455,  -164721,  1957272,  3369112,  185531,   -1207385,
        -3183426, 162844,   1616392,  3014001,  810149,   1652634,  -3694233, -1799107,
        -3038916, 3523897,  3866901,  269760,   2213111,  -975884,  1717735,  472078,
        -426683,  1723600,  -1803090, 1910376,  -1667432, -1104333, -260646,  -3833893,
        -2939036, -2235985, -420899,  -2286327, 183443,   -976891,  1612842,  -3545687,
        -554416,  3919660,  -48306,   -1362209, 3937738,  1400424,  -846154,  1976782,
    };

    pub inline fn montgomeryReduce(a: i64) i32 {
        const low: i32 = @truncate(a);
        const t: i32 = @truncate(@as(i64, low) * qinv);
        return @intCast((a - @as(i64, t) * q) >> 32);
    }

    pub inline fn reduce32(a: i32) i32 {
        const t = (a + (@as(i32, 1) << 22)) >> 23;
        return a - t * q;
    }

    pub inline fn caddq(a_in: i32) i32 {
        var a = a_in;
        a += (a >> 31) & q;
        return a;
    }

    pub inline fn freeze(a: i32) i32 {
        return caddq(reduce32(a));
    }

    pub fn ntt(a: *Poly) void {
        var k: usize = 0;
        var len: usize = 128;
        while (len > 0) : (len >>= 1) {
            var start: usize = 0;
            while (start < n) {
                k += 1;
                const zeta = zetas[k];
                var j = start;
                while (j < start + len) : (j += 1) {
                    const t = montgomeryReduce(@as(i64, zeta) * a[j + len]);
                    const x = a[j];
                    a[j + len] = x - t;
                    a[j] = x + t;
                }
                start += 2 * len;
            }
        }
    }

    pub fn invNttToMont(a: *Poly) void {
        var k: usize = 256;
        var len: usize = 1;
        while (len < n) : (len <<= 1) {
            var start: usize = 0;
            while (start < n) {
                k -= 1;
                const zeta = -zetas[k];
                var j = start;
                while (j < start + len) : (j += 1) {
                    const t = a[j];
                    a[j] = t + a[j + len];
                    a[j + len] = t - a[j + len];
                    a[j + len] = montgomeryReduce(@as(i64, zeta) * a[j + len]);
                }
                start += 2 * len;
            }
        }
        const f: i32 = 41978;
        for (a) |*x| x.* = montgomeryReduce(@as(i64, f) * x.*);
    }

    pub fn pointwiseMontgomery(r: *Poly, a: *const Poly, b: *const Poly) void {
        for (0..n) |i| r[i] = montgomeryReduce(@as(i64, a[i]) * b[i]);
    }

    pub fn add(r: *Poly, a: *const Poly, b: *const Poly) void {
        for (0..n) |i| r[i] = a[i] + b[i];
    }

    pub fn sub(r: *Poly, a: *const Poly, b: *const Poly) void {
        for (0..n) |i| r[i] = a[i] - b[i];
    }

    pub fn reduce(r: *Poly) void {
        for (r) |*x| x.* = reduce32(x.*);
    }
    pub fn cadd(r: *Poly) void {
        for (r) |*x| x.* = caddq(x.*);
    }

    pub fn power2round(a: i32) struct { hi: i32, lo: i32 } {
        const d: u5 = 13;
        const a1 = (a + ((@as(i32, 1) << d) / 2) - 1) >> d;
        const a0 = a - (a1 << d);
        return .{ .hi = a1, .lo = a0 };
    }

    pub fn decompose(a_in: i32, gamma2: i32) struct { hi: i32, lo: i32 } {
        const a = freeze(a_in);
        var a1: i32 = undefined;
        if (gamma2 == (q - 1) / 32) {
            a1 = (a + 127) >> 7;
            a1 = (a1 * 1025 + (@as(i32, 1) << 21)) >> 22;
            a1 &= 15;
        } else {
            a1 = (a + 127) >> 7;
            a1 = (a1 * 11275 + (@as(i32, 1) << 23)) >> 24;
            a1 ^= ((43 - a1) >> 31) & a1;
        }
        var a0 = a - a1 * 2 * gamma2;
        a0 -= (((q - 1) / 2 - a0) >> 31) & q;
        return .{ .hi = a1, .lo = a0 };
    }

    pub fn makeHint(a0: i32, a1: i32, gamma2: i32) u1 {
        return @intFromBool(a0 > gamma2 or a0 < -gamma2 or (a0 == -gamma2 and a1 != 0));
    }

    pub fn useHint(a: i32, hint: u1, gamma2: i32) i32 {
        const d = decompose(a, gamma2);
        if (hint == 0) return d.hi;
        if (gamma2 == (q - 1) / 32) {
            return if (d.lo > 0) (d.hi + 1) & 15 else (d.hi - 1) & 15;
        }
        if (d.lo > 0) return if (d.hi == 43) 0 else d.hi + 1;
        return if (d.hi == 0) 43 else d.hi - 1;
    }

    pub fn chknorm(a: *const Poly, bound: i32) bool {
        if (bound > (q - 1) / 8) return true;
        for (a) |x| {
            const t = if (x < 0) -x else x;
            if (t >= bound) return true;
        }
        return false;
    }

    pub fn challenge(seed: *const [32]u8, tau: usize) Poly {
        var out = [_]i32{0} ** n;
        var buf: [1024]u8 = undefined;
        shake256(seed, &buf);
        var signs = tryReadU64(buf[0..8]);
        var pos: usize = 8;
        var i: usize = n - tau;
        while (i < n) : (i += 1) {
            var b: usize = 256;
            while (b > i) {
                if (pos == buf.len) @panic("ML-DSA challenge XOF stream exhausted");
                b = buf[pos];
                pos += 1;
            }
            out[i] = out[b];
            out[b] = 1 - 2 * @as(i32, @intCast(signs & 1));
            signs >>= 1;
        }
        secureZero(&buf);
        return out;
    }

    fn tryReadU64(src: []const u8) u64 {
        return readU64Le(src) catch unreachable;
    }
};

pub const MlDsaMatrix = struct {
    pub const max_k = 8;
    pub const max_l = 7;
    pub const Matrix = [max_k][max_l]MlDsa.Poly;

    pub fn expand(out: *Matrix, rho: *const [32]u8, params: MlDsa.Params) !void {
        if (params.k > max_k or params.l > max_l) return error.InvalidParameterSet;
        var i: usize = 0;
        while (i < params.k) : (i += 1) {
            var j: usize = 0;
            while (j < params.l) : (j += 1) {
                var seed: [34]u8 = undefined;
                @memcpy(seed[0..32], rho);
                seed[32] = @intCast(j);
                seed[33] = @intCast(i);
                out[i][j] = uniform(&seed);
            }
        }
    }

    fn uniform(seed: *const [34]u8) MlDsa.Poly {
        var stream: [4096]u8 = undefined;
        shake128(seed, &stream);
        var p: MlDsa.Poly = undefined;
        var ctr: usize = 0;
        var pos: usize = 0;
        while (ctr < MlDsa.n and pos + 3 <= stream.len) : (pos += 3) {
            var t = @as(u32, stream[pos]) | (@as(u32, stream[pos + 1]) << 8) | (@as(u32, stream[pos + 2]) << 16);
            t &= 0x7fffff;
            if (t < MlDsa.q) {
                p[ctr] = @intCast(t);
                ctr += 1;
            }
        }
        if (ctr != MlDsa.n) @panic("ML-DSA rejection stream exhausted");
        return p;
    }
};

// ----------------------------------------------------------------------------
// SLH-DSA / SPHINCS+ style address and tweakable hash implementation.
// This provides the core hash-tree machinery; full FIPS 205 parameter sets are
// represented below but signing remains fail-closed until complete KAT parity.
// ----------------------------------------------------------------------------

pub const SlhDsa = struct {
    pub const Address = [8]u32;

    pub const Params = struct {
        n: usize,
        h: usize,
        d: usize,
        hp: usize,
        a: usize,
        k: usize,
        lg_w: usize,
        m: usize,
    };

    pub const sha2_128s = Params{ .n = 16, .h = 63, .d = 7, .hp = 9, .a = 12, .k = 14, .lg_w = 4, .m = 30 };
    pub const sha2_128f = Params{ .n = 16, .h = 66, .d = 22, .hp = 3, .a = 6, .k = 33, .lg_w = 4, .m = 34 };
    pub const shake_128s = sha2_128s;
    pub const shake_128f = sha2_128f;
    pub const sha2_192s = Params{ .n = 24, .h = 63, .d = 7, .hp = 9, .a = 14, .k = 17, .lg_w = 4, .m = 39 };
    pub const sha2_192f = Params{ .n = 24, .h = 66, .d = 22, .hp = 3, .a = 8, .k = 33, .lg_w = 4, .m = 42 };
    pub const shake_192s = sha2_192s;
    pub const shake_192f = sha2_192f;
    pub const sha2_256s = Params{ .n = 32, .h = 64, .d = 8, .hp = 8, .a = 14, .k = 22, .lg_w = 4, .m = 47 };
    pub const sha2_256f = Params{ .n = 32, .h = 68, .d = 17, .hp = 4, .a = 9, .k = 35, .lg_w = 4, .m = 49 };
    pub const shake_256s = sha2_256s;
    pub const shake_256f = sha2_256f;

    pub fn setLayer(a: *Address, layer: u32) void {
        a[0] = layer;
    }
    pub fn setTree(a: *Address, tree: u64) void {
        a[1] = 0;
        a[2] = @truncate(tree >> 32);
        a[3] = @truncate(tree);
    }
    pub fn setType(a: *Address, ty: u32) void {
        a[4] = ty;
    }
    pub fn setKeypair(a: *Address, kp: u32) void {
        a[5] = kp;
    }
    pub fn setChain(a: *Address, chain: u32) void {
        a[6] = chain;
    }
    pub fn setHash(a: *Address, hash: u32) void {
        a[7] = hash;
    }
    pub fn setTreeHeight(a: *Address, h: u32) void {
        a[6] = h;
    }
    pub fn setTreeIndex(a: *Address, idx: u32) void {
        a[7] = idx;
    }

    pub fn addressBytes(a: *const Address, out: *[32]u8) void {
        for (a, 0..) |v, i| writeU32Le(out[i * 4 .. i * 4 + 4], v) catch unreachable;
    }

    pub fn prfShake(out: []u8, sk_seed: []const u8, addr: *const Address) !void {
        if (out.len > 64) return error.OutputTooLong;
        var ab: [32]u8 = undefined;
        addressBytes(addr, &ab);
        var s = Keccak.Sponge.init(136, 0x1f);
        try s.update(sk_seed);
        try s.update(&ab);
        s.finalize();
        try s.squeeze(out);
    }

    pub fn thashShake(out: []u8, pub_seed: []const u8, addr: *const Address, input: []const u8) !void {
        if (out.len > 64) return error.OutputTooLong;
        var ab: [32]u8 = undefined;
        addressBytes(addr, &ab);
        var s = Keccak.Sponge.init(136, 0x1f);
        try s.update(pub_seed);
        try s.update(&ab);
        try s.update(input);
        s.finalize();
        try s.squeeze(out);
    }

    pub fn chainShake(out: []u8, input: []const u8, start: usize, steps: usize, pub_seed: []const u8, addr: *Address) !void {
        if (out.len != input.len or out.len == 0 or out.len > 64) return error.InvalidParameterSet;
        @memcpy(out, input);
        var i = start;
        while (i < start + steps and i < 16) : (i += 1) {
            setHash(addr, @intCast(i));
            var tmp: [64]u8 = undefined;
            try thashShake(tmp[0..out.len], pub_seed, addr, out);
            @memcpy(out, tmp[0..out.len]);
            secureZero(tmp[0..]);
        }
    }

    pub fn baseW(out: []u8, input: []const u8, lg_w: usize) !void {
        if (lg_w == 0 or lg_w > 8 or 8 % lg_w != 0) return error.InvalidParameterSet;
        var in_idx: usize = 0;
        var total: u16 = 0;
        var bits: usize = 0;
        for (out) |*o| {
            if (bits == 0) {
                if (in_idx >= input.len) return error.InputTooShort;
                total = input[in_idx];
                in_idx += 1;
                bits = 8;
            }
            bits -= lg_w;
            o.* = @truncate((total >> @intCast(bits)) & ((@as(u16, 1) << @intCast(lg_w)) - 1));
        }
    }

    pub fn merkleParentShake(out: []u8, left: []const u8, right: []const u8, pub_seed: []const u8, addr: *Address, height: u32, index: u32) !void {
        if (left.len != right.len or out.len != left.len or out.len > 32) return error.InvalidParameterSet;
        setTreeHeight(addr, height);
        setTreeIndex(addr, index);
        var pair: [64]u8 = undefined;
        @memcpy(pair[0..left.len], left);
        @memcpy(pair[left.len .. 2 * left.len], right);
        try thashShake(out, pub_seed, addr, pair[0 .. 2 * left.len]);
        secureZero(pair[0..]);
    }
};

pub const MerkleTree = struct {
    pub fn rootShake(allocator: std.mem.Allocator, leaves: []const u8, leaf_size: usize, pub_seed: []const u8, base_addr: SlhDsa.Address) ![]u8 {
        if (leaf_size == 0 or leaves.len == 0 or leaves.len % leaf_size != 0) return error.InvalidTree;
        var count = leaves.len / leaf_size;
        if ((count & (count - 1)) != 0) return error.InvalidTree;
        var current = try allocator.dupe(u8, leaves);
        errdefer allocator.free(current);
        var height: u32 = 0;
        var addr = base_addr;
        while (count > 1) {
            var i: usize = 0;
            while (i < count / 2) : (i += 1) {
                const left = current[(2 * i) * leaf_size .. (2 * i + 1) * leaf_size];
                const right = current[(2 * i + 1) * leaf_size .. (2 * i + 2) * leaf_size];
                var tmp: [64]u8 = undefined;
                try SlhDsa.merkleParentShake(tmp[0..leaf_size], left, right, pub_seed, &addr, height + 1, @intCast(i));
                @memcpy(current[i * leaf_size .. (i + 1) * leaf_size], tmp[0..leaf_size]);
            }
            count /= 2;
            height += 1;
        }
        const root = try allocator.dupe(u8, current[0..leaf_size]);
        secureZero(current);
        allocator.free(current);
        return root;
    }
};

pub const Xmss = struct {
    pub const Address = SlhDsa.Address;
    pub const WotsParams = struct { n: usize = 32, w: usize = 16, len1: usize = 64, len2: usize = 3, len: usize = 67 };

    pub fn wotsChecksum(msg_digits: []const u8, w: usize) u32 {
        var sum: u32 = 0;
        for (msg_digits) |d| sum += @intCast(w - 1 - d);
        return sum;
    }

    pub fn lTreeShake(allocator: std.mem.Allocator, public_key: []const u8, n: usize, pub_seed: []const u8, addr: Address) ![]u8 {
        if (n == 0 or public_key.len % n != 0) return error.InvalidParameterSet;
        var nodes = public_key.len / n;
        var buf = try allocator.dupe(u8, public_key);
        errdefer allocator.free(buf);
        var height: u32 = 0;
        var a = addr;
        while (nodes > 1) {
            var i: usize = 0;
            while (i < nodes / 2) : (i += 1) {
                var pair: [64]u8 = undefined;
                if (2 * n > pair.len) return error.InvalidParameterSet;
                @memcpy(pair[0..n], buf[(2 * i) * n .. (2 * i + 1) * n]);
                @memcpy(pair[n .. 2 * n], buf[(2 * i + 1) * n .. (2 * i + 2) * n]);
                SlhDsa.setTreeHeight(&a, height);
                SlhDsa.setTreeIndex(&a, @intCast(i));
                try SlhDsa.thashShake(buf[i * n .. (i + 1) * n], pub_seed, &a, pair[0 .. 2 * n]);
            }
            if ((nodes & 1) != 0) {
                @memcpy(buf[(nodes / 2) * n .. (nodes / 2 + 1) * n], buf[(nodes - 1) * n .. nodes * n]);
                nodes = nodes / 2 + 1;
            } else nodes /= 2;
            height += 1;
        }
        const out = try allocator.dupe(u8, buf[0..n]);
        secureZero(buf);
        allocator.free(buf);
        return out;
    }
};

// ----------------------------------------------------------------------------
// HQC / code-based dense GF(2) polynomial primitives.
// These are generic and deliberately slow portable operations.
// ----------------------------------------------------------------------------

pub const Gf2Poly = struct {
    pub fn wordsForBits(bits: usize) usize {
        return (bits + 63) / 64;
    }

    pub fn clear(a: []u64) void {
        @memset(a, 0);
    }

    pub fn get(a: []const u64, bit: usize) u1 {
        return @truncate((a[bit >> 6] >> @intCast(bit & 63)) & 1);
    }

    pub fn set(a: []u64, bit: usize, value: u1) void {
        const mask = @as(u64, 1) << @intCast(bit & 63);
        if (value == 1) a[bit >> 6] |= mask else a[bit >> 6] &= ~mask;
    }

    pub fn toggle(a: []u64, bit: usize) void {
        a[bit >> 6] ^= @as(u64, 1) << @intCast(bit & 63);
    }

    pub fn xor(r: []u64, a: []const u64, b: []const u64) !void {
        if (r.len != a.len or a.len != b.len) return error.LengthMismatch;
        for (r, a, b) |*x, y, z| x.* = y ^ z;
    }

    pub fn weight(a: []const u64) usize {
        var w: usize = 0;
        for (a) |x| w += @popCount(x);
        return w;
    }

    pub fn rotateXorMod(r: []u64, a: []const u64, shift: usize, nbits: usize) !void {
        if (r.len < wordsForBits(nbits) or a.len < wordsForBits(nbits)) return error.BufferTooSmall;
        var i: usize = 0;
        while (i < nbits) : (i += 1) {
            if (get(a, i) == 1) toggle(r, (i + shift) % nbits);
        }
    }

    pub fn mulMod(r: []u64, a: []const u64, b: []const u64, nbits: usize) !void {
        if (r.len < wordsForBits(nbits)) return error.BufferTooSmall;
        clear(r);
        var i: usize = 0;
        while (i < nbits) : (i += 1) if (get(b, i) == 1) try rotateXorMod(r, a, i, nbits);
        if ((nbits & 63) != 0) r[wordsForBits(nbits) - 1] &= (@as(u64, 1) << @intCast(nbits & 63)) - 1;
    }

    pub fn fromBytes(out: []u64, bytes: []const u8, nbits: usize) !void {
        if (out.len < wordsForBits(nbits)) return error.BufferTooSmall;
        clear(out);
        const take = @min(bytes.len, (nbits + 7) / 8);
        for (bytes[0..take], 0..) |b, i| {
            var j: usize = 0;
            while (j < 8 and i * 8 + j < nbits) : (j += 1) if (((b >> @intCast(j)) & 1) == 1) set(out, i * 8 + j, 1);
        }
    }

    pub fn toBytes(out: []u8, a: []const u64, nbits: usize) !void {
        const need = (nbits + 7) / 8;
        if (out.len < need) return error.BufferTooSmall;
        @memset(out[0..need], 0);
        var i: usize = 0;
        while (i < nbits) : (i += 1) {
            if (get(a, i) == 1) out[i >> 3] |= @as(u8, 1) << @intCast(i & 7);
        }
    }
};

pub const Hqc = struct {
    pub const Params = struct {
        n: usize,
        n1: usize,
        n2: usize,
        k: usize,
        delta: usize,
        w: usize,
        wr: usize,
        we: usize,
        security: usize,
    };

    // Parameter sizes retained for architectural planning; verify against the
    // final NIST HQC specification before enabling wire compatibility.
    pub const hqc_128 = Params{ .n = 17669, .n1 = 46, .n2 = 384, .k = 16, .delta = 15, .w = 66, .wr = 75, .we = 75, .security = 128 };
    pub const hqc_192 = Params{ .n = 35851, .n1 = 56, .n2 = 640, .k = 24, .delta = 16, .w = 100, .wr = 114, .we = 114, .security = 192 };
    pub const hqc_256 = Params{ .n = 57637, .n1 = 90, .n2 = 640, .k = 32, .delta = 29, .w = 131, .wr = 149, .we = 149, .security = 256 };

    pub fn sampleFixedWeight(out: []u64, nbits: usize, weight: usize, seed: []const u8) !void {
        if (weight > nbits or out.len < Gf2Poly.wordsForBits(nbits)) return error.InvalidParameterSet;
        Gf2Poly.clear(out);
        var stream: [8192]u8 = undefined;
        shake256(seed, &stream);
        var pos: usize = 0;
        var set_count: usize = 0;
        while (set_count < weight) {
            if (pos + 4 > stream.len) return error.RejectionStreamExhausted;
            const x = try readU32Le(stream[pos .. pos + 4]);
            pos += 4;
            const idx: usize = @intCast(@as(u64, x) % nbits);
            if (Gf2Poly.get(out, idx) == 0) {
                Gf2Poly.set(out, idx, 1);
                set_count += 1;
            }
        }
    }

    pub fn syndrome(out: []u64, h: []const u64, r: []const u64, e: []const u64, nbits: usize) !void {
        try Gf2Poly.mulMod(out, h, r, nbits);
        if (out.len != e.len) return error.LengthMismatch;
        for (out, e) |*x, y| x.* ^= y;
    }
};

// ----------------------------------------------------------------------------
// Falcon/FN-DSA floating FFT implementation core. This is not the discrete Gaussian
// sampler; it is the deterministic transform machinery needed underneath it.
// ----------------------------------------------------------------------------

pub const Complex64 = struct {
    re: f64,
    im: f64,

    pub fn add(a: Complex64, b: Complex64) Complex64 {
        return .{ .re = a.re + b.re, .im = a.im + b.im };
    }
    pub fn sub(a: Complex64, b: Complex64) Complex64 {
        return .{ .re = a.re - b.re, .im = a.im - b.im };
    }
    pub fn mul(a: Complex64, b: Complex64) Complex64 {
        return .{ .re = a.re * b.re - a.im * b.im, .im = a.re * b.im + a.im * b.re };
    }
    pub fn conj(a: Complex64) Complex64 {
        return .{ .re = a.re, .im = -a.im };
    }
    pub fn scale(a: Complex64, s: f64) Complex64 {
        return .{ .re = a.re * s, .im = a.im * s };
    }
    pub fn norm2(a: Complex64) f64 {
        return a.re * a.re + a.im * a.im;
    }
};

pub const Fft = struct {
    fn reverseBits(x_in: usize, bits: usize) usize {
        var x = x_in;
        var y: usize = 0;
        var i: usize = 0;
        while (i < bits) : (i += 1) {
            y = (y << 1) | (x & 1);
            x >>= 1;
        }
        return y;
    }

    pub fn transform(a: []Complex64, inverse: bool) !void {
        const n = a.len;
        if (n == 0 or (n & (n - 1)) != 0) return error.InvalidFftLength;
        const bits: usize = @intCast(@ctz(n));
        var i: usize = 0;
        while (i < n) : (i += 1) {
            const j = reverseBits(i, bits);
            if (j > i) {
                const t = a[i];
                a[i] = a[j];
                a[j] = t;
            }
        }
        var len: usize = 2;
        while (len <= n) : (len <<= 1) {
            const sign: f64 = if (inverse) 1.0 else -1.0;
            const angle = sign * 2.0 * std.math.pi / @as(f64, @floatFromInt(len));
            const wlen = Complex64{ .re = @cos(angle), .im = @sin(angle) };
            var base: usize = 0;
            while (base < n) : (base += len) {
                var w = Complex64{ .re = 1, .im = 0 };
                var j: usize = 0;
                while (j < len / 2) : (j += 1) {
                    const u = a[base + j];
                    const v = Complex64.mul(a[base + j + len / 2], w);
                    a[base + j] = Complex64.add(u, v);
                    a[base + j + len / 2] = Complex64.sub(u, v);
                    w = Complex64.mul(w, wlen);
                }
            }
        }
        if (inverse) {
            const inv = 1.0 / @as(f64, @floatFromInt(n));
            for (a) |*z| z.* = Complex64.scale(z.*, inv);
        }
    }

    pub fn negacyclicConvolution(allocator: std.mem.Allocator, out: []f64, a: []const f64, b: []const f64) !void {
        if (out.len != a.len or a.len != b.len or a.len == 0 or (a.len & (a.len - 1)) != 0) return error.ShapeMismatch;
        // Portable O(n^2) form is retained because Falcon correctness matters
        // more than premature floating FFT optimization in this checkpoint.
        @memset(out, 0);
        const n = a.len;
        var i: usize = 0;
        while (i < n) : (i += 1) {
            var j: usize = 0;
            while (j < n) : (j += 1) {
                const k = i + j;
                if (k < n) out[k] += a[i] * b[j] else out[k - n] -= a[i] * b[j];
            }
        }
        _ = allocator;
    }
};

pub const Falcon = struct {
    pub const Params = struct { logn: u4, n: usize, security: usize };
    pub const falcon_512 = Params{ .logn = 9, .n = 512, .security = 128 };
    pub const falcon_1024 = Params{ .logn = 10, .n = 1024, .security = 256 };

    pub fn gramSchmidtNorm(f: []const f64, g: []const f64) !f64 {
        if (f.len != g.len) return error.ShapeMismatch;
        var s: f64 = 0;
        for (f, g) |x, y| s += x * x + y * y;
        return @sqrt(s);
    }
};

// ----------------------------------------------------------------------------
// Stateful hash-signature metadata for LMS/HSS. Stateful signing is never
// silently exposed: callers must provide and persist a monotonically increasing
// leaf index transactionally.
// ----------------------------------------------------------------------------

pub const StatefulSigner = struct {
    max_index: u64,
    next_index: u64,

    pub fn init(tree_height: u6) !StatefulSigner {
        if (tree_height >= 63) return error.TreeTooTall;
        return .{ .max_index = (@as(u64, 1) << tree_height) - 1, .next_index = 0 };
    }

    pub fn reserve(self: *StatefulSigner) !u64 {
        if (self.next_index > self.max_index) return error.KeyExhausted;
        const i = self.next_index;
        self.next_index += 1;
        return i;
    }

    pub fn serialize(self: StatefulSigner, out: *[16]u8) void {
        writeU64Le(out[0..8], self.max_index) catch unreachable;
        writeU64Le(out[8..16], self.next_index) catch unreachable;
    }

    pub fn parse(src: *const [16]u8) !StatefulSigner {
        const max = try readU64Le(src[0..8]);
        const next = try readU64Le(src[8..16]);
        if (next > max + 1) return error.InvalidSignerState;
        return .{ .max_index = max, .next_index = next };
    }
};

// ----------------------------------------------------------------------------
// Hybrid secret combiner. Combines arbitrary independent lanes with explicit
// names and transcript binding, useful for classical+PQC transition modes.
// ----------------------------------------------------------------------------

pub const HybridLane = struct { name: []const u8, secret: []const u8 };

pub const HybridCombiner = struct {
    pub fn derive(allocator: std.mem.Allocator, lanes: []const HybridLane, transcript_hash: []const u8, out: []u8) !void {
        if (lanes.len < 2 or lanes.len > 16) return error.InvalidLaneCount;
        var extracted = std.ArrayList(u8).empty;
        defer {
            secureZero(extracted.items);
            extracted.deinit(allocator);
        }
        for (lanes, 0..) |lane, i| {
            if (lane.name.len == 0 or lane.secret.len == 0) return error.InvalidLane;
            var salt_h = std.crypto.hash.sha2.Sha512.init(.{});
            salt_h.update("NAZA/HYBRID/LANE-SALT\x00");
            salt_h.update(transcript_hash);
            var ib: [8]u8 = undefined;
            try writeU64Le(&ib, i);
            salt_h.update(&ib);
            salt_h.update(lane.name);
            var salt: [64]u8 = undefined;
            salt_h.final(&salt);
            var lane_out: [64]u8 = undefined;
            try hkdfSha512(lane.secret, &salt, lane.name, &lane_out);
            try extracted.appendSlice(allocator, &lane_out);
            secureZero(lane_out[0..]);
        }
        var root_salt = sha512(transcript_hash);
        defer secureZero(root_salt[0..]);
        try hkdfSha512(extracted.items, &root_salt, "NAZA/HYBRID/ROOT\x00", out);
    }
};

test "ML-DSA NTT zero stable" {
    var p = [_]i32{0} ** MlDsa.n;
    MlDsa.ntt(&p);
    MlDsa.invNttToMont(&p);
    for (p) |x| try std.testing.expectEqual(@as(i32, 0), x);
}

test "GF2 cyclic multiplication identity" {
    const nbits = 127;
    var a = [_]u64{0} ** 2;
    var one = [_]u64{0} ** 2;
    var r = [_]u64{0} ** 2;
    Gf2Poly.set(&a, 3, 1);
    Gf2Poly.set(&a, 126, 1);
    Gf2Poly.set(&one, 0, 1);
    try Gf2Poly.mulMod(&r, &a, &one, nbits);
    try std.testing.expectEqualSlices(u64, &a, &r);
}

test "FFT roundtrip" {
    var a = [_]Complex64{ .{ .re = 1, .im = 0 }, .{ .re = 2, .im = 1 }, .{ .re = -1, .im = 0.5 }, .{ .re = 4, .im = -2 } };
    const original = a;
    try Fft.transform(&a, false);
    try Fft.transform(&a, true);
    for (a, original) |x, y| {
        try std.testing.expectApproxEqAbs(y.re, x.re, 1e-9);
        try std.testing.expectApproxEqAbs(y.im, x.im, 1e-9);
    }
}

test "stateful signer never reuses index" {
    var s = try StatefulSigner.init(4);
    const a = try s.reserve();
    const b = try s.reserve();
    try std.testing.expectEqual(@as(u64, 0), a);
    try std.testing.expectEqual(@as(u64, 1), b);
}

// ============================================================================
// EXPANSION 0.3d — exact scalar Q3_K decode for the pinned GGUF, quantized
// matvec kernels, seekable GGUF index helpers, and generation runtime pieces.
// ============================================================================

pub const Q3KExact = struct {
    pub const block_values: usize = 256;
    pub const block_bytes: usize = 110;
    pub const hmask_offset: usize = 0;
    pub const hmask_bytes: usize = 32;
    pub const qs_offset: usize = 32;
    pub const qs_bytes: usize = 64;
    pub const scales_offset: usize = 96;
    pub const scales_bytes: usize = 12;
    pub const d_offset: usize = 108;

    fn scaleCode(scales: *const [12]u8, group: usize) i8 {
        const low: u8 = if (group < 8) scales[group] & 0x0f else scales[group - 8] >> 4;
        const hi: u8 = (scales[8 + (group & 3)] >> @intCast(2 * (group >> 2))) & 0x03;
        const code: i16 = @as(i16, low | (hi << 4)) - 32;
        return @intCast(code);
    }

    pub fn dequantBlock(out: *[block_values]f32, src: *const [block_bytes]u8) void {
        var scales: [12]u8 = undefined;
        @memcpy(&scales, src[scales_offset .. scales_offset + scales_bytes]);
        const d = f16ToF32(readU16Le(src[d_offset .. d_offset + 2]) catch unreachable);
        const hm = src[hmask_offset .. hmask_offset + hmask_bytes];
        const q = src[qs_offset .. qs_offset + qs_bytes];

        var m: u8 = 1;
        var group: usize = 0;
        var section: usize = 0;
        while (section < 2) : (section += 1) {
            const qbase = section * 32;
            var shift: u4 = 0;
            var j: usize = 0;
            while (j < 4) : (j += 1) {
                const dl = d * @as(f32, @floatFromInt(scaleCode(&scales, group)));
                var l: usize = 0;
                while (l < 16) : (l += 1) {
                    const lo: i16 = @intCast((q[qbase + l] >> @as(u3, @truncate(shift))) & 3);
                    const high_adjust: i16 = if ((hm[l] & m) != 0) 0 else 4;
                    out[section * 128 + j * 32 + l] = dl * @as(f32, @floatFromInt(lo - high_adjust));
                }
                group += 1;
                const dl2 = d * @as(f32, @floatFromInt(scaleCode(&scales, group)));
                l = 0;
                while (l < 16) : (l += 1) {
                    const lo: i16 = @intCast((q[qbase + 16 + l] >> @as(u3, @truncate(shift))) & 3);
                    const high_adjust: i16 = if ((hm[16 + l] & m) != 0) 0 else 4;
                    out[section * 128 + j * 32 + 16 + l] = dl2 * @as(f32, @floatFromInt(lo - high_adjust));
                }
                group += 1;
                shift += 2;
                m <<= 1;
            }
        }
    }

    pub fn dequantRow(out: []f32, src: []const u8) !void {
        if (out.len % block_values != 0) return error.InvalidQuantizedLength;
        if (src.len != (out.len / block_values) * block_bytes) return error.InvalidQuantizedLength;
        var block: usize = 0;
        while (block < out.len / block_values) : (block += 1) {
            var raw: [block_bytes]u8 = undefined;
            @memcpy(&raw, src[block * block_bytes .. (block + 1) * block_bytes]);
            var vals: [block_values]f32 = undefined;
            dequantBlock(&vals, &raw);
            @memcpy(out[block * block_values .. (block + 1) * block_values], &vals);
        }
    }

    pub fn dotRow(src: []const u8, x: []const f32) !f32 {
        if (x.len % block_values != 0 or src.len != (x.len / block_values) * block_bytes) return error.InvalidQuantizedLength;
        var sum: f32 = 0;
        var block: usize = 0;
        while (block < x.len / block_values) : (block += 1) {
            const raw = src[block * block_bytes .. (block + 1) * block_bytes];
            var scales: [12]u8 = undefined;
            @memcpy(&scales, raw[scales_offset .. scales_offset + scales_bytes]);
            const d = f16ToF32(readU16Le(raw[d_offset .. d_offset + 2]) catch unreachable);
            const hm = raw[hmask_offset .. hmask_offset + hmask_bytes];
            const q = raw[qs_offset .. qs_offset + qs_bytes];
            const xb = x[block * block_values .. (block + 1) * block_values];

            var section: usize = 0;
            while (section < 2) : (section += 1) {
                const qbase = section * 32;
                const xbase = section * 128;
                var shift: u3 = 0;
                var mask: u8 = @as(u8, 1) << @as(u3, @intCast(section * 4));
                var group: usize = 0;
                while (group < 8) : (group += 2) {
                    const dl0 = d * @as(f32, @floatFromInt(scaleCode(&scales, section * 8 + group)));
                    const dl1 = d * @as(f32, @floatFromInt(scaleCode(&scales, section * 8 + group + 1)));
                    var lane: usize = 0;
                    while (lane < 16) : (lane += 1) {
                        const low0: i16 = @intCast((q[qbase + lane] >> shift) & 3);
                        const low1: i16 = @intCast((q[qbase + 16 + lane] >> shift) & 3);
                        const high0: i16 = if ((hm[lane] & mask) != 0) 0 else 4;
                        const high1: i16 = if ((hm[16 + lane] & mask) != 0) 0 else 4;
                        sum += dl0 * @as(f32, @floatFromInt(low0 - high0)) * xb[xbase + group * 16 + lane];
                        sum += dl1 * @as(f32, @floatFromInt(low1 - high1)) * xb[xbase + group * 16 + 16 + lane];
                    }
                    shift +%= 2;
                    mask <<= 1;
                }
            }
        }
        return sum;
    }

    pub fn matvec(out: []f32, weights: []const u8, x: []const f32, rows: usize, cols: usize) !void {
        if (out.len != rows or x.len != cols or cols % block_values != 0) return error.ShapeMismatch;
        const row_bytes = (cols / block_values) * block_bytes;
        const total_bytes = std.math.mul(usize, rows, row_bytes) catch return error.TensorTooLarge;
        if (weights.len != total_bytes) return error.InvalidQuantizedLength;
        var r: usize = 0;
        while (r < rows) : (r += 1) out[r] = try dotRow(weights[r * row_bytes .. (r + 1) * row_bytes], x);
    }
};

pub const QuantizedLinear = struct {
    pub fn apply(out: []f32, input: []const f32, bytes: []const u8, ggml_type: GgmlType, rows: usize, cols: usize, scratch: []f32) !void {
        const elements = std.math.mul(usize, rows, cols) catch return error.TensorTooLarge;
        switch (ggml_type) {
            .q3_k => try Q3KExact.matvec(out, bytes, input, rows, cols),
            .q8_0 => {
                if (scratch.len < elements) return error.BufferTooSmall;
                const fq = scratch[0..elements];
                try Dequant.q8_0(fq, bytes);
                try Linear.matmulF32(out, input, fq, rows, cols);
            },
            .q4_0 => {
                if (scratch.len < elements) return error.BufferTooSmall;
                const fq = scratch[0..elements];
                try Dequant.q4_0(fq, bytes);
                try Linear.matmulF32(out, input, fq, rows, cols);
            },
            else => return error.UnsupportedTensorType,
        }
    }
};

// ----------------------------------------------------------------------------
// Byte cursor parser for small GGUF metadata payloads and tests.
// ----------------------------------------------------------------------------

pub const ByteCursor = struct {
    data: []const u8,
    pos: usize = 0,

    pub fn remaining(self: ByteCursor) usize {
        return self.data.len - self.pos;
    }

    pub fn take(self: *ByteCursor, n: usize) ![]const u8 {
        if (n > self.remaining()) return error.UnexpectedEndOfFile;
        const out = self.data[self.pos .. self.pos + n];
        self.pos += n;
        return out;
    }

    pub fn u8v(self: *ByteCursor) !u8 {
        return (try self.take(1))[0];
    }
    pub fn u16le(self: *ByteCursor) !u16 {
        return readU16Le(try self.take(2));
    }
    pub fn u32le(self: *ByteCursor) !u32 {
        return readU32Le(try self.take(4));
    }
    pub fn u64le(self: *ByteCursor) !u64 {
        return readU64Le(try self.take(8));
    }

    pub fn string(self: *ByteCursor, maximum: usize) ![]const u8 {
        const n64 = try self.u64le();
        if (n64 > maximum) return error.StringTooLarge;
        return try self.take(@intCast(n64));
    }
};

pub const GgufMetadata = union(enum) {
    u8v: u8,
    i8v: i8,
    u16v: u16,
    i16v: i16,
    u32v: u32,
    i32v: i32,
    u64v: u64,
    i64v: i64,
    f32v: f32,
    f64v: f64,
    boolean: bool,
    string: []const u8,
};

pub const GgufSmallParser = struct {
    pub fn scalar(c: *ByteCursor, ty: Gguf.ValueType) !GgufMetadata {
        return switch (ty) {
            .uint8 => .{ .u8v = try c.u8v() },
            .int8 => .{ .i8v = @bitCast(try c.u8v()) },
            .uint16 => .{ .u16v = try c.u16le() },
            .int16 => .{ .i16v = @bitCast(try c.u16le()) },
            .uint32 => .{ .u32v = try c.u32le() },
            .int32 => .{ .i32v = @bitCast(try c.u32le()) },
            .uint64 => .{ .u64v = try c.u64le() },
            .int64 => .{ .i64v = @bitCast(try c.u64le()) },
            .float32 => .{ .f32v = @bitCast(try c.u32le()) },
            .float64 => .{ .f64v = @bitCast(try c.u64le()) },
            .bool => .{ .boolean = (try c.u8v()) != 0 },
            .string => .{ .string = try c.string(16 * 1024 * 1024) },
            .array => error.ArrayRequiresStreaming,
        };
    }
};

// ----------------------------------------------------------------------------
// Model tensor registry using SHA-256 names to avoid retaining unbounded strings.
// ----------------------------------------------------------------------------

pub const TensorRegistry = struct {
    pub const Entry = struct { name_hash: [32]u8, plan: TensorPlan };
    allocator: std.mem.Allocator,
    entries: std.ArrayList(Entry),

    pub fn init(allocator: std.mem.Allocator) TensorRegistry {
        return .{ .allocator = allocator, .entries = .empty };
    }

    pub fn deinit(self: *TensorRegistry) void {
        self.entries.deinit(self.allocator);
        self.* = undefined;
    }

    pub fn put(self: *TensorRegistry, name: []const u8, plan: TensorPlan) !void {
        const hash = sha256(name);
        for (self.entries.items) |*e| {
            if (ctEqual(&e.name_hash, &hash)) {
                e.plan = plan;
                return;
            }
        }
        try self.entries.append(self.allocator, .{ .name_hash = hash, .plan = plan });
    }

    pub fn get(self: TensorRegistry, name: []const u8) ?TensorPlan {
        const hash = sha256(name);
        for (self.entries.items) |e| if (ctEqual(&e.name_hash, &hash)) return e.plan;
        return null;
    }

    pub fn require(self: TensorRegistry, name: []const u8) !TensorPlan {
        return self.get(name) orelse error.MissingRequiredTensor;
    }
};

pub const LlamaTensorSet = struct {
    token_embd: TensorPlan,
    output_norm: TensorPlan,
    output: TensorPlan,

    pub fn fromRegistry(reg: TensorRegistry) !LlamaTensorSet {
        return .{
            .token_embd = try reg.require("token_embd.weight"),
            .output_norm = try reg.require("output_norm.weight"),
            .output = try reg.require("output.weight"),
        };
    }
};

// ----------------------------------------------------------------------------
// Tensor byte source abstraction. The file-backed implementation uses explicit
// offsets and bounded reads; there is no mmap/C dependency.
// ----------------------------------------------------------------------------

pub const TensorFile = struct {
    file: std.fs.File,
    data_start: u64,
    file_size: u64,

    pub fn open(path: []const u8, data_start: u64) !TensorFile {
        const f = try std.fs.cwd().openFile(path, .{});
        errdefer f.close();
        const st = try f.stat();
        if (data_start > st.size) return error.InvalidDataOffset;
        return .{ .file = f, .data_start = data_start, .file_size = st.size };
    }

    pub fn close(self: *TensorFile) void {
        self.file.close();
        self.* = undefined;
    }

    pub fn readPlan(self: *TensorFile, allocator: std.mem.Allocator, plan: TensorPlan) ![]u8 {
        try plan.validateRange(self.data_start, self.file_size);
        if (plan.bytes > std.math.maxInt(usize)) return error.TensorTooLarge;
        const n: usize = @intCast(plan.bytes);
        const out = try allocator.alloc(u8, n);
        errdefer allocator.free(out);
        try self.file.seekTo(self.data_start + plan.offset);
        var io_buf: [8192]u8 = undefined;
        var reader = self.file.reader(&io_buf).interface;
        try reader.readSliceAll(out);
        return out;
    }
};

// ----------------------------------------------------------------------------
// Embedding lookup and logits projection supporting f32 and Q3_K matrices.
// ----------------------------------------------------------------------------

pub const Embedding = struct {
    pub fn f32Lookup(out: []f32, weights: []const f32, token: usize, vocab: usize, hidden: usize) !void {
        if (out.len != hidden or weights.len != vocab * hidden or token >= vocab) return error.ShapeMismatch;
        @memcpy(out, weights[token * hidden .. (token + 1) * hidden]);
    }

    pub fn q3kLookup(out: []f32, weights: []const u8, token: usize, vocab: usize, hidden: usize) !void {
        if (out.len != hidden or hidden % Q3KExact.block_values != 0 or token >= vocab) return error.ShapeMismatch;
        const row_bytes = (hidden / Q3KExact.block_values) * Q3KExact.block_bytes;
        if (weights.len != vocab * row_bytes) return error.InvalidQuantizedLength;
        try Q3KExact.dequantRow(out, weights[token * row_bytes .. (token + 1) * row_bytes]);
    }
};

pub const Logits = struct {
    pub fn f32Project(out: []f32, hidden: []const f32, weights: []const f32, vocab: usize) !void {
        if (vocab == 0 or out.len != vocab or weights.len != vocab * hidden.len) return error.ShapeMismatch;
        try Linear.matmulF32(out, hidden, weights, vocab, hidden.len);
    }

    pub fn q3kProject(out: []f32, hidden: []const f32, weights: []const u8, vocab: usize) !void {
        try Q3KExact.matvec(out, weights, hidden, vocab, hidden.len);
    }
};

// ----------------------------------------------------------------------------
// Heap top-k utility used by sampling without sorting the entire vocabulary.
// ----------------------------------------------------------------------------

pub const TopK = struct {
    pub const Item = struct { index: u32, score: f32 };

    fn less(a: Item, b: Item) bool {
        return a.score < b.score;
    }

    fn siftUp(heap: []Item, idx_in: usize) void {
        var idx = idx_in;
        while (idx > 0) {
            const p = (idx - 1) / 2;
            if (!less(heap[idx], heap[p])) break;
            const t = heap[idx];
            heap[idx] = heap[p];
            heap[p] = t;
            idx = p;
        }
    }

    fn siftDown(heap: []Item, idx_in: usize) void {
        var idx = idx_in;
        while (true) {
            const l = idx * 2 + 1;
            if (l >= heap.len) break;
            const r = l + 1;
            var smallest = l;
            if (r < heap.len and less(heap[r], heap[l])) smallest = r;
            if (!less(heap[smallest], heap[idx])) break;
            const t = heap[idx];
            heap[idx] = heap[smallest];
            heap[smallest] = t;
            idx = smallest;
        }
    }

    pub fn select(out: []Item, logits: []const f32) !usize {
        if (out.len == 0) return 0;
        const k = @min(out.len, logits.len);
        var i: usize = 0;
        while (i < k) : (i += 1) {
            out[i] = .{ .index = @intCast(i), .score = logits[i] };
            siftUp(out[0 .. i + 1], i);
        }
        while (i < logits.len) : (i += 1) {
            if (logits[i] > out[0].score) {
                out[0] = .{ .index = @intCast(i), .score = logits[i] };
                siftDown(out[0..k], 0);
            }
        }
        return k;
    }

    pub fn sample(items: []Item, temperature: f32, rng: *XorShift128Plus) u32 {
        if (items.len == 0) return 0;
        if (temperature <= 0.00001) {
            var best = items[0];
            for (items[1..]) |it| if (it.score > best.score) {
                best = it;
            };
            return best.index;
        }
        var max = items[0].score;
        for (items[1..]) |it| if (it.score > max) {
            max = it.score;
        };
        var sum: f64 = 0;
        var probs: [1024]f64 = undefined;
        if (items.len > probs.len) return items[0].index;
        for (items, 0..) |it, i| {
            probs[i] = @exp(@as(f64, @floatCast((it.score - max) / temperature)));
            sum += probs[i];
        }
        var target = rng.unit() * sum;
        for (items, 0..) |it, i| {
            if (target <= probs[i]) return it.index;
            target -= probs[i];
        }
        return items[items.len - 1].index;
    }
};

pub const StopDetector = struct {
    patterns: []const []const u8,

    pub fn matched(self: StopDetector, generated: []const u8) ?[]const u8 {
        for (self.patterns) |p| {
            if (p.len <= generated.len and std.mem.eql(u8, generated[generated.len - p.len ..], p)) return p;
        }
        return null;
    }
};

// ----------------------------------------------------------------------------
// Generation session lifecycle. Model-specific forward callbacks can feed logits
// without pulling in Python or llama.cpp.
// ----------------------------------------------------------------------------

pub const GenerationSession = struct {
    allocator: std.mem.Allocator,
    config: GenerationConfig,
    sampler: Sampler,
    history: TokenHistory,
    position: usize = 0,

    pub fn init(allocator: std.mem.Allocator, config: GenerationConfig, history_capacity: usize) !GenerationSession {
        try config.validate();
        var sampler = Sampler.init(config.seed);
        sampler.temperature = config.temperature;
        sampler.top_k = config.top_k;
        sampler.top_p = config.top_p;
        sampler.repeat_penalty = config.repeat_penalty;
        return .{ .allocator = allocator, .config = config, .sampler = sampler, .history = try TokenHistory.init(allocator, history_capacity) };
    }

    pub fn deinit(self: *GenerationSession) void {
        self.history.deinit();
        self.* = undefined;
    }

    pub fn choose(self: *GenerationSession, logits: []f32, top_buffer: []TopK.Item) !u32 {
        self.sampler.applyRepeatPenalty(logits, self.history.slice());
        const wanted = if (self.config.top_k == 0) @min(logits.len, top_buffer.len) else @min(self.config.top_k, top_buffer.len);
        const n = try TopK.select(top_buffer[0..wanted], logits);
        const token = TopK.sample(top_buffer[0..n], self.config.temperature, &self.sampler.rng);
        self.history.push(token);
        self.position += 1;
        return token;
    }
};

test "Q3_K zero block decodes finite" {
    var block = [_]u8{0} ** Q3KExact.block_bytes;
    // fp16 d = 1.0
    block[Q3KExact.d_offset] = 0x00;
    block[Q3KExact.d_offset + 1] = 0x3c;
    var out: [256]f32 = undefined;
    Q3KExact.dequantBlock(&out, &block);
    for (out) |v| try std.testing.expect(std.math.isFinite(v));
}

test "top k selects maximum" {
    const logits = [_]f32{ -1, 3, 2, 9, 4 };
    var buf: [2]TopK.Item = undefined;
    const n = try TopK.select(&buf, &logits);
    try std.testing.expectEqual(@as(usize, 2), n);
    var found = false;
    for (buf) |it| if (it.index == 3) {
        found = true;
    };
    try std.testing.expect(found);
}

// ============================================================================
// EXPANSION 0.3e — explicit small statevector simulator and PUNKD-style local
// token weighting. This is classical simulation of quantum gates, not hardware.
// ============================================================================

pub const Complex = struct {
    re: f64,
    im: f64,

    pub fn zero() Complex {
        return .{ .re = 0, .im = 0 };
    }
    pub fn one() Complex {
        return .{ .re = 1, .im = 0 };
    }
    pub fn add(a: Complex, b: Complex) Complex {
        return .{ .re = a.re + b.re, .im = a.im + b.im };
    }
    pub fn sub(a: Complex, b: Complex) Complex {
        return .{ .re = a.re - b.re, .im = a.im - b.im };
    }
    pub fn mul(a: Complex, b: Complex) Complex {
        return .{ .re = a.re * b.re - a.im * b.im, .im = a.re * b.im + a.im * b.re };
    }
    pub fn scale(a: Complex, s: f64) Complex {
        return .{ .re = a.re * s, .im = a.im * s };
    }
    pub fn abs2(a: Complex) f64 {
        return a.re * a.re + a.im * a.im;
    }
};

pub const QuantumSim = struct {
    allocator: std.mem.Allocator,
    qubits: u5,
    state: []Complex,

    pub fn init(allocator: std.mem.Allocator, qubits: u5) !QuantumSim {
        if (qubits == 0 or qubits > 20) return error.QubitLimit;
        const n = @as(usize, 1) << qubits;
        const state = try allocator.alloc(Complex, n);
        for (state) |*amplitude| amplitude.* = Complex.zero();
        state[0] = Complex.one();
        return .{ .allocator = allocator, .qubits = qubits, .state = state };
    }

    pub fn deinit(self: *QuantumSim) void {
        @memset(std.mem.sliceAsBytes(self.state), 0);
        self.allocator.free(self.state);
        self.* = undefined;
    }

    pub fn normalize(self: *QuantumSim) !void {
        var norm: f64 = 0;
        for (self.state) |amplitude| norm += Complex.abs2(amplitude);
        if (norm <= 0) return error.ZeroState;
        const inv = 1.0 / @sqrt(norm);
        for (self.state) |*amplitude| amplitude.* = Complex.scale(amplitude.*, inv);
    }

    pub fn apply1(self: *QuantumSim, q: u5, a00: Complex, a01: Complex, a10: Complex, a11: Complex) !void {
        if (q >= self.qubits) return error.QubitOutOfRange;
        const bit = @as(usize, 1) << q;
        var i: usize = 0;
        while (i < self.state.len) : (i += 1) {
            if ((i & bit) != 0) continue;
            const j = i | bit;
            const a = self.state[i];
            const b = self.state[j];
            self.state[i] = Complex.add(Complex.mul(a00, a), Complex.mul(a01, b));
            self.state[j] = Complex.add(Complex.mul(a10, a), Complex.mul(a11, b));
        }
    }

    pub fn h(self: *QuantumSim, q: u5) !void {
        const s = 1.0 / @sqrt(2.0);
        try self.apply1(q, .{ .re = s, .im = 0 }, .{ .re = s, .im = 0 }, .{ .re = s, .im = 0 }, .{ .re = -s, .im = 0 });
    }

    pub fn rx(self: *QuantumSim, q: u5, theta: f64) !void {
        const c = @cos(theta / 2.0);
        const s = @sin(theta / 2.0);
        try self.apply1(q, .{ .re = c, .im = 0 }, .{ .re = 0, .im = -s }, .{ .re = 0, .im = -s }, .{ .re = c, .im = 0 });
    }

    pub fn ry(self: *QuantumSim, q: u5, theta: f64) !void {
        const c = @cos(theta / 2.0);
        const s = @sin(theta / 2.0);
        try self.apply1(q, .{ .re = c, .im = 0 }, .{ .re = -s, .im = 0 }, .{ .re = s, .im = 0 }, .{ .re = c, .im = 0 });
    }

    pub fn rz(self: *QuantumSim, q: u5, theta: f64) !void {
        const c = @cos(theta / 2.0);
        const s = @sin(theta / 2.0);
        try self.apply1(q, .{ .re = c, .im = -s }, Complex.zero(), Complex.zero(), .{ .re = c, .im = s });
    }

    pub fn x(self: *QuantumSim, q: u5) !void {
        try self.apply1(q, Complex.zero(), Complex.one(), Complex.one(), Complex.zero());
    }

    pub fn y(self: *QuantumSim, q: u5) !void {
        try self.apply1(q, Complex.zero(), .{ .re = 0, .im = -1 }, .{ .re = 0, .im = 1 }, Complex.zero());
    }

    pub fn z(self: *QuantumSim, q: u5) !void {
        try self.apply1(q, Complex.one(), Complex.zero(), Complex.zero(), .{ .re = -1, .im = 0 });
    }

    pub fn phase(self: *QuantumSim, q: u5, theta: f64) !void {
        try self.apply1(q, Complex.one(), Complex.zero(), Complex.zero(), .{ .re = @cos(theta), .im = @sin(theta) });
    }

    pub fn cx(self: *QuantumSim, control: u5, target: u5) !void {
        if (control >= self.qubits or target >= self.qubits or control == target) return error.QubitOutOfRange;
        const cb = @as(usize, 1) << control;
        const tb = @as(usize, 1) << target;
        var i: usize = 0;
        while (i < self.state.len) : (i += 1) {
            if ((i & cb) == 0 or (i & tb) != 0) continue;
            const j = i | tb;
            const t = self.state[i];
            self.state[i] = self.state[j];
            self.state[j] = t;
        }
    }

    pub fn cz(self: *QuantumSim, a: u5, b: u5) !void {
        if (a >= self.qubits or b >= self.qubits or a == b) return error.QubitOutOfRange;
        const mask = (@as(usize, 1) << a) | (@as(usize, 1) << b);
        for (self.state, 0..) |*zv, i| if ((i & mask) == mask) {
            zv.re = -zv.re;
            zv.im = -zv.im;
        };
    }

    pub fn swap(self: *QuantumSim, a: u5, b: u5) !void {
        if (a >= self.qubits or b >= self.qubits) return error.QubitOutOfRange;
        if (a == b) return;
        const ba = @as(usize, 1) << a;
        const bb = @as(usize, 1) << b;
        var i: usize = 0;
        while (i < self.state.len) : (i += 1) {
            const va = (i & ba) != 0;
            const vb = (i & bb) != 0;
            if (va or !vb) continue;
            const j = (i | ba) & ~bb;
            const t = self.state[i];
            self.state[i] = self.state[j];
            self.state[j] = t;
        }
    }

    pub fn expZ(self: QuantumSim, q: u5) !f64 {
        if (q >= self.qubits) return error.QubitOutOfRange;
        const bit = @as(usize, 1) << q;
        var e: f64 = 0;
        for (self.state, 0..) |zv, i| e += (if ((i & bit) == 0) 1.0 else -1.0) * Complex.abs2(zv);
        return e;
    }

    pub fn expZZ(self: QuantumSim, a: u5, b: u5) !f64 {
        if (a >= self.qubits or b >= self.qubits) return error.QubitOutOfRange;
        const ba = @as(usize, 1) << a;
        const bb = @as(usize, 1) << b;
        var e: f64 = 0;
        for (self.state, 0..) |zv, i| {
            const parity = ((i & ba) != 0) != ((i & bb) != 0);
            const sign: f64 = if (parity) -1.0 else 1.0;
            e += sign * Complex.abs2(zv);
        }
        return e;
    }

    pub fn probabilityOne(self: QuantumSim, q: u5) !f64 {
        if (q >= self.qubits) return error.QubitOutOfRange;
        const bit = @as(usize, 1) << q;
        var p: f64 = 0;
        for (self.state, 0..) |zv, i| if ((i & bit) != 0) {
            p += Complex.abs2(zv);
        };
        return p;
    }

    pub fn shannonEntropy(self: QuantumSim) f64 {
        var hsum: f64 = 0;
        for (self.state) |zv| {
            const p = Complex.abs2(zv);
            if (p > 0) hsum -= p * (@log(p) / @log(2.0));
        }
        return hsum;
    }

    pub fn cutEntropyFirstQubit(self: QuantumSim) !f64 {
        if (self.qubits < 1) return error.QubitOutOfRange;
        const p1 = try self.probabilityOne(0);
        const p0 = 1.0 - p1;
        var hsum: f64 = 0;
        if (p0 > 0) hsum -= p0 * (@log(p0) / @log(2.0));
        if (p1 > 0) hsum -= p1 * (@log(p1) / @log(2.0));
        return hsum;
    }

    pub fn sample(self: QuantumSim, rng: *XorShift128Plus) usize {
        var sample_value = rng.unit();
        for (self.state, 0..) |zv, i| {
            const p = Complex.abs2(zv);
            if (sample_value <= p) return i;
            sample_value -= p;
        }
        return self.state.len - 1;
    }
};

pub const QuantumEntropyCircuit = struct {
    pub fn score(allocator: std.mem.Allocator, metrics: SystemMetrics) !f64 {
        var sim = try QuantumSim.init(allocator, 5);
        defer sim.deinit();
        const vals = [_]f64{
            EntropyScore.clamp01(metrics.cpu_percent / 100.0),
            EntropyScore.clamp01(metrics.memory_percent / 100.0),
            EntropyScore.clamp01(metrics.load1 / 16.0),
            EntropyScore.clamp01((metrics.temperature_c - 20.0) / 80.0),
            EntropyScore.clamp01(@as(f64, @floatFromInt(metrics.process_count)) / 1000.0),
        };
        for (vals, 0..) |v, i| {
            try sim.ry(@intCast(i), v * std.math.pi);
            try sim.rz(@intCast(i), (1.0 - v) * std.math.pi / 2.0);
        }
        try sim.cx(0, 1);
        try sim.cx(1, 2);
        try sim.cx(2, 3);
        try sim.cx(3, 4);
        try sim.cz(4, 0);
        const entropy = sim.shannonEntropy() / @as(f64, @floatFromInt(sim.qubits));
        var corr: f64 = 0;
        corr += @abs(try sim.expZZ(0, 1));
        corr += @abs(try sim.expZZ(1, 2));
        corr += @abs(try sim.expZZ(2, 3));
        corr += @abs(try sim.expZZ(3, 4));
        corr /= 4.0;
        return EntropyScore.clamp01(0.75 * entropy + 0.25 * (1.0 - corr));
    }
};

// ============================================================================
// 30-circuit quantum-inspired RAG ensemble ported 1:1 from the Python runtime.
// Keeps every profile below 15 qubits, retrieves a five-circuit shortlist,
// samples with T=0.55, and learns from explicit Clef scores. Raw prompts are
// never persisted: only hashes, coarse features, and signed-hash embeddings are stored.
// ============================================================================

pub const QuantumEnsemble = struct {
    pub const state_path = "clef_quantum_history.json";
    pub const temperature: f64 = 0.55;
    pub const history_alpha: f64 = 0.20;
    pub const embed_dim: usize = 256;
    pub const max_attempts: usize = 500;
    pub const recent_window: usize = 20;
    pub const shortlist_size: usize = 5;

