        .{ .id = "C27", .qubits = 14, .topology = "GHZ backbone + sparse ZZ", .bias = "awe" },
        .{ .id = "C28", .qubits = 10, .topology = "two-cluster bridge circuit", .bias = "contrast" },
        .{ .id = "C29", .qubits = 12, .topology = "recursive interferometer", .bias = "abstraction" },
        .{ .id = "C30", .qubits = 14, .topology = "reservoir-style phase cascade", .bias = "wildcard search" },
    };

    const Stats = struct {
        historical_score: f64 = 0.5,
        mean_entropy: f64 = 0.83,
        runs: u32 = 0,
        clef_updates: u32 = 0,
    };

    const Attempt = struct {
        id: [16]u8 = [_]u8{0} ** 16,
        question_hash: [64]u8 = [_]u8{0} ** 64,
        category: [32]u8 = [_]u8{0} ** 32,
        category_len: u8 = 0,
        circuit_index: u8 = 0,
        clef_score: f32 = -1.0,
        entropy: f32 = 0.0,
        token_count: u32 = 0,
        embedding: [embed_dim]f32 = [_]f32{0} ** embed_dim,
        timestamp: i64 = 0,
    };

    const State = struct {
        circuits: [profiles.len]Stats = [_]Stats{.{}} ** profiles.len,
        recent: [recent_window]u8 = [_]u8{0} ** recent_window,
        recent_len: usize = 0,
        attempts: [max_attempts]Attempt = [_]Attempt{.{}} ** max_attempts,
        attempt_len: usize = 0,
    };

    pub const Candidate = struct {
        index: u8,
        probability: f64,
        score: f64,
    };

    pub const Route = struct {
        attempt_id: [16]u8,
        circuit_index: u8,
        entropy: f64,
        entropy_lo: f64,
        entropy_hi: f64,
        entropy_quality: f64,
        score: f64,
        probability: f64,
        top: [shortlist_size]Candidate,
    };

    pub const Feedback = struct {
        attempt_id: [16]u8,
        circuit_index: u8,
        clef_score: f64,
        historical_before: f64,
        historical_after: f64,
    };

    pub const StatusRow = struct {
        index: u8,
        historical_score: f64,
        mean_entropy: f64,
        runs: u32,
        clef_updates: u32,
    };

    fn categoryHint(category: []const u8) []const u8 {
        if (std.ascii.eqlIgnoreCase(category, "realism")) return "realistic photo physical material lighting camera ordinary plausible";
        if (std.ascii.eqlIgnoreCase(category, "stereotype") or std.ascii.eqlIgnoreCase(category, "stereotypes")) return "stereotype archetype nerd culture character identity recognizable tropes";
        if (std.ascii.eqlIgnoreCase(category, "beauty")) return "beautiful aesthetic elegant color harmony pleasing polished";
        if (std.ascii.eqlIgnoreCase(category, "emotion") or std.ascii.eqlIgnoreCase(category, "emotional")) return "emotion expressive feeling mood human affect empathy";
        if (std.ascii.eqlIgnoreCase(category, "epic")) return "epic cinematic vast monumental scale awe dramatic";
        if (std.ascii.eqlIgnoreCase(category, "awe")) return "awe epic vast monumental sublime cinematic scale";
        if (std.ascii.eqlIgnoreCase(category, "creative")) return "creative unusual novel exploratory surprising imaginative";
        if (std.ascii.eqlIgnoreCase(category, "composition")) return "composition framing layout balance foreground background visual hierarchy";
        if (std.ascii.eqlIgnoreCase(category, "character")) return "character face clothing pose personality design subject";
        if (std.ascii.eqlIgnoreCase(category, "abstract")) return "abstract conceptual symbolic geometry surreal nonliteral";
        if (std.ascii.eqlIgnoreCase(category, "road-risk")) return "road driving traffic weather obstacle visibility realistic safety environment";
        if (std.ascii.eqlIgnoreCase(category, "chat")) return "language reasoning associations semantics question answer context";
        return "";
    }

    pub fn inferCategory(text: []const u8) []const u8 {
        if (containsFolded(text, "stereotype") or containsFolded(text, "stereotypical") or containsFolded(text, "archetype")) return "stereotype";
        if (containsFolded(text, "realistic") or containsFolded(text, "realism") or containsFolded(text, "photoreal") or containsFolded(text, "photo")) return "realism";
        if (containsFolded(text, "beautiful") or containsFolded(text, "beauty") or containsFolded(text, "aesthetic") or containsFolded(text, "elegant")) return "beauty";
        if (containsFolded(text, "emotion") or containsFolded(text, "emotional") or containsFolded(text, "feeling") or containsFolded(text, "mood")) return "emotion";
        if (containsFolded(text, "epic") or containsFolded(text, "awe") or containsFolded(text, "cinematic") or containsFolded(text, "monumental")) return "epic";
        if (containsFolded(text, "character") or containsFolded(text, "portrait") or containsFolded(text, "person") or containsFolded(text, "face")) return "character";
        if (containsFolded(text, "composition") or containsFolded(text, "layout") or containsFolded(text, "framing") or containsFolded(text, "scene")) return "composition";
        if (containsFolded(text, "abstract") or containsFolded(text, "surreal") or containsFolded(text, "conceptual") or containsFolded(text, "symbolic")) return "abstract";
        return "chat";
    }

    fn containsFolded(text: []const u8, needle: []const u8) bool {
        if (needle.len == 0 or needle.len > text.len) return false;
        var start: usize = 0;
        while (start + needle.len <= text.len) : (start += 1) {
            var ok = true;
            for (needle, 0..) |c, i| {
                if (std.ascii.toLower(text[start + i]) != std.ascii.toLower(c)) {
                    ok = false;
                    break;
                }
            }
            if (ok) return true;
        }
        return false;
    }

    fn band(category: []const u8) [2]f64 {
        if (containsFolded(category, "realism") or containsFolded(category, "stereotype") or containsFolded(category, "road") or containsFolded(category, "photo")) return .{ 0.72, 0.82 };
        if (containsFolded(category, "beauty") or containsFolded(category, "emotion") or containsFolded(category, "emotional")) return .{ 0.78, 0.88 };
        if (containsFolded(category, "epic") or containsFolded(category, "awe") or containsFolded(category, "creative") or containsFolded(category, "cinematic")) return .{ 0.84, 0.92 };
        return .{ 0.78, 0.88 };
    }

    fn entropyQuality(value_raw: f64, b: [2]f64) f64 {
        const value = @max(0.0, @min(1.0, value_raw));
        if (value >= b[0] and value <= b[1]) return 1.0;
        const distance = if (value < b[0]) b[0] - value else value - b[1];
        return @max(0.0, 1.0 - distance / 0.20);
    }

    fn defaultState() State {
        var state = State{};
        for (profiles, 0..) |p, i| {
            const b = band(p.bias);
            state.circuits[i].mean_entropy = (b[0] + b[1]) / 2.0;
        }
        return state;
    }

    fn profileIndex(id: []const u8) ?usize {
        for (profiles, 0..) |p, i| if (std.mem.eql(u8, p.id, id)) return i;
        return null;
    }

    fn jsonField(value: std.json.Value, name: []const u8) ?std.json.Value {
        return switch (value) {
            .object => |object| object.get(name),
            else => null,
        };
    }

    fn jsonString(value: ?std.json.Value) ?[]const u8 {
        const v = value orelse return null;
        return switch (v) {
            .string => |s| s,
            else => null,
        };
    }

    fn jsonNumber(value: ?std.json.Value) ?f64 {
        const v = value orelse return null;
        return switch (v) {
            .float => |x| x,
            .integer => |x| @floatFromInt(x),
            else => null,
        };
    }

    fn jsonInteger(value: ?std.json.Value) ?i64 {
        const v = value orelse return null;
        return switch (v) {
            .integer => |x| x,
            else => null,
        };
    }

    fn loadState(allocator: std.mem.Allocator) !*State {
        const state = try allocator.create(State);
        errdefer allocator.destroy(state);
        state.* = defaultState();

        var file = std.fs.cwd().openFile(state_path, .{}) catch |err| switch (err) {
            error.FileNotFound => return state,
            else => return state,
        };
        defer file.close();
        const stat = file.stat() catch return state;
        if (stat.kind != .file or stat.size == 0 or stat.size > AtomicStorage.max_file) return state;
        const bytes = try allocator.alloc(u8, @intCast(stat.size));
        defer allocator.free(bytes);
        const got = file.readAll(bytes) catch return state;
        const parsed = std.json.parseFromSlice(std.json.Value, allocator, bytes[0..got], .{}) catch return state;
        defer parsed.deinit();

        const root = parsed.value;
        if (jsonField(root, "circuits")) |circuits_value| switch (circuits_value) {
            .object => |object| {
                for (profiles, 0..) |p, i| {
                    const item = object.get(p.id) orelse continue;
                    if (jsonNumber(jsonField(item, "historical_score"))) |v| state.circuits[i].historical_score = @max(0.0, @min(1.0, v));
                    if (jsonNumber(jsonField(item, "mean_entropy"))) |v| state.circuits[i].mean_entropy = @max(0.0, @min(1.0, v));
                    if (jsonInteger(jsonField(item, "runs"))) |v| {
                        if (v >= 0) state.circuits[i].runs = @intCast(@min(v, @as(i64, std.math.maxInt(u32))));
                    }
                    if (jsonInteger(jsonField(item, "clef_updates"))) |v| {
                        if (v >= 0) state.circuits[i].clef_updates = @intCast(@min(v, @as(i64, std.math.maxInt(u32))));
                    }
                }
            },
            else => {},
        };

        if (jsonField(root, "recent")) |recent_value| switch (recent_value) {
            .array => |array| {
                const start = if (array.items.len > recent_window) array.items.len - recent_window else 0;
                for (array.items[start..]) |item| {
                    const id = jsonString(item) orelse continue;
                    const idx = profileIndex(id) orelse continue;
                    if (state.recent_len < recent_window) {
                        state.recent[state.recent_len] = @intCast(idx);
                        state.recent_len += 1;
                    }
                }
            },
            else => {},
        };

        if (jsonField(root, "attempts")) |attempts_value| switch (attempts_value) {
            .array => |array| {
                const start = if (array.items.len > max_attempts) array.items.len - max_attempts else 0;
                for (array.items[start..]) |item| {
                    if (state.attempt_len >= max_attempts) break;
                    const cid = jsonString(jsonField(item, "circuit_id")) orelse continue;
                    const idx = profileIndex(cid) orelse continue;
                    var attempt = Attempt{};
                    attempt.circuit_index = @intCast(idx);
                    if (jsonString(jsonField(item, "id"))) |id| {
                        const n = @min(id.len, attempt.id.len);
                        @memcpy(attempt.id[0..n], id[0..n]);
                    }
                    if (jsonString(jsonField(item, "question_hash"))) |qh| {
                        const n = @min(qh.len, attempt.question_hash.len);
                        @memcpy(attempt.question_hash[0..n], qh[0..n]);
                    }
                    if (jsonString(jsonField(item, "category"))) |cat| {
                        const n = @min(cat.len, attempt.category.len);
                        @memcpy(attempt.category[0..n], cat[0..n]);
                        attempt.category_len = @intCast(n);
                    }
                    if (jsonNumber(jsonField(item, "entropy"))) |v| attempt.entropy = @floatCast(v);
                    if (jsonNumber(jsonField(item, "clef_score"))) |v| attempt.clef_score = @floatCast(v);
                    if (jsonInteger(jsonField(item, "timestamp"))) |v| attempt.timestamp = v;
                    if (jsonField(item, "features")) |features_value| switch (features_value) {
                        .array => |features_array| {
                            for (features_array.items) |feature_value| {
                                const feature = jsonString(feature_value) orelse continue;
                                if (std.mem.startsWith(u8, feature, "tokens:")) {
                                    attempt.token_count = std.fmt.parseInt(u32, feature[7..], 10) catch 0;
                                }
                            }
                        },
                        else => {},
                    };
                    if (jsonField(item, "embedding")) |embedding_value| switch (embedding_value) {
                        .array => |embedding_array| {
                            if (embedding_array.items.len == embed_dim) {
                                for (embedding_array.items, 0..) |x, j| attempt.embedding[j] = @floatCast(jsonNumber(x) orelse 0.0);
                            }
                        },
                        else => {},
                    };
                    state.attempts[state.attempt_len] = attempt;
                    state.attempt_len += 1;
                }
            },
            else => {},
        };
        return state;
    }

    fn appendFmt(list: *std.ArrayList(u8), allocator: std.mem.Allocator, comptime fmt: []const u8, args: anytype) !void {
        var buf: [1024]u8 = undefined;
        const text = try std.fmt.bufPrint(&buf, fmt, args);
        try list.appendSlice(allocator, text);
    }

    fn saveState(allocator: std.mem.Allocator, state: *const State) !void {
        var out = std.ArrayList(u8).empty;
        defer out.deinit(allocator);
        try out.appendSlice(allocator, "{\n  \"version\": 1,\n  \"circuits\": {\n");
        for (profiles, 0..) |p, i| {
            const s = state.circuits[i];
            try appendFmt(&out, allocator, "    \"{s}\": {{\"historical_score\": {d:.8}, \"mean_entropy\": {d:.8}, \"runs\": {}, \"clef_updates\": {}}}{s}\n", .{ p.id, s.historical_score, s.mean_entropy, s.runs, s.clef_updates, if (i + 1 == profiles.len) "" else "," });
        }
        try out.appendSlice(allocator, "  },\n  \"recent\": [");
        for (state.recent[0..state.recent_len], 0..) |idx, i| {
            if (i != 0) try out.appendSlice(allocator, ", ");
            try appendFmt(&out, allocator, "\"{s}\"", .{profiles[idx].id});
        }
        try out.appendSlice(allocator, "],\n  \"attempts\": [\n");
        for (state.attempts[0..state.attempt_len], 0..) |a, ai| {
            const cat = a.category[0..a.category_len];
            try appendFmt(&out, allocator, "    {{\"id\":\"{s}\",\"timestamp\":{},\"question_hash\":\"{s}\",\"category\":\"{s}\",\"circuit_id\":\"{s}\",\"clef_score\":", .{ a.id[0..], a.timestamp, a.question_hash[0..], cat, profiles[a.circuit_index].id });
            if (a.clef_score < 0) try out.appendSlice(allocator, "null") else try appendFmt(&out, allocator, "{d:.5}", .{a.clef_score});
            try appendFmt(&out, allocator, ",\"entropy\":{d:.8},\"embedding\":[", .{a.entropy});
            for (a.embedding, 0..) |v, j| {
                if (j != 0) try out.append(allocator, ',');
                try appendFmt(&out, allocator, "{d:.7}", .{v});
            }
            try appendFmt(&out, allocator, "],\"features\":[\"{s}\",\"{s}\",\"entropy:{d:.3}\",\"tokens:{}\"]}}{s}\n", .{ cat, profiles[a.circuit_index].bias, a.entropy, a.token_count, if (ai + 1 == state.attempt_len) "" else "," });
        }
        try out.appendSlice(allocator, "  ]\n}\n");
        try AtomicStorage.writeAtomic(state_path, out.items);
    }

    const Blake2b64 = std.crypto.hash.blake2.Blake2b(64);

    fn digestToU64(digest: [8]u8) u64 {
        var x: u64 = 0;
        for (digest, 0..) |b, i| x |= @as(u64, b) << @intCast(i * 8);
        return x;
    }

    fn hash64(bytes: []const u8) u64 {
        var digest: [Blake2b64.digest_length]u8 = undefined;
        Blake2b64.hash(bytes, &digest, .{});
        return digestToU64(digest);
    }

    fn hashTokenInto(v: *[embed_dim]f64, token: []const u8) void {
        if (token.len == 0) return;
        const h = hash64(token);
        const idx: usize = @intCast(h % embed_dim);
        const sign: f64 = if (((h >> 8) & 1) == 0) 1.0 else -1.0;
        v[idx] += sign;
    }

    fn embedding(texts: []const []const u8) [embed_dim]f64 {
        var v = [_]f64{0} ** embed_dim;
        var token: [192]u8 = undefined;
        var token_len: usize = 0;
        for (texts) |text| {
            for (text) |c| {
                if (std.ascii.isAlphanumeric(c)) {
                    if (token_len < token.len) {
                        token[token_len] = std.ascii.toLower(c);
                        token_len += 1;
                    }
                } else if (token_len != 0) {
                    hashTokenInto(&v, token[0..token_len]);
                    token_len = 0;
                }
            }
            if (token_len != 0) {
                hashTokenInto(&v, token[0..token_len]);
                token_len = 0;
            }
        }
        var norm2: f64 = 0;
        for (v) |x| norm2 += x * x;
        if (norm2 > 0) {
            const inv = 1.0 / @sqrt(norm2);
            for (&v) |*x| x.* *= inv;
        }
        return v;
    }

    fn cosine(a: *const [embed_dim]f64, b: *const [embed_dim]f64) f64 {
        var dot_product: f64 = 0;
        var na: f64 = 0;
        var nb: f64 = 0;
        for (0..embed_dim) |i| {
            dot_product += a[i] * b[i];
            na += a[i] * a[i];
            nb += b[i] * b[i];
        }
        if (na == 0 or nb == 0) return 0;
        return @max(0.0, @min(1.0, (dot_product / (@sqrt(na) * @sqrt(nb)) + 1.0) / 2.0));
    }

    fn cosineAttempt(query: *const [embed_dim]f64, attempt: *const Attempt) f64 {
        var dot_product: f64 = 0;
        var na: f64 = 0;
        var nb: f64 = 0;
        for (0..embed_dim) |i| {
            const av: f64 = attempt.embedding[i];
            dot_product += query[i] * av;
            na += query[i] * query[i];
            nb += av * av;
        }
        if (na == 0 or nb == 0) return 0;
        return @max(0.0, @min(1.0, (dot_product / (@sqrt(na) * @sqrt(nb)) + 1.0) / 2.0));
    }

    fn prior(category: []const u8, idx: usize) f64 {
        const id = profiles[idx].id;
        const Pair = struct { id: []const u8, value: f64 };
        const stereo = [_]Pair{ .{ .id = "C14", .value = 1.00 }, .{ .id = "C17", .value = 0.88 }, .{ .id = "C04", .value = 0.82 }, .{ .id = "C28", .value = 0.76 }, .{ .id = "C01", .value = 0.70 } };
        const realism = [_]Pair{ .{ .id = "C08", .value = 1.00 }, .{ .id = "C04", .value = 0.84 }, .{ .id = "C23", .value = 0.78 }, .{ .id = "C11", .value = 0.72 }, .{ .id = "C28", .value = 0.68 } };
        const road = [_]Pair{ .{ .id = "C08", .value = 1.00 }, .{ .id = "C23", .value = 0.88 }, .{ .id = "C11", .value = 0.80 }, .{ .id = "C10", .value = 0.74 }, .{ .id = "C04", .value = 0.70 } };
        const beauty = [_]Pair{ .{ .id = "C05", .value = 1.00 }, .{ .id = "C22", .value = 0.88 }, .{ .id = "C12", .value = 0.78 }, .{ .id = "C11", .value = 0.72 }, .{ .id = "C01", .value = 0.68 } };
        const emotion = [_]Pair{ .{ .id = "C01", .value = 1.00 }, .{ .id = "C17", .value = 0.82 }, .{ .id = "C16", .value = 0.76 }, .{ .id = "C04", .value = 0.72 }, .{ .id = "C05", .value = 0.66 } };
        const epic = [_]Pair{ .{ .id = "C13", .value = 1.00 }, .{ .id = "C27", .value = 0.96 }, .{ .id = "C26", .value = 0.84 }, .{ .id = "C24", .value = 0.76 }, .{ .id = "C20", .value = 0.70 } };
        const awe = [_]Pair{ .{ .id = "C27", .value = 1.00 }, .{ .id = "C13", .value = 0.94 }, .{ .id = "C26", .value = 0.82 }, .{ .id = "C24", .value = 0.76 }, .{ .id = "C20", .value = 0.70 } };
        const creative = [_]Pair{ .{ .id = "C07", .value = 0.94 }, .{ .id = "C19", .value = 0.90 }, .{ .id = "C30", .value = 0.88 }, .{ .id = "C18", .value = 0.82 }, .{ .id = "C29", .value = 0.78 } };
        const character = [_]Pair{ .{ .id = "C17", .value = 1.00 }, .{ .id = "C04", .value = 0.88 }, .{ .id = "C01", .value = 0.76 }, .{ .id = "C12", .value = 0.68 }, .{ .id = "C28", .value = 0.64 } };
        const composition = [_]Pair{ .{ .id = "C02", .value = 1.00 }, .{ .id = "C11", .value = 0.90 }, .{ .id = "C23", .value = 0.82 }, .{ .id = "C28", .value = 0.74 }, .{ .id = "C05", .value = 0.68 } };
        const abstract = [_]Pair{ .{ .id = "C29", .value = 1.00 }, .{ .id = "C18", .value = 0.92 }, .{ .id = "C07", .value = 0.86 }, .{ .id = "C03", .value = 0.78 }, .{ .id = "C30", .value = 0.74 } };
        var table: []const Pair = &[_]Pair{};
        if (std.ascii.eqlIgnoreCase(category, "stereotype") or std.ascii.eqlIgnoreCase(category, "stereotypes")) table = &stereo else if (std.ascii.eqlIgnoreCase(category, "realism")) table = &realism else if (std.ascii.eqlIgnoreCase(category, "road-risk")) table = &road else if (std.ascii.eqlIgnoreCase(category, "beauty")) table = &beauty else if (std.ascii.eqlIgnoreCase(category, "emotion") or std.ascii.eqlIgnoreCase(category, "emotional")) table = &emotion else if (std.ascii.eqlIgnoreCase(category, "epic")) table = &epic else if (std.ascii.eqlIgnoreCase(category, "awe")) table = &awe else if (std.ascii.eqlIgnoreCase(category, "creative")) table = &creative else if (std.ascii.eqlIgnoreCase(category, "character")) table = &character else if (std.ascii.eqlIgnoreCase(category, "composition")) table = &composition else if (std.ascii.eqlIgnoreCase(category, "abstract")) table = &abstract;
        for (table) |item| if (std.mem.eql(u8, item.id, id)) return item.value;
        return 0.0;
    }

    fn hasPriorTable(category: []const u8) bool {
        return std.ascii.eqlIgnoreCase(category, "stereotype") or std.ascii.eqlIgnoreCase(category, "stereotypes") or
            std.ascii.eqlIgnoreCase(category, "realism") or std.ascii.eqlIgnoreCase(category, "road-risk") or
            std.ascii.eqlIgnoreCase(category, "beauty") or std.ascii.eqlIgnoreCase(category, "emotion") or
            std.ascii.eqlIgnoreCase(category, "emotional") or std.ascii.eqlIgnoreCase(category, "epic") or
            std.ascii.eqlIgnoreCase(category, "awe") or std.ascii.eqlIgnoreCase(category, "creative") or
            std.ascii.eqlIgnoreCase(category, "character") or std.ascii.eqlIgnoreCase(category, "composition") or
            std.ascii.eqlIgnoreCase(category, "abstract");
    }

    fn cp(sim: *QuantumSim, a: u5, b: u5, theta: f64) !void {
        try sim.phase(a, theta / 2.0);
        try sim.phase(b, theta / 2.0);
        try sim.cx(a, b);
        try sim.phase(b, -theta / 2.0);
        try sim.cx(a, b);
    }

    fn isingZZ(sim: *QuantumSim, a: u5, b: u5, theta: f64) !void {
        try sim.cx(a, b);
        try sim.rz(b, theta);
        try sim.cx(a, b);
    }

    fn multiRz3(sim: *QuantumSim, a: u5, b: u5, c: u5, theta: f64) !void {
        try sim.cx(a, c);
        try sim.cx(b, c);
        try sim.rz(c, theta);
        try sim.cx(b, c);
        try sim.cx(a, c);
    }

    fn controlledRy(sim: *QuantumSim, control: u5, target: u5, theta: f64) !void {
        try sim.ry(target, theta / 2.0);
        try sim.cx(control, target);
        try sim.ry(target, -theta / 2.0);
        try sim.cx(control, target);
    }

    fn isingXX(sim: *QuantumSim, a: u5, b: u5, theta: f64) !void {
        try sim.h(a);
        try sim.h(b);
        try isingZZ(sim, a, b, theta);
        try sim.h(a);
        try sim.h(b);
    }

    fn isingYY(sim: *QuantumSim, a: u5, b: u5, theta: f64) !void {
        try sim.rx(a, std.math.pi / 2.0);
        try sim.rx(b, std.math.pi / 2.0);
        try isingZZ(sim, a, b, theta);
        try sim.rx(a, -std.math.pi / 2.0);
        try sim.rx(b, -std.math.pi / 2.0);
    }

    fn seedFor(question: []const u8, category: []const u8, p: Profile) u64 {
        // Python parity: blake2b(f"{profile.id}|{category}|{question}", digest_size=8).
        var h = Blake2b64.init(.{});
        h.update(p.id);
        h.update("|");
        h.update(category);
        h.update("|");
        h.update(question);
        var digest: [Blake2b64.digest_length]u8 = undefined;
        h.final(&digest);
        return digestToU64(digest);
    }

    fn angle(seed: u64, k: usize, scale: f64) f64 {
        var buf: [64]u8 = undefined;
        const text = std.fmt.bufPrint(&buf, "{}:{}", .{ seed, k }) catch unreachable;
        const h = hash64(text);
        // Python parity: int.from_bytes(digest, "little") / float(2**64 - 1).
        const u = @as(f64, @floatFromInt(h)) / 18446744073709551615.0;
        return (0.18 + 0.64 * u) * std.math.pi * scale;
    }

    fn prepareBase(sim: *QuantumSim, seed: u64, target_mid: f64) !void {
        const scale = 0.72 + 0.42 * @max(0.0, @min(1.0, target_mid));
        for (0..sim.qubits) |wi| {
            const w: u5 = @intCast(wi);
            try sim.ry(w, angle(seed, wi, scale));
            if (wi % 2 == 1) try sim.rx(w, angle(seed, 100 + wi, 0.35));
        }
    }

    fn ringCp(sim: *QuantumSim, seed: u64, offset: usize) !void {
        const n: usize = sim.qubits;
        for (0..n) |i| try cp(sim, @intCast(i), @intCast((i + 1) % n), angle(seed, 200 + offset + i, 0.55));
    }

    fn primeJumps(sim: *QuantumSim, seed: u64, offset: usize) !void {
        const n: usize = sim.qubits;
        const jumps = [_]usize{ 2, 3, 5 };
        for (jumps) |jump| {
            if (jump >= n) continue;
            var i: usize = 0;
            while (i < n) : (i += 2) {
                const j = (i + jump) % n;
                if (i != j) try cp(sim, @intCast(i), @intCast(j), angle(seed, 300 + offset + jump * 31 + i, 0.45));
            }
        }
    }

    fn butterfly(sim: *QuantumSim) !void {
        const n: usize = sim.qubits;
        var step: usize = 1;
        while (step < n) : (step *= 2) {
            var i: usize = 0;
            while (i < n) : (i += 2 * step) {
                var j = i;
                while (j < @min(i + step, n)) : (j += 1) {
                    const k = j + step;
                    if (k < n) try sim.cx(@intCast(j), @intCast(k));
                }
            }
        }
    }

    fn applyTopology(sim: *QuantumSim, index_one: usize, seed: u64, target_mid: f64) !void {
        const n: usize = sim.qubits;
        try prepareBase(sim, seed, target_mid);
        switch (index_one) {
            1 => {
                try sim.h(0);
                for (1..n) |i| try sim.cx(0, @intCast(i));
                try ringCp(sim, seed, 0);
                for (0..n) |i| try sim.ry(@intCast(i), angle(seed, 500 + i, 0.25));
            },
            2 => {
                try butterfly(sim);
                for (0..n) |i| try sim.rz(@intCast(i), angle(seed, 520 + i, 0.5));
                for (0..n) |i| try sim.h(@intCast(i));
            },
            3 => {
                try primeJumps(sim, seed, 0);
                var i: usize = 0;
                while (i < n) : (i += 2) try sim.rx(@intCast(i), angle(seed, 540 + i, 0.22));
            },
            4 => {
                for (1..n) |i| try sim.cx(0, @intCast(i));
                for (1..n) |i| try sim.rz(@intCast(i), angle(seed, 560 + i, 0.45));
                var i = n;
                while (i > 1) {
                    i -= 1;
                    try sim.cx(0, @intCast(i));
                }
                try sim.ry(0, angle(seed, 579, 0.35));
            },
            5 => {
                for (0..n) |i| try sim.cx(@intCast(i), @intCast((i + 1) % n));
                for (0..n) |i| try cp(sim, @intCast(i), @intCast((i + 2) % n), angle(seed, 580 + i, 0.35));
            },
            6 => {
                var i: usize = 0;
                while (i + 2 < n) : (i += 3) try multiRz3(sim, @intCast(i), @intCast(i + 1), @intCast(i + 2), angle(seed, 600 + i, 0.35));
                try ringCp(sim, seed, 30);
            },
            7 => {
                for (0..n) |i| try sim.h(@intCast(i));
                for (0..n) |i| {
                    var j = i + 1;
                    while (j < @min(n, i + 4)) : (j += 1) {
                        const denom = @as(f64, @floatFromInt(@as(usize, 1) << @intCast(j - i)));
                        try cp(sim, @intCast(j), @intCast(i), std.math.pi / denom);
                    }
                }
                var i = n;
                while (i > 0) {
                    i -= 1;
                    try sim.h(@intCast(i));
                }
            },
            8 => {
                for (0..2) |layer| {
                    var i = layer;
                    while (i + 1 < n) : (i += 2) try sim.cz(@intCast(i), @intCast(i + 1));
                    for (0..n) |j| try sim.ry(@intCast(j), angle(seed, 620 + layer * n + j, 0.28));
                }
            },
            9 => {
                const jumps = [_]usize{ 1, 2, 3, 5 };
                for (jumps) |jump| {
                    var i: usize = 0;
                    while (i + jump < n) : (i += 1) if (i % 2 == 0) try sim.cx(@intCast(i), @intCast(i + jump));
                }
            },
            10 => {
                try ringCp(sim, seed, 60);
                try primeJumps(sim, seed, 60);
            },
            11 => {
                var width: usize = 1;
                while (width < n) : (width *= 2) {
                    var i: usize = 0;
                    while (i + width < n) : (i += width * 2) try sim.cx(@intCast(i), @intCast(i + width));
                }
            },
            12 => for (0..n / 2) |i| {
                try sim.cx(@intCast(i), @intCast(n - 1 - i));
                try sim.ry(@intCast(n - 1 - i), angle(seed, 660 + i, 0.3));
            },
            13 => {
                for (0..n - 1) |i| try isingZZ(sim, @intCast(i), @intCast(i + 1), angle(seed, 680 + i, 0.25));
                for (0..n / 2) |i| try isingZZ(sim, @intCast(i), @intCast(n - 1 - i), angle(seed, 700 + i, 0.22));
                var i: usize = 0;
                while (i < n) : (i += 2) try sim.ry(@intCast(i), angle(seed, 720 + i, 0.20));
            },
            14 => {
                for (1..n) |i| try sim.cx(0, @intCast(i));
                var i = n;
                while (i > 1) {
                    i -= 1;
                    try sim.cx(0, @intCast(i));
                }
                for (0..n) |j| try sim.h(@intCast(j));
                var j: usize = 0;
                while (j < n) : (j += 2) try sim.ry(@intCast(j), angle(seed, 740 + j, 0.32));
            },
            15 => for (0..n - 1) |i| {
                const theta = angle(seed, 760 + i, 0.22);
                try isingXX(sim, @intCast(i), @intCast(i + 1), theta);
                try isingYY(sim, @intCast(i), @intCast(i + 1), theta);
            },
            16 => {
                for (0..n - 1) |i| try isingZZ(sim, @intCast(i), @intCast(i + 1), angle(seed, 780 + i, 0.34));
                for (0..n) |i| try sim.h(@intCast(i));
                try ringCp(sim, seed, 90);
            },
            17 => for (1..n) |i| try controlledRy(sim, 0, @intCast(i), angle(seed, 800 + i, 0.42)),
            18 => {
                for (0..n) |i| {
                    const j = (i + 1) % n;
                    try sim.cx(@intCast(i), @intCast(j));
                    if (i % 2 == 0) try sim.rz(@intCast(j), angle(seed, 820 + i, 0.42));
                }
                try sim.cx(0, @intCast(n / 2));
            },
            19 => {
                for (0..n) |i| {
                    for ([_]usize{ 2, 5 }) |jump| {
                        const j = (i + jump + @as(usize, @intCast(seed % 3))) % n;
                        if (i < j) try sim.cz(@intCast(i), @intCast(j));
                    }
                }
                var i: usize = 0;
                while (i < n) : (i += 3) try sim.ry(@intCast(i), angle(seed, 840 + i, 0.30));
            },
            20 => {
                for (0..n) |i| {
                    for ([_]usize{ 1, 2, 3 }) |jump| {
                        const j = (i + jump) % n;
                        if (i < j) try cp(sim, @intCast(i), @intCast(j), angle(seed, 860 + i * 5 + jump, 0.24));
                    }
                }
                for (0..n) |i| try sim.rx(@intCast(i), angle(seed, 900 + i, 0.16));
            },
            21 => {
                for (0..n) |i| try sim.ry(@intCast(i), (@as(f64, @floatFromInt(i + 1)) / @as(f64, @floatFromInt(n))) * std.math.pi * 0.42);
                for (0..n - 1) |i| try sim.cx(@intCast(i), @intCast(i + 1));
            },
            22 => {
                const golden = std.math.pi * (3.0 - @sqrt(5.0));
                for (0..n) |i| {
                    try sim.rz(@intCast(i), @as(f64, @floatFromInt(i + 1)) * golden);
                    try sim.ry(@intCast(i), angle(seed, 920 + i, 0.22));
                }
                try ringCp(sim, seed, 110);
            },
            23 => {
                for (0..2) |layer| {
                    var i = layer;
                    while (i + 1 < n) : (i += 2) {
                        try sim.swap(@intCast(i), @intCast(i + 1));
                        try sim.cz(@intCast(i), @intCast(i + 1));
                    }
                }
                for (0..n) |i| try sim.ry(@intCast(i), angle(seed, 940 + i, 0.22));
            },
            24 => {
                for (1..n) |i| try sim.cx(@intCast(i), 0);
                try sim.rz(0, angle(seed, 960, 0.75));
                var i = n;
                while (i > 1) {
                    i -= 1;
                    try sim.cx(@intCast(i), 0);
                }
                for (0..n) |j| try sim.rx(@intCast(j), angle(seed, 970 + j, 0.18));
            },
            25 => {
                var i: usize = 0;
                while (i + 2 < n) : (i += 2) try multiRz3(sim, @intCast(i), @intCast(i + 1), @intCast(i + 2), angle(seed, 990 + i, 0.30));
                for (0..n) |j| try sim.ry(@intCast(j), angle(seed, 1010 + j, 0.20));
            },
            26 => {
                try butterfly(sim);
                try primeJumps(sim, seed, 130);
                for (0..n) |i| try sim.ry(@intCast(i), angle(seed, 1030 + i, 0.18));
            },
            27 => {
                try sim.h(0);
                for (1..n) |i| try sim.cx(0, @intCast(i));
                var i: usize = 0;
                while (i + 2 < n) : (i += 3) try isingZZ(sim, @intCast(i), @intCast(i + 2), angle(seed, 1050 + i, 0.25));
                for (0..n) |j| try sim.ry(@intCast(j), angle(seed, 1070 + j, 0.16));
            },
            28 => {
                const mid = n / 2;
                var i: usize = 0;
                while (i + 1 < mid) : (i += 1) try sim.cx(@intCast(i), @intCast(i + 1));
                i = mid;
                while (i + 1 < n) : (i += 1) try sim.cx(@intCast(i), @intCast(i + 1));
                try sim.cz(@intCast(mid - 1), @intCast(mid));
                try sim.ry(@intCast(mid), angle(seed, 1090, 0.45));
            },
            29 => {
                var span: usize = 1;
                while (span < n) : (span *= 2) {
                    var i: usize = 0;
                    while (i + span < n) : (i += 2 * span) {
                        try sim.h(@intCast(i));
                        try sim.cz(@intCast(i), @intCast(i + span));
                    }
                }
                for (0..n) |i| try sim.ry(@intCast(i), angle(seed, 1110 + i, 0.20));
            },
            30 => for (0..3) |layer| {
                try ringCp(sim, seed, 160 + layer * n);
                for (0..n) |i| {
                    try sim.rz(@intCast(i), angle(seed, 1140 + layer * n + i, 0.38));
                    try sim.ry(@intCast(i), angle(seed, 1200 + layer * n + i, 0.14));
                }
            },
            else => {},
        }
    }

    fn executeCircuit(allocator: std.mem.Allocator, idx: usize, question: []const u8, category: []const u8) !f64 {
        const p = profiles[idx];
        const b = band(category);
        const target_mid = (b[0] + b[1]) / 2.0;
        const seed = seedFor(question, category, p);
        var sim = try QuantumSim.init(allocator, p.qubits);
        defer sim.deinit();
        try applyTopology(&sim, idx + 1, seed, target_mid);
        try sim.normalize();
        return @max(0.0, @min(1.0, sim.shannonEntropy() / @as(f64, @floatFromInt(p.qubits))));
    }

    fn novelty(state: *const State) [profiles.len]f64 {
        var out = [_]f64{1.0} ** profiles.len;
        if (state.recent_len == 0) return out;
        var counts = [_]u8{0} ** profiles.len;
        var max_count: u8 = 1;
        for (state.recent[0..state.recent_len]) |idx| {
            counts[idx] +|= 1;
            max_count = @max(max_count, counts[idx]);
        }
        for (&out, 0..) |*v, i| v.* = 1.0 - @as(f64, @floatFromInt(counts[i])) / @as(f64, @floatFromInt(max_count));
        return out;
    }

    fn computeRelevance(question: []const u8, category: []const u8, state: *const State) struct { rag: [profiles.len]f64, hist: [profiles.len]f64, query: [embed_dim]f64 } {
        const hint = categoryHint(category);
        const qparts = [_][]const u8{ question, category, hint };
        const query = embedding(&qparts);
        var rag = [_]f64{0} ** profiles.len;
        var hist = [_]f64{0.5} ** profiles.len;
        for (profiles, 0..) |p, i| {
            const phint = categoryHint(p.bias);
            const parts = [_][]const u8{ p.bias, p.topology, phint };
            const pv = embedding(&parts);
            rag[i] = cosine(&query, &pv);
            if (hasPriorTable(category)) rag[i] = @max(0.0, @min(1.0, 0.62 * rag[i] + 0.38 * prior(category, i)));
            hist[i] = state.circuits[i].historical_score;
        }

        var top_idx = [_]usize{0} ** 12;
        var top_sim = [_]f64{-1.0} ** 12;
        var top_score = [_]f64{-1.0} ** 12;
        var top_len: usize = 0;
        for (state.attempts[0..state.attempt_len], 0..) |attempt, ai| {
            if (attempt.clef_score < 0) continue;
            const sim = cosineAttempt(&query, &attempt);
            const reward: f64 = @as(f64, attempt.clef_score) / 100.0;
            var pos: usize = 0;
            while (pos < top_len and (top_sim[pos] > sim or (top_sim[pos] == sim and top_score[pos] >= reward))) : (pos += 1) {}
            if (pos >= 12) continue;
            const new_len = @min(top_len + 1, 12);
            var j = new_len;
            while (j > pos + 1) {
                j -= 1;
                top_idx[j] = top_idx[j - 1];
                top_sim[j] = top_sim[j - 1];
                top_score[j] = top_score[j - 1];
            }
            top_idx[pos] = ai;
            top_sim[pos] = sim;
            top_score[pos] = reward;
            top_len = new_len;
        }

        var evidence = [_]f64{0} ** profiles.len;
        var weight_sum = [_]f64{0} ** profiles.len;
        var reward_sum = [_]f64{0} ** profiles.len;
        for (0..top_len) |k| {
            const a = &state.attempts[top_idx[k]];
            const idx: usize = a.circuit_index;
            const reward: f64 = @as(f64, a.clef_score) / 100.0;
            evidence[idx] = @max(evidence[idx], top_sim[k] * reward);
            const w = @max(0.000001, top_sim[k]);
            weight_sum[idx] += w;
            reward_sum[idx] += w * reward;
        }
        for (0..profiles.len) |i| if (weight_sum[i] > 0) {
            rag[i] = @max(rag[i], evidence[i]);
            const local_hist = reward_sum[i] / weight_sum[i];
            hist[i] = 0.55 * hist[i] + 0.45 * local_hist;
        };
        return .{ .rag = rag, .hist = hist, .query = query };
    }

    fn appendRecent(state: *State, idx: u8) void {
        if (state.recent_len < recent_window) {
            state.recent[state.recent_len] = idx;
            state.recent_len += 1;
            return;
        }
        for (1..recent_window) |i| state.recent[i - 1] = state.recent[i];
        state.recent[recent_window - 1] = idx;
    }

    fn appendAttempt(state: *State, attempt: Attempt) void {
        if (state.attempt_len < max_attempts) {
            state.attempts[state.attempt_len] = attempt;
            state.attempt_len += 1;
            return;
        }
        for (1..max_attempts) |i| state.attempts[i - 1] = state.attempts[i];
        state.attempts[max_attempts - 1] = attempt;
    }

    fn makeHex(bytes: []const u8, out: []u8) void {
        const hex = "0123456789abcdef";
        for (bytes, 0..) |b, i| {
            out[i * 2] = hex[b >> 4];
            out[i * 2 + 1] = hex[b & 15];
        }
    }

    fn tokenCount(text: []const u8) usize {
        var count: usize = 0;
        var in_token = false;
        for (text) |c| {
            const alnum = std.ascii.isAlphanumeric(c);
            if (alnum and !in_token) count += 1;
            in_token = alnum;
        }
        return count;
    }

    fn makeAttemptId(question: []const u8, profile: Profile) [16]u8 {
        // Python parity: blake2b(f"{time.time_ns()}|{profile.id}|{question}", digest_size=8).hexdigest().
        var h = Blake2b64.init(.{});
        var time_buf: [48]u8 = undefined;
        const time_text = std.fmt.bufPrint(&time_buf, "{}", .{std.time.nanoTimestamp()}) catch unreachable;
        h.update(time_text);
        h.update("|");
        h.update(profile.id);
        h.update("|");
        h.update(question);
        var digest: [Blake2b64.digest_length]u8 = undefined;
        h.final(&digest);
        var out: [16]u8 = undefined;
        makeHex(&digest, &out);
        return out;
    }

    pub fn choose(allocator: std.mem.Allocator, question: []const u8, category: []const u8) !Route {
        const state = try loadState(allocator);
        defer allocator.destroy(state);
        const rel = computeRelevance(question, category, state);
        const novelty_scores = novelty(state);
        const b = band(category);
        var scores = [_]f64{0} ** profiles.len;
        for (0..profiles.len) |i| {
            const eq = entropyQuality(state.circuits[i].mean_entropy, b);
            scores[i] = 0.45 * rel.rag[i] + 0.30 * rel.hist[i] + 0.15 * novelty_scores[i] + 0.10 * eq;
        }

        var shortlist = [_]usize{0} ** shortlist_size;
        var used = [_]bool{false} ** profiles.len;
        for (0..shortlist_size) |k| {
            var best: ?usize = null;
            for (0..profiles.len) |i| {
                if (!used[i] and (best == null or rel.rag[i] > rel.rag[best.?])) best = i;
            }
            shortlist[k] = best.?;
            used[best.?] = true;
        }

        var max_scaled = -std.math.inf(f64);
        for (shortlist) |idx| max_scaled = @max(max_scaled, scores[idx] / temperature);
        var probs = [_]f64{0} ** shortlist_size;
        var total: f64 = 0;
        for (shortlist, 0..) |idx, i| {
            probs[i] = @exp(scores[idx] / temperature - max_scaled);
            total += probs[i];
        }
        for (&probs) |*p| p.* /= total;

        const rv = std.crypto.random.int(u64) >> 11;
        const unit = @as(f64, @floatFromInt(rv)) / 9007199254740992.0;
        var cursor: f64 = 0;
        var chosen_slot: usize = shortlist_size - 1;
        for (probs, 0..) |p, i| {
            cursor += p;
            if (unit <= cursor) {
                chosen_slot = i;
                break;
            }
        }
        const selected = shortlist[chosen_slot];
        const measured_entropy = executeCircuit(allocator, selected, question, category) catch blk: {
            const mid = (b[0] + b[1]) / 2.0;
            const seed = seedFor(question, category, profiles[selected]);
            const jitter = (@as(f64, @floatFromInt(seed % 10001)) / 10000.0 - 0.5) * 0.09;
            break :blk @max(0.0, @min(1.0, mid + jitter));
        };

        var stats = &state.circuits[selected];
        const runs = stats.runs;
        stats.runs +|= 1;
        stats.mean_entropy = (stats.mean_entropy * @as(f64, @floatFromInt(runs)) + measured_entropy) / @as(f64, @floatFromInt(runs + 1));
        appendRecent(state, @intCast(selected));

        var attempt = Attempt{};
        attempt.id = makeAttemptId(question, profiles[selected]);
        var qdigest: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(question, &qdigest, .{});
        makeHex(&qdigest, &attempt.question_hash);
        const cat_len = @min(category.len, attempt.category.len);
        @memcpy(attempt.category[0..cat_len], category[0..cat_len]);
        attempt.category_len = @intCast(cat_len);
        attempt.circuit_index = @intCast(selected);
        attempt.entropy = @floatCast(measured_entropy);
        attempt.token_count = @intCast(@min(tokenCount(question), @as(usize, std.math.maxInt(u32))));
        attempt.timestamp = std.time.timestamp();
        for (rel.query, 0..) |v, i| attempt.embedding[i] = @floatCast(v);
        appendAttempt(state, attempt);
        saveState(allocator, state) catch {};

        var top: [shortlist_size]Candidate = undefined;
        for (shortlist, 0..) |idx, i| top[i] = .{ .index = @intCast(idx), .probability = probs[i], .score = scores[idx] };
        for (0..shortlist_size) |i| {
            var best = i;
            for (i + 1..shortlist_size) |j| {
                if (top[j].probability > top[best].probability) best = j;
            }
            if (best != i) std.mem.swap(Candidate, &top[i], &top[best]);
        }

        return .{
            .attempt_id = attempt.id,
            .circuit_index = @intCast(selected),
            .entropy = measured_entropy,
            .entropy_lo = b[0],
            .entropy_hi = b[1],
            .entropy_quality = entropyQuality(measured_entropy, b),
            .score = scores[selected],
            .probability = probs[chosen_slot],
            .top = top,
        };
    }

    pub fn recordClef(allocator: std.mem.Allocator, score: f64, attempt_id: ?[]const u8) !Feedback {
        if (!std.math.isFinite(score) or score < 0 or score > 100) return error.InvalidClefScore;
        const state = try loadState(allocator);
        defer allocator.destroy(state);
        var target: ?usize = null;
        var i = state.attempt_len;
        while (i > 0) {
            i -= 1;
            const a = &state.attempts[i];
            if (attempt_id) |wanted| {
                if (std.mem.eql(u8, a.id[0..], wanted)) {
                    target = i;
                    break;
                }
            } else if (a.clef_score < 0) {
                target = i;
                break;
            }
        }
        const ti = target orelse return error.NoUnratedAttempt;
        var a = &state.attempts[ti];
        const idx: usize = a.circuit_index;
        var stats = &state.circuits[idx];
        const old = stats.historical_score;
        const reward = score / 100.0;
        const updated = (1.0 - history_alpha) * old + history_alpha * reward;
        stats.historical_score = updated;
        stats.clef_updates +|= 1;
        a.clef_score = @floatCast(score);
        try saveState(allocator, state);
        return .{ .attempt_id = a.id, .circuit_index = @intCast(idx), .clef_score = score, .historical_before = old, .historical_after = updated };
    }

    pub fn status(allocator: std.mem.Allocator) ![8]StatusRow {
        const state = try loadState(allocator);
        defer allocator.destroy(state);
        var rows: [profiles.len]StatusRow = undefined;
        for (profiles, 0..) |_, i| rows[i] = .{ .index = @intCast(i), .historical_score = state.circuits[i].historical_score, .mean_entropy = state.circuits[i].mean_entropy, .runs = state.circuits[i].runs, .clef_updates = state.circuits[i].clef_updates };
        for (0..rows.len) |i| {
            var best = i;
            for (i + 1..rows.len) |j| {
                const a = rows[j];
                const b = rows[best];
                if (a.historical_score > b.historical_score or
                    (a.historical_score == b.historical_score and a.clef_updates > b.clef_updates) or
                    (a.historical_score == b.historical_score and a.clef_updates == b.clef_updates and a.runs > b.runs)) best = j;
            }
            if (best != i) std.mem.swap(StatusRow, &rows[i], &rows[best]);
        }
        var top: [8]StatusRow = undefined;
        @memcpy(top[0..], rows[0..8]);
        return top;
    }

    pub fn contextAlloc(allocator: std.mem.Allocator, route: Route) ![]u8 {
        const p = profiles[route.circuit_index];
        var list = std.ArrayList(u8).empty;
        defer list.deinit(allocator);
        try list.appendSlice(allocator, "[quantum_ensemble]\n");
        try appendFmt(&list, allocator, "selected={s} qubits={} topology={s} bias={s}\n", .{ p.id, p.qubits, p.topology, p.bias });
        try appendFmt(&list, allocator, "selection_probability={d:.4} normalized_entropy={d:.4} target_band={d:.2}-{d:.2} entropy_quality={d:.3}\n", .{ route.probability, route.entropy, route.entropy_lo, route.entropy_hi, route.entropy_quality });
        try list.appendSlice(allocator, "top_candidates=");
        for (route.top, 0..) |candidate, i| {
            if (i != 0) try list.appendSlice(allocator, ", ");
            try appendFmt(&list, allocator, "{s}={d:.3}", .{ profiles[candidate.index].id, candidate.probability });
        }
        try list.appendSlice(allocator, "\nUse this as a weak stochastic preference signal, not as factual evidence.\n[/quantum_ensemble]");
        return try list.toOwnedSlice(allocator);
    }
};

// ----------------------------------------------------------------------------
// HSV/rainbow mapping from metrics, preserving the old Naza visual idea while
// keeping it explicitly a visualization transform.
// ----------------------------------------------------------------------------

pub const Rgb = struct { r: f64, g: f64, b: f64 };
pub const Hsv = struct { h: f64, s: f64, v: f64 };

pub fn hsvToRgb(hsv: Hsv) Rgb {
    const h = hsv.h - @floor(hsv.h);
    const s = EntropyScore.clamp01(hsv.s);
    const v = EntropyScore.clamp01(hsv.v);
    const x = h * 6.0;
    const i: u3 = @intFromFloat(@floor(x));
    const f = x - @floor(x);
    const p = v * (1.0 - s);
    const q = v * (1.0 - s * f);
    const t = v * (1.0 - s * (1.0 - f));
    return switch (i) {
        0 => .{ .r = v, .g = t, .b = p },
        1 => .{ .r = q, .g = v, .b = p },
        2 => .{ .r = p, .g = v, .b = t },
        3 => .{ .r = p, .g = q, .b = v },
        4 => .{ .r = t, .g = p, .b = v },
        else => .{ .r = v, .g = p, .b = q },
    };
}

pub const MetricRainbow = struct {
    hue: f64,
    saturation: f64,
    value: f64,
    rgb: Rgb,
    sync: f64,

    pub fn map(m: SystemMetrics) MetricRainbow {
        const cpu = EntropyScore.clamp01(m.cpu_percent / 100.0);
        const mem = EntropyScore.clamp01(m.memory_percent / 100.0);
        const load = EntropyScore.clamp01(m.load1 / 16.0);
        const temp = EntropyScore.clamp01((m.temperature_c - 20.0) / 80.0);
        const proc = EntropyScore.clamp01(@as(f64, @floatFromInt(m.process_count)) / 1000.0);
        const hue = @mod(0.11 * cpu + 0.23 * mem + 0.31 * load + 0.17 * temp + 0.18 * proc, 1.0);
        const sat = EntropyScore.clamp01(0.45 + 0.45 * @abs(cpu - mem));
        const val = EntropyScore.clamp01(0.55 + 0.4 * (cpu + mem + load) / 3.0);
        const sync = EntropyScore.clamp01(1.0 - (@abs(cpu - mem) + @abs(load - temp) + @abs(temp - proc)) / 3.0);
        return .{ .hue = hue, .saturation = sat, .value = val, .rgb = hsvToRgb(.{ .h = hue, .s = sat, .v = val }), .sync = sync };
    }
};

// ----------------------------------------------------------------------------
// Local PUNKD-style token analyzer: no model dependency, no Python regex.
// ----------------------------------------------------------------------------

pub const TokenWeight = struct { token_hash: [32]u8, weight: f32, count: u32 };

pub const Punkd = struct {
    fn isWordByte(b: u8) bool {
        return (b >= 'a' and b <= 'z') or (b >= 'A' and b <= 'Z') or (b >= '0' and b <= '9') or b == '_' or b >= 0x80;
    }

    fn lowerAsciiHash(token: []const u8) [32]u8 {
        var h = std.crypto.hash.sha2.Sha256.init(.{});
        for (token) |b| {
            const c = if (b >= 'A' and b <= 'Z') b + 32 else b;
            h.update(&[_]u8{c});
        }
        var out: [32]u8 = undefined;
        h.final(&out);
        return out;
    }

    pub fn analyze(allocator: std.mem.Allocator, text: []const u8, top_n: usize) ![]TokenWeight {
        var weights = std.ArrayList(TokenWeight).empty;
        defer weights.deinit(allocator);
        var i: usize = 0;
        while (i < text.len) {
            while (i < text.len and !isWordByte(text[i])) : (i += 1) {}
            const start = i;
            while (i < text.len and isWordByte(text[i])) : (i += 1) {}
            if (i == start) continue;
            const tok = text[start..i];
            const hash = lowerAsciiHash(tok);
            var found = false;
            for (weights.items) |*w| {
                if (ctEqual(&w.token_hash, &hash)) {
                    w.count += 1;
                    found = true;
                    break;
                }
            }
            if (!found) try weights.append(allocator, .{ .token_hash = hash, .weight = 0, .count = 1 });
        }
        var total: u64 = 0;
        for (weights.items) |w| total += w.count;
        for (weights.items) |*w| {
            const tf = @as(f32, @floatFromInt(w.count)) / @as(f32, @floatFromInt(@max(total, 1)));
            w.weight = @sqrt(tf) * (1.0 + @as(f32, @floatFromInt(@min(w.count, 10))) / 20.0);
        }
        // Selection sort is adequate for the small prompt-level table.
        var a: usize = 0;
        while (a < weights.items.len) : (a += 1) {
            var best = a;
            var b = a + 1;
            while (b < weights.items.len) : (b += 1) if (weights.items[b].weight > weights.items[best].weight) {
                best = b;
            };
            if (best != a) {
                const tmp = weights.items[a];
                weights.items[a] = weights.items[best];
                weights.items[best] = tmp;
            }
        }
        const take = @min(top_n, weights.items.len);
        return try allocator.dupe(TokenWeight, weights.items[0..take]);
    }

    pub fn profileTemperature(base: f32, weights: []const TokenWeight, profile: enum { precise, balanced, wild }) f32 {
        var avg: f32 = 0;
        for (weights) |w| avg += w.weight;
        if (weights.len != 0) avg /= @as(f32, @floatFromInt(weights.len));
        const factor: f32 = switch (profile) {
            .precise => 0.85,
            .balanced => 1.0,
            .wild => 1.25,
        };
        return @max(0.05, @min(2.0, base * factor * (0.9 + 0.2 * avg)));
    }
};

// ----------------------------------------------------------------------------
// Chunked generation coordinator. The callback interface allows the pure-Zig
// Llama engine to be wired in without circular dependencies.
// ----------------------------------------------------------------------------

pub const TokenGenerator = struct {
    context: *anyopaque,
    next_fn: *const fn (context: *anyopaque, prompt_tokens: []const u32, generated: []const u32, logits: []f32) anyerror!void,

    pub fn next(self: TokenGenerator, prompt_tokens: []const u32, generated: []const u32, logits: []f32) !void {
        try self.next_fn(self.context, prompt_tokens, generated, logits);
    }
};

pub const ChunkedGenerator = struct {
    pub fn run(
        allocator: std.mem.Allocator,
        engine: TokenGenerator,
        prompt: []const u32,
        vocab_size: usize,
        cfg: GenerationConfig,
        stop_tokens: []const u32,
    ) ![]u32 {
        var session = try GenerationSession.init(allocator, cfg, 256);
        defer session.deinit();
        const logits = try allocator.alloc(f32, vocab_size);
        defer allocator.free(logits);
        const top_cap = @min(@max(cfg.top_k, 1), @min(vocab_size, 1024));
        const top = try allocator.alloc(TopK.Item, top_cap);
        defer allocator.free(top);
        var generated = std.ArrayList(u32).empty;
        defer generated.deinit(allocator);
        var step: usize = 0;
        while (step < cfg.max_tokens) : (step += 1) {
            try engine.next(prompt, generated.items, logits);
            const tok = try session.choose(logits, top);
            var stop = false;
            for (stop_tokens) |s| if (s == tok) {
                stop = true;
                break;
            };
            if (stop) break;
            try generated.append(allocator, tok);
        }
        return try generated.toOwnedSlice(allocator);
    }
};

test "quantum bell state correlations" {
    var sim = try QuantumSim.init(std.testing.allocator, 2);
    defer sim.deinit();
    try sim.h(0);
    try sim.cx(0, 1);
    const zz = try sim.expZZ(0, 1);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), zz, 1e-12);
    try std.testing.expectApproxEqAbs(@as(f64, 1.0), sim.shannonEntropy(), 1e-12);
}

test "native GUI responsive layout contract" {
    try std.testing.expect(NativeGui.usesPhoneLayout(430, false));
    try std.testing.expect(!NativeGui.usesPhoneLayout(1240, false));
    try std.testing.expect(NativeGui.usesPhoneLayout(1240, true));
}

test "quantum ensemble profile contract" {
    try std.testing.expectEqual(@as(usize, 30), QuantumEnsemble.profiles.len);
    try std.testing.expectEqual(@as(f64, 0.55), QuantumEnsemble.temperature);
    try std.testing.expectEqual(@as(usize, 5), QuantumEnsemble.shortlist_size);
    for (QuantumEnsemble.profiles) |profile| {
        try std.testing.expect(profile.qubits >= 8 and profile.qubits < 15);
    }
}

test "metric rainbow bounded" {
    const r = MetricRainbow.map(.{ .cpu_percent = 50, .memory_percent = 25, .load1 = 2, .temperature_c = 45, .process_count = 100 });
    try std.testing.expect(r.hue >= 0 and r.hue < 1);
    try std.testing.expect(r.sync >= 0 and r.sync <= 1);
}

test "punkd extracts repeated token" {
    const allocator = std.testing.allocator;
    const w = try Punkd.analyze(allocator, "zig zig quantum crypto zig", 4);
    defer allocator.free(w);
    try std.testing.expect(w.len >= 1);
    try std.testing.expect(w[0].count >= 3);
}

// ============================================================================
// EXPANSION 0.4 — mixed GGUF K-quants, richer model metadata, tokenizer/model
// execution plumbing, parallel row kernels, and hash-signature machinery.
// ============================================================================

// ----------------------------------------------------------------------------
// GGML K-quant scalar decoders. These implement the portable standardized layout
// directly in Zig. They are deliberately scalar: correctness first, vectorize
// only after byte-for-byte parity tests against independent vectors.
// ----------------------------------------------------------------------------

pub const KQuant = struct {
    pub const qk: usize = 256;
    pub const k_scale_size: usize = 12;

    fn scaleMinK4(scales: *const [12]u8, j: usize) struct { scale: u8, min: u8 } {
        if (j < 4) {
            return .{ .scale = scales[j] & 63, .min = scales[j + 4] & 63 };
        }
        const scale = (scales[j + 4] & 0x0f) | ((scales[j - 4] >> 6) << 4);
        const minv = (scales[j + 4] >> 4) | ((scales[j] >> 6) << 4);
        return .{ .scale = scale, .min = minv };
    }

    pub fn rowBytes(comptime block_bytes: usize, values: usize) !usize {
        if (values % qk != 0) return error.InvalidQuantizedLength;
        return (values / qk) * block_bytes;
    }
};

pub const Q4KExact = struct {
    pub const block_values: usize = 256;
    pub const block_bytes: usize = 144;
    pub const d_offset: usize = 0;
    pub const dmin_offset: usize = 2;
    pub const scales_offset: usize = 4;
    pub const qs_offset: usize = 16;

    pub fn dequantBlock(out: *[256]f32, src: *const [block_bytes]u8) void {
        const d = f16ToF32(readU16Le(src[d_offset .. d_offset + 2]) catch unreachable);
        const dmin = f16ToF32(readU16Le(src[dmin_offset .. dmin_offset + 2]) catch unreachable);
        var scales: [12]u8 = undefined;
        @memcpy(&scales, src[scales_offset .. scales_offset + 12]);
        const qs = src[qs_offset .. qs_offset + 128];

        var group: usize = 0;
        var base: usize = 0;
        while (base < 256) : (base += 64) {
            const sm0 = KQuant.scaleMinK4(&scales, group);
            const sm1 = KQuant.scaleMinK4(&scales, group + 1);
            const d0 = d * @as(f32, @floatFromInt(sm0.scale));
            const d1 = d * @as(f32, @floatFromInt(sm1.scale));
            const m0 = dmin * @as(f32, @floatFromInt(sm0.min));
            const m1 = dmin * @as(f32, @floatFromInt(sm1.min));
            const qbase = (base / 64) * 32;
            var i: usize = 0;
            while (i < 32) : (i += 1) {
                const packed_byte = qs[qbase + i];
                out[base + i] = d0 * @as(f32, @floatFromInt(packed_byte & 0x0f)) - m0;
                out[base + 32 + i] = d1 * @as(f32, @floatFromInt(packed_byte >> 4)) - m1;
            }
            group += 2;
        }
    }

    pub fn dequantRow(out: []f32, src: []const u8) !void {
        if (out.len % block_values != 0) return error.InvalidQuantizedLength;
        const expected = try KQuant.rowBytes(block_bytes, out.len);
        if (src.len != expected) return error.InvalidQuantizedLength;
        var b: usize = 0;
        while (b < out.len / block_values) : (b += 1) {
            var raw: [block_bytes]u8 = undefined;
            @memcpy(&raw, src[b * block_bytes .. (b + 1) * block_bytes]);
            var vals: [block_values]f32 = undefined;
            dequantBlock(&vals, &raw);
            @memcpy(out[b * block_values .. (b + 1) * block_values], &vals);
        }
    }

    pub fn dotRow(src: []const u8, x: []const f32) !f32 {
        if (x.len % block_values != 0) return error.InvalidQuantizedLength;
        if (src.len != try KQuant.rowBytes(block_bytes, x.len)) return error.InvalidQuantizedLength;
        var sum: f32 = 0;
        var b: usize = 0;
        while (b < x.len / block_values) : (b += 1) {
            var raw: [block_bytes]u8 = undefined;
            @memcpy(&raw, src[b * block_bytes .. (b + 1) * block_bytes]);
            var vals: [block_values]f32 = undefined;
            dequantBlock(&vals, &raw);
            for (vals, x[b * block_values .. (b + 1) * block_values]) |w, xv| sum += w * xv;
        }
        return sum;
    }

    pub fn matvec(out: []f32, weights: []const u8, x: []const f32, rows: usize, cols: usize) !void {
        if (out.len != rows or x.len != cols) return error.ShapeMismatch;
        const rb = try KQuant.rowBytes(block_bytes, cols);
        const total_bytes = std.math.mul(usize, rows, rb) catch return error.TensorTooLarge;
        if (weights.len != total_bytes) return error.InvalidQuantizedLength;
        for (out, 0..) |*o, r| o.* = try dotRow(weights[r * rb .. (r + 1) * rb], x);
    }
};

pub const Q5KExact = struct {
    pub const block_values: usize = 256;
    pub const block_bytes: usize = 176;
    pub const d_offset: usize = 0;
    pub const dmin_offset: usize = 2;
    pub const scales_offset: usize = 4;
    pub const qh_offset: usize = 16;
    pub const qs_offset: usize = 48;

    pub fn dequantBlock(out: *[256]f32, src: *const [block_bytes]u8) void {
        const d = f16ToF32(readU16Le(src[d_offset .. d_offset + 2]) catch unreachable);
        const dmin = f16ToF32(readU16Le(src[dmin_offset .. dmin_offset + 2]) catch unreachable);
        var scales: [12]u8 = undefined;
        @memcpy(&scales, src[scales_offset .. scales_offset + 12]);
        const qh = src[qh_offset .. qh_offset + 32];
        const ql = src[qs_offset .. qs_offset + 128];

        var group: usize = 0;
        var qbase: usize = 0;
        var bit1: u8 = 1;
        var bit2: u8 = 2;
        var base: usize = 0;
        while (base < 256) : (base += 64) {
            const sm0 = KQuant.scaleMinK4(&scales, group);
            const sm1 = KQuant.scaleMinK4(&scales, group + 1);
            const d0 = d * @as(f32, @floatFromInt(sm0.scale));
            const d1 = d * @as(f32, @floatFromInt(sm1.scale));
            const m0 = dmin * @as(f32, @floatFromInt(sm0.min));
            const m1 = dmin * @as(f32, @floatFromInt(sm1.min));
            var i: usize = 0;
            while (i < 32) : (i += 1) {
                const packed_byte = ql[qbase + i];
                const lo = @as(u8, packed_byte & 0x0f) + (if ((qh[i] & bit1) != 0) @as(u8, 16) else 0);
                const hi = @as(u8, packed_byte >> 4) + (if ((qh[i] & bit2) != 0) @as(u8, 16) else 0);
                out[base + i] = d0 * @as(f32, @floatFromInt(lo)) - m0;
                out[base + 32 + i] = d1 * @as(f32, @floatFromInt(hi)) - m1;
            }
            qbase += 32;
            group += 2;
            bit1 <<= 2;
            bit2 <<= 2;
        }
    }

    pub fn dotRow(src: []const u8, x: []const f32) !f32 {
        if (x.len % block_values != 0 or src.len != try KQuant.rowBytes(block_bytes, x.len)) return error.InvalidQuantizedLength;
        var sum: f32 = 0;
        var b: usize = 0;
        while (b < x.len / block_values) : (b += 1) {
            var raw: [block_bytes]u8 = undefined;
            @memcpy(&raw, src[b * block_bytes .. (b + 1) * block_bytes]);
            var vals: [block_values]f32 = undefined;
            dequantBlock(&vals, &raw);
            for (vals, x[b * block_values .. (b + 1) * block_values]) |w, xv| sum += w * xv;
        }
        return sum;
    }

    pub fn matvec(out: []f32, weights: []const u8, x: []const f32, rows: usize, cols: usize) !void {
        if (out.len != rows or x.len != cols) return error.ShapeMismatch;
        const rb = try KQuant.rowBytes(block_bytes, cols);
        const total_bytes = std.math.mul(usize, rows, rb) catch return error.TensorTooLarge;
        if (weights.len != total_bytes) return error.InvalidQuantizedLength;
        for (out, 0..) |*o, r| o.* = try dotRow(weights[r * rb .. (r + 1) * rb], x);
    }
};

pub const Q6KExact = struct {
    pub const block_values: usize = 256;
    pub const block_bytes: usize = 210;
    pub const ql_offset: usize = 0;
    pub const qh_offset: usize = 128;
    pub const scales_offset: usize = 192;
    pub const d_offset: usize = 208;

    pub fn dequantBlock(out: *[256]f32, src: *const [block_bytes]u8) void {
        const ql = src[ql_offset .. ql_offset + 128];
        const qh = src[qh_offset .. qh_offset + 64];
        const d = f16ToF32(readU16Le(src[d_offset .. d_offset + 2]) catch unreachable);

        var scales: [16]i8 = undefined;
        var si: usize = 0;
        while (si < 16) : (si += 1) scales[si] = @bitCast(src[scales_offset + si]);

        var half: usize = 0;
        while (half < 2) : (half += 1) {
            const qlbase = half * 64;
            const qhbase = half * 32;
            const outbase = half * 128;
            var i: usize = 0;
            while (i < 32) : (i += 1) {
                const lo0: u8 = ql[qlbase + i] & 0x0f;
                const lo1: u8 = ql[qlbase + i + 32] & 0x0f;
                const lo2: u8 = ql[qlbase + i] >> 4;
                const lo3: u8 = ql[qlbase + i + 32] >> 4;
                const hb = qh[qhbase + i];
                const q0: i16 = @intCast(lo0 | ((hb & 0x03) << 4));
                const q1: i16 = @intCast(lo1 | (((hb >> 2) & 0x03) << 4));
                const q2: i16 = @intCast(lo2 | (((hb >> 4) & 0x03) << 4));
                const q3: i16 = @intCast(lo3 | (((hb >> 6) & 0x03) << 4));
                const g = half * 8;
                out[outbase + i] = d * @as(f32, @floatFromInt(scales[g + 0])) * @as(f32, @floatFromInt(q0 - 32));
                out[outbase + 32 + i] = d * @as(f32, @floatFromInt(scales[g + 2])) * @as(f32, @floatFromInt(q1 - 32));
                out[outbase + 64 + i] = d * @as(f32, @floatFromInt(scales[g + 4])) * @as(f32, @floatFromInt(q2 - 32));
                out[outbase + 96 + i] = d * @as(f32, @floatFromInt(scales[g + 6])) * @as(f32, @floatFromInt(q3 - 32));
                if (i == 15) {
                    // The scalar scale schedule changes each 16-element group.
                    // Remaining lanes are corrected below in group-wise form.
                }
            }
        }

        // Recompute using the exact 16-value group mapping. This branch-free
        // second pass is intentionally simple and avoids clever index coupling.
        var idx: usize = 0;
        while (idx < 256) : (idx += 1) {
            const section = idx / 128;
            const local = idx % 128;
            const quarter = local / 32;
            const lane = local % 32;
            const qlbase = section * 64;
            const qhbase = section * 32;
            const hb = qh[qhbase + lane];
            var raw: u8 = 0;
            raw = switch (quarter) {
                0 => (ql[qlbase + lane] & 0x0f) | ((hb & 0x03) << 4),
                1 => (ql[qlbase + 32 + lane] & 0x0f) | (((hb >> 2) & 0x03) << 4),
                2 => (ql[qlbase + lane] >> 4) | (((hb >> 4) & 0x03) << 4),
                else => (ql[qlbase + 32 + lane] >> 4) | (((hb >> 6) & 0x03) << 4),
            };
            const group = idx / 16;
            out[idx] = d * @as(f32, @floatFromInt(scales[group])) * @as(f32, @floatFromInt(@as(i16, raw) - 32));
        }
    }

    pub fn dotRow(src: []const u8, x: []const f32) !f32 {
        if (x.len % block_values != 0 or src.len != try KQuant.rowBytes(block_bytes, x.len)) return error.InvalidQuantizedLength;
        var sum: f32 = 0;
        var b: usize = 0;
        while (b < x.len / block_values) : (b += 1) {
            var raw: [block_bytes]u8 = undefined;
            @memcpy(&raw, src[b * block_bytes .. (b + 1) * block_bytes]);
            var vals: [block_values]f32 = undefined;
            dequantBlock(&vals, &raw);
            for (vals, x[b * block_values .. (b + 1) * block_values]) |w, xv| sum += w * xv;
        }
        return sum;
    }

    pub fn matvec(out: []f32, weights: []const u8, x: []const f32, rows: usize, cols: usize) !void {
        if (out.len != rows or x.len != cols) return error.ShapeMismatch;
        const rb = try KQuant.rowBytes(block_bytes, cols);
        const total_bytes = std.math.mul(usize, rows, rb) catch return error.TensorTooLarge;
        if (weights.len != total_bytes) return error.InvalidQuantizedLength;
        for (out, 0..) |*o, r| o.* = try dotRow(weights[r * rb .. (r + 1) * rb], x);
    }
};

pub const MixedLinear = struct {
    fn mulSize(a: usize, b: usize) !usize {
        return std.math.mul(usize, a, b) catch error.TensorTooLarge;
    }

    fn classicQuantRowBytes(cols: usize, bytes_per_block: usize) !usize {
        const rounded = std.math.add(usize, cols, 31) catch return error.TensorTooLarge;
        return mulSize(rounded / 32, bytes_per_block);
    }

    pub fn apply(
        out: []f32,
        input: []const f32,
        bytes: []const u8,
        ggml_type: GgmlType,
        rows: usize,
        cols: usize,
        scratch: []f32,
    ) !void {
        switch (ggml_type) {
            .q3_k => try Q3KExact.matvec(out, bytes, input, rows, cols),
            .q4_k => try Q4KExact.matvec(out, bytes, input, rows, cols),
            .q5_k => try Q5KExact.matvec(out, bytes, input, rows, cols),
            .q6_k => try Q6KExact.matvec(out, bytes, input, rows, cols),
            .q8_0, .q4_0 => try QuantizedLinear.apply(out, input, bytes, ggml_type, rows, cols, scratch),
            .f32 => {
                const elements = try mulSize(rows, cols);
                const byte_count = try mulSize(elements, 4);
                if (bytes.len != byte_count) return error.InvalidTensorBytes;
                if (scratch.len < elements) return error.BufferTooSmall;
                var i: usize = 0;
                while (i < elements) : (i += 1) {
                    scratch[i] = @bitCast(try readU32Le(bytes[i * 4 .. i * 4 + 4]));
                }
                try Linear.matmulF32(out, input, scratch[0..elements], rows, cols);
            },
            else => return error.UnsupportedTensorType,
        }
    }

    pub fn expectedBytes(ty: GgmlType, rows: usize, cols: usize) !usize {
        return switch (ty) {
            .f32 => mulSize(try mulSize(rows, cols), 4),
            .q3_k => mulSize(rows, try KQuant.rowBytes(Q3KExact.block_bytes, cols)),
            .q4_k => mulSize(rows, try KQuant.rowBytes(Q4KExact.block_bytes, cols)),
            .q5_k => mulSize(rows, try KQuant.rowBytes(Q5KExact.block_bytes, cols)),
            .q6_k => mulSize(rows, try KQuant.rowBytes(Q6KExact.block_bytes, cols)),
            .q8_0 => mulSize(rows, try classicQuantRowBytes(cols, 34)),
            .q4_0 => mulSize(rows, try classicQuantRowBytes(cols, 18)),
            else => error.UnsupportedTensorType,
        };
    }
};

test "mixed tensor byte sizing rejects integer overflow" {
    try std.testing.expectError(error.TensorTooLarge, MixedLinear.expectedBytes(.f32, std.math.maxInt(usize), 2));
    try std.testing.expectError(error.TensorTooLarge, MixedLinear.expectedBytes(.q8_0, std.math.maxInt(usize), std.math.maxInt(usize)));
}

// ----------------------------------------------------------------------------
// A complete owned GGUF metadata/index representation for model inspection.
// It bounds all attacker-controlled counts and lengths and never executes data.
// ----------------------------------------------------------------------------

pub const OwnedGgufValue = union(enum) {
    u64v: u64,
    i64v: i64,
    f64v: f64,
    boolean: bool,
    string: []u8,
    array_u32: []u32,
    array_u64: []u64,
    array_f32: []f32,
    array_string: [][]u8,

    pub fn deinit(self: *OwnedGgufValue, allocator: std.mem.Allocator) void {
        switch (self.*) {
            .string => |v| allocator.free(v),
            .array_u32 => |v| allocator.free(v),
            .array_u64 => |v| allocator.free(v),
            .array_f32 => |v| allocator.free(v),
            .array_string => |items| {
                for (items) |v| allocator.free(v);
                allocator.free(items);
            },
            else => {},
        }
        self.* = undefined;
    }
};

pub const OwnedGgufKv = struct {
    key: []u8,
    value: OwnedGgufValue,

    pub fn deinit(self: *OwnedGgufKv, allocator: std.mem.Allocator) void {
        allocator.free(self.key);
        self.value.deinit(allocator);
        self.* = undefined;
    }
};

pub const OwnedTensorInfo = struct {
    name: []u8,
    dims: []u64,
    ggml_type: GgmlType,
    offset: u64,
    elements: u64,
    bytes: u64,

    pub fn deinit(self: *OwnedTensorInfo, allocator: std.mem.Allocator) void {
        allocator.free(self.name);
        allocator.free(self.dims);
        self.* = undefined;
    }
};

pub const GgufIndex = struct {
    allocator: std.mem.Allocator,
    version: u32,
    alignment: u64,
    data_start: u64,
    metadata: std.ArrayList(OwnedGgufKv),
    tensors: std.ArrayList(OwnedTensorInfo),

    pub fn init(allocator: std.mem.Allocator) GgufIndex {
        return .{
            .allocator = allocator,
            .version = 0,
            .alignment = 32,
            .data_start = 0,
            .metadata = .empty,
            .tensors = .empty,
        };
    }

    pub fn deinit(self: *GgufIndex) void {
        for (self.metadata.items) |*kv| kv.deinit(self.allocator);
        for (self.tensors.items) |*t| t.deinit(self.allocator);
        self.metadata.deinit(self.allocator);
        self.tensors.deinit(self.allocator);
        self.* = undefined;
    }

    pub fn findKv(self: *const GgufIndex, key: []const u8) ?*const OwnedGgufValue {
        for (self.metadata.items) |*kv| if (std.mem.eql(u8, kv.key, key)) return &kv.value;
        return null;
    }

    pub fn findTensor(self: *const GgufIndex, name: []const u8) ?*const OwnedTensorInfo {
        for (self.tensors.items) |*t| if (std.mem.eql(u8, t.name, name)) return t;
        return null;
    }

    pub fn requireTensor(self: *const GgufIndex, name: []const u8) !*const OwnedTensorInfo {
        return self.findTensor(name) orelse error.MissingRequiredTensor;
    }

    pub fn string(self: *const GgufIndex, key: []const u8) ?[]const u8 {
        const v = self.findKv(key) orelse return null;
        return switch (v.*) {
            .string => |sval| sval,
            else => null,
        };
    }

    pub fn integer(self: *const GgufIndex, key: []const u8) ?u64 {
        const v = self.findKv(key) orelse return null;
        return switch (v.*) {
            .u64v => |x| x,
            .i64v => |x| if (x >= 0) @intCast(x) else null,
            else => null,
        };
    }
};

// ----------------------------------------------------------------------------
// Llama architecture metadata and tensor naming. This stays data-driven so the
// runtime can reject incompatible GGUFs before allocating multi-gigabyte buffers.
// ----------------------------------------------------------------------------

pub const LlamaArch = struct {
    context_length: usize,
    embedding_length: usize,
    feed_forward_length: usize,
    block_count: usize,
    head_count: usize,
    head_count_kv: usize,
    rope_dim: usize,
    rope_base: f32,
    rms_epsilon: f32,
    vocab_size: usize,

    pub fn validate(self: LlamaArch) !void {
        if (self.context_length == 0 or self.context_length > 1024 * 1024) return error.InvalidModelConfig;
        if (self.embedding_length == 0 or self.embedding_length > 131072) return error.InvalidModelConfig;
        if (self.feed_forward_length < self.embedding_length) return error.InvalidModelConfig;
        if (self.block_count == 0 or self.block_count > 1024) return error.InvalidModelConfig;
        if (self.head_count == 0 or self.embedding_length % self.head_count != 0) return error.InvalidModelConfig;
        if (self.head_count_kv == 0 or self.head_count % self.head_count_kv != 0) return error.InvalidModelConfig;
        if (self.rope_dim == 0 or self.rope_dim > self.embedding_length / self.head_count) return error.InvalidModelConfig;
        if (self.vocab_size == 0 or self.vocab_size > 16 * 1024 * 1024) return error.InvalidModelConfig;
        if (!(self.rms_epsilon > 0)) return error.InvalidModelConfig;
    }

    pub fn headDim(self: LlamaArch) usize {
        return self.embedding_length / self.head_count;
    }
    pub fn kvDim(self: LlamaArch) usize {
        return self.headDim() * self.head_count_kv;
    }
    pub fn groupSize(self: LlamaArch) usize {
        return self.head_count / self.head_count_kv;
    }
};

pub const LlamaTensorNames = struct {
    pub fn attentionNorm(buf: []u8, layer: usize) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.attn_norm.weight", .{layer});
    }
    pub fn attentionQ(buf: []u8, layer: usize) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.attn_q.weight", .{layer});
    }
    pub fn attentionK(buf: []u8, layer: usize) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.attn_k.weight", .{layer});
    }
    pub fn attentionV(buf: []u8, layer: usize) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.attn_v.weight", .{layer});
    }
    pub fn attentionOutput(buf: []u8, layer: usize) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.attn_output.weight", .{layer});
    }
    pub fn ffnNorm(buf: []u8, layer: usize) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.ffn_norm.weight", .{layer});
    }
    pub fn ffnGate(buf: []u8, layer: usize) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.ffn_gate.weight", .{layer});
    }
    pub fn ffnUp(buf: []u8, layer: usize) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.ffn_up.weight", .{layer});
    }
    pub fn ffnDown(buf: []u8, layer: usize) ![]const u8 {
        return try std.fmt.bufPrint(buf, "blk.{}.ffn_down.weight", .{layer});
    }
};

pub const TensorShape = struct {
    dims: [4]usize = [_]usize{1} ** 4,
    rank: u3 = 0,

    pub fn elements(self: TensorShape) !usize {
        var n: usize = 1;
        var i: usize = 0;
        while (i < self.rank) : (i += 1) n = std.math.mul(usize, n, self.dims[i]) catch return error.TensorTooLarge;
        return n;
    }

    pub fn matrixRows(self: TensorShape) !usize {
        if (self.rank != 2) return error.ShapeMismatch;
        return self.dims[1];
    }

    pub fn matrixCols(self: TensorShape) !usize {
        if (self.rank != 2) return error.ShapeMismatch;
        return self.dims[0];
    }
};

pub const LayerTensorSpec = struct {
    name: []const u8,
    rows: usize,
    cols: usize,
    optional: bool = false,
};

pub const LlamaModelValidator = struct {
    pub fn validateCore(index: *const GgufIndex, arch: LlamaArch) !void {
        try arch.validate();
        const emb = try index.requireTensor("token_embd.weight");
        if (emb.dims.len != 2) return error.ShapeMismatch;
        if (emb.dims[0] != arch.embedding_length or emb.dims[1] != arch.vocab_size) return error.ShapeMismatch;

        const norm = try index.requireTensor("output_norm.weight");
        if (norm.dims.len != 1 or norm.dims[0] != arch.embedding_length) return error.ShapeMismatch;

        if (index.findTensor("output.weight")) |out| {
            if (out.dims.len != 2 or out.dims[0] != arch.embedding_length or out.dims[1] != arch.vocab_size) return error.ShapeMismatch;
        }

        var layer: usize = 0;
        var buf: [96]u8 = undefined;
        while (layer < arch.block_count) : (layer += 1) {
            const an = try index.requireTensor(try LlamaTensorNames.attentionNorm(&buf, layer));
            if (an.dims.len != 1 or an.dims[0] != arch.embedding_length) return error.ShapeMismatch;
            const q = try index.requireTensor(try LlamaTensorNames.attentionQ(&buf, layer));
            if (q.dims.len != 2 or q.dims[0] != arch.embedding_length or q.dims[1] != arch.embedding_length) return error.ShapeMismatch;
            const k = try index.requireTensor(try LlamaTensorNames.attentionK(&buf, layer));
            if (k.dims.len != 2 or k.dims[0] != arch.embedding_length or k.dims[1] != arch.kvDim()) return error.ShapeMismatch;
            const v = try index.requireTensor(try LlamaTensorNames.attentionV(&buf, layer));
            if (v.dims.len != 2 or v.dims[0] != arch.embedding_length or v.dims[1] != arch.kvDim()) return error.ShapeMismatch;
            const ao = try index.requireTensor(try LlamaTensorNames.attentionOutput(&buf, layer));
            if (ao.dims.len != 2 or ao.dims[0] != arch.embedding_length or ao.dims[1] != arch.embedding_length) return error.ShapeMismatch;
            const fnorm = try index.requireTensor(try LlamaTensorNames.ffnNorm(&buf, layer));
            if (fnorm.dims.len != 1 or fnorm.dims[0] != arch.embedding_length) return error.ShapeMismatch;
            const gate = try index.requireTensor(try LlamaTensorNames.ffnGate(&buf, layer));
            const up = try index.requireTensor(try LlamaTensorNames.ffnUp(&buf, layer));
            const down = try index.requireTensor(try LlamaTensorNames.ffnDown(&buf, layer));
            if (gate.dims.len != 2 or up.dims.len != 2 or down.dims.len != 2) return error.ShapeMismatch;
            if (gate.dims[0] != arch.embedding_length or gate.dims[1] != arch.feed_forward_length) return error.ShapeMismatch;
            if (up.dims[0] != arch.embedding_length or up.dims[1] != arch.feed_forward_length) return error.ShapeMismatch;
            if (down.dims[0] != arch.feed_forward_length or down.dims[1] != arch.embedding_length) return error.ShapeMismatch;
        }
    }
};

// ----------------------------------------------------------------------------
// RoPE helpers for grouped-query attention and Llama-style interleaved pairs.
// ----------------------------------------------------------------------------

pub const LlamaRope = struct {
    pub fn applyInPlace(vec: []f32, position: usize, head_count: usize, head_dim: usize, rope_dim: usize, base: f32) !void {
        if (vec.len != head_count * head_dim or rope_dim > head_dim or rope_dim % 2 != 0) return error.ShapeMismatch;
        var h: usize = 0;
        while (h < head_count) : (h += 1) {
            const head = vec[h * head_dim .. (h + 1) * head_dim];
            var i: usize = 0;
            while (i < rope_dim) : (i += 2) {
                const exponent = @as(f32, @floatFromInt(i)) / @as(f32, @floatFromInt(rope_dim));
                const theta = @as(f32, @floatFromInt(position)) / std.math.pow(f32, base, exponent);
                const c = @cos(theta);
                const sn = @sin(theta);
                const x0 = head[i];
                const x1 = head[i + 1];
                head[i] = x0 * c - x1 * sn;
                head[i + 1] = x0 * sn + x1 * c;
            }
        }
    }
};

// ----------------------------------------------------------------------------
// GQA attention over a ring-style KV cache. It operates one token at a time and
// uses caller-owned scratch, avoiding hidden allocation in the hot path.
// ----------------------------------------------------------------------------

pub const GqaCache = struct {
    allocator: std.mem.Allocator,
    layers: usize,
    context: usize,
    kv_heads: usize,
    head_dim: usize,
    keys: []f32,
    values: []f32,
    length: usize = 0,

    pub fn init(allocator: std.mem.Allocator, layers: usize, context: usize, kv_heads: usize, head_dim: usize) !GqaCache {
        const per_layer = std.math.mul(usize, context, kv_heads * head_dim) catch return error.BufferTooLarge;
        const all = std.math.mul(usize, layers, per_layer) catch return error.BufferTooLarge;
        const keys = try allocator.alloc(f32, all);
        errdefer allocator.free(keys);
        const vals = try allocator.alloc(f32, all);
        @memset(keys, 0);
        @memset(vals, 0);
        return .{ .allocator = allocator, .layers = layers, .context = context, .kv_heads = kv_heads, .head_dim = head_dim, .keys = keys, .values = vals };
    }

    pub fn deinit(self: *GqaCache) void {
        @memset(self.keys, 0);
        @memset(self.values, 0);
        self.allocator.free(self.keys);
        self.allocator.free(self.values);
        self.* = undefined;
    }

    fn slot(self: GqaCache, layer: usize, position: usize, kv_head: usize) !usize {
        if (layer >= self.layers or position >= self.context or kv_head >= self.kv_heads) return error.IndexOutOfBounds;
        return (((layer * self.context + position) * self.kv_heads) + kv_head) * self.head_dim;
    }

    pub fn write(self: *GqaCache, layer: usize, position: usize, key: []const f32, value: []const f32) !void {
        if (key.len != self.kv_heads * self.head_dim or value.len != key.len) return error.ShapeMismatch;
        if (position >= self.context) return error.ContextExceeded;
        var kh: usize = 0;
        while (kh < self.kv_heads) : (kh += 1) {
            const dst = try self.slot(layer, position, kh);
            @memcpy(self.keys[dst .. dst + self.head_dim], key[kh * self.head_dim .. (kh + 1) * self.head_dim]);
            @memcpy(self.values[dst .. dst + self.head_dim], value[kh * self.head_dim .. (kh + 1) * self.head_dim]);
        }
        self.length = @max(self.length, position + 1);
    }

    pub fn attend(
        self: *const GqaCache,
        out: []f32,
        query: []const f32,
        layer: usize,
        position: usize,
        q_heads: usize,
        scores: []f32,
    ) !void {
        if (q_heads == 0 or q_heads % self.kv_heads != 0) return error.ShapeMismatch;
        if (query.len != q_heads * self.head_dim or out.len != query.len) return error.ShapeMismatch;
        if (position >= self.length or position >= self.context) return error.IndexOutOfBounds;
        if (scores.len < position + 1) return error.BufferTooSmall;
        @memset(out, 0);
        const group = q_heads / self.kv_heads;
        const scale = 1.0 / @sqrt(@as(f32, @floatFromInt(self.head_dim)));

        var qh: usize = 0;
        while (qh < q_heads) : (qh += 1) {
            const kvh = qh / group;
            const qv = query[qh * self.head_dim .. (qh + 1) * self.head_dim];
            var t: usize = 0;
            while (t <= position) : (t += 1) {
                const off = try self.slot(layer, t, kvh);
                var sc: f32 = 0;
                var d: usize = 0;
                while (d < self.head_dim) : (d += 1) sc += qv[d] * self.keys[off + d];
                scores[t] = sc * scale;
            }
            softmaxInPlace(scores[0 .. position + 1]);
            t = 0;
            while (t <= position) : (t += 1) {
                const off = try self.slot(layer, t, kvh);
                const p = scores[t];
                var d: usize = 0;
                while (d < self.head_dim) : (d += 1) out[qh * self.head_dim + d] += p * self.values[off + d];
            }
        }
    }
};

// ----------------------------------------------------------------------------
// Tokenizer support for Llama-3 style byte-level BPE metadata. The model GGUF
// remains the source of truth; these helpers avoid hard-coding Python tokenizers.
// ----------------------------------------------------------------------------

pub const TokenPiece = struct {
    bytes: []const u8,
    score: f32 = 0,
    kind: enum { normal, unknown, control, user_defined, unused, byte } = .normal,
};

pub const SpecialTokenSet = struct {
    bos: ?u32 = null,
    eos: ?u32 = null,
    eot: ?u32 = null,
    padding: ?u32 = null,
    unknown: ?u32 = null,
};

pub const Llama3Prompt = struct {
    pub const begin_of_text = "<|begin_of_text|>";
    pub const start_header = "<|start_header_id|>";
    pub const end_header = "<|end_header_id|>";
    pub const eot = "<|eot_id|>";

    pub fn appendHeader(list: *std.ArrayList(u8), allocator: std.mem.Allocator, role: []const u8) !void {
        try list.appendSlice(allocator, start_header);
        try list.appendSlice(allocator, role);
        try list.appendSlice(allocator, end_header);
        try list.appendSlice(allocator, "\n\n");
    }

    pub fn appendMessage(list: *std.ArrayList(u8), allocator: std.mem.Allocator, role: []const u8, content: []const u8) !void {
        try appendHeader(list, allocator, role);
        try list.appendSlice(allocator, content);
        try list.appendSlice(allocator, eot);
    }

    pub fn build(allocator: std.mem.Allocator, system: ?[]const u8, messages: []const ChatMessage) ![]u8 {
        var out = std.ArrayList(u8).empty;
        errdefer out.deinit(allocator);
        try out.appendSlice(allocator, begin_of_text);
        if (system) |sys| try appendMessage(&out, allocator, "system", sys);
        for (messages) |m| {
            const role = switch (m.role) {
                .system => "system",
                .user => "user",
                .assistant => "assistant",
            };
            try appendMessage(&out, allocator, role, m.text);
        }
        try appendHeader(&out, allocator, "assistant");
        return try out.toOwnedSlice(allocator);
    }
};

pub const ByteFallback = struct {
    pub fn tokenText(buf: *[6]u8, byte: u8) []const u8 {
        const hex = "0123456789ABCDEF";
        buf[0] = '<';
        buf[1] = '0';
        buf[2] = 'x';
        buf[3] = hex[byte >> 4];
        buf[4] = hex[byte & 0x0f];
        buf[5] = '>';
        return buf[0..6];
    }

    pub fn parse(piece: []const u8) ?u8 {
        if (piece.len != 6 or piece[0] != '<' or piece[1] != '0' or piece[2] != 'x' or piece[5] != '>') return null;
        const hi = std.fmt.charToDigit(piece[3], 16) catch return null;
        const lo = std.fmt.charToDigit(piece[4], 16) catch return null;
        return @intCast(hi * 16 + lo);
    }
};

// ----------------------------------------------------------------------------
// Incremental detokenizer. It handles raw byte fallback tokens and buffers
// incomplete UTF-8 boundaries so streamed chat output never emits invalid text.
// ----------------------------------------------------------------------------

pub const Detokenizer = struct {
    pending: [4]u8 = undefined,
    pending_len: usize = 0,

    pub fn reset(self: *Detokenizer) void {
        self.pending_len = 0;
    }

    fn expectedUtf8Len(first: u8) usize {
        if (first < 0x80) return 1;
        if ((first & 0xe0) == 0xc0) return 2;
        if ((first & 0xf0) == 0xe0) return 3;
        if ((first & 0xf8) == 0xf0) return 4;
        return 1;
    }

    pub fn push(self: *Detokenizer, writer: anytype, piece: []const u8) !void {
        if (ByteFallback.parse(piece)) |b| {
            try self.pushBytes(writer, &[_]u8{b});
            return;
        }
        try self.pushBytes(writer, piece);
    }

    pub fn pushBytes(self: *Detokenizer, writer: anytype, bytes: []const u8) !void {
        var i: usize = 0;
        while (i < bytes.len) {
            if (self.pending_len == 0 and bytes[i] < 0x80) {
                try writer.writeByte(bytes[i]);
                i += 1;
                continue;
            }
            if (self.pending_len == 0) {
                self.pending[0] = bytes[i];
                self.pending_len = 1;
                i += 1;
            }
            const need = expectedUtf8Len(self.pending[0]);
            while (self.pending_len < need and i < bytes.len) : (i += 1) {
                self.pending[self.pending_len] = bytes[i];
                self.pending_len += 1;
            }
            if (self.pending_len == need) {
                if (std.unicode.utf8ValidateSlice(self.pending[0..need])) {
                    try writer.writeAll(self.pending[0..need]);
                } else {
                    try writer.writeAll("\xef\xbf\xbd");
                }
                self.pending_len = 0;
            }
        }
    }

    pub fn finish(self: *Detokenizer, writer: anytype) !void {
        if (self.pending_len != 0) {
            try writer.writeAll("\xef\xbf\xbd");
            self.pending_len = 0;
        }
    }
};

// ----------------------------------------------------------------------------
// Pure-Zig bounded worker fanout for independent output rows. This is an
// optional optimization and keeps scalar kernels as the canonical implementation.
// ----------------------------------------------------------------------------

pub const ParallelMatvec = struct {
    const Job = struct {
        out: []f32,
        weights: []const u8,
        input: []const f32,
        ty: GgmlType,
        rows: usize,
        cols: usize,
        row_start: usize,
        row_end: usize,
        err: ?anyerror = null,
    };

    fn worker(job: *Job) void {
        const local_rows = job.row_end - job.row_start;
        const rb = switch (job.ty) {
            .q3_k => KQuant.rowBytes(Q3KExact.block_bytes, job.cols) catch {
                job.err = error.InvalidQuantizedLength;
                return;
            },
            .q4_k => KQuant.rowBytes(Q4KExact.block_bytes, job.cols) catch {
                job.err = error.InvalidQuantizedLength;
                return;
            },
            .q5_k => KQuant.rowBytes(Q5KExact.block_bytes, job.cols) catch {
                job.err = error.InvalidQuantizedLength;
                return;
            },
            .q6_k => KQuant.rowBytes(Q6KExact.block_bytes, job.cols) catch {
                job.err = error.InvalidQuantizedLength;
                return;
            },
            else => {
                job.err = error.UnsupportedTensorType;
                return;
            },
        };
        const slice = job.weights[job.row_start * rb .. job.row_end * rb];
        const out = job.out[job.row_start..job.row_end];
        switch (job.ty) {
            .q3_k => Q3KExact.matvec(out, slice, job.input, local_rows, job.cols) catch |e| {
                job.err = e;
            },
            .q4_k => Q4KExact.matvec(out, slice, job.input, local_rows, job.cols) catch |e| {
                job.err = e;
            },
            .q5_k => Q5KExact.matvec(out, slice, job.input, local_rows, job.cols) catch |e| {
                job.err = e;
            },
            .q6_k => Q6KExact.matvec(out, slice, job.input, local_rows, job.cols) catch |e| {
                job.err = e;
            },
            else => unreachable,
        }
    }

    pub fn run(allocator: std.mem.Allocator, out: []f32, weights: []const u8, input: []const f32, ty: GgmlType, rows: usize, cols: usize, requested_threads: usize) !void {
        if (out.len != rows or input.len != cols) return error.ShapeMismatch;
        const threads_n = @min(@max(requested_threads, 1), @min(rows, 64));
        if (threads_n == 1) {
            return switch (ty) {
                .q3_k => Q3KExact.matvec(out, weights, input, rows, cols),
                .q4_k => Q4KExact.matvec(out, weights, input, rows, cols),
                .q5_k => Q5KExact.matvec(out, weights, input, rows, cols),
                .q6_k => Q6KExact.matvec(out, weights, input, rows, cols),
                else => error.UnsupportedTensorType,
            };
        }
        const jobs = try allocator.alloc(Job, threads_n);
        defer allocator.free(jobs);
        const threads = try allocator.alloc(std.Thread, threads_n);
        defer allocator.free(threads);

        var launched: usize = 0;
        errdefer {
            var j: usize = 0;
            while (j < launched) : (j += 1) threads[j].join();
        }

        var t: usize = 0;
        while (t < threads_n) : (t += 1) {
            const start = rows * t / threads_n;
            const end = rows * (t + 1) / threads_n;
            jobs[t] = .{ .out = out, .weights = weights, .input = input, .ty = ty, .rows = rows, .cols = cols, .row_start = start, .row_end = end };
            threads[t] = try std.Thread.spawn(.{}, worker, .{&jobs[t]});
            launched += 1;
        }
        t = 0;
        while (t < threads_n) : (t += 1) threads[t].join();
        for (jobs) |job| if (job.err) |e| return e;
    }
};

// ----------------------------------------------------------------------------
// Mixed-quant tensor views and one-token Llama execution. Tensor bytes remain
// borrowed from caller-owned storage; no hidden file mapping or C runtime.
// ----------------------------------------------------------------------------

pub const MatrixView = struct {
    bytes: []const u8,
    ty: GgmlType,
    rows: usize,
    cols: usize,

    pub fn validate(self: MatrixView) !void {
        if (self.rows == 0 or self.cols == 0) return error.ShapeMismatch;
        const expected = try MixedLinear.expectedBytes(self.ty, self.rows, self.cols);
        if (self.bytes.len != expected) return error.InvalidTensorBytes;
    }

    pub fn apply(self: MatrixView, out: []f32, input: []const f32, scratch: []f32) !void {
        try self.validate();
        if (out.len != self.rows or input.len != self.cols) return error.ShapeMismatch;
        try MixedLinear.apply(out, input, self.bytes, self.ty, self.rows, self.cols, scratch);
    }
};

pub const VectorView = struct {
    bytes: []const u8,
    ty: GgmlType,
    len: usize,

    pub fn decode(self: VectorView, out: []f32) !void {
        if (out.len != self.len) return error.ShapeMismatch;
        switch (self.ty) {
            .f32 => {
                if (self.bytes.len != self.len * 4) return error.InvalidTensorBytes;
                var i: usize = 0;
                while (i < self.len) : (i += 1) out[i] = @bitCast(try readU32Le(self.bytes[i * 4 .. i * 4 + 4]));
            },
            .f16 => {
                if (self.bytes.len != self.len * 2) return error.InvalidTensorBytes;
                var i: usize = 0;
                while (i < self.len) : (i += 1) out[i] = f16ToF32(try readU16Le(self.bytes[i * 2 .. i * 2 + 2]));
            },
            else => return error.UnsupportedTensorType,
        }
    }
};

pub const EmbeddingView = struct {
    bytes: []const u8,
    ty: GgmlType,
    vocab: usize,
    hidden: usize,

    pub fn lookup(self: EmbeddingView, out: []f32, token: u32) !void {
        if (out.len != self.hidden or token >= self.vocab) return error.ShapeMismatch;
        const row: usize = @intCast(token);
        switch (self.ty) {
            .f32 => {
                const rb = self.hidden * 4;
                if (self.bytes.len != self.vocab * rb) return error.InvalidTensorBytes;
                var i: usize = 0;
                const slice = self.bytes[row * rb .. (row + 1) * rb];
                while (i < self.hidden) : (i += 1) out[i] = @bitCast(try readU32Le(slice[i * 4 .. i * 4 + 4]));
            },
            .f16 => {
                const rb = self.hidden * 2;
                if (self.bytes.len != self.vocab * rb) return error.InvalidTensorBytes;
                var i: usize = 0;
                const slice = self.bytes[row * rb .. (row + 1) * rb];
                while (i < self.hidden) : (i += 1) out[i] = f16ToF32(try readU16Le(slice[i * 2 .. i * 2 + 2]));
            },
            .q3_k => {
                const rb = try KQuant.rowBytes(Q3KExact.block_bytes, self.hidden);
                if (self.bytes.len != self.vocab * rb) return error.InvalidTensorBytes;
                try Q3KExact.dequantRow(out, self.bytes[row * rb .. (row + 1) * rb]);
            },
            .q4_k => {
                const rb = try KQuant.rowBytes(Q4KExact.block_bytes, self.hidden);
                if (self.bytes.len != self.vocab * rb) return error.InvalidTensorBytes;
                var b: usize = 0;
                while (b < self.hidden / 256) : (b += 1) {
                    var raw: [Q4KExact.block_bytes]u8 = undefined;
                    @memcpy(&raw, self.bytes[row * rb + b * Q4KExact.block_bytes .. row * rb + (b + 1) * Q4KExact.block_bytes]);
                    var vals: [256]f32 = undefined;
                    Q4KExact.dequantBlock(&vals, &raw);
                    @memcpy(out[b * 256 .. (b + 1) * 256], &vals);
                }
            },
            .q5_k => {
                const rb = try KQuant.rowBytes(Q5KExact.block_bytes, self.hidden);
                if (self.bytes.len != self.vocab * rb) return error.InvalidTensorBytes;
                var b: usize = 0;
                while (b < self.hidden / 256) : (b += 1) {
                    var raw: [Q5KExact.block_bytes]u8 = undefined;
                    @memcpy(&raw, self.bytes[row * rb + b * Q5KExact.block_bytes .. row * rb + (b + 1) * Q5KExact.block_bytes]);
                    var vals: [256]f32 = undefined;
                    Q5KExact.dequantBlock(&vals, &raw);
                    @memcpy(out[b * 256 .. (b + 1) * 256], &vals);
                }
            },
            .q6_k => {
                const rb = try KQuant.rowBytes(Q6KExact.block_bytes, self.hidden);
                if (self.bytes.len != self.vocab * rb) return error.InvalidTensorBytes;
                var b: usize = 0;
                while (b < self.hidden / 256) : (b += 1) {
                    var raw: [Q6KExact.block_bytes]u8 = undefined;
                    @memcpy(&raw, self.bytes[row * rb + b * Q6KExact.block_bytes .. row * rb + (b + 1) * Q6KExact.block_bytes]);
                    var vals: [256]f32 = undefined;
                    Q6KExact.dequantBlock(&vals, &raw);
                    @memcpy(out[b * 256 .. (b + 1) * 256], &vals);
                }
            },
            else => return error.UnsupportedTensorType,
        }
    }
};

pub const LlamaLayerView = struct {
    attn_norm: []const f32,
    wq: MatrixView,
    wk: MatrixView,
    wv: MatrixView,
    wo: MatrixView,
    ffn_norm: []const f32,
    gate: MatrixView,
    up: MatrixView,
    down: MatrixView,

    pub fn validate(self: LlamaLayerView, arch: LlamaArch) !void {
        if (self.attn_norm.len != arch.embedding_length or self.ffn_norm.len != arch.embedding_length) return error.ShapeMismatch;
        if (self.wq.rows != arch.embedding_length or self.wq.cols != arch.embedding_length) return error.ShapeMismatch;
        if (self.wk.rows != arch.kvDim() or self.wk.cols != arch.embedding_length) return error.ShapeMismatch;
        if (self.wv.rows != arch.kvDim() or self.wv.cols != arch.embedding_length) return error.ShapeMismatch;
        if (self.wo.rows != arch.embedding_length or self.wo.cols != arch.embedding_length) return error.ShapeMismatch;
        if (self.gate.rows != arch.feed_forward_length or self.gate.cols != arch.embedding_length) return error.ShapeMismatch;
        if (self.up.rows != arch.feed_forward_length or self.up.cols != arch.embedding_length) return error.ShapeMismatch;
        if (self.down.rows != arch.embedding_length or self.down.cols != arch.feed_forward_length) return error.ShapeMismatch;
        try self.wq.validate();
        try self.wk.validate();
        try self.wv.validate();
        try self.wo.validate();
        try self.gate.validate();
        try self.up.validate();
        try self.down.validate();
    }
};

pub const LlamaStepScratch = struct {
    allocator: std.mem.Allocator,
    norm: []f32,
    q: []f32,
    k: []f32,
    v: []f32,
    attn: []f32,
    projected: []f32,
    ffn_normed: []f32,
    gate: []f32,
    up: []f32,
    activated: []f32,
    down: []f32,
    scores: []f32,
    matrix: []f32,

    pub fn init(allocator: std.mem.Allocator, arch: LlamaArch) !LlamaStepScratch {
        try arch.validate();
        const hidden = arch.embedding_length;
        const kv = arch.kvDim();
        const ffn = arch.feed_forward_length;
        const matrix_need = @max(
            @max(hidden * hidden, hidden * kv),
            @max(hidden * ffn, ffn * hidden),
        );
        var self: LlamaStepScratch = undefined;
        self.allocator = allocator;
        self.norm = try allocator.alloc(f32, hidden);
        errdefer allocator.free(self.norm);
        self.q = try allocator.alloc(f32, hidden);
        errdefer allocator.free(self.q);
        self.k = try allocator.alloc(f32, kv);
        errdefer allocator.free(self.k);
        self.v = try allocator.alloc(f32, kv);
        errdefer allocator.free(self.v);
        self.attn = try allocator.alloc(f32, hidden);
        errdefer allocator.free(self.attn);
        self.projected = try allocator.alloc(f32, hidden);
        errdefer allocator.free(self.projected);
        self.ffn_normed = try allocator.alloc(f32, hidden);
        errdefer allocator.free(self.ffn_normed);
        self.gate = try allocator.alloc(f32, ffn);
        errdefer allocator.free(self.gate);
        self.up = try allocator.alloc(f32, ffn);
        errdefer allocator.free(self.up);
        self.activated = try allocator.alloc(f32, ffn);
        errdefer allocator.free(self.activated);
        self.down = try allocator.alloc(f32, hidden);
        errdefer allocator.free(self.down);
        self.scores = try allocator.alloc(f32, arch.context_length);
        errdefer allocator.free(self.scores);
        self.matrix = try allocator.alloc(f32, matrix_need);
        return self;
    }

    pub fn deinit(self: *LlamaStepScratch) void {
        self.allocator.free(self.norm);
        self.allocator.free(self.q);
        self.allocator.free(self.k);
        self.allocator.free(self.v);
        self.allocator.free(self.attn);
        self.allocator.free(self.projected);
        self.allocator.free(self.ffn_normed);
        self.allocator.free(self.gate);
        self.allocator.free(self.up);
        self.allocator.free(self.activated);
        self.allocator.free(self.down);
        self.allocator.free(self.scores);
        self.allocator.free(self.matrix);
        self.* = undefined;
    }
};

pub const LlamaLayerExecutor = struct {
    pub fn step(
        state: []f32,
        layer: LlamaLayerView,
        arch: LlamaArch,
        layer_index: usize,
        position: usize,
        cache: *GqaCache,
        scratch: *LlamaStepScratch,
    ) !void {
        try layer.validate(arch);
        if (state.len != arch.embedding_length or layer_index >= arch.block_count or position >= arch.context_length) return error.ShapeMismatch;

        try rmsNorm(scratch.norm, state, layer.attn_norm, arch.rms_epsilon);
        try layer.wq.apply(scratch.q, scratch.norm, scratch.matrix);
        try layer.wk.apply(scratch.k, scratch.norm, scratch.matrix);
        try layer.wv.apply(scratch.v, scratch.norm, scratch.matrix);

        try LlamaRope.applyInPlace(scratch.q, position, arch.head_count, arch.headDim(), arch.rope_dim, arch.rope_base);
        try LlamaRope.applyInPlace(scratch.k, position, arch.head_count_kv, arch.headDim(), arch.rope_dim, arch.rope_base);
        try cache.write(layer_index, position, scratch.k, scratch.v);
        try cache.attend(scratch.attn, scratch.q, layer_index, position, arch.head_count, scratch.scores);
        try layer.wo.apply(scratch.projected, scratch.attn, scratch.matrix);

        var i: usize = 0;
        while (i < state.len) : (i += 1) state[i] += scratch.projected[i];

        try rmsNorm(scratch.ffn_normed, state, layer.ffn_norm, arch.rms_epsilon);
        try layer.gate.apply(scratch.gate, scratch.ffn_normed, scratch.matrix);
        try layer.up.apply(scratch.up, scratch.ffn_normed, scratch.matrix);
        try swiglu(scratch.activated, scratch.gate, scratch.up);
        try layer.down.apply(scratch.down, scratch.activated, scratch.matrix);

        i = 0;
        while (i < state.len) : (i += 1) state[i] += scratch.down[i];
    }
};

pub const LlamaModelView = struct {
    arch: LlamaArch,
    embedding: EmbeddingView,
    layers: []const LlamaLayerView,
    final_norm: []const f32,
    output: MatrixView,

    pub fn validate(self: LlamaModelView) !void {
        try self.arch.validate();
        if (self.layers.len != self.arch.block_count) return error.ShapeMismatch;
        if (self.embedding.hidden != self.arch.embedding_length or self.embedding.vocab != self.arch.vocab_size) return error.ShapeMismatch;
        if (self.final_norm.len != self.arch.embedding_length) return error.ShapeMismatch;
        if (self.output.rows != self.arch.vocab_size or self.output.cols != self.arch.embedding_length) return error.ShapeMismatch;
        for (self.layers) |layer| try layer.validate(self.arch);
        try self.output.validate();
    }
};

pub const LlamaModelExecutor = struct {
    model: LlamaModelView,
    cache: GqaCache,
    scratch: LlamaStepScratch,
    hidden: []f32,
    final_hidden: []f32,
    logits: []f32,

    pub fn init(allocator: std.mem.Allocator, model: LlamaModelView) !LlamaModelExecutor {
        try model.validate();
        const cache = try GqaCache.init(allocator, model.arch.block_count, model.arch.context_length, model.arch.head_count_kv, model.arch.headDim());
        errdefer {
            var c = cache;
            c.deinit();
        }
        var scratch = try LlamaStepScratch.init(allocator, model.arch);
        errdefer scratch.deinit();
        const hidden = try allocator.alloc(f32, model.arch.embedding_length);
        errdefer allocator.free(hidden);
        const final_hidden = try allocator.alloc(f32, model.arch.embedding_length);
        errdefer allocator.free(final_hidden);
        const logits = try allocator.alloc(f32, model.arch.vocab_size);
        return .{ .model = model, .cache = cache, .scratch = scratch, .hidden = hidden, .final_hidden = final_hidden, .logits = logits };
    }

    pub fn deinit(self: *LlamaModelExecutor) void {
        const allocator = self.scratch.allocator;
        self.cache.deinit();
        self.scratch.deinit();
        allocator.free(self.hidden);
        allocator.free(self.final_hidden);
        allocator.free(self.logits);
        self.* = undefined;
    }

    pub fn forwardToken(self: *LlamaModelExecutor, token: u32, position: usize) ![]const f32 {
        if (position >= self.model.arch.context_length) return error.ContextExceeded;
        try self.model.embedding.lookup(self.hidden, token);
        var layer_idx: usize = 0;
        while (layer_idx < self.model.layers.len) : (layer_idx += 1) {
            try LlamaLayerExecutor.step(self.hidden, self.model.layers[layer_idx], self.model.arch, layer_idx, position, &self.cache, &self.scratch);
        }
        try rmsNorm(self.final_hidden, self.hidden, self.model.final_norm, self.model.arch.rms_epsilon);
        try self.model.output.apply(self.logits, self.final_hidden, self.scratch.matrix);
        return self.logits;
    }
};

// ----------------------------------------------------------------------------
// Model-independent autoregressive driver: prefill then decode. Tokenization
// remains supplied by the GGUF tokenizer implementation.
// ----------------------------------------------------------------------------

pub const AutoregressiveDriver = struct {
    pub fn prefill(executor: *LlamaModelExecutor, tokens: []const u32) ![]const f32 {
        if (tokens.len == 0) return error.EmptyPrompt;
        var logits: []const f32 = &[_]f32{};
        for (tokens, 0..) |tok, pos| logits = try executor.forwardToken(tok, pos);
        return logits;
    }

    pub fn generate(
        allocator: std.mem.Allocator,
        executor: *LlamaModelExecutor,
        prompt: []const u32,
        config: GenerationConfig,
        stop_tokens: []const u32,
    ) ![]u32 {
        if (prompt.len == 0) return error.EmptyPrompt;
        var session = try GenerationSession.init(allocator, config, 512);
        defer session.deinit();
        const top = try allocator.alloc(TopK.Item, @min(@max(config.top_k, 1), @min(executor.model.arch.vocab_size, 1024)));
        defer allocator.free(top);
        var generated = std.ArrayList(u32).empty;
        errdefer generated.deinit(allocator);

        var current_logits = try prefill(executor, prompt);
        var position = prompt.len;
        while (generated.items.len < config.max_tokens and position < executor.model.arch.context_length) : (position += 1) {
            // choose mutates logits for repeat penalty, so copy into executor's owned logits
            if (current_logits.ptr != executor.logits.ptr) @memcpy(executor.logits, current_logits);
            const tok = try session.choose(executor.logits, top);
            var stopped = false;
            for (stop_tokens) |s| if (s == tok) {
                stopped = true;
                break;
            };
            if (stopped) break;
            try generated.append(allocator, tok);
            current_logits = try executor.forwardToken(tok, position);
        }
        return try generated.toOwnedSlice(allocator);
    }
};

// ----------------------------------------------------------------------------
// Token ID sequence utilities used by prompt truncation and repetition logic.
// ----------------------------------------------------------------------------

pub const TokenSequence = struct {
    pub fn truncateLeft(tokens: []const u32, max_len: usize) []const u32 {
        if (tokens.len <= max_len) return tokens;
        return tokens[tokens.len - max_len ..];
    }

    pub fn longestSuffixPrefix(haystack: []const u32, needle: []const u32) usize {
        const max = @min(haystack.len, needle.len);
        var n = max;
        while (n > 0) : (n -= 1) {
            if (std.mem.eql(u32, haystack[haystack.len - n ..], needle[0..n])) return n;
        }
        return 0;
    }

    pub fn endsWith(tokens: []const u32, suffix: []const u32) bool {
        return suffix.len <= tokens.len and std.mem.eql(u32, tokens[tokens.len - suffix.len ..], suffix);
    }
};

test "token sequence suffix prefix" {
    const a = [_]u32{ 1, 2, 3, 4 };
    const b = [_]u32{ 3, 4, 5 };
    try std.testing.expectEqual(@as(usize, 2), TokenSequence.longestSuffixPrefix(&a, &b));
}

// ----------------------------------------------------------------------------
// WOTS+ and FORS-like hash machinery. This is reusable for SLH-DSA but final
// FIPS-205 signing stays disabled until all parameter-set KATs are integrated.
// ----------------------------------------------------------------------------

pub const WotsPlus = struct {
    pub const n: usize = 32;
    pub const w: usize = 16;
    pub const log_w: usize = 4;
    pub const len1: usize = (8 * n + log_w - 1) / log_w;
    pub const len2: usize = 3;
    pub const len: usize = len1 + len2;

    fn baseW(out: []u8, input: []const u8) !void {
        var in_idx: usize = 0;
        var total: u16 = 0;
        var bits: u8 = 0;
        for (out) |*o| {
            if (bits == 0) {
                if (in_idx >= input.len) return error.InputTooShort;
                total = input[in_idx];
                in_idx += 1;
                bits = 8;
            }
            bits -= log_w;
            o.* = @intCast((total >> bits) & (w - 1));
        }
    }

    fn checksum(msg_base: []const u8) u32 {
        var csum: u32 = 0;
        for (msg_base) |v| csum += (w - 1) - v;
        return csum << ((8 - ((len2 * log_w) % 8)) % 8);
    }

    fn chain(out: *[n]u8, input: *const [n]u8, start: u8, steps: u8, seed: *const [n]u8, address: SlhDsa.Address) void {
        out.* = input.*;
        var addr = address;
        var i: u8 = 0;
        while (i < steps and start + i < w) : (i += 1) {
            addr.words[6] = start + i;
            out.* = SlhDsa.thash1(seed, addr, out);
        }
    }

    pub fn chainLengths(msg_digest: *const [n]u8) [len]u8 {
        var lengths: [len]u8 = [_]u8{0} ** len;
        baseW(lengths[0..len1], msg_digest) catch unreachable;
        const csum = checksum(lengths[0..len1]);
        var buf: [4]u8 = undefined;
        buf[0] = @truncate(csum >> 24);
        buf[1] = @truncate(csum >> 16);
        buf[2] = @truncate(csum >> 8);
        buf[3] = @truncate(csum);
        baseW(lengths[len1..], buf[4 - ((len2 * log_w + 7) / 8) ..]) catch unreachable;
        return lengths;
    }

    pub fn publicFromSecret(out: *[len][n]u8, secret: *const [len][n]u8, seed: *const [n]u8, address: SlhDsa.Address) void {
        var i: usize = 0;
        while (i < len) : (i += 1) {
            var addr = address;
            addr.words[5] = @intCast(i);
            chain(&out[i], &secret[i], 0, w - 1, seed, addr);
        }
    }

    pub fn sign(out: *[len][n]u8, digest: *const [n]u8, secret: *const [len][n]u8, seed: *const [n]u8, address: SlhDsa.Address) void {
        const lengths = chainLengths(digest);
        var i: usize = 0;
        while (i < len) : (i += 1) {
            var addr = address;
            addr.words[5] = @intCast(i);
            chain(&out[i], &secret[i], 0, lengths[i], seed, addr);
        }
    }

    pub fn publicFromSignature(out: *[len][n]u8, signature: *const [len][n]u8, digest: *const [n]u8, seed: *const [n]u8, address: SlhDsa.Address) void {
        const lengths = chainLengths(digest);
        var i: usize = 0;
        while (i < len) : (i += 1) {
            var addr = address;
            addr.words[5] = @intCast(i);
            chain(&out[i], &signature[i], lengths[i], (w - 1) - lengths[i], seed, addr);
        }
    }
};

pub const HashTree = struct {
    pub const Node = [32]u8;

    pub fn parent(left: *const Node, right: *const Node, domain: []const u8) Node {
        var h = Keccak.Sponge.init(136, 0x06);
        h.update(domain) catch unreachable;
        h.update(left) catch unreachable;
        h.update(right) catch unreachable;
        h.finalize();
        var out: Node = undefined;
        h.squeeze(&out) catch unreachable;
        return out;
    }

    pub fn root(allocator: std.mem.Allocator, leaves: []const Node, domain: []const u8) !Node {
        if (leaves.len == 0 or !std.math.isPowerOfTwo(leaves.len)) return error.InvalidTreeSize;
        var level = try allocator.dupe(Node, leaves);
        defer allocator.free(level);
        var count = leaves.len;
        while (count > 1) {
            var i: usize = 0;
            while (i < count / 2) : (i += 1) level[i] = parent(&level[2 * i], &level[2 * i + 1], domain);
            count /= 2;
        }
        return level[0];
    }

    pub fn authPath(allocator: std.mem.Allocator, leaves: []const Node, leaf_index: usize, out: []Node, domain: []const u8) !void {
        if (leaves.len == 0 or !std.math.isPowerOfTwo(leaves.len) or leaf_index >= leaves.len) return error.InvalidTreeSize;
        const height: usize = @intCast(std.math.log2_int(usize, leaves.len));
        if (out.len != height) return error.ShapeMismatch;
        var level = try allocator.dupe(Node, leaves);
        defer allocator.free(level);
        var count = leaves.len;
        var idx = leaf_index;
        var h: usize = 0;
        while (count > 1) : (h += 1) {
            out[h] = level[idx ^ 1];
            var i: usize = 0;
            while (i < count / 2) : (i += 1) level[i] = parent(&level[2 * i], &level[2 * i + 1], domain);
            idx /= 2;
            count /= 2;
        }
    }

    pub fn rootFromPath(leaf: Node, leaf_index: usize, path: []const Node, domain: []const u8) Node {
        var node = leaf;
        var idx = leaf_index;
        for (path) |sibling| {
            node = if ((idx & 1) == 0) parent(&node, &sibling, domain) else parent(&sibling, &node, domain);
            idx >>= 1;
        }
        return node;
    }
};

// ----------------------------------------------------------------------------
// HKDF-labeled key schedule used by local encrypted records and hybrid KEM
// contexts. Domain separation is mandatory; empty labels are rejected.
// ----------------------------------------------------------------------------

pub const KeySchedule = struct {
    pub fn derive(master: []const u8, salt: []const u8, label: []const u8, context: []const u8, out: []u8) !void {
        if (label.len == 0 or label.len > 255 or context.len > 65535) return error.InvalidLabel;
        const prk = hkdfExtractSha512(salt, master);
        var info = std.ArrayList(u8).empty;
        defer info.deinit(std.heap.page_allocator);
        try info.appendSlice(std.heap.page_allocator, "NAZA-ZIG-v1");
        try info.append(std.heap.page_allocator, @intCast(label.len));
        try info.appendSlice(std.heap.page_allocator, label);
        var lenbuf: [2]u8 = undefined;
        try writeU16Le(&lenbuf, @intCast(context.len));
        try info.appendSlice(std.heap.page_allocator, &lenbuf);
        try info.appendSlice(std.heap.page_allocator, context);
        try hkdfExpandSha512(&prk, info.items, out);
    }
};

// ----------------------------------------------------------------------------
// Deterministic transcript builder with length-prefixing, avoiding ambiguous
// concatenation in protocol hashes.
// ----------------------------------------------------------------------------

pub const Transcript = struct {
    sponge: Keccak.Sponge = Keccak.Sponge.init(136, 0x06),

    pub fn init(domain: []const u8) Transcript {
        var t = Transcript{};
        t.field("domain", domain) catch unreachable;
        return t;
    }

    pub fn field(self: *Transcript, name: []const u8, value: []const u8) !void {
        if (name.len > std.math.maxInt(u16) or value.len > std.math.maxInt(u32)) return error.FieldTooLarge;
        var hdr: [6]u8 = undefined;
        try writeU16Le(hdr[0..2], @intCast(name.len));
        try writeU32Le(hdr[2..6], @intCast(value.len));
        try self.sponge.update(&hdr);
        try self.sponge.update(name);
        try self.sponge.update(value);
    }

    pub fn finish(self: *Transcript) [32]u8 {
        self.sponge.finalize();
        var out: [32]u8 = undefined;
        self.sponge.squeeze(&out) catch unreachable;
        return out;
    }
};

