test "Q4_K zero scales remains finite" {
    var raw = [_]u8{0} ** Q4KExact.block_bytes;
    raw[0] = 0x00;
    raw[1] = 0x3c;
    raw[2] = 0x00;
    raw[3] = 0x3c;
    var out: [256]f32 = undefined;
    Q4KExact.dequantBlock(&out, &raw);
    for (out) |v| try std.testing.expect(std.math.isFinite(v));
}

test "Q5_K zero scales remains finite" {
    var raw = [_]u8{0} ** Q5KExact.block_bytes;
    raw[0] = 0x00;
    raw[1] = 0x3c;
    raw[2] = 0x00;
    raw[3] = 0x3c;
    var out: [256]f32 = undefined;
    Q5KExact.dequantBlock(&out, &raw);
    for (out) |v| try std.testing.expect(std.math.isFinite(v));
}

test "Q6_K zero scales remains finite" {
    var raw = [_]u8{0} ** Q6KExact.block_bytes;
    raw[Q6KExact.d_offset] = 0x00;
    raw[Q6KExact.d_offset + 1] = 0x3c;
    var out: [256]f32 = undefined;
    Q6KExact.dequantBlock(&out, &raw);
    for (out) |v| try std.testing.expect(std.math.isFinite(v));
}

test "hash tree path reconstructs root" {
    const allocator = std.testing.allocator;
    var leaves: [8]HashTree.Node = undefined;
    for (&leaves, 0..) |*leaf, i| {
        var b: [8]u8 = undefined;
        try writeU64Le(&b, i);
        leaf.* = sha256(&b);
    }
    const r = try HashTree.root(allocator, &leaves, "tree");
    var path: [3]HashTree.Node = undefined;
    try HashTree.authPath(allocator, &leaves, 5, &path, "tree");
    const rebuilt = HashTree.rootFromPath(leaves[5], 5, &path, "tree");
    try std.testing.expect(ctEqual(&r, &rebuilt));
}

test "llama3 prompt framing" {
    const allocator = std.testing.allocator;
    const messages = [_]ChatMessage{
        .{ .role = .user, .text = "hello" },
    };
    const p = try Llama3Prompt.build(allocator, "system", &messages);
    defer allocator.free(p);
    try std.testing.expect(std.mem.indexOf(u8, p, "<|start_header_id|>assistant<|end_header_id|>") != null);
}

test "GQA cache one-token attention returns value" {
    const allocator = std.testing.allocator;
    var cache = try GqaCache.init(allocator, 1, 4, 1, 2);
    defer cache.deinit();
    try cache.write(0, 0, &[_]f32{ 1, 0 }, &[_]f32{ 3, 4 });
    var out: [2]f32 = undefined;
    var scores: [4]f32 = undefined;
    try cache.attend(&out, &[_]f32{ 1, 0 }, 0, 0, 1, &scores);
    try std.testing.expectApproxEqAbs(@as(f32, 3), out[0], 1e-6);
    try std.testing.expectApproxEqAbs(@as(f32, 4), out[1], 1e-6);
}

// ----------------------------------------------------------------------------
// Post-quantum catalog. Every named family is visible; status and implementation
// are separate so "supported name" can never be confused with "verified crypto".
// ----------------------------------------------------------------------------

pub const PqcKind = enum { kem, signature, stateful_signature, hybrid, primitive };
pub const PqcBasis = enum { lattice, code, hash, isogeny, multivariate, mpc_in_the_head, symmetric, mixed, other };
pub const PqcStatus = enum { nist_standard, nist_selected, ietf_standard, national_standard, candidate, research, deprecated_broken };
pub const PqcImplementation = enum { catalog_only, partial, implemented_unverified, implemented, verified_vectors };

pub const PqcAlgorithm = struct {
    id: []const u8,
    kind: PqcKind,
    basis: PqcBasis,
    status: PqcStatus,
    implementation: PqcImplementation,
};

pub const pqc_algorithms = [_]PqcAlgorithm{
    .{ .id = "ML-KEM-512", .kind = .kem, .basis = .lattice, .status = .nist_standard, .implementation = .implemented_unverified },
    .{ .id = "ML-KEM-768", .kind = .kem, .basis = .lattice, .status = .nist_standard, .implementation = .implemented_unverified },
    .{ .id = "ML-KEM-1024", .kind = .kem, .basis = .lattice, .status = .nist_standard, .implementation = .implemented_unverified },
    .{ .id = "HQC-256", .kind = .kem, .basis = .code, .status = .nist_selected, .implementation = .partial },
    .{ .id = "ML-KEM-1024+HQC-256", .kind = .hybrid, .basis = .mixed, .status = .research, .implementation = .catalog_only },
    .{ .id = "ML-KEM-1024+HQC-256+X25519", .kind = .hybrid, .basis = .mixed, .status = .research, .implementation = .catalog_only },
};

pub fn findPqc(id: []const u8) ?PqcAlgorithm {
    for (pqc_algorithms) |a| if (std.mem.eql(u8, a.id, id)) return a;
    return null;
}

pub fn pqcUsable(id: []const u8) bool {
    const a = findPqc(id) orelse return false;
    return a.implementation == .implemented or a.implementation == .verified_vectors;
}

pub fn pqcCallable(id: []const u8) bool {
    const a = findPqc(id) orelse return false;
    // Experimental code remains directly testable through its implementation
    // APIs, but the public dispatch facade is production-gated until vectors
    // and independent interoperability checks have passed.
    return a.implementation == .implemented or a.implementation == .verified_vectors;
}

pub const Kem = struct {
    pub const Sizes = struct { public_key: usize, secret_key: usize, ciphertext: usize, shared_secret: usize };

    fn mlKemParams(id: []const u8) ?MlKem.Params {
        if (std.mem.eql(u8, id, "ML-KEM-512")) return MlKem.p512;
        if (std.mem.eql(u8, id, "ML-KEM-768")) return MlKem.p768;
        if (std.mem.eql(u8, id, "ML-KEM-1024")) return MlKem.p1024;
        return null;
    }

    pub fn sizes(id: []const u8) !Sizes {
        const p = mlKemParams(id) orelse return error.UnsupportedAlgorithm;
        return .{
            .public_key = MlKemSizes.publicKeyBytes(p),
            .secret_key = MlKemSizes.secretKeyBytes(p),
            .ciphertext = MlKemSizes.cipherTextBytes(p),
            .shared_secret = 32,
        };
    }

    pub fn keypair(id: []const u8, seed: []const u8, pk: []u8, sk: []u8) !void {
        const params = mlKemParams(id) orelse return error.UnsupportedAlgorithm;
        if (!pqcCallable(id)) return error.AlgorithmNotCallable;
        if (seed.len < 64) return error.SeedTooShort;
        var d: [32]u8 = undefined;
        var z: [32]u8 = undefined;
        @memcpy(&d, seed[0..32]);
        @memcpy(&z, seed[32..64]);
        defer secureZero(&d);
        defer secureZero(&z);
        try MlKemKem.keypair(pk, sk, &d, &z, params);
    }

    pub fn encapsulate(id: []const u8, randomness: []const u8, pk: []const u8, ct: []u8, ss: []u8) !void {
        const params = mlKemParams(id) orelse return error.UnsupportedAlgorithm;
        if (!pqcCallable(id)) return error.AlgorithmNotCallable;
        if (randomness.len < 32) return error.SeedTooShort;
        if (ss.len != 32) return error.LengthMismatch;
        var m: [32]u8 = undefined;
        var shared: [32]u8 = undefined;
        @memcpy(&m, randomness[0..32]);
        defer secureZero(&m);
        defer secureZero(&shared);
        try MlKemKem.encapsulate(ct, &shared, pk, &m, params);
        @memcpy(ss, &shared);
    }

    pub fn decapsulate(id: []const u8, sk: []const u8, ct: []const u8, ss: []u8) !void {
        const params = mlKemParams(id) orelse return error.UnsupportedAlgorithm;
        if (!pqcCallable(id)) return error.AlgorithmNotCallable;
        if (ss.len != 32) return error.LengthMismatch;
        var shared: [32]u8 = undefined;
        defer secureZero(&shared);
        try MlKemKem.decapsulate(&shared, ct, sk, params);
        @memcpy(ss, &shared);
    }
};

pub const Signature = struct {
    pub const Sizes = struct { public_key: usize, secret_key: usize, signature: usize };

    fn mlDsaParams(id: []const u8) ?MlDsaParams {
        if (std.mem.eql(u8, id, "ML-DSA-44")) return MlDsaParams.level44();
        if (std.mem.eql(u8, id, "ML-DSA-65")) return MlDsaParams.level65();
        if (std.mem.eql(u8, id, "ML-DSA-87")) return MlDsaParams.level87();
        return null;
    }

    pub fn sizes(id: []const u8) !Sizes {
        const p = mlDsaParams(id) orelse return error.UnsupportedAlgorithm;
        const lay = MlDsaStdPacking.layout(p);
        return .{ .public_key = lay.pk_bytes, .secret_key = lay.sk_bytes, .signature = lay.sig_bytes };
    }

    pub fn keypair(id: []const u8, seed: []const u8, pk_out: []u8, sk_out: []u8) !void {
        const params = mlDsaParams(id) orelse return error.UnsupportedAlgorithm;
        if (!pqcCallable(id)) return error.AlgorithmNotCallable;
        if (seed.len < 32) return error.SeedTooShort;
        const lay = MlDsaStdPacking.layout(params);
        if (pk_out.len != lay.pk_bytes or sk_out.len != lay.sk_bytes) return error.LengthMismatch;
        var seed32: [32]u8 = undefined;
        @memcpy(&seed32, seed[0..32]);
        defer secureZero(&seed32);
        var pk: MlDsaExpandedPublicKey = undefined;
        var sk: MlDsaExpandedSecretKey = undefined;
        defer secureZero(std.mem.asBytes(&sk));
        try MlDsaExpanded.keypair(&seed32, params, &pk, &sk);
        const pkn = try MlDsaStdPacking.packPublicKey(pk_out, &pk);
        const skn = try MlDsaStdPacking.packSecretKey(sk_out, &sk);
        if (pkn != lay.pk_bytes or skn != lay.sk_bytes) return error.InternalEncodingLength;
    }

    pub fn sign(id: []const u8, sk_bytes: []const u8, message: []const u8, out: []u8) !usize {
        const params = mlDsaParams(id) orelse return error.UnsupportedAlgorithm;
        if (!pqcCallable(id)) return error.AlgorithmNotCallable;
        const lay = MlDsaStdPacking.layout(params);
        if (sk_bytes.len != lay.sk_bytes or out.len < lay.sig_bytes) return error.LengthMismatch;
        var sk: MlDsaExpandedSecretKey = undefined;
        var sig: MlDsaExpandedSignature = undefined;
        defer secureZero(std.mem.asBytes(&sk));
        _ = try MlDsaStdPacking.unpackSecretKey(&sk, sk_bytes, params);
        try MlDsaExpanded.signExpanded(&sk, message, "", &sig);
        const n = try MlDsaStdPacking.packSignature(out, &sig);
        return n;
    }

    pub fn verify(id: []const u8, pk_bytes: []const u8, message: []const u8, sig_bytes: []const u8) !bool {
        const params = mlDsaParams(id) orelse return error.UnsupportedAlgorithm;
        if (!pqcCallable(id)) return error.AlgorithmNotCallable;
        const lay = MlDsaStdPacking.layout(params);
        if (pk_bytes.len != lay.pk_bytes or sig_bytes.len != lay.sig_bytes) return false;
        return MlDsaVerifier.verifyPacked(pk_bytes, sig_bytes, params, message, "");
    }
};

