fn usage() void {
    std.debug.print("NAZA pure-Zig monolith {s}\n", .{VERSION});
    std.debug.print("  gui                         open the Debian native Zig GUI\n", .{});
    std.debug.print("  gui-phone                   open the vertical phone-layout preview\n", .{});
    std.debug.print("  tui                         open the interactive terminal UI\n", .{});
    std.debug.print("  install                     lock/unlock checkpoint for Android Keystore enrollment\n", .{});
    std.debug.print("  model                       pinned GGUF identity\n", .{});
    std.debug.print("  download <path.gguf>        secure HTTPS download + hash verify\n", .{});
    std.debug.print("  verify <path.gguf>          SHA-256 verify pinned GGUF\n", .{});
    std.debug.print("  gguf <path.gguf>            parse GGUF metadata/tensor table\n", .{});
    std.debug.print("  pqc                         list PQ algorithms + implementation state\n", .{});
    std.debug.print("  selftest                    run built-in crypto checks\n", .{});
}

fn printHex(bytes: []const u8) void {
    for (bytes) |b| std.debug.print("{x:0>2}", .{b});
    std.debug.print("\n", .{});
}

fn selfTestRuntime() !void {
    const empty_sha3 = sha3_256("");
    var expected: [32]u8 = undefined;
    _ = try std.fmt.hexToBytes(&expected, "a7ffc6f8bf1ed76651c14756a061d662f580ff4de43b49fa82d80a4b80f8434a");
    if (!ctEqual(&empty_sha3, &expected)) return error.Sha3KatFailed;

    const abc_sha3 = sha3_256("abc");
    _ = try std.fmt.hexToBytes(&expected, "3a985da74fe225b2045c172d6bd390bd855f086e3e9d525b46bfe24511431532");
    if (!ctEqual(&abc_sha3, &expected)) return error.Sha3KatFailed;

    var shake: [32]u8 = undefined;
    shake256("", &shake);
    _ = try std.fmt.hexToBytes(&expected, "46b9dd2b0ba88d13233b3feb743eeb243fcd52ea62b81b82b50c27646ed5762f");
    if (!ctEqual(&shake, &expected)) return error.ShakeKatFailed;

    var a = [_]i16{0} ** MlKem.n;
    var b = [_]i16{0} ** MlKem.n;
    a[0] = 1;
    a[255] = 1;
    b[0] = 1;
    b[1] = 1;
    const c = MlKem.mulNegacyclic(a, b);
    if (c[0] != 0 or c[1] != 1 or c[255] != 1) return error.MlKemNegacyclicFailed;

    // Do not run unverified ML-KEM through the CLI self-test. The primitive is
    // exercised in development-only tests below; production dispatch remains
    // disabled until official vectors and independent differential checks pass.
    if (!pqcCallable("ML-KEM-1024")) {
        var no_bytes: [0]u8 = .{};
        Kem.keypair("ML-KEM-1024", "", &no_bytes, &no_bytes) catch |err| {
            if (err == error.AlgorithmNotCallable) return;
            return error.MlKemSelfTestFailed;
        };
        return error.MlKemSelfTestFailed;
    }

    // Exercise a vector-verified algorithm here after it becomes callable.
    var kem_seed: [64]u8 = undefined;
    var kem_coins: [32]u8 = undefined;
    for (&kem_seed, 0..) |*v, i| v.* = @truncate(i *% 37 +% 11);
    for (&kem_coins, 0..) |*v, i| v.* = @truncate(i *% 19 +% 7);
    var kem_pk: [1568]u8 = undefined;
    var kem_sk: [3168]u8 = undefined;
    var kem_ct: [1568]u8 = undefined;
    var kem_enc: [32]u8 = undefined;
    var kem_dec: [32]u8 = undefined;
    Kem.keypair("ML-KEM-1024", &kem_seed, &kem_pk, &kem_sk) catch return error.MlKemSelfTestFailed;
    Kem.encapsulate("ML-KEM-1024", &kem_coins, &kem_pk, &kem_ct, &kem_enc) catch return error.MlKemSelfTestFailed;
    Kem.decapsulate("ML-KEM-1024", &kem_sk, &kem_ct, &kem_dec) catch return error.MlKemSelfTestFailed;
    if (!ctEqual(&kem_enc, &kem_dec)) return error.MlKemSelfTestFailed;
}

// ----------------------------------------------------------------------------
// Terminal UI — intentionally dependency-free, with the original Naza's
// numbered boxed-menu feel adapted to the pure-Zig feature surface.
// ----------------------------------------------------------------------------

const TuiInput = struct {
    file: std.fs.File,
    buffer: [4096]u8 = undefined,
    len: usize = 0,
};

fn tuiClear() void {
    std.debug.print("\x1b[2J\x1b[H", .{});
}

fn tuiHeader(page: []const u8) void {
    tuiClear();
    std.debug.print("\x1b[1;36m+------------------------------------------------------------------------------+\x1b[0m\n", .{});
    std.debug.print("\x1b[1;36m|\x1b[0m \x1b[1;35mNAZA\x1b[0m  pure-Zig monolith                                      v{s} \x1b[1;36m|\x1b[0m\n", .{VERSION});
    std.debug.print("\x1b[1;36m|\x1b[0m page: \x1b[1;33m{s:<64}\x1b[0m \x1b[1;36m|\x1b[0m\n", .{page});
    std.debug.print("\x1b[1;36m+------------------------------------------------------------------------------+\x1b[0m\n\n", .{});
}

fn tuiBox(title: []const u8) void {
    std.debug.print("\x1b[1;36m+------------------------------------------------------------------------------+\x1b[0m\n", .{});
    std.debug.print("\x1b[1;36m|\x1b[0m \x1b[1;36m{s}\x1b[0m\n", .{title});
    std.debug.print("\x1b[1;36m+------------------------------------------------------------------------------+\x1b[0m\n", .{});
}

fn tuiReadLine(input: *TuiInput, prompt: []const u8) ![]const u8 {
    std.debug.print("\x1b[1;32m{s}\x1b[0m", .{prompt});
    input.len = 0;
    while (input.len < input.buffer.len) {
        const n = try input.file.read(input.buffer[input.len .. input.len + 1]);
        if (n == 0) {
            if (input.len == 0) return error.EndOfStream;
            break;
        }
        if (input.buffer[input.len] == '\n') break;
        input.len += 1;
    }
    if (input.len == input.buffer.len) return error.InputTooLong;
    return std.mem.trim(u8, input.buffer[0..input.len], " \t\r");
}

fn tuiPause(input: *TuiInput) void {
    _ = tuiReadLine(input, "\n\x1b[2mPress Enter to continue...\x1b[0m ") catch {};
}

fn tuiChoice(input: *TuiInput, prompt: []const u8, max: usize) !usize {
    while (true) {
        const line = try tuiReadLine(input, prompt);
        const choice = std.fmt.parseInt(usize, line, 10) catch 0;
        if (choice >= 1 and choice <= max) return choice;
        std.debug.print("\x1b[1;31mChoose a number from 1 to {}.\x1b[0m\n", .{max});
    }
}

fn tuiField(input: *TuiInput, prompt: []const u8, destination: []u8, fallback: []const u8) ![]const u8 {
    const line = try tuiReadLine(input, prompt);
    const value = if (line.len == 0) fallback else line;
    if (value.len > destination.len) return error.InputTooLong;
    @memcpy(destination[0..value.len], value);
    return destination[0..value.len];
}

fn tuiModelManager(input: *TuiInput) !void {
    while (true) {
        tuiHeader("MODEL MANAGER");
        tuiBox("Pinned GGUF identity");
        std.debug.print("  file   : {s}\n  sha256 : {s}\n  source : {s}\n\n", .{ PinnedModel.file, PinnedModel.sha256_hex, PinnedModel.repo });
        std.debug.print("  1) Securely download and install\n  2) Verify an existing local GGUF\n  3) Back\n\n", .{});
        switch (try tuiChoice(input, "Choose (1-3)> ", 3)) {
            1 => {
                const destination = "models/" ++ PinnedModel.file;
                std.fs.cwd().makePath("models") catch |err| {
                    std.debug.print("\x1b[1;31mcould not create models directory: {s}\x1b[0m\n", .{@errorName(err)});
                    tuiPause(input);
                    continue;
                };
                std.debug.print("destination: {s}\n", .{destination});
                const bytes = downloadPinnedModelInternal(std.heap.page_allocator, destination, true) catch |err| switch (err) {
                    error.ModelAlreadyVerified => {
                        std.debug.print("\x1b[1;32mmodel is already downloaded and verified: {s}\x1b[0m\n", .{destination});
                        tuiPause(input);
                        continue;
                    },
                    else => {
                        std.debug.print("\x1b[1;31mdownload refused/failed: {s}\x1b[0m\n", .{@errorName(err)});
                        tuiPause(input);
                        continue;
                    },
                };
                std.debug.print("\x1b[1;32mdownloaded and verified {} bytes: {s}\x1b[0m\n", .{ bytes, destination });
                tuiPause(input);
            },
            2 => {
                const path = try tuiReadLine(input, "path> ");
                if (path.len != 0) {
                    verifyPinnedModel(path) catch |err| {
                        std.debug.print("\x1b[1;31mverification failed: {s}\x1b[0m\n", .{@errorName(err)});
                        tuiPause(input);
                        continue;
                    };
                    std.debug.print("\x1b[1;32mverified: {s}\x1b[0m\n", .{path});
                }
                tuiPause(input);
            },
            3 => return,
            else => unreachable,
        }
    }
}

fn tuiChatPreview(allocator: std.mem.Allocator, input: *TuiInput) !void {
    tuiHeader("CHAT PROMPT PREVIEW");
    tuiBox("Llama 3 conversation framing + 30-circuit ensemble");
    std.debug.print("Commands: /clef <0-100> scores the latest unrated route; /quantum shows ensemble history.\n", .{});
    var message_buf: [2048]u8 = undefined;
    const message = try tuiField(input, "message> ", &message_buf, "");
    if (message.len == 0) return;

    if (std.mem.startsWith(u8, message, "/clef")) {
        const score_text = std.mem.trim(u8, message[@min(message.len, 5)..], " \t\r\n");
        if (score_text.len == 0) {
            std.debug.print("Usage: /clef <0-100>\n", .{});
            tuiPause(input);
            return;
        }
        const score = std.fmt.parseFloat(f64, score_text) catch {
            std.debug.print("Clef score must be a number from 0 to 100.\n", .{});
            tuiPause(input);
            return;
        };
        const update = QuantumEnsemble.recordClef(allocator, score, null) catch |err| {
            std.debug.print("Clef feedback rejected: {s}\n", .{@errorName(err)});
            tuiPause(input);
            return;
        };
        const p = QuantumEnsemble.profiles[update.circuit_index];
        std.debug.print("Clef feedback: {s} {d:.3} -> {d:.3}\n", .{ p.id, update.historical_before, update.historical_after });
        tuiPause(input);
        return;
    }

    if (std.mem.eql(u8, message, "/quantum")) {
        const rows = QuantumEnsemble.status(allocator) catch |err| {
            std.debug.print("Unable to read ensemble status: {s}\n", .{@errorName(err)});
            tuiPause(input);
            return;
        };
        std.debug.print("Top circuit history:\n", .{});
        for (rows) |row| {
            const p = QuantumEnsemble.profiles[row.index];
            std.debug.print("  {s} q={} bias={s:<20} H={d:.3} entropy={d:.3} runs={} clef={}\n", .{ p.id, p.qubits, p.bias, row.historical_score, row.mean_entropy, row.runs, row.clef_updates });
        }
        tuiPause(input);
        return;
    }

    var routed_owned: ?[]u8 = null;
    defer if (routed_owned) |owned| allocator.free(owned);
    var route_opt: ?QuantumEnsemble.Route = null;
    const category = QuantumEnsemble.inferCategory(message);
    route_opt = QuantumEnsemble.choose(allocator, message, category) catch null;
    if (route_opt) |route| {
        const context: ?[]u8 = QuantumEnsemble.contextAlloc(allocator, route) catch null;
        if (context) |ctx| {
            defer allocator.free(ctx);
            routed_owned = std.fmt.allocPrint(allocator, "{s}\n\n{s}", .{ ctx, message }) catch null;
        }
        const p = QuantumEnsemble.profiles[route.circuit_index];
        std.debug.print("\n\x1b[1;36mEnsemble route: {s} ({}q, {s}) p={d:.3}, entropy={d:.3}\x1b[0m\n", .{ p.id, p.qubits, p.bias, route.probability, route.entropy });
    }

    const answer = try runPinnedModelMode(allocator, routed_owned orelse message, .chat, 128);
    defer allocator.free(answer);
    std.debug.print("\n\x1b[1;32mModel reply:\x1b[0m\n{s}\n", .{answer});
    tuiPause(input);
}

const InferenceMode = enum { chat, road, food };

fn runPinnedModel(allocator: std.mem.Allocator, prompt: []const u8) ![]u8 {
    return runPinnedModelMode(allocator, prompt, .road, 16);
}

fn runPinnedModelMode(allocator: std.mem.Allocator, prompt: []const u8, mode: InferenceMode, max_tokens: usize) ![]u8 {
    const path = "models/" ++ PinnedModel.file;
    var file = try openRegularModel(path);
    defer file.close();
    const stat = try file.stat();
    if (stat.size == 0 or stat.size > PinnedModel.max_download_bytes) return error.ModelTooLarge;
    const bytes = try allocator.alloc(u8, @intCast(stat.size));
    defer allocator.free(bytes);
    if (try file.readAll(bytes) != bytes.len) return error.DownloadTruncated;
    // Verify precisely the owned bytes consumed by parsing and inference.
    try verifyPinnedModelBytes(bytes);
    try Wave38Llm.initMatrixPool(allocator, 8);
    defer Wave38Llm.deinitMatrixPool();

    var index = try Wave38Llm.GgufOwnedIndex.parse(allocator, bytes);
    defer index.deinit();
    const meta = try Wave38Llm.LlamaMetadata.fromIndex(index);
    var tokenizer = try Wave38Llm.Tokenizer.fromIndex(allocator, index);
    defer tokenizer.deinit();
    const binder = Wave38Llm.Binder{ .allocator = allocator, .catalog = .{ .index = &index } };
    var model = try binder.bind(meta);
    defer binder.deinitModel(&model);
    var executor = try Wave38Llm.Executor.init(allocator, &model, @min(meta.context_length, 2048));
    defer executor.deinit();
    var sampler = try Wave38Llm.Sampler38.init(allocator, meta.vocab_size, .{ .temperature = 0 });
    defer sampler.deinit();
    const messages = [_]Wave38Llm.Wave38ChatMessage{
        .{ .role = .system, .content = switch (mode) {
            .chat => "You are a helpful assistant. Answer the user clearly and concisely.",
            .road => "Classify road risk from the supplied observations. Reply with exactly Low, Medium, or High. Do not invent live sensor data.",
            .food => "Classify food or water risk from the supplied observations. Reply with exactly Low, Medium, or High. Do not invent sensor data.",
        } },
        .{ .role = .user, .content = prompt },
    };
    const chat_prompt = try Wave38Llm.ModelChat.render(allocator, tokenizer.vocab, &messages, true);
    defer allocator.free(chat_prompt);
    var generator = Wave38Llm.Generator{
        .allocator = allocator,
        .executor = &executor,
        .tokenizer = &tokenizer,
        .sampler = &sampler,
        .stops = .{ .stops = &[_]Wave38Llm.StopSequence{} },
        // The portable pure-Zig executor performs a full transformer pass per
        // token. Keep the interactive scanner bounded so it returns a real
        // multi-token probe instead of appearing hung; longer generation can
        // still be requested by callers using Generator directly.
        .config = .{ .max_new_tokens = max_tokens },
        .coherence = .{ .min_margin = 0 },
    };
    return generator.generateText(chat_prompt);
}

fn containsAsciiFolded(text: []const u8, needle: []const u8) bool {
    if (needle.len == 0 or needle.len > text.len) return false;
    var start: usize = 0;
    while (start + needle.len <= text.len) : (start += 1) {
        var matched = true;
        for (needle, 0..) |wanted, i| {
            if (std.ascii.toLower(text[start + i]) != std.ascii.toLower(wanted)) {
                matched = false;
                break;
            }
        }
        if (matched) return true;
    }
    return false;
}

fn fastEvidenceAssessment(allocator: std.mem.Allocator, prompt: []const u8) ![]u8 {
    // This is deliberately evidence-only: it does not claim sensor access or
    // substitute for the GGUF model. It gives the TUI a bounded result while
    // the portable transformer backend is still being optimized.
    const high_signal = [_][]const u8{
        "collision", "crash",   "fire",  "flood",  "ice",    "black ice", "closed",
        "debris",    "blocked", "smoke", "severe", "unsafe",
    };
    for (high_signal) |signal| {
        if (containsAsciiFolded(prompt, signal)) {
            return std.fmt.allocPrint(allocator, "Risk: High\nEvidence flag: {s}\nUncertainty: no live sensors or route feed were used.", .{signal});
        }
    }
    const favorable = containsAsciiFolded(prompt, "dry pavement") and
        containsAsciiFolded(prompt, "clear") and
        containsAsciiFolded(prompt, "good") and
        containsAsciiFolded(prompt, "traffic: low") and
        containsAsciiFolded(prompt, "none reported");
    if (favorable) {
        return allocator.dupe(u8, "Risk: Low\nEvidence flag: supplied conditions are favorable.\nUncertainty: no live sensors or route feed were used; verify conditions independently.");
    }
    return allocator.dupe(u8, "Risk: Medium\nEvidence flag: no decisive hazard signal was supplied.\nUncertainty: no live sensors or route feed were used; verify conditions independently.");
}

fn buildRoadRiskPrompt(allocator: std.mem.Allocator, location: []const u8, road_type: []const u8, weather: []const u8, traffic: []const u8, obstacles: []const u8, sensor_notes: []const u8) ![]u8 {
    return std.fmt.allocPrint(allocator,
        \\You are a Hypertime Nanobot specialized Road Risk Classification AI trained to evaluate real-world driving scenes.
        \\Analyze and Triple Check for validating accuracy the environmental and sensor data and determine the overall road risk level.
        \\Your reply must be only one word: Low, Medium, or High.
        \\
        \\[tuning]
        \\Scene details:
        \\Location: {s}
        \\Road type: {s}
        \\Weather: {s}
        \\Traffic: {s}
        \\Obstacles: {s}
        \\Sensor notes: {s}
        \\sys_metrics: disabled
        \\Quantum State: entropic_score=unknown
        \\[/tuning]
        \\
        \\Follow these strict rules when forming your decision:
        \\- Think through all scene factors internally but do not show reasoning.
        \\- Evaluate surface, visibility, weather, traffic, and obstacles holistically.
        \\- Optionally use the system entropic signal to bias your internal confidence slightly.
        \\- Choose only one risk level that best fits the entire situation.
        \\- Output exactly one word, with no punctuation or labels.
        \\- The valid outputs are only: Low, Medium, High.
        \\
        \\[action]
        \\1) Normalize sensor inputs to comparable scales.
        \\3) Map environmental risk cues -> discrete label using conservative thresholds.
        \\4) If sensor integrity anomalies are detected, bias toward higher risk.
        \\5) PUNKD: detect key tokens and locally adjust attention/temperature slightly to focus decisions.
        \\6) Do not output internal reasoning or diagnostics; only return the single-word label.
        \\[/action]
        \\
        \\[replytemplate]
        \\Low | Medium | High
        \\[/replytemplate]
    , .{ location, road_type, weather, traffic, obstacles, sensor_notes });
}

fn buildFoodWaterRiskPrompt(allocator: std.mem.Allocator, location: []const u8, food_type: []const u8, condition: []const u8, temperature: []const u8, cooked_state: []const u8, sensor_notes: []const u8) ![]u8 {
    return std.fmt.allocPrint(allocator,
        \\Classify food or water risk from these observations. Do not invent measurements.
        \\Location: {s}
        \\Food or Water Type: {s}
        \\Condition: {s}
        \\Temperature: {s}
        \\Cooked, Frozen Or Uncooked: {s}
        \\Sensor notes: {s}
        \\Spoilage, unsafe storage temperatures, undercooking, or contaminated water increase risk.
        \\Reply with exactly one word: Low, Medium, or High.
    , .{ location, food_type, condition, temperature, cooked_state, sensor_notes });
}

fn tuiScanner(allocator: std.mem.Allocator, input: *TuiInput, food: bool) !void {
    tuiHeader(if (food) "FOOD / WATER SCANNER" else "ROAD SCANNER");
    tuiBox(if (food) "Food / Water Scanner - Step 1/6" else "Road Risk Scanner - Step 1/6");
    std.debug.print("Blank fields stay blank.\n\n", .{});

    var location_buf: [256]u8 = undefined;
    var type_buf: [256]u8 = undefined;
    var weather_buf: [256]u8 = undefined;
    var traffic_buf: [256]u8 = undefined;
    var obstacles_buf: [256]u8 = undefined;
    var notes_buf: [512]u8 = undefined;

    const location = try tuiField(input, if (food) "Location (e.g., whole foods'): " else "Location (e.g., 'I-95 NB mile 12'): ", &location_buf, "");
    const item_type = try tuiField(input, if (food) "food or water type: " else "Road type (highway/urban/residential): ", &type_buf, "");
    const weather = try tuiField(input, if (food) "Condition " else "Weather/visibility: ", &weather_buf, "");
    const traffic = try tuiField(input, if (food) "Temperture " else "Traffic density (low/med/high): ", &traffic_buf, "");
    const obstacles = try tuiField(input, if (food) "Cooked Frozen Or uncooked " else "Reported obstacles: ", &obstacles_buf, "");
    const notes = try tuiField(input, "Sensor notes: ", &notes_buf, "");

    const raw_prompt = if (food)
        try buildFoodWaterRiskPrompt(allocator, location, item_type, weather, traffic, obstacles, notes)
    else
        try buildRoadRiskPrompt(allocator, location, item_type, weather, traffic, obstacles, notes);
    defer allocator.free(raw_prompt);

    var routed_owned: ?[]u8 = null;
    defer if (routed_owned) |owned| allocator.free(owned);
    if (!food) {
        const route_query = try std.fmt.allocPrint(allocator, "{s} {s} {s} {s} {s} {s}\n{s}", .{ location, item_type, weather, traffic, obstacles, notes, raw_prompt });
        defer allocator.free(route_query);
        const route_opt: ?QuantumEnsemble.Route = QuantumEnsemble.choose(allocator, route_query, "road-risk") catch null;
        if (route_opt) |route| {
            const context: ?[]u8 = QuantumEnsemble.contextAlloc(allocator, route) catch null;
            if (context) |ctx| {
                defer allocator.free(ctx);
                routed_owned = std.fmt.allocPrint(allocator, "{s}\n\n{s}", .{ ctx, raw_prompt }) catch null;
            }
            const p = QuantumEnsemble.profiles[route.circuit_index];
            std.debug.print("\n\x1b[1;36mEnsemble route: {s} ({}q, {s}) p={d:.3}, entropy={d:.3}\x1b[0m\n", .{ p.id, p.qubits, p.bias, route.probability, route.entropy });
        }
    }
    const prompt = routed_owned orelse raw_prompt;

    std.debug.print("\nRunning the verified GGUF model...\n", .{});
    const answer = runPinnedModelMode(allocator, prompt, if (food) .food else .road, 16) catch |err| {
        std.debug.print("Model inference failed: {s}. No risk classification was produced.\n", .{@errorName(err)});
        tuiPause(input);
        return;
    };
    defer allocator.free(answer);
    std.debug.print("\n\x1b[1;32mModel response:\x1b[0m\n{s}\n", .{answer});
    const label = std.mem.trim(u8, answer, " \t\r\n");
    if (!@import("inference_task.zig").validRiskLabel(label)) {
        std.debug.print("Model returned no valid risk label. No classification was produced.\n", .{});
    }
    std.debug.print("\x1b[2mVerify real-world conditions independently.\x1b[0m\n", .{});
    tuiPause(input);
}

fn inspectGguf(path: []const u8) !void {
    var file = try std.fs.cwd().openFile(path, .{});
    defer file.close();
    var io_buf: [8192]u8 = undefined;
    var r = file.reader(&io_buf).interface;
    const h = try Gguf.readHeader(&r, .{});
    try Gguf.skipMetadata(&r, h, .{});
    var i: u64 = 0;
    while (i < h.tensor_count) : (i += 1) _ = try Gguf.readTensorInfo(&r, .{});
    std.debug.print("GGUF v{} tensors={} metadata={}\n", .{ h.version, h.tensor_count, h.metadata_count });
}

fn tuiGguf(input: *TuiInput) !void {
    tuiHeader("GGUF INSPECTOR");
    tuiBox("Parse model metadata and tensor table");
    const path = try tuiReadLine(input, "GGUF path> ");
    if (path.len == 0) return;
    inspectGguf(path) catch |err| {
        std.debug.print("\x1b[1;31mGGUF inspection failed: {s}\x1b[0m\n", .{@errorName(err)});
        tuiPause(input);
        return;
    };
    tuiPause(input);
}

fn tuiPqc(input: *TuiInput) void {
    tuiHeader("POST-QUANTUM CATALOG");
    tuiBox("Algorithm | kind | status | implementation");
    for (pqc_algorithms) |algorithm| {
        std.debug.print("  {s:<22} {s:<8} {s:<14} {s}\n", .{ algorithm.id, @tagName(algorithm.kind), @tagName(algorithm.status), @tagName(algorithm.implementation) });
    }
    tuiPause(input);
}

fn tuiCryptoLab(allocator: std.mem.Allocator, input: *TuiInput) !void {
    while (true) {
        tuiHeader("CRYPTO LAB");
        tuiBox("Pure-Zig hash tools");
        std.debug.print("  1) SHA3-256\n  2) SHAKE256\n  3) Back\n\n", .{});
        switch (try tuiChoice(input, "Choose (1-3)> ", 3)) {
            1 => {
                const text = try tuiReadLine(input, "text> ");
                const digest = sha3_256(text);
                std.debug.print("digest> ", .{});
                printHex(&digest);
                tuiPause(input);
            },
            2 => {
                const text = try tuiReadLine(input, "text> ");
                const amount_line = try tuiReadLine(input, "bytes [32]> ");
                const amount = if (amount_line.len == 0) 32 else std.fmt.parseInt(usize, amount_line, 10) catch 0;
                if (amount > 1024 * 1024) {
                    std.debug.print("\x1b[1;31mOutput is limited to 1 MiB.\x1b[0m\n", .{});
                    tuiPause(input);
                    continue;
                }
                const output = try allocator.alloc(u8, amount);
                defer allocator.free(output);
                shake256(text, output);
                std.debug.print("digest> ", .{});
                printHex(output);
                tuiPause(input);
            },
            3 => return,
            else => unreachable,
        }
    }
}

fn tuiSelfTest(input: *TuiInput) void {
    tuiHeader("SELF-TEST");
    tuiBox("Built-in cryptographic checks");
    selfTestRuntime() catch |err| {
        std.debug.print("\x1b[1;31mselftest failed: {s}\x1b[0m\n", .{@errorName(err)});
        tuiPause(input);
        return;
    };
    std.debug.print("\x1b[1;32mselftest: ok\x1b[0m\n", .{});
    tuiPause(input);
}

fn runTui(allocator: std.mem.Allocator) !void {
    var input = TuiInput{ .file = std.fs.File.stdin() };
    while (true) {
        tuiHeader("MAIN MENU");
        tuiBox("Choose a module");
        std.debug.print("  1) Model Manager\n", .{});
        std.debug.print("  2) Chat with local LLM\n", .{});
        std.debug.print("  3) Road Scanner\n", .{});
        std.debug.print("  4) Food/Water Scanner\n", .{});
        std.debug.print("  5) GGUF Inspector\n", .{});
        std.debug.print("  6) PQC Catalog\n", .{});
        std.debug.print("  7) Self-test\n", .{});
        std.debug.print("  8) Exit\n\n", .{});

        switch (try tuiChoice(&input, "Choose (1-8)> ", 8)) {
            1 => try tuiModelManager(&input),
            2 => try tuiChatPreview(allocator, &input),
            3 => try tuiScanner(allocator, &input, false),
            4 => try tuiScanner(allocator, &input, true),
            5 => try tuiGguf(&input),
            6 => tuiPqc(&input),
            7 => tuiSelfTest(&input),
            8 => {
                tuiClear();
                std.debug.print("Goodbye.\n", .{});
                return;
            },
            else => unreachable,
        }
    }
}

pub const AndroidKeystoreGate = struct {
    const modulus_length = 256;
    const challenge_domain = "NAZA-ANDROID-UNLOCK-V1\x00";

    fn jsonField(value: std.json.Value, name: []const u8) ?std.json.Value {
        return switch (value) {
            .object => |object| object.get(name),
            else => null,
        };
    }

    fn jsonString(value: ?std.json.Value) ?[]const u8 {
        const v = value orelse return null;
        return switch (v) {
            .string => |s| s,
            else => null,
        };
    }

    fn jsonBool(value: ?std.json.Value) ?bool {
        const v = value orelse return null;
        return switch (v) {
            .bool => |b| b,
            else => null,
        };
    }

    fn jsonInt(value: ?std.json.Value) ?i64 {
        const v = value orelse return null;
        return switch (v) {
            .integer => |n| n,
            else => null,
        };
    }

    fn captureBridge(allocator: std.mem.Allocator, argv: []const []const u8, stdin_data: ?[]const u8, max_output: usize) ![]u8 {
        var child = std.process.Child.init(argv, allocator);
        child.stdin_behavior = if (stdin_data != null) .Pipe else .Ignore;
        child.stdout_behavior = .Pipe;
        child.stderr_behavior = .Inherit;
        try child.spawn();
        errdefer {
            _ = child.kill() catch {};
        }

        if (stdin_data) |data| {
            try child.stdin.?.writeAll(data);
            child.stdin.?.close();
            child.stdin = null;
        }

        var output: std.ArrayList(u8) = .empty;
        defer output.deinit(allocator);
        var buf: [4096]u8 = undefined;
        while (true) {
            const n = try child.stdout.?.read(&buf);
            if (n == 0) break;
            if (n > max_output or output.items.len > max_output - n) return error.KeystoreOutputTooLong;
            try output.appendSlice(allocator, buf[0..n]);
        }
        child.stdout.?.close();
        child.stdout = null;
        switch (try child.wait()) {
            .Exited => |code| if (code != 0) return error.KeystoreCommandFailed,
            else => return error.KeystoreCommandFailed,
        }
        return output.toOwnedSlice(allocator);
    }

    fn verifyKeyEnrollment(allocator: std.mem.Allocator, details: []const u8) !void {
        const parsed = try std.json.parseFromSlice(std.json.Value, allocator, details, .{});
        defer parsed.deinit();
        const entries = switch (parsed.value) {
            .array => |array| array.items,
            else => return error.KeystoreMetadataInvalid,
        };

        var matching: ?std.json.Value = null;
        for (entries) |entry| {
            const alias = jsonString(jsonField(entry, "alias")) orelse continue;
            if (!std.mem.eql(u8, alias, AndroidKeystoreOptions.key_alias)) continue;
            if (matching != null) return error.KeystoreMetadataInvalid;
            matching = entry;
        }
        const entry = matching orelse return error.KeystoreKeyMissing;
        if (!std.mem.eql(u8, jsonString(jsonField(entry, "algorithm")) orelse return error.KeystoreMetadataInvalid, "RSA")) return error.KeystoreMetadataInvalid;
        if (jsonInt(jsonField(entry, "size")) != 2048) return error.KeystoreMetadataInvalid;
        if (jsonBool(jsonField(entry, "inside_secure_hardware")) != true) return error.KeystoreNotHardwareBacked;
        if (!std.ascii.eqlIgnoreCase(jsonString(jsonField(entry, "modulus")) orelse return error.KeystoreMetadataInvalid, AndroidKeystoreOptions.rsa_modulus_hex)) return error.KeystoreKeyChanged;
        if (!std.ascii.eqlIgnoreCase(jsonString(jsonField(entry, "exponent")) orelse return error.KeystoreMetadataInvalid, AndroidKeystoreOptions.rsa_exponent_hex)) return error.KeystoreKeyChanged;

        const auth = jsonField(entry, "user_authentication") orelse return error.KeystoreMetadataInvalid;
        if (jsonBool(jsonField(auth, "required")) != true or jsonBool(jsonField(auth, "enforced_by_secure_hardware")) != true) return error.KeystoreAuthenticationNotHardwareEnforced;
    }

    fn verifySignature(modulus_hex: []const u8, exponent_hex: []const u8, challenge: []const u8, signature: []const u8) !void {
        if (modulus_hex.len != modulus_length * 2 or exponent_hex.len == 0 or exponent_hex.len > 8 or signature.len != modulus_length) return error.KeystoreProofInvalid;
        var modulus: [modulus_length]u8 = undefined;
        const modulus_bytes = std.fmt.hexToBytes(&modulus, modulus_hex) catch return error.KeystoreProofInvalid;
        var exponent: [4]u8 = undefined;
        var normalized_exponent: [8]u8 = undefined;
        const normalized_hex = if (exponent_hex.len % 2 == 0) exponent_hex else blk: {
            normalized_exponent[0] = '0';
            @memcpy(normalized_exponent[1 .. exponent_hex.len + 1], exponent_hex);
            break :blk normalized_exponent[0 .. exponent_hex.len + 1];
        };
        const exponent_bytes = std.fmt.hexToBytes(&exponent, normalized_hex) catch return error.KeystoreProofInvalid;
        const public_key = std.crypto.Certificate.rsa.PublicKey.fromBytes(exponent_bytes, modulus_bytes) catch return error.KeystoreProofInvalid;
        const sig: [modulus_length]u8 = signature[0..modulus_length].*;
        std.crypto.Certificate.rsa.PKCS1v1_5Signature.verify(modulus_length, sig, challenge, public_key, std.crypto.hash.sha2.Sha256) catch return error.KeystoreProofInvalid;
    }

    pub fn authenticate(allocator: std.mem.Allocator) !void {
        if (AndroidKeystoreOptions.rsa_modulus_hex.len != modulus_length * 2 or AndroidKeystoreOptions.termux_keystore_path.len == 0) return error.KeystoreGateNotConfigured;

        const list_argv = [_][]const u8{ AndroidKeystoreOptions.termux_keystore_path, "list", "-d" };
        const details = try captureBridge(allocator, &list_argv, null, 1024 * 1024);
        defer allocator.free(details);
        try verifyKeyEnrollment(allocator, details);

        var nonce: [32]u8 = undefined;
        std.crypto.random.bytes(&nonce);
        defer secureZero(&nonce);
        var challenge: [challenge_domain.len + nonce.len]u8 = undefined;
        @memcpy(challenge[0..challenge_domain.len], challenge_domain);
        @memcpy(challenge[challenge_domain.len..], &nonce);
        defer secureZero(&challenge);

        const sign_argv = [_][]const u8{ AndroidKeystoreOptions.termux_keystore_path, "sign", AndroidKeystoreOptions.key_alias, "SHA256withRSA" };
        const signature = try captureBridge(allocator, &sign_argv, &challenge, modulus_length + 1);
        defer secureZero(signature);
        defer allocator.free(signature);
        try verifySignature(AndroidKeystoreOptions.rsa_modulus_hex, AndroidKeystoreOptions.rsa_exponent_hex, &challenge, signature);
    }
};

fn guiQuantumStatusAlloc(allocator: std.mem.Allocator) ![]u8 {
    const rows = try QuantumEnsemble.status(allocator);
    var out = std.ArrayList(u8).empty;
    defer out.deinit(allocator);
    try out.appendSlice(allocator, "TOP CIRCUITS\n");
    for (rows) |row| {
        const p = QuantumEnsemble.profiles[row.index];
        var line_buf: [256]u8 = undefined;
        const line = try std.fmt.bufPrint(&line_buf, "{s}  {}q  {s}  H={d:.3}  E={d:.3}  runs={}  clef={}\n", .{
            p.id,
            p.qubits,
            p.bias,
            row.historical_score,
            row.mean_entropy,
            row.runs,
            row.clef_updates,
        });
        try out.appendSlice(allocator, line);
    }
    return try out.toOwnedSlice(allocator);
}

fn guiRefreshQuantum(allocator: std.mem.Allocator, ui: *NativeGui.App) void {
    const status = guiQuantumStatusAlloc(allocator) catch |err| {
        var buf: [160]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Unable to read quantum history: {s}", .{@errorName(err)}) catch "Unable to read quantum history.";
        ui.setQuantum(msg);
        return;
    };
    defer allocator.free(status);
    ui.setQuantum(status);
}

fn guiRecordClef(allocator: std.mem.Allocator, ui: *NativeGui.App, score_text: []const u8) void {
    const trimmed = std.mem.trim(u8, score_text, " \t\r\n");
    if (trimmed.len == 0) {
        ui.setOutput("Enter a Clef score from 0 to 100.");
        return;
    }
    const score = std.fmt.parseFloat(f64, trimmed) catch {
        ui.setOutput("Clef score must be a number from 0 to 100.");
        return;
    };
    const update = QuantumEnsemble.recordClef(allocator, score, null) catch |err| {
        var buf: [192]u8 = undefined;
        const msg = std.fmt.bufPrint(&buf, "Clef feedback rejected: {s}", .{@errorName(err)}) catch "Clef feedback rejected.";
        ui.setOutput(msg);
        return;
    };
    const p = QuantumEnsemble.profiles[update.circuit_index];
    var buf: [256]u8 = undefined;
    const msg = std.fmt.bufPrint(&buf, "Clef feedback applied to {s}: {d:.3} -> {d:.3}", .{ p.id, update.historical_before, update.historical_after }) catch "Clef feedback applied.";
    ui.setOutput(msg);
    ui.clearClef();
    guiRefreshQuantum(allocator, ui);
}

fn guiChatSubmit(allocator: std.mem.Allocator, ui: *NativeGui.App, task: *GuiInferenceTask) !void {
    const message = ui.chatText();
    if (message.len == 0) {
        ui.setOutput("Message is blank.");
        return;
    }
    if (std.mem.startsWith(u8, message, "/clef")) {
        guiRecordClef(allocator, ui, std.mem.trim(u8, message[@min(message.len, 5)..], " \t\r\n"));
        ui.clearChat();
        return;
    }
    if (std.mem.eql(u8, message, "/quantum")) {
        guiRefreshQuantum(allocator, ui);
        ui.setOutput("Quantum history refreshed. Open Quantum in the navigation rail to inspect it.");
        ui.clearChat();
        return;
    }

    var routed_owned: ?[]u8 = null;
    defer if (routed_owned) |owned| allocator.free(owned);
    const category = QuantumEnsemble.inferCategory(message);
    const route_opt: ?QuantumEnsemble.Route = QuantumEnsemble.choose(allocator, message, category) catch null;
    if (route_opt) |route| {
        if (QuantumEnsemble.contextAlloc(allocator, route) catch null) |ctx| {
            defer allocator.free(ctx);
            routed_owned = std.fmt.allocPrint(allocator, "{s}\n\n{s}", .{ ctx, message }) catch null;
        }
        const p = QuantumEnsemble.profiles[route.circuit_index];
        var route_buf: [512]u8 = undefined;
        const route_text = std.fmt.bufPrint(&route_buf, "{s} / {}q / {s} / p={d:.3} / entropy={d:.3}", .{ p.id, p.qubits, p.bias, route.probability, route.entropy }) catch "Quantum route selected.";
        ui.setRoute(route_text);
    } else {
        ui.setRoute("Quantum route unavailable; the model receives your message directly.");
    }

    try task.start(allocator, "chat", routed_owned orelse message);
    ui.setOutput("Loading verified GGUF and generating a model reply...");
    ui.clearChat();
}

fn guiScannerSubmit(allocator: std.mem.Allocator, ui: *NativeGui.App, task: *GuiInferenceTask, food_mode: bool) !void {
    const location = ui.scanText(food_mode, 0);
    const item_type = ui.scanText(food_mode, 1);
    const weather = ui.scanText(food_mode, 2);
    const traffic = ui.scanText(food_mode, 3);
    const obstacles = ui.scanText(food_mode, 4);
    const notes = ui.scanText(food_mode, 5);

    const raw_prompt = if (food_mode)
        try buildFoodWaterRiskPrompt(allocator, location, item_type, weather, traffic, obstacles, notes)
    else
        try buildRoadRiskPrompt(allocator, location, item_type, weather, traffic, obstacles, notes);
    defer allocator.free(raw_prompt);

    var routed_owned: ?[]u8 = null;
    defer if (routed_owned) |owned| allocator.free(owned);
    if (!food_mode) {
        const route_query = try std.fmt.allocPrint(allocator, "{s} {s} {s} {s} {s} {s}\n{s}", .{ location, item_type, weather, traffic, obstacles, notes, raw_prompt });
        defer allocator.free(route_query);
        const route_opt: ?QuantumEnsemble.Route = QuantumEnsemble.choose(allocator, route_query, "road-risk") catch null;
        if (route_opt) |route| {
            if (QuantumEnsemble.contextAlloc(allocator, route) catch null) |ctx| {
                defer allocator.free(ctx);
                routed_owned = std.fmt.allocPrint(allocator, "{s}\n\n{s}", .{ ctx, raw_prompt }) catch null;
            }
            const p = QuantumEnsemble.profiles[route.circuit_index];
            var route_buf: [512]u8 = undefined;
            const route_text = std.fmt.bufPrint(&route_buf, "{s} / {}q / {s} / p={d:.3} / entropy={d:.3}", .{ p.id, p.qubits, p.bias, route.probability, route.entropy }) catch "Road route selected.";
            ui.setRoute(route_text);
        }
    } else {
        ui.setRoute("Food/water mode keeps the Python parity path: no quantum routing injected.");
    }

    try task.start(allocator, if (food_mode) "food" else "road", routed_owned orelse raw_prompt);
    ui.setOutput("Loading verified GGUF and evaluating the supplied observations with the model...");
}

fn runNativeGui(allocator: std.mem.Allocator, force_phone: bool) !void {
    if (builtin.os.tag != .linux or builtin.abi == .android) return error.GuiBackendUnavailable;
    var ui = try NativeGui.App.init(allocator, force_phone);
    defer ui.deinit();
    try ui.harden();
    guiRefreshQuantum(allocator, &ui);
    var model_task = GuiModelTask{};
    defer model_task.deinit();
    var inference_task = GuiInferenceTask{};
    defer inference_task.deinit();

    while (ui.isRunning()) {
        if (inference_task.busy()) {
            const completed = inference_task.poll() catch |err| blk: {
                inference_task.cancel();
                var msg: [256]u8 = undefined;
                ui.setOutput(std.fmt.bufPrint(&msg, "Inference failed: {s}", .{@errorName(err)}) catch "Inference failed.");
                break :blk false;
            };
            if (completed) ui.setOutput(inference_task.text());
        }
        ui.inference_busy = inference_task.busy();
        if (model_task.busy()) {
            model_task.poll(PinnedModel.file) catch |err| {
                if (model_task.busy()) model_task.cancel();
                var buf: [192]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "Model operation failed: {s}. Existing model preserved.", .{@errorName(err)}) catch "Model operation failed.";
                ui.setModelStatus(msg, false);
                continue;
            };
            if (model_task.text().len != 0) ui.setModelStatus(model_task.text(), model_task.busy());
        }
        try ui.pump();
        switch (ui.takeAction()) {
            .none => {},
            .model_download, .model_verify => |action| {
                model_task.start(allocator, PinnedModel.file, action == .model_download) catch |err| {
                    var buf: [192]u8 = undefined;
                    const msg = std.fmt.bufPrint(&buf, "Model operation refused: {s}. Use a model directory owned by you without group/world write access.", .{@errorName(err)}) catch "Model operation refused.";
                    ui.setModelStatus(msg, false);
                    continue;
                };
                ui.setModelStatus(model_task.text(), true);
            },
            .model_cancel => {
                model_task.cancel();
                ui.setModelStatus(model_task.text(), false);
            },
            .inference_cancel => {
                inference_task.cancel();
                ui.setOutput(inference_task.text());
            },
            .chat_submit => guiChatSubmit(allocator, &ui, &inference_task) catch |err| {
                var buf: [192]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "Chat action failed: {s}", .{@errorName(err)}) catch "Chat action failed.";
                ui.setOutput(msg);
            },
            .road_scan => guiScannerSubmit(allocator, &ui, &inference_task, false) catch |err| {
                var buf: [192]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "Road scan failed: {s}", .{@errorName(err)}) catch "Road scan failed.";
                ui.setOutput(msg);
            },
            .food_scan => guiScannerSubmit(allocator, &ui, &inference_task, true) catch |err| {
                var buf: [192]u8 = undefined;
                const msg = std.fmt.bufPrint(&buf, "Food/water scan failed: {s}", .{@errorName(err)}) catch "Food/water scan failed.";
                ui.setOutput(msg);
            },
            .clef_submit => guiRecordClef(allocator, &ui, ui.clefText()),
            .quantum_refresh => guiRefreshQuantum(allocator, &ui),
            .self_test => {
                selfTestRuntime() catch |err| {
                    var buf: [192]u8 = undefined;
                    const msg = std.fmt.bufPrint(&buf, "Self-test failed: {s}", .{@errorName(err)}) catch "Self-test failed.";
                    ui.setSecurity(msg);
                    continue;
                };
                ui.setSecurity("Self-test: OK. Cryptographic KATs and runtime integrity checks completed successfully.");
            },
            .clear_sensitive => {
                if (inference_task.busy()) inference_task.cancel();
                inference_task.deinit();
                inference_task = .{};
                ui.inference_busy = false;
                ui.clearSensitive();
                ui.setSecurity("Sensitive edit buffers scrubbed in-place. Conversation text is not persisted by the GUI.");
            },
        }
    }
}

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    const args = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, args);

    if (builtin.abi == .android) try AndroidKeystoreGate.authenticate(allocator);

    if (args.len >= 2 and std.mem.eql(u8, args[1], "install")) {
        var input = TuiInput{ .file = std.fs.File.stdin() };
        try runAndroidInstallCheckpoint(&input);
        return;
    }

    if (args.len < 2) {
        if (builtin.os.tag == .linux and builtin.abi != .android) {
            const has_display = std.process.hasEnvVar(allocator, "DISPLAY") catch false;
            if (has_display) {
                runNativeGui(allocator, false) catch |err| {
                    std.debug.print("GUI unavailable ({s}); falling back to TUI.\n", .{@errorName(err)});
                    if (std.fs.File.stdin().isTty()) try runTui(allocator) else usage();
                };
                return;
            }
        }
        if (std.fs.File.stdin().isTty()) try runTui(allocator) else usage();
        return;
    }

    if (builtin.os.tag == .linux and builtin.abi != .android) {
        if (std.mem.eql(u8, args[1], "gui") or std.mem.eql(u8, args[1], "gui-phone")) {
            try runNativeGui(allocator, std.mem.eql(u8, args[1], "gui-phone"));
            return;
        }
    }
    if (std.mem.eql(u8, args[1], "tui")) {
        try runTui(allocator);
        return;
    }
    if (std.mem.eql(u8, args[1], "infer")) {
        if (args.len != 4 and args.len != 5) return error.InvalidArguments;
        const mode = std.meta.stringToEnum(InferenceMode, args[2]) orelse return error.InvalidArguments;
        const count = try std.fmt.parseInt(usize, args[3], 10);
        if (count == 0 or count > 256) return error.InvalidArguments;
        var input_buffer: [8193]u8 = undefined;
        const prompt = if (args.len == 5) args[4] else blk: {
            const n = try std.fs.File.stdin().readAll(&input_buffer);
            if (n == 0 or n > 8192) return error.InvalidArguments;
            break :blk input_buffer[0..n];
        };
        defer secureZero(&input_buffer);
        if (prompt.len == 0 or prompt.len > 8192) return error.InvalidArguments;
        const answer = try runPinnedModelMode(allocator, prompt, mode, count);
        defer allocator.free(answer);
        try std.fs.File.stdout().writeAll(answer);
        try std.fs.File.stdout().writeAll("\n");
        return;
    }
    if (std.mem.eql(u8, args[1], "model")) {
        std.debug.print("file: {s}\nsha256: {s}\nrepo: {s}\n", .{ PinnedModel.file, PinnedModel.sha256_hex, PinnedModel.repo });
        return;
    }
    if (std.mem.eql(u8, args[1], "download")) {
        if (args.len != 3) return error.InvalidArguments;
        const bytes = try downloadPinnedModelInternal(allocator, args[2], true);
        std.debug.print("downloaded and verified {} bytes: {s}\n", .{ bytes, args[2] });
        return;
    }
    if (std.mem.eql(u8, args[1], "verify")) {
        if (args.len != 3) return error.InvalidArguments;
        try verifyPinnedModel(args[2]);
        std.debug.print("verified: {s}\n", .{args[2]});
        return;
    }
    if (std.mem.eql(u8, args[1], "pqc")) {
        for (pqc_algorithms) |a| std.debug.print("{s}\t{s}\t{s}\t{s}\n", .{ a.id, @tagName(a.kind), @tagName(a.status), @tagName(a.implementation) });
        return;
    }
    if (std.mem.eql(u8, args[1], "gguf")) {
        if (args.len != 3) return error.InvalidArguments;
        try inspectGguf(args[2]);
        return;
    }
    if (std.mem.eql(u8, args[1], "selftest")) {
        try selfTestRuntime();
        std.debug.print("selftest: ok\n", .{});
        return;
    }
    usage();
}

