test "ML-KEM negacyclic multiply" {
    var a = [_]i16{0} ** MlKem.n;
    var b = [_]i16{0} ** MlKem.n;
    a[255] = 1;
    b[1] = 1;
    const c = MlKem.mulNegacyclic(a, b);
    try std.testing.expectEqual(@as(i16, MlKem.q - 1), c[0]);
}

