// ============================================================================
// EXPANSION 0.6 — ML-KEM IND-CPA/KEM implementation, GGUF binding,
// tokenizer metadata ingestion, executable mapped-model views, and ML-DSA
// serialization/signature transcript machinery. Pure Zig; no C ABI.
// ============================================================================

pub const MlKemSizes = struct {
    pub fn polyVecBytes(params: MlKem.Params) usize {
        return @as(usize, params.k) * MlKemCodec.poly_bytes;
    }
    pub fn indCpaPublicKeyBytes(params: MlKem.Params) usize {
        return polyVecBytes(params) + 32;
    }
    pub fn indCpaSecretKeyBytes(params: MlKem.Params) usize {
        return polyVecBytes(params);
    }
    pub fn publicKeyBytes(params: MlKem.Params) usize {
        return indCpaPublicKeyBytes(params);
    }
    pub fn secretKeyBytes(params: MlKem.Params) usize {
        return indCpaSecretKeyBytes(params) + indCpaPublicKeyBytes(params) + 64;
    }
    pub fn cipherTextBytes(params: MlKem.Params) usize {
        const du_bytes = (@as(usize, params.k) * MlKem.n * @as(usize, params.du)) / 8;
        const dv_bytes = (MlKem.n * @as(usize, params.dv)) / 8;
        return du_bytes + dv_bytes;
    }
};

pub const MlKemBitCodec = struct {
    pub fn pack(out: []u8, values: []const u16, bits: u5) !void {
        const need = (values.len * @as(usize, bits) + 7) / 8;
        if (out.len != need) return error.LengthMismatch;
        @memset(out, 0);
        var acc: u64 = 0;
        var acc_bits: u6 = 0;
        var pos: usize = 0;
        const mask: u16 = @truncate((@as(u32, 1) << bits) - 1);
        for (values) |v| {
            if (v > mask) return error.NonCanonicalEncoding;
            acc |= @as(u64, v & mask) << acc_bits;
            acc_bits += bits;
            while (acc_bits >= 8) {
                out[pos] = @truncate(acc);
                pos += 1;
                acc >>= 8;
                acc_bits -= 8;
            }
        }
        if (acc_bits != 0) {
            if (pos >= out.len) return error.BufferTooSmall;
            out[pos] = @truncate(acc);
        }
    }

    pub fn unpack(values: []u16, src: []const u8, bits: u5) !void {
        const need = (values.len * @as(usize, bits) + 7) / 8;
        if (src.len != need) return error.LengthMismatch;
        var acc: u64 = 0;
        var acc_bits: u6 = 0;
        var pos: usize = 0;
        const mask: u64 = (@as(u64, 1) << bits) - 1;
        for (values) |*v| {
            while (acc_bits < bits) {
                if (pos >= src.len) return error.TruncatedInput;
                acc |= @as(u64, src[pos]) << acc_bits;
                pos += 1;
                acc_bits += 8;
            }
            v.* = @truncate(acc & mask);
            acc >>= bits;
            acc_bits -= bits;
        }
    }
};

test "ML-KEM bit codec rejects non-canonical values" {
    var out: [1]u8 = undefined;
    try std.testing.expectError(error.NonCanonicalEncoding, MlKemBitCodec.pack(&out, &[_]u16{16}, 4));
    try MlKemBitCodec.pack(&out, &[_]u16{ 15, 0 }, 4);
    var values: [2]u16 = undefined;
    try MlKemBitCodec.unpack(&values, &out, 4);
    try std.testing.expectEqual(@as(u16, 15), values[0]);
    try std.testing.expectEqual(@as(u16, 0), values[1]);
}

pub const MlKemSerialization = struct {
    pub fn packPolyVec(out: []u8, v: *const MlKemVec.PolyVec, k: usize) !void {
        if (k < 2 or k > MlKemVec.max_k) return error.InvalidParameterSet;
        if (out.len != k * MlKemCodec.poly_bytes) return error.LengthMismatch;
        var i: usize = 0;
        while (i < k) : (i += 1) {
            var tmp: [MlKemCodec.poly_bytes]u8 = undefined;
            MlKemCodec.polyToBytes(&tmp, &v[i]);
            @memcpy(out[i * MlKemCodec.poly_bytes .. (i + 1) * MlKemCodec.poly_bytes], &tmp);
        }
    }

    pub fn unpackPolyVec(v: *MlKemVec.PolyVec, src: []const u8, k: usize) !void {
        if (k < 2 or k > MlKemVec.max_k) return error.InvalidParameterSet;
        if (src.len != k * MlKemCodec.poly_bytes) return error.LengthMismatch;
        var i: usize = 0;
        while (i < k) : (i += 1) {
            var tmp: [MlKemCodec.poly_bytes]u8 = undefined;
            @memcpy(&tmp, src[i * MlKemCodec.poly_bytes .. (i + 1) * MlKemCodec.poly_bytes]);
            MlKemCodec.polyFromBytes(&v[i], &tmp);
        }
    }

    pub fn packPublicKey(out: []u8, t: *const MlKemVec.PolyVec, rho: *const [32]u8, params: MlKem.Params) !void {
        if (out.len != MlKemSizes.indCpaPublicKeyBytes(params)) return error.LengthMismatch;
        const pv = MlKemSizes.polyVecBytes(params);
        try packPolyVec(out[0..pv], t, params.k);
        @memcpy(out[pv .. pv + 32], rho);
    }

    pub fn unpackPublicKey(t: *MlKemVec.PolyVec, rho: *[32]u8, src: []const u8, params: MlKem.Params) !void {
        if (src.len != MlKemSizes.indCpaPublicKeyBytes(params)) return error.LengthMismatch;
        const pv = MlKemSizes.polyVecBytes(params);
        try unpackPolyVec(t, src[0..pv], params.k);
        @memcpy(rho, src[pv .. pv + 32]);
    }

    pub fn packSecretKey(out: []u8, s: *const MlKemVec.PolyVec, params: MlKem.Params) !void {
        try packPolyVec(out, s, params.k);
    }

    pub fn unpackSecretKey(s: *MlKemVec.PolyVec, src: []const u8, params: MlKem.Params) !void {
        try unpackPolyVec(s, src, params.k);
    }

    pub fn compressVector(out: []u8, v: *const MlKemVec.PolyVec, params: MlKem.Params) !void {
        const count = @as(usize, params.k) * MlKem.n;
        if (out.len != (count * @as(usize, params.du)) / 8) return error.LengthMismatch;
        var vals: [MlKemVec.max_k * MlKem.n]u16 = undefined;
        var p: usize = 0;
        var i: usize = 0;
        while (i < params.k) : (i += 1) {
            var j: usize = 0;
            while (j < MlKem.n) : (j += 1) {
                vals[p] = MlKemCodec.compressCoeff(v[i][j], @intCast(params.du));
                p += 1;
            }
        }
        try MlKemBitCodec.pack(out, vals[0..count], @intCast(params.du));
    }

    pub fn decompressVector(v: *MlKemVec.PolyVec, src: []const u8, params: MlKem.Params) !void {
        const count = @as(usize, params.k) * MlKem.n;
        if (src.len != (count * @as(usize, params.du)) / 8) return error.LengthMismatch;
        var vals: [MlKemVec.max_k * MlKem.n]u16 = undefined;
        try MlKemBitCodec.unpack(vals[0..count], src, @intCast(params.du));
        var p: usize = 0;
        var i: usize = 0;
        while (i < params.k) : (i += 1) {
            var j: usize = 0;
            while (j < MlKem.n) : (j += 1) {
                v[i][j] = MlKemCodec.decompressCoeff(vals[p], @intCast(params.du));
                p += 1;
            }
        }
    }

    pub fn compressPoly(out: []u8, p: *const MlKem.Poly, bits: u5) !void {
        if (bits != 4 and bits != 5) return error.InvalidParameterSet;
        const count = MlKem.n;
        if (out.len != (count * @as(usize, bits)) / 8) return error.LengthMismatch;
        var vals: [MlKem.n]u16 = undefined;
        for (&vals, 0..) |*v, i| v.* = MlKemCodec.compressCoeff(p[i], bits);
        try MlKemBitCodec.pack(out, &vals, bits);
    }

    pub fn decompressPoly(p: *MlKem.Poly, src: []const u8, bits: u5) !void {
        if (bits != 4 and bits != 5) return error.InvalidParameterSet;
        if (src.len != (MlKem.n * @as(usize, bits)) / 8) return error.LengthMismatch;
        var vals: [MlKem.n]u16 = undefined;
        try MlKemBitCodec.unpack(&vals, src, bits);
        for (&vals, 0..) |v, i| p[i] = MlKemCodec.decompressCoeff(v, bits);
    }

    pub fn packCiphertext(out: []u8, b: *const MlKemVec.PolyVec, v: *const MlKem.Poly, params: MlKem.Params) !void {
        if (out.len != MlKemSizes.cipherTextBytes(params)) return error.LengthMismatch;
        const u_bytes = (@as(usize, params.k) * MlKem.n * @as(usize, params.du)) / 8;
        try compressVector(out[0..u_bytes], b, params);
        try compressPoly(out[u_bytes..], v, @intCast(params.dv));
    }

    pub fn unpackCiphertext(b: *MlKemVec.PolyVec, v: *MlKem.Poly, src: []const u8, params: MlKem.Params) !void {
        if (src.len != MlKemSizes.cipherTextBytes(params)) return error.LengthMismatch;
        const u_bytes = (@as(usize, params.k) * MlKem.n * @as(usize, params.du)) / 8;
        try decompressVector(b, src[0..u_bytes], params);
        try decompressPoly(v, src[u_bytes..], @intCast(params.dv));
    }
};

pub const MlKemIndCpaFull = struct {
    pub fn keypair(pk: []u8, sk: []u8, seed: *const [32]u8, params: MlKem.Params) !void {
        if (pk.len != MlKemSizes.indCpaPublicKeyBytes(params)) return error.LengthMismatch;
        if (sk.len != MlKemSizes.indCpaSecretKeyBytes(params)) return error.LengthMismatch;
        var t: MlKemVec.PolyVec = undefined;
        var s: MlKemVec.PolyVec = undefined;
        defer secureZero(std.mem.asBytes(&s));
        var rho: [32]u8 = undefined;
        try MlKemIndCpa.keypairCore(&t, &s, &rho, seed, params);
        try MlKemSerialization.packPublicKey(pk, &t, &rho, params);
        try MlKemSerialization.packSecretKey(sk, &s, params);
    }

    pub fn encrypt(ct: []u8, msg: *const [32]u8, pk: []const u8, coins: *const [32]u8, params: MlKem.Params) !void {
        if (ct.len != MlKemSizes.cipherTextBytes(params)) return error.LengthMismatch;
        if (pk.len != MlKemSizes.indCpaPublicKeyBytes(params)) return error.LengthMismatch;

        var pkpv: MlKemVec.PolyVec = undefined;
        var rho: [32]u8 = undefined;
        try MlKemSerialization.unpackPublicKey(&pkpv, &rho, pk, params);
        var at: MlKemIndCpa.Matrix = undefined;
        try MlKemIndCpa.genMatrix(&at, &rho, params.k, true);

        var sp: MlKemVec.PolyVec = undefined;
        defer secureZero(std.mem.asBytes(&sp));
        var ep: MlKemVec.PolyVec = undefined;
        defer secureZero(std.mem.asBytes(&ep));
        var nonce: u8 = 0;
        var i: usize = 0;
        while (i < params.k) : (i += 1) {
            sp[i] = if (params.eta1 == 3) MlKemCodec.noiseEta3(coins, nonce) else MlKemCodec.noiseEta2(coins, nonce);
            nonce +%= 1;
        }
        i = 0;
        while (i < params.k) : (i += 1) {
            ep[i] = MlKemCodec.noiseEta2(coins, nonce);
            nonce +%= 1;
        }
        var epp = MlKemCodec.noiseEta2(coins, nonce);
        defer secureZero(std.mem.asBytes(&epp));
        var mpoly: MlKem.Poly = undefined;
        defer secureZero(std.mem.asBytes(&mpoly));
        MlKemCodec.fromMsg(&mpoly, msg);

        MlKemVec.ntt(&sp, params.k);
        var b: MlKemVec.PolyVec = undefined;
        i = 0;
        while (i < params.k) : (i += 1) MlKemVec.pointwiseAcc(&b[i], &at[i], &sp, params.k);
        var v: MlKem.Poly = undefined;
        MlKemVec.pointwiseAcc(&v, &pkpv, &sp, params.k);
        MlKemVec.invNtt(&b, params.k);
        MlKemNtt.invNttToMont(&v);

        i = 0;
        while (i < params.k) : (i += 1) b[i] = MlKem.add(b[i], ep[i]);
        v = MlKem.add(v, epp);
        v = MlKem.add(v, mpoly);
        MlKemVec.reduce(&b, params.k);
        MlKemNtt.polyReduce(&v);
        try MlKemSerialization.packCiphertext(ct, &b, &v, params);
    }

    pub fn decrypt(msg: *[32]u8, ct: []const u8, sk: []const u8, params: MlKem.Params) !void {
        if (ct.len != MlKemSizes.cipherTextBytes(params)) return error.LengthMismatch;
        if (sk.len != MlKemSizes.indCpaSecretKeyBytes(params)) return error.LengthMismatch;
        var b: MlKemVec.PolyVec = undefined;
        var v: MlKem.Poly = undefined;
        try MlKemSerialization.unpackCiphertext(&b, &v, ct, params);
        var s: MlKemVec.PolyVec = undefined;
        defer secureZero(std.mem.asBytes(&s));
        try MlKemSerialization.unpackSecretKey(&s, sk, params);
        MlKemVec.ntt(&b, params.k);
        var mp: MlKem.Poly = undefined;
        MlKemVec.pointwiseAcc(&mp, &s, &b, params.k);
        MlKemNtt.invNttToMont(&mp);
        mp = MlKem.sub(v, mp);
        MlKemNtt.polyReduce(&mp);
        MlKemCodec.toMsg(msg, &mp);
    }
};

pub const MlKemKdf = struct {
    pub fn hashH(data: []const u8) [32]u8 {
        return sha3_256(data);
    }
    pub fn hashG(data: []const u8) [64]u8 {
        var out: [64]u8 = undefined;
        out = sha3_512(data);
        return out;
    }
    pub fn kdf(data: []const u8) [32]u8 {
        var out: [32]u8 = undefined;
        shake256(data, &out);
        return out;
    }
};

const MlKemKem = struct {
    pub fn keypair(pk: []u8, sk: []u8, d: *const [32]u8, z: *const [32]u8, params: MlKem.Params) !void {
        const ind_sk_n = MlKemSizes.indCpaSecretKeyBytes(params);
        const pk_n = MlKemSizes.indCpaPublicKeyBytes(params);
        if (pk.len != pk_n or sk.len != MlKemSizes.secretKeyBytes(params)) return error.LengthMismatch;
        try MlKemIndCpaFull.keypair(pk, sk[0..ind_sk_n], d, params);
        @memcpy(sk[ind_sk_n .. ind_sk_n + pk_n], pk);
        const hpk = MlKemKdf.hashH(pk);
        @memcpy(sk[ind_sk_n + pk_n .. ind_sk_n + pk_n + 32], &hpk);
        @memcpy(sk[ind_sk_n + pk_n + 32 .. ind_sk_n + pk_n + 64], z);
    }

    pub fn encapsulate(ct: []u8, ss: *[32]u8, pk: []const u8, randomness: *const [32]u8, params: MlKem.Params) !void {
        // FIPS 203 ML-KEM.Encaps_internal: (K, r) = G(m || H(ek)), c = K-PKE.Encrypt(ek,m,r).
        if (pk.len != MlKemSizes.publicKeyBytes(params)) return error.LengthMismatch;
        if (ct.len != MlKemSizes.cipherTextBytes(params)) return error.LengthMismatch;
        const hpk = MlKemKdf.hashH(pk);
        var g_in: [64]u8 = undefined;
        @memcpy(g_in[0..32], randomness);
        @memcpy(g_in[32..64], &hpk);
        var kr = MlKemKdf.hashG(&g_in);
        defer secureZero(&kr);
        var coins: [32]u8 = undefined;
        @memcpy(&coins, kr[32..64]);
        try MlKemIndCpaFull.encrypt(ct, randomness, pk, &coins, params);
        @memcpy(ss, kr[0..32]);
        secureZero(&g_in);
        secureZero(&coins);
    }

    fn rejectionKey(out: *[32]u8, z: []const u8, ct: []const u8) !void {
        if (z.len != 32) return error.LengthMismatch;
        var sponge = Keccak.Sponge.init(136, 0x1f);
        try sponge.update(z);
        try sponge.update(ct);
        sponge.finalize();
        try sponge.squeeze(out);
    }

    pub fn decapsulate(ss: *[32]u8, ct: []const u8, sk: []const u8, params: MlKem.Params) !void {
        // FIPS 203 implicit rejection: derive K' from decrypted m', re-encrypt,
        // and constant-time select J(z || c) when c != c'.
        const ind_sk_n = MlKemSizes.indCpaSecretKeyBytes(params);
        const pk_n = MlKemSizes.publicKeyBytes(params);
        if (ct.len != MlKemSizes.cipherTextBytes(params) or sk.len != MlKemSizes.secretKeyBytes(params)) return error.LengthMismatch;
        const pk = sk[ind_sk_n .. ind_sk_n + pk_n];
        const hpk = sk[ind_sk_n + pk_n .. ind_sk_n + pk_n + 32];
        const z = sk[ind_sk_n + pk_n + 32 .. ind_sk_n + pk_n + 64];

        var m: [32]u8 = undefined;
        try MlKemIndCpaFull.decrypt(&m, ct, sk[0..ind_sk_n], params);
        var g_in: [64]u8 = undefined;
        @memcpy(g_in[0..32], &m);
        @memcpy(g_in[32..64], hpk);
        var kr = MlKemKdf.hashG(&g_in);
        defer secureZero(&kr);
        var coins: [32]u8 = undefined;
        @memcpy(&coins, kr[32..64]);

        var ct_cmp: [1568]u8 = undefined;
        const ct_n = MlKemSizes.cipherTextBytes(params);
        try MlKemIndCpaFull.encrypt(ct_cmp[0..ct_n], &m, pk, &coins, params);
        const good_mask = ctCompareMask(ct, ct_cmp[0..ct_n]);

        var fallback: [32]u8 = undefined;
        try rejectionKey(&fallback, z, ct);
        var i: usize = 0;
        while (i < 32) : (i += 1) ss[i] = ctSelect(good_mask, kr[i], fallback[i]);

        secureZero(&m);
        secureZero(&g_in);
        secureZero(&coins);
        secureZero(&ct_cmp);
        secureZero(&fallback);
    }
};

// ----------------------------------------------------------------------------
// GGUF metadata convenience accessors and architecture extraction.
// ----------------------------------------------------------------------------

pub const GgufAccess = struct {
    pub fn asU64(v: *const OwnedGgufValue) ?u64 {
        return switch (v.*) {
            .u64v => |x| x,
            .i64v => |x| if (x >= 0) @intCast(x) else null,
            .f64v => |x| if (x >= 0 and x <= @as(f64, @floatFromInt(std.math.maxInt(u64)))) @intFromFloat(x) else null,
            else => null,
        };
    }

    pub fn asF64(v: *const OwnedGgufValue) ?f64 {
        return switch (v.*) {
            .f64v => |x| x,
            .u64v => |x| @floatFromInt(x),
            .i64v => |x| @floatFromInt(x),
            else => null,
        };
    }

    pub fn requireUsize(index: *const GgufIndex, key: []const u8) !usize {
        const v = index.findKv(key) orelse return error.MissingMetadata;
        const n = asU64(v) orelse return error.InvalidMetadataType;
        return std.math.cast(usize, n) orelse error.MetadataOutOfRange;
    }

    pub fn optionalUsize(index: *const GgufIndex, key: []const u8, default: usize) !usize {
        const v = index.findKv(key) orelse return default;
        const n = asU64(v) orelse return error.InvalidMetadataType;
        return std.math.cast(usize, n) orelse error.MetadataOutOfRange;
    }

    pub fn optionalF32(index: *const GgufIndex, key: []const u8, default: f32) !f32 {
        const v = index.findKv(key) orelse return default;
        const n = asF64(v) orelse return error.InvalidMetadataType;
        if (!std.math.isFinite(n)) return error.InvalidMetadata;
        return @floatCast(n);
    }

    pub fn llamaArch(index: *const GgufIndex) !LlamaArch {
        const emb = try requireUsize(index, "llama.embedding_length");
        const heads = try requireUsize(index, "llama.attention.head_count");
        const head_dim = if (heads == 0) return error.InvalidModelConfig else emb / heads;
        const arch = LlamaArch{
            .context_length = try requireUsize(index, "llama.context_length"),
            .embedding_length = emb,
            .feed_forward_length = try requireUsize(index, "llama.feed_forward_length"),
            .block_count = try requireUsize(index, "llama.block_count"),
            .head_count = heads,
            .head_count_kv = try optionalUsize(index, "llama.attention.head_count_kv", heads),
            .rope_dim = try optionalUsize(index, "llama.rope.dimension_count", head_dim),
            .rope_base = try optionalF32(index, "llama.rope.freq_base", 10000.0),
            .rms_epsilon = try optionalF32(index, "llama.attention.layer_norm_rms_epsilon", 1e-5),
            .vocab_size = blk: {
                const tv = index.findKv("tokenizer.ggml.tokens") orelse return error.MissingTokenizer;
                break :blk switch (tv.*) {
                    .array_string => |items| items.len,
                    else => return error.InvalidMetadataType,
                };
            },
        };
        try arch.validate();
        return arch;
    }
};

pub const GgufTokenizerMeta = struct {
    tokens: [][]u8,
    scores: ?[]f32,
    token_types: ?[]u32,
    bos_id: ?u32,
    eos_id: ?u32,
    unknown_id: ?u32,
    padding_id: ?u32,
    add_bos: bool,
    add_eos: bool,

    pub fn fromIndex(index: *const GgufIndex) !GgufTokenizerMeta {
        const tv = index.findKv("tokenizer.ggml.tokens") orelse return error.MissingTokenizer;
        const tokens = switch (tv.*) {
            .array_string => |x| x,
            else => return error.InvalidMetadataType,
        };
        const scores: ?[]f32 = if (index.findKv("tokenizer.ggml.scores")) |v| switch (v.*) {
            .array_f32 => |x| x,
            else => null,
        } else null;
        const types: ?[]u32 = if (index.findKv("tokenizer.ggml.token_type")) |v| switch (v.*) {
            .array_u32 => |x| x,
            else => null,
        } else null;
        if (scores) |x| if (x.len != tokens.len) return error.InvalidTokenizer;
        if (types) |x| if (x.len != tokens.len) return error.InvalidTokenizer;
        return .{
            .tokens = tokens,
            .scores = scores,
            .token_types = types,
            .bos_id = getTokenId(index, "tokenizer.ggml.bos_token_id"),
            .eos_id = getTokenId(index, "tokenizer.ggml.eos_token_id"),
            .unknown_id = getTokenId(index, "tokenizer.ggml.unknown_token_id"),
            .padding_id = getTokenId(index, "tokenizer.ggml.padding_token_id"),
            .add_bos = getBool(index, "tokenizer.ggml.add_bos_token", false),
            .add_eos = getBool(index, "tokenizer.ggml.add_eos_token", false),
        };
    }

    fn getTokenId(index: *const GgufIndex, key: []const u8) ?u32 {
        const v = index.findKv(key) orelse return null;
        const x = GgufAccess.asU64(v) orelse return null;
        return std.math.cast(u32, x);
    }

    fn getBool(index: *const GgufIndex, key: []const u8, default: bool) bool {
        const v = index.findKv(key) orelse return default;
        return switch (v.*) {
            .boolean => |x| x,
            else => default,
        };
    }

    pub fn validate(self: GgufTokenizerMeta) !void {
        if (self.tokens.len == 0 or self.tokens.len > 16 * 1024 * 1024) return error.InvalidTokenizer;
        for (self.tokens) |t| if (t.len > 1024 * 1024) return error.InvalidTokenizer;
        if (self.bos_id) |x| if (@as(usize, x) >= self.tokens.len) return error.InvalidTokenizer;
        if (self.eos_id) |x| if (@as(usize, x) >= self.tokens.len) return error.InvalidTokenizer;
        if (self.unknown_id) |x| if (@as(usize, x) >= self.tokens.len) return error.InvalidTokenizer;
    }
};

pub const TokenTrie = struct {
    pub const Node = struct {
        first_edge: u32 = std.math.maxInt(u32),
        token_id: u32 = std.math.maxInt(u32),
    };
    pub const Edge = struct {
        byte: u8,
        child: u32,
        next: u32 = std.math.maxInt(u32),
    };

    allocator: std.mem.Allocator,
    nodes: std.ArrayList(Node),
    edges: std.ArrayList(Edge),

    pub fn init(allocator: std.mem.Allocator) !TokenTrie {
        var self = TokenTrie{ .allocator = allocator, .nodes = .empty, .edges = .empty };
        try self.nodes.append(allocator, .{});
        return self;
    }

    pub fn deinit(self: *TokenTrie) void {
        self.nodes.deinit(self.allocator);
        self.edges.deinit(self.allocator);
        self.* = undefined;
    }

    fn findEdge(self: *const TokenTrie, node: u32, byte: u8) ?u32 {
        var e = self.nodes.items[node].first_edge;
        while (e != std.math.maxInt(u32)) {
            const edge = self.edges.items[e];
            if (edge.byte == byte) return edge.child;
            e = edge.next;
        }
        return null;
    }

    fn ensureEdge(self: *TokenTrie, node: u32, byte: u8) !u32 {
        if (self.findEdge(node, byte)) |x| return x;
        const child: u32 = @intCast(self.nodes.items.len);
        try self.nodes.append(self.allocator, .{});
        const edge_id: u32 = @intCast(self.edges.items.len);
        try self.edges.append(self.allocator, .{ .byte = byte, .child = child, .next = self.nodes.items[node].first_edge });
        self.nodes.items[node].first_edge = edge_id;
        return child;
    }

    pub fn insert(self: *TokenTrie, token: []const u8, id: u32) !void {
        var node: u32 = 0;
        for (token) |b| node = try self.ensureEdge(node, b);
        self.nodes.items[node].token_id = id;
    }

    pub fn build(allocator: std.mem.Allocator, meta: GgufTokenizerMeta) !TokenTrie {
        var trie = try init(allocator);
        errdefer trie.deinit();
        for (meta.tokens, 0..) |tok, i| try trie.insert(tok, @intCast(i));
        return trie;
    }

    pub const Match = struct { token_id: u32, bytes: usize };

    pub fn longest(self: *const TokenTrie, input: []const u8) ?Match {
        var node: u32 = 0;
        var best: ?Match = null;
        for (input, 0..) |b, i| {
            node = self.findEdge(node, b) orelse break;
            const tid = self.nodes.items[node].token_id;
            if (tid != std.math.maxInt(u32)) best = .{ .token_id = tid, .bytes = i + 1 };
        }
        return best;
    }
};

pub const GreedyGgufTokenizer = struct {
    allocator: std.mem.Allocator,
    meta: GgufTokenizerMeta,
    trie: TokenTrie,

    pub fn init(allocator: std.mem.Allocator, meta: GgufTokenizerMeta) !GreedyGgufTokenizer {
        try meta.validate();
        return .{ .allocator = allocator, .meta = meta, .trie = try TokenTrie.build(allocator, meta) };
    }

    pub fn deinit(self: *GreedyGgufTokenizer) void {
        self.trie.deinit();
        self.* = undefined;
    }

    pub fn encode(self: *const GreedyGgufTokenizer, allocator: std.mem.Allocator, text: []const u8) ![]u32 {
        var out: std.ArrayList(u32) = .empty;
        errdefer out.deinit(allocator);
        if (self.meta.add_bos) if (self.meta.bos_id) |id| try out.append(allocator, id);
        var pos: usize = 0;
        while (pos < text.len) {
            if (self.trie.longest(text[pos..])) |m| {
                try out.append(allocator, m.token_id);
                pos += m.bytes;
            } else if (self.meta.unknown_id) |unk| {
                try out.append(allocator, unk);
                pos += 1;
            } else return error.UnencodableByte;
        }
        if (self.meta.add_eos) if (self.meta.eos_id) |id| try out.append(allocator, id);
        return try out.toOwnedSlice(allocator);
    }

    pub fn decode(self: *const GreedyGgufTokenizer, allocator: std.mem.Allocator, ids: []const u32) ![]u8 {
        var out: std.ArrayList(u8) = .empty;
        errdefer out.deinit(allocator);
        for (ids) |id| {
            if (@as(usize, id) >= self.meta.tokens.len) return error.InvalidTokenId;
            try out.appendSlice(allocator, self.meta.tokens[@as(usize, id)]);
        }
        return try out.toOwnedSlice(allocator);
    }
};

// ----------------------------------------------------------------------------
// Bounded mapped-GGUF tensor views. The backing bytes may be mmap'd or loaded
// normally; the abstraction never assumes C mmap APIs.
// ----------------------------------------------------------------------------

pub const TensorByteView = struct {
    bytes: []const u8,
    ggml_type: GgmlType,
    dims: []const u64,

    pub fn elements(self: TensorByteView) !usize {
        var n: usize = 1;
        for (self.dims) |d| n = std.math.mul(usize, n, std.math.cast(usize, d) orelse return error.TensorTooLarge) catch return error.TensorTooLarge;
        return n;
    }
};

pub const GgufBoundFile = struct {
    file_bytes: []const u8,
    index: *const GgufIndex,

    pub fn tensor(self: GgufBoundFile, info: *const OwnedTensorInfo) !TensorByteView {
        const abs = std.math.add(u64, self.index.data_start, info.offset) catch return error.TensorOutOfBounds;
        const end = std.math.add(u64, abs, info.bytes) catch return error.TensorOutOfBounds;
        if (end > self.file_bytes.len) return error.TensorOutOfBounds;
        const a = std.math.cast(usize, abs) orelse return error.TensorOutOfBounds;
        const b = std.math.cast(usize, end) orelse return error.TensorOutOfBounds;
        return .{ .bytes = self.file_bytes[a..b], .ggml_type = info.ggml_type, .dims = info.dims };
    }

    pub fn named(self: GgufBoundFile, name: []const u8) !TensorByteView {
        return self.tensor(try self.index.requireTensor(name));
    }
};

pub const BoundLinear = struct {
    bytes: []const u8,
    ggml_type: GgmlType,
    rows: usize,
    cols: usize,

    pub fn fromTensor(t: TensorByteView) !BoundLinear {
        if (t.dims.len != 2) return error.ShapeMismatch;
        const cols = std.math.cast(usize, t.dims[0]) orelse return error.TensorTooLarge;
        const rows = std.math.cast(usize, t.dims[1]) orelse return error.TensorTooLarge;
        _ = try MixedLinear.expectedBytes(t.ggml_type, rows, cols);
        return .{ .bytes = t.bytes, .ggml_type = t.ggml_type, .rows = rows, .cols = cols };
    }

    pub fn scratchFloats(self: BoundLinear) usize {
        return switch (self.ggml_type) {
            .q3_k, .q4_k, .q5_k, .q6_k => 0,
            else => self.rows * self.cols,
        };
    }

    pub fn run(self: BoundLinear, out: []f32, x: []const f32, scratch: []f32) !void {
        if (out.len != self.rows or x.len != self.cols) return error.ShapeMismatch;
        try MixedLinear.apply(out, x, self.bytes, self.ggml_type, self.rows, self.cols, scratch);
    }
};

pub const BoundLlamaLayer = struct {
    attn_norm: TensorByteView,
    q: BoundLinear,
    k: BoundLinear,
    v: BoundLinear,
    o: BoundLinear,
    ffn_norm: TensorByteView,
    gate: BoundLinear,
    up: BoundLinear,
    down: BoundLinear,
};

pub const BoundLlamaModel = struct {
    allocator: std.mem.Allocator,
    arch: LlamaArch,
    embedding: TensorByteView,
    output_norm: TensorByteView,
    output: ?BoundLinear,
    layers: []BoundLlamaLayer,

    pub fn bind(allocator: std.mem.Allocator, file: GgufBoundFile) !BoundLlamaModel {
        const arch = try GgufAccess.llamaArch(file.index);
        try LlamaModelValidator.validateCore(file.index, arch);
        var layers = try allocator.alloc(BoundLlamaLayer, arch.block_count);
        errdefer allocator.free(layers);
        var name: [96]u8 = undefined;
        var i: usize = 0;
        while (i < arch.block_count) : (i += 1) {
            layers[i] = .{
                .attn_norm = try file.named(try LlamaTensorNames.attentionNorm(&name, i)),
                .q = try BoundLinear.fromTensor(try file.named(try LlamaTensorNames.attentionQ(&name, i))),
                .k = try BoundLinear.fromTensor(try file.named(try LlamaTensorNames.attentionK(&name, i))),
                .v = try BoundLinear.fromTensor(try file.named(try LlamaTensorNames.attentionV(&name, i))),
                .o = try BoundLinear.fromTensor(try file.named(try LlamaTensorNames.attentionOutput(&name, i))),
                .ffn_norm = try file.named(try LlamaTensorNames.ffnNorm(&name, i)),
                .gate = try BoundLinear.fromTensor(try file.named(try LlamaTensorNames.ffnGate(&name, i))),
                .up = try BoundLinear.fromTensor(try file.named(try LlamaTensorNames.ffnUp(&name, i))),
                .down = try BoundLinear.fromTensor(try file.named(try LlamaTensorNames.ffnDown(&name, i))),
            };
        }
        return .{
            .allocator = allocator,
            .arch = arch,
            .embedding = try file.named("token_embd.weight"),
            .output_norm = try file.named("output_norm.weight"),
            .output = if (file.index.findTensor("output.weight")) |_| try BoundLinear.fromTensor(try file.named("output.weight")) else null,
            .layers = layers,
        };
    }

    pub fn deinit(self: *BoundLlamaModel) void {
        self.allocator.free(self.layers);
        self.* = undefined;
    }
};

pub const FpTensor = struct {
    pub fn f16At(bytes: []const u8, index: usize) !f32 {
        const off = std.math.mul(usize, index, 2) catch return error.TensorOutOfBounds;
        if (off + 2 > bytes.len) return error.TensorOutOfBounds;
        const bits = @as(u16, bytes[off]) | (@as(u16, bytes[off + 1]) << 8);
        return @floatCast(@as(f16, @bitCast(bits)));
    }

    pub fn f32At(bytes: []const u8, index: usize) !f32 {
        const off = std.math.mul(usize, index, 4) catch return error.TensorOutOfBounds;
        if (off + 4 > bytes.len) return error.TensorOutOfBounds;
        const bits = @as(u32, bytes[off]) | (@as(u32, bytes[off + 1]) << 8) | (@as(u32, bytes[off + 2]) << 16) | (@as(u32, bytes[off + 3]) << 24);
        return @bitCast(bits);
    }

    pub fn loadVector(out: []f32, t: TensorByteView) !void {
        if (try t.elements() != out.len) return error.ShapeMismatch;
        for (out, 0..) |*v, i| v.* = switch (t.ggml_type) {
            .f16 => try f16At(t.bytes, i),
            .f32 => try f32At(t.bytes, i),
            else => return error.UnsupportedQuantization,
        };
    }

    pub fn loadEmbeddingRow(out: []f32, t: TensorByteView, token_id: usize) !void {
        if (t.dims.len != 2) return error.ShapeMismatch;
        const cols = std.math.cast(usize, t.dims[0]) orelse return error.TensorTooLarge;
        const rows = std.math.cast(usize, t.dims[1]) orelse return error.TensorTooLarge;
        if (out.len != cols or token_id >= rows) return error.ShapeMismatch;
        switch (t.ggml_type) {
            .f16 => {
                for (out, 0..) |*v, i| v.* = try f16At(t.bytes, token_id * cols + i);
            },
            .f32 => {
                for (out, 0..) |*v, i| v.* = try f32At(t.bytes, token_id * cols + i);
            },
            else => return error.UnsupportedEmbeddingQuantization,
        }
    }
};

// ----------------------------------------------------------------------------
// ML-DSA encoding/transcript implementation. Arithmetic remains in MlDsa above;
// this section supplies deterministic domain separation and bounds-aware packing.
// ----------------------------------------------------------------------------

pub const MlDsaDomain = struct {
    pub fn messageRepresentative(out: []u8, tr: *const [64]u8, context: []const u8, message: []const u8) !void {
        if (context.len > 255) return error.ContextTooLong;
        var sponge = Keccak.Sponge.init(136, 0x1f);
        try sponge.update(tr);
        const prefix = [_]u8{ 0, @intCast(context.len) };
        try sponge.update(&prefix);
        try sponge.update(context);
        try sponge.update(message);
        sponge.finalize();
        try sponge.squeeze(out);
    }

    pub fn challengeSeed(out: []u8, mu: []const u8, w1: []const u8) !void {
        if (out.len == 0 or out.len > 64) return error.InvalidParameterSet;
        var sponge = Keccak.Sponge.init(136, 0x1f);
        try sponge.update(mu);
        try sponge.update(w1);
        sponge.finalize();
        try sponge.squeeze(out);
    }
};

pub const MlDsaPacking = struct {
    pub fn packSigned(out: []u8, values: []const i32, min_value: i32, max_value: i32, bits: u6) !void {
        if (min_value > max_value) return error.InvalidParameterSet;
        const range: u64 = @intCast(@as(i64, max_value) - min_value + 1);
        if (range > (@as(u64, 1) << bits)) return error.InvalidParameterSet;
        if (out.len != (values.len * @as(usize, bits) + 7) / 8) return error.LengthMismatch;
        @memset(out, 0);
        var acc: u64 = 0;
        var acc_bits: u7 = 0;
        var pos: usize = 0;
        for (values) |x| {
            if (x < min_value or x > max_value) return error.CoefficientOutOfRange;
            const enc: u64 = @intCast(@as(i64, x) - min_value);
            acc |= enc << @intCast(acc_bits);
            acc_bits += bits;
            while (acc_bits >= 8) {
                out[pos] = @truncate(acc);
                pos += 1;
                acc >>= 8;
                acc_bits -= 8;
            }
        }
        if (acc_bits != 0) out[pos] = @truncate(acc);
    }

    pub fn unpackSigned(values: []i32, src: []const u8, min_value: i32, max_value: i32, bits: u6) !void {
        if (src.len != (values.len * @as(usize, bits) + 7) / 8) return error.LengthMismatch;
        const mask: u64 = (@as(u64, 1) << bits) - 1;
        var acc: u64 = 0;
        var acc_bits: u7 = 0;
        var pos: usize = 0;
        for (values) |*x| {
            while (acc_bits < bits) {
                if (pos >= src.len) return error.TruncatedInput;
                acc |= @as(u64, src[pos]) << @intCast(acc_bits);
                pos += 1;
                acc_bits += 8;
            }
            const enc = acc & mask;
            const decoded = @as(i64, min_value) + @as(i64, @intCast(enc));
            if (decoded > max_value) return error.NonCanonicalEncoding;
            x.* = @intCast(decoded);
            acc >>= bits;
            acc_bits -= bits;
        }
    }

    pub fn packEta(out: []u8, p: *const MlDsa.Poly, eta: i32) !void {
        const bits: u6 = if (eta == 2) 3 else if (eta == 4) 4 else return error.InvalidParameterSet;
        try packSigned(out, p, -eta, eta, bits);
    }

    pub fn unpackEta(p: *MlDsa.Poly, src: []const u8, eta: i32) !void {
        const bits: u6 = if (eta == 2) 3 else if (eta == 4) 4 else return error.InvalidParameterSet;
        try unpackSigned(p, src, -eta, eta, bits);
    }
};

pub const MlDsaHintCodec = struct {
    pub fn encode(out: []u8, hints: []const bool, omega: usize) !usize {
        const ones = blk: {
            var n: usize = 0;
            for (hints) |h| if (h) {
                n += 1;
            };
            break :blk n;
        };
        if (ones > omega) return error.TooManyHints;
        const index_bytes = if (hints.len <= 256) ones else ones * 2;
        if (out.len < index_bytes + 2) return error.BufferTooSmall;
        var p: usize = 0;
        for (hints, 0..) |h, i| if (h) {
            if (hints.len <= 256) {
                out[p] = @intCast(i);
                p += 1;
            } else {
                try writeU16Le(out[p .. p + 2], @intCast(i));
                p += 2;
            }
        };
        try writeU16Le(out[p .. p + 2], @intCast(ones));
        return p + 2;
    }
};

// ----------------------------------------------------------------------------
// Verification tests for the newly-added codecs and bindings.
// ----------------------------------------------------------------------------

test "ML-KEM bit codec roundtrip" {
    var vals = [_]u16{ 0, 1, 2, 3, 7, 15, 31, 17, 9, 5, 4, 2, 1 };
    var enc: [9]u8 = undefined;
    try MlKemBitCodec.pack(&enc, &vals, 5);
    var dec: [vals.len]u16 = undefined;
    try MlKemBitCodec.unpack(&dec, &enc, 5);
    try std.testing.expectEqualSlices(u16, &vals, &dec);
}

test "ML-KEM polynomial bytes canonical roundtrip" {
    var p: MlKem.Poly = undefined;
    for (&p, 0..) |*x, i| x.* = @intCast(i % MlKem.q);
    var bytes: [MlKemCodec.poly_bytes]u8 = undefined;
    MlKemCodec.polyToBytes(&bytes, &p);
    var q: MlKem.Poly = undefined;
    MlKemCodec.polyFromBytes(&q, &bytes);
    for (p, q) |a, b| try std.testing.expectEqual(a, b);
}

test "ML-KEM ciphertext size parameters" {
    try std.testing.expectEqual(@as(usize, 768), MlKemSizes.cipherTextBytes(MlKem.p512));
    try std.testing.expectEqual(@as(usize, 1088), MlKemSizes.cipherTextBytes(MlKem.p768));
    try std.testing.expectEqual(@as(usize, 1568), MlKemSizes.cipherTextBytes(MlKem.p1024));
}

test "token trie longest match" {
    const testing = std.testing;
    var trie = try TokenTrie.init(testing.allocator);
    defer trie.deinit();
    try trie.insert("a", 1);
    try trie.insert("abc", 2);
    const m = trie.longest("abcd") orelse return error.NoMatch;
    try testing.expectEqual(@as(u32, 2), m.token_id);
    try testing.expectEqual(@as(usize, 3), m.bytes);
}

test "ML-DSA bounded signed packing roundtrip" {
    var p = [_]i32{ -2, -1, 0, 1, 2, -2, 2, 0 };
    var enc: [3]u8 = undefined;
    try MlDsaPacking.packSigned(&enc, &p, -2, 2, 3);
    var q: [p.len]i32 = undefined;
    try MlDsaPacking.unpackSigned(&q, &enc, -2, 2, 3);
    try std.testing.expectEqualSlices(i32, &p, &q);
}

// ============================================================================
// CONTINUATION CHECKPOINT: production-facing tokenizer and bound executor
// ============================================================================

pub const GgufBpeMergeTable = struct {
    allocator: std.mem.Allocator,
    merges: []BpeMerge,

    pub fn deinit(self: *GgufBpeMergeTable) void {
        self.allocator.free(self.merges);
        self.* = undefined;
    }

    fn findTokenId(tokens: [][]u8, needle: []const u8) ?u32 {
        for (tokens, 0..) |tok, i| {
            if (std.mem.eql(u8, tok, needle)) return @intCast(i);
        }
        return null;
    }

    pub fn fromIndex(allocator: std.mem.Allocator, index: *const GgufIndex, meta: GgufTokenizerMeta) !GgufBpeMergeTable {
        const raw = index.findKv("tokenizer.ggml.merges") orelse return .{ .allocator = allocator, .merges = try allocator.alloc(BpeMerge, 0) };
        const lines = switch (raw.*) {
            .array_string => |x| x,
            else => return error.InvalidTokenizerMerges,
        };
        var list: std.ArrayList(BpeMerge) = .empty;
        errdefer list.deinit(allocator);
        for (lines, 0..) |line, rank| {
            const sep = std.mem.indexOfScalar(u8, line, ' ') orelse continue;
            if (sep == 0 or sep + 1 >= line.len) continue;
            const left_text = line[0..sep];
            const right_text = line[sep + 1 ..];
            const left = findTokenId(meta.tokens, left_text) orelse continue;
            const right = findTokenId(meta.tokens, right_text) orelse continue;
            const merged_text = try std.mem.concat(allocator, u8, &.{ left_text, right_text });
            defer allocator.free(merged_text);
            const merged = findTokenId(meta.tokens, merged_text) orelse continue;
            try list.append(allocator, .{ .left = left, .right = right, .merged = merged, .rank = @intCast(rank) });
        }
        return .{ .allocator = allocator, .merges = try list.toOwnedSlice(allocator) };
    }
};

pub const Llama3ByteCodec = struct {
    // GPT-style byte-to-unicode fallback is represented in GGUF token strings.
    // This decoder also recognizes the common <0xHH> serialized byte form.
    pub fn decodeToken(allocator: std.mem.Allocator, token: []const u8) ![]u8 {
        if (token.len == 6 and token[0] == '<' and token[1] == '0' and token[2] == 'x' and token[5] == '>') {
            const hi = hexNibble(token[3]) orelse return allocator.dupe(u8, token);
            const lo = hexNibble(token[4]) orelse return allocator.dupe(u8, token);
            const out = try allocator.alloc(u8, 1);
            out[0] = (hi << 4) | lo;
            return out;
        }
        return allocator.dupe(u8, token);
    }

    fn hexNibble(c: u8) ?u8 {
        return switch (c) {
            '0'...'9' => c - '0',
            'a'...'f' => c - 'a' + 10,
            'A'...'F' => c - 'A' + 10,
            else => null,
        };
    }
};

pub const RankedGgufTokenizer = struct {
    allocator: std.mem.Allocator,
    meta: GgufTokenizerMeta,
    trie: TokenTrie,
    bpe: BpeTokenizer,

    pub fn init(allocator: std.mem.Allocator, index: *const GgufIndex) !RankedGgufTokenizer {
        const meta = try GgufTokenizerMeta.fromIndex(index);
        try meta.validate();
        var table = try GgufBpeMergeTable.fromIndex(allocator, index, meta);
        defer table.deinit();
        return .{
            .allocator = allocator,
            .meta = meta,
            .trie = try TokenTrie.build(allocator, meta),
            .bpe = try BpeTokenizer.init(allocator, table.merges),
        };
    }

    pub fn deinit(self: *RankedGgufTokenizer) void {
        self.trie.deinit();
        self.bpe.deinit();
        self.* = undefined;
    }

    fn initialPieces(self: *const RankedGgufTokenizer, allocator: std.mem.Allocator, text: []const u8) ![]u32 {
        var out: std.ArrayList(u32) = .empty;
        errdefer out.deinit(allocator);
        var pos: usize = 0;
        while (pos < text.len) {
            // Prefer one-byte tokens at this stage when possible; BPE performs
            // the ranked composition. If unavailable, fall back to longest token.
            var chosen: ?TokenTrie.Match = null;
            if (self.trie.longest(text[pos .. pos + 1])) |one| chosen = one;
            if (chosen == null) chosen = self.trie.longest(text[pos..]);
            if (chosen) |m| {
                try out.append(allocator, m.token_id);
                pos += m.bytes;
            } else if (self.meta.unknown_id) |unk| {
                try out.append(allocator, unk);
                pos += 1;
            } else return error.UnencodableByte;
        }
        return try out.toOwnedSlice(allocator);
    }

    pub fn encode(self: *const RankedGgufTokenizer, allocator: std.mem.Allocator, text: []const u8) ![]u32 {
        var pieces = try self.initialPieces(allocator, text);
        errdefer allocator.free(pieces);
        var len = pieces.len;
        self.bpe.mergeInPlace(pieces, &len);
        const extra: usize = (if (self.meta.add_bos and self.meta.bos_id != null) @as(usize, 1) else 0) +
            (if (self.meta.add_eos and self.meta.eos_id != null) @as(usize, 1) else 0);
        const out = try allocator.alloc(u32, len + extra);
        var w: usize = 0;
        if (self.meta.add_bos) if (self.meta.bos_id) |id| {
            out[w] = id;
            w += 1;
        };
        @memcpy(out[w .. w + len], pieces[0..len]);
        w += len;
        if (self.meta.add_eos) if (self.meta.eos_id) |id| {
            out[w] = id;
        };
        allocator.free(pieces);
        return out;
    }

    pub fn decode(self: *const RankedGgufTokenizer, allocator: std.mem.Allocator, ids: []const u32) ![]u8 {
        var out: std.ArrayList(u8) = .empty;
        errdefer out.deinit(allocator);
        for (ids) |id| {
            if (@as(usize, id) >= self.meta.tokens.len) return error.InvalidTokenId;
            const decoded = try Llama3ByteCodec.decodeToken(allocator, self.meta.tokens[@as(usize, id)]);
            defer allocator.free(decoded);
            try out.appendSlice(allocator, decoded);
        }
        return try out.toOwnedSlice(allocator);
    }
};

pub const BoundNorm = struct {
    view: TensorByteView,

    pub fn load(self: BoundNorm, out: []f32) !void {
        try FpTensor.loadVector(out, self.view);
    }
};

pub const BoundEmbedding = struct {
    view: TensorByteView,

    pub fn lookup(self: BoundEmbedding, out: []f32, token: u32) !void {
        try FpTensor.loadEmbeddingRow(out, self.view, token);
    }
};

pub const BoundStepScratch = struct {
    allocator: std.mem.Allocator,
    norm: []f32,
    q: []f32,
    k: []f32,
    v: []f32,
    attn: []f32,
    proj: []f32,
    gate: []f32,
    up: []f32,
    ff: []f32,
    logits: []f32,
    linear_scratch: []f32,
    scores: []f32,

    pub fn init(allocator: std.mem.Allocator, arch: LlamaArch) !BoundStepScratch {
        const d = arch.embedding_length;
        const kv = arch.head_count_kv * arch.headDim();
        const ff = arch.feed_forward_length;
        var self: BoundStepScratch = undefined;
        self.allocator = allocator;
        self.norm = try allocator.alloc(f32, d);
        errdefer allocator.free(self.norm);
        self.q = try allocator.alloc(f32, d);
        errdefer allocator.free(self.q);
        self.k = try allocator.alloc(f32, kv);
        errdefer allocator.free(self.k);
        self.v = try allocator.alloc(f32, kv);
        errdefer allocator.free(self.v);
        self.attn = try allocator.alloc(f32, d);
        errdefer allocator.free(self.attn);
        self.proj = try allocator.alloc(f32, d);
        errdefer allocator.free(self.proj);
        self.gate = try allocator.alloc(f32, ff);
        errdefer allocator.free(self.gate);
        self.up = try allocator.alloc(f32, ff);
        errdefer allocator.free(self.up);
        self.ff = try allocator.alloc(f32, ff);
        errdefer allocator.free(self.ff);
        self.logits = try allocator.alloc(f32, arch.vocab_size);
        errdefer allocator.free(self.logits);
        // F32 matrices require dense scratch; quantized paths use none. Keep a
        // bounded fallback for occasional small floating tensors.
        const ls = @min(@as(usize, 16 * 1024 * 1024), @max(d * 4, ff * 2));
        self.linear_scratch = try allocator.alloc(f32, ls);
        errdefer allocator.free(self.linear_scratch);
        self.scores = try allocator.alloc(f32, arch.context_length);
        return self;
    }

    pub fn deinit(self: *BoundStepScratch) void {
        const a = self.allocator;
        a.free(self.norm);
        a.free(self.q);
        a.free(self.k);
        a.free(self.v);
        a.free(self.attn);
        a.free(self.proj);
        a.free(self.gate);
        a.free(self.up);
        a.free(self.ff);
        a.free(self.logits);
        a.free(self.linear_scratch);
        a.free(self.scores);
        self.* = undefined;
    }
};

fn siluScalar(x: f32) f32 {
    return x / (1.0 + @exp(-x));
}

pub const BoundLlamaExecutor = struct {
    model: *const BoundLlamaModel,
    cache: GqaCache,
    scratch: BoundStepScratch,
    hidden: []f32,
    norm_weight: []f32,

    pub fn init(allocator: std.mem.Allocator, model: *const BoundLlamaModel) !BoundLlamaExecutor {
        const arch = model.arch;
        var cache = try GqaCache.init(allocator, arch.block_count, arch.context_length, arch.head_count_kv, arch.headDim());
        errdefer cache.deinit();
        var scratch = try BoundStepScratch.init(allocator, arch);
        errdefer scratch.deinit();
        const hidden = try allocator.alloc(f32, arch.embedding_length);
        errdefer allocator.free(hidden);
        const nw = try allocator.alloc(f32, @max(arch.embedding_length, arch.feed_forward_length));
        return .{ .model = model, .cache = cache, .scratch = scratch, .hidden = hidden, .norm_weight = nw };
    }

    pub fn deinit(self: *BoundLlamaExecutor) void {
        const a = self.scratch.allocator;
        self.cache.deinit();
        self.scratch.deinit();
        a.free(self.hidden);
        a.free(self.norm_weight);
        self.* = undefined;
    }

    fn addResidual(dst: []f32, add: []const f32) void {
        for (dst, add) |*d, x| d.* += x;
    }

    fn ropeVector(vec: []f32, heads: usize, head_dim: usize, rope_dim: usize, pos: usize, base: f32) void {
        var h: usize = 0;
        while (h < heads) : (h += 1) {
            const off = h * head_dim;
            var i: usize = 0;
            while (i + 1 < rope_dim) : (i += 2) {
                const exponent = @as(f32, @floatFromInt(i)) / @as(f32, @floatFromInt(rope_dim));
                const theta = @as(f32, @floatFromInt(pos)) / std.math.pow(f32, base, exponent);
                const c = @cos(theta);
                const s = @sin(theta);
                const x0 = vec[off + i];
                const x1 = vec[off + i + 1];
                vec[off + i] = x0 * c - x1 * s;
                vec[off + i + 1] = x0 * s + x1 * c;
            }
        }
    }

    fn attention(self: *BoundLlamaExecutor, layer: usize, position: usize) !void {
        const arch = self.model.arch;
        try self.cache.write(layer, position, self.scratch.k, self.scratch.v);
        try self.cache.attend(self.scratch.attn, self.scratch.q, layer, position, arch.head_count, self.scratch.scores);
    }

    fn runLayer(self: *BoundLlamaExecutor, layer_index: usize, position: usize) !void {
        const arch = self.model.arch;
        const layer = self.model.layers[layer_index];
        try FpTensor.loadVector(self.norm_weight[0..arch.embedding_length], layer.attn_norm);
        try rmsNorm(self.scratch.norm, self.hidden, self.norm_weight[0..arch.embedding_length], arch.rms_epsilon);
        try layer.q.run(self.scratch.q, self.scratch.norm, self.scratch.linear_scratch);
        try layer.k.run(self.scratch.k, self.scratch.norm, self.scratch.linear_scratch);
        try layer.v.run(self.scratch.v, self.scratch.norm, self.scratch.linear_scratch);
        ropeVector(self.scratch.q, arch.head_count, arch.headDim(), arch.rope_dim, position, arch.rope_base);
        ropeVector(self.scratch.k, arch.head_count_kv, arch.headDim(), arch.rope_dim, position, arch.rope_base);
        try self.attention(layer_index, position);
        try layer.o.run(self.scratch.proj, self.scratch.attn, self.scratch.linear_scratch);
        addResidual(self.hidden, self.scratch.proj);

        try FpTensor.loadVector(self.norm_weight[0..arch.embedding_length], layer.ffn_norm);
        try rmsNorm(self.scratch.norm, self.hidden, self.norm_weight[0..arch.embedding_length], arch.rms_epsilon);
        try layer.gate.run(self.scratch.gate, self.scratch.norm, self.scratch.linear_scratch);
        try layer.up.run(self.scratch.up, self.scratch.norm, self.scratch.linear_scratch);
        var i: usize = 0;
        while (i < arch.feed_forward_length) : (i += 1) self.scratch.ff[i] = siluScalar(self.scratch.gate[i]) * self.scratch.up[i];
        try layer.down.run(self.scratch.proj, self.scratch.ff, self.scratch.linear_scratch);
        addResidual(self.hidden, self.scratch.proj);
    }

    pub fn forwardToken(self: *BoundLlamaExecutor, token: u32, position: usize) ![]const f32 {
        if (position >= self.model.arch.context_length) return error.ContextExceeded;
        try FpTensor.loadEmbeddingRow(self.hidden, self.model.embedding, token);
        var l: usize = 0;
        while (l < self.model.layers.len) : (l += 1) try self.runLayer(l, position);
        try FpTensor.loadVector(self.norm_weight[0..self.model.arch.embedding_length], self.model.output_norm);
        try rmsNorm(self.scratch.norm, self.hidden, self.norm_weight[0..self.model.arch.embedding_length], self.model.arch.rms_epsilon);
        if (self.model.output) |out| {
            try out.run(self.scratch.logits, self.scratch.norm, self.scratch.linear_scratch);
        } else {
            // Tied embedding output projection. Portable scalar implementation
            // deliberately handles only F16/F32 embedding tensors for now.
            const emb = self.model.embedding;
            if (emb.dims.len != 2) return error.ShapeMismatch;
            const cols: usize = @intCast(emb.dims[0]);
            const rows: usize = @intCast(emb.dims[1]);
            if (cols != self.model.arch.embedding_length or rows != self.model.arch.vocab_size) return error.ShapeMismatch;
            var r: usize = 0;
            while (r < rows) : (r += 1) {
                var sum: f32 = 0;
                var c: usize = 0;
                while (c < cols) : (c += 1) {
                    const w = switch (emb.ggml_type) {
                        .f16 => try FpTensor.f16At(emb.bytes, r * cols + c),
                        .f32 => try FpTensor.f32At(emb.bytes, r * cols + c),
                        else => return error.UnsupportedEmbeddingQuantization,
                    };
                    sum += w * self.scratch.norm[c];
                }
                self.scratch.logits[r] = sum;
            }
        }
        return self.scratch.logits;
    }

    pub fn prefill(self: *BoundLlamaExecutor, tokens: []const u32) ![]const f32 {
        if (tokens.len == 0) return error.EmptyPrompt;
        var logits: []const f32 = &[_]f32{};
        for (tokens, 0..) |tok, pos| logits = try self.forwardToken(tok, pos);
        return logits;
    }
};

// ============================================================================
// ML-DSA signature-side data structures and deterministic sampling implementation
// ============================================================================

pub const MlDsaParams = struct {
    k: usize,
    l: usize,
    eta: i32,
    tau: usize,
    beta: i32,
    gamma1: i32,
    gamma2: i32,
    omega: usize,
    c_tilde_bytes: usize,

    pub fn level44() MlDsaParams {
        return .{ .k = 4, .l = 4, .eta = 2, .tau = 39, .beta = 78, .gamma1 = 1 << 17, .gamma2 = (MlDsa.q - 1) / 88, .omega = 80, .c_tilde_bytes = 32 };
    }
    pub fn level65() MlDsaParams {
        return .{ .k = 6, .l = 5, .eta = 4, .tau = 49, .beta = 196, .gamma1 = 1 << 19, .gamma2 = (MlDsa.q - 1) / 32, .omega = 55, .c_tilde_bytes = 48 };
    }
    pub fn level87() MlDsaParams {
        return .{ .k = 8, .l = 7, .eta = 2, .tau = 60, .beta = 120, .gamma1 = 1 << 19, .gamma2 = (MlDsa.q - 1) / 32, .omega = 75, .c_tilde_bytes = 64 };
    }
};

pub const MlDsaDecompose = struct {
    pub const Parts = struct { high: i32, low: i32 };

    pub fn power2round(a: i32) Parts {
        const d: i32 = 13;
        var a1 = (a + (1 << (d - 1)) - 1) >> d;
        var a0 = a - (a1 << d);
        if (a0 > (1 << (d - 1))) {
            a0 -= 1 << d;
            a1 += 1;
        }
        return .{ .high = a1, .low = a0 };
    }

    pub fn decompose(a_in: i32, gamma2: i32) Parts {
        const a = MlDsa.freeze(a_in);
        var a1: i32 = undefined;
        if (gamma2 == (MlDsa.q - 1) / 32) {
            a1 = (a + 127) >> 7;
            a1 = (a1 * 1025 + (1 << 21)) >> 22;
            a1 &= 15;
        } else {
            a1 = (a + 127) >> 7;
            a1 = (a1 * 11275 + (1 << 23)) >> 24;
            a1 ^= ((43 - a1) >> 31) & a1;
        }
        var a0 = a - a1 * 2 * gamma2;
        a0 -= (((MlDsa.q - 1) / 2 - a0) >> 31) & MlDsa.q;
        return .{ .high = a1, .low = a0 };
    }

    pub fn makeHint(a0: i32, a1: i32, gamma2: i32) bool {
        return a0 > gamma2 or a0 < -gamma2 or (a0 == -gamma2 and a1 != 0);
    }

    pub fn useHint(a: i32, hint: bool, gamma2: i32) i32 {
        const p = decompose(a, gamma2);
        if (!hint) return p.high;
        if (gamma2 == (MlDsa.q - 1) / 32) return if (p.low > 0) (p.high + 1) & 15 else (p.high - 1) & 15;
        return if (p.low > 0) (if (p.high == 43) 0 else p.high + 1) else (if (p.high == 0) 43 else p.high - 1);
    }
};

pub const MlDsaChallenge = struct {
    pub fn fromSeed(seed: []const u8, tau: usize) !MlDsa.Poly {
        if (tau > 64 or seed.len == 0 or seed.len > 64) return error.InvalidParameterSet;
        var p: MlDsa.Poly = [_]i32{0} ** MlDsa.n;
        // One contiguous SHAKE256 stream preserves the standardized XOF sequence.
        // 1024 bytes is deliberately generous for the rejection sampler; if an
        // adversarial seed exhausts it we fail closed instead of changing domains.
        var stream: [1024]u8 = undefined;
        shake256(seed, &stream);
        var signs: u64 = 0;
        for (0..8) |i| signs |= @as(u64, stream[i]) << @intCast(8 * i);
        var pos: usize = 8;
        var i: usize = MlDsa.n - tau;
        while (i < MlDsa.n) : (i += 1) {
            var b: usize = undefined;
            while (true) {
                if (pos >= stream.len) return error.XofStreamExhausted;
                b = stream[pos];
                pos += 1;
                if (b <= i) break;
            }
            p[i] = p[b];
            p[b] = if ((signs & 1) == 0) 1 else -1;
            signs >>= 1;
        }
        secureZero(&stream);
        return p;
    }
};

pub const MlDsaVectorOps = struct {
    pub fn add(out: []MlDsa.Poly, a: []const MlDsa.Poly, b: []const MlDsa.Poly) !void {
        if (out.len != a.len or a.len != b.len) return error.ShapeMismatch;
        for (out, a, b) |*o, x, y| {
            for (o, x, y) |*z, xv, yv| {
                z.* = xv + yv;
            }
        }
    }

    pub fn sub(out: []MlDsa.Poly, a: []const MlDsa.Poly, b: []const MlDsa.Poly) !void {
        if (out.len != a.len or a.len != b.len) return error.ShapeMismatch;
        for (out, a, b) |*o, x, y| {
            for (o, x, y) |*z, xv, yv| {
                z.* = xv - yv;
            }
        }
    }

    pub fn reduce(v: []MlDsa.Poly) void {
        for (v) |*p| {
            for (p) |*x| {
                x.* = MlDsa.reduce32(x.*);
            }
        }
    }

    pub fn ntt(v: []MlDsa.Poly) void {
        for (v) |*p| MlDsa.ntt(p);
    }
    pub fn invNtt(v: []MlDsa.Poly) void {
        for (v) |*p| MlDsa.invNttToMont(p);
    }

    pub fn normExceeds(v: []const MlDsa.Poly, bound: i32) bool {
        if (bound <= 0) return true;
        for (v) |p| for (p) |x| {
            const y = if (x < 0) -x else x;
            if (y >= bound) return true;
        };
        return false;
    }
};

// SLH-DSA/WOTS+ address and chain primitives. These are reusable pieces of
// FIPS-205 style hypertree signing. The final standardized serialization API
// remains intentionally fail-closed until official vector validation.
pub const SlhAddress = struct {
    words: [8]u32 = [_]u32{0} ** 8,

    pub fn setLayer(self: *SlhAddress, x: u32) void {
        self.words[0] = x;
    }
    pub fn setTree(self: *SlhAddress, x: u64) void {
        self.words[1] = @truncate(x >> 32);
        self.words[2] = @truncate(x);
    }
    pub fn setType(self: *SlhAddress, x: u32) void {
        self.words[3] = x;
    }
    pub fn setKeypair(self: *SlhAddress, x: u32) void {
        self.words[4] = x;
    }
    pub fn setChain(self: *SlhAddress, x: u32) void {
        self.words[5] = x;
    }
    pub fn setHash(self: *SlhAddress, x: u32) void {
        self.words[6] = x;
    }
    pub fn setTreeHeight(self: *SlhAddress, x: u32) void {
        self.words[5] = x;
    }
    pub fn setTreeIndex(self: *SlhAddress, x: u32) void {
        self.words[6] = x;
    }

    pub fn bytes(self: SlhAddress) [32]u8 {
        var out: [32]u8 = undefined;
        for (self.words, 0..) |w, i| {
            out[i * 4 + 0] = @truncate(w >> 24);
            out[i * 4 + 1] = @truncate(w >> 16);
            out[i * 4 + 2] = @truncate(w >> 8);
            out[i * 4 + 3] = @truncate(w);
        }
        return out;
    }
};

pub const SlhThash = struct {
    pub fn hashN(out: []u8, pub_seed: []const u8, addr: SlhAddress, input: []const u8) !void {
        if (out.len == 0 or out.len > 64) return error.InvalidParameterSet;
        const ab = addr.bytes();
        var sponge = Keccak.Sponge.init(136, 0x1f);
        try sponge.update(pub_seed);
        try sponge.update(&ab);
        try sponge.update(input);
        sponge.finalize();
        try sponge.squeeze(out);
    }
};

pub const SlhWots = struct {
    pub const w: usize = 16;

    pub fn baseW(out: []u8, input: []const u8) !void {
        var in_pos: usize = 0;
        var total: u8 = 0;
        var bits: u4 = 0;
        for (out) |*x| {
            if (bits == 0) {
                if (in_pos >= input.len) return error.TruncatedInput;
                total = input[in_pos];
                in_pos += 1;
                bits = 8;
            }
            bits -= 4;
            x.* = (total >> @intCast(bits)) & 0x0f;
        }
    }

    pub fn chain(out: []u8, input: []const u8, start: usize, steps: usize, pub_seed: []const u8, addr_in: SlhAddress) !void {
        if (out.len != input.len) return error.LengthMismatch;
        @memcpy(out, input);
        var addr = addr_in;
        var i = start;
        while (i < start + steps and i < w) : (i += 1) {
            addr.setHash(@intCast(i));
            var tmp: [64]u8 = undefined;
            try SlhThash.hashN(tmp[0..out.len], pub_seed, addr, out);
            @memcpy(out, tmp[0..out.len]);
            secureZero(&tmp);
        }
    }
};

pub const MerkleAuth = struct {
    pub fn rootFromPath(out: []u8, leaf: []const u8, leaf_index: usize, auth_path: []const u8, height: usize, pub_seed: []const u8, addr_in: SlhAddress) !void {
        const n = out.len;
        if (n == 0 or leaf.len != n or auth_path.len != height * n) return error.LengthMismatch;
        var cur: [64]u8 = undefined;
        var pair: [128]u8 = undefined;
        if (n > 64) return error.InvalidParameterSet;
        @memcpy(cur[0..n], leaf);
        var idx = leaf_index;
        var level: usize = 0;
        var addr = addr_in;
        while (level < height) : (level += 1) {
            const sibling = auth_path[level * n .. (level + 1) * n];
            if ((idx & 1) == 0) {
                @memcpy(pair[0..n], cur[0..n]);
                @memcpy(pair[n .. 2 * n], sibling);
            } else {
                @memcpy(pair[0..n], sibling);
                @memcpy(pair[n .. 2 * n], cur[0..n]);
            }
            addr.setTreeHeight(@intCast(level + 1));
            addr.setTreeIndex(@intCast(idx >> 1));
            try SlhThash.hashN(cur[0..n], pub_seed, addr, pair[0 .. 2 * n]);
            idx >>= 1;
        }
        @memcpy(out, cur[0..n]);
        secureZero(&cur);
        secureZero(&pair);
    }
};

test "Llama3 byte fallback token decoder" {
    const a = std.testing.allocator;
    const x = try Llama3ByteCodec.decodeToken(a, "<0x41>");
    defer a.free(x);
    try std.testing.expectEqualStrings("A", x);
}

test "ML-DSA power2round reconstructs" {
