// ============================================================================
// CONTINUATION 0.8 — ML-DSA signing flow, SLH-DSA FORS/hypertree helpers,
// and tokenizer pre-tokenization. Pure Zig only; no C/Python linkage.
// ============================================================================

pub const MlDsaSampler = struct {
    fn squeezeNonce(seed: []const u8, nonce: u16, out: []u8) void {
        var sponge = Keccak.Sponge.init(136, 0x1f);
        sponge.update(seed) catch unreachable;
        const nonce_le = [2]u8{ @truncate(nonce), @truncate(nonce >> 8) };
        sponge.update(&nonce_le) catch unreachable;
        sponge.finalize();
        sponge.squeeze(out) catch unreachable;
    }

    pub fn eta(out: *MlDsa.Poly, seed: []const u8, nonce: u16, eta_value: i32) !void {
        if (eta_value != 2 and eta_value != 4) return error.InvalidParameterSet;
        var stream: [1024]u8 = undefined;
        squeezeNonce(seed, nonce, &stream);
        var ctr: usize = 0;
        var pos: usize = 0;
        while (ctr < MlDsa.n and pos < stream.len) : (pos += 1) {
            const b = stream[pos];
            const lo: u8 = b & 0x0f;
            const hi: u8 = b >> 4;
            const vals = [_]u8{ lo, hi };
            for (vals) |v| {
                if (ctr >= MlDsa.n) break;
                if (eta_value == 2) {
                    if (v < 15) {
                        const t: i32 = @intCast(v % 5);
                        out[ctr] = 2 - t;
                        ctr += 1;
                    }
                } else {
                    if (v < 9) {
                        out[ctr] = 4 - @as(i32, @intCast(v));
                        ctr += 1;
                    }
                }
            }
        }
        if (ctr != MlDsa.n) return error.RejectionStreamExhausted;
    }

    pub fn gamma1(out: *MlDsa.Poly, seed: []const u8, nonce: u16, gamma1_value: i32) !void {
        if (gamma1_value != (1 << 17) and gamma1_value != (1 << 19)) return error.InvalidParameterSet;
        var stream: [768]u8 = undefined;
        squeezeNonce(seed, nonce, &stream);
        var bit: usize = 0;
        const width: usize = if (gamma1_value == (1 << 17)) 18 else 20;
        for (out) |*x| {
            var v: u32 = 0;
            var j: usize = 0;
            while (j < width) : (j += 1) {
                const bi = bit + j;
                const byte = bi >> 3;
                if (byte >= stream.len) return error.RejectionStreamExhausted;
                v |= (@as(u32, (stream[byte] >> @intCast(bi & 7)) & 1) << @intCast(j));
            }
            bit += width;
            x.* = gamma1_value - @as(i32, @intCast(v));
        }
    }
};

pub const MlDsaMatrixOps = struct {
    pub fn mul(out: []MlDsa.Poly, mat: *const MlDsaMatrix.Matrix, vec: []const MlDsa.Poly, params: MlDsaParams) !void {
        if (out.len < params.k or vec.len < params.l) return error.ShapeMismatch;
        var vh: [MlDsaMatrix.max_l]MlDsa.Poly = undefined;
        for (0..params.l) |j| {
            vh[j] = vec[j];
            MlDsa.ntt(&vh[j]);
        }
        for (0..params.k) |i| {
            var acc = [_]i32{0} ** MlDsa.n;
            for (0..params.l) |j| {
                var a = mat[i][j];
                MlDsa.ntt(&a);
                var prod: MlDsa.Poly = undefined;
                MlDsa.pointwiseMontgomery(&prod, &a, &vh[j]);
                for (0..MlDsa.n) |c| acc[c] += prod[c];
            }
            MlDsa.reduce(&acc);
            MlDsa.invNttToMont(&acc);
            MlDsa.reduce(&acc);
            out[i] = acc;
        }
    }
};

pub const MlDsaHighLow = struct {
    pub fn power2RoundVec(high: []MlDsa.Poly, low: []MlDsa.Poly, src: []const MlDsa.Poly) !void {
        if (high.len != src.len or low.len != src.len) return error.ShapeMismatch;
        for (src, 0..) |p, i| for (p, 0..) |x, j| {
            const r = MlDsaDecompose.power2round(MlDsa.freeze(x));
            high[i][j] = r.high;
            low[i][j] = r.low;
        };
    }

    pub fn decomposeVec(high: []MlDsa.Poly, low: []MlDsa.Poly, src: []const MlDsa.Poly, gamma2: i32) !void {
        if (high.len != src.len or low.len != src.len) return error.ShapeMismatch;
        for (src, 0..) |p, i| for (p, 0..) |x, j| {
            const r = MlDsaDecompose.decompose(x, gamma2);
            high[i][j] = r.high;
            low[i][j] = r.low;
        };
    }

    pub fn makeHints(hints: []MlDsa.Poly, low: []const MlDsa.Poly, high: []const MlDsa.Poly, gamma2: i32) !usize {
        if (hints.len != low.len or low.len != high.len) return error.ShapeMismatch;
        var count: usize = 0;
        for (hints, low, high) |*h, l, hi| for (h, l, hi) |*dst, a0, a1| {
            const bit = MlDsaDecompose.makeHint(a0, a1, gamma2);
            dst.* = @intFromBool(bit);
            count += @intFromBool(bit);
        };
        return count;
    }

    pub fn useHints(out: []MlDsa.Poly, src: []const MlDsa.Poly, hints: []const MlDsa.Poly, gamma2: i32) !void {
        if (out.len != src.len or src.len != hints.len) return error.ShapeMismatch;
        for (out, src, hints) |*o, s, h| for (o, s, h) |*dst, x, bit| {
            if (bit != 0 and bit != 1) return error.InvalidEncoding;
            dst.* = MlDsaDecompose.useHint(x, bit == 1, gamma2);
        };
    }
};

pub const MlDsaTranscript = struct {
    pub fn messageRepresentative(out: *[64]u8, tr: []const u8, ctx: []const u8, message: []const u8) !void {
        if (ctx.len > 255) return error.ContextTooLong;
        var s = Keccak.Sponge.init(136, 0x1f);
        try s.update(tr);
        const pre = [_]u8{ 0, @intCast(ctx.len) };
        try s.update(&pre);
        try s.update(ctx);
        try s.update(message);
        s.finalize();
        try s.squeeze(out);
    }

    pub fn signingSeed(out: *[64]u8, key: []const u8, rnd: []const u8, mu: *const [64]u8) !void {
        var s = Keccak.Sponge.init(136, 0x1f);
        try s.update(key);
        try s.update(rnd);
        try s.update(mu);
        s.finalize();
        try s.squeeze(out);
    }

    pub fn challengeSeed(out: []u8, mu: *const [64]u8, packed_w1: []const u8) !void {
        if (out.len == 0 or out.len > 64) return error.InvalidParameterSet;
        var s = Keccak.Sponge.init(136, 0x1f);
        try s.update(mu);
        try s.update(packed_w1);
        s.finalize();
        try s.squeeze(out);
    }
};

// In-memory expanded forms back the canonical packed ML-DSA API. Official
// vector verification remains a separate validation state from implementation.
pub const MlDsaExpandedPublicKey = struct {
    rho: [32]u8,
    t1: [MlDsaMatrix.max_k]MlDsa.Poly,
    params: MlDsaParams,
};

pub const MlDsaExpandedSecretKey = struct {
    rho: [32]u8,
    key: [32]u8,
    tr: [64]u8,
    s1: [MlDsaMatrix.max_l]MlDsa.Poly,
    s2: [MlDsaMatrix.max_k]MlDsa.Poly,
    t0: [MlDsaMatrix.max_k]MlDsa.Poly,
    params: MlDsaParams,
};

pub const MlDsaExpandedSignature = struct {
    c_seed: [64]u8,
    z: [MlDsaMatrix.max_l]MlDsa.Poly,
    h: [MlDsaMatrix.max_k]MlDsa.Poly,
    params: MlDsaParams,
};

pub const MlDsaExpanded = struct {
    fn deriveSeeds(seed: *const [32]u8, params: MlDsaParams, rho: *[32]u8, rhoprime: *[64]u8, key: *[32]u8) void {
        var in: [34]u8 = undefined;
        @memcpy(in[0..32], seed);
        in[32] = @intCast(params.k);
        in[33] = @intCast(params.l);
        var out: [128]u8 = undefined;
        shake256(&in, &out);
        @memcpy(rho, out[0..32]);
        @memcpy(rhoprime, out[32..96]);
        @memcpy(key, out[96..128]);
        secureZero(&out);
    }

    pub fn keypair(seed: *const [32]u8, params: MlDsaParams, pk: *MlDsaExpandedPublicKey, sk: *MlDsaExpandedSecretKey) !void {
        if (params.k > MlDsaMatrix.max_k or params.l > MlDsaMatrix.max_l) return error.InvalidParameterSet;
        var rhoprime: [64]u8 = undefined;
        deriveSeeds(seed, params, &pk.rho, &rhoprime, &sk.key);
        sk.rho = pk.rho;
        pk.params = params;
        sk.params = params;
        for (0..params.l) |i| try MlDsaSampler.eta(&sk.s1[i], &rhoprime, @intCast(i), params.eta);
        for (0..params.k) |i| try MlDsaSampler.eta(&sk.s2[i], &rhoprime, @intCast(params.l + i), params.eta);
        var mat: MlDsaMatrix.Matrix = undefined;
        const mp = MlDsa.Params{ .k = params.k, .l = params.l, .eta = params.eta, .tau = params.tau, .beta = params.beta, .gamma1 = params.gamma1, .gamma2 = params.gamma2, .omega = params.omega };
        try MlDsaMatrix.expand(&mat, &pk.rho, mp);
        var t: [MlDsaMatrix.max_k]MlDsa.Poly = undefined;
        try MlDsaMatrixOps.mul(t[0..params.k], &mat, sk.s1[0..params.l], params);
        for (0..params.k) |i| {
            for (0..MlDsa.n) |j| {
                t[i][j] += sk.s2[i][j];
            }
        }
        try MlDsaHighLow.power2RoundVec(pk.t1[0..params.k], sk.t0[0..params.k], t[0..params.k]);

        // FIPS 204 tr = H(pk), where pk is the canonical packed public key.
        var packed_pk: [2592]u8 = undefined;
        const packed_pk_len = try MlDsaStdPacking.packPublicKey(&packed_pk, pk);
        var sponge = Keccak.Sponge.init(136, 0x1f);
        try sponge.update(packed_pk[0..packed_pk_len]);
        sponge.finalize();
        try sponge.squeeze(&sk.tr);
        secureZero(&rhoprime);
        secureZero(&packed_pk);
    }

    fn pointwiseChallenge(out: *MlDsa.Poly, challenge: *const MlDsa.Poly, secret: *const MlDsa.Poly) void {
        var c = challenge.*;
        var s = secret.*;
        MlDsa.ntt(&c);
        MlDsa.ntt(&s);
        MlDsa.pointwiseMontgomery(out, &c, &s);
        MlDsa.invNttToMont(out);
        MlDsa.reduce(out);
    }

    // Full equation-level signing flow using expanded keys. This is kept
    // separate from the standardized Signature facade until official vectors
    // validate the exact packing/sampling byte compatibility.
    pub fn signExpanded(sk: *const MlDsaExpandedSecretKey, message: []const u8, ctx: []const u8, sig: *MlDsaExpandedSignature) !void {
        const params = sk.params;
        sig.params = params;
        var mu: [64]u8 = undefined;
        try MlDsaTranscript.messageRepresentative(&mu, &sk.tr, ctx, message);
        var zero_rnd = [_]u8{0} ** 32;
        var rhoprime: [64]u8 = undefined;
        try MlDsaTranscript.signingSeed(&rhoprime, &sk.key, &zero_rnd, &mu);
        var mat: MlDsaMatrix.Matrix = undefined;
        const mp = MlDsa.Params{ .k = params.k, .l = params.l, .eta = params.eta, .tau = params.tau, .beta = params.beta, .gamma1 = params.gamma1, .gamma2 = params.gamma2, .omega = params.omega };
        try MlDsaMatrix.expand(&mat, &sk.rho, mp);

        var nonce: u16 = 0;
        var attempts: usize = 0;
        while (attempts < 1024) : (attempts += 1) {
            var y: [MlDsaMatrix.max_l]MlDsa.Poly = undefined;
            for (0..params.l) |i| {
                try MlDsaSampler.gamma1(&y[i], &rhoprime, nonce, params.gamma1);
                nonce +%= 1;
            }
            var w: [MlDsaMatrix.max_k]MlDsa.Poly = undefined;
            try MlDsaMatrixOps.mul(w[0..params.k], &mat, y[0..params.l], params);
            var w1: [MlDsaMatrix.max_k]MlDsa.Poly = undefined;
            var w0: [MlDsaMatrix.max_k]MlDsa.Poly = undefined;
            try MlDsaHighLow.decomposeVec(w1[0..params.k], w0[0..params.k], w[0..params.k], params.gamma2);

            // Canonical FIPS 204 w1 packing for challenge binding.
            var packed_w1: [MlDsaMatrix.max_k * 192]u8 = undefined;
            const pp = try MlDsaStdPacking.packW1Vec(&packed_w1, w1[0..params.k], params.gamma2);
            try MlDsaTranscript.challengeSeed(sig.c_seed[0..params.c_tilde_bytes], &mu, packed_w1[0..pp]);
            const cp = try MlDsaChallenge.fromSeed(sig.c_seed[0..params.c_tilde_bytes], params.tau);

            var reject = false;
            for (0..params.l) |i| {
                var cs1: MlDsa.Poly = undefined;
                pointwiseChallenge(&cs1, &cp, &sk.s1[i]);
                for (0..MlDsa.n) |j| sig.z[i][j] = y[i][j] + cs1[j];
                MlDsa.reduce(&sig.z[i]);
                if (MlDsa.chknorm(&sig.z[i], params.gamma1 - params.beta)) reject = true;
            }
            if (reject) continue;

            var hint_count: usize = 0;
            for (0..params.k) |i| {
                var cs2: MlDsa.Poly = undefined;
                var ct0: MlDsa.Poly = undefined;
                pointwiseChallenge(&cs2, &cp, &sk.s2[i]);
                pointwiseChallenge(&ct0, &cp, &sk.t0[i]);
                for (0..MlDsa.n) |j| {
                    const low = MlDsa.reduce32(w0[i][j] - cs2[j]);
                    if (@abs(low) >= params.gamma2 - params.beta) {
                        reject = true;
                        break;
                    }
                    if (@abs(ct0[j]) >= params.gamma2) {
                        reject = true;
                        break;
                    }
                    const bit = MlDsaDecompose.makeHint(low + ct0[j], w1[i][j], params.gamma2);
                    sig.h[i][j] = @intFromBool(bit);
                    hint_count += @intFromBool(bit);
                }
                if (reject) break;
            }
            if (reject or hint_count > params.omega) continue;
            secureZero(&mu);
            secureZero(&rhoprime);
            secureZero(&zero_rnd);
            secureZero(&packed_w1);
            return;
        }
        return error.RejectionLimitExceeded;
    }
};

// ---- SLH-DSA FORS and hypertree implementation ------------------------------
pub const SlhFors = struct {
    pub fn messageIndices(out: []u32, digest: []const u8, a: usize) !void {
        if (a == 0 or a > 31) return error.InvalidParameterSet;
        if (out.len * a > digest.len * 8) return error.TruncatedInput;
        var bit: usize = 0;
        for (out) |*idx| {
            var v: u32 = 0;
            for (0..a) |j| {
                const b = bit + j;
                v |= @as(u32, (digest[b >> 3] >> @intCast(b & 7)) & 1) << @intCast(j);
            }
            idx.* = v;
            bit += a;
        }
    }

    pub fn secretElement(out: []u8, sk_seed: []const u8, addr_in: SlhAddress, tree: u32, leaf_index: u32) !void {
        if (out.len > 64) return error.InvalidParameterSet;
        var addr = addr_in;
        addr.words[5] = tree;
        addr.words[6] = leaf_index;
        var ab: [32]u8 = undefined;
        for (addr.words, 0..) |v, i| writeU32Le(ab[i * 4 .. i * 4 + 4], v) catch unreachable;
        var s = Keccak.Sponge.init(136, 0x1f);
        try s.update(sk_seed);
        try s.update(&ab);
        s.finalize();
        try s.squeeze(out);
    }

    pub fn leaf(out: []u8, sk_seed: []const u8, pub_seed: []const u8, addr: SlhAddress, tree: u32, leaf_index: u32) !void {
        var sk: [64]u8 = undefined;
        try secretElement(sk[0..out.len], sk_seed, addr, tree, leaf_index);
        try SlhThash.hashN(out, pub_seed, addr, sk[0..out.len]);
        secureZero(&sk);
    }

    pub fn treeRoot(out: []u8, sk_seed: []const u8, pub_seed: []const u8, addr: SlhAddress, tree: u32, height: usize) !void {
        if (height > 16 or out.len == 0 or out.len > 64) return error.InvalidParameterSet;
        const leaves: usize = @as(usize, 1) << @intCast(height);
        var nodes: [1 << 16][64]u8 = undefined;
        for (0..leaves) |i| try leaf(nodes[i][0..out.len], sk_seed, pub_seed, addr, tree, @intCast(i));
        var count = leaves;
        var level: usize = 0;
        while (count > 1) : (level += 1) {
            var next: usize = 0;
            var i: usize = 0;
            while (i < count) : (i += 2) {
                var pair: [128]u8 = undefined;
                @memcpy(pair[0..out.len], nodes[i][0..out.len]);
                @memcpy(pair[out.len .. 2 * out.len], nodes[i + 1][0..out.len]);
                var a2 = addr;
                a2.setTreeHeight(@intCast(level + 1));
                a2.setTreeIndex(@intCast(next));
                try SlhThash.hashN(nodes[next][0..out.len], pub_seed, a2, pair[0 .. 2 * out.len]);
                next += 1;
            }
            count = next;
        }
        @memcpy(out, nodes[0][0..out.len]);
    }
};

pub const SlhHypertree = struct {
    pub fn layerAddress(layer: u32, tree: u64, keypair: u32) SlhAddress {
        var a = SlhAddress{};
        a.words[0] = layer;
        a.words[2] = @truncate(tree >> 32);
        a.words[3] = @truncate(tree);
        a.words[5] = keypair;
        return a;
    }

    pub fn computeRoot(out: []u8, leaf: []const u8, index: usize, auth: []const u8, height: usize, pub_seed: []const u8, addr: SlhAddress) !void {
        try MerkleAuth.rootFromPath(out, leaf, index, auth, height, pub_seed, addr);
    }

    pub fn splitTreeIndex(global: u64, hp: usize) struct { leaf: u32, parent: u64 } {
        const mask: u64 = if (hp == 64) ~@as(u64, 0) else (@as(u64, 1) << @intCast(hp)) - 1;
        return .{ .leaf = @intCast(global & mask), .parent = global >> @intCast(hp) };
    }
};

// ---- Llama-3-ish pre-tokenization -----------------------------------------
pub const Llama3Pretokenizer = struct {
    pub const Span = struct { start: usize, end: usize };

    fn isAsciiSpace(c: u8) bool {
        return c == ' ' or c == '\t' or c == '\n' or c == '\r' or c == 0x0b or c == 0x0c;
    }
    fn isAsciiAlpha(c: u8) bool {
        return (c >= 'A' and c <= 'Z') or (c >= 'a' and c <= 'z');
    }
    fn isAsciiDigit(c: u8) bool {
        return c >= '0' and c <= '9';
    }
    fn isPunct(c: u8) bool {
        return !isAsciiSpace(c) and !isAsciiAlpha(c) and !isAsciiDigit(c) and c < 0x80;
    }

    pub fn spans(allocator: std.mem.Allocator, text: []const u8) ![]Span {
        var list = std.ArrayList(Span).empty;
        errdefer list.deinit(allocator);
        var i: usize = 0;
        while (i < text.len) {
            const start = i;
            if (isAsciiSpace(text[i])) {
                i += 1;
                while (i < text.len and isAsciiSpace(text[i])) i += 1;
            } else if (isAsciiAlpha(text[i])) {
                i += 1;
                while (i < text.len and isAsciiAlpha(text[i])) i += 1;
            } else if (isAsciiDigit(text[i])) {
                i += 1;
                while (i < text.len and isAsciiDigit(text[i]) and i - start < 3) i += 1;
            } else if (isPunct(text[i])) {
                i += 1;
                while (i < text.len and isPunct(text[i])) i += 1;
            } else {
                // Preserve a complete UTF-8 scalar as one coarse span; byte BPE
                // beneath this layer may still merge adjacent scalars.
                const lead = text[i];
                const width: usize = if (lead < 0x80) 1 else if ((lead & 0xe0) == 0xc0) 2 else if ((lead & 0xf0) == 0xe0) 3 else if ((lead & 0xf8) == 0xf0) 4 else 1;
                i = @min(text.len, i + width);
            }
            try list.append(allocator, .{ .start = start, .end = i });
        }
        return list.toOwnedSlice(allocator);
    }
};

test "ML-DSA eta sampler bounds" {
    var p: MlDsa.Poly = undefined;
    var seed = [_]u8{0x42} ** 64;
    try MlDsaSampler.eta(&p, &seed, 0, 2);
    for (p) |x| try std.testing.expect(x >= -2 and x <= 2);
}

test "ML-DSA expanded key equations instantiate" {
    var seed = [_]u8{7} ** 32;
    var pk: MlDsaExpandedPublicKey = undefined;
    var sk: MlDsaExpandedSecretKey = undefined;
    try MlDsaExpanded.keypair(&seed, MlDsaParams.level44(), &pk, &sk);
    try std.testing.expectEqual(@as(usize, 4), pk.params.k);
}

test "SLH FORS bit indices" {
    var idx: [4]u32 = undefined;
    try SlhFors.messageIndices(&idx, &[_]u8{ 0b11100100, 0b00011011 }, 4);
    try std.testing.expectEqual(@as(u32, 4), idx[0]);
    try std.testing.expectEqual(@as(u32, 14), idx[1]);
}

test "Llama pretokenizer preserves coverage" {
    const a = std.testing.allocator;
    const text = "Hello, world! 12345";
    const ss = try Llama3Pretokenizer.spans(a, text);
    defer a.free(ss);
    try std.testing.expect(ss.len > 0);
    try std.testing.expectEqual(@as(usize, 0), ss[0].start);
    try std.testing.expectEqual(text.len, ss[ss.len - 1].end);
}

// ============================================================================
// 10K RUN EXPANSION: STANDARDIZED PQ PACKING, SLH SIGNATURE RECONSTRUCTION,
// TOKEN SEGMENTATION, GENERATION PIPELINE, AND GGUF RUNTIME AUDIT
// ============================================================================

pub const BitWriter = struct {
    out: []u8,
    bit: usize = 0,

    pub fn init(out: []u8) BitWriter {
        @memset(out, 0);
        return .{ .out = out };
    }

    pub fn put(self: *BitWriter, value: u64, width: u6) !void {
        if (width > 63) return error.InvalidBitWidth;
        if (self.bit + width > self.out.len * 8) return error.OutputTooSmall;
        var i: usize = 0;
        while (i < width) : (i += 1) {
            const b = @as(u8, @truncate((value >> @intCast(i)) & 1));
            const pos = self.bit + i;
            self.out[pos >> 3] |= b << @intCast(pos & 7);
        }
        self.bit += width;
    }

    pub fn alignByte(self: *BitWriter) void {
        self.bit = (self.bit + 7) & ~@as(usize, 7);
    }

    pub fn bytesWritten(self: *const BitWriter) usize {
        return (self.bit + 7) / 8;
    }
};

pub const BitReader = struct {
    input: []const u8,
    bit: usize = 0,

    pub fn init(input: []const u8) BitReader {
        return .{ .input = input };
    }

    pub fn get(self: *BitReader, width: u6) !u64 {
        if (width > 63) return error.InvalidBitWidth;
        if (self.bit + width > self.input.len * 8) return error.InputTooShort;
        var v: u64 = 0;
        var i: usize = 0;
        while (i < width) : (i += 1) {
            const pos = self.bit + i;
            const b = (self.input[pos >> 3] >> @intCast(pos & 7)) & 1;
            v |= @as(u64, b) << @intCast(i);
        }
        self.bit += width;
        return v;
    }

    pub fn alignByte(self: *BitReader) void {
        self.bit = (self.bit + 7) & ~@as(usize, 7);
    }
    pub fn bytesRead(self: *const BitReader) usize {
        return (self.bit + 7) / 8;
    }
};

pub const MlDsaStdPacking = struct {
    pub const PackedLayout = struct {
        pk_bytes: usize,
        sk_bytes: usize,
        sig_bytes: usize,
        eta_bits: u6,
        z_bits: u6,
        t0_bits: u6,
        t1_bits: u6,
    };

    pub fn layout(p: MlDsaParams) PackedLayout {
        const eta_bits: u6 = if (p.eta == 2) 3 else 4;
        const z_bits: u6 = if (p.gamma1 == (1 << 17)) 18 else 20;
        const t0_bits: u6 = 13;
        const t1_bits: u6 = 10;
        const pk = 32 + p.k * (MlDsa.N * t1_bits / 8);
        const sk = 32 + 32 + 64 + p.l * (MlDsa.N * eta_bits / 8) + p.k * (MlDsa.N * eta_bits / 8) + p.k * (MlDsa.N * t0_bits / 8);
        const sig = p.c_tilde_bytes + p.l * (MlDsa.N * z_bits / 8) + p.omega + p.k;
        return .{ .pk_bytes = pk, .sk_bytes = sk, .sig_bytes = sig, .eta_bits = eta_bits, .z_bits = z_bits, .t0_bits = t0_bits, .t1_bits = t1_bits };
    }

    fn packUnsignedPoly(out: []u8, poly: *const MlDsa.Poly, bits: u6, max: u32) !usize {
        var w = BitWriter.init(out);
        for (poly.*) |x| {
            if (x < 0 or @as(u64, @intCast(x)) > max) return error.CoefficientOutOfRange;
            try w.put(@intCast(x), bits);
        }
        return w.bytesWritten();
    }

    fn unpackUnsignedPoly(poly: *MlDsa.Poly, input: []const u8, bits: u6, max: u32) !usize {
        var r = BitReader.init(input);
        for (poly) |*x| {
            const v = try r.get(bits);
            if (v > max) return error.NonCanonicalEncoding;
            x.* = @intCast(v);
        }
        return r.bytesRead();
    }

    pub fn packEta(out: []u8, poly: *const MlDsa.Poly, eta: i32) !usize {
        const bits: u6 = if (eta == 2) 3 else if (eta == 4) 4 else return error.InvalidParameterSet;
        var w = BitWriter.init(out);
        for (poly.*) |x| {
            if (x < -eta or x > eta) return error.CoefficientOutOfRange;
            const v: u64 = @intCast(eta - x);
            try w.put(v, bits);
        }
        return w.bytesWritten();
    }

    pub fn unpackEta(poly: *MlDsa.Poly, input: []const u8, eta: i32) !usize {
        const bits: u6 = if (eta == 2) 3 else if (eta == 4) 4 else return error.InvalidParameterSet;
        var r = BitReader.init(input);
        for (poly) |*x| {
            const v = try r.get(bits);
            if (v > @as(u64, @intCast(2 * eta))) return error.NonCanonicalEncoding;
            x.* = eta - @as(i32, @intCast(v));
        }
        return r.bytesRead();
    }

    pub fn packT1(out: []u8, poly: *const MlDsa.Poly) !usize {
        return packUnsignedPoly(out, poly, 10, 1023);
    }

    pub fn unpackT1(poly: *MlDsa.Poly, input: []const u8) !usize {
        return unpackUnsignedPoly(poly, input, 10, 1023);
    }

    pub fn packT0(out: []u8, poly: *const MlDsa.Poly) !usize {
        var w = BitWriter.init(out);
        for (poly.*) |x| {
            const v = (1 << 12) - x;
            if (v < 0 or v > 8191) return error.CoefficientOutOfRange;
            try w.put(@intCast(v), 13);
        }
        return w.bytesWritten();
    }

    pub fn unpackT0(poly: *MlDsa.Poly, input: []const u8) !usize {
        var r = BitReader.init(input);
        for (poly) |*x| {
            const v = try r.get(13);
            x.* = (1 << 12) - @as(i32, @intCast(v));
        }
        return r.bytesRead();
    }

    pub fn packZ(out: []u8, poly: *const MlDsa.Poly, gamma1: i32) !usize {
        const bits: u6 = if (gamma1 == (1 << 17)) 18 else if (gamma1 == (1 << 19)) 20 else return error.InvalidParameterSet;
        var w = BitWriter.init(out);
        for (poly.*) |x| {
            const v = gamma1 - x;
            if (v < 0 or v >= 2 * gamma1) return error.CoefficientOutOfRange;
            try w.put(@intCast(v), bits);
        }
        return w.bytesWritten();
    }

    pub fn unpackZ(poly: *MlDsa.Poly, input: []const u8, gamma1: i32) !usize {
        const bits: u6 = if (gamma1 == (1 << 17)) 18 else if (gamma1 == (1 << 19)) 20 else return error.InvalidParameterSet;
        var r = BitReader.init(input);
        for (poly) |*x| {
            const v = try r.get(bits);
            if (v >= @as(u64, @intCast(2 * gamma1))) return error.NonCanonicalEncoding;
            x.* = gamma1 - @as(i32, @intCast(v));
        }
        return r.bytesRead();
    }

    pub fn w1PackedBytes(gamma2: i32) !usize {
        if (gamma2 == (MlDsa.q - 1) / 88) return 192;
        if (gamma2 == (MlDsa.q - 1) / 32) return 128;
        return error.InvalidParameterSet;
    }

    pub fn packW1(out: []u8, poly: *const MlDsa.Poly, gamma2: i32) !usize {
        const need = try w1PackedBytes(gamma2);
        if (out.len < need) return error.OutputTooSmall;
        if (gamma2 == (MlDsa.q - 1) / 88) {
            var i: usize = 0;
            while (i < MlDsa.N / 4) : (i += 1) {
                const x0 = poly[4 * i + 0];
                const x1 = poly[4 * i + 1];
                const x2 = poly[4 * i + 2];
                const x3 = poly[4 * i + 3];
                if (x0 < 0 or x0 > 43 or x1 < 0 or x1 > 43 or x2 < 0 or x2 > 43 or x3 < 0 or x3 > 43) return error.CoefficientOutOfRange;
                const a0: u16 = @intCast(x0);
                const a1: u16 = @intCast(x1);
                const a2: u16 = @intCast(x2);
                const a3: u16 = @intCast(x3);
                out[3 * i + 0] = @truncate(a0 | (a1 << 6));
                out[3 * i + 1] = @truncate((a1 >> 2) | (a2 << 4));
                out[3 * i + 2] = @truncate((a2 >> 4) | (a3 << 2));
            }
        } else if (gamma2 == (MlDsa.q - 1) / 32) {
            var i: usize = 0;
            while (i < MlDsa.N / 2) : (i += 1) {
                const x0 = poly[2 * i + 0];
                const x1 = poly[2 * i + 1];
                if (x0 < 0 or x0 > 15 or x1 < 0 or x1 > 15) return error.CoefficientOutOfRange;
                const a0: u8 = @intCast(x0);
                const a1: u8 = @intCast(x1);
                out[i] = a0 | (a1 << 4);
            }
        } else return error.InvalidParameterSet;
        return need;
    }

    pub fn packW1Vec(out: []u8, polys: []const MlDsa.Poly, gamma2: i32) !usize {
        const each = try w1PackedBytes(gamma2);
        const total = std.math.mul(usize, each, polys.len) catch return error.OutputTooSmall;
        if (out.len < total) return error.OutputTooSmall;
        var off: usize = 0;
        for (polys) |*poly| off += try packW1(out[off..], poly, gamma2);
        return off;
    }

    pub fn packPublicKey(out: []u8, pk: *const MlDsaExpandedPublicKey) !usize {
        const lay = layout(pk.params);
        if (out.len < lay.pk_bytes) return error.OutputTooSmall;
        @memcpy(out[0..32], &pk.rho);
        var off: usize = 32;
        for (0..pk.params.k) |i| {
            const n = try packT1(out[off..], &pk.t1[i]);
            off += n;
        }
        return off;
    }

    pub fn unpackPublicKey(pk: *MlDsaExpandedPublicKey, input: []const u8, params: MlDsaParams) !usize {
        const lay = layout(params);
        if (input.len < lay.pk_bytes) return error.InputTooShort;
        pk.params = params;
        @memcpy(&pk.rho, input[0..32]);
        var off: usize = 32;
        for (0..params.k) |i| off += try unpackT1(&pk.t1[i], input[off..]);
        return off;
    }

    pub fn packSecretKey(out: []u8, sk: *const MlDsaExpandedSecretKey) !usize {
        const lay = layout(sk.params);
        if (out.len < lay.sk_bytes) return error.OutputTooSmall;
        var off: usize = 0;
        @memcpy(out[off .. off + 32], &sk.rho);
        off += 32;
        @memcpy(out[off .. off + 32], &sk.key);
        off += 32;
        @memcpy(out[off .. off + 64], &sk.tr);
        off += 64;
        for (0..sk.params.l) |i| off += try packEta(out[off..], &sk.s1[i], sk.params.eta);
        for (0..sk.params.k) |i| off += try packEta(out[off..], &sk.s2[i], sk.params.eta);
        for (0..sk.params.k) |i| off += try packT0(out[off..], &sk.t0[i]);
        return off;
    }

    pub fn unpackSecretKey(sk: *MlDsaExpandedSecretKey, input: []const u8, params: MlDsaParams) !usize {
        const lay = layout(params);
        if (input.len < lay.sk_bytes) return error.InputTooShort;
        sk.params = params;
        var off: usize = 0;
        @memcpy(&sk.rho, input[off .. off + 32]);
        off += 32;
        @memcpy(&sk.key, input[off .. off + 32]);
        off += 32;
        @memcpy(&sk.tr, input[off .. off + 64]);
        off += 64;
        for (0..params.l) |i| off += try unpackEta(&sk.s1[i], input[off..], params.eta);
        for (0..params.k) |i| off += try unpackEta(&sk.s2[i], input[off..], params.eta);
        for (0..params.k) |i| off += try unpackT0(&sk.t0[i], input[off..]);
        return off;
    }

    pub fn packSignature(out: []u8, sig: *const MlDsaExpandedSignature) !usize {
        const lay = layout(sig.params);
        if (out.len < lay.sig_bytes) return error.OutputTooSmall;
        var off: usize = 0;
        @memcpy(out[0..sig.params.c_tilde_bytes], sig.c_seed[0..sig.params.c_tilde_bytes]);
        off += sig.params.c_tilde_bytes;
        for (0..sig.params.l) |i| off += try packZ(out[off..], &sig.z[i], sig.params.gamma1);
        const hint_begin = off;
        @memset(out[hint_begin .. hint_begin + sig.params.omega + sig.params.k], 0);
        var count: usize = 0;
        for (0..sig.params.k) |i| {
            for (0..MlDsa.N) |j| {
                if (sig.h[i][j] != 0) {
                    if (count >= sig.params.omega) return error.TooManyHints;
                    out[hint_begin + count] = @intCast(j);
                    count += 1;
                }
            }
            out[hint_begin + sig.params.omega + i] = @intCast(count);
        }
        return lay.sig_bytes;
    }

    pub fn unpackSignature(sig: *MlDsaExpandedSignature, input: []const u8, params: MlDsaParams) !usize {
        const lay = layout(params);
        if (input.len < lay.sig_bytes) return error.InputTooShort;
        sig.params = params;
        @memset(&sig.c_seed, 0);
        @memcpy(sig.c_seed[0..params.c_tilde_bytes], input[0..params.c_tilde_bytes]);
        var off: usize = params.c_tilde_bytes;
        for (0..params.l) |i| off += try unpackZ(&sig.z[i], input[off..], params.gamma1);
        for (0..params.k) |i| @memset(&sig.h[i], 0);
        const h = input[off .. off + params.omega + params.k];
        var kprev: usize = 0;
        for (0..params.k) |i| {
            const kend: usize = h[params.omega + i];
            if (kend < kprev or kend > params.omega) return error.NonCanonicalEncoding;
            var j = kprev;
            while (j < kend) : (j += 1) {
                if (j > kprev and h[j] <= h[j - 1]) return error.NonCanonicalEncoding;
                sig.h[i][h[j]] = 1;
            }
            kprev = kend;
        }
        for (kprev..params.omega) |j| if (h[j] != 0) return error.NonCanonicalEncoding;
        return lay.sig_bytes;
    }
};

pub const MlDsaVerifier = struct {
    fn vecCheckNorm(v: []const MlDsa.Poly, count: usize, bound: i32) bool {
        for (0..count) |i| for (v[i]) |x| if (x <= -bound or x >= bound) return false;
        return true;
    }

    fn copyVec(dst: []MlDsa.Poly, src: []const MlDsa.Poly, count: usize) void {
        for (0..count) |i| dst[i] = src[i];
    }

    pub fn verifyExpanded(pk: *const MlDsaExpandedPublicKey, sig: *const MlDsaExpandedSignature, msg: []const u8, ctx: []const u8) !bool {
        if (ctx.len > 255) return false;
        if (pk.params.k != sig.params.k or pk.params.l != sig.params.l) return false;
        const p = pk.params;
        if (!vecCheckNorm(sig.z[0..], p.l, p.gamma1 - p.beta)) return false;

        var tr: [64]u8 = undefined;
        var pkbuf: [4096]u8 = undefined;
        const pkn = try MlDsaStdPacking.packPublicKey(&pkbuf, pk);
        var sponge = Keccak.Sponge.init(136, 0x1f);
        try sponge.update(pkbuf[0..pkn]);
        sponge.finalize();
        try sponge.squeeze(&tr);
        var mu: [64]u8 = undefined;
        try MlDsaTranscript.messageRepresentative(&mu, &tr, ctx, msg);

        var c = try MlDsaChallenge.fromSeed(sig.c_seed[0..p.c_tilde_bytes], p.tau);
        MlDsa.ntt(&c);

        var mat: MlDsaMatrix.Matrix = undefined;
        const mp = MlDsa.Params{ .k = p.k, .l = p.l, .eta = p.eta, .tau = p.tau, .beta = p.beta, .gamma1 = p.gamma1, .gamma2 = p.gamma2, .omega = p.omega };
        try MlDsaMatrix.expand(&mat, &pk.rho, mp);

        var zhat: [7]MlDsa.Poly = undefined;
        copyVec(zhat[0..], sig.z[0..], p.l);
        for (0..p.l) |i| MlDsa.ntt(&zhat[i]);

        var w: [8]MlDsa.Poly = undefined;
        try MlDsaMatrixOps.mul(&w, &mat, &zhat, p);

        var ct1: MlDsa.Poly = undefined;
        for (0..p.k) |i| {
            var t1shift: MlDsa.Poly = undefined;
            for (0..MlDsa.N) |j| t1shift[j] = pk.t1[i][j] << MlDsa.D;
            MlDsa.ntt(&t1shift);
            MlDsa.pointwiseMontgomery(&ct1, &c, &t1shift);
            for (0..MlDsa.N) |j| w[i][j] -= ct1[j];
            MlDsa.reduce(&w[i]);
            MlDsa.invNttToMont(&w[i]);
            for (0..MlDsa.N) |j| w[i][j] = MlDsa.caddq(w[i][j]);
        }

        var w1: [8]MlDsa.Poly = undefined;
        for (0..p.k) |i| {
            for (0..MlDsa.N) |j| w1[i][j] = MlDsaDecompose.useHint(w[i][j], sig.h[i][j] != 0, p.gamma2);
        }

        var packed_w1: [MlDsaMatrix.max_k * 192]u8 = undefined;
        const used = try MlDsaStdPacking.packW1Vec(&packed_w1, w1[0..p.k], p.gamma2);

        var c2: [64]u8 = undefined;
        var hs = Keccak.Sponge.init(136, 0x1f);
        try hs.update(&mu);
        try hs.update(packed_w1[0..used]);
        hs.finalize();
        try hs.squeeze(c2[0..p.c_tilde_bytes]);
        return ctEqual(sig.c_seed[0..p.c_tilde_bytes], c2[0..p.c_tilde_bytes]);
    }

    pub fn verifyPacked(pk_bytes: []const u8, sig_bytes: []const u8, params: MlDsaParams, msg: []const u8, ctx: []const u8) !bool {
        var pk: MlDsaExpandedPublicKey = undefined;
        var sig: MlDsaExpandedSignature = undefined;
        _ = try MlDsaStdPacking.unpackPublicKey(&pk, pk_bytes, params);
        _ = try MlDsaStdPacking.unpackSignature(&sig, sig_bytes, params);
        return verifyExpanded(&pk, &sig, msg, ctx);
    }
};

pub const SlhParams = struct {
    name: []const u8,
    n: usize,
    h: usize,
    d: usize,
    hp: usize,
    a: usize,
    k: usize,
    w: usize = 16,

    pub fn sha2_128s() SlhParams {
        return .{ .name = "SLH-DSA-SHA2-128s", .n = 16, .h = 63, .d = 7, .hp = 9, .a = 12, .k = 14 };
    }
    pub fn sha2_128f() SlhParams {
        return .{ .name = "SLH-DSA-SHA2-128f", .n = 16, .h = 66, .d = 22, .hp = 3, .a = 6, .k = 33 };
    }
    pub fn sha2_192s() SlhParams {
        return .{ .name = "SLH-DSA-SHA2-192s", .n = 24, .h = 63, .d = 7, .hp = 9, .a = 14, .k = 17 };
    }
    pub fn sha2_192f() SlhParams {
        return .{ .name = "SLH-DSA-SHA2-192f", .n = 24, .h = 66, .d = 22, .hp = 3, .a = 8, .k = 33 };
    }
    pub fn sha2_256s() SlhParams {
        return .{ .name = "SLH-DSA-SHA2-256s", .n = 32, .h = 64, .d = 8, .hp = 8, .a = 14, .k = 22 };
    }
    pub fn sha2_256f() SlhParams {
        return .{ .name = "SLH-DSA-SHA2-256f", .n = 32, .h = 68, .d = 17, .hp = 4, .a = 9, .k = 35 };
    }
    pub fn shake_128s() SlhParams {
        var p = sha2_128s();
        p.name = "SLH-DSA-SHAKE-128s";
        return p;
    }
    pub fn shake_128f() SlhParams {
        var p = sha2_128f();
        p.name = "SLH-DSA-SHAKE-128f";
        return p;
    }
    pub fn shake_192s() SlhParams {
        var p = sha2_192s();
        p.name = "SLH-DSA-SHAKE-192s";
        return p;
    }
    pub fn shake_192f() SlhParams {
        var p = sha2_192f();
        p.name = "SLH-DSA-SHAKE-192f";
        return p;
    }
    pub fn shake_256s() SlhParams {
        var p = sha2_256s();
        p.name = "SLH-DSA-SHAKE-256s";
        return p;
    }
    pub fn shake_256f() SlhParams {
        var p = sha2_256f();
        p.name = "SLH-DSA-SHAKE-256f";
        return p;
    }

    pub fn forsSigBytes(self: SlhParams) usize {
        return self.k * (self.a + 1) * self.n;
    }
    pub fn wotsLen1(self: SlhParams) usize {
        return (8 * self.n + 3) / 4;
    }
    pub fn wotsLen2(self: SlhParams) usize {
        const l1 = self.wotsLen1();
        var v = 15 * l1;
        var digits: usize = 0;
        while (v > 0) : (v /= 16) digits += 1;
        return digits;
    }
    pub fn wotsLen(self: SlhParams) usize {
        return self.wotsLen1() + self.wotsLen2();
    }
    pub fn xmssSigBytes(self: SlhParams) usize {
        return (self.wotsLen() + self.hp) * self.n;
    }
    pub fn htSigBytes(self: SlhParams) usize {
        return self.d * self.xmssSigBytes();
    }
};

pub const SlhWotsSignature = struct {
    pub fn baseW(out: []u8, input: []const u8) void {
        var in_idx: usize = 0;
        var out_idx: usize = 0;
        var total: u16 = 0;
        var bits: u8 = 0;
        while (out_idx < out.len) {
            if (bits == 0) {
                total = if (in_idx < input.len) input[in_idx] else 0;
                in_idx += 1;
                bits = 8;
            }
            bits -= 4;
            out[out_idx] = @truncate((total >> @intCast(bits)) & 0x0f);
            out_idx += 1;
        }
    }

    pub fn chainLengths(out: []u8, msg: []const u8, p: SlhParams) !void {
        const l1 = p.wotsLen1();
        const l2 = p.wotsLen2();
        if (out.len < l1 + l2) return error.OutputTooSmall;
        baseW(out[0..l1], msg);
        var csum: usize = 0;
        for (out[0..l1]) |x| csum += 15 - x;
        var i: usize = 0;
        while (i < l2) : (i += 1) {
            out[l1 + l2 - 1 - i] = @intCast(csum & 0xf);
            csum >>= 4;
        }
    }

    pub fn sign(out: []u8, msg: []const u8, sk_seed: []const u8, pub_seed: []const u8, addr_in: SlhAddress, p: SlhParams) !usize {
        const len = p.wotsLen();
        if (out.len < len * p.n) return error.OutputTooSmall;
        var lengths: [80]u8 = undefined;
        if (len > lengths.len) return error.InvalidParameterSet;
        try chainLengths(lengths[0..len], msg, p);
        var addr = addr_in;
        for (0..len) |i| {
            addr.words[6] = @intCast(i);
            var sk: [64]u8 = undefined;
            try SlhFors.secretElement(sk[0..p.n], sk_seed, addr, @intCast(addr.words[2]), @intCast(i));
            try SlhWots.chain(out[i * p.n .. (i + 1) * p.n], sk[0..p.n], 0, lengths[i], pub_seed, addr);
            secureZero(&sk);
        }
        return len * p.n;
    }

    pub fn publicFromSignature(out: []u8, sig: []const u8, msg: []const u8, pub_seed: []const u8, addr_in: SlhAddress, p: SlhParams) !void {
        const len = p.wotsLen();
        if (sig.len < len * p.n or out.len < len * p.n) return error.InputTooShort;
        var lengths: [80]u8 = undefined;
        if (len > lengths.len) return error.InvalidParameterSet;
        try chainLengths(lengths[0..len], msg, p);
        var addr = addr_in;
        for (0..len) |i| {
            addr.words[6] = @intCast(i);
            try SlhWots.chain(out[i * p.n .. (i + 1) * p.n], sig[i * p.n .. (i + 1) * p.n], lengths[i], 15 - lengths[i], pub_seed, addr);
        }
    }

    pub fn compressPk(out: []u8, expanded: []const u8, pub_seed: []const u8, addr: SlhAddress, p: SlhParams) !void {
        if (out.len < p.n) return error.OutputTooSmall;
        try SlhThash.hashN(out[0..p.n], pub_seed, addr, expanded);
    }
};

pub const SlhForsSignature = struct {
    pub fn sign(out: []u8, digest: []const u8, sk_seed: []const u8, pub_seed: []const u8, addr: SlhAddress, p: SlhParams) !usize {
        if (out.len < p.forsSigBytes()) return error.OutputTooSmall;
        var idx: [64]u32 = undefined;
        if (p.k > idx.len) return error.InvalidParameterSet;
        try SlhFors.messageIndices(idx[0..p.k], digest, p.a);
        var off: usize = 0;
        for (0..p.k) |t| {
            const leaf_idx = idx[t];
            try SlhFors.secretElement(out[off .. off + p.n], sk_seed, addr, @intCast(t), leaf_idx);
            off += p.n;
            const leaves: usize = @as(usize, 1) << @intCast(p.a);
            var level_nodes = try std.heap.page_allocator.alloc(u8, leaves * p.n);
            defer std.heap.page_allocator.free(level_nodes);
            for (0..leaves) |i| try SlhFors.leaf(level_nodes[i * p.n .. (i + 1) * p.n], sk_seed, pub_seed, addr, @intCast(t), @intCast(i));
            var current_index: usize = leaf_idx;
            var count = leaves;
            var level: usize = 0;
            while (level < p.a) : (level += 1) {
                const sibling = current_index ^ 1;
                @memcpy(out[off .. off + p.n], level_nodes[sibling * p.n .. (sibling + 1) * p.n]);
                off += p.n;
                var next: usize = 0;
                var i: usize = 0;
                while (i < count) : (i += 2) {
                    var pair: [128]u8 = undefined;
                    @memcpy(pair[0..p.n], level_nodes[i * p.n .. (i + 1) * p.n]);
                    @memcpy(pair[p.n .. 2 * p.n], level_nodes[(i + 1) * p.n .. (i + 2) * p.n]);
                    var a2 = addr;
                    a2.setTreeHeight(@intCast(level + 1));
                    a2.setTreeIndex(@intCast(next));
                    try SlhThash.hashN(level_nodes[next * p.n .. (next + 1) * p.n], pub_seed, a2, pair[0 .. 2 * p.n]);
                    next += 1;
                }
                count = next;
                current_index >>= 1;
            }
        }
        return off;
    }

    pub fn rootsFromSignature(roots: []u8, sig: []const u8, digest: []const u8, pub_seed: []const u8, addr: SlhAddress, p: SlhParams) !usize {
        if (roots.len < p.k * p.n or sig.len < p.forsSigBytes()) return error.InputTooShort;
        var idx: [64]u32 = undefined;
        try SlhFors.messageIndices(idx[0..p.k], digest, p.a);
        var off: usize = 0;
        for (0..p.k) |t| {
            var leaf: [64]u8 = undefined;
            try SlhThash.hashN(leaf[0..p.n], pub_seed, addr, sig[off .. off + p.n]);
            off += p.n;
            const auth = sig[off .. off + p.a * p.n];
            off += p.a * p.n;
            try MerkleAuth.rootFromPath(roots[t * p.n .. (t + 1) * p.n], leaf[0..p.n], idx[t], auth, p.a, pub_seed, addr);
        }
        return off;
    }

    pub fn publicKeyFromSignature(out: []u8, sig: []const u8, digest: []const u8, pub_seed: []const u8, addr: SlhAddress, p: SlhParams) !void {
        var roots: [64 * 32]u8 = undefined;
        if (p.k * p.n > roots.len) return error.InvalidParameterSet;
        _ = try rootsFromSignature(roots[0 .. p.k * p.n], sig, digest, pub_seed, addr, p);
        try SlhThash.hashN(out[0..p.n], pub_seed, addr, roots[0 .. p.k * p.n]);
    }
};

pub const SlhXmss = struct {
    pub fn leafFromWotsSignature(out: []u8, sig: []const u8, msg: []const u8, pub_seed: []const u8, addr: SlhAddress, p: SlhParams) !void {
        var expanded: [80 * 32]u8 = undefined;
        const need = p.wotsLen() * p.n;
        if (need > expanded.len) return error.InvalidParameterSet;
        try SlhWotsSignature.publicFromSignature(expanded[0..need], sig, msg, pub_seed, addr, p);
        try SlhWotsSignature.compressPk(out, expanded[0..need], pub_seed, addr, p);
    }

    pub fn rootFromSignature(out: []u8, sig: []const u8, msg: []const u8, leaf_idx: usize, pub_seed: []const u8, addr: SlhAddress, p: SlhParams) !usize {
        const wbytes = p.wotsLen() * p.n;
        if (sig.len < wbytes + p.hp * p.n) return error.InputTooShort;
        var leaf: [64]u8 = undefined;
        try leafFromWotsSignature(leaf[0..p.n], sig[0..wbytes], msg, pub_seed, addr, p);
        try MerkleAuth.rootFromPath(out[0..p.n], leaf[0..p.n], leaf_idx, sig[wbytes .. wbytes + p.hp * p.n], p.hp, pub_seed, addr);
        return wbytes + p.hp * p.n;
    }
};

pub const SlhHypertreeSignature = struct {
    pub fn verify(top_root: []const u8, sig: []const u8, msg_root: []const u8, tree_index: u64, leaf_index: u32, pub_seed: []const u8, p: SlhParams) !bool {
        if (top_root.len < p.n or msg_root.len < p.n or sig.len < p.htSigBytes()) return false;
        var current: [64]u8 = undefined;
        @memcpy(current[0..p.n], msg_root[0..p.n]);
        var tree = tree_index;
        var leaf = leaf_index;
        var off: usize = 0;
        for (0..p.d) |layer| {
            const addr = SlhHypertree.layerAddress(@intCast(layer), tree, leaf);
            const used = try SlhXmss.rootFromSignature(current[0..p.n], sig[off..], current[0..p.n], leaf, pub_seed, addr, p);
            off += used;
            if (layer + 1 < p.d) {
                const split = SlhHypertree.splitTreeIndex(tree, p.hp);
                leaf = split.leaf;
                tree = split.parent;
            }
        }
        return ctEqual(top_root[0..p.n], current[0..p.n]);
    }
};

pub const SpecialTokenSegmenter = struct {
    pub const SegmentKind = enum { text, special };
    pub const Segment = struct { kind: SegmentKind, start: usize, end: usize, token_id: ?u32 = null };

    pub fn segment(allocator: std.mem.Allocator, text: []const u8, meta: GgufTokenizerMeta) ![]Segment {
        var out = std.ArrayList(Segment).init(allocator);
        errdefer out.deinit();
        var pos: usize = 0;
        while (pos < text.len) {
            var best_start = text.len;
            var best_end = text.len;
            var best_id: ?u32 = null;
            for (meta.tokens, 0..) |tok, id| {
                if (tok.len < 4 or tok[0] != '<') continue;
                if (std.mem.indexOfPos(u8, text, pos, tok)) |s| {
                    if (s < best_start or (s == best_start and tok.len > best_end - best_start)) {
                        best_start = s;
                        best_end = s + tok.len;
                        best_id = @intCast(id);
                    }
                }
            }
            if (best_id == null) {
                try out.append(.{ .kind = .text, .start = pos, .end = text.len });
                break;
            }
            if (best_start > pos) try out.append(.{ .kind = .text, .start = pos, .end = best_start });
            try out.append(.{ .kind = .special, .start = best_start, .end = best_end, .token_id = best_id });
            pos = best_end;
        }
        return out.toOwnedSlice();
    }
};

pub const Llama3TokenizerRuntime = struct {
    tok: RankedGgufTokenizer,

    pub fn init(allocator: std.mem.Allocator, index: *const GgufIndex) !Llama3TokenizerRuntime {
        return .{ .tok = try RankedGgufTokenizer.init(allocator, index) };
    }
    pub fn deinit(self: *Llama3TokenizerRuntime) void {
        self.tok.deinit();
    }

    pub fn encodeWithSpecials(self: *const Llama3TokenizerRuntime, allocator: std.mem.Allocator, text: []const u8) ![]u32 {
        const segs = try SpecialTokenSegmenter.segment(allocator, text, self.tok.meta);
        defer allocator.free(segs);
        var ids = std.ArrayList(u32).init(allocator);
        errdefer ids.deinit();
        for (segs) |seg| switch (seg.kind) {
            .special => try ids.append(seg.token_id.?),
            .text => {
                const spans = try Llama3Pretokenizer.spans(allocator, text[seg.start..seg.end]);
                defer allocator.free(spans);
                for (spans) |sp| {
                    const piece = text[seg.start + sp.start .. seg.start + sp.end];
                    const pids = try self.tok.encode(allocator, piece);
                    defer allocator.free(pids);
                    try ids.appendSlice(pids);
                }
            },
        };
        return ids.toOwnedSlice();
    }

    pub fn decodeIncremental(self: *const Llama3TokenizerRuntime, allocator: std.mem.Allocator, ids: []const u32) ![]u8 {
        return self.tok.decode(allocator, ids);
    }
};

pub const RepetitionWindow = struct {
    ids: []u32,
    pos: usize = 0,
    filled: usize = 0,

    pub fn init(allocator: std.mem.Allocator, n: usize) !RepetitionWindow {
        if (n == 0) return error.InvalidWindow;
        return .{ .ids = try allocator.alloc(u32, n) };
    }
    pub fn deinit(self: *RepetitionWindow, allocator: std.mem.Allocator) void {
        allocator.free(self.ids);
        self.* = undefined;
    }
    pub fn push(self: *RepetitionWindow, id: u32) void {
        self.ids[self.pos] = id;
        self.pos = (self.pos + 1) % self.ids.len;
        self.filled = @min(self.filled + 1, self.ids.len);
    }
    pub fn count(self: *const RepetitionWindow, id: u32) usize {
        var n: usize = 0;
        for (self.ids[0..self.filled]) |x| {
            if (x == id) n += 1;
        }
        return n;
    }
};

pub const LogitProcessor = struct {
    pub fn repetitionPenalty(logits: []f32, window: *const RepetitionWindow, penalty: f32) void {
        if (penalty <= 0 or penalty == 1) return;
        for (window.ids[0..window.filled]) |id| if (@as(usize, id) < logits.len) {
            if (logits[id] < 0) logits[id] *= penalty else logits[id] /= penalty;
        };
    }

    pub fn frequencyPresence(logits: []f32, window: *const RepetitionWindow, frequency: f32, presence: f32) void {
        var i: usize = 0;
        while (i < logits.len) : (i += 1) {
            const c = window.count(@intCast(i));
            if (c == 0) continue;
            logits[i] -= presence + frequency * @as(f32, @floatFromInt(c));
        }
    }

    pub fn temperature(logits: []f32, t: f32) void {
        if (t <= 0 or t == 1) return;
        for (logits) |*x| x.* /= t;
    }

    pub fn topK(logits: []f32, k: usize) void {
        if (k == 0 or k >= logits.len) return;
        var threshold: f32 = -std.math.inf(f32);
        var rep: usize = 0;
        while (rep < k) : (rep += 1) {
            var best = -std.math.inf(f32);
            for (logits) |x| {
                if (x > threshold and x > best) best = x;
            }
            if (!std.math.isFinite(best)) break;
            threshold = best;
        }
        for (logits) |*x| {
            if (x.* < threshold) x.* = -std.math.inf(f32);
        }
    }

    pub fn softmax(probs: []f32, logits: []const f32) !void {
        if (probs.len < logits.len) return error.OutputTooSmall;
        var maxv = -std.math.inf(f32);
        for (logits) |x| {
            if (x > maxv) maxv = x;
        }
        var sum: f64 = 0;
        for (logits, 0..) |x, i| {
            const e = @exp(@as(f64, x - maxv));
            probs[i] = @floatCast(e);
            sum += e;
        }
        if (sum == 0 or !std.math.isFinite(sum)) return error.InvalidDistribution;
        for (probs[0..logits.len]) |*p| p.* = @floatCast(@as(f64, p.*) / sum);
    }

    pub fn topP(probs: []f32, p: f32) void {
        if (p <= 0 or p >= 1) return;
        // Portable O(n^2) path: repeatedly locate the largest probability and
        // keep tokens until the cumulative mass crosses p.
        var keep = tryKeepMask(probs.len) catch return;
        defer std.heap.page_allocator.free(keep);
        @memset(keep, false);
        var cumulative: f32 = 0;
        while (cumulative < p) {
            var bi: ?usize = null;
            var bv: f32 = -1;
            for (probs, 0..) |x, i| if (!keep[i] and x > bv) {
                bv = x;
                bi = i;
            };
            if (bi == null) break;
            keep[bi.?] = true;
            cumulative += bv;
        }
        for (probs, 0..) |*x, i| {
            if (!keep[i]) x.* = 0;
        }
        var s: f32 = 0;
        for (probs) |x| s += x;
        if (s > 0) {
            for (probs) |*x| {
                x.* /= s;
            }
        }
    }

    fn tryKeepMask(n: usize) ![]bool {
        return std.heap.page_allocator.alloc(bool, n);
    }
};

pub const CheckpointRng = struct {
    s0: u64,
    s1: u64,
    pub fn init(seed: u64) CheckpointRng {
        const a = seed ^ 0x9e3779b97f4a7c15;
        var b = (seed << 1) ^ 0xbf58476d1ce4e5b9;
        if (a == 0 and b == 0) b = 1;
        return .{ .s0 = a, .s1 = b };
    }
    pub fn next(self: *XorShift128Plus) u64 {
        var x = self.s0;
        const y = self.s1;
        self.s0 = y;
        x ^= x << 23;
        self.s1 = x ^ y ^ (x >> 17) ^ (y >> 26);
        return self.s1 + y;
    }
    pub fn unit(self: *XorShift128Plus) f64 {
        return @as(f64, @floatFromInt(self.next() >> 11)) / 9007199254740992.0;
    }
};

pub const TokenSampler = struct {
    pub fn sample(probs: []const f32, rng: *CheckpointRng) !u32 {
        const r: f64 = rng.unit();
        var acc: f64 = 0;
        for (probs, 0..) |p, i| {
            if (p <= 0) continue;
            acc += p;
            if (r <= acc) return @intCast(i);
        }
        var best: usize = 0;
        var bv: f32 = -1;
        for (probs, 0..) |p, i| {
            if (p > bv) {
                best = i;
                bv = p;
            }
        }
        return @intCast(best);
    }
    pub fn greedy(logits: []const f32) u32 {
        var best: usize = 0;
        var bv = -std.math.inf(f32);
        for (logits, 0..) |x, i| {
            if (x > bv) {
                best = i;
                bv = x;
            }
        }
        return @intCast(best);
    }
};

pub const AdvancedGenerationConfig = struct {
    max_new_tokens: usize = 256,
    temperature: f32 = 0.8,
    top_k: usize = 40,
    top_p: f32 = 0.95,
    repetition_penalty: f32 = 1.1,
    frequency_penalty: f32 = 0,
    presence_penalty: f32 = 0,
    repeat_last_n: usize = 64,
    seed: u64 = 1,
    eos_id: ?u32 = null,
};

pub const StopMatcher = struct {
    stops: []const []const u8,
    pub fn matched(self: StopMatcher, text: []const u8) bool {
        for (self.stops) |s| if (s.len <= text.len and std.mem.eql(u8, text[text.len - s.len ..], s)) return true;
        return false;
    }
};

pub const GenerationState = struct {
    rng: CheckpointRng,
    repetition: RepetitionWindow,
    tokens_generated: usize = 0,
    pub fn init(a: std.mem.Allocator, cfg: AdvancedGenerationConfig) !GenerationState {
        return .{ .rng = CheckpointRng.init(cfg.seed), .repetition = try RepetitionWindow.init(a, cfg.repeat_last_n) };
    }
    pub fn deinit(self: *GenerationState, a: std.mem.Allocator) void {
        self.repetition.deinit(a);
    }
};

pub const GenerationPipeline = struct {
    pub fn choose(allocator: std.mem.Allocator, logits_in: []const f32, state: *GenerationState, cfg: AdvancedGenerationConfig) !u32 {
        if (cfg.temperature <= 0) return TokenSampler.greedy(logits_in);
        const logits = try allocator.dupe(f32, logits_in);
        defer allocator.free(logits);
        LogitProcessor.repetitionPenalty(logits, &state.repetition, cfg.repetition_penalty);
        LogitProcessor.frequencyPresence(logits, &state.repetition, cfg.frequency_penalty, cfg.presence_penalty);
        LogitProcessor.temperature(logits, cfg.temperature);
        LogitProcessor.topK(logits, cfg.top_k);
        const probs = try allocator.alloc(f32, logits.len);
        defer allocator.free(probs);
        try LogitProcessor.softmax(probs, logits);
        LogitProcessor.topP(probs, cfg.top_p);
        const id = try TokenSampler.sample(probs, &state.rng);
        state.repetition.push(id);
        state.tokens_generated += 1;
        return id;
    }
    pub fn shouldStop(state: *const GenerationState, id: u32, cfg: AdvancedGenerationConfig) bool {
        return state.tokens_generated >= cfg.max_new_tokens or (cfg.eos_id != null and id == cfg.eos_id.?);
    }
};

pub const TensorAudit = struct {
    pub const IssueKind = enum { duplicate_name, out_of_bounds, bad_rank, zero_dimension, unsupported_type, misaligned_offset, overflow };
    pub const Issue = struct { kind: IssueKind, tensor_index: usize, name: []const u8 };

    pub fn typeBlock(tt: GgmlType) ?struct { q: usize, bytes: usize } {
        return switch (tt) {
            .f32 => .{ .q = 1, .bytes = 4 },
            .f16 => .{ .q = 1, .bytes = 2 },
            .q3_k => .{ .q = 256, .bytes = 110 },
            .q4_k => .{ .q = 256, .bytes = 144 },
            .q5_k => .{ .q = 256, .bytes = 176 },
            .q6_k => .{ .q = 256, .bytes = 210 },
            else => null,
        };
    }

    pub fn elementCount(t: *const OwnedTensorInfo) !usize {
        var n: usize = 1;
        if (t.dims.len == 0) return error.BadRank;
        for (t.dims) |d| {
            if (d == 0) return error.ZeroDimension;
            n = std.math.mul(usize, n, @intCast(d)) catch return error.Overflow;
        }
        return n;
    }

    pub fn byteSize(t: *const OwnedTensorInfo) !usize {
        const spec = typeBlock(t.ggml_type) orelse return error.UnsupportedType;
        const n = try elementCount(t);
        const blocks = (n + spec.q - 1) / spec.q;
        return std.math.mul(usize, blocks, spec.bytes) catch error.Overflow;
    }

    pub fn audit(allocator: std.mem.Allocator, index: *const GgufIndex, file_len: usize) ![]Issue {
        var issues = std.ArrayList(Issue).init(allocator);
        errdefer issues.deinit();
        var names = std.StringHashMap(void).init(allocator);
        defer names.deinit();
        for (index.tensors, 0..) |*t, i| {
            if (names.contains(t.name)) try issues.append(.{ .kind = .duplicate_name, .tensor_index = i, .name = t.name }) else try names.put(t.name, {});
            if (t.dims.len == 0 or t.dims.len > 4) try issues.append(.{ .kind = .bad_rank, .tensor_index = i, .name = t.name });
            var zero = false;
            for (t.dims) |d| {
                if (d == 0) zero = true;
            }
            if (zero) try issues.append(.{ .kind = .zero_dimension, .tensor_index = i, .name = t.name });
            if (typeBlock(t.ggml_type) == null) try issues.append(.{ .kind = .unsupported_type, .tensor_index = i, .name = t.name });
            if ((t.offset & 31) != 0) try issues.append(.{ .kind = .misaligned_offset, .tensor_index = i, .name = t.name });
            const size = byteSize(t) catch |e| {
                try issues.append(.{ .kind = if (e == error.Overflow) .overflow else .unsupported_type, .tensor_index = i, .name = t.name });
                continue;
            };
            const end = std.math.add(usize, @intCast(index.data_offset + t.offset), size) catch {
                try issues.append(.{ .kind = .overflow, .tensor_index = i, .name = t.name });
                continue;
            };
            if (end > file_len) try issues.append(.{ .kind = .out_of_bounds, .tensor_index = i, .name = t.name });
        }
        return issues.toOwnedSlice();
    }
};

pub const LlamaArchitectureAudit = struct {
    pub const Report = struct { ok: bool, missing: usize, bad_shape: usize, unsupported: usize };
    fn tensor(index: *const GgufIndex, name: []const u8) ?*const OwnedTensorInfo {
        for (index.tensors) |*t| if (std.mem.eql(u8, t.name, name)) return t;
        return null;
    }
    fn expect2(report: *Report, index: *const GgufIndex, name: []const u8, a: u64, b: u64) void {
        const t = tensor(index, name) orelse {
            report.missing += 1;
            report.ok = false;
            return;
        };
        if (t.dims.len != 2 or t.dims[0] != a or t.dims[1] != b) {
            report.bad_shape += 1;
            report.ok = false;
        }
        if (TensorAudit.typeBlock(t.ggml_type) == null) {
            report.unsupported += 1;
            report.ok = false;
        }
    }
    fn expect1(report: *Report, index: *const GgufIndex, name: []const u8, a: u64) void {
        const t = tensor(index, name) orelse {
            report.missing += 1;
            report.ok = false;
            return;
        };
        if (t.dims.len != 1 or t.dims[0] != a) {
            report.bad_shape += 1;
            report.ok = false;
        }
    }
    pub fn run(index: *const GgufIndex, arch: LlamaArch) !Report {
        var r = Report{ .ok = true, .missing = 0, .bad_shape = 0, .unsupported = 0 };
        expect2(&r, index, "token_embd.weight", arch.n_embd, arch.n_vocab);
        expect1(&r, index, "output_norm.weight", arch.n_embd);
        var buf: [96]u8 = undefined;
        for (0..arch.n_layer) |i| {
            const names = [7][]const u8{
                try std.fmt.bufPrint(&buf, "blk.{d}.attn_norm.weight", .{i}),
                try std.fmt.bufPrint(&buf, "blk.{d}.attn_q.weight", .{i}),
                try std.fmt.bufPrint(&buf, "blk.{d}.attn_k.weight", .{i}),
                try std.fmt.bufPrint(&buf, "blk.{d}.attn_v.weight", .{i}),
                try std.fmt.bufPrint(&buf, "blk.{d}.attn_output.weight", .{i}),
                try std.fmt.bufPrint(&buf, "blk.{d}.ffn_gate.weight", .{i}),
                try std.fmt.bufPrint(&buf, "blk.{d}.ffn_up.weight", .{i}),
            };
            _ = names;
            // Shape checks are performed by BoundLlamaModel as tensors are bound;
            // here we at least assert the pair of norms exists for each block.
            const n1 = try std.fmt.bufPrint(&buf, "blk.{d}.attn_norm.weight", .{i});
            expect1(&r, index, n1, arch.n_embd);
            const n2 = try std.fmt.bufPrint(&buf, "blk.{d}.ffn_norm.weight", .{i});
            expect1(&r, index, n2, arch.n_embd);
        }
        return r;
    }
};

pub const RuntimeHealth = struct {
    tokens_seen: u64 = 0,
    tokens_generated: u64 = 0,
    matvec_calls: u64 = 0,
    attention_calls: u64 = 0,
    bytes_read: u64 = 0,
    rejected_crypto_ops: u64 = 0,
    pub fn recordPrefill(self: *RuntimeHealth, n: usize) void {
        self.tokens_seen += n;
    }
    pub fn recordGeneration(self: *RuntimeHealth) void {
        self.tokens_generated += 1;
        self.tokens_seen += 1;
    }
    pub fn recordMatvec(self: *RuntimeHealth) void {
        self.matvec_calls += 1;
    }
    pub fn recordAttention(self: *RuntimeHealth) void {
        self.attention_calls += 1;
    }
    pub fn recordRead(self: *RuntimeHealth, n: usize) void {
        self.bytes_read += n;
    }
    pub fn rejectCrypto(self: *RuntimeHealth) void {
        self.rejected_crypto_ops += 1;
    }
};

pub const CryptoCapabilityMatrix = struct {
    pub const Capability = struct { name: []const u8, keygen: bool, encaps: bool, decaps: bool, sign: bool, verify: bool, kat_verified: bool };
    pub const rows = [_]Capability{
        .{ .name = "ML-KEM-512", .keygen = false, .encaps = false, .decaps = false, .sign = false, .verify = false, .kat_verified = false },
        .{ .name = "ML-KEM-768", .keygen = false, .encaps = false, .decaps = false, .sign = false, .verify = false, .kat_verified = false },
        .{ .name = "ML-KEM-1024", .keygen = false, .encaps = false, .decaps = false, .sign = false, .verify = false, .kat_verified = false },
        .{ .name = "ML-DSA-44", .keygen = true, .encaps = false, .decaps = false, .sign = true, .verify = true, .kat_verified = false },
        .{ .name = "ML-DSA-65", .keygen = true, .encaps = false, .decaps = false, .sign = true, .verify = true, .kat_verified = false },
        .{ .name = "ML-DSA-87", .keygen = true, .encaps = false, .decaps = false, .sign = true, .verify = true, .kat_verified = false },
        .{ .name = "SLH-DSA-SHA2-128s", .keygen = false, .encaps = false, .decaps = false, .sign = false, .verify = true, .kat_verified = false },
        .{ .name = "SLH-DSA-SHAKE-128s", .keygen = false, .encaps = false, .decaps = false, .sign = false, .verify = true, .kat_verified = false },
        .{ .name = "HQC-256", .keygen = false, .encaps = false, .decaps = false, .sign = false, .verify = false, .kat_verified = false },
        .{ .name = "FN-DSA-1024", .keygen = false, .encaps = false, .decaps = false, .sign = false, .verify = false, .kat_verified = false },
    };
    pub fn find(name: []const u8) ?Capability {
        for (rows) |r| if (std.mem.eql(u8, r.name, name)) return r;
        return null;
    }
};

pub const ModelIntegrityReport = struct { hash_ok: bool, gguf_ok: bool, tensor_issues: usize, arch_ok: bool, tokenizer_ok: bool };
pub fn auditPinnedModel(allocator: std.mem.Allocator, path: []const u8) !ModelIntegrityReport {
    const hash_ok = verifyPinnedModel(path) catch false;
    var file = try std.fs.cwd().openFile(path, .{});
    defer file.close();
    const st = try file.stat();
    const bytes = try allocator.alloc(u8, @intCast(st.size));
    defer allocator.free(bytes);
    _ = try file.readAll(bytes);
    var idx = GgufIndex.init(allocator);
    defer idx.deinit();
    const gguf_ok = (idx.parse(bytes) catch null) != null;
    if (!gguf_ok) return .{ .hash_ok = hash_ok, .gguf_ok = false, .tensor_issues = 0, .arch_ok = false, .tokenizer_ok = false };
    const issues = try TensorAudit.audit(allocator, &idx, bytes.len);
    defer allocator.free(issues);
    const arch = LlamaArch.fromIndex(&idx) catch return .{ .hash_ok = hash_ok, .gguf_ok = true, .tensor_issues = issues.len, .arch_ok = false, .tokenizer_ok = false };
    const ar = try LlamaArchitectureAudit.run(&idx, arch);
    GgufTokenizerMeta.fromIndex(&idx) catch {
        return .{ .hash_ok = hash_ok, .gguf_ok = true, .tensor_issues = issues.len, .arch_ok = ar.ok, .tokenizer_ok = false };
    };
    return .{ .hash_ok = hash_ok, .gguf_ok = true, .tensor_issues = issues.len, .arch_ok = ar.ok, .tokenizer_ok = true };
}

