pub const SlhCatalog = struct {
    pub const all = [_]SlhParams{ SlhParams.sha2_128s(), SlhParams.sha2_128f(), SlhParams.sha2_192s(), SlhParams.sha2_192f(), SlhParams.sha2_256s(), SlhParams.sha2_256f(), SlhParams.shake_128s(), SlhParams.shake_128f(), SlhParams.shake_192s(), SlhParams.shake_192f(), SlhParams.shake_256s(), SlhParams.shake_256f() };
    pub fn byName(name: []const u8) ?SlhParams {
        for (all) |p| if (std.mem.eql(u8, p.name, name)) return p;
        return null;
    }
};

// ---- Additional self-tests for this checkpoint ----------------------------
test "bit writer reader round trip" {
    var b: [16]u8 = undefined;
    var w = BitWriter.init(&b);
    try w.put(5, 3);
    try w.put(511, 9);
    var r = BitReader.init(&b);
    try std.testing.expectEqual(@as(u64, 5), try r.get(3));
    try std.testing.expectEqual(@as(u64, 511), try r.get(9));
}
test "ML-DSA eta codec" {
    var p: MlDsa.Poly = undefined;
    for (0..MlDsa.N) |i| p[i] = @as(i32, @intCast(i % 5)) - 2;
    var b: [256]u8 = undefined;
    const n = try MlDsaStdPacking.packEta(&b, &p, 2);
    var q: MlDsa.Poly = undefined;
    _ = try MlDsaStdPacking.unpackEta(&q, b[0..n], 2);
    try std.testing.expectEqualSlices(i32, &p, &q);
}
test "ML-DSA t1 codec" {
    var p: MlDsa.Poly = undefined;
    for (0..MlDsa.N) |i| p[i] = @intCast(i & 1023);
    var b: [512]u8 = undefined;
    const n = try MlDsaStdPacking.packT1(&b, &p);
    var q: MlDsa.Poly = undefined;
    _ = try MlDsaStdPacking.unpackT1(&q, b[0..n]);
    try std.testing.expectEqualSlices(i32, &p, &q);
}
test "SLH parameter catalog" {
    try std.testing.expectEqual(@as(usize, 12), SlhCatalog.all.len);
    try std.testing.expect(SlhCatalog.byName("SLH-DSA-SHAKE-256f") != null);
}
test "SLH WOTS chain lengths" {
    const p = SlhParams.sha2_128s();
    var out: [80]u8 = undefined;
    var m = [_]u8{0x12} ** 32;
    try SlhWotsSignature.chainLengths(out[0..p.wotsLen()], &m, p);
    for (out[0..p.wotsLen()]) |x| try std.testing.expect(x < 16);
}
test "repetition window" {
    const a = std.testing.allocator;
    var w = try RepetitionWindow.init(a, 4);
    defer w.deinit(a);
    w.push(1);
    w.push(2);
    w.push(1);
    try std.testing.expectEqual(@as(usize, 2), w.count(1));
}
test "token sampler greedy" {
    const x = [_]f32{ -1, 2, 1 };
    try std.testing.expectEqual(@as(u32, 1), TokenSampler.greedy(&x));
}
test "crypto capability matrix is fail closed" {
    const h = CryptoCapabilityMatrix.find("HQC-256").?;
    try std.testing.expect(!h.keygen and !h.kat_verified);
}

