pub const CommandCatalog = struct {
    pub const Item = struct { name: []const u8, usage: []const u8, description: []const u8 };
    pub const items = [_]Item{
        .{ .name = "install", .usage = "install", .description = "run Android lock/unlock Keystore enrollment checkpoint" },
        .{ .name = "model", .usage = "model", .description = "print pinned GGUF identity" },
        .{ .name = "verify", .usage = "verify <path.gguf>", .description = "verify pinned model SHA-256" },
        .{ .name = "gguf", .usage = "gguf <path.gguf>", .description = "parse and summarize GGUF" },
        .{ .name = "audit", .usage = "audit <path.gguf>", .description = "run model/tensor/tokenizer audit" },
        .{ .name = "pqc", .usage = "pqc", .description = "list post-quantum capability registry" },
        .{ .name = "tokenize", .usage = "tokenize <path.gguf> <text>", .description = "tokenize using GGUF tokenizer metadata" },
        .{ .name = "detokenize", .usage = "detokenize <path.gguf> <ids...>", .description = "decode token ids" },
        .{ .name = "generate", .usage = "generate <path.gguf> <prompt>", .description = "run scalar pure-Zig generation" },
        .{ .name = "mlkem-selftest", .usage = "mlkem-selftest", .description = "run deterministic ML-KEM self consistency checks" },
        .{ .name = "mldsa-selftest", .usage = "mldsa-selftest", .description = "run expanded ML-DSA equation tests" },
        .{ .name = "slh-selftest", .usage = "slh-selftest", .description = "run SLH-DSA hash-tree/WOTS/FORS checks" },
    };
    pub fn find(name: []const u8) ?Item {
        for (items) |x| if (std.mem.eql(u8, x.name, name)) return x;
        return null;
    }
};

/// Host-side half of Android Keystore enrollment. The private key must be
/// generated by the Android provider, not by this host process.
pub fn runAndroidInstallCheckpoint(input: *TuiInput) !void {
    tuiHeader("ANDROID KEYSTORE ENROLLMENT");
    tuiBox("Device lock/unlock required");
    std.debug.print("Before continuing, lock the Android device, then unlock it\n", .{});
    std.debug.print("using its screen lock. Come right back to this installer.\n\n", .{});
    std.debug.print("The Android app will generate its non-exportable RSA-2048 key\n", .{});
    std.debug.print("only after you confirm that step below.\n\n", .{});
    while (true) {
        const answer = try tuiReadLine(input, "Type u after locking and unlocking the device (q to cancel)> ");
        if (std.mem.eql(u8, answer, "q")) return error.InstallCancelled;
        if (std.mem.eql(u8, answer, "u")) break;
        std.debug.print("Please type lowercase u after the device has been unlocked.\n", .{});
    }
    std.debug.print("\nCheckpoint confirmed. Ask the Android bridge to generate the key now.\n", .{});
    std.debug.print("The private key must remain inside Android Keystore.\n", .{});
}

pub const SecurityInvariant = struct {
    pub const Item = struct { name: []const u8, required: bool };
    pub const all = [_]Item{
        .{ .name = "no_c_import", .required = true },
        .{ .name = "no_libc_link", .required = true },
        .{ .name = "no_openssl_link", .required = true },
        .{ .name = "no_liboqs_link", .required = true },
        .{ .name = "no_llama_cpp_link", .required = true },
        .{ .name = "constant_time_kem_fallback", .required = true },
        .{ .name = "model_hash_pinned", .required = true },
        .{ .name = "bounded_gguf_offsets", .required = true },
        .{ .name = "noncanonical_signature_rejected", .required = true },
        .{ .name = "special_token_boundaries", .required = true },
        .{ .name = "secure_zero_secret_buffers", .required = true },
        .{ .name = "unsupported_pqc_fails_closed", .required = true },
        .{ .name = "context_length_bounded", .required = true },
        .{ .name = "tensor_shape_checked", .required = true },
        .{ .name = "token_id_range_checked", .required = true },
        .{ .name = "ciphertext_length_checked", .required = true },
        .{ .name = "signature_length_checked", .required = true },
        .{ .name = "nonce_domain_separated", .required = true },
        .{ .name = "transcript_domain_separated", .required = true },
        .{ .name = "no_silent_crypto_substitution", .required = true },
    };
};
test "10k checkpoint tables" {
    try std.testing.expect(QuantRowSizeTable.q3k_4096 == 1760);
    try std.testing.expect(CommandCatalog.find("audit") != null);
    try std.testing.expect(SecurityInvariant.all.len >= 20);
}

