    pub const Q4_K = Fact{ .name = "Q4_K", .block_values = 256, .block_bytes = 144, .bits_per_weight = 4.5 };
    pub const Q5_K = Fact{ .name = "Q5_K", .block_values = 256, .block_bytes = 176, .bits_per_weight = 5.5 };
    pub const Q6_K = Fact{ .name = "Q6_K", .block_values = 256, .block_bytes = 210, .bits_per_weight = 6.5625 };
    pub fn forType(t: GgmlType) ?Fact {
        return switch (t) {
            .f32 => F32,
            .f16 => F16,
            .q3_k => Q3_K,
            .q4_k => Q4_K,
            .q5_k => Q5_K,
            .q6_k => Q6_K,
            else => null,
        };
    }
};

