pub const ParameterSanity = struct {
    pub fn mlDsa(p: MlDsaParams) bool {
        return p.k >= 4 and p.k <= 8 and p.l >= 4 and p.l <= 7 and (p.eta == 2 or p.eta == 4) and p.tau > 0 and p.omega > 0;
    }
    pub fn slh(p: SlhParams) bool {
        return (p.n == 16 or p.n == 24 or p.n == 32) and p.d > 0 and p.hp > 0 and p.d * p.hp == p.h and p.w == 16;
    }
    pub fn llama(a: LlamaArch) bool {
        return a.n_embd > 0 and a.n_layer > 0 and a.n_head > 0 and a.n_head_kv > 0 and a.n_vocab > 0 and a.n_embd % a.n_head == 0;
    }
};
test "SLH facade Sha2_128s" {
