}

// ---- Checkpoint-level operational diagnostics --------------------------------
pub const DiagnosticSeverity = enum { info, warning, fatal };
pub const Diagnostic = struct { severity: DiagnosticSeverity, code: []const u8, message: []const u8 };

pub const DiagnosticCatalog = struct {
    pub const entries = [_]Diagnostic{
        .{ .severity = .fatal, .code = "MODEL_HASH_MISMATCH", .message = "Pinned GGUF SHA-256 does not match expected digest" },
        .{ .severity = .fatal, .code = "GGUF_MAGIC", .message = "GGUF magic/version is invalid or unsupported" },
        .{ .severity = .fatal, .code = "GGUF_RANGE", .message = "Tensor byte range escapes mapped file" },
        .{ .severity = .fatal, .code = "GGUF_SHAPE", .message = "Tensor rank or dimensions are incompatible with Llama architecture" },
        .{ .severity = .fatal, .code = "GGUF_QUANT", .message = "Tensor quantization type has no pure-Zig kernel" },
        .{ .severity = .fatal, .code = "TOKEN_ID_RANGE", .message = "Tokenizer produced an id outside vocabulary" },
        .{ .severity = .fatal, .code = "MLKEM_CT_LEN", .message = "ML-KEM ciphertext length is invalid" },
        .{ .severity = .fatal, .code = "MLDSA_SIG_LEN", .message = "ML-DSA signature length is invalid" },
        .{ .severity = .fatal, .code = "MLDSA_NONCANON", .message = "ML-DSA encoding is non-canonical" },
        .{ .severity = .warning, .code = "PQC_UNVERIFIED", .message = "Algorithm implementation has not passed official KAT vectors" },
        .{ .severity = .warning, .code = "SCALAR_KERNEL", .message = "Portable scalar quantized kernel is active; performance is not optimized" },
        .{ .severity = .warning, .code = "NO_ZIG_COMPILER", .message = "This checkpoint was structurally checked but not compiled in the build environment" },
        .{ .severity = .info, .code = "PURE_ZIG", .message = "No C ABI import or system crypto dependency is required" },
        .{ .severity = .info, .code = "MODEL_PINNED", .message = "Model repository, filename and SHA-256 are pinned" },
        .{ .severity = .info, .code = "FAIL_CLOSED", .message = "Unsupported cryptographic operations return errors instead of substitutes" },
    };
    pub fn find(code: []const u8) ?Diagnostic {
        for (entries) |d| if (std.mem.eql(u8, d.code, code)) return d;
        return null;
    }
};

pub const BuildFeatureSummary = struct {
    pure_zig: bool = true,
    c_linking: bool = false,
    python_runtime: bool = false,
    llama_cpp_runtime: bool = false,
    gguf_parser: bool = true,
    llama_scalar_runtime: bool = true,
    tokenizer_runtime: bool = true,
    ml_kem_equations: bool = true,
    ml_dsa_equations: bool = true,
    slh_dsa_equations: bool = true,
    official_kats_all_passed: bool = false,

    pub fn safeForProductionCrypto(self: BuildFeatureSummary) bool {
        return self.pure_zig and !self.c_linking and self.official_kats_all_passed;
    }
};

pub const CheckpointInfo = struct {
    pub const target_lines: usize = 10000;
    pub const long_term_target_lines: usize = 50000;
    pub const zig_target = "0.15.2";
    pub const model_file = ModelSpec.file;
    pub const model_sha256 = ModelSpec.sha256_hex;

    pub fn banner(writer: anytype, lines: usize) !void {
        try writer.print("NAZA pure-Zig monolith: {d}/{d} lines checkpoint, Zig {s}, model {s}\n", .{ lines, long_term_target_lines, zig_target, model_file });
    }
};

test "diagnostic catalog fail closed" {
    const d = DiagnosticCatalog.find("MLDSA_NONCANON").?;
    try std.testing.expectEqual(DiagnosticSeverity.fatal, d.severity);
    try std.testing.expect(DiagnosticCatalog.find("DOES_NOT_EXIST") == null);
}

test "build feature summary does not overclaim" {
    const f = BuildFeatureSummary{};
    try std.testing.expect(f.pure_zig);
    try std.testing.expect(!f.safeForProductionCrypto());
}

pub const TenKCheckpoint = struct {
    pub const reached = true;
    pub const philosophy = "substantive implementation over padding";
    pub const source_language = "Zig";
    pub const foreign_linkage = false;
    pub const primary_model = CheckpointInfo.model_file;
    pub const pqc_policy = "fail closed until vectors pass";

    pub fn assertInvariants() !void {
        if (!reached) return error.CheckpointNotReached;
        if (foreign_linkage) return error.ForeignLinkageForbidden;
        if (!std.mem.eql(u8, source_language, "Zig")) return error.WrongLanguage;
    }
};

test "10k checkpoint invariants" {
    try TenKCheckpoint.assertInvariants();
}

// ============================================================================
// WAVE 15K: deep pure-Zig expansion
// These namespaces are intentionally prefixed to avoid collisions with earlier
// checkpoint symbols. The code is portable scalar-first and contains no C ABI.
// ============================================================================

pub const Wave15HqcCore = struct {
    pub const max_words: usize = 1024;
    pub const Params = struct {
        name: []const u8,
        n: usize,
        n1: usize,
        n2: usize,
        omega: usize,
        omega_r: usize,
        omega_e: usize,
        security_bits: u16,
    };

    pub const parameter_sets = [_]Params{
        .{ .name = "HQC-128", .n = 17669, .n1 = 46, .n2 = 384, .omega = 66, .omega_r = 75, .omega_e = 75, .security_bits = 128 },
        .{ .name = "HQC-192", .n = 35851, .n1 = 56, .n2 = 640, .omega = 100, .omega_r = 114, .omega_e = 114, .security_bits = 192 },
        .{ .name = "HQC-256", .n = 57637, .n1 = 90, .n2 = 640, .omega = 131, .omega_r = 149, .omega_e = 149, .security_bits = 256 },
    };

    pub fn wordsForBits(n: usize) usize {
        return (n + 63) / 64;
    }
    pub fn lastWordMask(n: usize) u64 {
        const rem = n & 63;
        return if (rem == 0) ~@as(u64, 0) else (@as(u64, 1) << @intCast(rem)) - 1;
    }

    pub fn zero(dst: []u64) void {
        @memset(dst, 0);
    }
    pub fn copy(dst: []u64, src: []const u64) void {
        const n = @min(dst.len, src.len);
        @memcpy(dst[0..n], src[0..n]);
        if (dst.len > n) @memset(dst[n..], 0);
    }
    pub fn xorInto(dst: []u64, src: []const u64) void {
        const n = @min(dst.len, src.len);
        for (0..n) |i| dst[i] ^= src[i];
    }
    pub fn andInto(dst: []u64, src: []const u64) void {
        const n = @min(dst.len, src.len);
        for (0..n) |i| dst[i] &= src[i];
        if (dst.len > n) @memset(dst[n..], 0);
    }
    pub fn parity(words: []const u64) u1 {
        var p: u1 = 0;
        for (words) |w| p ^= @as(u1, @truncate(@popCount(w)));
        return p;
    }
    pub fn weight(words: []const u64) usize {
        var n: usize = 0;
        for (words) |w| n += @popCount(w);
        return n;
    }
    pub fn getBit(words: []const u64, bit: usize) u1 {
        const wi = bit >> 6;
        if (wi >= words.len) return 0;
        return @truncate((words[wi] >> @intCast(bit & 63)) & 1);
    }
    pub fn setBit(words: []u64, bit: usize, value: u1) void {
        const wi = bit >> 6;
        if (wi >= words.len) return;
        const m = @as(u64, 1) << @intCast(bit & 63);
        words[wi] = (words[wi] & ~m) | (@as(u64, value) * m);
    }
    pub fn toggleBit(words: []u64, bit: usize) void {
        const wi = bit >> 6;
        if (wi < words.len) words[wi] ^= @as(u64, 1) << @intCast(bit & 63);
    }
    pub fn clearUnused(words: []u64, nbits: usize) void {
        const need = wordsForBits(nbits);
        if (need == 0 or words.len == 0) return;
        if (need <= words.len) words[need - 1] &= lastWordMask(nbits);
        if (words.len > need) @memset(words[need..], 0);
    }

    pub fn rotateLeftBits(dst: []u64, src: []const u64, nbits: usize, shift_in: usize) void {
        zero(dst);
        if (nbits == 0) return;
        const shift = shift_in % nbits;
        var i: usize = 0;
        while (i < nbits) : (i += 1) {
            if (getBit(src, i) != 0) setBit(dst, (i + shift) % nbits, 1);
        }
        clearUnused(dst, nbits);
    }
    pub fn rotateRightBits(dst: []u64, src: []const u64, nbits: usize, shift_in: usize) void {
        if (nbits == 0) {
            zero(dst);
            return;
        }
        const s = shift_in % nbits;
        rotateLeftBits(dst, src, nbits, (nbits - s) % nbits);
    }
    pub fn cyclicMulSparse(dst: []u64, dense: []const u64, sparse_positions: []const u32, nbits: usize, scratch: []u64) void {
        zero(dst);
        for (sparse_positions) |pos| {
            rotateLeftBits(scratch, dense, nbits, @as(usize, pos) % nbits);
            Wave15HqcCore.xorInto(dst, scratch);
        }
        clearUnused(dst, nbits);
    }
    pub fn cyclicMulDense(dst: []u64, a: []const u64, b: []const u64, nbits: usize) void {
        zero(dst);
        var i: usize = 0;
        while (i < nbits) : (i += 1) {
            if (getBit(a, i) == 0) continue;
            var j: usize = 0;
            while (j < nbits) : (j += 1) if (getBit(b, j) != 0) toggleBit(dst, (i + j) % nbits);
        }
        clearUnused(dst, nbits);
    }
    pub fn dotParity(a: []const u64, b: []const u64) u1 {
        const n = @min(a.len, b.len);
        var p: u1 = 0;
        for (0..n) |i| p ^= @as(u1, @truncate(@popCount(a[i] & b[i])));
        return p;
    }
    pub fn hammingDistance(a: []const u64, b: []const u64) usize {
        const n = @min(a.len, b.len);
        var d: usize = 0;
        for (0..n) |i| d += @popCount(a[i] ^ b[i]);
        for (n..a.len) |i| d += @popCount(a[i]);
        for (n..b.len) |i| d += @popCount(b[i]);
        return d;
    }

    pub const SparseSampler = struct {
        state: u64,
        pub fn init(seed: u64) SparseSampler {
            return .{ .state = if (seed == 0) 0x9e3779b97f4a7c15 else seed };
        }
        fn next(self: *SparseSampler) u64 {
            var x = self.state;
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            self.state = x;
            return x;
        }
        pub fn sampleDistinct(self: *SparseSampler, out: []u32, modulus: u32) !void {
            if (out.len > modulus) return error.WeightTooLarge;
            var used: usize = 0;
            while (used < out.len) {
                const x: u32 = @intCast(self.next() % modulus);
                var duplicate = false;
                for (out[0..used]) |v| if (v == x) {
                    duplicate = true;
                    break;
                };
                if (!duplicate) {
                    out[used] = x;
                    used += 1;
                }
            }
        }
    };

    pub const ReedMuller = struct {
        pub fn encodeRm1(byte: u8, out: *[128]u8) void {
            const constant: u1 = @truncate(byte >> 7);
            const linear: u7 = @truncate(byte);
            for (0..128) |x| {
                var bit: u1 = constant;
                for (0..7) |j| bit ^= @as(u1, @truncate(((linear >> @intCast(j)) & 1) & ((x >> j) & 1)));
                out[x] = bit;
            }
        }
        pub fn correlation(codeword: []const u8, mask: u8) i32 {
            var acc: i32 = 0;
            for (codeword, 0..) |b, x| {
                var predicted: u1 = @truncate(mask >> 7);
                const lin: u7 = @truncate(mask);
                for (0..7) |j| predicted ^= @as(u1, @truncate(((lin >> @intCast(j)) & 1) & ((x >> j) & 1)));
                acc += if ((b & 1) == predicted) 1 else -1;
            }
            return acc;
        }
        pub fn decodeBruteforce(codeword: []const u8) u8 {
            var best: u8 = 0;
            var best_score: i32 = -1000000;
            var m: usize = 0;
            while (m < 256) : (m += 1) {
                const score = correlation(codeword, @intCast(m));
                if (score > best_score) {
                    best_score = score;
                    best = @intCast(m);
                }
            }
            return best;
        }
    };

    pub const Gf256 = struct {
        pub fn mul(a_in: u8, b_in: u8) u8 {
            var a = a_in;
            var b = b_in;
            var r: u8 = 0;
            var i: usize = 0;
            while (i < 8) : (i += 1) {
                if ((b & 1) != 0) r ^= a;
                const hi = a & 0x80;
                a <<= 1;
                if (hi != 0) a ^= 0x1d;
                b >>= 1;
            }
            return r;
        }
        pub fn pow(a: u8, e_in: usize) u8 {
            var e = e_in;
            var x = a;
            var r: u8 = 1;
            while (e != 0) : (e >>= 1) {
                if ((e & 1) != 0) r = mul(r, x);
                x = mul(x, x);
            }
            return r;
        }
        pub fn inv(a: u8) u8 {
            return if (a == 0) 0 else pow(a, 254);
        }
        pub fn div(a: u8, b: u8) u8 {
            return if (b == 0) 0 else mul(a, inv(b));
        }
    };

    pub const ReedSolomon = struct {
        pub fn evalPoly(coeffs: []const u8, x: u8) u8 {
            var y: u8 = 0;
            var i = coeffs.len;
            while (i > 0) {
                i -= 1;
                y = Gf256.mul(y, x) ^ coeffs[i];
            }
            return y;
        }
        pub fn syndromes(code: []const u8, out: []u8) void {
            for (out, 0..) |*v, i| v.* = evalPoly(code, Gf256.pow(2, i + 1));
        }
        pub fn allZero(x: []const u8) bool {
            for (x) |v| if (v != 0) return false;
            return true;
        }
        pub fn formalDerivative(poly: []const u8, out: []u8) void {
            @memset(out, 0);
            var i: usize = 1;
            while (i < poly.len and i - 1 < out.len) : (i += 1) {
                if ((i & 1) != 0) out[i - 1] = poly[i];
            }
        }
    };

    pub const DecoderTrace = struct {
        iterations: usize = 0,
        initial_weight: usize = 0,
        final_weight: usize = 0,
        converged: bool = false,
        pub fn update(self: *DecoderTrace, before: usize, after: usize) void {
            if (self.iterations == 0) self.initial_weight = before;
            self.iterations += 1;
            self.final_weight = after;
            self.converged = after == 0;
        }
    };

    pub fn bitFlipIteration(error_estimate: []u64, syndrome: []u64, checks: []const []const u32, threshold: usize) usize {
        var flips: usize = 0;
        for (checks, 0..) |neighbors, bit| {
            var unsat: usize = 0;
            for (neighbors) |sidx| {
                if (getBit(syndrome, sidx) != 0) unsat += 1;
            }
            if (unsat >= threshold) {
                toggleBit(error_estimate, bit);
                flips += 1;
            }
        }
        return flips;
    }

    pub fn syndromeFromSparse(out: []u64, positions: []const u32, columns: []const []const u64) void {
        zero(out);
        for (positions) |p| {
            if (p < columns.len) Wave15HqcCore.xorInto(out, columns[p]);
        }
    }
};
