pub const Wave15FnDsaCore = struct {
    pub const q: i32 = 12289;
    pub const Complex = struct {
        re: f64,
        im: f64,
        pub fn add(a: @This(), b: @This()) @This() {
            return .{ .re = a.re + b.re, .im = a.im + b.im };
        }
        pub fn sub(a: @This(), b: @This()) @This() {
            return .{ .re = a.re - b.re, .im = a.im - b.im };
        }
        pub fn mul(a: @This(), b: @This()) @This() {
            return .{ .re = a.re * b.re - a.im * b.im, .im = a.re * b.im + a.im * b.re };
        }
        pub fn conj(a: @This()) @This() {
            return .{ .re = a.re, .im = -a.im };
        }
        pub fn scale(a: @This(), s: f64) @This() {
            return .{ .re = a.re * s, .im = a.im * s };
        }
        pub fn norm2(a: @This()) f64 {
            return a.re * a.re + a.im * a.im;
        }
    };

    pub fn modQ(x_in: i64) i32 {
        var x = x_in % @as(i64, q);
        if (x < 0) x += q;
        return @intCast(x);
    }
    pub fn addQ(a: i32, b: i32) i32 {
        return modQ(@as(i64, a) + b);
    }
    pub fn subQ(a: i32, b: i32) i32 {
        return modQ(@as(i64, a) - b);
    }
    pub fn mulQ(a: i32, b: i32) i32 {
        return modQ(@as(i64, a) * b);
    }
    pub fn powQ(a: i32, e_in: u32) i32 {
        var e = e_in;
        var x = a;
        var r: i32 = 1;
        while (e != 0) : (e >>= 1) {
            if ((e & 1) != 0) r = mulQ(r, x);
            x = mulQ(x, x);
        }
        return r;
    }
    pub fn invQ(a: i32) i32 {
        return powQ(a, @intCast(q - 2));
    }
    pub fn centerQ(a: i32) i32 {
        const x = modQ(a);
        return if (x > q / 2) x - q else x;
    }

    pub fn bitReverse(x_in: usize, logn: u5) usize {
        var x = x_in;
        var r: usize = 0;
        var i: u5 = 0;
        while (i < logn) : (i += 1) {
            r = (r << 1) | (x & 1);
            x >>= 1;
        }
        return r;
    }
    pub fn fft(a: []Wave15FnDsaCore.Complex, inverse: bool) void {
        const n = a.len;
        if (n <= 1) return;
        var logn: u5 = 0;
        var t = n;
        while (t > 1) : (t >>= 1) logn += 1;
        for (0..n) |i| {
            const j = bitReverse(i, logn);
            if (j > i) {
                const z = a[i];
                a[i] = a[j];
                a[j] = z;
            }
        }
        var len: usize = 2;
        while (len <= n) : (len <<= 1) {
            const ang = (if (inverse) 2.0 else -2.0) * std.math.pi / @as(f64, @floatFromInt(len));
            const wlen = Wave15FnDsaCore.Complex{ .re = @cos(ang), .im = @sin(ang) };
            var i: usize = 0;
            while (i < n) : (i += len) {
                var w = Wave15FnDsaCore.Complex{ .re = 1, .im = 0 };
                var j: usize = 0;
                while (j < len / 2) : (j += 1) {
                    const u = a[i + j];
                    const v = Wave15FnDsaCore.Complex.mul(a[i + j + len / 2], w);
                    a[i + j] = Wave15FnDsaCore.Complex.add(u, v);
                    a[i + j + len / 2] = Wave15FnDsaCore.Complex.sub(u, v);
                    w = Wave15FnDsaCore.Complex.mul(w, wlen);
                }
            }
        }
        if (inverse) {
            const invn = 1.0 / @as(f64, @floatFromInt(n));
            for (a) |*z| z.* = Wave15FnDsaCore.Complex.scale(z.*, invn);
        }
    }
    pub fn splitFft(src: []const Wave15FnDsaCore.Complex, even: []Wave15FnDsaCore.Complex, odd: []Wave15FnDsaCore.Complex) void {
        const n = @min(even.len, odd.len);
        for (0..n) |i| {
            even[i] = src[2 * i];
            odd[i] = src[2 * i + 1];
        }
    }
    pub fn mergeFft(dst: []Wave15FnDsaCore.Complex, even: []const Wave15FnDsaCore.Complex, odd: []const Wave15FnDsaCore.Complex) void {
        const n = @min(even.len, odd.len);
        for (0..n) |i| {
            dst[2 * i] = even[i];
            dst[2 * i + 1] = odd[i];
        }
    }
    pub fn polyAdd(dst: []f64, a: []const f64, b: []const f64) void {
        const n = @min(dst.len, @min(a.len, b.len));
        for (0..n) |i| dst[i] = a[i] + b[i];
    }
    pub fn polySub(dst: []f64, a: []const f64, b: []const f64) void {
        const n = @min(dst.len, @min(a.len, b.len));
        for (0..n) |i| dst[i] = a[i] - b[i];
    }
    pub fn polyMulPointwise(dst: []Wave15FnDsaCore.Complex, a: []const Wave15FnDsaCore.Complex, b: []const Wave15FnDsaCore.Complex) void {
        const n = @min(dst.len, @min(a.len, b.len));
        for (0..n) |i| dst[i] = Wave15FnDsaCore.Complex.mul(a[i], b[i]);
    }
    pub fn polyAdjoint(dst: []Wave15FnDsaCore.Complex, a: []const Wave15FnDsaCore.Complex) void {
        const n = @min(dst.len, a.len);
        for (0..n) |i| dst[i] = Wave15FnDsaCore.Complex.conj(a[i]);
    }
    pub fn gramMatrix(g00: []f64, g01: []Wave15FnDsaCore.Complex, g11: []f64, b00: []const Wave15FnDsaCore.Complex, b01: []const Wave15FnDsaCore.Complex, b10: []const Wave15FnDsaCore.Complex, b11: []const Wave15FnDsaCore.Complex) void {
        const n = @min(g00.len, @min(g11.len, @min(g01.len, @min(b00.len, @min(b01.len, @min(b10.len, b11.len))))));
        for (0..n) |i| {
            g00[i] = Wave15FnDsaCore.Complex.norm2(b00[i]) + Wave15FnDsaCore.Complex.norm2(b01[i]);
            g11[i] = Wave15FnDsaCore.Complex.norm2(b10[i]) + Wave15FnDsaCore.Complex.norm2(b11[i]);
            g01[i] = Wave15FnDsaCore.Complex.add(Wave15FnDsaCore.Complex.mul(b00[i], Wave15FnDsaCore.Complex.conj(b10[i])), Wave15FnDsaCore.Complex.mul(b01[i], Wave15FnDsaCore.Complex.conj(b11[i])));
        }
    }

    pub const LdlNode = struct { l: Wave15FnDsaCore.Complex, d11: f64 };
    pub fn ldl(g00: f64, g01: Wave15FnDsaCore.Complex, g11: f64) LdlNode {
        const inv = if (g00 == 0) 0 else 1.0 / g00;
        const l = Wave15FnDsaCore.Complex.scale(g01, inv);
        const d = g11 - Wave15FnDsaCore.Complex.norm2(g01) * inv;
        return .{ .l = l, .d11 = d };
    }

    pub const GaussianPrng = struct {
        s0: u64,
        s1: u64,
        pub fn init(seed: u128) GaussianPrng {
            return .{ .s0 = @truncate(seed), .s1 = @truncate(seed >> 64) };
        }
        fn next(self: *GaussianPrng) u64 {
            var x = self.s0;
            const y = self.s1;
            self.s0 = y;
            x ^= x << 23;
            self.s1 = x ^ y ^ (x >> 17) ^ (y >> 26);
            return self.s1 + y;
        }
        pub fn uniform01(self: *GaussianPrng) f64 {
            return (@as(f64, @floatFromInt(self.next() >> 11)) + 0.5) / 9007199254740992.0;
        }
        pub fn normal(self: *GaussianPrng) f64 {
            const uniform_a = @max(self.uniform01(), 1e-15);
            const uniform_b = self.uniform01();
            return @sqrt(-2.0 * @log(uniform_a)) * @cos(2.0 * std.math.pi * uniform_b);
        }
        pub fn sampleDiscrete(self: *GaussianPrng, sigma: f64, center: f64) i32 {
            return @intFromFloat(@round(center + sigma * self.normal()));
        }
    };

    pub fn normSqI16(a: []const i16, b: []const i16) u64 {
        const n = @min(a.len, b.len);
        var s: u64 = 0;
        for (0..n) |i| {
            const x: i64 = a[i];
            const y: i64 = b[i];
            s += @intCast(x * x + y * y);
        }
        return s;
    }
    pub fn isShort(a: []const i16, b: []const i16, bound: u64) bool {
        return normSqI16(a, b) <= bound;
    }

    pub const SignatureEnvelope = struct {
        nonce: [40]u8 = [_]u8{0} ** 40,
        logn: u8 = 0,
        coeffs_len: usize = 0,
        pub fn validate(self: SignatureEnvelope) bool {
            return self.logn >= 1 and self.logn <= 10 and self.coeffs_len <= (@as(usize, 1) << @intCast(self.logn));
        }
    };

    pub fn verifyEquation(h: []const i32, s1: []const i16, s2: []const i16, c: []const i32) bool {
        const n = @min(h.len, @min(s1.len, @min(s2.len, c.len)));
        for (0..n) |i| if (modQ(@as(i64, s1[i]) + @as(i64, s2[i]) * h[i]) != modQ(c[i])) return false;
        return true;
    }
};
