pub const Wave15SlhDeep = struct {
    pub const Variant = struct { name: []const u8, n: u8, h: u8, d: u8, a: u8, k: u8, w: u16 };
    pub const variants = [_]Variant{
        .{ .name = "SLH-DSA-SHA2-128s", .n = 16, .h = 63, .d = 7, .a = 12, .k = 14, .w = 16 },
        .{ .name = "SLH-DSA-SHA2-128f", .n = 16, .h = 66, .d = 22, .a = 6, .k = 33, .w = 16 },
        .{ .name = "SLH-DSA-SHA2-192s", .n = 24, .h = 63, .d = 7, .a = 14, .k = 17, .w = 16 },
        .{ .name = "SLH-DSA-SHA2-192f", .n = 24, .h = 66, .d = 22, .a = 8, .k = 33, .w = 16 },
        .{ .name = "SLH-DSA-SHA2-256s", .n = 32, .h = 64, .d = 8, .a = 14, .k = 22, .w = 16 },
        .{ .name = "SLH-DSA-SHA2-256f", .n = 32, .h = 68, .d = 17, .a = 9, .k = 35, .w = 16 },
        .{ .name = "SLH-DSA-SHAKE-128s", .n = 16, .h = 63, .d = 7, .a = 12, .k = 14, .w = 16 },
        .{ .name = "SLH-DSA-SHAKE-128f", .n = 16, .h = 66, .d = 22, .a = 6, .k = 33, .w = 16 },
        .{ .name = "SLH-DSA-SHAKE-192s", .n = 24, .h = 63, .d = 7, .a = 14, .k = 17, .w = 16 },
        .{ .name = "SLH-DSA-SHAKE-192f", .n = 24, .h = 66, .d = 22, .a = 8, .k = 33, .w = 16 },
        .{ .name = "SLH-DSA-SHAKE-256s", .n = 32, .h = 64, .d = 8, .a = 14, .k = 22, .w = 16 },
        .{ .name = "SLH-DSA-SHAKE-256f", .n = 32, .h = 68, .d = 17, .a = 9, .k = 35, .w = 16 },
    };

    pub const Address = struct {
        layer: u32 = 0,
        tree: u64 = 0,
        kind: u32 = 0,
        keypair: u32 = 0,
        chain: u32 = 0,
        hash: u32 = 0,
        height: u32 = 0,
        index: u32 = 0,
        pub fn encode(self: Address, out: *[32]u8) void {
            std.mem.writeInt(u32, out[0..4], self.layer, .big);
            std.mem.writeInt(u64, out[4..12], self.tree, .big);
            std.mem.writeInt(u32, out[12..16], self.kind, .big);
            std.mem.writeInt(u32, out[16..20], self.keypair, .big);
            std.mem.writeInt(u32, out[20..24], self.chain, .big);
            std.mem.writeInt(u32, out[24..28], self.hash, .big);
            out[28] = @truncate(self.height >> 8);
            out[29] = @truncate(self.height);
            out[30] = @truncate(self.index >> 8);
            out[31] = @truncate(self.index);
        }
        pub fn withLayer(self: Address, x: u32) Address {
            var r = self;
            r.layer = x;
            return r;
        }
        pub fn withTree(self: Address, x: u64) Address {
            var r = self;
            r.tree = x;
            return r;
        }
        pub fn withType(self: Address, x: u32) Address {
            var r = self;
            r.kind = x;
            return r;
        }
        pub fn withKeypair(self: Address, x: u32) Address {
            var r = self;
            r.keypair = x;
            return r;
        }
        pub fn withChain(self: Address, x: u32) Address {
            var r = self;
            r.chain = x;
            return r;
        }
        pub fn withHash(self: Address, x: u32) Address {
            var r = self;
            r.hash = x;
            return r;
        }
        pub fn withTreeNode(self: Address, h: u32, i: u32) Address {
            var r = self;
            r.height = h;
            r.index = i;
            return r;
        }
    };

    pub fn hashN(out: []u8, parts: []const []const u8) void {
        var h = std.crypto.hash.sha2.Sha256.init(.{});
        for (parts) |p| h.update(p);
        var full: [32]u8 = undefined;
        h.final(&full);
        @memcpy(out, full[0..@min(out.len, 32)]);
        if (out.len > 32) @memset(out[32..], 0);
    }
    pub fn prfAddress(out: []u8, sk_seed: []const u8, addr: Address) void {
        var a: [32]u8 = undefined;
        addr.encode(&a);
        const parts = [_][]const u8{ sk_seed, &a };
        hashN(out, &parts);
    }
    pub fn thash(out: []u8, pub_seed: []const u8, addr: Address, input: []const u8) void {
        var a: [32]u8 = undefined;
        addr.encode(&a);
        const parts = [_][]const u8{ pub_seed, &a, input };
        hashN(out, &parts);
    }

    pub fn baseW(out: []u8, input: []const u8, w_log2: u3) void {
        var in_idx: usize = 0;
        var total: u16 = 0;
        var bits: u4 = 0;
        for (out) |*d| {
            if (bits < w_log2) {
                total <<= 8;
                if (in_idx < input.len) {
                    total |= input[in_idx];
                    in_idx += 1;
                }
                bits += 8;
            }
            bits -= w_log2;
            d.* = @truncate((total >> @intCast(bits)) & ((@as(u16, 1) << w_log2) - 1));
        }
    }
    pub fn checksum(digits: []const u8, w: u16, len2: usize, out: []u8) void {
        var sum: u64 = 0;
        for (digits) |d| sum += w - 1 - d;
        for (0..@min(len2, out.len)) |i| {
            out[len2 - 1 - i] = @truncate(sum % (w));
            sum /= w;
        }
    }
    pub fn chain(out: []u8, start: []const u8, start_idx: u32, steps: u32, pub_seed: []const u8, addr_in: Address) void {
        @memcpy(out, start[0..@min(out.len, start.len)]);
        var i: u32 = 0;
        while (i < steps) : (i += 1) {
            var tmp: [32]u8 = [_]u8{0} ** 32;
            const addr = addr_in.withHash(start_idx + i);
            thash(tmp[0..out.len], pub_seed, addr, out);
            @memcpy(out, tmp[0..out.len]);
        }
    }
    pub fn wotsLengths(n: usize, w: u16) struct { len1: usize, len2: usize, total: usize } {
        const lg: @TypeOf(@as(usize, 0)) = std.math.log2_int(usize, w);
        const l1 = (8 * n + lg - 1) / lg;
        var v = (w - 1) * l1;
        var l2: usize = 0;
        while (v > 0) {
            l2 += 1;
            v /= w;
        }
        return .{ .len1 = l1, .len2 = l2, .total = l1 + l2 };
    }

    pub fn wotsPkFromSig(pk: []u8, sig: []const u8, msg: []const u8, pub_seed: []const u8, addr: Address, n: usize, w: u16) !void {
        const lens = wotsLengths(n, w);
        if (pk.len < lens.total * n or sig.len < lens.total * n) return error.BufferTooSmall;
        var d: [256]u8 = undefined;
        if (lens.total > d.len) return error.ParameterTooLarge;
        baseW(d[0..lens.len1], msg, @intCast(std.math.log2_int(usize, w)));
        checksum(d[0..lens.len1], w, lens.len2, d[lens.len1..lens.total]);
        for (0..lens.total) |i| chain(
            pk[i * n ..][0..n],
            sig[i * n ..][0..n],
            d[i],
            @intCast(w - 1 - d[i]),
            pub_seed,
            addr.withChain(@intCast(i)),
        );
    }

    pub fn computeRoot(out: []u8, leaf: []const u8, leaf_idx: u32, auth_path: []const u8, height: u32, pub_seed: []const u8, addr_in: Address, n: usize) !void {
        if (out.len < n or leaf.len < n or auth_path.len < @as(usize, height) * n) return error.BufferTooSmall;
        var node: [32]u8 = [_]u8{0} ** 32;
        @memcpy(node[0..n], leaf[0..n]);
        var idx = leaf_idx;
        var h: u32 = 0;
        while (h < height) : (h += 1) {
            var pair: [64]u8 = [_]u8{0} ** 64;
            const auth = auth_path[@as(usize, h) * n ..][0..n];
            if ((idx & 1) == 0) {
                @memcpy(pair[0..n], node[0..n]);
                @memcpy(pair[n .. 2 * n], auth);
            } else {
                @memcpy(pair[0..n], auth);
                @memcpy(pair[n .. 2 * n], node[0..n]);
            }
            const ad = addr_in.withTreeNode(h + 1, idx >> 1);
            thash(node[0..n], pub_seed, ad, pair[0 .. 2 * n]);
            idx >>= 1;
        }
        @memcpy(out[0..n], node[0..n]);
    }

    pub fn forsMessageToIndices(out: []u32, m: []const u8, a: u8) void {
        var bit: usize = 0;
        for (out) |*v| {
            var x: u32 = 0;
            for (0..a) |j| {
                const bi = bit >> 3;
                if (bi < m.len) x |= @as(u32, (m[bi] >> @intCast(bit & 7)) & 1) << @intCast(j);
                bit += 1;
            }
            v.* = x;
        }
    }
    pub fn forsSkGen(out: []u8, sk_seed: []const u8, idx: u32, addr: Address) void {
        prfAddress(out, sk_seed, addr.withTreeNode(0, idx));
    }
    pub fn forsNode(out: []u8, sk_seed: []const u8, pub_seed: []const u8, start: u32, height: u32, addr: Address, n: usize) !void {
        if (out.len < n or n > 32) return error.BufferTooSmall;
        const leaves = @as(u32, 1) << @intCast(height);
        var stack: [32][32]u8 = undefined;
        var heights: [32]u8 = undefined;
        var sp: usize = 0;
        var i: u32 = 0;
        while (i < leaves) : (i += 1) {
            var sk: [32]u8 = [_]u8{0} ** 32;
            forsSkGen(sk[0..n], sk_seed, start + i, addr);
            thash(stack[sp][0..n], pub_seed, addr.withTreeNode(0, start + i), sk[0..n]);
            heights[sp] = 0;
            sp += 1;
            while (sp >= 2 and heights[sp - 1] == heights[sp - 2]) {
                const h = heights[sp - 1];
                var pair: [64]u8 = undefined;
                @memcpy(pair[0..n], stack[sp - 2][0..n]);
                @memcpy(pair[n .. 2 * n], stack[sp - 1][0..n]);
                sp -= 2;
                thash(stack[sp][0..n], pub_seed, addr.withTreeNode(h + 1, (start + i) >> @intCast(h + 1)), pair[0 .. 2 * n]);
                heights[sp] = h + 1;
                sp += 1;
            }
        }
        if (sp != 1) return error.TreeBuildFailure;
        @memcpy(out[0..n], stack[0][0..n]);
    }
};

pub const Wave15QuantDeep = struct {
    pub const Kind = enum { f32, f16, q4_0, q4_1, q5_0, q5_1, q8_0, q2_k, q3_k, q4_k, q5_k, q6_k, q8_k, unknown };
    pub const Layout = struct { block: usize, bytes: usize, name: []const u8 };
    pub fn layout(k: Kind) Layout {
        return switch (k) {
            .f32 => .{ .block = 1, .bytes = 4, .name = "F32" },
            .f16 => .{ .block = 1, .bytes = 2, .name = "F16" },
            .q4_0 => .{ .block = 32, .bytes = 18, .name = "Q4_0" },
            .q4_1 => .{ .block = 32, .bytes = 20, .name = "Q4_1" },
            .q5_0 => .{ .block = 32, .bytes = 22, .name = "Q5_0" },
            .q5_1 => .{ .block = 32, .bytes = 24, .name = "Q5_1" },
            .q8_0 => .{ .block = 32, .bytes = 34, .name = "Q8_0" },
            .q2_k => .{ .block = 256, .bytes = 84, .name = "Q2_K" },
            .q3_k => .{ .block = 256, .bytes = 110, .name = "Q3_K" },
            .q4_k => .{ .block = 256, .bytes = 144, .name = "Q4_K" },
            .q5_k => .{ .block = 256, .bytes = 176, .name = "Q5_K" },
            .q6_k => .{ .block = 256, .bytes = 210, .name = "Q6_K" },
            .q8_k => .{ .block = 256, .bytes = 292, .name = "Q8_K" },
            else => .{ .block = 0, .bytes = 0, .name = "UNKNOWN" },
        };
    }
    pub fn rowBytes(kind: Kind, elements: usize) !usize {
        const l = layout(kind);
        if (l.block == 0) return error.UnsupportedQuant;
        if (elements % l.block != 0) return error.InvalidRowWidth;
        return elements / l.block * l.bytes;
    }
    pub fn fp16(x: u16) f32 {
        return @floatCast(@as(f16, @bitCast(x)));
    }
    pub fn readF16(p: []const u8) f32 {
        return fp16(std.mem.readInt(u16, p[0..2], .little));
    }

    pub fn dequantQ4_0(block: []const u8, out: []f32) !void {
        if (block.len < 18 or out.len < 32) return error.BufferTooSmall;
        const d = readF16(block[0..2]);
        for (0..16) |i| {
            const q = block[2 + i];
            out[i] = d * @as(f32, @floatFromInt(@as(i8, @intCast(q & 15)) - 8));
            out[i + 16] = d * @as(f32, @floatFromInt(@as(i8, @intCast(q >> 4)) - 8));
        }
    }
    pub fn dequantQ4_1(block: []const u8, out: []f32) !void {
        if (block.len < 20 or out.len < 32) return error.BufferTooSmall;
        const d = readF16(block[0..2]);
        const m = readF16(block[2..4]);
        for (0..16) |i| {
            const q = block[4 + i];
            out[i] = d * @as(f32, @floatFromInt(q & 15)) + m;
            out[i + 16] = d * @as(f32, @floatFromInt(q >> 4)) + m;
        }
    }
    pub fn dequantQ5_0(block: []const u8, out: []f32) !void {
        if (block.len < 22 or out.len < 32) return error.BufferTooSmall;
        const d = readF16(block[0..2]);
        const qh = std.mem.readInt(u32, block[2..6], .little);
        for (0..16) |i| {
            const q = block[6 + i];
            const a = (q & 15) | @as(u8, @truncate(((qh >> @intCast(i)) & 1) << 4));
            const b = (q >> 4) | @as(u8, @truncate(((qh >> @intCast(i + 16)) & 1) << 4));
            out[i] = d * @as(f32, @floatFromInt(@as(i8, @intCast(a)) - 16));
            out[i + 16] = d * @as(f32, @floatFromInt(@as(i8, @intCast(b)) - 16));
        }
    }
    pub fn dequantQ5_1(block: []const u8, out: []f32) !void {
        if (block.len < 24 or out.len < 32) return error.BufferTooSmall;
        const d = readF16(block[0..2]);
        const m = readF16(block[2..4]);
        const qh = std.mem.readInt(u32, block[4..8], .little);
        for (0..16) |i| {
            const q = block[8 + i];
            const a = (q & 15) | @as(u8, @truncate(((qh >> @intCast(i)) & 1) << 4));
            const b = (q >> 4) | @as(u8, @truncate(((qh >> @intCast(i + 16)) & 1) << 4));
            out[i] = d * @as(f32, @floatFromInt(a)) + m;
            out[i + 16] = d * @as(f32, @floatFromInt(b)) + m;
        }
    }
    pub fn dequantQ8_0(block: []const u8, out: []f32) !void {
        if (block.len < 34 or out.len < 32) return error.BufferTooSmall;
        const d = readF16(block[0..2]);
        for (0..32) |i| out[i] = d * @as(f32, @floatFromInt(@as(i8, @bitCast(block[2 + i]))));
    }

    fn scaleMinK4(j: usize, q: []const u8) struct { d: u8, m: u8 } {
        if (j < 4) return .{ .d = q[j] & 63, .m = q[j + 4] & 63 };
        return .{ .d = (q[j + 4] & 15) | ((q[j - 4] >> 6) << 4), .m = (q[j + 4] >> 4) | ((q[j] >> 6) << 4) };
    }
    pub fn dequantQ4K(block: []const u8, out: []f32) !void {
        if (block.len < 144 or out.len < 256) return error.BufferTooSmall;
        const d = readF16(block[0..2]);
        const dm = readF16(block[2..4]);
        const scales = block[4..16];
        const qs = block[16..144];
        var qi: usize = 0;
        var oi: usize = 0;
        for (0..4) |g| {
            _ = g;
            const a = scaleMinK4((oi / 32), scales);
            const b = scaleMinK4((oi / 32) + 1, scales);
            for (0..32) |l| out[oi + l] = d * @as(f32, @floatFromInt(a.d)) * @as(f32, @floatFromInt(qs[qi + l] & 15)) - dm * @as(f32, @floatFromInt(a.m));
            for (0..32) |l| out[oi + 32 + l] = d * @as(f32, @floatFromInt(b.d)) * @as(f32, @floatFromInt(qs[qi + l] >> 4)) - dm * @as(f32, @floatFromInt(b.m));
            qi += 32;
            oi += 64;
        }
    }
    pub fn dequantQ5K(block: []const u8, out: []f32) !void {
        if (block.len < 176 or out.len < 256) return error.BufferTooSmall;
        const d = readF16(block[0..2]);
        const dm = readF16(block[2..4]);
        const scales = block[4..16];
        const qh = block[16..48];
        const qs = block[48..176];
        var qi: usize = 0;
        var oi: usize = 0;
        var mask1: u8 = 1;
        var mask2: u8 = 2;
        for (0..4) |_| {
            const a = scaleMinK4(oi / 32, scales);
            const b = scaleMinK4(oi / 32 + 1, scales);
            for (0..32) |l| {
                const q = (qs[qi + l] & 15) + if ((qh[l] & mask1) != 0) @as(u8, 16) else 0;
                out[oi + l] = d * @as(f32, @floatFromInt(a.d)) * @as(f32, @floatFromInt(q)) - dm * @as(f32, @floatFromInt(a.m));
            }
            for (0..32) |l| {
                const q = (qs[qi + l] >> 4) + if ((qh[l] & mask2) != 0) @as(u8, 16) else 0;
                out[oi + 32 + l] = d * @as(f32, @floatFromInt(b.d)) * @as(f32, @floatFromInt(q)) - dm * @as(f32, @floatFromInt(b.m));
            }
            qi += 32;
            oi += 64;
            mask1 <<= 2;
            mask2 <<= 2;
        }
    }
    pub fn dequantQ6K(block: []const u8, out: []f32) !void {
        if (block.len < 210 or out.len < 256) return error.BufferTooSmall;
        const ql = block[0..128];
        const qh = block[128..192];
        const scales = block[192..208];
        const d = readF16(block[208..210]);
        for (0..16) |g| {
            const sc = @as(i8, @bitCast(scales[g]));
            for (0..16) |j| {
                const idx = g * 16 + j;
                const lo = if ((idx & 16) == 0) ql[(idx & 15) + (idx / 32) * 32] & 15 else ql[(idx & 15) + (idx / 32) * 32] >> 4;
                const hi = (qh[(idx & 31) + (idx / 128) * 32] >> @intCast((idx / 32 & 3) * 2)) & 3;
                const q: i8 = @bitCast(@as(u8, lo | (hi << 4)));
                out[idx] = d * @as(f32, @floatFromInt(sc)) * @as(f32, @floatFromInt(q));
            }
        }
    }

    pub fn dequantRow(kind: Kind, src: []const u8, dst: []f32) !void {
        const l = layout(kind);
        if (l.block == 0) return error.UnsupportedQuant;
        if (dst.len % l.block != 0) return error.InvalidRowWidth;
        var si: usize = 0;
        var di: usize = 0;
        while (di < dst.len) : (di += l.block) {
            const b = src[si..][0..l.bytes];
            switch (kind) {
                .q4_0 => try dequantQ4_0(b, dst[di..][0..32]),
                .q4_1 => try dequantQ4_1(b, dst[di..][0..32]),
                .q5_0 => try dequantQ5_0(b, dst[di..][0..32]),
                .q5_1 => try dequantQ5_1(b, dst[di..][0..32]),
                .q8_0 => try dequantQ8_0(b, dst[di..][0..32]),
                .q4_k => try dequantQ4K(b, dst[di..][0..256]),
                .q5_k => try dequantQ5K(b, dst[di..][0..256]),
                .q6_k => try dequantQ6K(b, dst[di..][0..256]),
                else => return error.UnsupportedQuant,
            }
            si += l.bytes;
        }
    }
    pub fn dotRow(kind: Kind, src: []const u8, x: []const f32, scratch: []f32) !f32 {
        if (scratch.len < x.len) return error.BufferTooSmall;
        try dequantRow(kind, src, scratch[0..x.len]);
        var s: f32 = 0;
        for (x, scratch[0..x.len]) |a, b| s += a * b;
        return s;
    }
};
