pub const Wave15Runtime = struct {
    pub const SamplerConfig = struct { temperature: f32 = 0.8, top_k: usize = 40, top_p: f32 = 0.95, min_p: f32 = 0.0, repetition_penalty: f32 = 1.0, frequency_penalty: f32 = 0, presence_penalty: f32 = 0, seed: u64 = 0x123456789abcdef0 };
    pub const Candidate = struct { token: u32, logit: f32, prob: f32 = 0, count: u32 = 0 };
    pub const Rng = struct {
        s: u64,
        pub fn init(seed: u64) Rng {
            return .{ .s = if (seed == 0) 0x2545f4914f6cdd1d else seed };
        }
        pub fn next(self: *Rng) u64 {
            var x = self.s;
            x ^= x >> 12;
            x ^= x << 25;
            x ^= x >> 27;
            self.s = x;
            return x *% 0x2545f4914f6cdd1d;
        }
        pub fn unit(self: *Rng) f64 {
            return @as(f64, @floatFromInt(self.next() >> 11)) / 9007199254740992.0;
        }
    };
    fn sortByLogit(c: []Candidate) void {
        var i: usize = 1;
        while (i < c.len) : (i += 1) {
            const x = c[i];
            var j = i;
            while (j > 0 and c[j - 1].logit < x.logit) : (j -= 1) c[j] = c[j - 1];
            c[j] = x;
        }
    }
    pub fn applyPenalties(c: []Candidate, cfg: SamplerConfig) void {
        for (c) |*v| {
            if (v.count > 0) {
                if (cfg.repetition_penalty != 1) {
                    v.logit = if (v.logit < 0) v.logit * cfg.repetition_penalty else v.logit / cfg.repetition_penalty;
                }
                v.logit -= cfg.frequency_penalty * @as(f32, @floatFromInt(v.count));
                v.logit -= cfg.presence_penalty;
            }
        }
    }
    pub fn softmax(c: []Candidate, temp: f32) void {
        if (c.len == 0) return;
        const t = @max(temp, 0.000001);
        var m = c[0].logit;
        for (c[1..]) |v| m = @max(m, v.logit);
        var sum: f64 = 0;
        for (c) |*v| {
            const p = @exp(@as(f64, v.logit - m) / t);
            v.prob = @floatCast(p);
            sum += p;
        }
        if (sum > 0) {
            for (c) |*v| {
                v.prob = @floatCast(@as(f64, v.prob) / sum);
            }
        }
    }
    pub fn truncateTopK(c: []Candidate, k: usize) []Candidate {
        sortByLogit(c);
        return c[0..@min(k, c.len)];
    }
    pub fn truncateTopP(c: []Candidate, p: f32) []Candidate {
        sortByLogit(c);
        var s: f32 = 0;
        for (c, 0..) |v, i| {
            s += v.prob;
            if (s >= p) return c[0 .. i + 1];
        }
        return c;
    }
    pub fn truncateMinP(c: []Candidate, p: f32) []Candidate {
        if (c.len == 0) return c;
        var maxp: f32 = 0;
        for (c) |v| maxp = @max(maxp, v.prob);
        var w: usize = 0;
        for (c) |v| if (v.prob >= maxp * p) {
            c[w] = v;
            w += 1;
        };
        return c[0..w];
    }
    pub fn sample(c: []Candidate, cfg: SamplerConfig, rng: *Rng) !u32 {
        if (c.len == 0) return error.EmptyDistribution;
        applyPenalties(c, cfg);
        softmax(c, cfg.temperature);
        var work = truncateTopK(c, if (cfg.top_k == 0) c.len else cfg.top_k);
        work = truncateTopP(work, cfg.top_p);
        work = truncateMinP(work, cfg.min_p);
        var total: f64 = 0;
        for (work) |v| total += v.prob;
        if (total <= 0) return work[0].token;
        var r = rng.unit() * total;
        for (work) |v| {
            r -= v.prob;
            if (r <= 0) return v.token;
        }
        return work[work.len - 1].token;
    }

    pub const Wave20StopMatcher = struct {
        allocator: std.mem.Allocator,
        patterns: std.ArrayList([]u8),
        max_len: usize = 0,
        pub fn init(a: std.mem.Allocator) Wave20StopMatcher {
            return .{ .allocator = a, .patterns = std.ArrayList([]u8).empty };
        }
        pub fn deinit(self: *Wave20StopMatcher) void {
            for (self.patterns.items) |p| self.allocator.free(p);
            self.patterns.deinit(self.allocator);
        }
        pub fn add(self: *Wave20StopMatcher, p: []const u8) !void {
            const d = try self.allocator.dupe(u8, p);
            try self.patterns.append(self.allocator, d);
            self.max_len = @max(self.max_len, p.len);
        }
        pub fn suffixMatch(self: *const Wave20StopMatcher, text: []const u8) ?usize {
            for (self.patterns.items, 0..) |p, i| if (text.len >= p.len and std.mem.eql(u8, text[text.len - p.len ..], p)) return i;
            return null;
        }
    };

    pub const Utf8Accumulator = struct {
        buf: [4]u8 = [_]u8{0} ** 4,
        len: u3 = 0,
        pub fn push(self: *Utf8Accumulator, b: u8, out: []u8) !usize {
            if (self.len >= 4) return error.InvalidUtf8;
            self.buf[self.len] = b;
            self.len += 1;
            const need = utf8Need(self.buf[0]);
            if (need == 0) {
                self.len = 0;
                return error.InvalidUtf8;
            }
            if (self.len < need) return 0;
            if (self.len > need) {
                self.len = 0;
                return error.InvalidUtf8;
            }
            @memcpy(out[0..need], self.buf[0..need]);
            self.len = 0;
            return need;
        }
        fn utf8Need(b: u8) u3 {
            return if (b < 0x80) 1 else if ((b & 0xe0) == 0xc0) 2 else if ((b & 0xf0) == 0xe0) 3 else if ((b & 0xf8) == 0xf0) 4 else 0;
        }
    };

    pub const TokenCounter = struct {
        table: std.AutoHashMap(u32, u32),
        allocator: std.mem.Allocator,
        pub fn init(a: std.mem.Allocator) TokenCounter {
            return .{ .table = std.AutoHashMap(u32, u32).init(a), .allocator = a };
        }
        pub fn deinit(self: *TokenCounter) void {
            self.table.deinit();
        }
        pub fn add(self: *TokenCounter, t: u32) !void {
            const g = try self.table.getOrPut(t);
            if (!g.found_existing) g.value_ptr.* = 0;
            g.value_ptr.* += 1;
        }
        pub fn count(self: *const TokenCounter, t: u32) u32 {
            return self.table.get(t) orelse 0;
        }
    };

    pub const GenerationStats = struct {
        prompt_tokens: u64 = 0,
        generated_tokens: u64 = 0,
        prefill_ns: u64 = 0,
        decode_ns: u64 = 0,
        bytes_out: u64 = 0,
        pub fn promptTps(self: GenerationStats) f64 {
            return if (self.prefill_ns == 0) 0 else @as(f64, @floatFromInt(self.prompt_tokens)) * 1e9 / @as(f64, @floatFromInt(self.prefill_ns));
        }
        pub fn decodeTps(self: GenerationStats) f64 {
            return if (self.decode_ns == 0) 0 else @as(f64, @floatFromInt(self.generated_tokens)) * 1e9 / @as(f64, @floatFromInt(self.decode_ns));
        }
    };

    pub const JournalRecordKind = enum(u8) { session_start = 1, user = 2, assistant = 3, token = 4, checkpoint = 5, error_event = 6 };
    pub const JournalHeader = packed struct { magic: u32 = 0x4e415a41, version: u16 = 1, kind: u8 = 0, reserved: u8 = 0, length: u32 = 0, crc: u32 = 0 };
    pub fn crc32(bytes: []const u8) u32 {
        var crc: u32 = 0xffffffff;
        for (bytes) |b| {
            crc ^= b;
            for (0..8) |_| crc = if ((crc & 1) != 0) (crc >> 1) ^ 0xedb88320 else crc >> 1;
        }
        return ~crc;
    }
    pub fn encodeJournalHeader(kind: JournalRecordKind, payload: []const u8) JournalHeader {
        return .{ .kind = @intFromEnum(kind), .length = @intCast(payload.len), .crc = crc32(payload) };
    }
    pub fn validateJournalHeader(h: JournalHeader, payload: []const u8) bool {
        return h.magic == 0x4e415a41 and h.version == 1 and h.length == payload.len and h.crc == crc32(payload);
    }

    pub const RingEvents = struct {
        const cap = 256;
        items: [cap]Event = undefined,
        head: usize = 0,
        tail: usize = 0,
        count: usize = 0,
        pub const Event = struct { kind: JournalRecordKind, value: u64, timestamp_ns: i128 };
        pub fn push(self: *RingEvents, e: Event) !void {
            if (self.count == cap) return error.Full;
            self.items[self.tail] = e;
            self.tail = (self.tail + 1) % cap;
            self.count += 1;
        }
        pub fn pop(self: *RingEvents) ?Event {
            if (self.count == 0) return null;
            const e = self.items[self.head];
            self.head = (self.head + 1) % cap;
            self.count -= 1;
            return e;
        }
    };
};

pub const Wave15Audit = struct {
    pub const Severity = enum { info, warning, fatal };
    pub const Finding = struct { code: []const u8, severity: Severity, message: []const u8 };
    pub const Report = struct {
        findings: [128]Finding = undefined,
        count: usize = 0,
        pub fn add(self: *Report, f: Finding) void {
            if (self.count < self.findings.len) {
                self.findings[self.count] = f;
                self.count += 1;
            }
        }
        pub fn fatalCount(self: *const Report) usize {
            var n: usize = 0;
            for (self.findings[0..self.count]) |f| {
                if (f.severity == .fatal) n += 1;
            }
            return n;
        }
        pub fn ok(self: *const Report) bool {
            return self.fatalCount() == 0;
        }
    };
    pub const TensorFact = struct { name: []const u8, dims: [4]u64, ndims: u8, kind: Wave15QuantDeep.Kind, offset: u64, bytes: u64 };
    pub fn validateTensor(f: TensorFact, file_size: u64, data_start: u64, r: *Report) void {
        if (f.ndims == 0 or f.ndims > 4) r.add(.{ .code = "TENSOR_NDIMS", .severity = .fatal, .message = "invalid tensor rank" });
        for (0..f.ndims) |i| {
            if (f.dims[i] == 0) r.add(.{ .code = "TENSOR_ZERO", .severity = .fatal, .message = "zero-sized dimension" });
        }
        if (f.offset + f.bytes > file_size - data_start) r.add(.{ .code = "TENSOR_RANGE", .severity = .fatal, .message = "tensor exceeds file" });
        if (Wave15QuantDeep.layout(f.kind).block == 0) r.add(.{ .code = "TENSOR_QUANT", .severity = .fatal, .message = "unsupported quantization" });
    }
    pub fn validateModelFacts(facts: []const TensorFact, file_size: u64, data_start: u64) Report {
        var r = Report{};
        for (facts) |f| validateTensor(f, file_size, data_start, &r);
        return r;
    }

    pub const CryptoState = enum { catalog_only, partial, implemented_unverified, implemented, vector_verified, deprecated };
    pub const Capability = struct { name: []const u8, state: CryptoState, standard: []const u8 };
    pub const capabilities = [_]Capability{
        .{ .name = "ML-KEM-512", .state = .implemented_unverified, .standard = "FIPS 203" }, .{ .name = "ML-KEM-768", .state = .implemented_unverified, .standard = "FIPS 203" }, .{ .name = "ML-KEM-1024", .state = .implemented_unverified, .standard = "FIPS 203" },
        .{ .name = "ML-DSA-44", .state = .partial, .standard = "FIPS 204" },                 .{ .name = "ML-DSA-65", .state = .partial, .standard = "FIPS 204" },                 .{ .name = "ML-DSA-87", .state = .partial, .standard = "FIPS 204" },
        .{ .name = "SLH-DSA", .state = .partial, .standard = "FIPS 205" },                   .{ .name = "FN-DSA-512", .state = .partial, .standard = "FIPS 206/draft" },          .{ .name = "FN-DSA-1024", .state = .partial, .standard = "FIPS 206/draft" },
        .{ .name = "HQC-128", .state = .partial, .standard = "NIST selected" },              .{ .name = "HQC-192", .state = .partial, .standard = "NIST selected" },              .{ .name = "HQC-256", .state = .partial, .standard = "NIST selected" },
    };
    pub fn findCapability(name: []const u8) ?Capability {
        for (capabilities) |c| if (std.mem.eql(u8, c.name, name)) return c;
        return null;
    }

    pub const KatStatus = enum { not_run, pass, fail, unsupported };
    pub const KatResult = struct { name: []const u8, status: KatStatus, detail: []const u8 };
    pub const KatSuite = struct {
        results: [64]KatResult = undefined,
        count: usize = 0,
        pub fn push(self: *KatSuite, r: KatResult) void {
            if (self.count < self.results.len) {
                self.results[self.count] = r;
                self.count += 1;
            }
        }
        pub fn allPassed(self: *const KatSuite) bool {
            for (self.results[0..self.count]) |r| if (r.status != .pass) return false;
            return self.count > 0;
        }
    };

    pub fn constantTimeEq(a: []const u8, b: []const u8) bool {
        if (a.len != b.len) return false;
        var d: u8 = 0;
        for (a, b) |x, y| d |= x ^ y;
        return d == 0;
    }
    pub fn wipe(bytes: []volatile u8) void {
        @memset(bytes, 0);
    }
    pub fn overlap(a_start: usize, a_len: usize, b_start: usize, b_len: usize) bool {
        return a_start < b_start + b_len and b_start < a_start + a_len;
    }

    pub const SecureArena = struct {
        backing: []u8,
        used: usize = 0,
        pub fn init(buf: []u8) SecureArena {
            @memset(buf, 0);
            return .{ .backing = buf };
        }
        pub fn alloc(self: *SecureArena, n: usize, alignment: usize) ![]u8 {
            const start = std.mem.alignForward(usize, self.used, @max(alignment, 1));
            if (start + n > self.backing.len) return error.OutOfMemory;
            self.used = start + n;
            return self.backing[start..self.used];
        }
        pub fn reset(self: *SecureArena) void {
            const v: []volatile u8 = self.backing[0..self.used];
            wipe(v);
            self.used = 0;
        }
    };
};
