pub const Wave15Tokenizer = struct {
    pub const Special = struct { text: []const u8, id: u32 };
    pub const Segment = struct { start: usize, end: usize, special_id: ?u32 = null };
    pub fn findNextSpecial(text: []const u8, start: usize, specials: []const Special) ?Segment {
        var best: ?Segment = null;
        for (specials) |sp| {
            if (std.mem.indexOfPos(u8, text, start, sp.text)) |i| {
                if (best == null or i < best.?.start) best = .{ .start = i, .end = i + sp.text.len, .special_id = sp.id };
            }
        }
        return best;
    }
    pub fn segment(text: []const u8, specials: []const Special, out: []Segment) !usize {
        var pos: usize = 0;
        var n: usize = 0;
        while (pos < text.len) {
            const s = findNextSpecial(text, pos, specials);
            if (s) |sp| {
                if (sp.start > pos) {
                    if (n >= out.len) return error.BufferTooSmall;
                    out[n] = .{ .start = pos, .end = sp.start };
                    n += 1;
                }
                if (n >= out.len) return error.BufferTooSmall;
                out[n] = sp;
                n += 1;
                pos = sp.end;
            } else {
                if (n >= out.len) return error.BufferTooSmall;
                out[n] = .{ .start = pos, .end = text.len };
                n += 1;
                break;
            }
        }
        return n;
    }
    pub fn isWhitespace(cp: u21) bool {
        return cp == ' ' or cp == '\n' or cp == '\r' or cp == '\t' or cp == 0x0b or cp == 0x0c or cp == 0x85 or cp == 0xa0;
    }
    pub fn isAsciiPunct(cp: u21) bool {
        return cp < 128 and ((cp >= 33 and cp <= 47) or (cp >= 58 and cp <= 64) or (cp >= 91 and cp <= 96) or (cp >= 123 and cp <= 126));
    }
    pub fn utf8SeqLen(b: u8) usize {
        return if (b < 0x80) 1 else if ((b & 0xe0) == 0xc0) 2 else if ((b & 0xf0) == 0xe0) 3 else if ((b & 0xf8) == 0xf0) 4 else 1;
    }
    pub fn byteFallbackName(b: u8, out: *[6]u8) []const u8 {
        const hex = "0123456789ABCDEF";
        out.* = .{ '<', '0', 'x', hex[b >> 4], hex[b & 15], '>' };
        return out;
    }
    pub fn longestTokenPrefix(text: []const u8, tokens: []const []const u8) ?usize {
        var best: ?usize = null;
        var bestlen: usize = 0;
        for (tokens, 0..) |t, i| if (t.len <= text.len and t.len > bestlen and std.mem.eql(u8, text[0..t.len], t)) {
            best = i;
            bestlen = t.len;
        };
        return best;
    }
    pub const Merge = struct { left: u32, right: u32, rank: u32, result: u32 };
    pub fn bestMerge(ids: []const u32, merges: []const Merge) ?struct { pos: usize, m: Merge } {
        if (ids.len < 2) return null;
        var best: ?struct { pos: usize, m: Merge } = null;
        for (0..ids.len - 1) |i| for (merges) |m| if (m.left == ids[i] and m.right == ids[i + 1]) {
            if (best == null or m.rank < best.?.m.rank) best = .{ .pos = i, .m = m };
        };
        return best;
    }
    pub fn applyMerges(ids: []u32, len_in: usize, merges: []const Merge) usize {
        var len = len_in;
        while (true) {
            const b = bestMerge(ids[0..len], merges) orelse break;
            ids[b.pos] = b.m.result;
            var j = b.pos + 1;
            while (j + 1 < len) : (j += 1) ids[j] = ids[j + 1];
            len -= 1;
        }
        return len;
    }
};
