pub const FifteenKCheckpoint = struct {
    pub const target_lines: usize = 15000;
    pub const long_term_target_lines: usize = 50000;
    pub const single_source = true;
    pub const foreign_linkage = false;
    pub const cryptography_policy = "fail closed until exact vectors pass";
    pub fn assertInvariants(lines: usize) !void {
        if (lines < target_lines) return error.CheckpointNotReached;
        if (!single_source) return error.SplitSourceForbidden;
        if (foreign_linkage) return error.ForeignLinkageForbidden;
    }
};

