// ============================================================================
// WAVE 20: deeper pure-Zig cryptography, GGUF/runtime, and persistence implementations
// ============================================================================

pub const Wave20HqcKem = struct {
    pub const Params = struct {
        name: []const u8,
        n: usize,
        n1: usize,
        n2: usize,
        omega: usize,
        omega_r: usize,
        omega_e: usize,
        security_bits: u16,
        seed_bytes: usize,
        shared_secret_bytes: usize,
    };
    pub const sets = [_]Params{
        .{ .name = "HQC-128", .n = 17669, .n1 = 46, .n2 = 384, .omega = 66, .omega_r = 75, .omega_e = 75, .security_bits = 128, .seed_bytes = 40, .shared_secret_bytes = 64 },
        .{ .name = "HQC-192", .n = 35851, .n1 = 56, .n2 = 640, .omega = 100, .omega_r = 114, .omega_e = 114, .security_bits = 192, .seed_bytes = 40, .shared_secret_bytes = 64 },
        .{ .name = "HQC-256", .n = 57637, .n1 = 90, .n2 = 640, .omega = 131, .omega_r = 149, .omega_e = 149, .security_bits = 256, .seed_bytes = 40, .shared_secret_bytes = 64 },
    };

    pub const Domain = enum(u8) { keygen = 1, encaps = 2, decaps = 3, theta = 4, shared = 5, fallback = 6 };
    pub const SeedMaterial = struct { sk_seed: [40]u8, pk_seed: [40]u8, sigma: [40]u8 };
    pub const CiphertextView = struct { u: []const u8, v: []const u8, salt: []const u8 };

    pub fn bytesForBits(bits: usize) usize {
        return (bits + 7) / 8;
    }
    pub fn publicKeyBytes(ps: Params) usize {
        return 40 + bytesForBits(ps.n);
    }
    pub fn secretKeyBytes(ps: Params) usize {
        return 40 + 40 + publicKeyBytes(ps);
    }
    pub fn ciphertextBytes(ps: Params) usize {
        return bytesForBits(ps.n) + ps.n1 * ps.n2 / 8 + 16;
    }

    pub fn hashDomain(out: []u8, domain: Domain, inputs: anytype) void {
        var h = std.crypto.hash.sha3.Sha3_512.init(.{});
        const d = [_]u8{@intFromEnum(domain)};
        h.update(&d);
        inline for (inputs) |x| h.update(x);
        var full: [64]u8 = undefined;
        h.final(&full);
        const n = @min(out.len, full.len);
        @memcpy(out[0..n], full[0..n]);
        if (out.len > n) {
            var ctr: u32 = 1;
            var off = n;
            while (off < out.len) : (ctr += 1) {
                var x = std.crypto.hash.sha3.Sha3_512.init(.{});
                x.update(&d);
                x.update(&full);
                var c: [4]u8 = undefined;
                std.mem.writeInt(u32, &c, ctr, .little);
                x.update(&c);
                var b: [64]u8 = undefined;
                x.final(&b);
                const m = @min(b.len, out.len - off);
                @memcpy(out[off .. off + m], b[0..m]);
                off += m;
            }
        }
    }

    pub fn deriveSeeds(master: []const u8) SeedMaterial {
        var r: SeedMaterial = undefined;
        hashDomain(&r.sk_seed, .keygen, .{ master, "sk" });
        hashDomain(&r.pk_seed, .keygen, .{ master, "pk" });
        hashDomain(&r.sigma, .keygen, .{ master, "sigma" });
        return r;
    }

    pub fn sampleSparsePositions(out: []u32, seed: []const u8, modulus: u32) !void {
        if (out.len > modulus) return error.WeightTooLarge;
        var shake = std.crypto.hash.sha3.Shake256.init(.{});
        shake.update(seed);
        var buf: [4096]u8 = undefined;
        var pos: usize = buf.len;
        var filled: usize = 0;
        while (filled < out.len) {
            if (pos + 4 > buf.len) {
                shake.squeeze(&buf);
                pos = 0;
            }
            const x = std.mem.readInt(u32, buf[pos..][0..4], .little) % modulus;
            pos += 4;
            var dup = false;
            for (out[0..filled]) |v| if (v == x) {
                dup = true;
                break;
            };
            if (!dup) {
                out[filled] = x;
                filled += 1;
            }
        }
    }

    pub fn bytesToWords(dst: []u64, src: []const u8, nbits: usize) void {
        @memset(dst, 0);
        const n = @min(src.len, bytesForBits(nbits));
        for (0..n) |i| dst[i >> 3] |= @as(u64, src[i]) << @intCast((i & 7) * 8);
        Wave15HqcCore.clearUnused(dst, nbits);
    }
    pub fn wordsToBytes(dst: []u8, src: []const u64, nbits: usize) void {
        @memset(dst, 0);
        const n = @min(dst.len, bytesForBits(nbits));
        for (0..n) |i| dst[i] = @truncate(src[i >> 3] >> @intCast((i & 7) * 8));
        if ((nbits & 7) != 0 and n > 0) dst[n - 1] &= @as(u8, 0xff) >> @intCast(8 - (nbits & 7));
    }

    pub fn encodeSparse(dst: []u64, positions: []const u32, nbits: usize) void {
        Wave15HqcCore.zero(dst);
        for (positions) |x| if (x < nbits) Wave15HqcCore.setBit(dst, x, 1);
        Wave15HqcCore.clearUnused(dst, nbits);
    }
    pub fn syndrome(dst: []u64, h: []const u64, e: []const u32, nbits: usize, scratch: []u64) void {
        Wave15HqcCore.cyclicMulSparse(dst, h, e, nbits, scratch);
    }

    pub fn theta(out: []u8, m: []const u8, pk: []const u8) void {
        hashDomain(out, .theta, .{ m, pk });
    }
    pub fn sharedSecret(out: []u8, m: []const u8, ct: []const u8) void {
        hashDomain(out, .shared, .{ m, ct });
    }
    pub fn fallbackSecret(out: []u8, sigma: []const u8, ct: []const u8) void {
        hashDomain(out, .fallback, .{ sigma, ct });
    }

    pub fn constantTimeSelect(out: []u8, a: []const u8, b: []const u8, choose_b: bool) void {
        const mask: u8 = 0 -% @as(u8, @intFromBool(choose_b));
        const n = @min(out.len, @min(a.len, b.len));
        for (0..n) |i| out[i] = (a[i] & ~mask) | (b[i] & mask);
    }

    pub fn ciphertextSplit(ps: Params, ct: []const u8) !CiphertextView {
        const ub = bytesForBits(ps.n);
        const vb = ps.n1 * ps.n2 / 8;
        if (ct.len < ub + vb + 16) return error.CiphertextTooShort;
        return .{ .u = ct[0..ub], .v = ct[ub .. ub + vb], .salt = ct[ub + vb .. ub + vb + 16] };
    }

    pub fn validateParams(ps: Params) bool {
        return ps.n > 0 and ps.n1 > 0 and ps.n2 > 0 and ps.omega > 0 and ps.omega_r > 0 and ps.omega_e > 0 and ps.seed_bytes == 40;
    }
    pub fn status() []const u8 {
        return "HQC arithmetic/transcript partial implementation present; standardized decoder/KAT gate still required";
    }
};

pub const Wave20FnDsa = struct {
    pub const q: i32 = 12289;
    pub const Header = struct { logn: u8, nonce_len: u8, payload_len: u16 };
    pub const Basis = struct { f: []const i16, g: []const i16, F: []const i16, G: []const i16 };

    pub fn negacyclicMul(dst: []i32, a: anytype, b: anytype) void {
        @memset(dst, 0);
        const n = dst.len;
        for (0..@min(n, a.len)) |i| {
            for (0..@min(n, b.len)) |j| {
                const k = i + j;
                const prod: i64 = @as(i64, a[i]) * @as(i64, b[j]);
                if (k < n) {
                    dst[k] = Wave15FnDsaCore.modQ(@as(i64, dst[k]) + prod);
                } else {
                    dst[k - n] = Wave15FnDsaCore.modQ(@as(i64, dst[k - n]) - prod);
                }
            }
        }
    }
    pub fn ntruRelation(f: []const i16, g: []const i16, F: []const i16, G: []const i16, scratch1: []i32, scratch2: []i32) bool {
        if (scratch1.len != scratch2.len) return false;
        negacyclicMul(scratch1, f, G);
        negacyclicMul(scratch2, g, F);
        for (0..scratch1.len) |i| {
            const want = if (i == 0) q else 0;
            if (scratch1[i] - scratch2[i] != want and Wave15FnDsaCore.centerQ(scratch1[i] - scratch2[i]) != Wave15FnDsaCore.centerQ(want)) return false;
        }
        return true;
    }
    pub fn publicKeyFromFg(dst: []i32, f: []const i16, g: []const i16) bool {
        if (dst.len != f.len or f.len != g.len) return false;
        const inv0 = Wave15FnDsaCore.invQ(Wave15FnDsaCore.modQ(f[0]));
        if (inv0 == 0) return false;
        for (0..dst.len) |i| dst[i] = Wave15FnDsaCore.mulQ(Wave15FnDsaCore.modQ(g[i]), inv0);
        return true;
    }
    pub fn hashToPoint(dst: []i32, nonce: []const u8, msg: []const u8) void {
        var x = std.crypto.hash.sha3.Shake256.init(.{});
        x.update(nonce);
        x.update(msg);
        var buf: [512]u8 = undefined;
        var p: usize = buf.len;
        for (dst) |*d| {
            while (true) {
                if (p + 2 > buf.len) {
                    x.squeeze(&buf);
                    p = 0;
                }
                const w = std.mem.readInt(u16, buf[p..][0..2], .little);
                p += 2;
                if (w < 5 * q) {
                    d.* = @intCast(w % @as(u16, @intCast(q)));
                    break;
                }
            }
        }
    }
    pub fn signatureEquation(dst_s1: []i16, h: []const i32, s2: []const i16, c: []const i32, scratch: []i32) bool {
        if (dst_s1.len != h.len or h.len != s2.len or s2.len != c.len or scratch.len < h.len) return false;
        negacyclicMul(scratch[0..h.len], h, s2);
        for (0..h.len) |i| dst_s1[i] = @intCast(Wave15FnDsaCore.centerQ(c[i] - scratch[i]));
        return true;
    }
    pub fn verify(h: []const i32, nonce: []const u8, msg: []const u8, s2: []const i16, bound: u64, s1: []i16, c: []i32, scratch: []i32) bool {
        if (c.len < h.len or s1.len < h.len) return false;
        hashToPoint(c[0..h.len], nonce, msg);
        if (!signatureEquation(s1[0..h.len], h, s2, c[0..h.len], scratch)) return false;
        return Wave15FnDsaCore.isShort(s1[0..h.len], s2, bound);
    }

    pub fn zigzagEncode(x: i32) u32 {
        return @bitCast((x << 1) ^ (x >> 31));
    }
    pub fn zigzagDecode(x: u32) i32 {
        const y: i32 = @bitCast(x >> 1);
        return y ^ -@as(i32, @intCast(x & 1));
    }
    pub fn writeVarint(out: []u8, x_in: u32) !usize {
        var x = x_in;
        var n: usize = 0;
        while (true) {
            if (n >= out.len) return error.BufferTooSmall;
            var b: u8 = @truncate(x & 0x7f);
            x >>= 7;
            if (x != 0) b |= 0x80;
            out[n] = b;
            n += 1;
            if (x == 0) return n;
        }
    }
    pub fn readVarint(src: []const u8) !struct { value: u32, used: usize } {
        var x: u32 = 0;
        var shift: u5 = 0;
        for (src, 0..) |b, i| {
            x |= @as(u32, b & 0x7f) << shift;
            if ((b & 0x80) == 0) return .{ .value = x, .used = i + 1 };
            if (shift >= 28) return error.MalformedVarint;
            shift += 7;
        }
        return error.Truncated;
    }
    pub fn compressSigned(out: []u8, coeffs: []const i16) !usize {
        var off: usize = 0;
        for (coeffs) |v| {
            const z = zigzagEncode(v);
            const n = try writeVarint(out[off..], z);
            off += n;
        }
        return off;
    }
    pub fn decompressSigned(out: []i16, src: []const u8) !usize {
        var off: usize = 0;
        for (out) |*v| {
            const r = try readVarint(src[off..]);
            off += r.used;
            const x = zigzagDecode(r.value);
            if (x < std.math.minInt(i16) or x > std.math.maxInt(i16)) return error.CoefficientOutOfRange;
            v.* = @intCast(x);
        }
        return off;
    }

    pub const Sampler = struct {
        prng: Wave15FnDsaCore.GaussianPrng,
        sigma: f64,
        pub fn init(seed: u128, sigma: f64) Wave20HqcKem.Sampler {
            return .{ .prng = Wave15FnDsaCore.GaussianPrng.init(seed), .sigma = sigma };
        }
        pub fn vector(self: *Wave20HqcKem.Sampler, out: []i16, center: []const f64) !void {
            if (out.len > center.len) return error.BufferTooSmall;
            for (out, 0..) |*v, i| {
                const x = self.prng.sampleDiscrete(self.sigma, center[i]);
                if (x < std.math.minInt(i16) or x > std.math.maxInt(i16)) return error.SampleOutOfRange;
                v.* = @intCast(x);
            }
        }
    };

    pub fn signatureHeader(logn: u8, payload_len: usize) Header {
        return .{ .logn = logn, .nonce_len = 40, .payload_len = @intCast(@min(payload_len, std.math.maxInt(u16))) };
    }
    pub fn encodeHeader(out: []u8, h: Header) !usize {
        if (out.len < 4) return error.BufferTooSmall;
        out[0] = h.logn;
        out[1] = h.nonce_len;
        std.mem.writeInt(u16, out[2..4], h.payload_len, .little);
        return 4;
    }
    pub fn decodeHeader(src: []const u8) !Header {
        if (src.len < 4) return error.Truncated;
        return .{ .logn = src[0], .nonce_len = src[1], .payload_len = std.mem.readInt(u16, src[2..4], .little) };
    }
    pub fn status() []const u8 {
        return "FN-DSA/Falcon equation, encoding, sampler partial implementation present; exact FIPS-206 vectors still gate readiness";
    }
};

pub const Wave20Slh = struct {
    pub const Variant = struct { name: []const u8, n: u8, h: u8, d: u8, a: u8, k: u8, w: u16, security: u16 };
    pub const variants = [_]Variant{
        .{ .name = "SLH-DSA-SHA2-128s", .n = 16, .h = 63, .d = 7, .a = 12, .k = 14, .w = 16, .security = 128 },
        .{ .name = "SLH-DSA-SHA2-128f", .n = 16, .h = 66, .d = 22, .a = 6, .k = 33, .w = 16, .security = 128 },
        .{ .name = "SLH-DSA-SHA2-192s", .n = 24, .h = 63, .d = 7, .a = 14, .k = 17, .w = 16, .security = 192 },
        .{ .name = "SLH-DSA-SHA2-192f", .n = 24, .h = 66, .d = 22, .a = 8, .k = 33, .w = 16, .security = 192 },
        .{ .name = "SLH-DSA-SHA2-256s", .n = 32, .h = 64, .d = 8, .a = 14, .k = 22, .w = 16, .security = 256 },
        .{ .name = "SLH-DSA-SHA2-256f", .n = 32, .h = 68, .d = 17, .a = 9, .k = 35, .w = 16, .security = 256 },
        .{ .name = "SLH-DSA-SHAKE-128s", .n = 16, .h = 63, .d = 7, .a = 12, .k = 14, .w = 16, .security = 128 },
        .{ .name = "SLH-DSA-SHAKE-128f", .n = 16, .h = 66, .d = 22, .a = 6, .k = 33, .w = 16, .security = 128 },
        .{ .name = "SLH-DSA-SHAKE-192s", .n = 24, .h = 63, .d = 7, .a = 14, .k = 17, .w = 16, .security = 192 },
        .{ .name = "SLH-DSA-SHAKE-192f", .n = 24, .h = 66, .d = 22, .a = 8, .k = 33, .w = 16, .security = 192 },
        .{ .name = "SLH-DSA-SHAKE-256s", .n = 32, .h = 64, .d = 8, .a = 14, .k = 22, .w = 16, .security = 256 },
        .{ .name = "SLH-DSA-SHAKE-256f", .n = 32, .h = 68, .d = 17, .a = 9, .k = 35, .w = 16, .security = 256 },
    };
    pub fn xmssHeight(v: Variant) u8 {
        return v.h / v.d;
    }
    pub fn len1(v: Variant) usize {
        return (8 * @as(usize, v.n) + 3) / 4;
    }
    pub fn len2(v: Variant) usize {
        var x = (len1(v) * 15);
        var n: usize = 0;
        while (x > 0) {
            x >>= 4;
            n += 1;
        }
        return n;
    }
    pub fn wotsLen(v: Variant) usize {
        return len1(v) + len2(v);
    }
    pub fn forsSigBytes(v: Variant) usize {
        return @as(usize, v.k) * (1 + v.a) * v.n;
    }
    pub fn xmssSigBytes(v: Variant) usize {
        return (wotsLen(v) + xmssHeight(v)) * v.n;
    }
    pub fn signatureBytes(v: Variant) usize {
        return v.n + forsSigBytes(v) + @as(usize, v.d) * xmssSigBytes(v);
    }
    pub fn publicKeyBytes(v: Variant) usize {
        return 2 * @as(usize, v.n);
    }
    pub fn secretKeyBytes(v: Variant) usize {
        return 4 * @as(usize, v.n);
    }

    pub fn base16(out: []u8, input: []const u8) void {
        var oi: usize = 0;
        for (input) |b| {
            if (oi < out.len) {
                out[oi] = b >> 4;
                oi += 1;
            }
            if (oi < out.len) {
                out[oi] = b & 15;
                oi += 1;
            }
        }
        while (oi < out.len) : (oi += 1) out[oi] = 0;
    }
    pub fn wotsDigits(out: []u8, msg: []const u8, v: Variant) void {
        const l1 = len1(v);
        const l2 = len2(v);
        base16(out[0..@min(out.len, l1)], msg);
        var csum: usize = 0;
        for (out[0..@min(out.len, l1)]) |x| csum += 15 - x;
        for (0..l2) |i| {
            if (l1 + i < out.len) out[l1 + i] = @truncate(csum >> @intCast(4 * (l2 - 1 - i)));
        }
    }
    pub fn forsIndices(out: []u32, digest: []const u8, v: Variant) void {
        var bit: usize = 0;
        for (out[0..@min(out.len, v.k)]) |*idx| {
            var x: u32 = 0;
            for (0..v.a) |j| {
                const bi = bit >> 3;
                if (bi < digest.len) x |= @as(u32, (digest[bi] >> @intCast(bit & 7)) & 1) << @intCast(j);
                bit += 1;
            }
            idx.* = x;
        }
    }

    pub fn authRoot(out: []u8, leaf: []const u8, auth: []const u8, index: u32, height: u8, n: usize, pub_seed: []const u8, base_addr: Wave15SlhDeep.Address) !void {
        if (out.len < n or leaf.len < n or auth.len < @as(usize, height) * n) return error.BufferTooSmall;
        var node: [32]u8 = [_]u8{0} ** 32;
        @memcpy(node[0..n], leaf[0..n]);
        var idx = index;
        var h: u8 = 0;
        while (h < height) : (h += 1) {
            var pair: [64]u8 = undefined;
            const sibling = auth[@as(usize, h) * n ..][0..n];
            if ((idx & 1) == 0) {
                @memcpy(pair[0..n], node[0..n]);
                @memcpy(pair[n .. 2 * n], sibling);
            } else {
                @memcpy(pair[0..n], sibling);
                @memcpy(pair[n .. 2 * n], node[0..n]);
            }
            Wave15SlhDeep.thash(node[0..n], pub_seed, base_addr.withTreeNode(h + 1, idx >> 1), pair[0 .. 2 * n]);
            idx >>= 1;
        }
        @memcpy(out[0..n], node[0..n]);
    }

    pub fn splitDigest(md: []const u8, v: Variant) struct { tree: u64, leaf: u32 } {
        const th = xmssHeight(v);
        var tree: u64 = 0;
        var leaf: u32 = 0;
        const tree_bits = @as(usize, v.h) - th;
        for (0..@min(tree_bits, 64)) |i| {
            const bi = i >> 3;
            if (bi < md.len) tree |= @as(u64, (md[bi] >> @intCast(i & 7)) & 1) << @intCast(i);
        }
        for (0..th) |i| {
            const bit = tree_bits + i;
            const bi = bit >> 3;
            if (bi < md.len) leaf |= @as(u32, (md[bi] >> @intCast(bit & 7)) & 1) << @intCast(i);
        }
        return .{ .tree = tree, .leaf = leaf };
    }

    pub fn randomizer(out: []u8, sk_prf: []const u8, opt_rand: []const u8, msg: []const u8) void {
        var x = std.crypto.hash.sha3.Shake256.init(.{});
        x.update(sk_prf);
        x.update(opt_rand);
        x.update(msg);
        x.squeeze(out);
    }
    pub fn messageDigest(out: []u8, r: []const u8, pk_seed: []const u8, pk_root: []const u8, msg: []const u8) void {
        var x = std.crypto.hash.sha3.Shake256.init(.{});
        x.update(r);
        x.update(pk_seed);
        x.update(pk_root);
        x.update(msg);
        x.squeeze(out);
    }

    pub const ParsedSignature = struct { r: []const u8, fors: []const u8, hypertree: []const u8 };
    pub fn parseSignature(sig: []const u8, v: Variant) !ParsedSignature {
        const n = v.n;
        const fb = forsSigBytes(v);
        if (sig.len != signatureBytes(v)) return error.InvalidSignatureLength;
        return .{ .r = sig[0..n], .fors = sig[n .. n + fb], .hypertree = sig[n + fb ..] };
    }
    pub fn status() []const u8 {
        return "SLH-DSA sizing/digest/FORS-WOTS-XMSS reconstruction partial implementation present; complete standardized signer remains KAT-gated";
    }
};

pub const Wave20Quant = struct {
    pub const Fp16 = struct {
        pub fn read(p: []const u8) f32 {
            return Wave15QuantDeep.readF16(p);
        }
    };
    pub fn dequantQ2K(block: []const u8, out: []f32) !void {
        if (block.len < 84 or out.len < 256) return error.BufferTooSmall;
        const scales = block[0..16];
        const qs = block[16..80];
        const d = Fp16.read(block[80..82]);
        const dm = Fp16.read(block[82..84]);
        for (0..16) |g| {
            const scale = scales[g] & 15;
            const min = scales[g] >> 4;
            for (0..16) |j| {
                const idx = g * 16 + j;
                const packed_byte = qs[idx >> 2];
                const q = (packed_byte >> @intCast((idx & 3) * 2)) & 3;
                out[idx] = d * @as(f32, @floatFromInt(scale)) * @as(f32, @floatFromInt(q)) - dm * @as(f32, @floatFromInt(min));
            }
        }
    }
    pub fn dequantQ3K(block: []const u8, out: []f32) !void {
        if (block.len < 110 or out.len < 256) return error.BufferTooSmall;
        const hm = block[0..32];
        const q = block[32..96];
        const packed_bytes = block[96..108];
        const d = Fp16.read(block[108..110]);
        var sc: [16]i8 = undefined;
        for (0..16) |i| {
            const lo = if (i < 8) (packed_bytes[i] & 15) else (packed_bytes[i - 8] >> 4);
            const hi = (packed_bytes[8 + i % 4] >> @intCast(2 * (i / 4))) & 3;
            sc[i] = @as(i8, @intCast(lo | (hi << 4))) - 32;
        }
        for (0..256) |idx| {
            const group = idx / 16;
            const lo = (q[(idx % 128) / 4 + 32 * (idx / 128)] >> @intCast(2 * (idx & 3))) & 3;
            const bit = (hm[idx & 31] >> @intCast(idx / 32)) & 1;
            const signed = @as(i8, @intCast(lo)) - if (bit == 0) @as(i8, 4) else 0;
            out[idx] = d * @as(f32, @floatFromInt(sc[group])) * @as(f32, @floatFromInt(signed));
        }
    }
    pub fn dequantQ8K(block: []const u8, out: []f32) !void {
        if (block.len < 292 or out.len < 256) return error.BufferTooSmall;
        const d = @as(f32, @bitCast(std.mem.readInt(u32, block[0..4], .little)));
        for (0..256) |i| out[i] = d * @as(f32, @floatFromInt(@as(i8, @bitCast(block[4 + i]))));
    }
    pub fn dotQ2K(src: []const u8, x: []const f32, scratch: []f32) !f32 {
        if (x.len % 256 != 0 or scratch.len < x.len) return error.InvalidRowWidth;
        var s: f32 = 0;
        var si: usize = 0;
        var xi: usize = 0;
        while (xi < x.len) : (xi += 256) {
            try dequantQ2K(src[si..][0..84], scratch[xi..][0..256]);
            for (0..256) |j| s += scratch[xi + j] * x[xi + j];
            si += 84;
        }
        return s;
    }
    pub fn dotQ3K(src: []const u8, x: []const f32, scratch: []f32) !f32 {
        if (x.len % 256 != 0 or scratch.len < x.len) return error.InvalidRowWidth;
        var s: f32 = 0;
        var si: usize = 0;
        var xi: usize = 0;
        while (xi < x.len) : (xi += 256) {
            try dequantQ3K(src[si..][0..110], scratch[xi..][0..256]);
            for (0..256) |j| s += scratch[xi + j] * x[xi + j];
            si += 110;
        }
        return s;
    }
    pub fn dotQ8K(src: []const u8, x: []const f32, scratch: []f32) !f32 {
        if (x.len % 256 != 0 or scratch.len < x.len) return error.InvalidRowWidth;
        var s: f32 = 0;
        var si: usize = 0;
        var xi: usize = 0;
        while (xi < x.len) : (xi += 256) {
            try dequantQ8K(src[si..][0..292], scratch[xi..][0..256]);
            for (0..256) |j| s += scratch[xi + j] * x[xi + j];
            si += 292;
        }
        return s;
    }

    pub const RowKernel = enum { f32, f16, q4_0, q4_1, q5_0, q5_1, q8_0, q2_k, q3_k, q4_k, q5_k, q6_k, q8_k };
    pub fn blockSize(k: RowKernel) usize {
        return switch (k) {
            .f32, .f16 => 1,
            .q4_0, .q4_1, .q5_0, .q5_1, .q8_0 => 32,
            else => 256,
        };
    }
    pub fn bytesPerBlock(k: RowKernel) usize {
        return switch (k) {
            .f32 => 4,
            .f16 => 2,
            .q4_0 => 18,
            .q4_1 => 20,
            .q5_0 => 22,
            .q5_1 => 24,
            .q8_0 => 34,
            .q2_k => 84,
            .q3_k => 110,
            .q4_k => 144,
            .q5_k => 176,
            .q6_k => 210,
            .q8_k => 292,
        };
    }
    pub fn rowBytes(k: RowKernel, n: usize) !usize {
        const b = blockSize(k);
        if (n % b != 0) return error.InvalidRowWidth;
        return n / b * bytesPerBlock(k);
    }
};

pub const Wave20Gguf = struct {
    pub const TensorRole = enum { token_embd, output_norm, output, attn_norm, attn_q, attn_k, attn_v, attn_output, ffn_norm, ffn_gate, ffn_up, ffn_down, rope_freq, unknown };
    pub const ParsedName = struct { role: TensorRole, layer: ?usize };
    pub fn parseUnsigned(s: []const u8) !usize {
        var v: usize = 0;
        if (s.len == 0) return error.InvalidNumber;
        for (s) |c| {
            if (c < '0' or c > '9') return error.InvalidNumber;
            v = try std.math.mul(usize, v, 10);
            v = try std.math.add(usize, v, c - '0');
        }
        return v;
    }
    pub fn parseTensorName(name: []const u8) ParsedName {
        if (std.mem.eql(u8, name, "token_embd.weight")) return .{ .role = .token_embd, .layer = null };
        if (std.mem.eql(u8, name, "output_norm.weight")) return .{ .role = .output_norm, .layer = null };
        if (std.mem.eql(u8, name, "output.weight")) return .{ .role = .output, .layer = null };
        if (!std.mem.startsWith(u8, name, "blk.")) return .{ .role = .unknown, .layer = null };
        const rest = name[4..];
        const separator = std.mem.indexOfScalar(u8, rest, '.') orelse return .{ .role = .unknown, .layer = null };
        const layer = parseUnsigned(rest[0..separator]) catch return .{ .role = .unknown, .layer = null };
        const tail = rest[separator + 1 ..];
        const role: TensorRole = if (std.mem.eql(u8, tail, "attn_norm.weight")) .attn_norm else if (std.mem.eql(u8, tail, "attn_q.weight")) .attn_q else if (std.mem.eql(u8, tail, "attn_k.weight")) .attn_k else if (std.mem.eql(u8, tail, "attn_v.weight")) .attn_v else if (std.mem.eql(u8, tail, "attn_output.weight")) .attn_output else if (std.mem.eql(u8, tail, "ffn_norm.weight")) .ffn_norm else if (std.mem.eql(u8, tail, "ffn_gate.weight")) .ffn_gate else if (std.mem.eql(u8, tail, "ffn_up.weight")) .ffn_up else if (std.mem.eql(u8, tail, "ffn_down.weight")) .ffn_down else if (std.mem.eql(u8, tail, "rope_freqs.weight")) .rope_freq else .unknown;
        return .{ .role = role, .layer = layer };
    }
    pub const Shape = struct {
        dims: [4]u64 = [_]u64{0} ** 4,
        n_dims: u8 = 0,
        pub fn elements(self: Shape) !u64 {
            var n: u64 = 1;
            for (self.dims[0..self.n_dims]) |d| {
                if (d == 0) return error.ZeroDimension;
                n = try std.math.mul(u64, n, d);
            }
            return n;
        }
    };
    pub fn expectedRank(role: TensorRole) u8 {
        return switch (role) {
            .output_norm, .attn_norm, .ffn_norm, .rope_freq => 1,
            .token_embd, .output, .attn_q, .attn_k, .attn_v, .attn_output, .ffn_gate, .ffn_up, .ffn_down => 2,
            .unknown => 0,
        };
    }
    pub fn validateRoleShape(role: TensorRole, shape: Shape, hidden: usize, ff: usize, vocab: usize) bool {
        if (role == .unknown) return false;
        if (shape.n_dims != expectedRank(role)) return false;
        const d = shape.dims;
        return switch (role) {
            .token_embd => d[0] == hidden and d[1] == vocab,
            .output => d[0] == hidden or d[1] == hidden,
            .output_norm, .attn_norm, .ffn_norm => d[0] == hidden,
            .attn_q, .attn_k, .attn_v, .attn_output => d[0] == hidden or d[1] == hidden,
            .ffn_gate, .ffn_up => d[0] == hidden and d[1] == ff or d[1] == hidden and d[0] == ff,
            .ffn_down => d[0] == ff and d[1] == hidden or d[1] == ff and d[0] == hidden,
            .rope_freq => d[0] > 0,
            .unknown => false,
        };
    }
    pub fn alignmentOk(offset: u64, alignment: u64) bool {
        return alignment != 0 and offset % alignment == 0;
    }
    pub fn rangeOk(offset: u64, size: u64, file_len: u64) bool {
        return offset <= file_len and size <= file_len - offset;
    }
    pub const AuditCounts = struct { tensors: usize = 0, recognized: usize = 0, bad_rank: usize = 0, bad_shape: usize = 0, bad_range: usize = 0, bad_alignment: usize = 0 };
};

pub const Wave20Generation = struct {
    pub const Role = enum { system, user, assistant, tool };
    pub const Message = struct { role: Role, text: []const u8 };
    pub fn roleName(r: Role) []const u8 {
        return switch (r) {
            .system => "system",
            .user => "user",
            .assistant => "assistant",
            .tool => "tool",
        };
    }
    pub fn appendChatTemplate(out: []u8, messages: []const Message) !usize {
        var off: usize = 0;
        for (messages) |m| {
            const a = "<|start_header_id|>";
            const b = "<|end_header_id|>\n\n";
            const e = "<|eot_id|>";
            for ([_][]const u8{ a, roleName(m.role), b, m.text, e }) |s| {
                if (off + s.len > out.len) return error.BufferTooSmall;
                @memcpy(out[off .. off + s.len], s);
                off += s.len;
            }
        }
        return off;
    }

    pub const Utf8Stream = struct {
        buf: [4]u8 = [_]u8{0} ** 4,
        len: u3 = 0,
        expected: u3 = 0,
        pub fn push(self: *Utf8Stream, b: u8, out: []u8) !usize {
            if (self.len == 0) {
                if (b < 0x80) {
                    if (out.len < 1) return error.BufferTooSmall;
                    out[0] = b;
                    return 1;
                }
                self.expected = if ((b & 0xe0) == 0xc0) 2 else if ((b & 0xf0) == 0xe0) 3 else if ((b & 0xf8) == 0xf0) 4 else return error.InvalidUtf8;
                self.buf[0] = b;
                self.len = 1;
                return 0;
            }
            if ((b & 0xc0) != 0x80) {
                self.len = 0;
                self.expected = 0;
                return error.InvalidUtf8;
            }
            self.buf[self.len] = b;
            self.len += 1;
            if (self.len == self.expected) {
                if (out.len < self.len) return error.BufferTooSmall;
                @memcpy(out[0..self.len], self.buf[0..self.len]);
                const n = self.len;
                self.len = 0;
                self.expected = 0;
                return n;
            }
            return 0;
        }
    };

    pub const StopSet = struct {
        items: []const []const u8,
        pub fn suffix(self: StopSet, text: []const u8) ?usize {
            for (self.items, 0..) |s, i| if (text.len >= s.len and std.mem.eql(u8, text[text.len - s.len ..], s)) return i;
            return null;
        }
    };
    pub const TokenRing = struct {
        buf: []u32,
        head: usize = 0,
        count: usize = 0,
        pub fn push(self: *TokenRing, t: u32) void {
            if (self.buf.len == 0) return;
            self.buf[self.head] = t;
            self.head = (self.head + 1) % self.buf.len;
            self.count = @min(self.count + 1, self.buf.len);
        }
        pub fn occurrences(self: TokenRing, t: u32) usize {
            var n: usize = 0;
            for (self.buf[0..self.count]) |x| {
                if (x == t) n += 1;
            }
            return n;
        }
    };
    pub fn penalties(logits: []f32, history: TokenRing, repetition: f32, frequency: f32, presence: f32) void {
        for (logits, 0..) |*l, i| {
            const c = history.occurrences(@intCast(i));
            if (c == 0) continue;
            if (repetition != 1) {
                l.* = if (l.* > 0) 1.0 / repetition else repetition;
            }
            l.* -= frequency * @as(f32, @floatFromInt(c)) + presence;
        }
    }
    pub fn argmax(logits: []const f32) usize {
        var best: usize = 0;
        var v: f32 = -std.math.inf(f32);
        for (logits, 0..) |x, i| if (x > v) {
            v = x;
            best = i;
        };
        return best;
    }
    pub fn softmaxInPlace(x: []f32) void {
        if (x.len == 0) return;
        var m = x[0];
        for (x[1..]) |v| m = @max(m, v);
        var s: f64 = 0;
        for (x) |*v| {
            v.* = @exp(v.* - m);
            s += v.*;
        }
        if (s == 0) return;
        for (x) |*v| v.* /= @floatCast(s);
    }

    pub const Metrics = struct {
        prompt_tokens: usize = 0,
        generated_tokens: usize = 0,
        nanos_prefill: u64 = 0,
        nanos_decode: u64 = 0,
        pub fn decodeTps(self: Metrics) f64 {
            return if (self.nanos_decode == 0) 0 else @as(f64, @floatFromInt(self.generated_tokens)) * 1e9 / @as(f64, @floatFromInt(self.nanos_decode));
        }
    };
};

pub const Wave20Journal = struct {
    pub const magic: u32 = 0x4a5a414e;
    pub const Version: u16 = 1;
    pub const RecordType = enum(u8) { conversation = 1, message = 2, setting = 3, key_envelope = 4, checkpoint = 5 };
    pub const Header = struct { magic_value: u32 = magic, version: u16 = Version, record_type: u8, payload_len: u32, crc: u32 };
    pub fn crc32(data: []const u8) u32 {
        var c: u32 = 0xffffffff;
        for (data) |b| {
            c ^= b;
            for (0..8) |_| c = if ((c & 1) != 0) (c >> 1) ^ 0xedb88320 else c >> 1;
        }
        return ~c;
    }
    pub fn writeHeader(out: []u8, h: Header) !usize {
        if (out.len < 15) return error.BufferTooSmall;
        std.mem.writeInt(u32, out[0..4], h.magic_value, .little);
        std.mem.writeInt(u16, out[4..6], h.version, .little);
        out[6] = h.record_type;
        std.mem.writeInt(u32, out[7..11], h.payload_len, .little);
        std.mem.writeInt(u32, out[11..15], h.crc, .little);
        return 15;
    }
    pub fn readHeader(src: []const u8) !Header {
        if (src.len < 15) return error.Truncated;
        const h = Header{ .magic_value = std.mem.readInt(u32, src[0..4], .little), .version = std.mem.readInt(u16, src[4..6], .little), .record_type = src[6], .payload_len = std.mem.readInt(u32, src[7..11], .little), .crc = std.mem.readInt(u32, src[11..15], .little) };
        if (h.magic_value != magic) return error.BadMagic;
        if (h.version != Version) return error.UnsupportedVersion;
        return h;
    }
    pub fn encodeRecord(out: []u8, kind: RecordType, payload: []const u8) !usize {
        if (payload.len > std.math.maxInt(u32)) return error.RecordTooLarge;
        const h = Header{ .record_type = @intFromEnum(kind), .payload_len = @intCast(payload.len), .crc = crc32(payload) };
        const n = try writeHeader(out, h);
        if (n + payload.len > out.len) return error.BufferTooSmall;
        @memcpy(out[n .. n + payload.len], payload);
        return n + payload.len;
    }
    pub fn verifyRecord(src: []const u8) ![]const u8 {
        const h = try readHeader(src);
        const end = 15 + @as(usize, h.payload_len);
        if (end > src.len) return error.Truncated;
        const p = src[15..end];
        if (crc32(p) != h.crc) return error.CrcMismatch;
        return p;
    }
};

pub const Wave20SelfAudit = struct {
    pub const State = enum { unavailable, partial, implemented_unverified, implemented, vector_verified };
    pub const Capability = struct { name: []const u8, state: State, note: []const u8 };
    pub const capabilities = [_]Capability{
        .{ .name = "ML-KEM-512", .state = .implemented_unverified, .note = "NIST ACVP keygen/encapsulation/decapsulation vectors pass; differential review pending" },
        .{ .name = "ML-KEM-768", .state = .implemented_unverified, .note = "NIST ACVP keygen/encapsulation/decapsulation vectors pass; differential review pending" },
        .{ .name = "ML-KEM-1024", .state = .implemented_unverified, .note = "NIST ACVP keygen/encapsulation/decapsulation vectors pass; differential review pending" },
        .{ .name = "ML-DSA-44", .state = .partial, .note = "sign/verify interoperability fails; public facade is fail-closed" },
        .{ .name = "ML-DSA-65", .state = .partial, .note = "sign/verify interoperability fails; public facade is fail-closed" },
        .{ .name = "ML-DSA-87", .state = .partial, .note = "sign/verify interoperability fails; public facade is fail-closed" },
        .{ .name = "SLH-DSA", .state = .partial, .note = "WOTS/FORS/XMSS/hypertree partial implementation present" },
        .{ .name = "HQC", .state = .partial, .note = "GF(2), coding and KEM transcript partial implementation present" },
        .{ .name = "FN-DSA", .state = .partial, .note = "FFT/Gaussian/equation/codec partial implementation present" },
        .{ .name = "GGUF-Llama", .state = .partial, .note = "pure-Zig loader and scalar mixed-quant execution path present" },
    };
    pub fn readyForProduction(name: []const u8) bool {
        for (capabilities) |c| if (std.mem.eql(u8, c.name, name)) return c.state == .vector_verified;
        return false;
    }
    pub fn count(s: State) usize {
        var n: usize = 0;
        for (capabilities) |c| {
            if (c.state == s) n += 1;
        }
        return n;
    }
};

