pub const Wave20Kats = struct {
    pub const HashCase = struct { name: []const u8, input: []const u8, expected: [32]u8 };
    pub const sha256_empty = [32]u8{ 0xe3, 0xb0, 0xc4, 0x42, 0x98, 0xfc, 0x1c, 0x14, 0x9a, 0xfb, 0xf4, 0xc8, 0x99, 0x6f, 0xb9, 0x24, 0x27, 0xae, 0x41, 0xe4, 0x64, 0x9b, 0x93, 0x4c, 0xa4, 0x95, 0x99, 0x1b, 0x78, 0x52, 0xb8, 0x55 };
    pub const sha256_abc = [32]u8{ 0xba, 0x78, 0x16, 0xbf, 0x8f, 0x01, 0xcf, 0xea, 0x41, 0x41, 0x40, 0xde, 0x5d, 0xae, 0x22, 0x23, 0xb0, 0x03, 0x61, 0xa3, 0x96, 0x17, 0x7a, 0x9c, 0xb4, 0x10, 0xff, 0x61, 0xf2, 0x00, 0x15, 0xad };
    pub const hash_cases = [_]HashCase{ .{ .name = "sha256-empty", .input = "", .expected = sha256_empty }, .{ .name = "sha256-abc", .input = "abc", .expected = sha256_abc } };
    pub fn runSha256() bool {
        for (hash_cases) |c| {
            var out: [32]u8 = undefined;
            std.crypto.hash.sha2.Sha256.hash(c.input, &out, .{});
            if (!std.mem.eql(u8, &out, &c.expected)) return false;
        }
        return true;
    }
    pub fn runJournal() bool {
        var buf: [128]u8 = undefined;
        const n = Wave20Journal.encodeRecord(&buf, .message, "abc") catch return false;
        const p = Wave20Journal.verifyRecord(buf[0..n]) catch return false;
        return std.mem.eql(u8, p, "abc");
    }
    pub fn runQuantSizing() bool {
        return (Wave20Quant.rowBytes(.q3_k, 256) catch 0) == 110 and (Wave20Quant.rowBytes(.q4_k, 256) catch 0) == 144 and (Wave20Quant.rowBytes(.q6_k, 256) catch 0) == 210;
    }
    pub fn runTensorParser() bool {
        const a = Wave20Gguf.parseTensorName("blk.7.attn_q.weight");
        return a.role == .attn_q and a.layer != null and a.layer.? == 7;
    }
    pub fn runAll() bool {
        return runSha256() and runJournal() and runQuantSizing() and runTensorParser();
    }
};

