pub const Wave20Sampler = struct {
    pub const Candidate = struct { id: u32, logit: f32, prob: f32 };
    pub fn temperature(logits: []f32, t: f32) void {
        if (t <= 0) return;
        const inv = 1.0 / t;
        for (logits) |*x| x.* *= inv;
    }
    pub fn suppress(logits: []f32, ids: []const u32) void {
        for (ids) |id| {
            if (id < logits.len) logits[id] = -std.math.inf(f32);
        }
    }
    pub fn bias(logits: []f32, ids: []const u32, values: []const f32) void {
        for (ids, 0..) |id, i| {
            if (id < logits.len and i < values.len) logits[id] += values[i];
        }
    }
    pub fn topK(logits: []const f32, out: []Candidate, k_in: usize) usize {
        const k = @min(k_in, out.len);
        for (0..k) |i| out[i] = .{ .id = 0, .logit = -std.math.inf(f32), .prob = 0 };
        for (logits, 0..) |v, i| {
            var pos: usize = 0;
            while (pos < k and v <= out[pos].logit) : (pos += 1) {}
            if (pos < k) {
                var j = k - 1;
                while (j > pos) : (j -= 1) out[j] = out[j - 1];
                out[pos] = .{ .id = @intCast(i), .logit = v, .prob = 0 };
            }
        }
        return k;
    }
    pub fn normalize(c: []Candidate) void {
        if (c.len == 0) return;
        var m = c[0].logit;
        for (c[1..]) |x| m = @max(m, x.logit);
        var s: f64 = 0;
        for (c) |*x| {
            x.prob = @exp(x.logit - m);
            s += x.prob;
        }
        if (s == 0) return;
        for (c) |*x| x.prob /= @floatCast(s);
    }
    pub fn nucleus(c: []Candidate, p: f32) usize {
        normalize(c);
        var acc: f32 = 0;
        for (c, 0..) |x, i| {
            acc += x.prob;
            if (acc >= p) return i + 1;
        }
        return c.len;
    }
    pub fn sample(c: []const Candidate, r: f64) u32 {
        var acc: f64 = 0;
        for (c) |x| {
            acc += x.prob;
            if (r < acc) return x.id;
        }
        return if (c.len == 0) 0 else c[c.len - 1].id;
    }
    pub fn minP(c: []Candidate, min_p: f32) usize {
        normalize(c);
        if (c.len == 0) return 0;
        const cutoff = c[0].prob * min_p;
        var n: usize = 0;
        while (n < c.len and c[n].prob >= cutoff) : (n += 1) {}
        return n;
    }
    pub fn typical(c: []Candidate, mass: f32) usize {
        normalize(c);
        var acc: f32 = 0;
        for (c, 0..) |x, i| {
            acc += x.prob;
            if (acc >= mass) return i + 1;
        }
        return c.len;
    }
};

pub const Wave20Tokenizer = struct {
    pub const Piece = struct { start: usize, end: usize, special: bool };
    pub fn isSpace(b: u8) bool {
        return b == ' ' or b == '\t' or b == '\n' or b == '\r';
    }
    pub fn isAsciiLetter(b: u8) bool {
        return (b >= 'a' and b <= 'z') or (b >= 'A' and b <= 'Z');
    }
    pub fn isAsciiDigit(b: u8) bool {
        return b >= '0' and b <= '9';
    }
    pub fn utf8Len(b: u8) u3 {
        return if (b < 0x80) 1 else if ((b & 0xe0) == 0xc0) 2 else if ((b & 0xf0) == 0xe0) 3 else if ((b & 0xf8) == 0xf0) 4 else 0;
    }
    pub fn splitAsciiPretokens(text: []const u8, out: []Piece) !usize {
        var n: usize = 0;
        var i: usize = 0;
        while (i < text.len) {
            if (n >= out.len) return error.BufferTooSmall;
            const start = i;
            const b = text[i];
            if (isSpace(b)) {
                i += 1;
                while (i < text.len and isSpace(text[i])) : (i += 1) {}
            } else if (isAsciiLetter(b)) {
                i += 1;
                while (i < text.len and isAsciiLetter(text[i])) : (i += 1) {}
            } else if (isAsciiDigit(b)) {
                i += 1;
                while (i < text.len and isAsciiDigit(text[i]) and i - start < 3) : (i += 1) {}
            } else {
                const l = utf8Len(b);
                if (l == 0 or i + l > text.len) return error.InvalidUtf8;
                i += l;
            }
            out[n] = .{ .start = start, .end = i, .special = false };
            n += 1;
        }
        return n;
    }
    pub fn findSpecial(text: []const u8, specials: []const []const u8, start: usize) ?struct { index: usize, which: usize } {
        var best: ?struct { index: usize, which: usize } = null;
        for (specials, 0..) |s, j| {
            if (s.len == 0) continue;
            const rel = std.mem.indexOfPos(u8, text, start, s) orelse continue;
            if (best == null or rel < best.?.index) best = .{ .index = rel, .which = j };
        }
        return best;
    }
    pub fn segmentSpecial(text: []const u8, specials: []const []const u8, out: []Piece) !usize {
        var n: usize = 0;
        var pos: usize = 0;
        while (pos < text.len) {
            const hit = findSpecial(text, specials, pos);
            if (hit == null) {
                if (n >= out.len) return error.BufferTooSmall;
                out[n] = .{ .start = pos, .end = text.len, .special = false };
                n += 1;
                break;
            }
            const h = hit.?;
            if (h.index > pos) {
                if (n >= out.len) return error.BufferTooSmall;
                out[n] = .{ .start = pos, .end = h.index, .special = false };
                n += 1;
            }
            const e = h.index + specials[h.which].len;
            if (n >= out.len) return error.BufferTooSmall;
            out[n] = .{ .start = h.index, .end = e, .special = true };
            n += 1;
            pos = e;
        }
        return n;
    }
    pub fn byteTokenName(out: []u8, b: u8) ![]const u8 {
        if (out.len < 6) return error.BufferTooSmall;
        const hex = "0123456789ABCDEF";
        out[0] = '<';
        out[1] = '0';
        out[2] = 'x';
        out[3] = hex[b >> 4];
        out[4] = hex[b & 15];
        out[5] = '>';
        return out[0..6];
    }
};

pub const Wave20ModelManifest = struct {
    pub const Entry = struct { name: []const u8, required: bool, rank: u8 };
    pub const globals = [_]Entry{
        .{ .name = "token_embd.weight", .required = true, .rank = 2 },
        .{ .name = "output_norm.weight", .required = true, .rank = 1 },
        .{ .name = "output.weight", .required = false, .rank = 2 },
    };
    pub const layer_suffixes = [_]Entry{
        .{ .name = "attn_norm.weight", .required = true, .rank = 1 },
        .{ .name = "attn_q.weight", .required = true, .rank = 2 },
        .{ .name = "attn_k.weight", .required = true, .rank = 2 },
        .{ .name = "attn_v.weight", .required = true, .rank = 2 },
        .{ .name = "attn_output.weight", .required = true, .rank = 2 },
        .{ .name = "ffn_norm.weight", .required = true, .rank = 1 },
        .{ .name = "ffn_gate.weight", .required = true, .rank = 2 },
        .{ .name = "ffn_up.weight", .required = true, .rank = 2 },
        .{ .name = "ffn_down.weight", .required = true, .rank = 2 },
        .{ .name = "rope_freqs.weight", .required = false, .rank = 1 },
    };
    pub fn requiredTensorCount(layers: usize) usize {
        return 2 + layers * 9;
    }
    pub fn optionalTensorCount(layers: usize) usize {
        return 1 + layers;
    }
    pub fn isRequiredRole(role: Wave20Gguf.TensorRole) bool {
        return switch (role) {
            .token_embd, .output_norm, .attn_norm, .attn_q, .attn_k, .attn_v, .attn_output, .ffn_norm, .ffn_gate, .ffn_up, .ffn_down => true,
            else => false,
        };
    }
    pub fn expectedPerLayer() usize {
        return layer_suffixes.len;
    }
};

pub const Wave20Secure = struct {
    pub fn wipe(bytes: []u8) void {
        std.crypto.secureZero(u8, bytes);
    }
    pub fn ctEqual(a: []const u8, b: []const u8) bool {
        if (a.len != b.len) return false;
        var d: u8 = 0;
        for (a, b) |x, y| d |= x ^ y;
        return d == 0;
    }
    pub fn ctSelect(dst: []u8, a: []const u8, b: []const u8, choose_b: u1) void {
        const mask: u8 = 0 -% @as(u8, choose_b);
        const n = @min(dst.len, @min(a.len, b.len));
        for (0..n) |i| dst[i] = (a[i] & ~mask) | (b[i] & mask);
    }
    pub fn incrementNonce(nonce: []u8) bool {
        var i = nonce.len;
        while (i > 0) {
            i -= 1;
            nonce[i] +%= 1;
            if (nonce[i] != 0) return true;
        }
        return false;
    }
    pub fn deriveKey(out: []u8, master: []const u8, context: []const u8) void {
        var h = std.crypto.hash.sha3.Shake256.init(.{});
        h.update("Naza/Wave20/KDF");
        h.update(master);
        h.update(context);
        h.squeeze(out);
    }
};

pub const Wave20RuntimeAudit = struct {
    pub const Issue = enum { none, missing_tensor, bad_shape, bad_quant, bad_offset, bad_alignment, bad_tokenizer, bad_architecture, hash_mismatch };
    pub const Result = struct { issue: Issue = .none, index: usize = 0, detail: []const u8 = "" };
    pub fn merge(a: Result, b: Result) Result {
        return if (a.issue != .none) a else b;
    }
    pub fn ok(r: Result) bool {
        return r.issue == .none;
    }
    pub fn checkAlignment(offsets: []const u64, alignment: u64) Result {
        for (offsets, 0..) |x, i| if (!Wave20Gguf.alignmentOk(x, alignment)) return .{ .issue = .bad_alignment, .index = i, .detail = "tensor offset is not aligned" };
        return .{};
    }
    pub fn checkMonotonic(offsets: []const u64) Result {
        if (offsets.len < 2) return .{};
        for (1..offsets.len) |i| if (offsets[i] < offsets[i - 1]) return .{ .issue = .bad_offset, .index = i, .detail = "tensor offsets are not monotonic" };
        return .{};
    }
    pub fn checkQuantRow(kind: Wave20Quant.RowKernel, elements: usize) Result {
        _ = Wave20Quant.rowBytes(kind, elements) catch return .{ .issue = .bad_quant, .detail = "row is not divisible by quant block" };
        return .{};
    }
};

