// ============================================================================
// Wave 29 expansion: fixed-size execution surfaces, code-based arithmetic,
// signature-tree helpers, quantized tensor validation, generation/session
// utilities, and deterministic self-test plumbing.  These additions remain
// partial implementation unless an enclosing registry entry has passed official vectors.
// ============================================================================

pub const Wave29Bits = struct {
    pub fn parity64(x0: u64) u1 {
        var x = x0;
        x ^= x >> 32;
        x ^= x >> 16;
        x ^= x >> 8;
        x ^= x >> 4;
        x &= 0xf;
        return @intCast((0x6996 >> @intCast(x)) & 1);
    }

    pub fn weight(words: []const u64) usize {
        var total: usize = 0;
        for (words) |w| total += @popCount(w);
        return total;
    }

    pub fn clear(words: []u64) void {
        @memset(words, 0);
    }

    pub fn xorInto(dst: []u64, src: []const u64) !void {
        if (dst.len != src.len) return error.LengthMismatch;
        for (dst, src) |*d, s| d.* ^= s;
    }

    pub fn andWeight(a: []const u64, b: []const u64) !usize {
        if (a.len != b.len) return error.LengthMismatch;
        var total: usize = 0;
        for (a, b) |x, y| total += @popCount(x & y);
        return total;
    }

    pub fn get(words: []const u64, bit: usize) bool {
        const wi = bit >> 6;
        if (wi >= words.len) return false;
        return ((words[wi] >> @intCast(bit & 63)) & 1) != 0;
    }

    pub fn toggle(words: []u64, bit: usize) !void {
        const wi = bit >> 6;
        if (wi >= words.len) return error.IndexOutOfBounds;
        words[wi] ^= @as(u64, 1) << @intCast(bit & 63);
    }

    pub fn set(words: []u64, bit: usize, value: bool) !void {
        const wi = bit >> 6;
        if (wi >= words.len) return error.IndexOutOfBounds;
        const mask = @as(u64, 1) << @intCast(bit & 63);
        if (value) words[wi] |= mask else words[wi] &= ~mask;
    }

    pub fn maskTail(words: []u64, n_bits: usize) void {
        if (words.len == 0) return;
        const rem = n_bits & 63;
        if (rem == 0) return;
        words[words.len - 1] &= (@as(u64, 1) << @intCast(rem)) - 1;
    }
};

pub const Wave29Ring = struct {
    pub fn rotateXorMod(dst: []u64, src: []const u64, n_bits: usize, shift: usize) !void {
        if (dst.len != src.len) return error.LengthMismatch;
        if (n_bits == 0 or n_bits > dst.len * 64) return error.InvalidBitLength;
        const s = shift % n_bits;
        var bit: usize = 0;
        while (bit < n_bits) : (bit += 1) {
            if (Wave29Bits.get(src, bit)) {
                const out = (bit + s) % n_bits;
                try Wave29Bits.toggle(dst, out);
            }
        }
    }

    pub fn sparseMul(dst: []u64, dense: []const u64, n_bits: usize, positions: []const u32) !void {
        if (dst.len != dense.len) return error.LengthMismatch;
        Wave29Bits.clear(dst);
        for (positions) |pos| {
            if (pos >= n_bits) return error.IndexOutOfBounds;
            try rotateXorMod(dst, dense, n_bits, pos);
        }
        Wave29Bits.maskTail(dst, n_bits);
    }

    pub fn denseMulPortable(dst: []u64, a: []const u64, b: []const u64, n_bits: usize) !void {
        if (dst.len != a.len or dst.len != b.len) return error.LengthMismatch;
        Wave29Bits.clear(dst);
        var i: usize = 0;
        while (i < n_bits) : (i += 1) {
            if (!Wave29Bits.get(a, i)) continue;
            var j: usize = 0;
            while (j < n_bits) : (j += 1) {
                if (Wave29Bits.get(b, j)) try Wave29Bits.toggle(dst, (i + j) % n_bits);
            }
        }
        Wave29Bits.maskTail(dst, n_bits);
    }

    pub fn syndromeWeight(h: []const u64, e: []const u64) !usize {
        return Wave29Bits.andWeight(h, e);
    }
};

pub const Wave29HqcCodec = struct {
    pub fn bytesForBits(n_bits: usize) usize {
        return (n_bits + 7) / 8;
    }

    pub fn packBits(out: []u8, words: []const u64, n_bits: usize) !usize {
        const need = bytesForBits(n_bits);
        if (out.len < need or words.len * 64 < n_bits) return error.BufferTooSmall;
        @memset(out[0..need], 0);
        var i: usize = 0;
        while (i < n_bits) : (i += 1) {
            if (Wave29Bits.get(words, i)) out[i >> 3] |= @as(u8, 1) << @intCast(i & 7);
        }
        return need;
    }

    pub fn unpackBits(words: []u64, input: []const u8, n_bits: usize) !void {
        if (input.len < bytesForBits(n_bits) or words.len * 64 < n_bits) return error.BufferTooSmall;
        Wave29Bits.clear(words);
        var i: usize = 0;
        while (i < n_bits) : (i += 1) {
            const v = ((input[i >> 3] >> @intCast(i & 7)) & 1) != 0;
            if (v) try Wave29Bits.set(words, i, true);
        }
        Wave29Bits.maskTail(words, n_bits);
    }

    pub fn canonicalPadding(input: []const u8, n_bits: usize) bool {
        const rem = n_bits & 7;
        if (rem == 0 or input.len == 0) return true;
        const mask: u8 = @intCast((@as(u16, 1) << @intCast(rem)) - 1);
        return (input[bytesForBits(n_bits) - 1] & ~mask) == 0;
    }
};

pub const Wave29Repetition = struct {
    pub fn encodeBit(bit: bool, out: []u8) void {
        @memset(out, if (bit) 0xff else 0x00);
    }
    pub fn decodeBit(input: []const u8) bool {
        var ones: usize = 0;
        for (input) |b| ones += @popCount(b);
        return ones * 2 >= input.len * 8;
    }
    pub fn distance(a: []const u8, b: []const u8) !usize {
        if (a.len != b.len) return error.LengthMismatch;
        var d: usize = 0;
        for (a, b) |x, y| d += @popCount(x ^ y);
        return d;
    }
};

pub const Wave29FnCodec = struct {
    pub fn encodeSigned(out: []u8, coeffs: []const i16, bits: u5) !usize {
        if (bits == 0 or bits > 16) return error.InvalidBitWidth;
        const total_bits = coeffs.len * @as(usize, bits);
        const need = (total_bits + 7) / 8;
        if (out.len < need) return error.BufferTooSmall;
        @memset(out[0..need], 0);
        const mask: u32 = if (bits == 16) 0xffff else (@as(u32, 1) << bits) - 1;
        var cursor: usize = 0;
        for (coeffs) |c| {
            const raw: u32 = @as(u16, @bitCast(c)) & mask;
            var j: u5 = 0;
            while (j < bits) : (j += 1) {
                if (((raw >> j) & 1) != 0) out[cursor >> 3] |= @as(u8, 1) << @intCast(cursor & 7);
                cursor += 1;
            }
        }
        return need;
    }

    pub fn decodeSigned(coeffs: []i16, input: []const u8, bits: u5) !void {
        if (bits == 0 or bits > 16) return error.InvalidBitWidth;
        const total_bits = coeffs.len * @as(usize, bits);
        if (input.len * 8 < total_bits) return error.BufferTooSmall;
        var cursor: usize = 0;
        for (coeffs) |*c| {
            var raw: u16 = 0;
            var j: u5 = 0;
            while (j < bits) : (j += 1) {
                const bit = (input[cursor >> 3] >> @intCast(cursor & 7)) & 1;
                raw |= @as(u16, bit) << j;
                cursor += 1;
            }
            if (bits < 16 and ((raw >> @intCast(bits - 1)) & 1) != 0) raw |= ~(@as(u16, 0xffff) >> @intCast(16 - bits));
            c.* = @bitCast(raw);
        }
    }

    pub fn squaredNorm(a: []const i16, b: []const i16) !u64 {
        if (a.len != b.len) return error.LengthMismatch;
        var acc: u64 = 0;
        for (a, b) |x, y| {
            const xx: i64 = x;
            const yy: i64 = y;
            acc +%= @intCast(xx * xx + yy * yy);
        }
        return acc;
    }
};

pub const Wave29SlhTree = struct {
    pub fn nodeCount(height: u8) !usize {
        if (height > 30) return error.HeightTooLarge;
        return (@as(usize, 1) << @intCast(height + 1)) - 1;
    }

    pub fn leafCount(height: u8) !usize {
        if (height > 30) return error.HeightTooLarge;
        return @as(usize, 1) << @intCast(height);
    }

    pub fn authPathBytes(height: u8, n: usize) !usize {
        return std.math.mul(usize, height, n);
    }

    pub fn rootFromAuthPath(
        out: []u8,
        leaf: []const u8,
        auth: []const u8,
        leaf_index: u32,
        height: u8,
        n: usize,
        pub_seed: []const u8,
    ) !void {
        if (out.len < n or leaf.len < n or auth.len < try authPathBytes(height, n)) return error.BufferTooSmall;
        if (n == 0 or n > 64) return error.InvalidNodeSize;
        var current: [64]u8 = undefined;
        @memcpy(current[0..n], leaf[0..n]);
        var parent: [64]u8 = undefined;
        var pair: [128]u8 = undefined;
        var level: u8 = 0;
        while (level < height) : (level += 1) {
            const sib = auth[@as(usize, level) * n .. (@as(usize, level) + 1) * n];
            const is_right = ((leaf_index >> @intCast(level)) & 1) != 0;
            if (is_right) {
                @memcpy(pair[0..n], sib);
                @memcpy(pair[n .. 2 * n], current[0..n]);
            } else {
                @memcpy(pair[0..n], current[0..n]);
                @memcpy(pair[n .. 2 * n], sib);
            }
            var sponge = std.crypto.hash.sha3.Shake256.init(.{});
            sponge.update(pub_seed);
            var addr: [8]u8 = undefined;
            std.mem.writeInt(u32, addr[0..4], level, .big);
            std.mem.writeInt(u32, addr[4..8], leaf_index >> @intCast(level + 1), .big);
            sponge.update(&addr);
            sponge.update(pair[0 .. 2 * n]);
            sponge.squeeze(parent[0..n]);
            @memcpy(current[0..n], parent[0..n]);
        }
        @memcpy(out[0..n], current[0..n]);
    }
};

pub const Wave29QuantAudit = struct {
    pub const TypeFacts = struct { block_elems: usize, block_bytes: usize, quantized: bool };

    pub fn facts(t: GgmlType) ?TypeFacts {
        return switch (t) {
            .f32 => .{ .block_elems = 1, .block_bytes = 4, .quantized = false },
            .f16 => .{ .block_elems = 1, .block_bytes = 2, .quantized = false },
            .q4_0 => .{ .block_elems = 32, .block_bytes = 18, .quantized = true },
            .q8_0 => .{ .block_elems = 32, .block_bytes = 34, .quantized = true },
            .q2_k => .{ .block_elems = 256, .block_bytes = 84, .quantized = true },
            .q3_k => .{ .block_elems = 256, .block_bytes = 110, .quantized = true },
            .q4_k => .{ .block_elems = 256, .block_bytes = 144, .quantized = true },
            .q5_k => .{ .block_elems = 256, .block_bytes = 176, .quantized = true },
            .q6_k => .{ .block_elems = 256, .block_bytes = 210, .quantized = true },
            else => null,
        };
    }

    pub fn rowBytes(t: GgmlType, cols: usize) !usize {
        const f = facts(t) orelse return error.UnsupportedQuantType;
        if (cols % f.block_elems != 0) return error.InvalidRowLength;
        return std.math.mul(usize, cols / f.block_elems, f.block_bytes);
    }

    pub fn tensorBytes(t: GgmlType, rows: usize, cols: usize) !usize {
        return std.math.mul(usize, rows, try rowBytes(t, cols));
    }

    pub fn validateTensor(t: GgmlType, dims: []const u64, byte_len: usize) !void {
        if (dims.len == 0 or dims.len > 4) return error.InvalidRank;
        var elems: usize = 1;
        for (dims) |d| {
            if (d == 0 or d > std.math.maxInt(usize)) return error.InvalidDimension;
            elems = try std.math.mul(usize, elems, @intCast(d));
        }
        const f = facts(t) orelse return error.UnsupportedQuantType;
        if (elems % f.block_elems != 0) return error.InvalidTensorElementCount;
        const expect = try std.math.mul(usize, elems / f.block_elems, f.block_bytes);
        if (expect != byte_len) return error.TensorByteLengthMismatch;
    }
};

pub const Wave29TokenWindow = struct {
    pub const Entry = struct { id: u32, count: u32 };

    pub fn frequency(ids: []const u32, token: u32) usize {
        var n: usize = 0;
        for (ids) |id| {
            if (id == token) n += 1;
        }
        return n;
    }

    pub fn tailContains(ids: []const u32, window: usize, token: u32) bool {
        const start = if (ids.len > window) ids.len - window else 0;
        return std.mem.indexOfScalar(u32, ids[start..], token) != null;
    }

    pub fn applyPresencePenalty(logits: []f32, ids: []const u32, window: usize, penalty: f32) void {
        const start = if (ids.len > window) ids.len - window else 0;
        for (ids[start..]) |id| {
            if (id < logits.len) logits[id] -= penalty;
        }
    }

    pub fn applyFrequencyPenalty(logits: []f32, ids: []const u32, window: usize, penalty: f32) void {
        const start = if (ids.len > window) ids.len - window else 0;
        for (ids[start..]) |id| {
            if (id < logits.len) logits[id] -= penalty;
        }
    }
};

pub const Wave29Utf8 = struct {
    pub fn scalarLen(first: u8) !u3 {
        if (first < 0x80) return 1;
        if ((first & 0xe0) == 0xc0) return 2;
        if ((first & 0xf0) == 0xe0) return 3;
        if ((first & 0xf8) == 0xf0) return 4;
        return error.InvalidUtf8LeadByte;
    }

    pub fn validScalar(bytes: []const u8) bool {
        if (bytes.len == 0 or bytes.len > 4) return false;
        const n = scalarLen(bytes[0]) catch return false;
        if (n != bytes.len) return false;
        if (n == 1) return true;
        for (bytes[1..]) |b| {
            if ((b & 0xc0) != 0x80) return false;
        }
        if (n == 2 and bytes[0] < 0xc2) return false;
        if (n == 3) {
            if (bytes[0] == 0xe0 and bytes[1] < 0xa0) return false;
            if (bytes[0] == 0xed and bytes[1] >= 0xa0) return false;
        }
        if (n == 4) {
            if (bytes[0] == 0xf0 and bytes[1] < 0x90) return false;
            if (bytes[0] > 0xf4) return false;
            if (bytes[0] == 0xf4 and bytes[1] > 0x8f) return false;
        }
        return true;
    }

    pub fn prefixLength(bytes: []const u8) usize {
        var i: usize = 0;
        while (i < bytes.len) {
            const n = scalarLen(bytes[i]) catch break;
            if (i + n > bytes.len or !validScalar(bytes[i .. i + n])) break;
            i += n;
        }
        return i;
    }
};

pub const Wave29Journal = struct {
    pub const Header = struct { magic: [4]u8, version: u16, kind: u16, payload_len: u32, sequence: u64, crc32: u32 };

    pub fn crc32(data: []const u8) u32 {
        var crc: u32 = 0xffff_ffff;
        for (data) |byte| {
            crc ^= byte;
            var bit: u4 = 0;
            while (bit < 8) : (bit += 1) crc = (crc >> 1) ^ (0xedb8_8320 & (0 -% (crc & 1)));
        }
        return ~crc;
    }

    pub fn encodeHeader(out: []u8, h: Header) !void {
        if (out.len < 24) return error.BufferTooSmall;
        @memcpy(out[0..4], &h.magic);
        std.mem.writeInt(u16, out[4..6], h.version, .little);
        std.mem.writeInt(u16, out[6..8], h.kind, .little);
        std.mem.writeInt(u32, out[8..12], h.payload_len, .little);
        std.mem.writeInt(u64, out[12..20], h.sequence, .little);
        std.mem.writeInt(u32, out[20..24], h.crc32, .little);
    }

    pub fn decodeHeader(input: []const u8) !Header {
        if (input.len < 24) return error.BufferTooSmall;
        return .{
            .magic = input[0..4].*,
            .version = std.mem.readInt(u16, input[4..6], .little),
            .kind = std.mem.readInt(u16, input[6..8], .little),
            .payload_len = std.mem.readInt(u32, input[8..12], .little),
            .sequence = std.mem.readInt(u64, input[12..20], .little),
            .crc32 = std.mem.readInt(u32, input[20..24], .little),
        };
    }

    pub fn validateRecord(header_bytes: []const u8, payload: []const u8) !void {
        const h = try decodeHeader(header_bytes);
        if (!std.mem.eql(u8, &h.magic, "NZJ2")) return error.BadMagic;
        if (@as(usize, h.payload_len) != payload.len) return error.PayloadLengthMismatch;
        if (h.crc32 != crc32(payload)) return error.CrcMismatch;
    }
};

