pub const Wave29TensorRoles = struct {
    pub const Role = enum { token_embd, attn_norm, attn_q, attn_k, attn_v, attn_output, ffn_norm, ffn_gate, ffn_up, ffn_down, output_norm, output };
    pub const Shape = struct { rows: usize, cols: usize };

    pub fn expected(role: Role, hidden: usize, kv_hidden: usize, intermediate: usize, vocab: usize) Shape {
        return switch (role) {
            .token_embd => .{ .rows = vocab, .cols = hidden },
            .attn_norm => .{ .rows = 1, .cols = hidden },
            .attn_q => .{ .rows = hidden, .cols = hidden },
            .attn_k, .attn_v => .{ .rows = kv_hidden, .cols = hidden },
            .attn_output => .{ .rows = hidden, .cols = hidden },
            .ffn_norm => .{ .rows = 1, .cols = hidden },
            .ffn_gate, .ffn_up => .{ .rows = intermediate, .cols = hidden },
            .ffn_down => .{ .rows = hidden, .cols = intermediate },
            .output_norm => .{ .rows = 1, .cols = hidden },
            .output => .{ .rows = vocab, .cols = hidden },
        };
    }

    pub fn matches(dims: []const u64, shape: Shape) bool {
        if (dims.len == 1) return shape.rows == 1 and dims[0] == shape.cols;
        if (dims.len != 2) return false;
        return dims[0] == shape.cols and dims[1] == shape.rows;
    }
};

pub const Wave29ModelProfiles = struct {
    pub const Tiny128 = struct {
        pub const hidden: usize = 128;
        pub const heads: usize = 4;
        pub const kv_heads: usize = 2;
        pub const head_dim: usize = hidden / heads;
        pub const kv_hidden: usize = head_dim * kv_heads;
        pub const intermediate: usize = 512;
        pub const vocab: usize = 32000;
        pub fn shape(role: Wave29TensorRoles.Role) Wave29TensorRoles.Shape {
            return Wave29TensorRoles.expected(role, hidden, kv_hidden, intermediate, vocab);
        }
        pub fn validate(role: Wave29TensorRoles.Role, dims: []const u64) bool {
            return Wave29TensorRoles.matches(dims, shape(role));
