pub const Wave29QuantRows = struct {
    fn dequantGeneric(t: GgmlType, bytes: []const u8, out: []f32) !void {
        switch (t) {
            .q3_k => try Q3KExact.dequantRow(out, bytes),
            .q4_0 => try Wave15QuantDeep.dequantRow(.q4_0, bytes, out),
            .q8_0 => try Wave15QuantDeep.dequantRow(.q8_0, bytes, out),
            else => return error.UnsupportedQuantType,
        }
    }

    pub const C128 = struct {
        pub const cols: usize = 128;
        pub fn expectedBytes(t: GgmlType) !usize {
            return Wave29QuantAudit.rowBytes(t, cols);
        }
        pub fn dequant(t: GgmlType, bytes: []const u8, out: *[cols]f32) !void {
            if (bytes.len != try expectedBytes(t)) return error.RowByteLengthMismatch;
            try dequantGeneric(t, bytes, out);
        }
        pub fn dotF32(x: *const [cols]f32, y: *const [cols]f32) f32 {
            var acc: f32 = 0;
            for (x, y) |a, b| acc += a * b;
            return acc;
        }
        pub fn rms(x: *const [cols]f32) f32 {
            var s: f64 = 0;
            for (x) |v| s += @as(f64, v) * v;
            return @floatCast(@sqrt(s / @as(f64, @floatFromInt(cols))));
        }
    };

