        pub fn f32ActivationBytes() !usize {
            return std.math.mul(usize, hidden, @sizeOf(f32));
        }
        pub fn kvBytes(kv_hidden: usize, layers: usize) !usize {
            var n = try std.math.mul(usize, context, kv_hidden);
            n = try std.math.mul(usize, n, layers);
            n = try std.math.mul(usize, n, 2);
            return std.math.mul(usize, n, @sizeOf(f32));
        }
        pub fn positionFits(pos: usize) bool {
            return pos < context;
        }
        pub fn remaining(pos: usize) usize {
            return if (pos >= context) 0 else context - pos;
        }
        pub fn maxBatch(batch: usize) usize {
            return @min(batch, context);
        }
    };

