pub const Wave29InvariantCases = struct {
    pub const Case1 = struct {
        pub const n_bits: usize = 127;
        pub const target_weight: usize = 3;
        pub const words: usize = (n_bits + 63) / 64;
        pub fn validPositions(pos: []const u32) bool {
            if (pos.len != target_weight) return false;
            for (pos, 0..) |p0, i| {
                if (p0 >= n_bits) return false;
                for (pos[0..i]) |p1| {
                    if (p0 == p1) return false;
                }
            }
            return true;
        }
        pub fn encodedBytes() usize {
            return (n_bits + 7) / 8;
        }
        pub fn wordCount() usize {
            return words;
        }
        pub fn density() f64 {
            return @as(f64, @floatFromInt(target_weight)) / @as(f64, @floatFromInt(n_bits));
        }
    };

