// ============================================================================
// WAVE 38 — LLM-FOCUSED PURE-ZIG RUNTIME EXPANSION
//
// This namespace deliberately concentrates on model loading, tokenizer/runtime,
// quantized inference, context management, sampling, chat/session semantics,
// training utilities, and diagnostics. It does not link llama.cpp or Python.
// The scalar kernels are portable-first and are intended to be compiler-audited
// and then optimized without changing their public semantics.
// ============================================================================

pub const Wave38Llm = struct {
    // Persistent workers avoid creating and joining OS threads for every
    // projection and every generated token.
    var matrix_pool: ?std.Thread.Pool = null;

    pub fn initMatrixPool(allocator: std.mem.Allocator, jobs: usize) !void {
        if (matrix_pool != null) return;
        // Worker threads retain the pool address. Initialize in its final
        // storage; copying an initialized pool strands workers on old locks.
        matrix_pool = @as(std.Thread.Pool, undefined);
        errdefer matrix_pool = null;
        try matrix_pool.?.init(.{ .allocator = allocator, .n_jobs = @max(@as(usize, 1), jobs) });
    }

    pub fn deinitMatrixPool() void {
        if (matrix_pool) |*pool| pool.deinit();
        matrix_pool = null;
    }

    pub const target_model_repo = ModelSpec.repository;
    pub const target_model_file = ModelSpec.file;
    pub const target_model_sha256 = ModelSpec.sha256_hex;
    pub const target_model_approx_bytes: usize = ModelSpec.approximate_bytes;
    pub const llama3_vocab_hint: usize = 128256;
    pub const hard_max_metadata_entries: usize = 1_000_000;
    pub const hard_max_tensors: usize = 1_000_000;
    pub const hard_max_token_bytes: usize = 1 << 20;
    pub const hard_max_context: usize = 1 << 20;

    pub const Error = error{
        EndOfInput,
        Overflow,
        InvalidGguf,
        UnsupportedGgufVersion,
        InvalidMetadata,
        MetadataLimit,
        InvalidTensor,
        TensorNotFound,
        TensorOutOfBounds,
        UnsupportedQuantType,
        InvalidQuantBlock,
        ShapeMismatch,
        InvalidArchitecture,
        InvalidTokenizer,
        InvalidToken,
        InvalidMerge,
        InvalidUtf8,
        InvalidSpecialToken,
        ContextExceeded,
        CacheCapacity,
        EmptyPrompt,
        EmptyDistribution,
        InvalidProbability,
        InvalidSamplingConfig,
        InvalidSession,
        InvalidCheckpoint,
        ChecksumMismatch,
        DownloadTooLarge,
        DownloadHashMismatch,
        DownloadUnexpectedStatus,
        UnsupportedTransport,
        InvalidGrammar,
        GrammarRejected,
        BeamExhausted,
        TrainingShapeMismatch,
        NonFinite,
    };

    pub const Wave38ByteCursor = struct {
        bytes: []const u8,
        pos: usize = 0,

        pub fn remaining(self: Wave38ByteCursor) usize {
            return self.bytes.len -| self.pos;
        }

        pub fn seek(self: *Wave38ByteCursor, pos: usize) !void {
            if (pos > self.bytes.len) return Error.EndOfInput;
            self.pos = pos;
        }

        pub fn skip(self: *Wave38ByteCursor, n: usize) !void {
            if (n > self.remaining()) return Error.EndOfInput;
            self.pos += n;
        }

        pub fn read(self: *Wave38ByteCursor, comptime T: type) !T {
            const n = @sizeOf(T);
            if (n > self.remaining()) return Error.EndOfInput;
            const out = std.mem.readInt(T, @ptrCast(self.bytes[self.pos .. self.pos + n].ptr), .little);
            self.pos += n;
            return out;
        }

        pub fn readF32(self: *Wave38ByteCursor) !f32 {
            const bits = try self.read(u32);
            return @bitCast(bits);
        }

        pub fn readF64(self: *Wave38ByteCursor) !f64 {
            const bits = try self.read(u64);
            return @bitCast(bits);
        }

        pub fn take(self: *Wave38ByteCursor, n: usize) ![]const u8 {
            if (n > self.remaining()) return Error.EndOfInput;
            const out = self.bytes[self.pos .. self.pos + n];
            self.pos += n;
            return out;
        }

        pub fn readString(self: *Wave38ByteCursor, max_len: usize) ![]const u8 {
            const n64 = try self.read(u64);
            if (n64 > max_len or n64 > std.math.maxInt(usize)) return Error.MetadataLimit;
            return try self.take(@intCast(n64));
        }
    };

    pub const GgufValueType = enum(u32) {
        uint8 = 0,
        int8 = 1,
        uint16 = 2,
        int16 = 3,
        uint32 = 4,
        int32 = 5,
        float32 = 6,
        bool = 7,
        string = 8,
        array = 9,
        uint64 = 10,
        int64 = 11,
        float64 = 12,
    };

    pub const MetadataScalar = union(enum) {
        u8v: u8,
        i8v: i8,
        u16v: u16,
        i16v: i16,
        u32v: u32,
        i32v: i32,
        f32v: f32,
        boolv: bool,
        u64v: u64,
        i64v: i64,
        f64v: f64,
        string: []const u8,

        pub fn asU64(self: MetadataScalar) ?u64 {
            return switch (self) {
                .u8v => |v| v,
                .u16v => |v| v,
                .u32v => |v| v,
                .u64v => |v| v,
                .i8v => |v| if (v >= 0) @intCast(v) else null,
                .i16v => |v| if (v >= 0) @intCast(v) else null,
                .i32v => |v| if (v >= 0) @intCast(v) else null,
                .i64v => |v| if (v >= 0) @intCast(v) else null,
                else => null,
            };
        }

        pub fn asF64(self: MetadataScalar) ?f64 {
            return switch (self) {
                .f32v => |v| @floatCast(v),
                .f64v => |v| v,
                .u8v => |v| @floatFromInt(v),
                .u16v => |v| @floatFromInt(v),
                .u32v => |v| @floatFromInt(v),
                .u64v => |v| @floatFromInt(v),
                .i8v => |v| @floatFromInt(v),
                .i16v => |v| @floatFromInt(v),
                .i32v => |v| @floatFromInt(v),
                .i64v => |v| @floatFromInt(v),
                else => null,
            };
        }

        pub fn asString(self: MetadataScalar) ?[]const u8 {
            return switch (self) {
                .string => |v| v,
                else => null,
            };
        }
    };

    pub const MetadataArrayRef = struct {
        item_type: GgufValueType,
        count: usize,
        payload_offset: usize,
        payload_end: usize,
    };

    pub const MetadataEntry = struct {
        key: []const u8,
        value_type: GgufValueType,
        scalar: ?MetadataScalar = null,
        array: ?MetadataArrayRef = null,
    };

    pub const TensorDesc = struct {
        name: []const u8,
        dims: [4]u64 = .{ 0, 0, 0, 0 },
        n_dims: u32,
        ggml_type: u32,
        relative_offset: u64,
        absolute_offset: u64 = 0,
        byte_len: u64 = 0,

        pub fn elementCount(self: TensorDesc) !u64 {
            if (self.n_dims == 0 or self.n_dims > 4) return Error.InvalidTensor;
            var n: u64 = 1;
            var i: usize = 0;
            while (i < self.n_dims) : (i += 1) {
                if (self.dims[i] == 0) return Error.InvalidTensor;
                if (n > std.math.maxInt(u64) / self.dims[i]) return Error.Overflow;
                n *= self.dims[i];
            }
            return n;
        }

        pub fn rows(self: TensorDesc) usize {
            if (self.n_dims < 2) return 1;
            return @intCast(self.dims[1]);
        }

        pub fn cols(self: TensorDesc) usize {
            return @intCast(self.dims[0]);
        }
    };

    fn scalarPayloadBytes(t: GgufValueType) ?usize {
        return switch (t) {
            .uint8, .int8, .bool => 1,
            .uint16, .int16 => 2,
            .uint32, .int32, .float32 => 4,
            .uint64, .int64, .float64 => 8,
            .string, .array => null,
        };
    }

    fn parseScalar(cur: *Wave38ByteCursor, t: GgufValueType) !MetadataScalar {
        return switch (t) {
            .uint8 => .{ .u8v = try cur.read(u8) },
            .int8 => .{ .i8v = @bitCast(try cur.read(u8)) },
            .uint16 => .{ .u16v = try cur.read(u16) },
            .int16 => .{ .i16v = @bitCast(try cur.read(u16)) },
            .uint32 => .{ .u32v = try cur.read(u32) },
            .int32 => .{ .i32v = @bitCast(try cur.read(u32)) },
            .float32 => .{ .f32v = try cur.readF32() },
            .bool => .{ .boolv = (try cur.read(u8)) != 0 },
            .uint64 => .{ .u64v = try cur.read(u64) },
            .int64 => .{ .i64v = @bitCast(try cur.read(u64)) },
            .float64 => .{ .f64v = try cur.readF64() },
            .string => .{ .string = try cur.readString(hard_max_token_bytes) },
            .array => return Error.InvalidMetadata,
        };
    }

    fn skipArrayPayload(cur: *Wave38ByteCursor, item_type: GgufValueType, count: usize) !void {
        if (scalarPayloadBytes(item_type)) |width| {
            if (count != 0 and width > std.math.maxInt(usize) / count) return Error.Overflow;
            try cur.skip(width * count);
            return;
        }
        var i: usize = 0;
        while (i < count) : (i += 1) {
            switch (item_type) {
                .string => {
                    _ = try cur.readString(hard_max_token_bytes);
                },
                else => return Error.InvalidMetadata,
            }
        }
    }

    pub const GgufOwnedIndex = struct {
        bytes: []const u8,
        version: u32,
        metadata: []MetadataEntry,
        tensors: []TensorDesc,
        tensor_data_offset: usize,
        alignment: usize,
        allocator: std.mem.Allocator,

        pub fn deinit(self: *GgufOwnedIndex) void {
            self.allocator.free(self.metadata);
            self.allocator.free(self.tensors);
            self.* = undefined;
        }

        pub fn metadataEntry(self: GgufOwnedIndex, key: []const u8) ?MetadataEntry {
            for (self.metadata) |e| {
                if (std.mem.eql(u8, e.key, key)) return e;
            }
            return null;
        }

        pub fn scalar(self: GgufOwnedIndex, key: []const u8) ?MetadataScalar {
            const e = self.metadataEntry(key) orelse return null;
            return e.scalar;
        }

        pub fn tensor(self: GgufOwnedIndex, name: []const u8) ?TensorDesc {
            for (self.tensors) |t| {
                if (std.mem.eql(u8, t.name, name)) return t;
            }
            return null;
        }

        pub fn tensorBytes(self: GgufOwnedIndex, desc: TensorDesc) ![]const u8 {
            if (desc.absolute_offset > self.bytes.len) return Error.TensorOutOfBounds;
            if (desc.byte_len > self.bytes.len - desc.absolute_offset) return Error.TensorOutOfBounds;
            const start: usize = @intCast(desc.absolute_offset);
            const end: usize = @intCast(desc.absolute_offset + desc.byte_len);
            return self.bytes[start..end];
        }

        pub fn parse(allocator: std.mem.Allocator, bytes: []const u8) !GgufOwnedIndex {
            var cur = Wave38ByteCursor{ .bytes = bytes };
            const magic = try cur.take(4);
            if (!std.mem.eql(u8, magic, "GGUF")) return Error.InvalidGguf;
            const version = try cur.read(u32);
            if (version < 2 or version > 3) return Error.UnsupportedGgufVersion;
            const tensor_count64 = try cur.read(u64);
            const metadata_count64 = try cur.read(u64);
            if (tensor_count64 > hard_max_tensors or metadata_count64 > hard_max_metadata_entries) return Error.MetadataLimit;
            const tensor_count: usize = @intCast(tensor_count64);
            const metadata_count: usize = @intCast(metadata_count64);

            const metadata = try allocator.alloc(MetadataEntry, metadata_count);
            errdefer allocator.free(metadata);
            const tensors = try allocator.alloc(TensorDesc, tensor_count);
            errdefer allocator.free(tensors);

            var alignment: usize = 32;
            var mi: usize = 0;
            while (mi < metadata_count) : (mi += 1) {
                const key = try cur.readString(hard_max_token_bytes);
                const raw_type = try cur.read(u32);
                const t = std.meta.intToEnum(GgufValueType, raw_type) catch return Error.InvalidMetadata;
                if (t == .array) {
                    const item_raw = try cur.read(u32);
                    const item_type = std.meta.intToEnum(GgufValueType, item_raw) catch return Error.InvalidMetadata;
                    const count64 = try cur.read(u64);
                    if (count64 > hard_max_metadata_entries * 1024) return Error.MetadataLimit;
                    const count: usize = @intCast(count64);
                    const start = cur.pos;
                    try skipArrayPayload(&cur, item_type, count);
                    metadata[mi] = .{
                        .key = key,
                        .value_type = t,
                        .array = .{
                            .item_type = item_type,
                            .count = count,
                            .payload_offset = start,
                            .payload_end = cur.pos,
                        },
                    };
                } else {
                    const s = try parseScalar(&cur, t);
                    metadata[mi] = .{ .key = key, .value_type = t, .scalar = s };
                    if (std.mem.eql(u8, key, "general.alignment")) {
                        if (s.asU64()) |a| {
                            if (a == 0 or a > 4096 or (a & (a - 1)) != 0) return Error.InvalidMetadata;
                            alignment = @intCast(a);
                        }
                    }
                }
            }

            var ti: usize = 0;
            while (ti < tensor_count) : (ti += 1) {
                const name = try cur.readString(hard_max_token_bytes);
                const n_dims = try cur.read(u32);
                if (n_dims == 0 or n_dims > 4) return Error.InvalidTensor;
                var dims: [4]u64 = .{ 0, 0, 0, 0 };
                var di: usize = 0;
                while (di < n_dims) : (di += 1) dims[di] = try cur.read(u64);
                const qtype = try cur.read(u32);
                const off = try cur.read(u64);
                tensors[ti] = .{
                    .name = name,
                    .dims = dims,
                    .n_dims = n_dims,
                    .ggml_type = qtype,
                    .relative_offset = off,
                };
            }

            const aligned = (cur.pos + alignment - 1) & ~(alignment - 1);
            if (aligned > bytes.len) return Error.InvalidGguf;
            var out = GgufOwnedIndex{
                .bytes = bytes,
                .version = version,
                .metadata = metadata,
                .tensors = tensors,
                .tensor_data_offset = aligned,
                .alignment = alignment,
                .allocator = allocator,
            };
            try out.finalizeTensorRanges();
            return out;
        }

        fn finalizeTensorRanges(self: *GgufOwnedIndex) !void {
            for (self.tensors) |*t| {
                if (t.relative_offset > std.math.maxInt(u64) - self.tensor_data_offset) return Error.Overflow;
                t.absolute_offset = @as(u64, @intCast(self.tensor_data_offset)) + t.relative_offset;
                const elements = try t.elementCount();
                t.byte_len = try QuantFormat.tensorBytes(t.ggml_type, elements);
                if (t.absolute_offset > self.bytes.len) return Error.TensorOutOfBounds;
                if (t.byte_len > self.bytes.len - t.absolute_offset) return Error.TensorOutOfBounds;
            }
        }
    };

    pub const QuantFormat = struct {
        pub const F32: u32 = 0;
        pub const F16: u32 = 1;
        pub const Q4_0: u32 = 2;
        pub const Q4_1: u32 = 3;
        pub const Q5_0: u32 = 6;
        pub const Q5_1: u32 = 7;
        pub const Q8_0: u32 = 8;
        pub const Q2_K: u32 = 10;
        pub const Q3_K: u32 = 11;
        pub const Q4_K: u32 = 12;
        pub const Q5_K: u32 = 13;
        pub const Q6_K: u32 = 14;
        pub const Q8_K: u32 = 15;
        pub const BF16: u32 = 30;

        pub const Facts = struct {
            block_values: u32,
            block_bytes: u32,
            name: []const u8,
        };

        pub fn facts(t: u32) ?Facts {
            return switch (t) {
                F32 => .{ .block_values = 1, .block_bytes = 4, .name = "F32" },
                F16 => .{ .block_values = 1, .block_bytes = 2, .name = "F16" },
                BF16 => .{ .block_values = 1, .block_bytes = 2, .name = "BF16" },
                Q4_0 => .{ .block_values = 32, .block_bytes = 18, .name = "Q4_0" },
                Q4_1 => .{ .block_values = 32, .block_bytes = 20, .name = "Q4_1" },
                Q5_0 => .{ .block_values = 32, .block_bytes = 22, .name = "Q5_0" },
                Q5_1 => .{ .block_values = 32, .block_bytes = 24, .name = "Q5_1" },
                Q8_0 => .{ .block_values = 32, .block_bytes = 34, .name = "Q8_0" },
                Q2_K => .{ .block_values = 256, .block_bytes = 84, .name = "Q2_K" },
                Q3_K => .{ .block_values = 256, .block_bytes = 110, .name = "Q3_K" },
                Q4_K => .{ .block_values = 256, .block_bytes = 144, .name = "Q4_K" },
                Q5_K => .{ .block_values = 256, .block_bytes = 176, .name = "Q5_K" },
                Q6_K => .{ .block_values = 256, .block_bytes = 210, .name = "Q6_K" },
                Q8_K => .{ .block_values = 256, .block_bytes = 292, .name = "Q8_K" },
                else => null,
            };
        }

        pub fn tensorBytes(t: u32, elements: u64) !u64 {
            const f = facts(t) orelse return Error.UnsupportedQuantType;
            if (elements % f.block_values != 0) return Error.InvalidQuantBlock;
            const blocks = elements / f.block_values;
            if (blocks > std.math.maxInt(u64) / @as(u64, f.block_bytes)) return Error.Overflow;
            return blocks * @as(u64, f.block_bytes);
        }

        pub fn rowBytes(t: u32, columns: usize) !usize {
            const f = facts(t) orelse return Error.UnsupportedQuantType;
            if (columns % f.block_values != 0) return Error.InvalidQuantBlock;
            const blocks = columns / f.block_values;
            if (blocks > std.math.maxInt(usize) / @as(usize, f.block_bytes)) return Error.Overflow;
            return blocks * @as(usize, f.block_bytes);
        }
    };

    pub fn wave38F16ToF32(bits: u16) f32 {
        const sign: u32 = (@as(u32, bits) & 0x8000) << 16;
        const exp: u32 = (@as(u32, bits) >> 10) & 0x1f;
        const frac: u32 = @as(u32, bits) & 0x03ff;
        var out: u32 = undefined;
        if (exp == 0) {
            if (frac == 0) {
                out = sign;
            } else {
                var f = frac;
                var e: i32 = -14;
                while ((f & 0x400) == 0) {
                    f <<= 1;
                    e -= 1;
                }
                f &= 0x3ff;
                out = sign | (@as(u32, @intCast(e + 127)) << 23) | (f << 13);
            }
        } else if (exp == 31) {
            out = sign | 0x7f800000 | (frac << 13);
        } else {
            out = sign | ((exp + 112) << 23) | (frac << 13);
        }
        return @bitCast(out);
    }

    pub fn bf16ToF32(bits: u16) f32 {
        const raw: u32 = @as(u32, bits) << 16;
        return @bitCast(raw);
    }

    pub fn loadF16(src: []const u8) f32 {
        const b: [2]u8 = .{ src[0], src[1] };
        return wave38F16ToF32(std.mem.readInt(u16, &b, .little));
    }

    pub fn loadF32(src: []const u8) f32 {
        const b: [4]u8 = .{ src[0], src[1], src[2], src[3] };
        return @bitCast(std.mem.readInt(u32, &b, .little));
    }

    pub const ScalarQuant = struct {
        pub fn q4_0(out: []f32, src: []const u8) !void {
            if (out.len % 32 != 0 or src.len != (out.len / 32) * 18) return Error.InvalidQuantBlock;
            var b: usize = 0;
            var oi: usize = 0;
            while (oi < out.len) : ({
                oi += 32;
                b += 18;
            }) {
                const d = loadF16(src[b .. b + 2]);
                var j: usize = 0;
                while (j < 16) : (j += 1) {
                    const q = src[b + 2 + j];
                    out[oi + j] = d * @as(f32, @floatFromInt(@as(i8, @intCast(q & 0x0f)) - 8));
                    out[oi + 16 + j] = d * @as(f32, @floatFromInt(@as(i8, @intCast(q >> 4)) - 8));
                }
            }
        }

        pub fn q4_1(out: []f32, src: []const u8) !void {
            if (out.len % 32 != 0 or src.len != (out.len / 32) * 20) return Error.InvalidQuantBlock;
            var b: usize = 0;
            var oi: usize = 0;
            while (oi < out.len) : ({
                oi += 32;
                b += 20;
            }) {
                const d = loadF16(src[b .. b + 2]);
                const m = loadF16(src[b + 2 .. b + 4]);
                var j: usize = 0;
                while (j < 16) : (j += 1) {
                    const q = src[b + 4 + j];
                    out[oi + j] = d * @as(f32, @floatFromInt(q & 0x0f)) + m;
                    out[oi + 16 + j] = d * @as(f32, @floatFromInt(q >> 4)) + m;
                }
            }
        }

        pub fn q5_0(out: []f32, src: []const u8) !void {
            if (out.len % 32 != 0 or src.len != (out.len / 32) * 22) return Error.InvalidQuantBlock;
            var b: usize = 0;
            var oi: usize = 0;
            while (oi < out.len) : ({
                oi += 32;
                b += 22;
            }) {
                const d = loadF16(src[b .. b + 2]);
                const qh = std.mem.readInt(u32, @ptrCast(src[b + 2 .. b + 6].ptr), .little);
                var j: usize = 0;
                while (j < 16) : (j += 1) {
                    const packed_byte = src[b + 6 + j];
                    const lo0: u8 = packed_byte & 0x0f;
                    const lo1: u8 = packed_byte >> 4;
                    const hi0: u8 = @intCast((qh >> @intCast(j)) & 1);
                    const hi1: u8 = @intCast((qh >> @intCast(j + 16)) & 1);
                    const q0: i32 = @as(i32, lo0 | (hi0 << 4)) - 16;
                    const q1: i32 = @as(i32, lo1 | (hi1 << 4)) - 16;
                    out[oi + j] = d * @as(f32, @floatFromInt(q0));
                    out[oi + 16 + j] = d * @as(f32, @floatFromInt(q1));
                }
            }
        }

        pub fn q5_1(out: []f32, src: []const u8) !void {
            if (out.len % 32 != 0 or src.len != (out.len / 32) * 24) return Error.InvalidQuantBlock;
            var b: usize = 0;
            var oi: usize = 0;
            while (oi < out.len) : ({
                oi += 32;
                b += 24;
            }) {
                const d = loadF16(src[b .. b + 2]);
                const m = loadF16(src[b + 2 .. b + 4]);
                const qh = std.mem.readInt(u32, @ptrCast(src[b + 4 .. b + 8].ptr), .little);
                var j: usize = 0;
                while (j < 16) : (j += 1) {
                    const packed_byte = src[b + 8 + j];
                    const q0 = (packed_byte & 0x0f) | (@as(u8, @intCast((qh >> @intCast(j)) & 1)) << 4);
                    const q1 = (packed_byte >> 4) | (@as(u8, @intCast((qh >> @intCast(j + 16)) & 1)) << 4);
                    out[oi + j] = d * @as(f32, @floatFromInt(q0)) + m;
                    out[oi + 16 + j] = d * @as(f32, @floatFromInt(q1)) + m;
                }
            }
        }

        pub fn q8_0(out: []f32, src: []const u8) !void {
            if (out.len % 32 != 0 or src.len != (out.len / 32) * 34) return Error.InvalidQuantBlock;
            var b: usize = 0;
            var oi: usize = 0;
            while (oi < out.len) : ({
                oi += 32;
                b += 34;
            }) {
                const d = loadF16(src[b .. b + 2]);
                var j: usize = 0;
                while (j < 32) : (j += 1) {
                    const q: i8 = @bitCast(src[b + 2 + j]);
                    out[oi + j] = d * @as(f32, @floatFromInt(q));
                }
            }
        }

        pub fn decodeF16(out: []f32, src: []const u8) !void {
            if (src.len != out.len * 2) return Error.InvalidQuantBlock;
            for (out, 0..) |*v, i| v.* = loadF16(src[i * 2 .. i * 2 + 2]);
        }

        pub fn bf16(out: []f32, src: []const u8) !void {
            if (src.len != out.len * 2) return Error.InvalidQuantBlock;
            for (out, 0..) |*v, i| {
                const b: [2]u8 = .{ src[i * 2], src[i * 2 + 1] };
                v.* = bf16ToF32(std.mem.readInt(u16, &b, .little));
            }
        }

        pub fn decodeF32(out: []f32, src: []const u8) !void {
            if (src.len != out.len * 4) return Error.InvalidQuantBlock;
            for (out, 0..) |*v, i| v.* = loadF32(src[i * 4 .. i * 4 + 4]);
        }

        pub fn decode(t: u32, out: []f32, src: []const u8) !void {
            switch (t) {
                QuantFormat.F32 => try decodeF32(out, src),
                QuantFormat.F16 => try decodeF16(out, src),
                QuantFormat.BF16 => try bf16(out, src),
                QuantFormat.Q4_0 => try q4_0(out, src),
                QuantFormat.Q4_1 => try q4_1(out, src),
                QuantFormat.Q5_0 => try q5_0(out, src),
                QuantFormat.Q5_1 => try q5_1(out, src),
                QuantFormat.Q8_0 => try q8_0(out, src),
                QuantFormat.Q3_K => try Q3KExact.dequantRow(out, src),
                QuantFormat.Q4_K => try Q4KExact.dequantRow(out, src),
                QuantFormat.Q5_K => {
                    if (out.len % 256 != 0 or src.len != (out.len / 256) * 176) return Error.InvalidQuantBlock;
                    for (0..out.len / 256) |block| {
                        var raw: [176]u8 = undefined;
                        @memcpy(&raw, src[block * 176 .. (block + 1) * 176]);
                        var values: [256]f32 = undefined;
                        Q5KExact.dequantBlock(&values, &raw);
                        @memcpy(out[block * 256 .. (block + 1) * 256], &values);
                    }
                },
                QuantFormat.Q6_K => {
                    if (out.len % 256 != 0 or src.len != (out.len / 256) * 210) return Error.InvalidQuantBlock;
                    for (0..out.len / 256) |block| {
                        var raw: [210]u8 = undefined;
                        @memcpy(&raw, src[block * 210 .. (block + 1) * 210]);
                        var values: [256]f32 = undefined;
                        Q6KExact.dequantBlock(&values, &raw);
                        @memcpy(out[block * 256 .. (block + 1) * 256], &values);
                    }
                },
                else => return Error.UnsupportedQuantType,
            }
        }
    };

    pub const RowView = struct {
        ggml_type: u32,
        bytes: []const u8,
        columns: usize,

        pub fn validate(self: RowView) !void {
            const n = try QuantFormat.rowBytes(self.ggml_type, self.columns);
            if (n != self.bytes.len) return Error.InvalidQuantBlock;
        }

        pub fn wave38Dot(self: RowView, x: []const f32, scratch: []f32) !f32 {
            const quantized = self.ggml_type == QuantFormat.Q3_K or self.ggml_type == QuantFormat.Q4_K or self.ggml_type == QuantFormat.Q5_K or self.ggml_type == QuantFormat.Q6_K;
            if (x.len != self.columns or (!quantized and scratch.len < self.columns)) return Error.ShapeMismatch;
            switch (self.ggml_type) {
                QuantFormat.Q3_K => return Q3KExact.dotRow(self.bytes, x),
                QuantFormat.Q4_K => return Q4KExact.dotRow(self.bytes, x),
                QuantFormat.Q5_K => return Q5KExact.dotRow(self.bytes, x),
                QuantFormat.Q6_K => return Q6KExact.dotRow(self.bytes, x),
                QuantFormat.F32,
                QuantFormat.F16,
                QuantFormat.BF16,
                QuantFormat.Q4_0,
                QuantFormat.Q4_1,
                QuantFormat.Q5_0,
                QuantFormat.Q5_1,
                QuantFormat.Q8_0,
                => {
                    try ScalarQuant.decode(self.ggml_type, scratch[0..self.columns], self.bytes);
                    var acc: f32 = 0;
                    var i: usize = 0;
                    while (i < self.columns) : (i += 1) acc += scratch[i] * x[i];
                    return acc;
                },
                else => return Error.UnsupportedQuantType,
            }
        }
    };

    pub const Wave38MatrixView = struct {
        ggml_type: u32,
        bytes: []const u8,
        rows: usize,
        cols: usize,

        pub fn row(self: Wave38MatrixView, r: usize) !RowView {
            if (r >= self.rows) return Error.ShapeMismatch;
            const rb = try QuantFormat.rowBytes(self.ggml_type, self.cols);
            if (rb > self.bytes.len or r > self.bytes.len / rb) return Error.TensorOutOfBounds;
            const start = r * rb;
            if (start > self.bytes.len or rb > self.bytes.len - start) return Error.TensorOutOfBounds;
            return .{ .ggml_type = self.ggml_type, .bytes = self.bytes[start .. start + rb], .columns = self.cols };
        }

        pub fn apply(self: Wave38MatrixView, out: []f32, x: []const f32, scratch: []f32) !void {
            if (out.len != self.rows or x.len != self.cols or scratch.len < self.cols) return Error.ShapeMismatch;
            const quantized = self.ggml_type == QuantFormat.Q3_K or self.ggml_type == QuantFormat.Q4_K or self.ggml_type == QuantFormat.Q5_K or self.ggml_type == QuantFormat.Q6_K;
            if (quantized and self.rows >= 256) {
                const worker_count = @min(@as(usize, 8), @max(@as(usize, 1), self.rows / 128));
                const chunk = (self.rows + worker_count - 1) / worker_count;
                if (Wave38Llm.matrix_pool) |*pool| {
                    var wait_group: std.Thread.WaitGroup = .{};
                    var worker: usize = 0;
                    while (worker < worker_count) : (worker += 1) {
                        const start = worker * chunk;
                        const end = @min(self.rows, start + chunk);
                        pool.spawnWg(&wait_group, applyQuantizedRows, .{ self, x, out, start, end });
                    }
                    wait_group.wait();
                    return;
                }
            }
            var r: usize = 0;
            while (r < self.rows) : (r += 1) out[r] = try (try self.row(r)).wave38Dot(x, scratch);
        }

        fn applyQuantizedRows(self: Wave38MatrixView, x: []const f32, out: []f32, start: usize, end: usize) void {
            var scratch: [1]f32 = undefined;
            var r = start;
            while (r < end) : (r += 1) out[r] = (self.row(r) catch unreachable).wave38Dot(x, &scratch) catch unreachable;
        }
    };

    pub const TensorCatalog = struct {
        index: *const GgufOwnedIndex,

        pub fn matrix(self: TensorCatalog, name: []const u8) !Wave38MatrixView {
            const t = self.index.tensor(name) orelse return Error.TensorNotFound;
            if (t.n_dims != 2) return Error.ShapeMismatch;
            return .{
                .ggml_type = t.ggml_type,
                .bytes = try self.index.tensorBytes(t),
                .rows = @intCast(t.dims[1]),
                .cols = @intCast(t.dims[0]),
            };
        }

        pub fn vectorF32(self: TensorCatalog, allocator: std.mem.Allocator, name: []const u8) ![]f32 {
            const t = self.index.tensor(name) orelse return Error.TensorNotFound;
            if (t.n_dims != 1) return Error.ShapeMismatch;
            const n: usize = @intCast(t.dims[0]);
            const out = try allocator.alloc(f32, n);
            errdefer allocator.free(out);
            try ScalarQuant.decode(t.ggml_type, out, try self.index.tensorBytes(t));
            return out;
        }

        pub fn embedding(self: TensorCatalog, name: []const u8) !Wave38MatrixView {
            return self.matrix(name);
        }
    };

    pub const LlamaMetadata = struct {
        context_length: usize,
        embedding_length: usize,
        feed_forward_length: usize,
        block_count: usize,
        head_count: usize,
        head_count_kv: usize,
        rope_dimension_count: usize,
        rope_freq_base: f32,
        rms_epsilon: f32,
        vocab_size: usize,
        bos_id: u32,
        eos_id: u32,
        eot_id: ?u32,
        tokenizer_model: []const u8,

        fn getU(index: GgufOwnedIndex, key: []const u8) ?usize {
            const v = index.scalar(key) orelse return null;
            const n = v.asU64() orelse return null;
            if (n > std.math.maxInt(usize)) return null;
            return @intCast(n);
        }

        fn getF(index: GgufOwnedIndex, key: []const u8) ?f32 {
            const v = index.scalar(key) orelse return null;
            const n = v.asF64() orelse return null;
            return @floatCast(n);
        }

        fn getArrayCount(index: GgufOwnedIndex, key: []const u8) ?usize {
            const e = index.metadataEntry(key) orelse return null;
            const a = e.array orelse return null;
            return a.count;
        }

        pub fn fromIndex(index: GgufOwnedIndex) !LlamaMetadata {
            const context_length = getU(index, "llama.context_length") orelse return Error.InvalidArchitecture;
            const embedding_length = getU(index, "llama.embedding_length") orelse return Error.InvalidArchitecture;
            const feed_forward_length = getU(index, "llama.feed_forward_length") orelse return Error.InvalidArchitecture;
            const block_count = getU(index, "llama.block_count") orelse return Error.InvalidArchitecture;
            const head_count = getU(index, "llama.attention.head_count") orelse return Error.InvalidArchitecture;
            const head_count_kv = getU(index, "llama.attention.head_count_kv") orelse head_count;
            const rope_dimension_count = getU(index, "llama.rope.dimension_count") orelse embedding_length / head_count;
            const rope_freq_base = getF(index, "llama.rope.freq_base") orelse 500000.0;
            const rms_epsilon = getF(index, "llama.attention.layer_norm_rms_epsilon") orelse 0.00001;
            const vocab_size = getU(index, "llama.vocab_size") orelse getArrayCount(index, "tokenizer.ggml.tokens") orelse llama3_vocab_hint;
            const bos_id: u32 = @intCast(getU(index, "tokenizer.ggml.bos_token_id") orelse 128000);
            const eos_id: u32 = @intCast(getU(index, "tokenizer.ggml.eos_token_id") orelse 128001);
            const eot_id: ?u32 = if (getU(index, "tokenizer.ggml.eot_token_id")) |v| @intCast(v) else null;
            const tokenizer_model = if (index.scalar("tokenizer.ggml.model")) |s| s.asString() orelse "" else "";
            var out = LlamaMetadata{
                .context_length = context_length,
                .embedding_length = embedding_length,
                .feed_forward_length = feed_forward_length,
                .block_count = block_count,
                .head_count = head_count,
                .head_count_kv = head_count_kv,
                .rope_dimension_count = rope_dimension_count,
                .rope_freq_base = rope_freq_base,
                .rms_epsilon = rms_epsilon,
                .vocab_size = vocab_size,
                .bos_id = bos_id,
                .eos_id = eos_id,
                .eot_id = eot_id,
                .tokenizer_model = tokenizer_model,
            };
            try out.validate();
            return out;
        }

        pub fn headDim(self: LlamaMetadata) usize {
            return self.embedding_length / self.head_count;
        }

        pub fn kvWidth(self: LlamaMetadata) usize {
            return self.head_count_kv * self.headDim();
        }

        pub fn validate(self: LlamaMetadata) !void {
            if (self.context_length == 0 or self.context_length > hard_max_context) return Error.InvalidArchitecture;
            if (self.embedding_length == 0 or self.feed_forward_length == 0 or self.block_count == 0) return Error.InvalidArchitecture;
            if (self.head_count == 0 or self.head_count_kv == 0) return Error.InvalidArchitecture;
            if (self.embedding_length % self.head_count != 0) return Error.InvalidArchitecture;
            if (self.head_count % self.head_count_kv != 0) return Error.InvalidArchitecture;
            if (self.rope_dimension_count == 0 or self.rope_dimension_count > self.headDim()) return Error.InvalidArchitecture;
            if (!(self.rms_epsilon > 0) or !std.math.isFinite(self.rms_epsilon)) return Error.InvalidArchitecture;
        }
    };

    pub fn fnv1a64(bytes: []const u8) u64 {
        var h: u64 = 0xcbf29ce484222325;
        for (bytes) |b| {
            h ^= b;
            h *%= 0x100000001b3;
        }
        return h;
    }

    pub const TokenKind = enum(u8) {
        normal,
        unknown,
        control,
        user_defined,
        unused,
        byte,
        special,
    };

    pub const TokenRecord = struct {
        text: []const u8,
        score: f32 = 0,
        kind: TokenKind = .normal,
    };

    pub const TokenHashSlot = struct {
        hash: u64 = 0,
        token_id_plus_one: u32 = 0,
    };

    pub const Vocab = struct {
        allocator: std.mem.Allocator,
        tokens: []TokenRecord,
        slots: []TokenHashSlot,

        pub fn init(allocator: std.mem.Allocator, tokens: []const TokenRecord) !Vocab {
            const owned = try allocator.dupe(TokenRecord, tokens);
            errdefer allocator.free(owned);
            var cap: usize = 1;
            while (cap < @max(@as(usize, 8), tokens.len * 2)) cap <<= 1;
            const slots = try allocator.alloc(TokenHashSlot, cap);
            @memset(slots, .{});
            var self = Vocab{ .allocator = allocator, .tokens = owned, .slots = slots };
            errdefer {
                allocator.free(owned);
                allocator.free(slots);
            }
            for (tokens, 0..) |t, id| try self.insert(t.text, @intCast(id));
            return self;
        }

        pub fn deinit(self: *Vocab) void {
            self.allocator.free(self.tokens);
            self.allocator.free(self.slots);
            self.* = undefined;
        }

        fn insert(self: *Vocab, text: []const u8, id: u32) !void {
            if (self.slots.len == 0) return Error.InvalidTokenizer;
            const h = fnv1a64(text);
            var idx = @as(usize, @intCast(h)) & (self.slots.len - 1);
            var probes: usize = 0;
            while (probes < self.slots.len) : (probes += 1) {
                if (self.slots[idx].token_id_plus_one == 0) {
                    self.slots[idx] = .{ .hash = h, .token_id_plus_one = id + 1 };
                    return;
                }
                idx = (idx + 1) & (self.slots.len - 1);
            }
            return Error.InvalidTokenizer;
        }

        pub fn find(self: Vocab, text: []const u8) ?u32 {
            if (self.slots.len == 0) return null;
            const h = fnv1a64(text);
            var idx = @as(usize, @intCast(h)) & (self.slots.len - 1);
            var probes: usize = 0;
            while (probes < self.slots.len) : (probes += 1) {
                const s = self.slots[idx];
                if (s.token_id_plus_one == 0) return null;
                if (s.hash == h) {
                    const id = s.token_id_plus_one - 1;
                    if (id < self.tokens.len and std.mem.eql(u8, self.tokens[id].text, text)) return id;
                }
                idx = (idx + 1) & (self.slots.len - 1);
            }
            return null;
        }

        pub fn token(self: Vocab, id: u32) ?TokenRecord {
            if (id >= self.tokens.len) return null;
            return self.tokens[id];
        }
    };

    pub const SpecialToken = struct {
        text: []const u8,
        id: u32,
    };

    pub const SpecialMatcher = struct {
        specials: []const SpecialToken,

        pub const Match = struct { start: usize, end: usize, id: u32 };

        pub fn findNext(self: SpecialMatcher, text: []const u8, from: usize) ?Match {
            if (from >= text.len) return null;
            var best: ?Match = null;
            for (self.specials) |sp| {
                if (sp.text.len == 0) continue;
                var i = from;
                while (i + sp.text.len <= text.len) : (i += 1) {
                    if (std.mem.eql(u8, text[i .. i + sp.text.len], sp.text)) {
                        const m = Match{ .start = i, .end = i + sp.text.len, .id = sp.id };
                        if (best == null or m.start < best.?.start or (m.start == best.?.start and (m.end - m.start) > (best.?.end - best.?.start))) best = m;
                        break;
                    }
                }
            }
            return best;
        }
    };

    pub const Utf8 = struct {
        pub fn scalarLength(first: u8) usize {
            if (first < 0x80) return 1;
            if ((first & 0xe0) == 0xc0) return 2;
            if ((first & 0xf0) == 0xe0) return 3;
            if ((first & 0xf8) == 0xf0) return 4;
            return 0;
        }

        pub fn validScalar(bytes: []const u8) bool {
            if (bytes.len == 0) return false;
            const n = scalarLength(bytes[0]);
            if (n == 0 or n != bytes.len) return false;
            if (n == 1) return true;
            var cp: u32 = switch (n) {
                2 => bytes[0] & 0x1f,
                3 => bytes[0] & 0x0f,
                4 => bytes[0] & 0x07,
                else => return false,
            };
            for (bytes[1..]) |b| {
                if ((b & 0xc0) != 0x80) return false;
                cp = (cp << 6) | (b & 0x3f);
            }
            if (n == 2 and cp < 0x80) return false;
            if (n == 3 and cp < 0x800) return false;
            if (n == 4 and cp < 0x10000) return false;
            if (cp > 0x10ffff) return false;
            if (cp >= 0xd800 and cp <= 0xdfff) return false;
            return true;
        }

        pub fn validate(bytes: []const u8) bool {
            var i: usize = 0;
            while (i < bytes.len) {
                const n = scalarLength(bytes[i]);
                if (n == 0 or i + n > bytes.len or !validScalar(bytes[i .. i + n])) return false;
                i += n;
            }
            return true;
        }

        pub fn nextBoundary(bytes: []const u8, start: usize) usize {
            if (start >= bytes.len) return bytes.len;
            const n = scalarLength(bytes[start]);
            if (n == 0 or start + n > bytes.len) return start + 1;
            return start + n;
        }
    };

    pub const PretokenPiece = struct {
        start: usize,
        end: usize,
        special_id: ?u32 = null,
    };

    pub const Llama3Pretoken = struct {
        pub fn classifyByte(b: u8) enum { alpha, digit, space, punct, utf8 } {
            if ((b >= 'A' and b <= 'Z') or (b >= 'a' and b <= 'z')) return .alpha;
            if (b >= '0' and b <= '9') return .digit;
            if (b == ' ' or b == '\n' or b == '\r' or b == '\t') return .space;
            if (b >= 0x80) return .utf8;
            return .punct;
        }

        pub fn split(allocator: std.mem.Allocator, input: []const u8, specials: SpecialMatcher) ![]PretokenPiece {
            var out = std.ArrayList(PretokenPiece).empty;
            errdefer out.deinit(allocator);
            var cursor: usize = 0;
            while (cursor < input.len) {
                if (specials.findNext(input, cursor)) |m| {
                    if (m.start > cursor) try splitPlain(allocator, &out, input, cursor, m.start);
                    try out.append(allocator, .{ .start = m.start, .end = m.end, .special_id = m.id });
                    cursor = m.end;
                } else {
                    try splitPlain(allocator, &out, input, cursor, input.len);
                    break;
                }
            }
            return try out.toOwnedSlice(allocator);
        }

        fn splitPlain(allocator: std.mem.Allocator, out: *std.ArrayList(PretokenPiece), input: []const u8, start: usize, end: usize) !void {
            var i = start;
            while (i < end) {
                // Llama 3 BPE includes one leading space in word pieces.
                const leading_space = input[i] == ' ' and i + 1 < end and (classifyByte(input[i + 1]) == .alpha or classifyByte(input[i + 1]) == .utf8);
                const cls = classifyByte(input[i + @as(usize, if (leading_space) 1 else 0)]);
                var j = i + 1 + @as(usize, if (leading_space) 1 else 0);
                switch (cls) {
                    .utf8 => {
                        j = Utf8.nextBoundary(input, i + @as(usize, if (leading_space) 1 else 0));
                        while (j < end and input[j] >= 0x80) j = Utf8.nextBoundary(input, j);
                    },
                    .alpha => while (j < end and classifyByte(input[j]) == .alpha) : (j += 1) {},
                    .digit => {
                        var count: usize = 1;
                        while (j < end and classifyByte(input[j]) == .digit and count < 3) : ({
                            j += 1;
                            count += 1;
                        }) {}
                    },
                    .space => while (j < end and classifyByte(input[j]) == .space) : (j += 1) {},
                    .punct => while (j < end and classifyByte(input[j]) == .punct) : (j += 1) {},
                }
                try out.append(allocator, .{ .start = i, .end = j });
                i = j;
            }
        }
    };

    pub const MergeRule = struct {
        left: u32,
        right: u32,
        merged: u32,
        rank: u32,
    };

    pub const MergeTable = struct {
        rules: []const MergeRule,

        pub fn lookup(self: MergeTable, left: u32, right: u32) ?MergeRule {
            var best: ?MergeRule = null;
            for (self.rules) |r| {
                if (r.left == left and r.right == right) {
                    if (best == null or r.rank < best.?.rank) best = r;
                }
            }
            return best;
        }
    };

    pub const BpeNode = struct {
        token: u32,
        prev: ?usize,
        next: ?usize,
        alive: bool = true,
    };

    pub const MergeCandidate = struct {
        rank: u32,
        left_index: usize,
        right_index: usize,
        merged: u32,
    };

    pub const MergeHeap = struct {
        items: std.ArrayList(MergeCandidate) = .empty,

        fn less(a: MergeCandidate, b: MergeCandidate) bool {
            if (a.rank != b.rank) return a.rank < b.rank;
            if (a.left_index != b.left_index) return a.left_index < b.left_index;
            return a.right_index < b.right_index;
        }

        pub fn deinit(self: *MergeHeap, allocator: std.mem.Allocator) void {
            self.items.deinit(allocator);
        }

        pub fn push(self: *MergeHeap, allocator: std.mem.Allocator, item: MergeCandidate) !void {
            try self.items.append(allocator, item);
            var i = self.items.items.len - 1;
            while (i > 0) {
                const p = (i - 1) / 2;
                if (!less(self.items.items[i], self.items.items[p])) break;
                std.mem.swap(MergeCandidate, &self.items.items[i], &self.items.items[p]);
                i = p;
            }
        }

        pub fn pop(self: *MergeHeap) ?MergeCandidate {
            if (self.items.items.len == 0) return null;
            const out = self.items.items[0];
            const last = self.items.pop() orelse return out;
            if (self.items.items.len == 0) return out;
            self.items.items[0] = last;
            var i: usize = 0;
            while (true) {
                const l = i * 2 + 1;
                const r = l + 1;
                if (l >= self.items.items.len) break;
                var c = l;
                if (r < self.items.items.len and less(self.items.items[r], self.items.items[l])) c = r;
                if (!less(self.items.items[c], self.items.items[i])) break;
                std.mem.swap(MergeCandidate, &self.items.items[i], &self.items.items[c]);
                i = c;
            }
            return out;
        }
    };

    pub const BpeEncoder = struct {
        vocab: Vocab,
        merges: MergeTable,
        byte_tokens: [256]?u32,

        pub fn initialByteTokens(self: BpeEncoder, allocator: std.mem.Allocator, bytes: []const u8) ![]u32 {
            var out = std.ArrayList(u32).empty;
            errdefer out.deinit(allocator);
            for (bytes) |b| {
                const tok = self.byte_tokens[b] orelse return Error.InvalidToken;
                try out.append(allocator, tok);
            }
            return try out.toOwnedSlice(allocator);
        }

        fn enqueueAround(self: BpeEncoder, allocator: std.mem.Allocator, heap: *MergeHeap, nodes: []const BpeNode, idx: usize) !void {
            if (!nodes[idx].alive) return;
            if (nodes[idx].next) |ri| {
                if (nodes[ri].alive) {
                    if (self.merges.lookup(nodes[idx].token, nodes[ri].token)) |r| {
                        try heap.push(allocator, .{ .rank = r.rank, .left_index = idx, .right_index = ri, .merged = r.merged });
                    }
                }
            }
            if (nodes[idx].prev) |li| {
                if (nodes[li].alive) {
                    if (self.merges.lookup(nodes[li].token, nodes[idx].token)) |r| {
                        try heap.push(allocator, .{ .rank = r.rank, .left_index = li, .right_index = idx, .merged = r.merged });
                    }
                }
            }
        }

        pub fn merge(self: BpeEncoder, allocator: std.mem.Allocator, initial: []const u32) ![]u32 {
            if (initial.len == 0) return allocator.alloc(u32, 0);
            const nodes = try allocator.alloc(BpeNode, initial.len);
            defer allocator.free(nodes);
            for (initial, 0..) |tok, i| {
                nodes[i] = .{
                    .token = tok,
                    .prev = if (i == 0) null else i - 1,
                    .next = if (i + 1 == initial.len) null else i + 1,
                    .alive = true,
                };
            }
            var heap = MergeHeap{};
            defer heap.deinit(allocator);
            var i: usize = 0;
            while (i + 1 < nodes.len) : (i += 1) try self.enqueueAround(allocator, &heap, nodes, i);

            while (heap.pop()) |c| {
                if (c.left_index >= nodes.len or c.right_index >= nodes.len) continue;
                if (!nodes[c.left_index].alive or !nodes[c.right_index].alive) continue;
                if (nodes[c.left_index].next != c.right_index or nodes[c.right_index].prev != c.left_index) continue;
                const rule = self.merges.lookup(nodes[c.left_index].token, nodes[c.right_index].token) orelse continue;
                if (rule.rank != c.rank or rule.merged != c.merged) continue;

                nodes[c.left_index].token = c.merged;
                const right_next = nodes[c.right_index].next;
                nodes[c.left_index].next = right_next;
                nodes[c.right_index].alive = false;
                if (right_next) |n| nodes[n].prev = c.left_index;
                try self.enqueueAround(allocator, &heap, nodes, c.left_index);
            }

            var out = std.ArrayList(u32).empty;
            errdefer out.deinit(allocator);
            var head: usize = 0;
            while (nodes[head].prev != null) head = nodes[head].prev.?;
            var cur: ?usize = head;
            while (cur) |idx| {
                if (nodes[idx].alive) try out.append(allocator, nodes[idx].token);
                cur = nodes[idx].next;
            }
            return try out.toOwnedSlice(allocator);
        }

        pub fn encodePiece(self: BpeEncoder, allocator: std.mem.Allocator, bytes: []const u8) ![]u32 {
            if (std.ascii.isAscii(bytes)) if (self.vocab.find(bytes)) |tok| {
                const out = try allocator.alloc(u32, 1);
                out[0] = tok;
                return out;
            };
            const initial = try self.initialByteTokens(allocator, bytes);
            defer allocator.free(initial);
            return self.merge(allocator, initial);
        }
    };

    pub const Tokenizer = struct {
        allocator: std.mem.Allocator,
        vocab: Vocab,
        bpe: BpeEncoder,
        specials: []SpecialToken,
        owned_merges: []MergeRule,

        pub fn deinit(self: *Tokenizer) void {
            self.vocab.deinit();
            self.allocator.free(self.specials);
            self.allocator.free(self.owned_merges);
            self.* = undefined;
        }

        pub fn fromIndex(allocator: std.mem.Allocator, index: GgufOwnedIndex) !Tokenizer {
            const token_entry = index.metadataEntry("tokenizer.ggml.tokens") orelse return Error.InvalidTokenizer;
            const token_array = token_entry.array orelse return Error.InvalidTokenizer;
            if (token_array.item_type != .string) return Error.InvalidTokenizer;
            const tokens = try allocator.alloc(TokenRecord, token_array.count);
            errdefer allocator.free(tokens);
            var cur = Wave38ByteCursor{ .bytes = index.bytes, .pos = token_array.payload_offset };
            for (tokens) |*record| record.* = .{ .text = try cur.readString(hard_max_token_bytes) };
            var vocab = try Vocab.init(allocator, tokens);
            errdefer vocab.deinit();
            allocator.free(tokens);

            const byte_tokens = Wave38TokenizerIo.Gpt2ByteMap.build(vocab);

            var merges = std.ArrayList(MergeRule).empty;
            errdefer merges.deinit(allocator);
            if (index.metadataEntry("tokenizer.ggml.merges")) |merge_entry| if (merge_entry.array) |merge_array| {
                if (merge_array.item_type == .string) {
                    var mc = Wave38ByteCursor{ .bytes = index.bytes, .pos = merge_array.payload_offset };
                    var rank: u32 = 0;
                    while (rank < merge_array.count) : (rank += 1) {
                        const line = try mc.readString(hard_max_token_bytes);
                        if (std.mem.indexOfScalar(u8, line, ' ')) |split| {
                            const left = vocab.find(line[0..split]) orelse continue;
                            const right = vocab.find(line[split + 1 ..]) orelse continue;
                            const merged_text = try std.mem.concat(allocator, u8, &.{ line[0..split], line[split + 1 ..] });
                            defer allocator.free(merged_text);
                            const merged = vocab.find(merged_text) orelse continue;
                            try merges.append(allocator, .{ .left = left, .right = right, .merged = merged, .rank = rank });
                        }
                    }
                }
            };
            const owned_merges = try merges.toOwnedSlice(allocator);
            errdefer allocator.free(owned_merges);
            var special_list = std.ArrayList(SpecialToken).empty;
            errdefer special_list.deinit(allocator);
            for ([_][]const u8{ "<|begin_of_text|>", "<|end_of_text|>", "<|eot_id|>", "<|start_header_id|>", "<|end_header_id|>", "<|im_start|>", "<|im_end|>", "<|endoftext|>" }) |text| {
                if (vocab.find(text)) |id| try special_list.append(allocator, .{ .text = text, .id = id });
            }
            const specials = try special_list.toOwnedSlice(allocator);
            return .{ .allocator = allocator, .vocab = vocab, .bpe = .{ .vocab = vocab, .merges = .{ .rules = owned_merges }, .byte_tokens = byte_tokens }, .specials = specials, .owned_merges = owned_merges };
        }

        pub fn encode(self: *Tokenizer, input: []const u8, allow_special: bool) ![]u32 {
            const matcher = SpecialMatcher{ .specials = if (allow_special) self.specials else &[_]SpecialToken{} };
            const pieces = try Llama3Pretoken.split(self.allocator, input, matcher);
            defer self.allocator.free(pieces);
            var out = std.ArrayList(u32).empty;
            errdefer out.deinit(self.allocator);
            for (pieces) |piece| {
                if (piece.special_id) |id| {
                    try out.append(self.allocator, id);
                } else if (piece.end > piece.start) {
                    const toks = try self.bpe.encodePiece(self.allocator, input[piece.start..piece.end]);
                    defer self.allocator.free(toks);
                    try out.appendSlice(self.allocator, toks);
                }
            }
            return try out.toOwnedSlice(self.allocator);
        }

        pub fn decode(self: *Tokenizer, token_ids: []const u32) ![]u8 {
            var out = std.ArrayList(u8).empty;
            errdefer out.deinit(self.allocator);
            for (token_ids) |id| {
                const rec = self.vocab.token(id) orelse return Error.InvalidToken;
                if (rec.kind == .control or rec.kind == .special) continue;
                if (std.mem.startsWith(u8, rec.text, "<|")) continue;
                var iterator = (try std.unicode.Utf8View.init(rec.text)).iterator();
                while (iterator.nextCodepoint()) |cp| {
                    var decoded: ?u8 = null;
                    for (0..256) |byte| {
                        if (Wave38TokenizerIo.Gpt2ByteMap.codepointForByte(@intCast(byte)) == cp) {
                            decoded = @intCast(byte);
                            break;
                        }
                    }
                    if (decoded) |byte| try out.append(self.allocator, byte) else return Error.InvalidTokenizer;
                }
            }
            return try out.toOwnedSlice(self.allocator);
        }
    };

    pub const ChatRole = enum { system, user, assistant, tool };

    pub const Wave38ChatMessage = struct {
        role: ChatRole,
        content: []const u8,
        name: ?[]const u8 = null,
    };

    pub const Llama3Chat = struct {
        pub fn roleName(role: ChatRole) []const u8 {
            return switch (role) {
                .system => "system",
                .user => "user",
                .assistant => "assistant",
                .tool => "tool",
            };
        }

        pub fn render(allocator: std.mem.Allocator, messages: []const Wave38ChatMessage, add_assistant_header: bool) ![]u8 {
            var out = std.ArrayList(u8).empty;
            errdefer out.deinit(allocator);
            try out.appendSlice(allocator, "<|begin_of_text|>");
            for (messages) |m| {
                try out.appendSlice(allocator, "<|start_header_id|>");
                try out.appendSlice(allocator, roleName(m.role));
                try out.appendSlice(allocator, "<|end_header_id|>\n\n");
                if (m.name) |name| {
                    try out.appendSlice(allocator, "name=");
                    try out.appendSlice(allocator, name);
                    try out.append(allocator, '\n');
                }
                try out.appendSlice(allocator, m.content);
                try out.appendSlice(allocator, "<|eot_id|>");
            }
            if (add_assistant_header) {
                try out.appendSlice(allocator, "<|start_header_id|>assistant<|end_header_id|>\n\n");
            }
            return try out.toOwnedSlice(allocator);
        }
    };

    pub const ModelChat = struct {
        pub fn render(allocator: std.mem.Allocator, vocab: Vocab, messages: []const Wave38ChatMessage, assistant: bool) ![]u8 {
            if (vocab.find("<|im_start|>") != null and vocab.find("<|im_end|>") != null) {
                var out = std.ArrayList(u8).empty;
                errdefer out.deinit(allocator);
                for (messages) |message| {
                    try out.appendSlice(allocator, "<|im_start|>");
                    try out.appendSlice(allocator, Llama3Chat.roleName(message.role));
                    try out.append(allocator, '\n');
                    try out.appendSlice(allocator, message.content);
                    try out.appendSlice(allocator, "<|im_end|>\n");
                }
                if (assistant) try out.appendSlice(allocator, "<|im_start|>assistant\n");
                return out.toOwnedSlice(allocator);
            }
            if (vocab.find("<|start_header_id|>") != null and vocab.find("<|end_header_id|>") != null) return Llama3Chat.render(allocator, messages, assistant);
            return Error.InvalidTokenizer;
        }
    };

    pub const RopeScaling = struct {
        enabled: bool = false,
        factor: f32 = 1,
        low_freq_factor: f32 = 1,
        high_freq_factor: f32 = 1,
        original_context: f32 = 8192,

        pub fn scaledFrequency(self: RopeScaling, base_freq: f32) f32 {
            if (!self.enabled or self.factor <= 1) return base_freq;
            if (base_freq <= 0) return base_freq;
            const wavelength = 2.0 * std.math.pi / base_freq;
            const low_wavelength = self.original_context / self.low_freq_factor;
            const high_wavelength = self.original_context / self.high_freq_factor;
            if (wavelength < high_wavelength) return base_freq;
            if (wavelength > low_wavelength) return base_freq / self.factor;
            const smooth = (self.original_context / wavelength - self.low_freq_factor) / (self.high_freq_factor - self.low_freq_factor);
            return (1.0 - smooth) * base_freq / self.factor + smooth * base_freq;
        }
    };

    pub const Wave38Rope = struct {
        pub fn apply(head: []f32, position: usize, theta: f32, rope_dims: usize, scaling: RopeScaling) !void {
            if (rope_dims > head.len or rope_dims % 2 != 0) return Error.ShapeMismatch;
            var i: usize = 0;
            while (i < rope_dims) : (i += 2) {
                const exponent = @as(f32, @floatFromInt(i)) / @as(f32, @floatFromInt(rope_dims));
                var freq = 1.0 / std.math.pow(f32, theta, exponent);
                freq = scaling.scaledFrequency(freq);
                const angle = @as(f32, @floatFromInt(position)) * freq;
                const c = @cos(angle);
                const s = @sin(angle);
                const x0 = head[i];
                const x1 = head[i + 1];
                head[i] = x0 * c - x1 * s;
                head[i + 1] = x0 * s + x1 * c;
            }
        }
    };

    pub fn rmsNormInto(out: []f32, x: []const f32, weight: []const f32, eps: f32) !void {
        if (out.len != x.len or x.len != weight.len or x.len == 0) return Error.ShapeMismatch;
        var sum: f64 = 0;
        for (x) |v| sum += @as(f64, v) * @as(f64, v);
        const mean: f32 = @floatCast(sum / @as(f64, @floatFromInt(x.len)));
        const inv = 1.0 / @sqrt(mean + eps);
        for (out, x, weight) |*o, v, w| o.* = v * inv * w;
    }

    pub fn softmaxStable(x: []f32) !void {
        if (x.len == 0) return Error.EmptyDistribution;
        var maxv = x[0];
        for (x[1..]) |v| {
            if (v > maxv) maxv = v;
        }
        var sum: f64 = 0;
        for (x) |*v| {
            v.* = @exp(v.* - maxv);
            sum += v.*;
        }
        if (!(sum > 0) or !std.math.isFinite(sum)) return Error.NonFinite;
        const inv: f32 = @floatCast(1.0 / sum);
        for (x) |*v| v.* *= inv;
    }

    pub const KvLayout = enum { layer_major, token_major };

    pub const SlidingKvCache = struct {
        allocator: std.mem.Allocator,
        layers: usize,
        capacity: usize,
        kv_heads: usize,
        head_dim: usize,
        keys: []f32,
        values: []f32,
        positions: []usize,
        valid: []bool,
        next_slot: usize = 0,
        count: usize = 0,

        pub fn init(allocator: std.mem.Allocator, layers: usize, capacity: usize, kv_heads: usize, head_dim: usize) !SlidingKvCache {
            if (layers == 0 or capacity == 0 or kv_heads == 0 or head_dim == 0) return Error.CacheCapacity;
            const per_token = kv_heads * head_dim;
            if (layers > std.math.maxInt(usize) / capacity) return Error.Overflow;
            const token_layers = layers * capacity;
            if (token_layers > std.math.maxInt(usize) / per_token) return Error.Overflow;
            const total = token_layers * per_token;
            const keys = try allocator.alloc(f32, total);
            errdefer allocator.free(keys);
            const values = try allocator.alloc(f32, total);
            errdefer allocator.free(values);
            const positions = try allocator.alloc(usize, capacity);
            errdefer allocator.free(positions);
            const valid = try allocator.alloc(bool, capacity);
            @memset(valid, false);
            return .{
                .allocator = allocator,
                .layers = layers,
                .capacity = capacity,
                .kv_heads = kv_heads,
                .head_dim = head_dim,
                .keys = keys,
                .values = values,
                .positions = positions,
                .valid = valid,
            };
        }

        pub fn deinit(self: *SlidingKvCache) void {
            self.allocator.free(self.keys);
            self.allocator.free(self.values);
            self.allocator.free(self.positions);
            self.allocator.free(self.valid);
            self.* = undefined;
        }

        fn vectorOffset(self: SlidingKvCache, layer: usize, slot: usize, head: usize) !usize {
            if (layer >= self.layers or slot >= self.capacity or head >= self.kv_heads) return Error.ShapeMismatch;
            const per_token = self.kv_heads * self.head_dim;
            return ((layer * self.capacity + slot) * per_token) + head * self.head_dim;
        }

        pub fn reservePosition(self: *SlidingKvCache, position: usize) usize {
            const slot = self.next_slot;
            self.positions[slot] = position;
            self.valid[slot] = true;
            self.next_slot = (self.next_slot + 1) % self.capacity;
            if (self.count < self.capacity) self.count += 1;
            return slot;
        }

        pub fn store(self: *SlidingKvCache, layer: usize, slot: usize, head: usize, key_values: []const f32, value_values: []const f32) !void {
            if (key_values.len != self.head_dim or value_values.len != self.head_dim) return Error.ShapeMismatch;
            const off = try self.vectorOffset(layer, slot, head);
            @memcpy(self.keys[off .. off + self.head_dim], key_values);
            @memcpy(self.values[off .. off + self.head_dim], value_values);
        }

        pub fn key(self: SlidingKvCache, layer: usize, slot: usize, head: usize) ![]const f32 {
            const off = try self.vectorOffset(layer, slot, head);
            return self.keys[off .. off + self.head_dim];
        }

        pub fn value(self: SlidingKvCache, layer: usize, slot: usize, head: usize) ![]const f32 {
            const off = try self.vectorOffset(layer, slot, head);
            return self.values[off .. off + self.head_dim];
        }

        pub fn chronologicalSlots(self: SlidingKvCache, allocator: std.mem.Allocator, max_position: usize) ![]usize {
            var slots = std.ArrayList(usize).empty;
            errdefer slots.deinit(allocator);
            var i: usize = 0;
            while (i < self.capacity) : (i += 1) {
                if (self.valid[i] and self.positions[i] <= max_position) try slots.append(allocator, i);
            }
            var a: usize = 1;
            while (a < slots.items.len) : (a += 1) {
                var b = a;
                while (b > 0 and self.positions[slots.items[b]] < self.positions[slots.items[b - 1]]) : (b -= 1) {
                    std.mem.swap(usize, &slots.items[b], &slots.items[b - 1]);
                }
            }
            return try slots.toOwnedSlice(allocator);
        }
    };

    pub const Attention = struct {
        pub fn wave38Dot(a: []const f32, b: []const f32) !f32 {
            if (a.len != b.len) return Error.ShapeMismatch;
            var acc: f64 = 0;
            for (a, b) |x, y| acc += @as(f64, x) * @as(f64, y);
            return @floatCast(acc);
        }

        pub fn attendHead(
            allocator: std.mem.Allocator,
            out: []f32,
            query: []const f32,
            cache: SlidingKvCache,
            layer: usize,
            kv_head: usize,
            position: usize,
        ) !void {
            if (out.len != query.len or query.len != cache.head_dim) return Error.ShapeMismatch;
            const slots = try cache.chronologicalSlots(allocator, position);
            defer allocator.free(slots);
            if (slots.len == 0) {
                @memset(out, 0);
                return;
            }
            const scores = try allocator.alloc(f32, slots.len);
            defer allocator.free(scores);
            const scale = 1.0 / @sqrt(@as(f32, @floatFromInt(query.len)));
            for (slots, 0..) |slot, i| scores[i] = try wave38Dot(query, try cache.key(layer, slot, kv_head)) * scale;
            try softmaxStable(scores);
            @memset(out, 0);
            for (slots, 0..) |slot, i| {
                const v = try cache.value(layer, slot, kv_head);
                var d: usize = 0;
                while (d < out.len) : (d += 1) out[d] += scores[i] * v[d];
            }
        }
    };

    pub const ModelScratch = struct {
        allocator: std.mem.Allocator,
        normed: []f32,
        q: []f32,
        k: []f32,
        v: []f32,
        attn: []f32,
        projected: []f32,
        gate: []f32,
        up: []f32,
        activated: []f32,
        down: []f32,
        row_scratch: []f32,

        pub fn init(allocator: std.mem.Allocator, meta: LlamaMetadata) !ModelScratch {
            const hidden = meta.embedding_length;
            const kv = meta.kvWidth();
            const ff = meta.feed_forward_length;
            return .{
                .allocator = allocator,
                .normed = try allocator.alloc(f32, hidden),
                .q = try allocator.alloc(f32, hidden),
                .k = try allocator.alloc(f32, kv),
                .v = try allocator.alloc(f32, kv),
                .attn = try allocator.alloc(f32, hidden),
                .projected = try allocator.alloc(f32, hidden),
                .gate = try allocator.alloc(f32, ff),
                .up = try allocator.alloc(f32, ff),
                .activated = try allocator.alloc(f32, ff),
                .down = try allocator.alloc(f32, hidden),
                .row_scratch = try allocator.alloc(f32, @max(hidden, ff)),
            };
        }

        pub fn deinit(self: *ModelScratch) void {
            const a = self.allocator;
            a.free(self.normed);
            a.free(self.q);
            a.free(self.k);
            a.free(self.v);
            a.free(self.attn);
            a.free(self.projected);
            a.free(self.gate);
            a.free(self.up);
            a.free(self.activated);
            a.free(self.down);
            a.free(self.row_scratch);
            self.* = undefined;
        }
    };

    pub const LayerWeights = struct {
        attn_norm: []const f32,
        wq: Wave38MatrixView,
        wk: Wave38MatrixView,
        wv: Wave38MatrixView,
        wo: Wave38MatrixView,
        ffn_norm: []const f32,
        gate: Wave38MatrixView,
        up: Wave38MatrixView,
        down: Wave38MatrixView,

        pub fn validate(self: LayerWeights, meta: LlamaMetadata) !void {
            const hidden = meta.embedding_length;
            const kv = meta.kvWidth();
            const ff = meta.feed_forward_length;
            if (self.attn_norm.len != hidden or self.ffn_norm.len != hidden) return Error.ShapeMismatch;
            if (self.wq.rows != hidden or self.wq.cols != hidden) return Error.ShapeMismatch;
            if (self.wk.rows != kv or self.wk.cols != hidden) return Error.ShapeMismatch;
            if (self.wv.rows != kv or self.wv.cols != hidden) return Error.ShapeMismatch;
            if (self.wo.rows != hidden or self.wo.cols != hidden) return Error.ShapeMismatch;
            if (self.gate.rows != ff or self.gate.cols != hidden) return Error.ShapeMismatch;
            if (self.up.rows != ff or self.up.cols != hidden) return Error.ShapeMismatch;
            if (self.down.rows != hidden or self.down.cols != ff) return Error.ShapeMismatch;
        }
    };

    pub const BoundModel = struct {
        meta: LlamaMetadata,
        token_embedding: Wave38MatrixView,
        layers: []LayerWeights,
        final_norm: []const f32,
        output: Wave38MatrixView,
        owns_output_alias: bool = false,

        pub fn validate(self: BoundModel) !void {
            try self.meta.validate();
            if (self.layers.len != self.meta.block_count) return Error.ShapeMismatch;
            if (self.token_embedding.rows != self.meta.vocab_size or self.token_embedding.cols != self.meta.embedding_length) return Error.ShapeMismatch;
            if (self.final_norm.len != self.meta.embedding_length) return Error.ShapeMismatch;
            if (self.output.rows != self.meta.vocab_size or self.output.cols != self.meta.embedding_length) return Error.ShapeMismatch;
            for (self.layers) |l| try l.validate(self.meta);
        }
    };

    pub const LayerNameBuffer = struct {
        buf: [128]u8 = undefined,

        pub fn format(self: *LayerNameBuffer, layer: usize, suffix: []const u8) ![]const u8 {
            return try std.fmt.bufPrint(&self.buf, "blk.{d}.{s}", .{ layer, suffix });
        }
    };

    pub const Binder = struct {
        allocator: std.mem.Allocator,
        catalog: TensorCatalog,

        fn loadVector(self: Binder, name: []const u8) ![]f32 {
            return self.catalog.vectorF32(self.allocator, name);
        }

        pub fn bindLayer(self: Binder, meta: LlamaMetadata, layer_idx: usize) !LayerWeights {
            var nb = LayerNameBuffer{};
            const an = try self.loadVector(try nb.format(layer_idx, "attn_norm.weight"));
            errdefer self.allocator.free(an);
            const wq = try self.catalog.matrix(try nb.format(layer_idx, "attn_q.weight"));
            const wk = try self.catalog.matrix(try nb.format(layer_idx, "attn_k.weight"));
            const wv = try self.catalog.matrix(try nb.format(layer_idx, "attn_v.weight"));
            const wo = try self.catalog.matrix(try nb.format(layer_idx, "attn_output.weight"));
            const fnorm = try self.loadVector(try nb.format(layer_idx, "ffn_norm.weight"));
            errdefer self.allocator.free(fnorm);
            const gate = try self.catalog.matrix(try nb.format(layer_idx, "ffn_gate.weight"));
            const up = try self.catalog.matrix(try nb.format(layer_idx, "ffn_up.weight"));
            const down = try self.catalog.matrix(try nb.format(layer_idx, "ffn_down.weight"));
            const layer = LayerWeights{
                .attn_norm = an,
                .wq = wq,
                .wk = wk,
                .wv = wv,
                .wo = wo,
                .ffn_norm = fnorm,
                .gate = gate,
                .up = up,
                .down = down,
            };
            try layer.validate(meta);
            return layer;
        }

        pub fn bind(self: Binder, meta: LlamaMetadata) !BoundModel {
            const embedding = try self.catalog.matrix("token_embd.weight");
            const final_norm = try self.loadVector("output_norm.weight");
            errdefer self.allocator.free(final_norm);
            const output = self.catalog.matrix("output.weight") catch embedding;
            const layers = try self.allocator.alloc(LayerWeights, meta.block_count);
            errdefer self.allocator.free(layers);
            var i: usize = 0;
            errdefer {
                var j: usize = 0;
                while (j < i) : (j += 1) {
                    self.allocator.free(layers[j].attn_norm);
                    self.allocator.free(layers[j].ffn_norm);
                }
            }
            while (i < meta.block_count) : (i += 1) layers[i] = try self.bindLayer(meta, i);
            const out = BoundModel{
                .meta = meta,
                .token_embedding = embedding,
                .layers = layers,
                .final_norm = final_norm,
                .output = output,
                .owns_output_alias = self.catalog.index.tensor("output.weight") == null,
            };
            try out.validate();
            return out;
        }

        pub fn deinitModel(self: Binder, model: *BoundModel) void {
            for (model.layers) |l| {
                self.allocator.free(l.attn_norm);
                self.allocator.free(l.ffn_norm);
            }
            self.allocator.free(model.layers);
            self.allocator.free(model.final_norm);
            model.* = undefined;
        }
    };

    pub const Executor = struct {
        allocator: std.mem.Allocator,
        model: *const BoundModel,
        cache: SlidingKvCache,
        scratch: ModelScratch,
        hidden: []f32,
        normalized: []f32,
        logits: []f32,

        pub fn init(allocator: std.mem.Allocator, model: *const BoundModel, cache_capacity: usize) !Executor {
            try model.validate();
            var cache = try SlidingKvCache.init(allocator, model.meta.block_count, cache_capacity, model.meta.head_count_kv, model.meta.headDim());
            errdefer cache.deinit();
            var scratch = try ModelScratch.init(allocator, model.meta);
            errdefer scratch.deinit();
            const hidden = try allocator.alloc(f32, model.meta.embedding_length);
            errdefer allocator.free(hidden);
            const normalized = try allocator.alloc(f32, model.meta.embedding_length);
            errdefer allocator.free(normalized);
            const logits = try allocator.alloc(f32, model.meta.vocab_size);
            return .{
                .allocator = allocator,
                .model = model,
                .cache = cache,
                .scratch = scratch,
                .hidden = hidden,
                .normalized = normalized,
                .logits = logits,
            };
        }

        pub fn deinit(self: *Executor) void {
            self.cache.deinit();
            self.scratch.deinit();
            self.allocator.free(self.hidden);
            self.allocator.free(self.normalized);
            self.allocator.free(self.logits);
            self.* = undefined;
        }

        fn loadEmbedding(self: *Executor, token: u32) !void {
            if (token >= self.model.meta.vocab_size) return Error.InvalidToken;
            const row = try self.model.token_embedding.row(token);
            try ScalarQuant.decode(row.ggml_type, self.hidden, row.bytes);
        }

        fn swiglu(out: []f32, gate: []const f32, up: []const f32) !void {
            if (out.len != gate.len or gate.len != up.len) return Error.ShapeMismatch;
            for (out, gate, up) |*o, g, u| o.* = (g / (1.0 + @exp(-g))) * u;
        }

        fn layerStep(self: *Executor, layer_idx: usize, position: usize, slot: usize) !void {
            const meta = self.model.meta;
            const layer = self.model.layers[layer_idx];
            try rmsNormInto(self.scratch.normed, self.hidden, layer.attn_norm, meta.rms_epsilon);
            try layer.wq.apply(self.scratch.q, self.scratch.normed, self.scratch.row_scratch);
            try layer.wk.apply(self.scratch.k, self.scratch.normed, self.scratch.row_scratch);
            try layer.wv.apply(self.scratch.v, self.scratch.normed, self.scratch.row_scratch);

            const head_dim = meta.headDim();
            var h: usize = 0;
            while (h < meta.head_count) : (h += 1) {
                try Wave38Rope.apply(
                    self.scratch.q[h * head_dim .. (h + 1) * head_dim],
                    position,
                    meta.rope_freq_base,
                    meta.rope_dimension_count,
                    .{},
                );
            }
            h = 0;
            while (h < meta.head_count_kv) : (h += 1) {
                try Wave38Rope.apply(
                    self.scratch.k[h * head_dim .. (h + 1) * head_dim],
                    position,
                    meta.rope_freq_base,
                    meta.rope_dimension_count,
                    .{},
                );
                try self.cache.store(
                    layer_idx,
                    slot,
                    h,
                    self.scratch.k[h * head_dim .. (h + 1) * head_dim],
                    self.scratch.v[h * head_dim .. (h + 1) * head_dim],
                );
            }

            const group = meta.head_count / meta.head_count_kv;
            h = 0;
            while (h < meta.head_count) : (h += 1) {
                const kvh = h / group;
                try Wave38Llm.Attention.attendHead(
                    self.allocator,
                    self.scratch.attn[h * head_dim .. (h + 1) * head_dim],
                    self.scratch.q[h * head_dim .. (h + 1) * head_dim],
                    self.cache,
                    layer_idx,
                    kvh,
                    position,
                );
            }
            try layer.wo.apply(self.scratch.projected, self.scratch.attn, self.scratch.row_scratch);
            for (self.hidden, self.scratch.projected) |*x, r| x.* += r;

            try rmsNormInto(self.scratch.normed, self.hidden, layer.ffn_norm, meta.rms_epsilon);
            try layer.gate.apply(self.scratch.gate, self.scratch.normed, self.scratch.row_scratch);
            try layer.up.apply(self.scratch.up, self.scratch.normed, self.scratch.row_scratch);
            try Executor.swiglu(self.scratch.activated, self.scratch.gate, self.scratch.up);
            try layer.down.apply(self.scratch.down, self.scratch.activated, self.scratch.row_scratch);
            for (self.hidden, self.scratch.down) |*x, r| x.* += r;
        }

        pub fn forward(self: *Executor, token: u32, position: usize) ![]const f32 {
            return self.forwardInternal(token, position, true);
        }

        fn forwardInternal(self: *Executor, token: u32, position: usize, output_logits: bool) ![]const f32 {
            if (position >= hard_max_context) return Error.ContextExceeded;
            try self.loadEmbedding(token);
            const slot = self.cache.reservePosition(position);
            var l: usize = 0;
            while (l < self.model.layers.len) : (l += 1) try self.layerStep(l, position, slot);
            if (!output_logits) return &.{};
            try rmsNormInto(self.normalized, self.hidden, self.model.final_norm, self.model.meta.rms_epsilon);
            try self.model.output.apply(self.logits, self.normalized, self.scratch.row_scratch);
            return self.logits;
        }

        pub fn prefill(self: *Executor, tokens: []const u32, start_position: usize) ![]const f32 {
            if (tokens.len == 0) return Error.EmptyPrompt;
            var logits: []const f32 = &[_]f32{};
            for (tokens, 0..) |tok, i| logits = try self.forwardInternal(tok, start_position + i, i + 1 == tokens.len);
            return logits;
        }
    };

    pub const XorShift = struct {
        s0: u64,
        s1: u64,

        pub fn init(seed: u64) XorShift {
            var x = seed ^ 0x9e3779b97f4a7c15;
            x ^= x >> 30;
            x *%= 0xbf58476d1ce4e5b9;
            x ^= x >> 27;
            x *%= 0x94d049bb133111eb;
            x ^= x >> 31;
            return .{ .s0 = x, .s1 = x ^ 0xd2b74407b1ce6e93 };
        }

        pub fn next(self: *XorShift) u64 {
            const x = self.s0;
            var y = self.s1;
            self.s0 = y;
            y ^= y << 23;
            self.s1 = y ^ x ^ (y >> 17) ^ (x >> 26);
            return self.s1 +% x;
        }

        pub fn unit(self: *XorShift) f64 {
            return @as(f64, @floatFromInt(self.next() >> 11)) * (1.0 / 9007199254740992.0);
        }
    };

    pub const SamplingConfig = struct {
        temperature: f32 = 0.8,
        top_k: usize = 40,
        top_p: f32 = 0.95,
        min_p: f32 = 0.0,
        repeat_penalty: f32 = 1.05,
        frequency_penalty: f32 = 0,
        presence_penalty: f32 = 0,
        repeat_last_n: usize = 64,
        seed: u64 = 0x4e415a41,

        pub fn validate(self: SamplingConfig) !void {
            if (self.temperature < 0 or !std.math.isFinite(self.temperature)) return Error.InvalidSamplingConfig;
            if (self.top_p <= 0 or self.top_p > 1) return Error.InvalidSamplingConfig;
            if (self.min_p < 0 or self.min_p > 1) return Error.InvalidSamplingConfig;
            if (self.repeat_penalty <= 0 or !std.math.isFinite(self.repeat_penalty)) return Error.InvalidSamplingConfig;
        }
    };

    pub const LogitItem = struct {
        id: u32,
        logit: f32,
        p: f32 = 0,
    };

    pub const Wave38TokenHistory = struct {
        allocator: std.mem.Allocator,
        items: std.ArrayList(u32) = .empty,

        pub fn init(allocator: std.mem.Allocator) Wave38TokenHistory {
            return .{ .allocator = allocator };
        }

        pub fn deinit(self: *Wave38TokenHistory) void {
            self.items.deinit(self.allocator);
        }

        pub fn append(self: *Wave38TokenHistory, token: u32) !void {
            try self.items.append(self.allocator, token);
        }

        pub fn countRecent(self: Wave38TokenHistory, token: u32, n: usize) usize {
            const start = if (self.items.items.len > n) self.items.items.len - n else 0;
            var count: usize = 0;
            for (self.items.items[start..]) |t| if (t == token) {
                count += 1;
            };
            return count;
        }
    };

    pub const Sampler38 = struct {
        allocator: std.mem.Allocator,
        config: SamplingConfig,
        rng: XorShift,
        history: Wave38TokenHistory,
        work: []LogitItem,

        pub fn init(allocator: std.mem.Allocator, vocab_size: usize, config: SamplingConfig) !Sampler38 {
            try config.validate();
            const work = try allocator.alloc(LogitItem, vocab_size);
            return .{
                .allocator = allocator,
                .config = config,
                .rng = XorShift.init(config.seed),
                .history = Wave38TokenHistory.init(allocator),
                .work = work,
            };
        }

        pub fn deinit(self: *Sampler38) void {
            self.history.deinit();
            self.allocator.free(self.work);
            self.* = undefined;
        }

        fn sortDesc(items: []LogitItem) void {
            var i: usize = 1;
            while (i < items.len) : (i += 1) {
                var j = i;
                while (j > 0 and items[j].logit > items[j - 1].logit) : (j -= 1) {
                    std.mem.swap(LogitItem, &items[j], &items[j - 1]);
                }
            }
        }

        fn prepare(self: *Sampler38, logits: []const f32) ![]LogitItem {
            if (logits.len != self.work.len or logits.len == 0) return Error.ShapeMismatch;
            for (logits, 0..) |logit, id| {
                var adjusted = logit;
                const c = self.history.countRecent(@intCast(id), self.config.repeat_last_n);
                if (c != 0) {
                    if (adjusted < 0) adjusted *= self.config.repeat_penalty else adjusted /= self.config.repeat_penalty;
                    adjusted -= self.config.frequency_penalty * @as(f32, @floatFromInt(c));
                    adjusted -= self.config.presence_penalty;
                }
                if (self.config.temperature > 0) adjusted /= self.config.temperature;
                self.work[id] = .{ .id = @intCast(id), .logit = adjusted };
            }
            sortDesc(self.work);
            var keep = self.work.len;
            if (self.config.top_k != 0) keep = @min(keep, self.config.top_k);
            const active = self.work[0..keep];

            var maxv = active[0].logit;
            for (active[1..]) |it| {
                if (it.logit > maxv) maxv = it.logit;
            }
            var sum: f64 = 0;
            for (active) |*it| {
                it.p = @exp(it.logit - maxv);
                sum += it.p;
            }
            if (!(sum > 0)) return Error.EmptyDistribution;
            const inv: f32 = @floatCast(1.0 / sum);
            for (active) |*it| it.p *= inv;

            var cumulative: f32 = 0;
            var nucleus = active.len;
            var i: usize = 0;
            while (i < active.len) : (i += 1) {
                cumulative += active[i].p;
                if (cumulative >= self.config.top_p) {
                    nucleus = i + 1;
                    break;
                }
            }
            const max_p = active[0].p;
            var min_keep = nucleus;
            i = 0;
            while (i < nucleus) : (i += 1) {
                if (active[i].p < max_p * self.config.min_p) {
                    min_keep = @max(@as(usize, 1), i);
                    break;
                }
            }
            return active[0..min_keep];
        }

        pub fn choose(self: *Sampler38, logits: []const f32) !u32 {
            if (self.config.temperature == 0) {
                if (logits.len == 0) return Error.EmptyDistribution;
                var best: usize = 0;
                var i: usize = 1;
                while (i < logits.len) : (i += 1) if (logits[i] > logits[best]) {
                    best = i;
                };
                const tok: u32 = @intCast(best);
                try self.history.append(tok);
                return tok;
            }
            const active = try self.prepare(logits);
            var sum: f64 = 0;
            for (active) |it| sum += it.p;
            var r = self.rng.unit() * sum;
            for (active) |it| {
                r -= it.p;
                if (r <= 0) {
                    try self.history.append(it.id);
                    return it.id;
                }
            }
            const tok = active[active.len - 1].id;
            try self.history.append(tok);
            return tok;
        }
    };

    pub const StopSequence = struct {
        tokens: []const u32,
    };

    pub const Wave38StopMatcher = struct {
        stops: []const StopSequence,

        pub fn matched(self: Wave38StopMatcher, generated: []const u32) ?usize {
            for (self.stops, 0..) |stop, i| {
                if (stop.tokens.len == 0 or stop.tokens.len > generated.len) continue;
                if (std.mem.eql(u32, generated[generated.len - stop.tokens.len ..], stop.tokens)) return i;
            }
            return null;
        }

        pub fn longestPartial(self: Wave38StopMatcher, generated: []const u32) usize {
            var best: usize = 0;
            for (self.stops) |stop| {
                const maxn = @min(stop.tokens.len, generated.len);
                var n = maxn;
                while (n > 0) : (n -= 1) {
                    if (std.mem.eql(u32, generated[generated.len - n ..], stop.tokens[0..n])) {
                        if (n > best) best = n;
                        break;
                    }
                }
            }
            return best;
        }
    };

    pub const Utf8Stream = struct {
        pending: [4]u8 = .{ 0, 0, 0, 0 },
        pending_len: usize = 0,

        pub fn push(self: *Utf8Stream, allocator: std.mem.Allocator, bytes: []const u8, out: *std.ArrayList(u8)) !void {
            for (bytes) |b| {
                if (self.pending_len == 0) {
                    const n = Utf8.scalarLength(b);
                    if (n == 0) {
                        try out.append(allocator, 0xef);
                        try out.append(allocator, 0xbf);
                        try out.append(allocator, 0xbd);
                    } else if (n == 1) {
                        try out.append(allocator, b);
                    } else {
                        self.pending[0] = b;
                        self.pending_len = 1;
                    }
                } else {
                    if (self.pending_len >= self.pending.len) return Error.InvalidUtf8;
                    self.pending[self.pending_len] = b;
                    self.pending_len += 1;
                    const need = Utf8.scalarLength(self.pending[0]);
                    if (need != 0 and self.pending_len == need) {
                        if (Utf8.validScalar(self.pending[0..need])) {
                            try out.appendSlice(allocator, self.pending[0..need]);
                        } else {
                            try out.appendSlice(allocator, &[_]u8{ 0xef, 0xbf, 0xbd });
                        }
                        self.pending_len = 0;
                    }
                }
            }
        }

        pub fn finish(self: *Utf8Stream, allocator: std.mem.Allocator, out: *std.ArrayList(u8)) !void {
            if (self.pending_len != 0) {
                try out.appendSlice(allocator, &[_]u8{ 0xef, 0xbf, 0xbd });
                self.pending_len = 0;
            }
        }
    };

    pub const GenerateConfig = struct {
        max_new_tokens: usize = 256,
        stop_on_eos: bool = true,
        context_shift: bool = true,
        context_keep: usize = 32,
    };

    /// Detects unstable next-token decisions without claiming to identify the
    /// physical cause. A low top-1/top-2 margin is treated as uncertainty; the
    /// last stable token is held briefly to prevent rapid output thrashing.
    pub const CoherenceGuard = struct {
        min_margin: f32 = 0.05,
        max_hold_steps: usize = 2,
        stable_token: ?u32 = null,
        hold_steps: usize = 0,

        pub fn choose(self: *CoherenceGuard, logits: []const f32, proposed: u32) Error!u32 {
            if (logits.len == 0 or proposed >= logits.len) return Error.InvalidToken;
            var best: usize = 0;
            var second: usize = 0;
            for (logits, 0..) |value, i| {
                if (!std.math.isFinite(value)) return Error.NonFinite;
                if (value > logits[best]) {
                    second = best;
                    best = i;
                } else if (i != best and (second == best or value > logits[second])) {
                    second = i;
                }
            }
            const margin = logits[best] - logits[second];
            if (margin < self.min_margin and self.stable_token != null and self.hold_steps < self.max_hold_steps) {
                self.hold_steps += 1;
                return self.stable_token.?;
            }
            self.stable_token = proposed;
            self.hold_steps = 0;
            return proposed;
        }
    };

    /// Timing-alignment window for streaming output. It does not alter model
    /// logits; it only surfaces bounded chunks at a target cadence so timing
    /// spikes or scheduler jitter cannot create unbounded output bursts.
    pub const TimingAlignmentWindow = struct {
        target_ns: u64 = 50 * std.time.ns_per_ms,
        tolerance_ns: u64 = 20 * std.time.ns_per_ms,
        max_tokens: usize = 64,
        pending_tokens: usize = 0,
        window_start_ns: ?u64 = null,
        timing_anomalies: u64 = 0,

        pub fn push(self: *TimingAlignmentWindow, now_ns: u64) bool {
            if (self.window_start_ns == null) self.window_start_ns = now_ns;
            self.pending_tokens += 1;
            const elapsed = now_ns -| self.window_start_ns.?;
            const flush = self.pending_tokens >= self.max_tokens or elapsed >= self.target_ns;
            if (elapsed > self.target_ns + self.tolerance_ns or (elapsed < self.target_ns and self.pending_tokens == self.max_tokens)) self.timing_anomalies += 1;
            if (flush) {
                self.pending_tokens = 0;
                self.window_start_ns = now_ns;
            }
            return flush;
        }

        pub fn reset(self: *TimingAlignmentWindow) void {
            self.pending_tokens = 0;
            self.window_start_ns = null;
        }
    };

    /// Deterministic timing-surface simulator. This models hostile or noisy
    /// scheduling as a test input, not as evidence of a physical adversary.
    /// The seed makes every scenario replayable for debugging and CI.
    pub const TimingSurface = struct {
        rng: XorShift,
        base_ns: u64 = 50 * std.time.ns_per_ms,
        jitter_ns: u64 = 10 * std.time.ns_per_ms,
        phase_ns: u64 = 0,

        pub fn init(seed: u64) TimingSurface {
            return .{ .rng = XorShift.init(seed) };
        }

        pub fn nextDeadline(self: *TimingSurface, previous_ns: u64) u64 {
            const span = self.jitter_ns * 2 + 1;
            const offset = self.rng.next() % span;
            const signed_offset: i128 = @as(i128, @intCast(offset)) - @as(i128, @intCast(self.jitter_ns));
            const interval: i128 = @as(i128, @intCast(self.base_ns)) + signed_offset;
            const safe_interval: u64 = @intCast(@max(@as(i128, 1), interval));
            self.phase_ns +%= safe_interval;
            return previous_ns +| safe_interval +| self.phase_ns % 3;
        }

        pub fn reset(self: *TimingSurface, seed: u64) void {
            self.rng = XorShift.init(seed);
            self.phase_ns = 0;
        }
    };

    /// Three-lane temporal shield. Each lane has an independent deterministic
    /// phase; the median deadline is used and the spread is surfaced as an
    /// anomaly. This is a replayable resilience primitive, not attribution.
    pub const TemporalShield = struct {
        lanes: [3]TimingSurface,
        quarantined: u64 = 0,
        max_spread_ns: u64 = 20 * std.time.ns_per_ms,

        pub fn init(seed: u64) TemporalShield {
            return .{ .lanes = .{
                TimingSurface.init(seed ^ 0x243f6a8885a308d3),
                TimingSurface.init(seed ^ 0x13198a2e03707344),
                TimingSurface.init(seed ^ 0xa4093822299f31d0),
            } };
        }

        pub fn nextDeadline(self: *TemporalShield, previous_ns: u64) u64 {
            var values: [3]u64 = undefined;
            for (&self.lanes, 0..) |*lane, i| values[i] = lane.nextDeadline(previous_ns);
            var i: usize = 1;
            while (i < values.len) : (i += 1) {
                var j = i;
                while (j > 0 and values[j] < values[j - 1]) : (j -= 1) std.mem.swap(u64, &values[j], &values[j - 1]);
            }
            if (values[2] -| values[0] > self.max_spread_ns) self.quarantined += 1;
            return values[1];
        }
    };

    /// Hash-chained run ledger for deterministic replay and tamper evidence.
    /// It does not authenticate an external actor; it authenticates the local
    /// sequence of model/timing events against accidental or injected edits.
    pub const TemporalLedger = struct {
        digest: [32]u8 = [_]u8{0} ** 32,
        events: u64 = 0,

        pub fn append(self: *TemporalLedger, token: u32, deadline_ns: u64) void {
            var event: [20]u8 = undefined;
            @memcpy(event[0..4], std.mem.asBytes(&token));
            @memcpy(event[4..12], std.mem.asBytes(&deadline_ns));
            @memcpy(event[12..20], std.mem.asBytes(&self.events));
            var hash = std.crypto.hash.sha2.Sha256.init(.{});
            hash.update(&self.digest);
            hash.update(&event);
            hash.final(&self.digest);
            self.events += 1;
        }

        pub fn reset(self: *TemporalLedger) void {
            self.* = .{};
        }
    };

    pub const Generator = struct {
        allocator: std.mem.Allocator,
        executor: *Executor,
        tokenizer: *Tokenizer,
        sampler: *Sampler38,
        stops: Wave38StopMatcher,
        config: GenerateConfig,
        coherence: CoherenceGuard = .{},
        timing: TimingAlignmentWindow = .{},
        temporal: TemporalShield = TemporalShield.init(0x4e415a),
        ledger: TemporalLedger = .{},

        pub fn generateTokens(self: *Generator, prompt: []const u32) ![]u32 {
            if (prompt.len == 0) return Error.EmptyPrompt;
            var out = std.ArrayList(u32).empty;
            errdefer out.deinit(self.allocator);
            var logits = try self.executor.prefill(prompt, 0);
            var pos = prompt.len;
            var n: usize = 0;
            while (n < self.config.max_new_tokens) : (n += 1) {
                const proposed = try self.sampler.choose(logits);
                const tok = try self.coherence.choose(logits, proposed);
                const now = @as(u64, @intCast(@max(@as(i128, 0), std.time.nanoTimestamp())));
                const deadline = self.temporal.nextDeadline(now);
                _ = self.timing.push(deadline);
                self.ledger.append(tok, deadline);
                if (self.config.stop_on_eos and (tok == self.executor.model.meta.eos_id or
                    tok == (self.tokenizer.vocab.find("<|im_end|>") orelse self.executor.model.meta.eos_id) or
                    tok == (self.tokenizer.vocab.find("<|eot_id|>") orelse self.executor.model.meta.eos_id))) break;
                try out.append(self.allocator, tok);
                if (self.stops.matched(out.items) != null) break;
                if (pos >= self.executor.cache.capacity and !self.config.context_shift) return Error.ContextExceeded;
                logits = try self.executor.forward(tok, pos);
                pos += 1;
            }
            return try out.toOwnedSlice(self.allocator);
        }

        pub fn generateText(self: *Generator, prompt_text: []const u8) ![]u8 {
            const prompt = try self.tokenizer.encode(prompt_text, true);
            defer self.allocator.free(prompt);
            const tokens = try self.generateTokens(prompt);
            defer self.allocator.free(tokens);
            return self.tokenizer.decode(tokens);
        }
    };

    pub const Beam = struct {
        tokens: std.ArrayList(u32) = .empty,
        score: f64 = 0,
        finished: bool = false,

        pub fn deinit(self: *Beam, allocator: std.mem.Allocator) void {
            self.tokens.deinit(allocator);
        }

        pub fn clone(self: Beam, allocator: std.mem.Allocator) !Beam {
            var out = Beam{ .score = self.score, .finished = self.finished };
            try out.tokens.appendSlice(allocator, self.tokens.items);
            return out;
        }
    };

    pub const BeamSearch = struct {
        allocator: std.mem.Allocator,
        width: usize,
        length_penalty: f64 = 1.0,

        fn normalized(self: BeamSearch, beam: Beam) f64 {
            if (beam.tokens.items.len == 0) return beam.score;
            const n = @as(f64, @floatFromInt(beam.tokens.items.len));
            return beam.score / std.math.pow(f64, n, self.length_penalty);
        }

        pub fn topLogits(self: BeamSearch, logits: []const f32, k: usize, out: []LogitItem) !usize {
            _ = self;
            if (out.len < k) return Error.ShapeMismatch;
            var used: usize = 0;
            for (logits, 0..) |l, id| {
                if (used < k) {
                    out[used] = .{ .id = @intCast(id), .logit = l };
                    used += 1;
                    var j = used - 1;
                    while (j > 0 and out[j].logit > out[j - 1].logit) : (j -= 1) std.mem.swap(LogitItem, &out[j], &out[j - 1]);
                } else if (l > out[k - 1].logit) {
                    out[k - 1] = .{ .id = @intCast(id), .logit = l };
                    var j = k - 1;
                    while (j > 0 and out[j].logit > out[j - 1].logit) : (j -= 1) std.mem.swap(LogitItem, &out[j], &out[j - 1]);
                }
            }
            return used;
        }
    };

    pub const Speculative = struct {
        pub fn acceptanceProbability(target_logit: f32, draft_logit: f32) f32 {
            const delta = target_logit - draft_logit;
            if (delta >= 0) return 1;
            return @exp(delta);
        }

        pub fn accept(rng: *XorShift, target_logit: f32, draft_logit: f32) bool {
            return rng.unit() <= acceptanceProbability(target_logit, draft_logit);
        }

        pub fn commonPrefix(a: []const u32, b: []const u32) usize {
            const n = @min(a.len, b.len);
            var i: usize = 0;
            while (i < n and a[i] == b[i]) : (i += 1) {}
            return i;
        }
    };

    pub const GrammarDfa = struct {
        transitions: []const i32,
        state_count: usize,
        class_count: usize,
        accepting: []const bool,
        current: usize = 0,

        pub fn validate(self: GrammarDfa) !void {
            if (self.state_count == 0 or self.class_count == 0) return Error.InvalidGrammar;
            if (self.transitions.len != self.state_count * self.class_count) return Error.InvalidGrammar;
            if (self.accepting.len != self.state_count or self.current >= self.state_count) return Error.InvalidGrammar;
            for (self.transitions) |t| {
                if (t < -1) return Error.InvalidGrammar;
                if (t >= 0 and @as(usize, @intCast(t)) >= self.state_count) return Error.InvalidGrammar;
            }
        }

        pub fn step(self: *GrammarDfa, class: usize) bool {
            if (class >= self.class_count) return false;
            const next = self.transitions[self.current * self.class_count + class];
            if (next < 0) return false;
            self.current = @intCast(next);
            return true;
        }

        pub fn isAccepting(self: GrammarDfa) bool {
            return self.accepting[self.current];
        }
    };

    pub const TensorAuditIssue = enum {
        missing,
        rank,
        rows,
        cols,
        unsupported_quant,
        range,
    };

    pub const TensorAuditRecord = struct {
        name: []const u8,
        issue: TensorAuditIssue,
        expected_a: usize = 0,
        expected_b: usize = 0,
        actual_a: usize = 0,
        actual_b: usize = 0,
    };

    pub const ModelAudit = struct {
        allocator: std.mem.Allocator,
        issues: std.ArrayList(TensorAuditRecord) = .empty,

        pub fn deinit(self: *ModelAudit) void {
            self.issues.deinit(self.allocator);
        }

        pub fn checkMatrix(self: *ModelAudit, index: GgufOwnedIndex, name: []const u8, rows: usize, cols: usize) !void {
            const t = index.tensor(name) orelse {
                try self.issues.append(self.allocator, .{ .name = name, .issue = .missing });
                return;
            };
            if (t.n_dims != 2) {
                try self.issues.append(self.allocator, .{ .name = name, .issue = .rank, .expected_a = 2, .actual_a = t.n_dims });
                return;
            }
            if (t.dims[1] != rows) try self.issues.append(self.allocator, .{ .name = name, .issue = .rows, .expected_a = rows, .actual_a = @intCast(t.dims[1]) });
            if (t.dims[0] != cols) try self.issues.append(self.allocator, .{ .name = name, .issue = .cols, .expected_a = cols, .actual_a = @intCast(t.dims[0]) });
            if (QuantFormat.facts(t.ggml_type) == null) try self.issues.append(self.allocator, .{ .name = name, .issue = .unsupported_quant });
        }

        pub fn auditLlama(self: *ModelAudit, index: GgufOwnedIndex, meta: LlamaMetadata) !void {
            try self.checkMatrix(index, "token_embd.weight", meta.vocab_size, meta.embedding_length);
            if (index.tensor("output.weight") != null) try self.checkMatrix(index, "output.weight", meta.vocab_size, meta.embedding_length);
            var nb = LayerNameBuffer{};
            var l: usize = 0;
            while (l < meta.block_count) : (l += 1) {
                try self.checkMatrix(index, try nb.format(l, "attn_q.weight"), meta.embedding_length, meta.embedding_length);
                try self.checkMatrix(index, try nb.format(l, "attn_k.weight"), meta.kvWidth(), meta.embedding_length);
                try self.checkMatrix(index, try nb.format(l, "attn_v.weight"), meta.kvWidth(), meta.embedding_length);
                try self.checkMatrix(index, try nb.format(l, "attn_output.weight"), meta.embedding_length, meta.embedding_length);
                try self.checkMatrix(index, try nb.format(l, "ffn_gate.weight"), meta.feed_forward_length, meta.embedding_length);
                try self.checkMatrix(index, try nb.format(l, "ffn_up.weight"), meta.feed_forward_length, meta.embedding_length);
                try self.checkMatrix(index, try nb.format(l, "ffn_down.weight"), meta.embedding_length, meta.feed_forward_length);
            }
        }

        pub fn ok(self: ModelAudit) bool {
            return self.issues.items.len == 0;
        }
    };

    pub const DownloadSink = struct {
        context: *anyopaque,
        writeFn: *const fn (*anyopaque, []const u8) anyerror!void,

        pub fn write(self: DownloadSink, bytes: []const u8) !void {
            try self.writeFn(self.context, bytes);
        }
    };

    pub const DownloadVerifier = struct {
        expected_size_max: usize,
        expected_sha256_hex: []const u8,
        received: usize = 0,
        sha: std.crypto.hash.sha2.Sha256 = std.crypto.hash.sha2.Sha256.init(.{}),

        pub fn update(self: *DownloadVerifier, bytes: []const u8) !void {
            if (bytes.len > self.expected_size_max -| self.received) return Error.DownloadTooLarge;
            self.received += bytes.len;
            self.sha.update(bytes);
        }

        fn hexNibble(b: u8) ?u8 {
            if (b >= '0' and b <= '9') return b - '0';
            if (b >= 'a' and b <= 'f') return b - 'a' + 10;
            if (b >= 'A' and b <= 'F') return b - 'A' + 10;
            return null;
        }

        pub fn finish(self: *DownloadVerifier) !void {
            if (self.expected_sha256_hex.len != 64) return Error.DownloadHashMismatch;
            var expected: [32]u8 = undefined;
            var i: usize = 0;
            while (i < 32) : (i += 1) {
                const hi = hexNibble(self.expected_sha256_hex[i * 2]) orelse return Error.DownloadHashMismatch;
                const lo = hexNibble(self.expected_sha256_hex[i * 2 + 1]) orelse return Error.DownloadHashMismatch;
                expected[i] = (hi << 4) | lo;
            }
            var actual: [32]u8 = undefined;
            self.sha.final(&actual);
            if (!ctEqual(actual[0..], expected[0..])) return Error.DownloadHashMismatch;
        }
    };

    pub const PromptCacheKey = struct {
        digest: [32]u8,

        pub fn fromTokens(tokens: []const u32, model_digest: [32]u8) PromptCacheKey {
            var h = std.crypto.hash.sha2.Sha256.init(.{});
            h.update(&model_digest);
            var buf: [4]u8 = undefined;
            for (tokens) |t| {
                std.mem.writeInt(u32, &buf, t, .little);
                h.update(&buf);
            }
            var out: [32]u8 = undefined;
            h.final(&out);
            return .{ .digest = out };
        }
    };

    pub const SessionHeader = struct {
        magic: [8]u8 = .{ 'N', 'Z', 'L', 'L', 'M', '3', '8', 0 },
        version: u32 = 1,
        token_count: u64,
        position: u64,
        cache_capacity: u64,
        model_sha256: [32]u8,

        pub const encoded_len = 8 + 4 + 8 + 8 + 8 + 32;

        pub fn encode(self: SessionHeader, out: []u8) !void {
            if (out.len < encoded_len) return Error.InvalidSession;
            @memcpy(out[0..8], &self.magic);
            std.mem.writeInt(u32, out[8..12], self.version, .little);
            std.mem.writeInt(u64, out[12..20], self.token_count, .little);
            std.mem.writeInt(u64, out[20..28], self.position, .little);
            std.mem.writeInt(u64, out[28..36], self.cache_capacity, .little);
            @memcpy(out[36..68], &self.model_sha256);
        }

        pub fn decode(bytes: []const u8) !SessionHeader {
            if (bytes.len < encoded_len) return Error.InvalidSession;
            const expected: [8]u8 = .{ 'N', 'Z', 'L', 'L', 'M', '3', '8', 0 };
            if (!std.mem.eql(u8, bytes[0..8], &expected)) return Error.InvalidSession;
            var digest: [32]u8 = undefined;
            @memcpy(&digest, bytes[36..68]);
            return .{
                .version = std.mem.readInt(u32, bytes[8..12], .little),
                .token_count = std.mem.readInt(u64, bytes[12..20], .little),
                .position = std.mem.readInt(u64, bytes[20..28], .little),
                .cache_capacity = std.mem.readInt(u64, bytes[28..36], .little),
                .model_sha256 = digest,
            };
        }
    };

    pub const Batch = struct {
        token_ids: []const u32,
        positions: []const u32,
        sequence_ids: []const u32,

        pub fn validate(self: Batch) !void {
            if (self.token_ids.len == 0) return Error.EmptyPrompt;
            if (self.positions.len != self.token_ids.len or self.sequence_ids.len != self.token_ids.len) return Error.ShapeMismatch;
        }
    };

    pub const BatchPlanner = struct {
        max_batch_tokens: usize,
        max_sequences: usize,

        pub fn fitPrefix(self: BatchPlanner, lengths: []const usize) usize {
            var tokens: usize = 0;
            var seqs: usize = 0;
            while (seqs < lengths.len and seqs < self.max_sequences) : (seqs += 1) {
                if (lengths[seqs] > self.max_batch_tokens -| tokens) break;
                tokens += lengths[seqs];
            }
            return seqs;
        }
    };

    pub const Perplexity = struct {
        sum_log_prob: f64 = 0,
        token_count: usize = 0,

        pub fn add(self: *Perplexity, logits: []const f32, target: u32, scratch: []f32) !void {
            if (target >= logits.len or scratch.len < logits.len) return Error.ShapeMismatch;
            @memcpy(scratch[0..logits.len], logits);
            try softmaxStable(scratch[0..logits.len]);
            const p = scratch[target];
            if (!(p > 0)) return Error.InvalidProbability;
            self.sum_log_prob += @log(@as(f64, p));
            self.token_count += 1;
        }

        pub fn value(self: Perplexity) ?f64 {
            if (self.token_count == 0) return null;
            return @exp(-self.sum_log_prob / @as(f64, @floatFromInt(self.token_count)));
        }
    };

    pub const EmbeddingPool = struct {
        pub fn mean(out: []f32, states: []const f32, token_count: usize, hidden: usize) !void {
            if (out.len != hidden or states.len != token_count * hidden or token_count == 0) return Error.ShapeMismatch;
            @memset(out, 0);
            var t: usize = 0;
            while (t < token_count) : (t += 1) {
                var d: usize = 0;
                while (d < hidden) : (d += 1) out[d] += states[t * hidden + d];
            }
            const inv = 1.0 / @as(f32, @floatFromInt(token_count));
            for (out) |*v| v.* *= inv;
        }

        pub fn l2Normalize(v: []f32) !void {
            var ss: f64 = 0;
            for (v) |x| ss += @as(f64, x) * @as(f64, x);
            if (!(ss > 0)) return Error.NonFinite;
            const inv: f32 = @floatCast(1.0 / @sqrt(ss));
            for (v) |*x| x.* *= inv;
        }

        pub fn cosine(a: []const f32, b: []const f32) !f32 {
            if (a.len != b.len or a.len == 0) return Error.ShapeMismatch;
            var ab: f64 = 0;
            var aa: f64 = 0;
            var bb: f64 = 0;
            for (a, b) |x, y| {
                ab += @as(f64, x) * @as(f64, y);
                aa += @as(f64, x) * @as(f64, x);
                bb += @as(f64, y) * @as(f64, y);
            }
            if (!(aa > 0) or !(bb > 0)) return Error.NonFinite;
            return @floatCast(ab / @sqrt(aa * bb));
        }
    };

    pub const CrossEntropy = struct {
        pub fn lossAndGradient(logits: []const f32, target: u32, grad: []f32) !f32 {
            if (target >= logits.len or grad.len != logits.len or logits.len == 0) return Error.TrainingShapeMismatch;
            @memcpy(grad, logits);
            try softmaxStable(grad);
            const p = grad[target];
            if (!(p > 0)) return Error.InvalidProbability;
            grad[target] -= 1;
            return -@log(p);
        }
    };

    pub const AdamW = struct {
        beta1: f32 = 0.9,
        beta2: f32 = 0.999,
        eps: f32 = 1e-8,
        weight_decay: f32 = 0.01,
        step_count: u64 = 0,

        pub fn step(self: *AdamW, params: []f32, grads: []const f32, m: []f32, v: []f32, lr: f32) !void {
            if (params.len != grads.len or params.len != m.len or params.len != v.len) return Error.TrainingShapeMismatch;
            self.step_count += 1;
            const b1t = 1.0 - std.math.pow(f32, self.beta1, @floatFromInt(self.step_count));
            const b2t = 1.0 - std.math.pow(f32, self.beta2, @floatFromInt(self.step_count));
            var i: usize = 0;
            while (i < params.len) : (i += 1) {
                m[i] = self.beta1 * m[i] + (1.0 - self.beta1) * grads[i];
                v[i] = self.beta2 * v[i] + (1.0 - self.beta2) * grads[i] * grads[i];
                const mh = m[i] / b1t;
                const vh = v[i] / b2t;
                const update = mh / (@sqrt(vh) + self.eps) + self.weight_decay * params[i];
                params[i] -= lr * update;
            }
        }
    };

    pub const Gradient = struct {
        pub fn l2Norm(grads: []const f32) f64 {
            var ss: f64 = 0;
            for (grads) |g| ss += @as(f64, g) * @as(f64, g);
            return @sqrt(ss);
        }

        pub fn clip(grads: []f32, max_norm: f64) void {
            const norm = l2Norm(grads);
            if (norm <= max_norm or norm == 0) return;
            const scale: f32 = @floatCast(max_norm / norm);
            for (grads) |*g| g.* *= scale;
        }

        pub fn zero(grads: []f32) void {
            @memset(grads, 0);
        }
    };

    pub const Lora = struct {
        rank: usize,
        alpha: f32,
        a: []const f32,
        b: []const f32,
        in_dim: usize,
        out_dim: usize,

        pub fn validate(self: Lora) !void {
            if (self.rank == 0 or self.a.len != self.rank * self.in_dim or self.b.len != self.out_dim * self.rank) return Error.ShapeMismatch;
        }

        pub fn apply(self: Lora, out: []f32, x: []const f32, temp: []f32) !void {
            try self.validate();
            if (x.len != self.in_dim or out.len != self.out_dim or temp.len < self.rank) return Error.ShapeMismatch;
            var r: usize = 0;
            while (r < self.rank) : (r += 1) {
                var acc: f32 = 0;
                var i: usize = 0;
                while (i < self.in_dim) : (i += 1) acc += self.a[r * self.in_dim + i] * x[i];
                temp[r] = acc;
            }
            const scale = self.alpha / @as(f32, @floatFromInt(self.rank));
            var o: usize = 0;
            while (o < self.out_dim) : (o += 1) {
                var acc: f32 = 0;
                r = 0;
                while (r < self.rank) : (r += 1) acc += self.b[o * self.rank + r] * temp[r];
                out[o] += acc * scale;
            }
        }
    };

    pub const RuntimeStats = struct {
        prompt_tokens: usize = 0,
        generated_tokens: usize = 0,
        matvec_rows: u64 = 0,
        quant_blocks: u64 = 0,
        cache_reads: u64 = 0,
        cache_writes: u64 = 0,
        bytes_read: u64 = 0,

        pub fn reset(self: *RuntimeStats) void {
            self.* = .{};
        }

        pub fn totalTokens(self: RuntimeStats) usize {
            return self.prompt_tokens + self.generated_tokens;
        }
    };

    pub const MemoryPlan = struct {
        hidden_bytes: usize,
        scratch_bytes: usize,
        kv_bytes: usize,
        logits_bytes: usize,
        total_bytes: usize,

        pub fn calculate(meta: LlamaMetadata, context: usize) !MemoryPlan {
            const f = @sizeOf(f32);
            const hidden = meta.embedding_length * f;
            const scratch_floats =
                meta.embedding_length * 6 +
                meta.kvWidth() * 2 +
                meta.feed_forward_length * 4 +
                @max(meta.embedding_length, meta.feed_forward_length);
            const scratch = scratch_floats * f;
            const per_layer_context = context * meta.kvWidth() * 2;
            if (meta.block_count > std.math.maxInt(usize) / per_layer_context) return Error.Overflow;
            const kv = meta.block_count * per_layer_context * f;
            const logits = meta.vocab_size * f;
            return .{
                .hidden_bytes = hidden,
                .scratch_bytes = scratch,
                .kv_bytes = kv,
                .logits_bytes = logits,
                .total_bytes = hidden + scratch + kv + logits,
            };
        }
    };

    pub const FixedTargetFacts = struct {
        pub const repo = target_model_repo;
        pub const file = target_model_file;
        pub const approx_file_bytes = target_model_approx_bytes;
        pub const architecture = "llama";
        pub const quantization = "Q3_K_M";
        pub const chat_begin = "<|begin_of_text|>";
        pub const chat_header_begin = "<|start_header_id|>";
        pub const chat_header_end = "<|end_header_id|>";
        pub const chat_turn_end = "<|eot_id|>";

        pub fn fileLooksRight(name: []const u8) bool {
            return std.mem.eql(u8, name, file);
