        }
    };
    // ------------------------------------------------------------------------
    // Fixed-dimension scalar kernels. These remove dynamic length checks from
    // hot inner loops once a model shape is known, while keeping a portable
    // portable implementation for each commonly encountered transformer width.
    // ------------------------------------------------------------------------
    pub const StaticVec32 = struct {
        pub const width: usize = 32;

        pub fn zero(out: *[width]f32) void {
            @memset(out, 0);
        }

        pub fn copy(out: *[width]f32, x: *const [width]f32) void {
            @memcpy(out, x);
        }

        pub fn addInPlace(out: *[width]f32, x: *const [width]f32) void {
            var i: usize = 0;
            while (i < width) : (i += 1) out[i] += x[i];
        }

        pub fn mulInPlace(out: *[width]f32, x: *const [width]f32) void {
            var i: usize = 0;
            while (i < width) : (i += 1) out[i] *= x[i];
        }

        pub fn scale(out: *[width]f32, factor: f32) void {
            var i: usize = 0;
            while (i < width) : (i += 1) out[i] *= factor;
        }

        pub fn wave38Dot(a: *const [width]f32, b: *const [width]f32) f32 {
            var acc: f64 = 0;
            var i: usize = 0;
            while (i < width) : (i += 1) acc += @as(f64, a[i]) * @as(f64, b[i]);
            return @floatCast(acc);
        }

        pub fn rms(out: *[width]f32, x: *const [width]f32, weight: *const [width]f32, eps: f32) void {
            var ss: f64 = 0;
            var i: usize = 0;
            while (i < width) : (i += 1) ss += @as(f64, x[i]) * @as(f64, x[i]);
            const inv: f32 = 1.0 / @sqrt(@as(f32, @floatCast(ss / @as(f64, @floatFromInt(width)))) + eps);
            i = 0;
            while (i < width) : (i += 1) out[i] = x[i] * inv * weight[i];
        }

        pub fn siluMul(out: *[width]f32, gate: *const [width]f32, up: *const [width]f32) void {
            var i: usize = 0;
            while (i < width) : (i += 1) {
                const g = gate[i];
                out[i] = (g / (1.0 + @exp(-g))) * up[i];
            }
        }

        pub fn finite(x: *const [width]f32) bool {
            for (x) |v| if (!std.math.isFinite(v)) return false;
            return true;
        }
    };

