    // Fixed head-dimension RoPE/attention kernels used by GQA/MHA paths.
    pub const HeadKernel32 = struct {
        pub const head_dim: usize = 32;

        pub fn score(q: *const [head_dim]f32, k: *const [head_dim]f32) f32 {
            var acc: f64 = 0;
            var i: usize = 0;
            while (i < head_dim) : (i += 1) acc += @as(f64, q[i]) * @as(f64, k[i]);
            return @floatCast(acc / @sqrt(@as(f64, @floatFromInt(head_dim))));
        }

        pub fn rope(x: *[head_dim]f32, position: usize, theta: f32) void {
            var i: usize = 0;
            while (i + 1 < head_dim) : (i += 2) {
                const exponent = @as(f32, @floatFromInt(i)) / @as(f32, @floatFromInt(head_dim));
                const freq = 1.0 / std.math.pow(f32, theta, exponent);
                const angle = @as(f32, @floatFromInt(position)) * freq;
                const c = @cos(angle);
                const s = @sin(angle);
                const a = x[i];
                const b = x[i + 1];
                x[i] = a * c - b * s;
                x[i + 1] = a * s + b * c;
            }
        }

        pub fn weightedAdd(out: *[head_dim]f32, value: *const [head_dim]f32, weight: f32) void {
            var i: usize = 0;
            while (i < head_dim) : (i += 1) out[i] += value[i] * weight;
        }

        pub fn zero(out: *[head_dim]f32) void {
            @memset(out, 0);
        }

        pub fn finite(x: *const [head_dim]f32) bool {
            for (x) |v| if (!std.math.isFinite(v)) return false;
            return true;
        }
    };

