    // Context profiles provide exact KV sizing and sliding-window arithmetic.
    pub const Context128 = struct {
        pub const tokens: usize = 128;

        pub fn clampPosition(pos: usize) usize {
            return @min(pos, tokens - 1);
        }

        pub fn slot(pos: usize) usize {
            return pos % tokens;
        }

        pub fn retainedStart(pos: usize) usize {
            if (pos + 1 <= tokens) return 0;
            return pos + 1 - tokens;
        }

        pub fn kvFloats(layers: usize, kv_heads: usize, head_dim: usize) !usize {
            if (layers > std.math.maxInt(usize) / tokens) return Error.Overflow;
            const lt = layers * tokens;
            if (kv_heads != 0 and lt > std.math.maxInt(usize) / kv_heads) return Error.Overflow;
            const lth = lt * kv_heads;
            if (head_dim != 0 and lth > std.math.maxInt(usize) / head_dim) return Error.Overflow;
            const one = lth * head_dim;
            if (one > std.math.maxInt(usize) / 2) return Error.Overflow;
            return one * 2;
        }

        pub fn kvBytes(layers: usize, kv_heads: usize, head_dim: usize) !usize {
            const floats = try kvFloats(layers, kv_heads, head_dim);
            if (floats > std.math.maxInt(usize) / @sizeOf(f32)) return Error.Overflow;
            return floats * @sizeOf(f32);
        }
    };

