    // Static quant-row adapters: fixed-width row byte accounting and scalar dots.
    pub const QuantRow64 = struct {
        pub const columns: usize = 64;

        pub fn bytesFor(ggml_type: u32) !usize {
            return QuantFormat.rowBytes(ggml_type, columns);
        }

        pub fn valid(ggml_type: u32, bytes: []const u8) bool {
            const expected = bytesFor(ggml_type) catch return false;
            return bytes.len == expected;
        }

        pub fn wave38Dot(ggml_type: u32, bytes: []const u8, x: *const [columns]f32, scratch: *[columns]f32) !f32 {
            if (!valid(ggml_type, bytes)) return Error.InvalidQuantBlock;
            const row = RowView{ .ggml_type = ggml_type, .bytes = bytes, .columns = columns };
            return row.wave38Dot(x, scratch);
        }

        pub fn decode(ggml_type: u32, bytes: []const u8, out: *[columns]f32) !void {
            if (!valid(ggml_type, bytes)) return Error.InvalidQuantBlock;
            try ScalarQuant.decode(ggml_type, out, bytes);
        }

        pub fn blocks(ggml_type: u32) !usize {
            const f = QuantFormat.facts(ggml_type) orelse return Error.UnsupportedQuantType;
            if (columns % f.block_values != 0) return Error.InvalidQuantBlock;
            return columns / f.block_values;
        }
    };

