    // Static dense training/evaluation kernels for common transformer projections.
    pub const DenseKernel00 = struct {
        pub const in_dim: usize = 128;
        pub const out_dim: usize = 128;

        pub fn forward(out: *[out_dim]f32, weight: *const [out_dim * in_dim]f32, x: *const [in_dim]f32) void {
            var r: usize = 0;
            while (r < out_dim) : (r += 1) {
                var acc: f64 = 0;
                var c: usize = 0;
                while (c < in_dim) : (c += 1) acc += @as(f64, weight[r * in_dim + c]) * @as(f64, x[c]);
                out[r] = @floatCast(acc);
            }
        }

        pub fn backwardInput(dx: *[in_dim]f32, weight: *const [out_dim * in_dim]f32, dy: *const [out_dim]f32) void {
            @memset(dx, 0);
            var r: usize = 0;
            while (r < out_dim) : (r += 1) {
                var c: usize = 0;
                while (c < in_dim) : (c += 1) dx[c] += weight[r * in_dim + c] * dy[r];
            }
        }

        pub fn accumulateWeightGradient(dw: *[out_dim * in_dim]f32, dy: *const [out_dim]f32, x: *const [in_dim]f32) void {
            var r: usize = 0;
            while (r < out_dim) : (r += 1) {
                var c: usize = 0;
                while (c < in_dim) : (c += 1) dw[r * in_dim + c] += dy[r] * x[c];
            }
        }

        pub fn parameterCount() usize {
            return out_dim * in_dim;
        }

        pub fn bytesF32() usize {
            return parameterCount() * @sizeOf(f32);
        }
    };

