    pub const SelfTest = struct {
        pub fn f16Basics() bool {
            return wave38F16ToF32(0x3c00) == 1.0 and wave38F16ToF32(0xc000) == -2.0;
        }

        pub fn utf8Basics() bool {
            return Utf8.validate("hello") and Utf8.validate("λ") and !Utf8.validate(&[_]u8{ 0xc0, 0x80 });
        }

        pub fn chatBasics(allocator: std.mem.Allocator) !bool {
            const messages = [_]Wave38ChatMessage{
                .{ .role = .system, .content = "S" },
                .{ .role = .user, .content = "U" },
            };
            const rendered = try Llama3Chat.render(allocator, &messages, true);
            defer allocator.free(rendered);
            return std.mem.indexOf(u8, rendered, "<|begin_of_text|>") != null and
                std.mem.indexOf(u8, rendered, "assistant") != null;
        }

        pub fn stopBasics() bool {
            const stop = [_]u32{ 9, 10 };
            const seqs = [_]StopSequence{.{ .tokens = &stop }};
            const m = Wave38StopMatcher{ .stops = &seqs };
            const gen = [_]u32{ 1, 2, 9, 10 };
            return m.matched(&gen) != null;
        }

        pub fn speculativeBasics() bool {
            const a = [_]u32{ 1, 2, 3, 4 };
            const b = [_]u32{ 1, 2, 9 };
            return Speculative.commonPrefix(&a, &b) == 2 and Speculative.acceptanceProbability(0, 1) < 1;
        }

        pub fn memoryPlanBasics() !bool {
            const m = LlamaMetadata{
                .context_length = 2048,
                .embedding_length = 512,
                .feed_forward_length = 1536,
                .block_count = 8,
                .head_count = 8,
                .head_count_kv = 2,
                .rope_dimension_count = 64,
                .rope_freq_base = 500000,
                .rms_epsilon = 0.00001,
                .vocab_size = 4096,
                .bos_id = 1,
                .eos_id = 2,
                .eot_id = null,
                .tokenizer_model = "gpt2",
            };
            const plan = try MemoryPlan.calculate(m, 1024);
            return plan.kv_bytes > 0 and plan.total_bytes >= plan.kv_bytes;
        }
    };
};

test "wave38 llm f16 and utf8" {
    try std.testing.expect(Wave38Llm.SelfTest.f16Basics());
    try std.testing.expect(Wave38Llm.SelfTest.utf8Basics());
}

test "wave38 llm chat stop speculative" {
    try std.testing.expect(try Wave38Llm.SelfTest.chatBasics(std.testing.allocator));
    try std.testing.expect(Wave38Llm.SelfTest.stopBasics());
    try std.testing.expect(Wave38Llm.SelfTest.speculativeBasics());
    try std.testing.expect(try Wave38Llm.SelfTest.memoryPlanBasics());
}

// ============================================================================
// WAVE 38 TOKENIZER I/O — GGUF array materialization for Llama-3/GPT-2 BPE.
// This remains separate from Wave38Llm so the main runtime stays readable while
// still living in the same monolithic Zig source file.
// ============================================================================

pub const Wave38TokenizerIo = struct {
    const W = Wave38Llm;

    pub const StringArray = struct {
        allocator: std.mem.Allocator,
        items: [][]const u8,

        pub fn deinit(self: *StringArray) void {
            self.allocator.free(self.items);
            self.* = undefined;
        }
    };

    pub const I32Array = struct {
        allocator: std.mem.Allocator,
        items: []i32,

        pub fn deinit(self: *I32Array) void {
            self.allocator.free(self.items);
            self.* = undefined;
        }
    };

    pub const F32Array = struct {
        allocator: std.mem.Allocator,
        items: []f32,

        pub fn deinit(self: *F32Array) void {
            self.allocator.free(self.items);
            self.* = undefined;
        }
    };

    fn entry(index: W.GgufOwnedIndex, key: []const u8) !W.MetadataArrayRef {
        const e = index.metadataEntry(key) orelse return W.Error.InvalidTokenizer;
        if (e.value_type != .array or e.array == null) return W.Error.InvalidTokenizer;
        return e.array.?;
    }

    pub fn strings(allocator: std.mem.Allocator, index: W.GgufOwnedIndex, key: []const u8) !StringArray {
        const a = try entry(index, key);
        if (a.item_type != .string) return W.Error.InvalidTokenizer;
        var cur = W.Wave38ByteCursor{ .bytes = index.bytes, .pos = a.payload_offset };
        const out = try allocator.alloc([]const u8, a.count);
        errdefer allocator.free(out);
        var i: usize = 0;
        while (i < a.count) : (i += 1) out[i] = try cur.readString(W.hard_max_token_bytes);
        if (cur.pos != a.payload_end) return W.Error.InvalidTokenizer;
        return .{ .allocator = allocator, .items = out };
    }

    pub fn i32s(allocator: std.mem.Allocator, index: W.GgufOwnedIndex, key: []const u8) !I32Array {
        const a = try entry(index, key);
        if (a.item_type != .int32) return W.Error.InvalidTokenizer;
        var cur = W.Wave38ByteCursor{ .bytes = index.bytes, .pos = a.payload_offset };
        const out = try allocator.alloc(i32, a.count);
        errdefer allocator.free(out);
        var i: usize = 0;
        while (i < a.count) : (i += 1) out[i] = @bitCast(try cur.read(u32));
        if (cur.pos != a.payload_end) return W.Error.InvalidTokenizer;
        return .{ .allocator = allocator, .items = out };
    }

    pub fn f32s(allocator: std.mem.Allocator, index: W.GgufOwnedIndex, key: []const u8) !F32Array {
        const a = try entry(index, key);
        if (a.item_type != .float32) return W.Error.InvalidTokenizer;
        var cur = W.Wave38ByteCursor{ .bytes = index.bytes, .pos = a.payload_offset };
        const out = try allocator.alloc(f32, a.count);
        errdefer allocator.free(out);
        var i: usize = 0;
        while (i < a.count) : (i += 1) out[i] = try cur.readF32();
        if (cur.pos != a.payload_end) return W.Error.InvalidTokenizer;
        return .{ .allocator = allocator, .items = out };
    }

    pub fn tokenKind(raw: i32, text: []const u8) W.TokenKind {
        // GGML token types follow the SentencePiece convention in common GGUFs:
        // 1 normal, 2 unknown, 3 control, 4 user-defined, 5 unused, 6 byte.
        if (std.mem.startsWith(u8, text, "<|") and std.mem.endsWith(u8, text, "|>")) return .special;
        return switch (raw) {
            1 => .normal,
            2 => .unknown,
            3 => .control,
            4 => .user_defined,
            5 => .unused,
            6 => .byte,
            else => .normal,
        };
    }

    pub const Gpt2ByteMap = struct {
        // GPT-2 byte-level BPE maps the 256 bytes to a reversible set of Unicode
        // scalar values. Printable Latin-1 ranges map to themselves; the rest are
        // assigned code points starting at U+0100 in byte-order.
        pub fn codepointForByte(target: u8) u21 {
            if ((target >= 33 and target <= 126) or (target >= 161 and target <= 172) or (target >= 174)) {
                return @intCast(target);
            }
            var extra: u21 = 256;
            var b: u16 = 0;
            while (b < 256) : (b += 1) {
                const x: u8 = @intCast(b);
                const direct = (x >= 33 and x <= 126) or (x >= 161 and x <= 172) or (x >= 174);
                if (!direct) {
                    if (x == target) return extra;
                    extra += 1;
                }
            }
            unreachable;
        }

        pub fn utf8Encode(cp: u21, out: *[4]u8) usize {
            if (cp <= 0x7f) {
                out[0] = @intCast(cp);
                return 1;
            }
            if (cp <= 0x7ff) {
                out[0] = 0xc0 | @as(u8, @intCast(cp >> 6));
                out[1] = 0x80 | @as(u8, @intCast(cp & 0x3f));
                return 2;
            }
            if (cp <= 0xffff) {
                out[0] = 0xe0 | @as(u8, @intCast(cp >> 12));
                out[1] = 0x80 | @as(u8, @intCast((cp >> 6) & 0x3f));
                out[2] = 0x80 | @as(u8, @intCast(cp & 0x3f));
                return 3;
            }
            out[0] = 0xf0 | @as(u8, @intCast(cp >> 18));
            out[1] = 0x80 | @as(u8, @intCast((cp >> 12) & 0x3f));
            out[2] = 0x80 | @as(u8, @intCast((cp >> 6) & 0x3f));
            out[3] = 0x80 | @as(u8, @intCast(cp & 0x3f));
            return 4;
        }

        pub fn tokenForByte(vocab: W.Vocab, b: u8) ?u32 {
            var enc: [4]u8 = undefined;
            const n = utf8Encode(codepointForByte(b), &enc);
            return vocab.find(enc[0..n]);
        }

        pub fn build(vocab: W.Vocab) [256]?u32 {
            var out = [_]?u32{null} ** 256;
            var i: usize = 0;
            while (i < 256) : (i += 1) out[i] = tokenForByte(vocab, @intCast(i));
            return out;
        }

        pub fn complete(map: [256]?u32) bool {
            for (map) |x| if (x == null) return false;
            return true;
        }
    };

    pub const MergeText = struct {
        left: []const u8,
        right: []const u8,
    };

    pub fn splitMerge(line: []const u8) ?MergeText {
        const idx = std.mem.indexOfScalar(u8, line, ' ') orelse return null;
        if (idx == 0 or idx + 1 >= line.len) return null;
        if (std.mem.indexOfScalar(u8, line[idx + 1 ..], ' ') != null) return null;
        return .{ .left = line[0..idx], .right = line[idx + 1 ..] };
    }

    pub const BuiltTokenizer = struct {
        allocator: std.mem.Allocator,
        tokenizer: W.Tokenizer,
        merge_rules: []W.MergeRule,
        token_records: []W.TokenRecord,
        special_storage: []W.SpecialToken,

        pub fn deinit(self: *BuiltTokenizer) void {
            self.tokenizer.deinit();
            self.allocator.free(self.merge_rules);
            self.allocator.free(self.token_records);
            // special_storage aliases tokenizer.specials and was freed by tokenizer.deinit().
            self.* = undefined;
        }
    };

    fn specialIds(index: W.GgufOwnedIndex, allocator: std.mem.Allocator, vocab: W.Vocab) ![]W.SpecialToken {
        const candidate_keys = [_][]const u8{
            "tokenizer.ggml.bos_token_id",
            "tokenizer.ggml.eos_token_id",
            "tokenizer.ggml.unknown_token_id",
            "tokenizer.ggml.padding_token_id",
            "tokenizer.ggml.eot_token_id",
            "tokenizer.ggml.eom_token_id",
            "tokenizer.ggml.fim_prefix_token_id",
            "tokenizer.ggml.fim_middle_token_id",
            "tokenizer.ggml.fim_suffix_token_id",
            "tokenizer.ggml.fim_pad_token_id",
            "tokenizer.ggml.separator_token_id",
        };
        var out = std.ArrayList(W.SpecialToken).empty;
        errdefer out.deinit(allocator);
        for (candidate_keys) |key| {
            const s = index.scalar(key) orelse continue;
            const raw = s.asU64() orelse continue;
            if (raw >= vocab.tokens.len) continue;
            const id: u32 = @intCast(raw);
            const rec = vocab.token(id) orelse continue;
            var duplicate = false;
            for (out.items) |existing| if (existing.id == id) {
                duplicate = true;
                break;
            };
            if (!duplicate) try out.append(allocator, .{ .text = rec.text, .id = id });
        }
        // Also retain explicit <|...|> vocabulary entries as specials; this is
        // important for Llama-3 headers/eot even when a GGUF omits one id key.
        for (vocab.tokens, 0..) |rec, id_usize| {
            if (!std.mem.startsWith(u8, rec.text, "<|") or !std.mem.endsWith(u8, rec.text, "|>")) continue;
            const id: u32 = @intCast(id_usize);
            var duplicate = false;
            for (out.items) |existing| if (existing.id == id) {
                duplicate = true;
                break;
            };
            if (!duplicate) try out.append(allocator, .{ .text = rec.text, .id = id });
        }
        return try out.toOwnedSlice(allocator);
    }

    pub fn buildTokenizer(allocator: std.mem.Allocator, index: W.GgufOwnedIndex) !BuiltTokenizer {
        var tokens = try strings(allocator, index, "tokenizer.ggml.tokens");
        defer tokens.deinit();
        if (tokens.items.len == 0) return W.Error.InvalidTokenizer;

        var types_opt: ?I32Array = i32s(allocator, index, "tokenizer.ggml.token_type") catch null;
        defer if (types_opt) |*v| v.deinit();
        var scores_opt: ?F32Array = f32s(allocator, index, "tokenizer.ggml.scores") catch null;
        defer if (scores_opt) |*v| v.deinit();
        if (types_opt) |v| if (v.items.len != tokens.items.len) return W.Error.InvalidTokenizer;
        if (scores_opt) |v| if (v.items.len != tokens.items.len) return W.Error.InvalidTokenizer;

        const records = try allocator.alloc(W.TokenRecord, tokens.items.len);
        errdefer allocator.free(records);
        for (tokens.items, 0..) |text, i| {
            const raw_type: i32 = if (types_opt) |v| v.items[i] else 1;
            const score: f32 = if (scores_opt) |v| v.items[i] else 0;
            records[i] = .{ .text = text, .score = score, .kind = tokenKind(raw_type, text) };
        }

        var vocab = try W.Vocab.init(allocator, records);
        errdefer vocab.deinit();
        const byte_map = Gpt2ByteMap.build(vocab);

        var merge_lines_opt: ?StringArray = strings(allocator, index, "tokenizer.ggml.merges") catch null;
        defer if (merge_lines_opt) |*v| v.deinit();
        var merge_list = std.ArrayList(W.MergeRule).empty;
        errdefer merge_list.deinit(allocator);
        if (merge_lines_opt) |marr| {
            for (marr.items, 0..) |line, rank| {
                const parts = splitMerge(line) orelse continue;
                const left = vocab.find(parts.left) orelse continue;
                const right = vocab.find(parts.right) orelse continue;
                const joined_len = parts.left.len + parts.right.len;
                const joined = try allocator.alloc(u8, joined_len);
                defer allocator.free(joined);
                @memcpy(joined[0..parts.left.len], parts.left);
                @memcpy(joined[parts.left.len..], parts.right);
                const merged = vocab.find(joined) orelse continue;
                try merge_list.append(allocator, .{
                    .left = left,
                    .right = right,
                    .merged = merged,
                    .rank = @intCast(rank),
                });
            }
        }
        const merge_rules = try merge_list.toOwnedSlice(allocator);
        errdefer allocator.free(merge_rules);
        const specials = try specialIds(index, allocator, vocab);
        errdefer allocator.free(specials);

        // Tokenizer owns its own Vocab token-record slice, but the record array is
        // retained separately here because it is useful for diagnostics/export.
        const tokenizer = W.Tokenizer{
            .allocator = allocator,
            .vocab = vocab,
            .bpe = .{ .vocab = vocab, .merges = .{ .rules = merge_rules }, .byte_tokens = byte_map },
            .specials = specials,
        };

        return .{
            .allocator = allocator,
            .tokenizer = tokenizer,
            .merge_rules = merge_rules,
            .token_records = records,
            .special_storage = specials,
        };
    }

    pub const TokenizerAudit = struct {
        token_count: usize,
        merge_count: usize,
        special_count: usize,
        byte_fallback_complete: bool,
        bos_present: bool,
        eos_present: bool,
        begin_text_present: bool,
        eot_present: bool,

        pub fn inspect(tok: W.Tokenizer, merge_count: usize) TokenizerAudit {
            const map = Gpt2ByteMap.build(tok.vocab);
            return .{
                .token_count = tok.vocab.tokens.len,
                .merge_count = merge_count,
                .special_count = tok.specials.len,
                .byte_fallback_complete = Gpt2ByteMap.complete(map),
                .bos_present = tok.vocab.find("<|begin_of_text|>") != null,
                .eos_present = tok.vocab.find("<|end_of_text|>") != null,
                .begin_text_present = tok.vocab.find("<|begin_of_text|>") != null,
                .eot_present = tok.vocab.find("<|eot_id|>") != null,
            };
        }
    };
};

test "wave38 gpt2 byte map is bijective on codepoints" {
    var seen = std.AutoHashMap(u21, void).init(std.testing.allocator);
    defer seen.deinit();
    var i: usize = 0;
    while (i < 256) : (i += 1) {
        const cp = Wave38TokenizerIo.Gpt2ByteMap.codepointForByte(@intCast(i));
        try std.testing.expect(!seen.contains(cp));
        try seen.put(cp, {});
    }
    try std.testing.expectEqual(@as(usize, 256), seen.count());
}

test "wave38 merge parser" {
    const m = Wave38TokenizerIo.splitMerge("hello world") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("hello", m.left);
    try std.testing.expectEqualStrings("world", m.right);
    try std.testing.expect(Wave38TokenizerIo.splitMerge("bad merge line") == null);
}

// ============================================================================
// WAVE 50 — EXPERIMENTAL LLM COHERENCE ENGINE
// ============================================================================
// These mechanisms are experimental combinations for coherence research.
// They are not represented as globally novel, scientifically validated, or as
// replacements for evaluation. The design goal is to give the pure-Zig runtime
// explicit state for claims, entities, discourse, uncertainty, long-horizon
// memory, candidate verification, and adaptive decoding without adding any C,
// Python, llama.cpp, or external-runtime dependency.
//
// Research inspirations include recurrent/associative memory, structured
// memory, contrastive decoding, self-verification, and adaptive sampling. The
// combinations below are deliberately original to this program's architecture:
//   * Claim-State Dual Ledger (CSDL)
//   * Multi-Horizon Semantic Recurrence (MHSR)
//   * Counterfactual Memory-Ablation Decoding (CMAD)
//   * Layer-Agreement Coherence Fusion (LACF)
//   * Entropy-Debt Adaptive Sampling (EDAS)
//   * Discourse Anchor Re-grounding (DAR)
//

pub const Wave50Math = struct {
    pub const eps: f32 = 1e-12;

    pub fn clamp01(x: f32) f32 {
        return @max(@as(f32, 0.0), @min(@as(f32, 1.0), x));
    }

    pub fn lerp(a: f32, b: f32, t: f32) f32 {
        return a + (b - a) * t;
    }

    pub fn safeLog(x: f32) f32 {
        return @log(@max(x, @as(f32, 1e-20)));
    }

    pub fn sigmoid(x: f32) f32 {
        if (x >= 0) {
            const z = @exp(-x);
            return 1.0 / (1.0 + z);
        }
        const z = @exp(x);
        return z / (1.0 + z);
    }

    pub fn softplus(x: f32) f32 {
        if (x > 20.0) return x;
        if (x < -20.0) return @exp(x);
        return @log(1.0 + @exp(x));
    }

    pub fn wave50Dot(a: []const f32, b: []const f32) !f32 {
        if (a.len != b.len) return error.ShapeMismatch;
        var s: f32 = 0;
        for (a, b) |x, y| {
            s += x * y;
        }
        return s;
    }

    pub fn norm2(a: []const f32) f32 {
        var s: f32 = 0;
        for (a) |x| {
            s += x * x;
        }
        return @sqrt(@max(s, @as(f32, 0)));
    }

    pub fn cosine(a: []const f32, b: []const f32) !f32 {
        const d = try wave50Dot(a, b);
        const na = norm2(a);
        const nb = norm2(b);
        if (na <= eps or nb <= eps) return 0;
        return d / (na * nb);
    }

    pub fn l1(a: []const f32, b: []const f32) !f32 {
        if (a.len != b.len) return error.ShapeMismatch;
        var s: f32 = 0;
        for (a, b) |x, y| {
            s += @abs(x - y);
        }
        return s;
    }

    pub fn mean(a: []const f32) f32 {
        if (a.len == 0) return 0;
        var s: f32 = 0;
        for (a) |x| s += x;
        return s / @as(f32, @floatFromInt(a.len));
    }

    pub fn variance(a: []const f32) f32 {
        if (a.len == 0) return 0;
        const m = mean(a);
        var s: f32 = 0;
        for (a) |x| {
            const d = x - m;
            s += d * d;
        }
        return s / @as(f32, @floatFromInt(a.len));
    }

    pub fn normalizeInPlace(a: []f32) void {
        const n = norm2(a);
        if (n <= eps) return;
        for (a) |*x| x.* /= n;
    }

    pub fn entropyFromProbs(p: []const f32) f32 {
        var h: f32 = 0;
        for (p) |x| {
            if (x > 0) h -= x * safeLog(x);
        }
        return h;
    }

    pub fn entropyFromLogits(allocator: std.mem.Allocator, logits: []const f32) !f32 {
        if (logits.len == 0) return 0;
        const tmp = try allocator.alloc(f32, logits.len);
        defer allocator.free(tmp);
        var maxv = logits[0];
        for (logits[1..]) |x| if (x > maxv) {
            maxv = x;
        };
        var z: f32 = 0;
        for (logits, 0..) |x, i| {
            tmp[i] = @exp(x - maxv);
            z += tmp[i];
        }
        if (z <= 0 or !std.math.isFinite(z)) return error.NonFinite;
        for (tmp) |*x| x.* /= z;
        return entropyFromProbs(tmp);
    }

    pub fn jsDivergence(allocator: std.mem.Allocator, p: []const f32, q: []const f32) !f32 {
        if (p.len != q.len) return error.ShapeMismatch;
        const m = try allocator.alloc(f32, p.len);
        defer allocator.free(m);
        for (p, q, 0..) |a, b, i| m[i] = 0.5 * (a + b);
        var out: f32 = 0;
        for (p, q, m) |a, b, c| {
            if (a > 0 and c > 0) out += 0.5 * a * safeLog(a / c);
            if (b > 0 and c > 0) out += 0.5 * b * safeLog(b / c);
        }
        return out;
    }

    pub fn logitMargin(logits: []const f32) f32 {
        if (logits.len < 2) return 0;
        var best: f32 = -std.math.inf(f32);
        var second: f32 = -std.math.inf(f32);
        for (logits) |v| {
            if (v > best) {
                second = best;
                best = v;
            } else if (v > second) {
                second = v;
            }
        }
        return best - second;
    }

    pub fn rms(a: []const f32) f32 {
        if (a.len == 0) return 0;
        var s: f32 = 0;
        for (a) |x| s += x * x;
        return @sqrt(s / @as(f32, @floatFromInt(a.len)));
    }

    pub fn splitmix64(x0: u64) u64 {
        var x = x0 +% 0x9e3779b97f4a7c15;
        x = (x ^ (x >> 30)) *% 0xbf58476d1ce4e5b9;
        x = (x ^ (x >> 27)) *% 0x94d049bb133111eb;
        return x ^ (x >> 31);
    }

    pub fn hashBytes(bytes: []const u8) u64 {
        var h: u64 = 0x6a09e667f3bcc909;
        for (bytes, 0..) |b, i| {
            h ^= splitmix64(@as(u64, b) +% (@as(u64, @intCast(i)) << 8));
            h = std.math.rotl(u64, h, 17) *% 0x9e3779b185ebca87;
        }
        return splitmix64(h ^ @as(u64, @intCast(bytes.len)));
    }

    pub fn hashTokenSequence(tokens: []const u32) u64 {
        var h: u64 = 0x510e527fade682d1;
        for (tokens, 0..) |tok, i| {
            h ^= splitmix64(@as(u64, tok) ^ (@as(u64, @intCast(i)) *% 0x9e3779b97f4a7c15));
            h = std.math.rotl(u64, h, 23) *% 0xd6e8feb86659fd93;
        }
        return splitmix64(h);
    }
};

pub const Wave50SemanticSketch = struct {
    pub const dims = 64;
    values: [dims]f32 = [_]f32{0} ** dims,
    mass: f32 = 0,

    pub fn zero() Wave50SemanticSketch {
        return .{};
    }

    pub fn fromHidden(hidden: []const f32, salt: u64) Wave50SemanticSketch {
        var out = Wave50SemanticSketch{};
        if (hidden.len == 0) return out;
        for (hidden, 0..) |x, i| {
            const h = Wave50Math.splitmix64(@as(u64, @intCast(i)) ^ salt);
            const idx: usize = @intCast(h % dims);
            const sign: f32 = if ((h >> 63) != 0) 1.0 else -1.0;
            out.values[idx] += sign * x;
        }
        Wave50Math.normalizeInPlace(out.values[0..]);
        out.mass = 1.0;
        return out;
    }

    pub fn fromTokens(tokens: []const u32, salt: u64) Wave50SemanticSketch {
        var out = Wave50SemanticSketch{};
        for (tokens, 0..) |tok, i| {
            const h = Wave50Math.splitmix64(@as(u64, tok) ^ salt ^ @as(u64, @intCast(i)));
            const idx0: usize = @intCast(h % dims);
            const idx1: usize = @intCast((h >> 7) % dims);
            const s0: f32 = if ((h & 1) == 0) 1.0 else -1.0;
            const s1: f32 = if ((h & 2) == 0) 0.5 else -0.5;
            out.values[idx0] += s0;
            out.values[idx1] += s1;
        }
        Wave50Math.normalizeInPlace(out.values[0..]);
        out.mass = @floatFromInt(tokens.len);
        return out;
    }

    pub fn cosine(self: Wave50SemanticSketch, other: Wave50SemanticSketch) f32 {
        return Wave50Math.cosine(self.values[0..], other.values[0..]) catch 0;
    }

    pub fn addScaled(self: *Wave50SemanticSketch, other: Wave50SemanticSketch, scale: f32) void {
        for (&self.values, other.values) |*a, b| a.* += b * scale;
        self.mass += other.mass * @abs(scale);
    }

    pub fn ema(self: *Wave50SemanticSketch, incoming: Wave50SemanticSketch, alpha: f32) void {
        const a = Wave50Math.clamp01(alpha);
        for (&self.values, incoming.values) |*x, y| x.* = (1.0 - a) * x.* + a * y;
        self.mass = (1.0 - a) * self.mass + a * incoming.mass;
        Wave50Math.normalizeInPlace(self.values[0..]);
    }

    pub fn distance(self: Wave50SemanticSketch, other: Wave50SemanticSketch) f32 {
        return 1.0 - self.cosine(other);
    }

    pub fn checksum(self: Wave50SemanticSketch) u64 {
        var h: u64 = 0x243f6a8885a308d3;
        for (self.values, 0..) |v, i| {
            const bits: u32 = @bitCast(v);
            h ^= Wave50Math.splitmix64(@as(u64, bits) ^ @as(u64, @intCast(i)));
        }
        return h;
    }
};

pub const Wave50ClaimLedger = struct {
    pub const Polarity = enum(i8) { negative = -1, unknown = 0, positive = 1 };
    pub const Status = enum { active, superseded, disputed, retracted };

    pub const Claim = struct {
        id: u64,
        subject_hash: u64,
        predicate_hash: u64,
        object_hash: u64,
        polarity: Polarity,
        confidence: f32,
        turn: u32,
        token_start: u32,
        token_end: u32,
        status: Status = .active,
        sketch: Wave50SemanticSketch = .{},
        provenance_hash: u64 = 0,

        pub fn tripleHash(self: Claim) u64 {
            return Wave50Math.splitmix64(self.subject_hash ^ std.math.rotl(u64, self.predicate_hash, 21) ^ std.math.rotl(u64, self.object_hash, 43));
        }
    };

    pub const Conflict = struct {
        left_id: u64,
        right_id: u64,
        severity: f32,
        same_triple: bool,
        semantic_overlap: f32,
    };

    allocator: std.mem.Allocator,
    claims: std.ArrayList(Claim) = .empty,
    next_id: u64 = 1,

    pub fn init(allocator: std.mem.Allocator) Wave50ClaimLedger {
        return .{ .allocator = allocator };
    }

    pub fn deinit(self: *Wave50ClaimLedger) void {
        self.claims.deinit(self.allocator);
    }

    pub fn append(self: *Wave50ClaimLedger, claim_in: Claim) !u64 {
        var c = claim_in;
        if (c.id == 0) {
            c.id = self.next_id;
            self.next_id +%= 1;
        }
        c.confidence = Wave50Math.clamp01(c.confidence);
        try self.claims.append(self.allocator, c);
        return c.id;
    }

    pub fn retract(self: *Wave50ClaimLedger, id: u64) bool {
        for (self.claims.items) |*c| {
            if (c.id == id) {
                c.status = .retracted;
                return true;
            }
        }
        return false;
    }

    pub fn findById(self: Wave50ClaimLedger, id: u64) ?Claim {
        for (self.claims.items) |c| if (c.id == id) return c;
        return null;
    }

    pub fn contradiction(a: Claim, b: Claim) ?Conflict {
        if (a.status == .retracted or b.status == .retracted) return null;
        const same_triple = a.subject_hash == b.subject_hash and a.predicate_hash == b.predicate_hash and a.object_hash == b.object_hash;
        const same_subject_pred = a.subject_hash == b.subject_hash and a.predicate_hash == b.predicate_hash;
        const semantic = a.sketch.cosine(b.sketch);
        const opposite = a.polarity != .unknown and b.polarity != .unknown and a.polarity != b.polarity;
        if (!opposite) return null;
        if (!same_triple and !same_subject_pred and semantic < 0.80) return null;
        var severity: f32 = @sqrt(a.confidence * b.confidence);
        if (same_triple) severity *= 1.0 else if (same_subject_pred) severity *= 0.85 else severity *= 0.55;
        severity *= 0.5 + 0.5 * Wave50Math.clamp01(semantic);
        return .{
            .left_id = a.id,
            .right_id = b.id,
            .severity = Wave50Math.clamp01(severity),
            .same_triple = same_triple,
            .semantic_overlap = semantic,
        };
    }

    pub fn conflictsFor(self: Wave50ClaimLedger, allocator: std.mem.Allocator, candidate: Claim) ![]Conflict {
        var out = std.ArrayList(Conflict).empty;
        errdefer out.deinit(allocator);
        for (self.claims.items) |old| {
            if (contradiction(old, candidate)) |c| try out.append(allocator, c);
        }
        return try out.toOwnedSlice(allocator);
    }

    pub fn maxConflict(self: Wave50ClaimLedger, candidate: Claim) f32 {
        var best: f32 = 0;
        for (self.claims.items) |old| {
            if (contradiction(old, candidate)) |c| best = @max(best, c.severity);
        }
        return best;
    }

    pub fn activeCount(self: Wave50ClaimLedger) usize {
        var n: usize = 0;
        for (self.claims.items) |c| if (c.status == .active) {
            n += 1;
        };
        return n;
    }

    pub fn compact(self: *Wave50ClaimLedger, min_confidence: f32, keep_recent_turns: u32, current_turn: u32) void {
        var dst: usize = 0;
        for (self.claims.items) |c| {
            const recent = current_turn -| c.turn <= keep_recent_turns;
            const keep = c.status == .active and (c.confidence >= min_confidence or recent);
            if (keep) {
                self.claims.items[dst] = c;
                dst += 1;
            }
        }
        self.claims.shrinkRetainingCapacity(dst);
    }
};

pub const Wave50StateLedger = struct {
    pub const ValueKind = enum { unknown, boolean, integer, scalar, symbolic_hash, semantic };

    pub const Value = union(ValueKind) {
        unknown: void,
        boolean: bool,
        integer: i64,
        scalar: f64,
        symbolic_hash: u64,
        semantic: Wave50SemanticSketch,
    };

    pub const Entry = struct {
        entity_hash: u64,
        attribute_hash: u64,
        value: Value,
        confidence: f32,
        version: u64,
        turn: u32,
        source_claim_id: u64,
        expires_turn: ?u32 = null,
    };

    allocator: std.mem.Allocator,
    entries: std.ArrayList(Entry) = .empty,
    version: u64 = 1,

    pub fn init(allocator: std.mem.Allocator) Wave50StateLedger {
        return .{ .allocator = allocator };
    }

    pub fn deinit(self: *Wave50StateLedger) void {
        self.entries.deinit(self.allocator);
    }

    pub fn put(self: *Wave50StateLedger, entry_in: Entry) !void {
        var e = entry_in;
        e.confidence = Wave50Math.clamp01(e.confidence);
        e.version = self.version;
        self.version +%= 1;
        for (self.entries.items) |*old| {
            if (old.entity_hash == e.entity_hash and old.attribute_hash == e.attribute_hash) {
                old.* = e;
                return;
            }
        }
        try self.entries.append(self.allocator, e);
    }

    pub fn get(self: Wave50StateLedger, entity_hash: u64, attribute_hash: u64, current_turn: u32) ?Entry {
        for (self.entries.items) |e| {
            if (e.entity_hash != entity_hash or e.attribute_hash != attribute_hash) continue;
            if (e.expires_turn) |x| if (current_turn > x) return null;
            return e;
        }
        return null;
    }

    pub fn expire(self: *Wave50StateLedger, current_turn: u32) void {
        var dst: usize = 0;
        for (self.entries.items) |e| {
            const expired = if (e.expires_turn) |x| current_turn > x else false;
            if (!expired) {
                self.entries.items[dst] = e;
                dst += 1;
            }
        }
        self.entries.shrinkRetainingCapacity(dst);
    }

    pub fn semanticMismatch(a: Value, b: Value) f32 {
        if (std.meta.activeTag(a) != std.meta.activeTag(b)) return 1.0;
        return switch (a) {
            .unknown => 0,
            .boolean => |av| if (av == b.boolean) 0 else 1,
            .integer => |av| if (av == b.integer) 0 else 1,
            .scalar => |av| blk: {
                const bv = b.scalar;
                const denom = @max(@abs(av), @max(@abs(bv), 1e-9));
                break :blk @floatCast(@min(@as(f64, 1.0), @abs(av - bv) / denom));
            },
            .symbolic_hash => |av| if (av == b.symbolic_hash) 0 else 1,
            .semantic => |av| 1.0 - Wave50Math.clamp01((av.cosine(b.semantic) + 1.0) * 0.5),
        };
    }
};

pub const Wave50DiscourseGraph = struct {
    pub const NodeKind = enum { entity, topic, claim, question, goal, instruction, evidence, plan_step };
    pub const EdgeKind = enum { mentions, supports, contradicts, answers, depends_on, elaborates, causes, before, after, resolves, refers_to };

    pub const Node = struct {
        id: u64,
        kind: NodeKind,
        key_hash: u64,
        salience: f32,
        confidence: f32,
        created_turn: u32,
        last_turn: u32,
        mentions: u32 = 1,
        sketch: Wave50SemanticSketch = .{},
    };

    pub const Edge = struct {
        from: u64,
        to: u64,
        kind: EdgeKind,
        weight: f32,
        turn: u32,
    };

    allocator: std.mem.Allocator,
    nodes: std.ArrayList(Node) = .empty,
    edges: std.ArrayList(Edge) = .empty,
    next_id: u64 = 1,

    pub fn init(allocator: std.mem.Allocator) Wave50DiscourseGraph {
        return .{ .allocator = allocator };
    }

    pub fn deinit(self: *Wave50DiscourseGraph) void {
        self.nodes.deinit(self.allocator);
        self.edges.deinit(self.allocator);
    }

    pub fn upsertNode(self: *Wave50DiscourseGraph, kind: NodeKind, key_hash: u64, salience: f32, confidence: f32, turn: u32, sketch: Wave50SemanticSketch) !u64 {
        for (self.nodes.items) |*n| {
            if (n.kind == kind and n.key_hash == key_hash) {
                n.salience = @max(n.salience * 0.92, Wave50Math.clamp01(salience));
                n.confidence = @max(n.confidence, Wave50Math.clamp01(confidence));
                n.last_turn = turn;
                n.mentions +|= 1;
                n.sketch.ema(sketch, 0.25);
                return n.id;
            }
        }
        const id = self.next_id;
        self.next_id +%= 1;
        try self.nodes.append(self.allocator, .{
            .id = id,
            .kind = kind,
            .key_hash = key_hash,
            .salience = Wave50Math.clamp01(salience),
            .confidence = Wave50Math.clamp01(confidence),
            .created_turn = turn,
            .last_turn = turn,
            .sketch = sketch,
        });
        return id;
    }

    pub fn addEdge(self: *Wave50DiscourseGraph, from: u64, to: u64, kind: EdgeKind, weight: f32, turn: u32) !void {
        for (self.edges.items) |*e| {
            if (e.from == from and e.to == to and e.kind == kind) {
                e.weight = @max(e.weight, Wave50Math.clamp01(weight));
                e.turn = turn;
                return;
            }
        }
        try self.edges.append(self.allocator, .{ .from = from, .to = to, .kind = kind, .weight = Wave50Math.clamp01(weight), .turn = turn });
    }

    pub fn decay(self: *Wave50DiscourseGraph, current_turn: u32, half_life_turns: f32) void {
        const hl = @max(half_life_turns, @as(f32, 1e-3));
        for (self.nodes.items) |*n| {
            const age: f32 = @floatFromInt(current_turn -| n.last_turn);
            n.salience *= @exp(-0.69314718056 * age / hl);
        }
        for (self.edges.items) |*e| {
            const age: f32 = @floatFromInt(current_turn -| e.turn);
            e.weight *= @exp(-0.69314718056 * age / hl);
        }
    }

    pub fn topNodes(self: Wave50DiscourseGraph, allocator: std.mem.Allocator, kind: ?NodeKind, limit: usize) ![]Node {
        var tmp = std.ArrayList(Node).empty;
        defer tmp.deinit(allocator);
        for (self.nodes.items) |n| {
            if (kind == null or n.kind == kind.?) try tmp.append(allocator, n);
        }
        std.mem.sort(Node, tmp.items, {}, struct {
            fn lessThan(_: void, a: Node, b: Node) bool {
                if (a.salience != b.salience) return a.salience > b.salience;
                return a.last_turn > b.last_turn;
            }
        }.lessThan);
        const n = @min(limit, tmp.items.len);
        const out = try allocator.alloc(Node, n);
        @memcpy(out, tmp.items[0..n]);
        return out;
    }

    pub fn unresolvedQuestions(self: Wave50DiscourseGraph) usize {
        var count: usize = 0;
        for (self.nodes.items) |n| {
            if (n.kind != .question) continue;
            var answered = false;
            for (self.edges.items) |e| {
                if (e.to == n.id and (e.kind == .answers or e.kind == .resolves) and e.weight >= 0.5) {
                    answered = true;
                    break;
                }
            }
            if (!answered) count += 1;
        }
        return count;
    }
};

pub const Wave50AssociativeMemory = struct {
    pub const Slot = struct {
        valid: bool = false,
        key: Wave50SemanticSketch = .{},
        value: Wave50SemanticSketch = .{},
        salience: f32 = 0,
        novelty: f32 = 0,
        write_turn: u32 = 0,
        read_turn: u32 = 0,
        read_count: u32 = 0,
        tag: u64 = 0,
    };

    pub const Match = struct {
        index: usize,
        score: f32,
        value: Wave50SemanticSketch,
        tag: u64,
    };

    allocator: std.mem.Allocator,
    slots: []Slot,
    writes: u64 = 0,
    reads: u64 = 0,

    pub fn init(allocator: std.mem.Allocator, capacity: usize) !Wave50AssociativeMemory {
        const slots = try allocator.alloc(Slot, capacity);
        @memset(slots, Slot{});
        return .{ .allocator = allocator, .slots = slots };
    }

    pub fn deinit(self: *Wave50AssociativeMemory) void {
        self.allocator.free(self.slots);
        self.* = undefined;
    }

    fn evictionScore(slot: Slot, current_turn: u32) f32 {
        if (!slot.valid) return -std.math.inf(f32);
        const age: f32 = @floatFromInt(current_turn -| slot.write_turn);
        const idle: f32 = @floatFromInt(current_turn -| slot.read_turn);
        const utility = slot.salience * (1.0 + @log(1.0 + @as(f32, @floatFromInt(slot.read_count))));
        return 0.02 * age + 0.01 * idle - utility - 0.25 * slot.novelty;
    }

    fn chooseSlot(self: Wave50AssociativeMemory, current_turn: u32) usize {
        for (self.slots, 0..) |slot, i| if (!slot.valid) return i;
        var best_i: usize = 0;
        var best_score = evictionScore(self.slots[0], current_turn);
        for (self.slots[1..], 1..) |slot, i| {
            const s = evictionScore(slot, current_turn);
            if (s > best_score) {
                best_score = s;
                best_i = i;
            }
        }
        return best_i;
    }

    pub fn write(self: *Wave50AssociativeMemory, key: Wave50SemanticSketch, value: Wave50SemanticSketch, salience: f32, novelty: f32, turn: u32, tag: u64) usize {
        const idx = self.chooseSlot(turn);
        self.slots[idx] = .{
            .valid = true,
            .key = key,
            .value = value,
            .salience = Wave50Math.clamp01(salience),
            .novelty = Wave50Math.clamp01(novelty),
            .write_turn = turn,
            .read_turn = turn,
            .read_count = 0,
            .tag = tag,
        };
        self.writes +%= 1;
        return idx;
    }

    pub fn retrieve(self: *Wave50AssociativeMemory, allocator: std.mem.Allocator, query: Wave50SemanticSketch, turn: u32, limit: usize, min_score: f32) ![]Match {
        var tmp = std.ArrayList(Match).empty;
        defer tmp.deinit(allocator);
        for (self.slots, 0..) |slot, i| {
            if (!slot.valid) continue;
            const similarity = query.cosine(slot.key);
            const age: f32 = @floatFromInt(turn -| slot.write_turn);
            const recency = @exp(-age / 256.0);
            const score = similarity * (0.65 + 0.20 * slot.salience + 0.15 * recency);
            if (score >= min_score) try tmp.append(allocator, .{ .index = i, .score = score, .value = slot.value, .tag = slot.tag });
        }
        std.mem.sort(Match, tmp.items, {}, struct {
            fn lessThan(_: void, a: Match, b: Match) bool {
                return a.score > b.score;
            }
        }.lessThan);
        const n = @min(limit, tmp.items.len);
        const out = try allocator.alloc(Match, n);
        @memcpy(out, tmp.items[0..n]);
        for (out) |m| {
            self.slots[m.index].read_turn = turn;
            self.slots[m.index].read_count +|= 1;
        }
        self.reads +%= n;
        return out;
    }

    pub fn mergeNearest(self: *Wave50AssociativeMemory, key: Wave50SemanticSketch, value: Wave50SemanticSketch, threshold: f32, turn: u32) bool {
        var best_idx: ?usize = null;
        var best: f32 = threshold;
        for (self.slots, 0..) |slot, i| {
            if (!slot.valid) continue;
            const s = key.cosine(slot.key);
            if (s > best) {
                best = s;
                best_idx = i;
            }
        }
        if (best_idx) |i| {
            self.slots[i].key.ema(key, 0.20);
            self.slots[i].value.ema(value, 0.25);
            self.slots[i].salience = Wave50Math.clamp01(self.slots[i].salience + 0.05);
            self.slots[i].write_turn = turn;
            return true;
        }
        return false;
    }
};

pub const Wave50MultiHorizonMemory = struct {
    pub const Horizon = struct {
        span_tokens: usize,
        alpha: f32,
        state: Wave50SemanticSketch = .{},
        updates: u64 = 0,
        last_token: u64 = 0,
    };

    horizons: [8]Horizon = .{
        .{ .span_tokens = 8, .alpha = 0.35 },
        .{ .span_tokens = 32, .alpha = 0.18 },
        .{ .span_tokens = 128, .alpha = 0.08 },
        .{ .span_tokens = 512, .alpha = 0.035 },
        .{ .span_tokens = 2048, .alpha = 0.015 },
        .{ .span_tokens = 8192, .alpha = 0.006 },
        .{ .span_tokens = 32768, .alpha = 0.0025 },
        .{ .span_tokens = 131072, .alpha = 0.001 },
    },

    pub fn update(self: *Wave50MultiHorizonMemory, sketch: Wave50SemanticSketch, token_index: u64) void {
        for (&self.horizons) |*h| {
            h.state.ema(sketch, h.alpha);
            h.updates +%= 1;
            h.last_token = token_index;
        }
    }

    pub fn coherenceVector(self: Wave50MultiHorizonMemory) [8]f32 {
        var out: [8]f32 = undefined;
        var i: usize = 0;
        while (i < self.horizons.len) : (i += 1) {
            if (i == 0) {
                out[i] = 1.0;
            } else {
                out[i] = self.horizons[0].state.cosine(self.horizons[i].state);
            }
        }
        return out;
    }

    pub fn drift(self: Wave50MultiHorizonMemory) f32 {
        const c = self.coherenceVector();
        var weighted: f32 = 0;
        var weight: f32 = 0;
        for (c[1..], 1..) |x, i| {
            const w = 1.0 / @as(f32, @floatFromInt(i));
            weighted += w * (1.0 - x);
            weight += w;
        }
        return if (weight > 0) Wave50Math.clamp01(weighted / weight) else 0;
    }

    pub fn consensus(self: Wave50MultiHorizonMemory) Wave50SemanticSketch {
        var out = Wave50SemanticSketch{};
        var total: f32 = 0;
        for (self.horizons, 0..) |h, i| {
            const w = 1.0 / @sqrt(1.0 + @as(f32, @floatFromInt(i)));
            out.addScaled(h.state, w);
            total += w;
        }
        if (total > 0) {
            for (&out.values) |*x| x.* /= total;
            Wave50Math.normalizeInPlace(out.values[0..]);
        }
        return out;
    }
};

pub const Wave50EntropyDebt = struct {
    debt: f32 = 0,
    smoothed_entropy: f32 = 0,
    smoothed_margin: f32 = 0,
    spikes: u32 = 0,
    low_confidence_run: u32 = 0,

    pub const Update = struct {
        debt: f32,
        uncertainty: f32,
        temperature_scale: f32,
        top_p_scale: f32,
        verification_pressure: f32,
    };

    pub fn observe(self: *Wave50EntropyDebt, entropy: f32, margin: f32, target_entropy: f32, drift: f32, contradiction_risk: f32) Update {
        const e = @max(entropy, @as(f32, 0));
        const m = @max(margin, @as(f32, 0));
        self.smoothed_entropy = 0.92 * self.smoothed_entropy + 0.08 * e;
        self.smoothed_margin = 0.92 * self.smoothed_margin + 0.08 * m;
        const excess = e - target_entropy;
        const uncertainty = Wave50Math.sigmoid(0.8 * excess - 0.35 * m + 1.1 * drift + 1.5 * contradiction_risk);
        self.debt = @max(@as(f32, 0), self.debt * 0.965 + excess * 0.06 + drift * 0.10 + contradiction_risk * 0.18);
        if (uncertainty > 0.72) self.low_confidence_run +|= 1 else self.low_confidence_run = 0;
        if (e > target_entropy * 1.5) self.spikes +|= 1;
        const verification = Wave50Math.clamp01(0.35 * uncertainty + 0.35 * Wave50Math.sigmoid(self.debt - 1.0) + 0.30 * contradiction_risk);
        return .{
            .debt = self.debt,
            .uncertainty = uncertainty,
            .temperature_scale = Wave50Math.lerp(1.05, 0.55, verification),
            .top_p_scale = Wave50Math.lerp(1.00, 0.78, verification),
            .verification_pressure = verification,
        };
    }

    pub fn repay(self: *Wave50EntropyDebt, amount: f32) void {
        self.debt = @max(@as(f32, 0), self.debt - @max(amount, @as(f32, 0)));
    }
};

pub const Wave50LayerAgreement = struct {
    pub const Snapshot = struct {
        layer: u16,
        logits: []const f32,
        weight: f32 = 1.0,
    };

    pub const Metrics = struct {
        mean_js: f32,
        top1_agreement: f32,
        margin_consensus: f32,
        instability: f32,
    };

    fn topIndex(logits: []const f32) ?usize {
        if (logits.len == 0) return null;
        var idx: usize = 0;
        for (logits[1..], 1..) |x, i| if (x > logits[idx]) {
            idx = i;
        };
        return idx;
    }

    fn softmaxInto(logits: []const f32, out: []f32) !void {
        if (logits.len != out.len or logits.len == 0) return error.ShapeMismatch;
        var m = logits[0];
        for (logits[1..]) |x| if (x > m) {
            m = x;
        };
        var z: f32 = 0;
        for (logits, out) |x, *y| {
            y.* = @exp(x - m);
            z += y.*;
        }
        if (z <= 0 or !std.math.isFinite(z)) return error.NonFinite;
        for (out) |*x| x.* /= z;
    }

    pub fn measure(allocator: std.mem.Allocator, snaps: []const Snapshot) !Metrics {
        if (snaps.len == 0) return .{ .mean_js = 0, .top1_agreement = 1, .margin_consensus = 0, .instability = 0 };
        const vocab = snaps[0].logits.len;
        if (vocab == 0) return error.ShapeMismatch;
        const refp = try allocator.alloc(f32, vocab);
        defer allocator.free(refp);
        try softmaxInto(snaps[snaps.len - 1].logits, refp);
        var js_sum: f32 = 0;
        var js_weight: f32 = 0;
        const final_top = topIndex(snaps[snaps.len - 1].logits).?;
        var agree_weight: f32 = 0;
        var total_weight: f32 = 0;
        var margin_sum: f32 = 0;
        for (snaps) |s| {
            if (s.logits.len != vocab) return error.ShapeMismatch;
            const p = try allocator.alloc(f32, vocab);
            defer allocator.free(p);
            try softmaxInto(s.logits, p);
            const w = @max(s.weight, @as(f32, 0));
            js_sum += w * (try Wave50Math.jsDivergence(allocator, p, refp));
            js_weight += w;
            if (topIndex(s.logits).? == final_top) agree_weight += w;
            total_weight += w;
            margin_sum += w * Wave50Math.logitMargin(s.logits);
        }
        const mean_js = if (js_weight > 0) js_sum / js_weight else 0;
        const agreement = if (total_weight > 0) agree_weight / total_weight else 1;
        const margin = if (total_weight > 0) margin_sum / total_weight else 0;
        return .{
            .mean_js = mean_js,
            .top1_agreement = agreement,
            .margin_consensus = margin,
            .instability = Wave50Math.clamp01(0.55 * Wave50Math.sigmoid(4.0 * mean_js - 1.0) + 0.45 * (1.0 - agreement)),
        };
    }

    pub fn fuse(allocator: std.mem.Allocator, out: []f32, snaps: []const Snapshot, contrast_strength: f32) !void {
        if (snaps.len == 0) return error.ShapeMismatch;
        const vocab = snaps[0].logits.len;
        if (out.len != vocab) return error.ShapeMismatch;
        @memset(out, 0);
        var total: f32 = 0;
        for (snaps) |s| {
            if (s.logits.len != vocab) return error.ShapeMismatch;
            const w = @max(s.weight, @as(f32, 0));
            for (out, s.logits) |*o, x| o.* += w * x;
            total += w;
        }
        if (total > 0) {
            for (out) |*x| {
                x.* /= total;
            }
        }
        if (snaps.len >= 2 and contrast_strength != 0) {
            const early = snaps[0].logits;
            const late = snaps[snaps.len - 1].logits;
            for (out, early, late) |*o, e, l| o.* += contrast_strength * (l - e);
        }
        _ = allocator;
    }
};

pub const Wave50AnchorRegistry = struct {
    pub const AnchorKind = enum { system_rule, user_goal, named_entity, numeric_fact, temporal_fact, plan, unresolved_question, style_constraint };
    pub const Anchor = struct {
        id: u64,
        kind: AnchorKind,
        key_hash: u64,
        priority: f32,
        confidence: f32,
        first_turn: u32,
        last_turn: u32,
        last_grounded_token: u64,
        sketch: Wave50SemanticSketch,
        payload_hash: u64,
    };

    allocator: std.mem.Allocator,
    anchors: std.ArrayList(Anchor) = .empty,
    next_id: u64 = 1,

    pub fn init(allocator: std.mem.Allocator) Wave50AnchorRegistry {
        return .{ .allocator = allocator };
    }
    pub fn deinit(self: *Wave50AnchorRegistry) void {
        self.anchors.deinit(self.allocator);
    }

    pub fn upsert(self: *Wave50AnchorRegistry, kind: AnchorKind, key_hash: u64, priority: f32, confidence: f32, turn: u32, token_index: u64, sketch: Wave50SemanticSketch, payload_hash: u64) !u64 {
        for (self.anchors.items) |*a| {
            if (a.kind == kind and a.key_hash == key_hash) {
                a.priority = @max(a.priority, Wave50Math.clamp01(priority));
                a.confidence = @max(a.confidence, Wave50Math.clamp01(confidence));
                a.last_turn = turn;
                a.last_grounded_token = token_index;
                a.sketch.ema(sketch, 0.20);
                a.payload_hash = payload_hash;
                return a.id;
            }
        }
        const id = self.next_id;
        self.next_id +%= 1;
        try self.anchors.append(self.allocator, .{
            .id = id,
            .kind = kind,
            .key_hash = key_hash,
            .priority = Wave50Math.clamp01(priority),
            .confidence = Wave50Math.clamp01(confidence),
            .first_turn = turn,
            .last_turn = turn,
            .last_grounded_token = token_index,
            .sketch = sketch,
            .payload_hash = payload_hash,
        });
        return id;
    }

    pub fn regroundPressure(self: Wave50AnchorRegistry, current_token: u64, live: Wave50SemanticSketch) f32 {
        var pressure: f32 = 0;
        var weight: f32 = 0;
        for (self.anchors.items) |a| {
            const age = @as(f32, @floatFromInt(current_token -| a.last_grounded_token));
            const stale = 1.0 - @exp(-age / 512.0);
            const mismatch = 1.0 - Wave50Math.clamp01((a.sketch.cosine(live) + 1.0) * 0.5);
            const w = a.priority * a.confidence;
            pressure += w * (0.55 * stale + 0.45 * mismatch);
            weight += w;
        }
        return if (weight > 0) Wave50Math.clamp01(pressure / weight) else 0;
    }

    pub fn markGrounded(self: *Wave50AnchorRegistry, id: u64, token_index: u64, turn: u32) bool {
        for (self.anchors.items) |*a| {
            if (a.id == id) {
                a.last_grounded_token = token_index;
                a.last_turn = turn;
                return true;
            }
        }
        return false;
    }
};

pub const Wave50CandidateVerifier = struct {
    pub const Features = struct {
        model_logprob: f32 = 0,
        semantic_continuity: f32 = 0,
        anchor_alignment: f32 = 0,
        contradiction_risk: f32 = 0,
        repetition_risk: f32 = 0,
        layer_instability: f32 = 0,
        unresolved_question_gain: f32 = 0,
        plan_alignment: f32 = 0,
        entropy: f32 = 0,
        novelty: f32 = 0,
    };

    pub const Weights = struct {
        model_logprob: f32 = 1.0,
        semantic_continuity: f32 = 0.65,
        anchor_alignment: f32 = 0.55,
        contradiction_risk: f32 = -1.35,
        repetition_risk: f32 = -0.45,
        layer_instability: f32 = -0.35,
        unresolved_question_gain: f32 = 0.35,
        plan_alignment: f32 = 0.45,
        entropy: f32 = -0.08,
        novelty: f32 = 0.15,
    };

    pub fn score(f: Features, w: Weights) f32 {
        return f.model_logprob * w.model_logprob +
            f.semantic_continuity * w.semantic_continuity +
            f.anchor_alignment * w.anchor_alignment +
            f.contradiction_risk * w.contradiction_risk +
            f.repetition_risk * w.repetition_risk +
            f.layer_instability * w.layer_instability +
            f.unresolved_question_gain * w.unresolved_question_gain +
            f.plan_alignment * w.plan_alignment +
            f.entropy * w.entropy +
            f.novelty * w.novelty;
    }

    pub fn softAccept(score_value: f32, threshold: f32, sharpness: f32) f32 {
        return Wave50Math.sigmoid((score_value - threshold) * sharpness);
    }
};

pub const Wave50CounterfactualAblation = struct {
    pub const View = enum { full_memory, no_long_term, no_claims, no_state, no_anchors, local_only };
    pub const Score = struct {
        view: View,
        candidate_score: f32,
        logprob: f32,
        contradiction: f32,
        drift: f32,
    };

    pub const Result = struct {
        preferred: View,
        robustness: f32,
        memory_dependency: f32,
        suspicious_dependency: bool,
    };

    pub fn analyze(scores: []const Score) Result {
        if (scores.len == 0) return .{ .preferred = .local_only, .robustness = 0, .memory_dependency = 0, .suspicious_dependency = false };
        var best = scores[0];
        var min_score = scores[0].candidate_score;
        var max_score = scores[0].candidate_score;
        var full: ?f32 = null;
        var local: ?f32 = null;
        for (scores) |s| {
            if (s.candidate_score > best.candidate_score) best = s;
            min_score = @min(min_score, s.candidate_score);
            max_score = @max(max_score, s.candidate_score);
            if (s.view == .full_memory) full = s.candidate_score;
            if (s.view == .local_only) local = s.candidate_score;
        }
        const spread = max_score - min_score;
        const dep = if (full != null and local != null) full.? - local.? else 0;
        return .{
            .preferred = best.view,
            .robustness = 1.0 / (1.0 + @abs(spread)),
            .memory_dependency = dep,
            .suspicious_dependency = dep > 2.0 and best.contradiction > 0.35,
        };
    }
};

pub const Wave50SentencePlanner = struct {
    pub const Intent = enum { answer, explain, qualify, contrast, enumerate, transition, summarize, ask, conclude, cite, code, warn };

    pub const Plan = struct {
        intent: Intent,
        target_tokens: u16,
        must_mention: [8]u64 = [_]u64{0} ** 8,
        must_count: u8 = 0,
        avoid_hashes: [8]u64 = [_]u64{0} ** 8,
        avoid_count: u8 = 0,
        desired_sketch: Wave50SemanticSketch = .{},
        factuality_weight: f32 = 0.5,
        novelty_weight: f32 = 0.3,
        closure_weight: f32 = 0.5,
    };

    pub const Progress = struct {
        emitted_tokens: u16 = 0,
        mentioned_mask: u8 = 0,
        violated_avoid_mask: u8 = 0,
        semantic_alignment: f32 = 0,
        complete: bool = false,
    };

    pub fn update(plan: Plan, progress: *Progress, token_hash: u64, live: Wave50SemanticSketch, ended_sentence: bool) void {
        progress.emitted_tokens +|= 1;
        var i: usize = 0;
        while (i < plan.must_count) : (i += 1) {
            if (plan.must_mention[i] == token_hash) progress.mentioned_mask |= @as(u8, 1) << @intCast(i);
        }
        i = 0;
        while (i < plan.avoid_count) : (i += 1) {
            if (plan.avoid_hashes[i] == token_hash) progress.violated_avoid_mask |= @as(u8, 1) << @intCast(i);
        }
        progress.semantic_alignment = Wave50Math.clamp01((plan.desired_sketch.cosine(live) + 1.0) * 0.5);
        const need_mask: u8 = if (plan.must_count == 8) 0xff else (@as(u8, 1) << @intCast(plan.must_count)) - 1;
        const coverage = (progress.mentioned_mask & need_mask) == need_mask;
        progress.complete = ended_sentence and coverage and progress.emitted_tokens >= @min(plan.target_tokens, 4);
    }

    pub fn tokenPressure(plan: Plan, progress: Progress) f32 {
        const length_ratio = @as(f32, @floatFromInt(progress.emitted_tokens)) / @max(@as(f32, @floatFromInt(plan.target_tokens)), 1.0);
        const closure = Wave50Math.sigmoid((length_ratio - 0.85) * 6.0) * plan.closure_weight;
        const align_penalty = (1.0 - progress.semantic_alignment) * 0.5;
        const avoid_penalty = if (progress.violated_avoid_mask != 0) 0.5 else 0;
        return closure - align_penalty - avoid_penalty;
    }
};

pub const Wave50DialogueCommitments = struct {
    pub const Kind = enum { promise, requirement, prohibition, preference, definition, correction, open_question, task_step };
    pub const Item = struct {
        id: u64,
        kind: Kind,
        key_hash: u64,
        turn: u32,
        priority: f32,
        satisfied: bool = false,
        superseded: bool = false,
        sketch: Wave50SemanticSketch = .{},
    };

    allocator: std.mem.Allocator,
    items: std.ArrayList(Item) = .empty,
    next_id: u64 = 1,

    pub fn init(allocator: std.mem.Allocator) Wave50DialogueCommitments {
        return .{ .allocator = allocator };
    }
    pub fn deinit(self: *Wave50DialogueCommitments) void {
        self.items.deinit(self.allocator);
    }

    pub fn add(self: *Wave50DialogueCommitments, item_in: Item) !u64 {
        var item = item_in;
        if (item.id == 0) {
            item.id = self.next_id;
            self.next_id +%= 1;
        }
        item.priority = Wave50Math.clamp01(item.priority);
        try self.items.append(self.allocator, item);
        return item.id;
    }

    pub fn satisfy(self: *Wave50DialogueCommitments, id: u64) bool {
        for (self.items.items) |*x| if (x.id == id) {
            x.satisfied = true;
            return true;
        };
        return false;
    }

    pub fn outstandingWeight(self: Wave50DialogueCommitments) f32 {
        var s: f32 = 0;
        for (self.items.items) |x| if (!x.satisfied and !x.superseded) {
            s += x.priority;
        };
        return s;
    }

    pub fn alignment(self: Wave50DialogueCommitments, sketch: Wave50SemanticSketch) f32 {
        var weighted: f32 = 0;
        var weight: f32 = 0;
        for (self.items.items) |x| {
            if (x.satisfied or x.superseded) continue;
            const w = x.priority;
            weighted += w * Wave50Math.clamp01((x.sketch.cosine(sketch) + 1.0) * 0.5);
            weight += w;
        }
        return if (weight > 0) weighted / weight else 1.0;
    }
};

pub const Wave50TopicManifold = struct {
    pub const dims = 16;
    center: [dims]f32 = [_]f32{0} ** dims,
    velocity: [dims]f32 = [_]f32{0} ** dims,
    acceleration: [dims]f32 = [_]f32{0} ** dims,
    initialized: bool = false,

    fn project(sketch: Wave50SemanticSketch) [dims]f32 {
        var out: [dims]f32 = [_]f32{0} ** dims;
        var i: usize = 0;
        while (i < Wave50SemanticSketch.dims) : (i += 1) {
            const j = i % dims;
            const sign: f32 = if (((i / dims) & 1) == 0) 1 else -1;
            out[j] += sign * sketch.values[i];
        }
        Wave50Math.normalizeInPlace(out[0..]);
        return out;
    }

    pub fn observe(self: *Wave50TopicManifold, sketch: Wave50SemanticSketch, alpha: f32) void {
        const p = project(sketch);
        if (!self.initialized) {
            self.center = p;
            self.initialized = true;
            return;
        }
        const a = Wave50Math.clamp01(alpha);
        var i: usize = 0;
        while (i < dims) : (i += 1) {
            const new_velocity = p[i] - self.center[i];
            const new_accel = new_velocity - self.velocity[i];
            self.center[i] = (1 - a) * self.center[i] + a * p[i];
            self.velocity[i] = (1 - a) * self.velocity[i] + a * new_velocity;
            self.acceleration[i] = (1 - a) * self.acceleration[i] + a * new_accel;
        }
        Wave50Math.normalizeInPlace(self.center[0..]);
    }

    pub fn drift(self: Wave50TopicManifold, sketch: Wave50SemanticSketch) f32 {
        if (!self.initialized) return 0;
        const p = project(sketch);
        return 1.0 - Wave50Math.clamp01(((Wave50Math.cosine(self.center[0..], p[0..]) catch 0) + 1.0) * 0.5);
    }

    pub fn turnSharpness(self: Wave50TopicManifold) f32 {
        return Wave50Math.clamp01(Wave50Math.norm2(self.acceleration[0..]) / 2.0);
    }
};

pub const Wave50AdaptiveSampling = struct {
    pub const Base = struct {
        temperature: f32 = 0.8,
        top_p: f32 = 0.95,
        min_p: f32 = 0.05,
        repetition_penalty: f32 = 1.08,
        candidate_width: usize = 8,
    };

    pub const Signals = struct {
        entropy_debt: f32 = 0,
        drift: f32 = 0,
        contradiction: f32 = 0,
        layer_instability: f32 = 0,
        anchor_pressure: f32 = 0,
        plan_pressure: f32 = 0,
        repetition: f32 = 0,
        novelty: f32 = 0,
    };

    pub const Effective = struct {
        temperature: f32,
        top_p: f32,
        min_p: f32,
        repetition_penalty: f32,
        candidate_width: usize,
        verification_strength: f32,
        force_reground: bool,
    };

    pub fn derive(base: Base, s: Signals) Effective {
        const risk = Wave50Math.clamp01(
            0.20 * Wave50Math.sigmoid(s.entropy_debt - 1.0) +
                0.18 * s.drift +
                0.24 * s.contradiction +
                0.12 * s.layer_instability +
                0.16 * s.anchor_pressure +
                0.10 * s.plan_pressure,
        );
        const creativity = Wave50Math.clamp01(s.novelty * (1.0 - risk));
        return .{
            .temperature = std.math.clamp(base.temperature * Wave50Math.lerp(1.10 + 0.10 * creativity, 0.48, risk), 0.05, 1.5),
            .top_p = std.math.clamp(base.top_p * Wave50Math.lerp(1.02, 0.72, risk), 0.15, 1.0),
            .min_p = std.math.clamp(base.min_p * Wave50Math.lerp(0.8, 2.2, risk), 0.0, 0.5),
            .repetition_penalty = std.math.clamp(base.repetition_penalty + 0.30 * s.repetition - 0.08 * creativity, 1.0, 1.8),
            .candidate_width = @max(@as(usize, 2), @min(@as(usize, 32), base.candidate_width + @as(usize, @intFromFloat(@floor(risk * 12.0))))),
            .verification_strength = risk,
            .force_reground = s.anchor_pressure > 0.72 or s.contradiction > 0.65,
        };
    }
};

pub const Wave50CoherenceSignals = struct {
    token_index: u64 = 0,
    turn: u32 = 0,
    entropy: f32 = 0,
    entropy_debt: f32 = 0,
    logit_margin: f32 = 0,
    topic_drift: f32 = 0,
    horizon_drift: f32 = 0,
    contradiction_risk: f32 = 0,
    anchor_pressure: f32 = 0,
    commitment_alignment: f32 = 1,
    layer_instability: f32 = 0,
    repetition_risk: f32 = 0,
    novelty: f32 = 0,
    plan_pressure: f32 = 0,
    unresolved_questions: u32 = 0,

    pub fn risk(self: Wave50CoherenceSignals) f32 {
        return Wave50Math.clamp01(
            0.15 * Wave50Math.sigmoid(self.entropy_debt - 1.0) +
                0.13 * self.topic_drift +
                0.13 * self.horizon_drift +
                0.23 * self.contradiction_risk +
                0.13 * self.anchor_pressure +
                0.10 * self.layer_instability +
                0.08 * self.repetition_risk +
                0.05 * (1.0 - self.commitment_alignment),
        );
    }
};

pub const Wave50CoherenceRuntime = struct {
    allocator: std.mem.Allocator,
    claims: Wave50ClaimLedger,
    state: Wave50StateLedger,
    graph: Wave50DiscourseGraph,
    memory: Wave50AssociativeMemory,
    horizons: Wave50MultiHorizonMemory = .{},
    entropy_debt: Wave50EntropyDebt = .{},
    anchors: Wave50AnchorRegistry,
    commitments: Wave50DialogueCommitments,
    topics: Wave50TopicManifold = .{},
    signals: Wave50CoherenceSignals = .{},
    live_sketch: Wave50SemanticSketch = .{},

    pub fn init(allocator: std.mem.Allocator, memory_slots: usize) !Wave50CoherenceRuntime {
        return .{
            .allocator = allocator,
            .claims = Wave50ClaimLedger.init(allocator),
            .state = Wave50StateLedger.init(allocator),
            .graph = Wave50DiscourseGraph.init(allocator),
            .memory = try Wave50AssociativeMemory.init(allocator, memory_slots),
            .anchors = Wave50AnchorRegistry.init(allocator),
            .commitments = Wave50DialogueCommitments.init(allocator),
        };
    }

    pub fn deinit(self: *Wave50CoherenceRuntime) void {
        self.claims.deinit();
        self.state.deinit();
        self.graph.deinit();
        self.memory.deinit();
        self.anchors.deinit();
        self.commitments.deinit();
    }

    pub fn beginTurn(self: *Wave50CoherenceRuntime, turn: u32) void {
        self.signals.turn = turn;
        self.state.expire(turn);
        self.graph.decay(turn, 24.0);
    }

    pub fn observeHidden(self: *Wave50CoherenceRuntime, hidden: []const f32, token_index: u64) void {
        const sketch = Wave50SemanticSketch.fromHidden(hidden, 0x434f484552454e43);
        self.live_sketch.ema(sketch, 0.18);
        self.horizons.update(sketch, token_index);
        self.topics.observe(sketch, 0.12);
        self.signals.token_index = token_index;
        self.signals.topic_drift = self.topics.drift(sketch);
        self.signals.horizon_drift = self.horizons.drift();
        self.signals.anchor_pressure = self.anchors.regroundPressure(token_index, sketch);
        self.signals.commitment_alignment = self.commitments.alignment(sketch);
        self.signals.unresolved_questions = @intCast(self.graph.unresolvedQuestions());
    }

    pub fn observeDistribution(self: *Wave50CoherenceRuntime, allocator: std.mem.Allocator, logits: []const f32, target_entropy: f32) !Wave50EntropyDebt.Update {
        const entropy = try Wave50Math.entropyFromLogits(allocator, logits);
        const margin = Wave50Math.logitMargin(logits);
        const update = self.entropy_debt.observe(entropy, margin, target_entropy, @max(self.signals.topic_drift, self.signals.horizon_drift), self.signals.contradiction_risk);
        self.signals.entropy = entropy;
        self.signals.entropy_debt = update.debt;
        self.signals.logit_margin = margin;
        return update;
    }

    pub fn effectiveSampling(self: Wave50CoherenceRuntime, base: Wave50AdaptiveSampling.Base) Wave50AdaptiveSampling.Effective {
        return Wave50AdaptiveSampling.derive(base, .{
            .entropy_debt = self.signals.entropy_debt,
            .drift = @max(self.signals.topic_drift, self.signals.horizon_drift),
            .contradiction = self.signals.contradiction_risk,
            .layer_instability = self.signals.layer_instability,
            .anchor_pressure = self.signals.anchor_pressure,
            .plan_pressure = self.signals.plan_pressure,
            .repetition = self.signals.repetition_risk,
            .novelty = self.signals.novelty,
        });
    }

    pub fn checkpointSketch(self: Wave50CoherenceRuntime) Wave50SemanticSketch {
        var out = self.horizons.consensus();
        out.ema(self.live_sketch, 0.45);
        return out;
    }
};

pub const Wave50Vec16 = struct {
    pub const dims: usize = 16;
    values: [dims]f32 = [_]f32{0} ** dims,

    pub fn zero() Wave50Vec16 {
        return .{};
    }

    pub fn fromSlice(src: []const f32) !Wave50Vec16 {
        if (src.len != dims) return error.ShapeMismatch;
        var out = Wave50Vec16{};
        @memcpy(out.values[0..], src);
        return out;
    }

    pub fn add(a: Wave50Vec16, b: Wave50Vec16) Wave50Vec16 {
        var out = Wave50Vec16{};
        for (&out.values, a.values, b.values) |*o, x, y| {
            o.* = x + y;
        }
        return out;
    }

    pub fn sub(a: Wave50Vec16, b: Wave50Vec16) Wave50Vec16 {
        var out = Wave50Vec16{};
        for (&out.values, a.values, b.values) |*o, x, y| {
            o.* = x - y;
        }
        return out;
    }

    pub fn scale(a: Wave50Vec16, s: f32) Wave50Vec16 {
        var out = a;
        for (&out.values) |*x| {
            x.* *= s;
        }
        return out;
    }

    pub fn wave50Dot(a: Wave50Vec16, b: Wave50Vec16) f32 {
        var s: f32 = 0;
        for (a.values, b.values) |x, y| {
            s += x * y;
        }
        return s;
    }

    pub fn norm(a: Wave50Vec16) f32 {
        return @sqrt(@max(wave50Dot(a, a), @as(f32, 0)));
    }

    pub fn cosine(a: Wave50Vec16, b: Wave50Vec16) f32 {
        const na = norm(a);
        const nb = norm(b);
        if (na <= 1e-12 or nb <= 1e-12) return 0;
        return wave50Dot(a, b) / (na * nb);
    }

    pub fn normalized(a: Wave50Vec16) Wave50Vec16 {
        const n = norm(a);
        if (n <= 1e-12) return a;
        return scale(a, 1.0 / n);
    }

    pub fn ema(a: Wave50Vec16, b: Wave50Vec16, alpha: f32) Wave50Vec16 {
        const t = Wave50Math.clamp01(alpha);
        var out = Wave50Vec16{};
        for (&out.values, a.values, b.values) |*o, x, y| {
            o.* = (1.0 - t) * x + t * y;
        }
        return out;
    }

    pub fn distance(a: Wave50Vec16, b: Wave50Vec16) f32 {
        return 1.0 - cosine(a, b);
    }

    pub fn maxAbs(a: Wave50Vec16) f32 {
        var m: f32 = 0;
        for (a.values) |x| {
            m = @max(m, @abs(x));
        }
        return m;
    }

    pub fn finite(a: Wave50Vec16) bool {
        for (a.values) |x| {
            if (!std.math.isFinite(x)) return false;
        }
        return true;
    }

    pub fn checksum(a: Wave50Vec16) u64 {
        var h: u64 = 0x6a09e667f3bcc909;
        for (a.values, 0..) |x, i| {
            const bits: u32 = @bitCast(x);
            h ^= Wave50Math.splitmix64(@as(u64, bits) ^ @as(u64, @intCast(i)));
        }
        return h;
    }
};

pub const Wave50Vec24 = struct {
    pub const dims: usize = 24;
    values: [dims]f32 = [_]f32{0} ** dims,

    pub fn zero() Wave50Vec24 {
        return .{};
    }

    pub fn fromSlice(src: []const f32) !Wave50Vec24 {
        if (src.len != dims) return error.ShapeMismatch;
        var out = Wave50Vec24{};
        @memcpy(out.values[0..], src);
        return out;
    }

    pub fn add(a: Wave50Vec24, b: Wave50Vec24) Wave50Vec24 {
        var out = Wave50Vec24{};
        for (&out.values, a.values, b.values) |*o, x, y| {
            o.* = x + y;
        }
        return out;
    }

    pub fn sub(a: Wave50Vec24, b: Wave50Vec24) Wave50Vec24 {
        var out = Wave50Vec24{};
        for (&out.values, a.values, b.values) |*o, x, y| {
            o.* = x - y;
        }
        return out;
    }

    pub fn scale(a: Wave50Vec24, s: f32) Wave50Vec24 {
        var out = a;
        for (&out.values) |*x| {
            x.* *= s;
        }
        return out;
    }

    pub fn wave50Dot(a: Wave50Vec24, b: Wave50Vec24) f32 {
        var s: f32 = 0;
        for (a.values, b.values) |x, y| {
