        for (a.values, 0..) |x, i| {
            const bits: u32 = @bitCast(x);
            h ^= Wave50Math.splitmix64(@as(u64, bits) ^ @as(u64, @intCast(i)));
        }
        return h;
    }
};

pub const Wave50Vec192 = struct {
    pub const dims: usize = 192;
    values: [dims]f32 = [_]f32{0} ** dims,

    pub fn zero() Wave50Vec192 {
        return .{};
    }

    pub fn fromSlice(src: []const f32) !Wave50Vec192 {
        if (src.len != dims) return error.ShapeMismatch;
        var out = Wave50Vec192{};
        @memcpy(out.values[0..], src);
        return out;
    }

    pub fn add(a: Wave50Vec192, b: Wave50Vec192) Wave50Vec192 {
        var out = Wave50Vec192{};
        for (&out.values, a.values, b.values) |*o, x, y| {
            o.* = x + y;
        }
        return out;
    }

    pub fn sub(a: Wave50Vec192, b: Wave50Vec192) Wave50Vec192 {
        var out = Wave50Vec192{};
        for (&out.values, a.values, b.values) |*o, x, y| {
            o.* = x - y;
        }
        return out;
    }

    pub fn scale(a: Wave50Vec192, s: f32) Wave50Vec192 {
        var out = a;
        for (&out.values) |*x| {
            x.* *= s;
        }
        return out;
    }

    pub fn wave50Dot(a: Wave50Vec192, b: Wave50Vec192) f32 {
        var s: f32 = 0;
        for (a.values, b.values) |x, y| {
            s += x * y;
        }
        return s;
    }

    pub fn norm(a: Wave50Vec192) f32 {
        return @sqrt(@max(wave50Dot(a, a), @as(f32, 0)));
    }

    pub fn cosine(a: Wave50Vec192, b: Wave50Vec192) f32 {
        const na = norm(a);
        const nb = norm(b);
        if (na <= 1e-12 or nb <= 1e-12) return 0;
        return wave50Dot(a, b) / (na * nb);
    }

    pub fn normalized(a: Wave50Vec192) Wave50Vec192 {
        const n = norm(a);
        if (n <= 1e-12) return a;
        return scale(a, 1.0 / n);
    }

    pub fn ema(a: Wave50Vec192, b: Wave50Vec192, alpha: f32) Wave50Vec192 {
        const t = Wave50Math.clamp01(alpha);
        var out = Wave50Vec192{};
        for (&out.values, a.values, b.values) |*o, x, y| {
            o.* = (1.0 - t) * x + t * y;
        }
        return out;
    }

    pub fn distance(a: Wave50Vec192, b: Wave50Vec192) f32 {
        return 1.0 - cosine(a, b);
    }

    pub fn maxAbs(a: Wave50Vec192) f32 {
        var m: f32 = 0;
        for (a.values) |x| {
            m = @max(m, @abs(x));
        }
        return m;
    }

    pub fn finite(a: Wave50Vec192) bool {
        for (a.values) |x| {
            if (!std.math.isFinite(x)) return false;
        }
        return true;
    }

    pub fn checksum(a: Wave50Vec192) u64 {
        var h: u64 = 0x6a09e667f3bcc909;
        for (a.values, 0..) |x, i| {
            const bits: u32 = @bitCast(x);
            h ^= Wave50Math.splitmix64(@as(u64, bits) ^ @as(u64, @intCast(i)));
        }
        return h;
    }
};

