};

pub const Wave50TokenWindow2048 = struct {
    pub const capacity: usize = 2048;
    tokens: [capacity]u32 = [_]u32{0} ** capacity,
    len: usize = 0,
    cursor: usize = 0,
    total: u64 = 0,

    pub fn push(self: *Wave50TokenWindow2048, token: u32) void {
        self.tokens[self.cursor] = token;
        self.cursor = (self.cursor + 1) % capacity;
        if (self.len < capacity) self.len += 1;
        self.total +%= 1;
    }

    pub fn clear(self: *Wave50TokenWindow2048) void {
        self.len = 0;
        self.cursor = 0;
        self.total = 0;
    }

    pub fn newest(self: Wave50TokenWindow2048, offset: usize) ?u32 {
        if (offset >= self.len) return null;
        const pos = (self.cursor + capacity - 1 - offset) % capacity;
        return self.tokens[pos];
    }

    pub fn count(self: Wave50TokenWindow2048, token: u32) usize {
        var n: usize = 0;
        var i: usize = 0;
        while (i < self.len) : (i += 1) {
            if (self.newest(i).? == token) n += 1;
        }
        return n;
    }

    pub fn contains(self: Wave50TokenWindow2048, token: u32) bool {
        return self.count(token) != 0;
    }

    pub fn suffixMatches(self: Wave50TokenWindow2048, seq: []const u32) bool {
        if (seq.len > self.len) return false;
        for (seq, 0..) |_, i| {
            const rev = seq.len - 1 - i;
            if (self.newest(i).? != seq[rev]) return false;
        }
        return true;
    }

    pub fn repetitionScore(self: Wave50TokenWindow2048, token: u32) f32 {
        if (self.len == 0) return 0;
        const c = self.count(token);
        return @as(f32, @floatFromInt(c)) / @as(f32, @floatFromInt(self.len));
    }

    pub fn uniqueEstimate(self: Wave50TokenWindow2048) usize {
        var unique: usize = 0;
        var i: usize = 0;
        while (i < self.len) : (i += 1) {
            const tok = self.newest(i).?;
            var seen = false;
            var j: usize = 0;
            while (j < i) : (j += 1) {
                if (self.newest(j).? == tok) {
                    seen = true;
                    break;
                }
            }
            if (!seen) unique += 1;
        }
        return unique;
    }

    pub fn diversity(self: Wave50TokenWindow2048) f32 {
        if (self.len == 0) return 1;
        return @as(f32, @floatFromInt(self.uniqueEstimate())) / @as(f32, @floatFromInt(self.len));
    }

    pub fn hash(self: Wave50TokenWindow2048) u64 {
        var h: u64 = 0x3c6ef372fe94f82b;
        var i: usize = self.len;
        while (i > 0) {
            i -= 1;
            h ^= Wave50Math.splitmix64(@as(u64, self.newest(i).?) +% @as(u64, @intCast(i)));
        }
        return h;
    }
};

