pub const Wave50LogitProcessor = struct {
    pub const Candidate = struct {
        token: u32,
        logit: f32,
        probability: f32 = 0,
        adjusted: f32 = 0,
    };

    pub fn applyTemperature(logits: []f32, temperature: f32) void {
        const t = @max(temperature, @as(f32, 1e-5));
        for (logits) |*x| x.* /= t;
    }

    pub fn applyRepetition(logits: []f32, recent: []const u32, penalty: f32) void {
        if (penalty <= 1.0) return;
        for (recent) |tok| {
            const i: usize = @intCast(tok);
            if (i >= logits.len) continue;
            if (logits[i] >= 0) logits[i] /= penalty else logits[i] *= penalty;
        }
    }

    pub fn applyPresenceFrequency(logits: []f32, recent: []const u32, presence: f32, frequency: f32) void {
        for (logits, 0..) |*logit, i| {
            var count: usize = 0;
            for (recent) |tok| if (@as(usize, @intCast(tok)) == i) {
                count += 1;
            };
            if (count > 0) {
                logit.* -= presence;
                logit.* -= frequency * @as(f32, @floatFromInt(count));
            }
        }
    }

    pub fn coherenceBias(logits: []f32, token_sketches: []const Wave50SemanticSketch, target: Wave50SemanticSketch, strength: f32) !void {
        if (token_sketches.len != logits.len) return error.ShapeMismatch;
        for (logits, token_sketches) |*l, s| {
            l.* += strength * s.cosine(target);
        }
    }

    pub fn anchorBias(logits: []f32, anchor_tokens: []const u32, boost: f32) void {
        for (anchor_tokens) |tok| {
            const i: usize = @intCast(tok);
            if (i < logits.len) logits[i] += boost;
        }
    }

    pub fn suppress(logits: []f32, tokens: []const u32, amount: f32) void {
        for (tokens) |tok| {
            const i: usize = @intCast(tok);
            if (i < logits.len) logits[i] -= amount;
        }
    }

    pub fn finiteOrNegInf(logits: []f32) void {
        for (logits) |*x| if (!std.math.isFinite(x.*)) {
            x.* = -std.math.inf(f32);
        };
    }

    pub fn topCandidates(allocator: std.mem.Allocator, logits: []const f32, k: usize) ![]Candidate {
        var list = std.ArrayList(Candidate).empty;
        defer list.deinit(allocator);
        for (logits, 0..) |logit, i| {
            try list.append(allocator, .{ .token = @intCast(i), .logit = logit, .adjusted = logit });
        }
        std.mem.sort(Candidate, list.items, {}, struct {
            fn lessThan(_: void, a: Candidate, b: Candidate) bool {
                return a.adjusted > b.adjusted;
            }
        }.lessThan);
        const n = @min(k, list.items.len);
        const out = try allocator.alloc(Candidate, n);
        @memcpy(out, list.items[0..n]);
        if (n != 0) {
            const m = out[0].adjusted;
            var z: f32 = 0;
            for (out) |*c| {
                c.probability = @exp(c.adjusted - m);
                z += c.probability;
            }
            if (z > 0) {
                for (out) |*c| {
                    c.probability /= z;
                }
            }
        }
        return out;
    }
};

pub const Wave50KvImportance = struct {
    pub const TokenScore = struct {
        position: u64,
        recency: f32,
        attention_mass: f32,
        anchor_overlap: f32,
        novelty: f32,
        question_relevance: f32,
        score: f32,
    };

    pub fn score(position: u64, current: u64, attention_mass: f32, anchor_overlap: f32, novelty: f32, question_relevance: f32) TokenScore {
        const age: f32 = @floatFromInt(current -| position);
        const recency = @exp(-age / 1024.0);
        const s = 0.22 * recency +
            0.34 * Wave50Math.clamp01(attention_mass) +
            0.18 * Wave50Math.clamp01(anchor_overlap) +
            0.12 * Wave50Math.clamp01(novelty) +
            0.14 * Wave50Math.clamp01(question_relevance);
        return .{
            .position = position,
            .recency = recency,
            .attention_mass = attention_mass,
            .anchor_overlap = anchor_overlap,
            .novelty = novelty,
            .question_relevance = question_relevance,
            .score = s,
        };
    }

    pub fn chooseKeep(allocator: std.mem.Allocator, scores: []const TokenScore, keep: usize) ![]u64 {
        const tmp = try allocator.dupe(TokenScore, scores);
        defer allocator.free(tmp);
        std.mem.sort(TokenScore, tmp, {}, struct {
            fn lessThan(_: void, a: TokenScore, b: TokenScore) bool {
                if (a.score != b.score) return a.score > b.score;
                return a.position > b.position;
            }
        }.lessThan);
        const n = @min(keep, tmp.len);
        const out = try allocator.alloc(u64, n);
        for (tmp[0..n], 0..) |s, i| out[i] = s.position;
        std.mem.sort(u64, out, {}, std.sort.asc(u64));
        return out;
    }
};

pub const Wave50PromptMemoryCompiler = struct {
    pub const SectionKind = enum { system_rules, current_goal, unresolved_questions, active_claims, world_state, anchor_facts, recent_summary, long_term_memory, plan };
    pub const Section = struct {
        kind: SectionKind,
        priority: f32,
        token_budget: usize,
        estimated_tokens: usize,
        content_hash: u64,
        required: bool,
    };

    pub const Allocation = struct {
        kind: SectionKind,
        granted_tokens: usize,
        included: bool,
    };

    pub fn allocate(allocator: std.mem.Allocator, sections: []const Section, total_budget: usize) ![]Allocation {
        const tmp = try allocator.dupe(Section, sections);
        defer allocator.free(tmp);
        std.mem.sort(Section, tmp, {}, struct {
            fn lessThan(_: void, a: Section, b: Section) bool {
                if (a.required != b.required) return a.required;
                return a.priority > b.priority;
            }
        }.lessThan);
        var remaining = total_budget;
        const out = try allocator.alloc(Allocation, tmp.len);
        for (tmp, 0..) |s, i| {
            const want = @min(s.token_budget, s.estimated_tokens);
            var grant: usize = 0;
            if (s.required) {
                grant = @min(want, remaining);
            } else if (remaining > 0) {
                grant = @min(want, remaining);
            }
            remaining -|= grant;
            out[i] = .{ .kind = s.kind, .granted_tokens = grant, .included = grant != 0 };
        }
        return out;
    }
};

pub const Wave50SpeculativeCoherence = struct {
    pub const DraftToken = struct {
        token: u32,
        draft_logprob: f32,
        semantic: Wave50SemanticSketch,
    };

    pub const Verify = struct {
        accepted: usize,
        rejected_at: ?usize,
        coherence_score: f32,
        contradiction_peak: f32,
    };

    pub fn verify(draft: []const DraftToken, target_logprobs: []const f32, memory: Wave50SemanticSketch, contradiction: []const f32, min_ratio: f32, min_coherence: f32) !Verify {
        if (draft.len != target_logprobs.len or draft.len != contradiction.len) return error.ShapeMismatch;
        var accepted: usize = 0;
        var coh_sum: f32 = 0;
        var peak: f32 = 0;
        var rejected: ?usize = null;
        for (draft, target_logprobs, contradiction, 0..) |d, target_lp, cr, i| {
            const ratio = @exp(@min(@as(f32, 20), target_lp - d.draft_logprob));
            const coh = Wave50Math.clamp01((d.semantic.cosine(memory) + 1.0) * 0.5);
            peak = @max(peak, cr);
            const ok = ratio >= min_ratio and coh >= min_coherence and cr < 0.65;
            if (!ok) {
                rejected = i;
                break;
            }
            accepted += 1;
            coh_sum += coh;
        }
        return .{
            .accepted = accepted,
            .rejected_at = rejected,
            .coherence_score = if (accepted > 0) coh_sum / @as(f32, @floatFromInt(accepted)) else 0,
            .contradiction_peak = peak,
        };
    }
};

pub const Wave50CoherenceTrace = struct {
    pub const EventKind = enum { token, sentence, memory_write, memory_read, claim_add, claim_conflict, anchor_reground, plan_update, sampling_change, verifier_reject, verifier_accept };
    pub const Event = struct {
        kind: EventKind,
        token_index: u64,
        turn: u32,
        value0: f32 = 0,
        value1: f32 = 0,
        hash0: u64 = 0,
        hash1: u64 = 0,
    };

    allocator: std.mem.Allocator,
    events: std.ArrayList(Event) = .empty,
    max_events: usize,

    pub fn init(allocator: std.mem.Allocator, max_events: usize) Wave50CoherenceTrace {
        return .{ .allocator = allocator, .max_events = max_events };
    }
    pub fn deinit(self: *Wave50CoherenceTrace) void {
        self.events.deinit(self.allocator);
    }

    pub fn push(self: *Wave50CoherenceTrace, event: Event) !void {
        if (self.max_events == 0) return;
        if (self.events.items.len == self.max_events) {
            std.mem.copyForwards(Event, self.events.items[0 .. self.max_events - 1], self.events.items[1..self.max_events]);
            self.events.items.len -= 1;
        }
        try self.events.append(self.allocator, event);
    }

    pub fn mean(self: Wave50CoherenceTrace, kind: EventKind, which: u1) f32 {
        var sum: f32 = 0;
        var count: usize = 0;
        for (self.events.items) |e| {
            if (e.kind != kind) continue;
            sum += if (which == 0) e.value0 else e.value1;
            count += 1;
        }
        return if (count > 0) sum / @as(f32, @floatFromInt(count)) else 0;
    }
};

pub const Wave50ModelIntrospection = struct {
    pub const LayerSignal = struct {
        layer: u16,
        hidden_rms: f32,
        hidden_norm: f32,
        residual_delta: f32,
        attn_entropy: f32,
        mlp_gate_mean: f32,
        sketch: Wave50SemanticSketch,
    };

    pub const Trajectory = struct {
        allocator: std.mem.Allocator,
        layers: std.ArrayList(LayerSignal) = .empty,

        pub fn init(allocator: std.mem.Allocator) Trajectory {
            return .{ .allocator = allocator };
        }
        pub fn deinit(self: *Trajectory) void {
            self.layers.deinit(self.allocator);
        }
        pub fn clear(self: *Trajectory) void {
            self.layers.clearRetainingCapacity();
        }
        pub fn add(self: *Trajectory, signal: LayerSignal) !void {
            try self.layers.append(self.allocator, signal);
        }

        pub fn semanticTurn(self: Trajectory) f32 {
            if (self.layers.items.len < 2) return 0;
            var sum: f32 = 0;
            var count: usize = 0;
            var i: usize = 1;
            while (i < self.layers.items.len) : (i += 1) {
                sum += 1.0 - Wave50Math.clamp01((self.layers.items[i - 1].sketch.cosine(self.layers.items[i].sketch) + 1.0) * 0.5);
                count += 1;
            }
            return if (count > 0) sum / @as(f32, @floatFromInt(count)) else 0;
        }

        pub fn residualGrowth(self: Trajectory) f32 {
            if (self.layers.items.len == 0) return 0;
            var s: f32 = 0;
            for (self.layers.items) |x| s += x.residual_delta;
            return s / @as(f32, @floatFromInt(self.layers.items.len));
        }
    };
};

pub const Wave50SessionSnapshot = struct {
    pub const magic = [_]u8{ 'N', 'Z', '5', '0', 'C', 'O', 'H', 'R' };
    pub const version: u32 = 1;

    pub const Header = struct {
        magic_bytes: [8]u8 = magic,
        version_number: u32 = version,
        turn: u32 = 0,
        token_index: u64 = 0,
        claim_count: u32 = 0,
        state_count: u32 = 0,
        anchor_count: u32 = 0,
        memory_slots: u32 = 0,
        live_checksum: u64 = 0,
    };

    pub fn writeHeader(out: []u8, header: Header) !usize {
        if (out.len < 48) return error.EndOfStream;
        var i: usize = 0;
        @memcpy(out[i .. i + 8], header.magic_bytes[0..]);
        i += 8;
        std.mem.writeInt(u32, @ptrCast(out[i..].ptr), header.version_number, .little);
        i += 4;
        std.mem.writeInt(u32, @ptrCast(out[i..].ptr), header.turn, .little);
        i += 4;
        std.mem.writeInt(u64, @ptrCast(out[i..].ptr), header.token_index, .little);
        i += 8;
        std.mem.writeInt(u32, @ptrCast(out[i..].ptr), header.claim_count, .little);
        i += 4;
        std.mem.writeInt(u32, @ptrCast(out[i..].ptr), header.state_count, .little);
        i += 4;
        std.mem.writeInt(u32, @ptrCast(out[i..].ptr), header.anchor_count, .little);
        i += 4;
        std.mem.writeInt(u32, @ptrCast(out[i..].ptr), header.memory_slots, .little);
        i += 4;
        std.mem.writeInt(u64, @ptrCast(out[i..].ptr), header.live_checksum, .little);
        i += 8;
        return i;
    }

    pub fn readHeader(src: []const u8) !Header {
        if (src.len < 48) return error.EndOfStream;
        if (!std.mem.eql(u8, src[0..8], magic[0..])) return error.InvalidSnapshot;
        const ver = std.mem.readInt(u32, src[8..12], .little);
        if (ver != version) return error.InvalidSnapshot;
        return .{
            .version_number = ver,
            .turn = std.mem.readInt(u32, src[12..16], .little),
            .token_index = std.mem.readInt(u64, src[16..24], .little),
            .claim_count = std.mem.readInt(u32, src[24..28], .little),
            .state_count = std.mem.readInt(u32, src[28..32], .little),
            .anchor_count = std.mem.readInt(u32, src[32..36], .little),
            .memory_slots = std.mem.readInt(u32, src[36..40], .little),
            .live_checksum = std.mem.readInt(u64, src[40..48], .little),
        };
    }
};

