    pub const balanced = Wave50AdaptiveSampling.Base{ .temperature = 0.75, .top_p = 0.95, .min_p = 0.05, .repetition_penalty = 1.08, .candidate_width = 10 };
    pub const creative = Wave50AdaptiveSampling.Base{ .temperature = 1.00, .top_p = 0.98, .min_p = 0.02, .repetition_penalty = 1.05, .candidate_width = 8 };
