pub const Wave50HorizonTiny = struct {
    pub const count: usize = 4;
    pub const spans = [_]usize{ 4, 16, 64, 256 };
    states: [count]Wave50SemanticSketch = [_]Wave50SemanticSketch{.{}} ** count,
    updates: [count]u64 = [_]u64{0} ** count,

    pub fn update(self: *@This(), incoming: Wave50SemanticSketch) void {
        var i: usize = 0;
        while (i < count) : (i += 1) {
            const alpha = 2.0 / (@as(f32, @floatFromInt(spans[i])) + 1.0);
            self.states[i].ema(incoming, std.math.clamp(alpha, 0.0001, 0.75));
            self.updates[i] +%= 1;
        }
    }

    pub fn drift(self: @This()) f32 {
        if (count < 2) return 0;
        var s: f32 = 0;
        var i: usize = 1;
        while (i < count) : (i += 1) {
            s += 1.0 - Wave50Math.clamp01((self.states[0].cosine(self.states[i]) + 1.0) * 0.5);
        }
        return s / @as(f32, @floatFromInt(count - 1));
    }
};

