pub const Wave50Audit = struct {
    pub const Report = struct {
        claim_count: usize,
        state_count: usize,
        graph_nodes: usize,
        graph_edges: usize,
        memory_valid: usize,
        anchor_count: usize,
        commitment_count: usize,
        horizon_drift: f32,
        topic_drift: f32,
        entropy_debt: f32,
        total_risk: f32,
        finite: bool,
    };

    pub fn inspect(runtime: Wave50CoherenceRuntime) Report {
        var valid: usize = 0;
        for (runtime.memory.slots) |slot| if (slot.valid) {
            valid += 1;
        };
        const risk = runtime.signals.risk();
        const finite = std.math.isFinite(runtime.signals.entropy_debt) and
            std.math.isFinite(runtime.signals.topic_drift) and
            std.math.isFinite(runtime.signals.horizon_drift) and
            std.math.isFinite(risk);
        return .{
            .claim_count = runtime.claims.claims.items.len,
            .state_count = runtime.state.entries.items.len,
            .graph_nodes = runtime.graph.nodes.items.len,
            .graph_edges = runtime.graph.edges.items.len,
            .memory_valid = valid,
            .anchor_count = runtime.anchors.anchors.items.len,
            .commitment_count = runtime.commitments.items.items.len,
            .horizon_drift = runtime.signals.horizon_drift,
            .topic_drift = runtime.signals.topic_drift,
            .entropy_debt = runtime.signals.entropy_debt,
            .total_risk = risk,
            .finite = finite,
        };
    }
};

test "wave50 semantic sketch cosine identity" {
    const tokens = [_]u32{ 1, 2, 3, 5, 8, 13, 21 };
    const a = Wave50SemanticSketch.fromTokens(tokens[0..], 7);
    const b = Wave50SemanticSketch.fromTokens(tokens[0..], 7);
    try std.testing.expect(a.cosine(b) > 0.999);
}

test "wave50 claim contradiction" {
    const s = Wave50SemanticSketch.fromTokens(&[_]u32{ 7, 8, 9 }, 1);
    const a = Wave50ClaimLedger.Claim{
        .id = 1,
        .subject_hash = 10,
        .predicate_hash = 20,
        .object_hash = 30,
        .polarity = .positive,
        .confidence = 0.9,
        .turn = 1,
        .token_start = 0,
        .token_end = 3,
        .sketch = s,
    };
    var b = a;
    b.id = 2;
    b.polarity = .negative;
    const c = Wave50ClaimLedger.contradiction(a, b) orelse return error.TestUnexpectedResult;
    try std.testing.expect(c.severity > 0.5);
}

test "wave50 associative memory retrieve" {
    var mem = try Wave50AssociativeMemory.init(std.testing.allocator, 4);
    defer mem.deinit();
    const a = Wave50SemanticSketch.fromTokens(&[_]u32{ 1, 2, 3 }, 4);
    const b = Wave50SemanticSketch.fromTokens(&[_]u32{ 9, 9, 9 }, 4);
    _ = mem.write(a, b, 1.0, 0.8, 1, 99);
    const got = try mem.retrieve(std.testing.allocator, a, 2, 1, 0.1);
    defer std.testing.allocator.free(got);
    try std.testing.expectEqual(@as(usize, 1), got.len);
    try std.testing.expectEqual(@as(u64, 99), got[0].tag);
}

test "wave50 entropy debt increases under uncertainty" {
    var d = Wave50EntropyDebt{};
    const uncertainty_low = d.observe(1.0, 2.0, 2.0, 0.0, 0.0);
    const uncertainty_high = d.observe(5.0, 0.1, 2.0, 0.8, 0.7);
    try std.testing.expect(uncertainty_high.debt >= uncertainty_low.debt);
    try std.testing.expect(uncertainty_high.verification_pressure > uncertainty_low.verification_pressure);
}

test "wave50 topic manifold stable input" {
    var t = Wave50TopicManifold{};
    const s = Wave50SemanticSketch.fromTokens(&[_]u32{ 4, 5, 6, 7 }, 12);
    t.observe(s, 0.2);
    t.observe(s, 0.2);
    try std.testing.expect(t.drift(s) < 0.05);
}

test "wave50 session snapshot header roundtrip" {
    var buf: [64]u8 = undefined;
    const h = Wave50SessionSnapshot.Header{ .turn = 7, .token_index = 1234, .claim_count = 2, .live_checksum = 99 };
    const n = try Wave50SessionSnapshot.writeHeader(buf[0..], h);
    try std.testing.expectEqual(@as(usize, 48), n);
    const got = try Wave50SessionSnapshot.readHeader(buf[0..n]);
    try std.testing.expectEqual(h.turn, got.turn);
    try std.testing.expectEqual(h.token_index, got.token_index);
    try std.testing.expectEqual(h.live_checksum, got.live_checksum);
}

// ----------------------------------------------------------------------------
// Wave 50B — discourse continuity, causal/evidence state, context routing
// ----------------------------------------------------------------------------

pub const Wave50EntityCoreference = struct {
    pub const MentionKind = enum { name, pronoun, noun_phrase, title, alias, implicit };
    pub const Mention = struct {
        entity_id: u64,
        token_start: u64,
        token_end: u64,
        turn: u32,
        kind: MentionKind,
        surface_hash: u64,
        grammatical_number: enum { unknown, singular, plural } = .unknown,
        grammatical_person: enum { unknown, first, second, third } = .unknown,
        salience: f32 = 0.5,
        sketch: Wave50SemanticSketch = .{},
    };

    pub const Entity = struct {
        id: u64,
        canonical_hash: u64,
        aliases_hash: u64 = 0,
        first_turn: u32,
        last_turn: u32,
        mention_count: u32 = 0,
        salience: f32 = 0.5,
        sketch: Wave50SemanticSketch = .{},
    };

    pub const Resolution = struct {
        entity_id: ?u64,
        score: f32,
        ambiguous: bool,
        runner_up_score: f32,
    };

    allocator: std.mem.Allocator,
    entities: std.ArrayList(Entity) = .empty,
    mentions: std.ArrayList(Mention) = .empty,
    next_entity_id: u64 = 1,

    pub fn init(allocator: std.mem.Allocator) Wave50EntityCoreference {
        return .{ .allocator = allocator };
    }

    pub fn deinit(self: *Wave50EntityCoreference) void {
        self.entities.deinit(self.allocator);
        self.mentions.deinit(self.allocator);
    }

    pub fn addEntity(self: *Wave50EntityCoreference, canonical_hash: u64, turn: u32, sketch: Wave50SemanticSketch) !u64 {
        for (self.entities.items) |*e| {
            if (e.canonical_hash == canonical_hash) {
                e.last_turn = turn;
                e.salience = Wave50Math.clamp01(e.salience + 0.08);
                e.sketch.ema(sketch, 0.2);
                return e.id;
            }
        }
        const id = self.next_entity_id;
        self.next_entity_id +%= 1;
        try self.entities.append(self.allocator, .{
            .id = id,
            .canonical_hash = canonical_hash,
            .first_turn = turn,
            .last_turn = turn,
            .sketch = sketch,
        });
        return id;
    }

    pub fn addMention(self: *Wave50EntityCoreference, mention: Mention) !void {
        try self.mentions.append(self.allocator, mention);
        for (self.entities.items) |*e| {
            if (e.id == mention.entity_id) {
                e.last_turn = mention.turn;
                e.mention_count +|= 1;
                e.salience = Wave50Math.clamp01(0.92 * e.salience + 0.08 * mention.salience + 0.04);
                e.sketch.ema(mention.sketch, 0.16);
                break;
            }
        }
    }

    fn compatibility(query: Mention, entity: Entity, current_turn: u32) f32 {
        const semantic = Wave50Math.clamp01((query.sketch.cosine(entity.sketch) + 1.0) * 0.5);
        const age: f32 = @floatFromInt(current_turn -| entity.last_turn);
        const recency = @exp(-age / 8.0);
        const alias_bonus: f32 = if (query.surface_hash == entity.canonical_hash) 0.35 else 0;
        return Wave50Math.clamp01(0.50 * semantic + 0.25 * recency + 0.20 * entity.salience + alias_bonus);
    }

    pub fn resolve(self: Wave50EntityCoreference, query: Mention, current_turn: u32, min_score: f32, ambiguity_margin: f32) Resolution {
        var best_id: ?u64 = null;
        var best: f32 = -1;
        var second: f32 = -1;
        for (self.entities.items) |e| {
            const s = compatibility(query, e, current_turn);
            if (s > best) {
                second = best;
                best = s;
                best_id = e.id;
            } else if (s > second) {
                second = s;
            }
        }
        if (best < min_score) return .{ .entity_id = null, .score = @max(best, @as(f32, 0)), .ambiguous = false, .runner_up_score = @max(second, @as(f32, 0)) };
        return .{
            .entity_id = best_id,
            .score = best,
            .ambiguous = second >= 0 and best - second < ambiguity_margin,
            .runner_up_score = @max(second, @as(f32, 0)),
        };
    }

    pub fn decay(self: *Wave50EntityCoreference, current_turn: u32) void {
        for (self.entities.items) |*e| {
            const age: f32 = @floatFromInt(current_turn -| e.last_turn);
            e.salience *= @exp(-age / 64.0);
        }
    }
};

pub const Wave50QuestionAgenda = struct {
    pub const QuestionState = enum { open, partial, answered, deferred, abandoned };
    pub const Question = struct {
        id: u64,
        key_hash: u64,
        created_turn: u32,
        updated_turn: u32,
        priority: f32,
        coverage: f32,
        state: QuestionState = .open,
        sketch: Wave50SemanticSketch = .{},
        answer_sketch: Wave50SemanticSketch = .{},
    };

    allocator: std.mem.Allocator,
    questions: std.ArrayList(Question) = .empty,
    next_id: u64 = 1,

    pub fn init(allocator: std.mem.Allocator) Wave50QuestionAgenda {
        return .{ .allocator = allocator };
    }
    pub fn deinit(self: *Wave50QuestionAgenda) void {
        self.questions.deinit(self.allocator);
    }

    pub fn open(self: *Wave50QuestionAgenda, key_hash: u64, turn: u32, priority: f32, sketch: Wave50SemanticSketch) !u64 {
        const id = self.next_id;
        self.next_id +%= 1;
        try self.questions.append(self.allocator, .{
            .id = id,
            .key_hash = key_hash,
            .created_turn = turn,
            .updated_turn = turn,
            .priority = Wave50Math.clamp01(priority),
            .coverage = 0,
            .sketch = sketch,
        });
        return id;
    }

    pub fn observeAnswer(self: *Wave50QuestionAgenda, answer: Wave50SemanticSketch, turn: u32) void {
        for (self.questions.items) |*q| {
            if (q.state == .answered or q.state == .abandoned) continue;
            const alignment = Wave50Math.clamp01((q.sketch.cosine(answer) + 1.0) * 0.5);
            if (alignment < 0.35) continue;
            q.answer_sketch.ema(answer, 0.35);
            q.coverage = Wave50Math.clamp01(q.coverage + alignment * 0.30);
            q.updated_turn = turn;
            if (q.coverage >= 0.88) q.state = .answered else q.state = .partial;
        }
    }

    pub fn highestPriority(self: Wave50QuestionAgenda) ?Question {
        var best: ?Question = null;
        for (self.questions.items) |q| {
            if (q.state == .answered or q.state == .abandoned) continue;
            const urgency = q.priority * (1.0 - q.coverage);
            if (best == null or urgency > best.?.priority * (1.0 - best.?.coverage)) best = q;
        }
        return best;
    }

    pub fn openWeight(self: Wave50QuestionAgenda) f32 {
        var s: f32 = 0;
        for (self.questions.items) |q| {
            if (q.state == .open or q.state == .partial or q.state == .deferred) s += q.priority * (1.0 - q.coverage);
        }
        return s;
    }
};

pub const Wave50CausalLedger = struct {
    pub const Relation = enum { causes, enables, prevents, increases, decreases, precedes, correlates, explains };
    pub const Edge = struct {
        cause_hash: u64,
        effect_hash: u64,
        relation: Relation,
        confidence: f32,
        turn: u32,
        source_claim: u64,
        sketch: Wave50SemanticSketch = .{},
    };

    allocator: std.mem.Allocator,
    edges: std.ArrayList(Edge) = .empty,

    pub fn init(allocator: std.mem.Allocator) Wave50CausalLedger {
        return .{ .allocator = allocator };
    }
    pub fn deinit(self: *Wave50CausalLedger) void {
        self.edges.deinit(self.allocator);
    }

    pub fn add(self: *Wave50CausalLedger, edge: Edge) !void {
        for (self.edges.items) |*e| {
            if (e.cause_hash == edge.cause_hash and e.effect_hash == edge.effect_hash and e.relation == edge.relation) {
                e.confidence = @max(e.confidence, Wave50Math.clamp01(edge.confidence));
                e.turn = @max(e.turn, edge.turn);
                e.sketch.ema(edge.sketch, 0.25);
                return;
            }
        }
        var x = edge;
        x.confidence = Wave50Math.clamp01(x.confidence);
        try self.edges.append(self.allocator, x);
    }

    pub fn reverseConflict(a: Edge, b: Edge) f32 {
        if (a.cause_hash != b.effect_hash or a.effect_hash != b.cause_hash) return 0;
        if (a.relation == .correlates or b.relation == .correlates) return 0.2 * @sqrt(a.confidence * b.confidence);
        if (a.relation == .precedes and b.relation == .precedes) return @sqrt(a.confidence * b.confidence);
        return 0.65 * @sqrt(a.confidence * b.confidence);
    }

    pub fn cycleRisk(self: Wave50CausalLedger, candidate: Edge) f32 {
        var risk: f32 = 0;
        for (self.edges.items) |e| risk = @max(risk, reverseConflict(e, candidate));
        return Wave50Math.clamp01(risk);
    }

    pub fn outgoing(self: Wave50CausalLedger, allocator: std.mem.Allocator, cause_hash: u64) ![]Edge {
        var out = std.ArrayList(Edge).empty;
        errdefer out.deinit(allocator);
        for (self.edges.items) |e| if (e.cause_hash == cause_hash) {
            try out.append(allocator, e);
        };
        return try out.toOwnedSlice(allocator);
    }
};

pub const Wave50EvidenceLedger = struct {
    pub const EvidenceKind = enum { user_statement, model_inference, retrieved_fact, tool_result, calculation, code_result, assumption };
    pub const Evidence = struct {
        id: u64,
        kind: EvidenceKind,
        content_hash: u64,
        source_hash: u64,
        confidence: f32,
        turn: u32,
        supports_claim: u64 = 0,
        sketch: Wave50SemanticSketch = .{},
    };

    allocator: std.mem.Allocator,
    items: std.ArrayList(Evidence) = .empty,
    next_id: u64 = 1,

    pub fn init(allocator: std.mem.Allocator) Wave50EvidenceLedger {
        return .{ .allocator = allocator };
    }
    pub fn deinit(self: *Wave50EvidenceLedger) void {
        self.items.deinit(self.allocator);
    }

    pub fn add(self: *Wave50EvidenceLedger, e_in: Evidence) !u64 {
        var e = e_in;
        if (e.id == 0) {
            e.id = self.next_id;
            self.next_id +%= 1;
        }
        e.confidence = Wave50Math.clamp01(e.confidence);
        try self.items.append(self.allocator, e);
        return e.id;
    }

    pub fn support(self: Wave50EvidenceLedger, claim_id: u64) f32 {
        var no_fail: f32 = 1.0;
        for (self.items.items) |e| {
            if (e.supports_claim != claim_id) continue;
            no_fail *= 1.0 - 0.75 * e.confidence;
        }
        return Wave50Math.clamp01(1.0 - no_fail);
    }

    pub fn toolBacked(self: Wave50EvidenceLedger, claim_id: u64) bool {
        for (self.items.items) |e| {
            if (e.supports_claim != claim_id) continue;
            if (e.kind == .tool_result or e.kind == .calculation or e.kind == .code_result) return true;
        }
        return false;
    }
};

pub const Wave50PlanGraph = struct {
    pub const StepState = enum { pending, active, complete, blocked, skipped };
    pub const Step = struct {
        id: u32,
        key_hash: u64,
        state: StepState,
        priority: f32,
        completion: f32,
        created_turn: u32,
        updated_turn: u32,
        sketch: Wave50SemanticSketch = .{},
    };
    pub const Dependency = struct { from: u32, to: u32, strength: f32 };

    allocator: std.mem.Allocator,
    steps: std.ArrayList(Step) = .empty,
    deps: std.ArrayList(Dependency) = .empty,
    next_id: u32 = 1,

    pub fn init(allocator: std.mem.Allocator) Wave50PlanGraph {
        return .{ .allocator = allocator };
    }
    pub fn deinit(self: *Wave50PlanGraph) void {
        self.steps.deinit(self.allocator);
        self.deps.deinit(self.allocator);
    }

    pub fn addStep(self: *Wave50PlanGraph, key_hash: u64, priority: f32, turn: u32, sketch: Wave50SemanticSketch) !u32 {
        const id = self.next_id;
        self.next_id +%= 1;
        try self.steps.append(self.allocator, .{ .id = id, .key_hash = key_hash, .state = .pending, .priority = Wave50Math.clamp01(priority), .completion = 0, .created_turn = turn, .updated_turn = turn, .sketch = sketch });
        return id;
    }

    pub fn depend(self: *Wave50PlanGraph, from: u32, to: u32, strength: f32) !void {
        try self.deps.append(self.allocator, .{ .from = from, .to = to, .strength = Wave50Math.clamp01(strength) });
    }

    pub fn ready(self: Wave50PlanGraph, step_id: u32) bool {
        for (self.deps.items) |d| {
            if (d.to != step_id or d.strength < 0.5) continue;
            var found = false;
            for (self.steps.items) |s| {
                if (s.id == d.from) {
                    found = s.state == .complete or s.state == .skipped;
                    break;
                }
            }
            if (!found) return false;
        }
        return true;
    }

    pub fn chooseNext(self: Wave50PlanGraph, live: Wave50SemanticSketch) ?Step {
        var best: ?Step = null;
        var best_score: f32 = -1;
        for (self.steps.items) |s| {
            if (s.state != .pending and s.state != .active) continue;
            if (!self.ready(s.id)) continue;
            const alignment = Wave50Math.clamp01((s.sketch.cosine(live) + 1.0) * 0.5);
            const score = 0.65 * s.priority + 0.25 * alignment + 0.10 * (1.0 - s.completion);
            if (score > best_score) {
                best_score = score;
                best = s;
            }
        }
        return best;
    }

    pub fn update(self: *Wave50PlanGraph, id: u32, completion: f32, turn: u32) bool {
        for (self.steps.items) |*s| {
            if (s.id != id) continue;
            s.completion = Wave50Math.clamp01(completion);
            s.updated_turn = turn;
            s.state = if (s.completion >= 0.999) .complete else .active;
            return true;
        }
        return false;
    }
};

pub const Wave50ContextBudget = struct {
    pub const Bucket = enum { system, user_recent, assistant_recent, claims, state, questions, anchors, retrieved_memory, summaries, generation_headroom };
    pub const Request = struct { bucket: Bucket, minimum: usize, desired: usize, priority: f32, hard: bool = false };
    pub const Grant = struct { bucket: Bucket, tokens: usize, truncated: bool };

    pub fn solve(allocator: std.mem.Allocator, requests: []const Request, capacity: usize) ![]Grant {
        const tmp = try allocator.dupe(Request, requests);
        defer allocator.free(tmp);
        std.mem.sort(Request, tmp, {}, struct {
            fn lessThan(_: void, a: Request, b: Request) bool {
                if (a.hard != b.hard) return a.hard;
                if (a.priority != b.priority) return a.priority > b.priority;
                return a.desired > b.desired;
            }
        }.lessThan);
        const out = try allocator.alloc(Grant, tmp.len);
        var remaining = capacity;
        for (tmp, 0..) |r, i| {
            const floor = @min(r.minimum, remaining);
            remaining -= floor;
            out[i] = .{ .bucket = r.bucket, .tokens = floor, .truncated = floor < r.desired };
        }
        var made_progress = true;
        while (remaining > 0 and made_progress) {
            made_progress = false;
            for (tmp, 0..) |r, i| {
                if (remaining == 0) break;
                if (out[i].tokens >= r.desired) continue;
                out[i].tokens += 1;
                remaining -= 1;
                made_progress = true;
            }
        }
        for (out, tmp) |*g, r| g.truncated = g.tokens < r.desired;
        return out;
    }
};

pub const Wave50SummaryPyramid = struct {
    pub const Node = struct {
        level: u8,
        start_token: u64,
        end_token: u64,
        sketch: Wave50SemanticSketch,
        salience: f32,
        claims_hash: u64,
        child_count: u16,
    };

    allocator: std.mem.Allocator,
    nodes: std.ArrayList(Node) = .empty,
    fanout: usize = 4,

    pub fn init(allocator: std.mem.Allocator, fanout: usize) Wave50SummaryPyramid {
        return .{ .allocator = allocator, .fanout = @max(fanout, 2) };
    }
    pub fn deinit(self: *Wave50SummaryPyramid) void {
        self.nodes.deinit(self.allocator);
    }

    pub fn addLeaf(self: *Wave50SummaryPyramid, start: u64, end: u64, sketch: Wave50SemanticSketch, salience: f32, claims_hash: u64) !void {
        try self.nodes.append(self.allocator, .{ .level = 0, .start_token = start, .end_token = end, .sketch = sketch, .salience = Wave50Math.clamp01(salience), .claims_hash = claims_hash, .child_count = 0 });
        try self.compactLevel(0);
    }

    fn compactLevel(self: *Wave50SummaryPyramid, level: u8) !void {
        var idxs = std.ArrayList(usize).empty;
        defer idxs.deinit(self.allocator);
        for (self.nodes.items, 0..) |n, i| if (n.level == level) {
            try idxs.append(self.allocator, i);
        };
        if (idxs.items.len < self.fanout) return;
        const start_idx = idxs.items[idxs.items.len - self.fanout];
        const end_idx = idxs.items[idxs.items.len - 1];
        var merged = Wave50SemanticSketch{};
        var salience: f32 = 0;
        var claims_hash: u64 = 0;
        var count: usize = 0;
        var start_token: u64 = std.math.maxInt(u64);
        var end_token: u64 = 0;
        var i = start_idx;
        while (i <= end_idx) : (i += 1) {
            const n = self.nodes.items[i];
            if (n.level != level) continue;
            const w = 0.25 + 0.75 * n.salience;
            merged.addScaled(n.sketch, w);
            salience += n.salience;
            claims_hash ^= Wave50Math.splitmix64(n.claims_hash +% @as(u64, @intCast(count)));
            start_token = @min(start_token, n.start_token);
            end_token = @max(end_token, n.end_token);
            count += 1;
        }
        if (count < self.fanout) return;
        Wave50Math.normalizeInPlace(merged.values[0..]);
        try self.nodes.append(self.allocator, .{
            .level = level + 1,
            .start_token = start_token,
            .end_token = end_token,
            .sketch = merged,
            .salience = Wave50Math.clamp01(salience / @as(f32, @floatFromInt(count))),
            .claims_hash = claims_hash,
            .child_count = @intCast(count),
        });
        if (level < 30) try self.compactLevel(level + 1);
    }

    pub fn retrieve(self: Wave50SummaryPyramid, allocator: std.mem.Allocator, query: Wave50SemanticSketch, limit: usize) ![]Node {
        const tmp = try allocator.dupe(Node, self.nodes.items);
        defer allocator.free(tmp);
        std.mem.sort(Node, tmp, query, struct {
            fn lessThan(q: Wave50SemanticSketch, a: Node, b: Node) bool {
                const sa = 0.7 * Wave50Math.clamp01((q.cosine(a.sketch) + 1.0) * 0.5) + 0.3 * a.salience;
                const sb = 0.7 * Wave50Math.clamp01((q.cosine(b.sketch) + 1.0) * 0.5) + 0.3 * b.salience;
                return sa > sb;
            }
        }.lessThan);
        const n = @min(limit, tmp.len);
        const out = try allocator.alloc(Node, n);
        @memcpy(out, tmp[0..n]);
        return out;
    }
};

pub const Wave50AttentionRouter = struct {
    pub const Route = enum { local, recent, anchor, question, plan, long_term, summary, mixed };
    pub const Scores = struct {
        local: f32 = 0,
        recent: f32 = 0,
        anchor: f32 = 0,
        question: f32 = 0,
        plan: f32 = 0,
        long_term: f32 = 0,
        summary: f32 = 0,
    };

    pub const Decision = struct {
        primary: Route,
        secondary: Route,
        primary_weight: f32,
        secondary_weight: f32,
        mix: [7]f32,
    };

    pub fn decide(s: Scores) Decision {
        var values = [_]f32{ s.local, s.recent, s.anchor, s.question, s.plan, s.long_term, s.summary };
        for (&values) |*x| x.* = @max(x.*, @as(f32, 0));
        var first: usize = 0;
        var second: usize = 1;
        if (values[second] > values[first]) {
            const t = first;
            first = second;
            second = t;
        }
        var i: usize = 2;
        while (i < values.len) : (i += 1) {
            if (values[i] > values[first]) {
                second = first;
                first = i;
            } else if (values[i] > values[second]) {
                second = i;
            }
        }
        var z: f32 = 0;
        for (values) |x| z += @exp(x);
        var mix: [7]f32 = undefined;
        for (values, 0..) |x, j| mix[j] = if (z > 0) @exp(x) / z else 1.0 / 7.0;
        const routes = [_]Route{ .local, .recent, .anchor, .question, .plan, .long_term, .summary };
        return .{
            .primary = routes[first],
            .secondary = routes[second],
            .primary_weight = mix[first],
            .secondary_weight = mix[second],
            .mix = mix,
        };
    }
};

pub const Wave50NgramBlocker = struct {
    allocator: std.mem.Allocator,
    order: usize,
    history: std.ArrayList(u32) = .empty,

    pub fn init(allocator: std.mem.Allocator, order: usize) Wave50NgramBlocker {
        return .{ .allocator = allocator, .order = @max(order, 2) };
    }
    pub fn deinit(self: *Wave50NgramBlocker) void {
        self.history.deinit(self.allocator);
    }
    pub fn push(self: *Wave50NgramBlocker, token: u32) !void {
        try self.history.append(self.allocator, token);
    }

    pub fn wouldRepeat(self: Wave50NgramBlocker, token: u32) bool {
        if (self.history.items.len + 1 < self.order) return false;
        const prefix_len = self.order - 1;
        const start = self.history.items.len - prefix_len;
        const prefix = self.history.items[start..];
        var i: usize = 0;
        while (i + self.order <= self.history.items.len) : (i += 1) {
            if (!std.mem.eql(u32, self.history.items[i .. i + prefix_len], prefix)) continue;
            if (self.history.items[i + prefix_len] == token) return true;
        }
        return false;
    }

    pub fn apply(self: Wave50NgramBlocker, logits: []f32, penalty: f32) void {
        for (logits, 0..) |*l, i| {
            if (self.wouldRepeat(@intCast(i))) l.* -= penalty;
        }
    }
};

pub const Wave50LoopDetector = struct {
    pub const Result = struct { period: usize = 0, repeats: usize = 0, confidence: f32 = 0 };

    pub fn detect(tokens: []const u32, max_period: usize, min_repeats: usize) Result {
        if (tokens.len < 2) return .{};
        var best = Result{};
        var period: usize = 1;
        while (period <= @min(max_period, tokens.len / 2)) : (period += 1) {
            var repeats: usize = 1;
            var cursor = tokens.len - period;
            while (cursor >= period) {
                if (!std.mem.eql(u32, tokens[cursor - period .. cursor], tokens[cursor .. cursor + period])) break;
                repeats += 1;
                cursor -= period;
                if (cursor < period) break;
            }
            if (repeats >= min_repeats) {
                const coverage = @as(f32, @floatFromInt(repeats * period)) / @as(f32, @floatFromInt(tokens.len));
                const confidence = Wave50Math.clamp01(0.4 + 0.15 * @as(f32, @floatFromInt(repeats - min_repeats)) + 0.45 * coverage);
                if (confidence > best.confidence) best = .{ .period = period, .repeats = repeats, .confidence = confidence };
            }
        }
        return best;
    }
};

pub const Wave50CoherenceLattice = struct {
    pub const Scale = enum { token, clause, sentence, paragraph, turn, session, long_term };
    pub const Cell = struct {
        scale: Scale,
        sketch: Wave50SemanticSketch = .{},
        confidence: f32 = 0,
        novelty: f32 = 0,
        drift: f32 = 0,
        updates: u64 = 0,
        last_token: u64 = 0,
    };

    cells: [7]Cell = .{
        .{ .scale = .token },
        .{ .scale = .clause },
        .{ .scale = .sentence },
        .{ .scale = .paragraph },
        .{ .scale = .turn },
        .{ .scale = .session },
        .{ .scale = .long_term },
    },

    fn alphaFor(scale: Scale) f32 {
        return switch (scale) {
            .token => 0.45,
            .clause => 0.28,
            .sentence => 0.18,
            .paragraph => 0.09,
            .turn => 0.045,
            .session => 0.012,
            .long_term => 0.003,
        };
    }

    pub fn observe(self: *Wave50CoherenceLattice, incoming: Wave50SemanticSketch, token_index: u64, boundary: ?Scale) void {
        for (&self.cells) |*cell| {
            var alpha = alphaFor(cell.scale);
            if (boundary) |b| {
                if (@intFromEnum(cell.scale) >= @intFromEnum(b)) alpha *= 1.8;
            }
            const previous = cell.sketch;
            cell.sketch.ema(incoming, @min(alpha, @as(f32, 0.8)));
            cell.drift = 1.0 - Wave50Math.clamp01((previous.cosine(cell.sketch) + 1.0) * 0.5);
            cell.novelty = 1.0 - Wave50Math.clamp01((incoming.cosine(previous) + 1.0) * 0.5);
            cell.confidence = Wave50Math.clamp01(0.95 * cell.confidence + 0.05 * (1.0 - cell.drift));
            cell.updates +%= 1;
            cell.last_token = token_index;
        }
    }

    pub fn crossScaleTension(self: Wave50CoherenceLattice) f32 {
        var sum: f32 = 0;
        var weight: f32 = 0;
        var i: usize = 1;
        while (i < self.cells.len) : (i += 1) {
            const c = Wave50Math.clamp01((self.cells[i - 1].sketch.cosine(self.cells[i].sketch) + 1.0) * 0.5);
            const w = 1.0 / @as(f32, @floatFromInt(i));
            sum += w * (1.0 - c);
            weight += w;
        }
        return if (weight > 0) Wave50Math.clamp01(sum / weight) else 0;
    }

    pub fn regroundTarget(self: Wave50CoherenceLattice) Wave50SemanticSketch {
        var out = Wave50SemanticSketch{};
        const weights = [_]f32{ 0.05, 0.07, 0.12, 0.16, 0.20, 0.20, 0.20 };
        for (self.cells, weights) |c, w| out.addScaled(c.sketch, w);
        Wave50Math.normalizeInPlace(out.values[0..]);
        return out;
    }
};

pub const Wave50LongContextController = struct {
    lattice: Wave50CoherenceLattice = .{},
    questions: Wave50QuestionAgenda,
    entities: Wave50EntityCoreference,
    causal: Wave50CausalLedger,
    evidence: Wave50EvidenceLedger,
    plan: Wave50PlanGraph,
    summaries: Wave50SummaryPyramid,

    pub fn init(allocator: std.mem.Allocator) Wave50LongContextController {
        return .{
            .questions = Wave50QuestionAgenda.init(allocator),
            .entities = Wave50EntityCoreference.init(allocator),
            .causal = Wave50CausalLedger.init(allocator),
            .evidence = Wave50EvidenceLedger.init(allocator),
            .plan = Wave50PlanGraph.init(allocator),
            .summaries = Wave50SummaryPyramid.init(allocator, 4),
        };
    }

    pub fn deinit(self: *Wave50LongContextController) void {
        self.questions.deinit();
        self.entities.deinit();
        self.causal.deinit();
        self.evidence.deinit();
        self.plan.deinit();
        self.summaries.deinit();
    }

    pub fn observe(self: *Wave50LongContextController, sketch: Wave50SemanticSketch, token_index: u64, boundary: ?Wave50CoherenceLattice.Scale, turn: u32) void {
        self.lattice.observe(sketch, token_index, boundary);
        self.questions.observeAnswer(sketch, turn);
        self.entities.decay(turn);
    }

    pub fn routingScores(self: Wave50LongContextController, base: Wave50CoherenceSignals) Wave50AttentionRouter.Scores {
        const tension = self.lattice.crossScaleTension();
        const q = Wave50Math.clamp01(self.questions.openWeight());
        const plan_step = self.plan.chooseNext(self.lattice.cells[0].sketch);
        return .{
            .local = 0.8 * (1.0 - base.topic_drift),
            .recent = 0.7 * (1.0 - base.horizon_drift),
            .anchor = 0.3 + 1.2 * base.anchor_pressure,
            .question = 0.2 + q,
            .plan = if (plan_step != null) 0.8 else 0.1,
            .long_term = 0.3 + 0.8 * tension,
            .summary = 0.2 + 0.7 * @max(base.horizon_drift, tension),
        };
    }
};

pub const Wave50GenerationCoordinator = struct {
    pub const Decision = struct {
        sampling: Wave50AdaptiveSampling.Effective,
        route: Wave50AttentionRouter.Decision,
        lattice_tension: f32,
        loop_risk: f32,
        should_verify: bool,
        should_reground: bool,
        should_compress_context: bool,
    };

    pub fn decide(runtime: Wave50CoherenceRuntime, long: Wave50LongContextController, base: Wave50AdaptiveSampling.Base, recent_tokens: []const u32) Decision {
        const sampling = runtime.effectiveSampling(base);
        const route = Wave50AttentionRouter.decide(long.routingScores(runtime.signals));
        const tension = long.lattice.crossScaleTension();
        const loop = Wave50LoopDetector.detect(recent_tokens, 64, 3).confidence;
        const risk = @max(runtime.signals.risk(), @max(tension, loop));
        return .{
            .sampling = sampling,
            .route = route,
            .lattice_tension = tension,
            .loop_risk = loop,
            .should_verify = risk > 0.42 or sampling.verification_strength > 0.5,
            .should_reground = sampling.force_reground or tension > 0.62,
            .should_compress_context = runtime.signals.horizon_drift > 0.65 and runtime.signals.token_index > 4096,
        };
    }
};

pub const Wave50ContextRing128 = struct {
    pub const capacity: usize = 128;
    token_ids: [capacity]u32 = [_]u32{0} ** capacity,
    positions: [capacity]u64 = [_]u64{0} ** capacity,
    importance: [capacity]f32 = [_]f32{0} ** capacity,
    cursor: usize = 0,
    len: usize = 0,

    pub fn push(self: *@This(), token: u32, position: u64, score: f32) void {
        self.token_ids[self.cursor] = token;
        self.positions[self.cursor] = position;
        self.importance[self.cursor] = Wave50Math.clamp01(score);
        self.cursor = (self.cursor + 1) % capacity;
        if (self.len < capacity) self.len += 1;
    }

    pub fn newestIndex(self: @This(), offset: usize) ?usize {
        if (offset >= self.len) return null;
        return (self.cursor + capacity - 1 - offset) % capacity;
    }

    pub fn newestToken(self: @This(), offset: usize) ?u32 {
        const i = self.newestIndex(offset) orelse return null;
        return self.token_ids[i];
    }

    pub fn meanImportance(self: @This()) f32 {
        if (self.len == 0) return 0;
        var s: f32 = 0;
        var i: usize = 0;
        while (i < self.len) : (i += 1) {
            const idx = self.newestIndex(i).?;
            s += self.importance[idx];
        }
        return s / @as(f32, @floatFromInt(self.len));
    }

    pub fn countToken(self: @This(), token: u32) usize {
        var n: usize = 0;
        var i: usize = 0;
        while (i < self.len) : (i += 1) {
            const idx = self.newestIndex(i).?;
            if (self.token_ids[idx] == token) n += 1;
        }
        return n;
    }

    pub fn oldestPosition(self: @This()) ?u64 {
        if (self.len == 0) return null;
        const idx = self.newestIndex(self.len - 1).?;
        return self.positions[idx];
    }

    pub fn newestPosition(self: @This()) ?u64 {
        if (self.len == 0) return null;
        const idx = self.newestIndex(0).?;
        return self.positions[idx];
    }

    pub fn span(self: @This()) u64 {
        const a = self.oldestPosition() orelse return 0;
        const b = self.newestPosition() orelse return 0;
        return b -| a;
    }
};

