pub const Wave50CandidatePool2 = struct {
    pub const capacity: usize = 2;
    pub const Item = struct {
        token: u32 = 0,
        model_score: f32 = -std.math.inf(f32),
        coherence_score: f32 = 0,
        contradiction: f32 = 0,
        final_score: f32 = -std.math.inf(f32),
        valid: bool = false,
    };
    items: [capacity]Item = [_]Item{.{}} ** capacity,
    len: usize = 0,

    pub fn clear(self: *@This()) void {
        self.len = 0;
        @memset(self.items[0..], Item{});
    }

    pub fn add(self: *@This(), token: u32, model_score: f32, coherence_score: f32, contradiction: f32) void {
        const final_score = model_score + 0.65 * coherence_score - 1.25 * contradiction;
        const item = Item{ .token = token, .model_score = model_score, .coherence_score = coherence_score, .contradiction = contradiction, .final_score = final_score, .valid = true };
        if (self.len < capacity) {
            self.items[self.len] = item;
            self.len += 1;
            return;
        }
        var worst: usize = 0;
        var i: usize = 1;
        while (i < self.len) : (i += 1) if (self.items[i].final_score < self.items[worst].final_score) {
            worst = i;
        };
        if (final_score > self.items[worst].final_score) self.items[worst] = item;
    }

    pub fn best(self: @This()) ?Item {
        if (self.len == 0) return null;
        var idx: usize = 0;
        var i: usize = 1;
        while (i < self.len) : (i += 1) if (self.items[i].final_score > self.items[idx].final_score) {
            idx = i;
        };
        return self.items[idx];
    }

    pub fn meanContradiction(self: @This()) f32 {
        if (self.len == 0) return 0;
        var s: f32 = 0;
        var i: usize = 0;
        while (i < self.len) : (i += 1) s += self.items[i].contradiction;
        return s / @as(f32, @floatFromInt(self.len));
    }
};

