test "wave50 coreference exact entity wins" {
    var c = Wave50EntityCoreference.init(std.testing.allocator);
    defer c.deinit();
    const s = Wave50SemanticSketch.fromTokens(&[_]u32{ 10, 20 }, 3);
    const id = try c.addEntity(123, 1, s);
    const q = Wave50EntityCoreference.Mention{
        .entity_id = 0,
        .token_start = 0,
        .token_end = 1,
        .turn = 2,
        .kind = .name,
        .surface_hash = 123,
        .sketch = s,
    };
    const r = c.resolve(q, 2, 0.2, 0.05);
    try std.testing.expectEqual(id, r.entity_id.?);
}

test "wave50 context budget honors capacity" {
    const reqs = [_]Wave50ContextBudget.Request{
        .{ .bucket = .system, .minimum = 100, .desired = 200, .priority = 1.0, .hard = true },
        .{ .bucket = .claims, .minimum = 50, .desired = 300, .priority = 0.8 },
        .{ .bucket = .summaries, .minimum = 0, .desired = 500, .priority = 0.4 },
    };
    const grants = try Wave50ContextBudget.solve(std.testing.allocator, &reqs, 600);
    defer std.testing.allocator.free(grants);
    var total: usize = 0;
    for (grants) |g| total += g.tokens;
    try std.testing.expect(total <= 600);
}

test "wave50 ngram blocker detects repeated continuation" {
    var b = Wave50NgramBlocker.init(std.testing.allocator, 3);
    defer b.deinit();
    try b.push(1);
    try b.push(2);
    try b.push(3);
    try b.push(1);
    try b.push(2);
    try std.testing.expect(b.wouldRepeat(3));
}

test "wave50 coherence lattice stable input has low tension" {
    var l = Wave50CoherenceLattice{};
    const s = Wave50SemanticSketch.fromTokens(&[_]u32{ 1, 4, 9, 16 }, 5);
    var i: usize = 0;
    while (i < 100) : (i += 1) l.observe(s, i, null);
    try std.testing.expect(l.crossScaleTension() < 0.15);
}

// ----------------------------------------------------------------------------
// Wave 50C — layer observability and boundary-aware coherence control
// ----------------------------------------------------------------------------

pub const Wave50BoundaryDetector = struct {
    pub const Boundary = enum { none, clause, sentence, paragraph, turn };

    pub fn classifyBytes(bytes: []const u8) Boundary {
        if (bytes.len == 0) return .none;
        if (std.mem.indexOf(u8, bytes, "\n\n") != null) return .paragraph;
        var sentence = false;
        var clause = false;
        for (bytes) |b| {
            switch (b) {
                '.', '!', '?' => sentence = true,
                ',', ';', ':' => clause = true,
                else => {},
            }
        }
        if (sentence) return .sentence;
        if (clause) return .clause;
        return .none;
    }

    pub fn toLattice(b: Boundary) ?Wave50CoherenceLattice.Scale {
        return switch (b) {
            .none => null,
            .clause => .clause,
            .sentence => .sentence,
            .paragraph => .paragraph,
            .turn => .turn,
        };
    }
};

pub const Wave50SemanticConsensus = struct {
    pub const Vote = struct {
        sketch: Wave50SemanticSketch,
        weight: f32,
        source_id: u32,
    };

    pub const Result = struct {
        consensus: Wave50SemanticSketch,
        agreement: f32,
        disagreement_peak: f32,
        effective_sources: f32,
    };

    pub fn compute(votes: []const Vote) Result {
        var out = Wave50SemanticSketch{};
        var total: f32 = 0;
        for (votes) |v| {
            const w = @max(v.weight, @as(f32, 0));
            out.addScaled(v.sketch, w);
            total += w;
        }
        if (total > 0) {
            for (&out.values) |*x| x.* /= total;
            Wave50Math.normalizeInPlace(out.values[0..]);
        }
        var agree: f32 = 0;
        var peak: f32 = 0;
        var sq: f32 = 0;
        for (votes) |v| {
            const w = @max(v.weight, @as(f32, 0));
            const a = Wave50Math.clamp01((v.sketch.cosine(out) + 1.0) * 0.5);
            agree += w * a;
            peak = @max(peak, 1.0 - a);
            sq += w * w;
        }
        return .{
            .consensus = out,
            .agreement = if (total > 0) agree / total else 1.0,
            .disagreement_peak = peak,
            .effective_sources = if (sq > 0) (total * total) / sq else 0,
        };
    }
};

pub const Wave50LayerTrajectory = struct {
    pub const Point = struct {
        layer: u16,
        rms: f32,
        residual_delta: f32,
        entropy_proxy: f32,
        sketch: Wave50SemanticSketch,
    };

    allocator: std.mem.Allocator,
    points: std.ArrayList(Point) = .empty,

    pub fn init(allocator: std.mem.Allocator) Wave50LayerTrajectory {
        return .{ .allocator = allocator };
    }
    pub fn deinit(self: *Wave50LayerTrajectory) void {
        self.points.deinit(self.allocator);
    }
    pub fn clear(self: *Wave50LayerTrajectory) void {
        self.points.clearRetainingCapacity();
    }
    pub fn push(self: *Wave50LayerTrajectory, p: Point) !void {
        try self.points.append(self.allocator, p);
    }

    pub fn monotonicDrift(self: Wave50LayerTrajectory) f32 {
        if (self.points.items.len < 2) return 0;
        var increases: usize = 0;
        var total: usize = 0;
        var last: f32 = 0;
        var i: usize = 1;
        while (i < self.points.items.len) : (i += 1) {
            const d = 1.0 - Wave50Math.clamp01((self.points.items[i - 1].sketch.cosine(self.points.items[i].sketch) + 1.0) * 0.5);
            if (i > 1 and d > last) increases += 1;
            last = d;
            total += 1;
        }
        return if (total > 0) @as(f32, @floatFromInt(increases)) / @as(f32, @floatFromInt(total)) else 0;
    }

    pub fn lateTurn(self: Wave50LayerTrajectory) f32 {
        if (self.points.items.len < 4) return 0;
        const n = self.points.items.len;
        const a = self.points.items[n - 4].sketch;
        const b = self.points.items[n - 1].sketch;
        return 1.0 - Wave50Math.clamp01((a.cosine(b) + 1.0) * 0.5);
    }

    pub fn unstable(self: Wave50LayerTrajectory, threshold: f32) bool {
        return self.lateTurn() > threshold or self.monotonicDrift() > 0.75;
    }
};

pub const Wave50VerifierPolicy = struct {
    pub const Action = enum { accept, contrast_layers, widen_candidates, reground_memory, rescore_claims, lower_temperature, force_plan_step };
    pub const Input = struct {
        layer_instability: f32,
        contradiction: f32,
        anchor_pressure: f32,
        entropy_debt: f32,
        loop_risk: f32,
        plan_pressure: f32,
        commitment_alignment: f32,
    };

    pub fn choose(input: Input) Action {
        if (input.contradiction > 0.68) return .rescore_claims;
        if (input.anchor_pressure > 0.70) return .reground_memory;
        if (input.loop_risk > 0.72) return .lower_temperature;
        if (input.layer_instability > 0.62) return .contrast_layers;
        if (input.entropy_debt > 2.5) return .widen_candidates;
        if (input.plan_pressure > 0.70 or input.commitment_alignment < 0.35) return .force_plan_step;
        return .accept;
    }
};

pub const Wave50Tap00 = struct {
    pub const layer: u16 = 0;
    pub const seed: u64 = 0xed09ed5feac1bd33;
    pub const expected_depth: f32 = 0.00000000;
    pub const local_gain: f32 = 1.15000000;
    pub const global_gain: f32 = 0.25000000;
    pub const contradiction_gain: f32 = 0.10000000;

    pub const Observation = struct {
        rms: f32,
        norm: f32,
        max_abs: f32,
        sketch: Wave50SemanticSketch,
        finite: bool,
    };

    pub fn observe(hidden: []const f32) Observation {
        var max_abs: f32 = 0;
        var finite = true;
        for (hidden) |x| {
            max_abs = @max(max_abs, @abs(x));
            if (!std.math.isFinite(x)) finite = false;
        }
        return .{
            .rms = Wave50Math.rms(hidden),
            .norm = Wave50Math.norm2(hidden),
            .max_abs = max_abs,
            .sketch = Wave50SemanticSketch.fromHidden(hidden, seed),
            .finite = finite,
        };
    }

    pub fn semanticAgreement(obs: Observation, target: Wave50SemanticSketch) f32 {
        return Wave50Math.clamp01((obs.sketch.cosine(target) + 1.0) * 0.5);
    }

    pub fn score(obs: Observation, target: Wave50SemanticSketch, contradiction: f32, novelty: f32) f32 {
        if (!obs.finite) return -std.math.inf(f32);
        const agreement = semanticAgreement(obs, target);
        const stability = 1.0 / (1.0 + obs.max_abs * 0.01);
        return local_gain * stability + global_gain * agreement + 0.15 * novelty - contradiction_gain * contradiction;
    }
};

