        rms: f32,
        norm: f32,
        max_abs: f32,
        sketch: Wave50SemanticSketch,
        finite: bool,
    };

    pub fn observe(hidden: []const f32) Observation {
        var max_abs: f32 = 0;
        var finite = true;
        for (hidden) |x| {
            max_abs = @max(max_abs, @abs(x));
            if (!std.math.isFinite(x)) finite = false;
        }
        return .{
            .rms = Wave50Math.rms(hidden),
            .norm = Wave50Math.norm2(hidden),
            .max_abs = max_abs,
            .sketch = Wave50SemanticSketch.fromHidden(hidden, seed),
            .finite = finite,
        };
    }

    pub fn semanticAgreement(obs: Observation, target: Wave50SemanticSketch) f32 {
        return Wave50Math.clamp01((obs.sketch.cosine(target) + 1.0) * 0.5);
    }

    pub fn score(obs: Observation, target: Wave50SemanticSketch, contradiction: f32, novelty: f32) f32 {
        if (!obs.finite) return -std.math.inf(f32);
        const agreement = semanticAgreement(obs, target);
        const stability = 1.0 / (1.0 + obs.max_abs * 0.01);
        return local_gain * stability + global_gain * agreement + 0.15 * novelty - contradiction_gain * contradiction;
    }
};

