    const votes = [_]Wave50SemanticConsensus.Vote{
        .{ .sketch = s, .weight = 1, .source_id = 1 },
        .{ .sketch = s, .weight = 2, .source_id = 2 },
    };
    const r = Wave50SemanticConsensus.compute(&votes);
    try std.testing.expect(r.agreement > 0.99);
}

