test "timing surface is deterministic and bounded" {
    var a = Wave38Llm.TimingSurface.init(42);
    var b = Wave38Llm.TimingSurface.init(42);
    var last: u64 = 0;
    for (0..16) |_| {
        const da = a.nextDeadline(last);
        const db = b.nextDeadline(last);
        try std.testing.expectEqual(da, db);
        try std.testing.expect(da > last);
        last = da;
    }
}

