test "temporal ledger is deterministic and event ordered" {
    var a = Wave38Llm.TemporalLedger{};
    var b = Wave38Llm.TemporalLedger{};
    a.append(12, 100);
    a.append(13, 200);
    b.append(12, 100);
    b.append(13, 200);
    try std.testing.expectEqual(a.events, b.events);
    try std.testing.expect(ctEqual(&a.digest, &b.digest));
    b.append(14, 300);
    try std.testing.expect(!ctEqual(&a.digest, &b.digest));
}

