test "Q3_K fused dot matches dequantization across both sections" {
    var block: [Q3KExact.block_bytes]u8 = undefined;
    for (&block, 0..) |*v, i| v.* = @truncate(i * 37 + 11);
    block[Q3KExact.d_offset] = 0;
    block[Q3KExact.d_offset + 1] = 0x3c;
    var weights: [256]f32 = undefined;
    var input: [256]f32 = undefined;
    Q3KExact.dequantBlock(&weights, &block);
    var expected: f32 = 0;
    for (&input, weights, 0..) |*x, w, i| {
        x.* = @as(f32, @floatFromInt(@as(i32, @intCast(i % 13)) - 6)) / 7;
        expected += w * x.*;
    }
    try std.testing.expectApproxEqAbs(expected, try Q3KExact.dotRow(&block, &input), 0.01);
}

